function bindInteractionControlCanvasEvents() {
  if (state.activeId !== "interaction-control") return;
  const viewport = document.querySelector("[data-interaction-story-canvas-viewport]");
  if (viewport) bindSourceGraphCanvasPanning(viewport);
  document.querySelector("[data-interaction-show-problem]")?.addEventListener("click", (event) => {
    focusInteractionProblemBoundary(event.currentTarget.dataset.interactionShowProblem);
  });
  document.querySelector("[data-interaction-open-controller-mapping]")?.addEventListener("click", () => {
    openInteractionControllerMappingEditor();
  });
  for (const button of document.querySelectorAll("[data-interaction-option-thumbnail]")) {
    button.addEventListener("click", () => {
      const targetType = button.dataset.interactionTargetType;
      const targetId = button.dataset.interactionTargetId;
      const kind = button.dataset.interactionKind;
      if (
        !["boundary", "variant-edge"].includes(targetType)
        || !targetId
        || !["button-step", "ui-button-press", "direct", "embodied-control"].includes(kind)
      ) return;
      if (kind === "direct" && (
        (targetType === "boundary" && !interactionBoundaryDirectManipulationAvailable(targetId))
        || (targetType === "variant-edge" && !interactionVariantDirectManipulationAvailable(targetId))
      )) return;
      const historyStarted = beginAuthorHistory("Choose and edit Reader actions", "interaction-control");
      if (targetType === "boundary") setInteractionBoundaryPolicy(targetId, kind, { retainConfiguration: true });
      else setInteractionVariantPolicy(targetId, kind, { retainConfiguration: true });
      if (historyStarted) commitAuthorHistory();
      openInteractionOptionEditor({
        beatId: button.dataset.interactionBeatId,
        variantGroupId: button.dataset.interactionVariantGroupId || null,
        variantOptionId: button.dataset.interactionVariantOptionId || null,
        interactionTargetType: targetType,
        interactionTargetId: targetId,
        interactionKind: kind,
      });
    });
  }
  for (const select of document.querySelectorAll("[data-story-variant-interaction-policy-select]")) {
    select.addEventListener("change", () => {
      const edgeId = select.dataset.interactionVariantEdgeId;
      const policyKind = select.value;
      if (!edgeId || !["ui-button-press", "direct", "embodied-control"].includes(policyKind)) return;
      if (policyKind === "direct" && !interactionVariantDirectManipulationAvailable(edgeId)) {
        state.output = { error: "Add at least one object readers can move to this choice before assigning Direct manipulation." };
        renderPreservingScroll();
        return;
      }
      const historyStarted = beginAuthorHistory("Edit choice action", "interaction-control");
      setInteractionVariantPolicy(edgeId, policyKind);
      state.output = { interaction: `${variantInteractionPolicyLabel(policyKind)} assigned to the choice arrow.` };
      if (historyStarted) commitAuthorHistory();
      renderPreservingScroll();
      [...document.querySelectorAll("[data-story-variant-interaction-policy-select]")]
        .find((candidate) => candidate.dataset.interactionVariantEdgeId === edgeId)
        ?.focus();
    });
  }
  for (const select of document.querySelectorAll("[data-interaction-boundary-policy-select]")) {
    select.addEventListener("change", () => {
      const boundaryId = select.dataset.interactionBoundaryId;
      const policyKind = select.value;
      if (!boundaryId || !["button-step", "direct", "embodied-control"].includes(policyKind)) return;
      if (policyKind === "direct" && !interactionBoundaryDirectManipulationAvailable(boundaryId)) {
        state.output = { error: "Add at least one object readers can move to the source story part before assigning Direct manipulation." };
        renderPreservingScroll();
        return;
      }
      const historyStarted = beginAuthorHistory("Edit a Reader actions scene change", "interaction-control");
      setInteractionBoundaryPolicy(boundaryId, policyKind);
      state.interactionManipulationOffset = { x: 0, y: 0, z: 0 };
      state.interactionEmbodiedRestartToken += 1;
      state.output = { interaction: `${interactionControlKindLabel(policyKind)} assigned to ${boundaryId}.` };
      if (historyStarted) commitAuthorHistory();
      renderPreservingScroll();
      [...document.querySelectorAll("[data-interaction-boundary-policy-select]")]
        .find((candidate) => candidate.dataset.interactionBoundaryId === boundaryId)
        ?.focus();
    });
  }
  for (const button of document.querySelectorAll("[data-interaction-open-scene]")) {
    button.addEventListener("click", () => openInteractionSceneEditor({
      beatId: button.dataset.interactionBeatId,
      variantGroupId: button.dataset.interactionVariantGroupId || null,
      variantOptionId: button.dataset.interactionVariantOptionId || null,
    }));
  }
  document.querySelector("[data-interaction-close-editor]")?.addEventListener("click", () => closeInteractionSceneEditor());
  bindInteractionOptionEditorEvents();
}

function focusInteractionProblemBoundary(boundaryId) {
  const viewport = document.querySelector("[data-interaction-story-canvas-viewport]");
  const select = [...document.querySelectorAll("[data-interaction-boundary-policy-select]")]
    .find((candidate) => candidate.dataset.interactionBoundaryId === boundaryId);
  const target = select?.closest("[data-interaction-needs-assignment]");
  if (!viewport || !select || !target) return false;
  const viewportRect = viewport.getBoundingClientRect();
  const targetRect = target.getBoundingClientRect();
  const left = viewport.scrollLeft
    + (targetRect.left - viewportRect.left)
    - ((viewport.clientWidth - targetRect.width) / 2);
  const top = viewport.scrollTop
    + (targetRect.top - viewportRect.top)
    - ((viewport.clientHeight - targetRect.height) / 2);
  const behavior = window.matchMedia?.("(prefers-reduced-motion: reduce)")?.matches ? "auto" : "smooth";
  viewport.scrollTo({
    left: Math.max(0, left),
    top: Math.max(0, top),
    behavior,
  });
  select.focus({ preventScroll: true });
  return true;
}

function interactionEditorContextFromState() {
  return interactionOptionEditorContext(selectedInteractionControlBase(), activeInteractionSceneContext());
}

function commitInteractionEditorMutation(label, mutate, { rerender = true } = {}) {
  const editorContext = interactionEditorContextFromState();
  if (!editorContext?.kind) return false;
  const historyStarted = beginAuthorHistory(label, "interaction-control");
  const changed = mutateInteractionOptionConfiguration(editorContext, mutate);
  if (historyStarted && changed) commitAuthorHistory();
  if (changed) {
    state.output = {
      interaction: editorContext.targetType === "global-controller"
        ? "Controller mapping updated for every Controller button press scene change."
        : `${interactionControlKindLabel(editorContext.kind)} configuration updated for this scene change.`,
    };
    if (rerender) renderPreservingScroll();
  }
  return changed;
}

function setInteractionTransformComponent(transform, part, axisIndex, rawValue, rotationReference = null) {
  const axis = Number(axisIndex);
  const value = Number(rawValue);
  if (!Number.isInteger(axis) || axis < 0 || axis > 2 || !Number.isFinite(value)) return false;
  const normalized = normalizeSpatialTransform(transform);
  if (part === "position" || part === "scale") {
    normalized[part][axis] = value;
    Object.assign(transform, normalizeSpatialTransform(normalized));
    return true;
  }
  if (part === "rotation") {
    const values = interactionTransformEulerDegrees(normalized, rotationReference);
    values[axis] = value;
    normalized.quaternion = new THREE.Quaternion().setFromEuler(new THREE.Euler(
      ...values.map((component) => THREE.MathUtils.degToRad(component)),
      "XYZ",
    )).normalize().toArray();
    Object.assign(transform, normalized);
    return true;
  }
  return false;
}

function bindInteractionOptionEditorEvents() {
  const root = document.querySelector("[data-interaction-option-editor]");
  if (!root) return;
  if (root.dataset.interactionOptionEditor === "in-beat") {
    bindInteractionInBeatEditorEvents(root);
    return;
  }
  for (const button of root.querySelectorAll("[data-interaction-destination-transform-mode]")) {
    button.addEventListener("click", () => {
      state.interactionDestinationTransformMode = button.dataset.interactionDestinationTransformMode;
      interactionViewer?.transformControls?.setMode(state.interactionDestinationTransformMode);
      for (const candidate of root.querySelectorAll("[data-interaction-destination-transform-mode]")) {
        const selected = candidate === button;
        candidate.classList.toggle("selected", selected);
        candidate.setAttribute("aria-pressed", String(selected));
      }
    });
  }
  for (const select of root.querySelectorAll("[data-interaction-controller-binding]")) {
    select.addEventListener("change", () => {
      commitInteractionEditorMutation("Map controller input", (configuration) => {
        const binding = configuration.bindings.find((candidate) => (
          candidate.hand === select.dataset.interactionHand
          && candidate.input === select.dataset.interactionInput
        ));
        if (binding) binding.action = select.value;
      });
    });
  }

  root.querySelector("[data-interaction-ui-button-label]")?.addEventListener("change", (event) => {
    commitInteractionEditorMutation("Edit UI button text", (configuration) => {
      configuration.buttons[0].label = shortText(event.currentTarget.value, 80) || "Continue";
    });
  });
  root.querySelector("[data-interaction-ui-button-label]")?.addEventListener("input", (event) => {
    const preview = root.querySelector("[data-interaction-ui-button-preview]");
    if (preview) preview.textContent = shortText(event.currentTarget.value, 80) || "Continue";
  });
  for (const input of root.querySelectorAll("[data-interaction-ui-button-position], [data-interaction-ui-button-size]")) {
    input.addEventListener("change", () => {
      commitInteractionEditorMutation("Position UI button", (configuration) => {
        const property = input.hasAttribute("data-interaction-ui-button-position") ? "position" : "size";
        const index = Number(input.dataset.interactionUiButtonPosition ?? input.dataset.interactionUiButtonSize);
        configuration.buttons[0][property][index] = Number(input.value);
        const normalized = normalizeTextPanelActionPresentation(configuration.buttons[0], {
          fallbackLabel: "Continue",
        });
        configuration.buttons[0].position = normalized.position;
        configuration.buttons[0].size = normalized.size;
      });
    });
  }
  bindInteractionUiButtonDrag(root);

  for (const input of root.querySelectorAll("[data-interaction-transform-input]")) {
    input.addEventListener("change", () => {
      const prefix = input.dataset.interactionTransformInput;
      commitInteractionEditorMutation(
        prefix === "direct" ? "Edit manipulation destination" : "Edit locomotion destination",
        (configuration) => {
          const directTarget = prefix === "direct"
            ? configuration.targets.find((target) => interactionDirectTargetKey(target) === state.interactionSelectedDirectTargetKey)
            : null;
          const transform = directTarget?.destinationTransform || configuration.destination?.transform;
          if (transform) setInteractionTransformComponent(
            transform,
            input.dataset.interactionTransformPart,
            input.dataset.interactionTransformAxis,
            input.value,
            interactionRotationRangeReference(directTarget?.constraints?.rotation),
          );
          if (directTarget) directTarget.destinationAuthored = true;
        },
      );
    });
  }

  for (const input of root.querySelectorAll("[data-interaction-locomotion-tolerance]")) {
    input.addEventListener("change", () => {
      commitInteractionEditorMutation("Edit locomotion trigger tolerance", (configuration) => {
        configuration.tolerance[input.dataset.interactionLocomotionTolerance] = Number(input.value);
      });
    });
  }
  for (const checkbox of root.querySelectorAll("[data-interaction-direct-trigger-component]")) {
    checkbox.addEventListener("change", () => {
      if (!root.querySelector("[data-interaction-direct-trigger-component]:checked")) {
        checkbox.checked = true;
        state.output = { error: "Choose at least one transform component for the completion trigger." };
        renderPreservingScroll();
        return;
      }
      const component = checkbox.dataset.interactionDirectTriggerComponent;
      commitInteractionEditorMutation("Edit manipulation trigger components", (configuration) => {
        const target = configuration.targets.find((candidate) => (
          interactionDirectTargetKey(candidate) === state.interactionSelectedDirectTargetKey
        ));
        if (!target || !["position", "rotation", "scale"].includes(component)) return;
        const components = new Set(interactionDirectTriggerComponents(target));
        if (checkbox.checked) components.add(component);
        else components.delete(component);
        target.triggerComponents = ["position", "rotation", "scale"].filter((item) => components.has(item));
        if (!checkbox.checked) {
          const initial = normalizeSpatialTransform(target.initialTransform);
          if (component === "position") target.destinationTransform.position = cloneJson(initial.position);
          else if (component === "rotation") target.destinationTransform.quaternion = cloneJson(initial.quaternion);
          else if (component === "scale") target.destinationTransform.scale = cloneJson(initial.scale);
        }
        target.suggested = false;
        target.source = "author";
      });
    });
  }
  for (const input of root.querySelectorAll("[data-interaction-direct-tolerance]")) {
    input.addEventListener("change", () => {
      commitInteractionEditorMutation("Edit direct-manipulation tolerance", (configuration) => {
        configuration.tolerance[input.dataset.interactionDirectTolerance] = Number(input.value);
      });
    });
  }
  for (const checkbox of root.querySelectorAll("[data-interaction-direct-target]")) {
    checkbox.addEventListener("change", () => {
      const targetKey = checkbox.dataset.interactionDirectTarget;
      commitInteractionEditorMutation(checkbox.checked ? "Add manipulation target" : "Remove manipulation target", (configuration) => {
        configuration.targets = configuration.targets.filter((target) => interactionDirectTargetKey(target) !== targetKey);
        if (!checkbox.checked) return;
        const sceneTarget = interactionDirectSceneTargets(interactionEditorContextFromState()?.sceneContext)
          .find((target) => interactionDirectTargetKey(target) === targetKey);
        if (!sceneTarget) return;
        configuration.targets = configuration.targets.filter((target) => {
          if (target.entityId !== sceneTarget.entityId) return true;
          const existingPart = Boolean(target.nodePath || target.nodeIndex != null);
          const nextPart = Boolean(sceneTarget.nodePath || sceneTarget.nodeIndex != null);
          if (!existingPart || !nextPart) return false;
          if (target.nodePath && sceneTarget.nodePath) {
            return !target.nodePath.startsWith(`${sceneTarget.nodePath}/`)
              && !sceneTarget.nodePath.startsWith(`${target.nodePath}/`);
          }
          return interactionDirectTargetKey(target) !== targetKey;
        });
        configuration.targets.push({
          entityId: sceneTarget.entityId,
          assetId: sceneTarget.assetId,
          ...(sceneTarget.nodePath ? { nodePath: sceneTarget.nodePath } : {}),
          ...(sceneTarget.nodeIndex != null ? { nodeIndex: sceneTarget.nodeIndex } : {}),
          coordinateSpace: "local",
          oneHandGrabbable: sceneTarget.oneHandGrabbable,
          twoHandScalable: sceneTarget.twoHandScalable,
          ...(sceneTarget.elasticDragging ? { elasticDragging: true } : {}),
          triggerComponents: interactionDirectAvailableTriggerComponents(sceneTarget),
          initialTransform: cloneJson(sceneTarget.sourceTransform),
          constraints: cloneJson(sceneTarget.constraints || {}),
          destinationTransform: cloneJson(sceneTarget.sourceTransform),
          destinationAuthored: false,
          suggested: false,
          source: "author",
        });
        state.interactionSelectedDirectTargetKey = interactionDirectTargetKey(sceneTarget);
      });
    });
  }
  for (const button of root.querySelectorAll("[data-interaction-select-direct-target]")) {
    button.addEventListener("click", () => {
      state.interactionSelectedDirectTargetKey = button.dataset.interactionSelectDirectTarget;
      renderPreservingScroll();
    });
  }
  root.querySelector("[data-interaction-apply-transform-suggestions]")?.addEventListener("click", () => {
    const editorContext = interactionEditorContextFromState();
    const suggestions = interactionMappedTransformSuggestions(editorContext);
    commitInteractionEditorMutation("Use mapped scene-change placement", (configuration) => {
      const keys = new Set(suggestions.map((target) => interactionDirectTargetKey(target)));
      const entitiesWithPartSuggestions = new Set(suggestions.filter((target) => target.nodePath || target.nodeIndex != null).map((target) => target.entityId));
      const existingTargets = new Map(configuration.targets.map((target) => [interactionDirectTargetKey(target), target]));
      configuration.targets = [
        ...configuration.targets.filter((target) => (
          !keys.has(interactionDirectTargetKey(target))
          && !(entitiesWithPartSuggestions.has(target.entityId) && !target.nodePath && target.nodeIndex == null)
        )),
        ...suggestions.map((target) => {
          const existing = existingTargets.get(interactionDirectTargetKey(target));
          return {
            ...target,
            triggerComponents: existing
              ? interactionDirectTriggerComponents(existing)
              : interactionDirectTriggerComponents(target),
            destinationAuthored: true,
          };
        }),
      ];
      state.interactionSelectedDirectTargetKey = interactionDirectTargetKey(suggestions[0]) || state.interactionSelectedDirectTargetKey;
    });
  });
}

function commitInteractionInBeatMutation(label, mutate, { rerender = true } = {}) {
  const editorContext = interactionEditorContextFromState();
  if (editorContext?.targetType !== "in-beat") return false;
  const historyStarted = beginAuthorHistory(label, "interaction-control");
  const changed = mutateInteractionInBeatRecord(editorContext.sceneContext, mutate);
  if (historyStarted && changed) commitAuthorHistory();
  if (changed) {
    state.output = { interaction: "Interactive object updated. Return to the story canvas and finish the Reader actions step when ready." };
    if (rerender) renderPreservingScroll();
  }
  return changed;
}

function interactionInBeatTargetByKey(record, key) {
  return record?.targets?.find((target) => interactionInBeatTargetKey(target) === key) || null;
}

function bindInteractionInBeatEditorEvents(root) {
  for (const button of root.querySelectorAll("[data-interaction-constraint-transform-mode]")) {
    button.addEventListener("click", () => {
      state.interactionConstraintTransformMode = button.dataset.interactionConstraintTransformMode;
      interactionViewer?.transformControls?.setMode(state.interactionConstraintTransformMode);
      refreshInteractionConstraintRangeVisual(interactionViewer);
      for (const candidate of root.querySelectorAll("[data-interaction-constraint-transform-mode]")) {
        const selected = candidate === button;
        candidate.classList.toggle("selected", selected);
        candidate.setAttribute("aria-pressed", String(selected));
      }
    });
  }
  for (const button of root.querySelectorAll("[data-interaction-constraint-endpoint]")) {
    button.addEventListener("click", () => {
      const endpoint = button.dataset.interactionConstraintEndpoint === "max" ? "max" : "min";
      if (!activateInteractionConstraintEndpoint(interactionViewer, endpoint)) {
        state.interactionConstraintEndpoint = endpoint;
        renderPreservingScroll();
      }
    });
  }
  for (const input of root.querySelectorAll("[data-interaction-inbeat-capability]")) {
    input.addEventListener("change", () => {
      const key = input.dataset.interactionInbeatTargetKey;
      const capability = input.dataset.interactionInbeatCapability;
      const currentTarget = interactionInBeatTargetsForContext(interactionEditorContextFromState()?.sceneContext)
        .find((target) => interactionInBeatTargetKey(target) === key);
      const otherCapability = capability === "oneHandGrabbable" ? "twoHandScalable" : "oneHandGrabbable";
      if (!input.checked && currentTarget && !currentTarget[otherCapability]) {
        input.checked = true;
        state.output = { error: "An interactive object needs one-hand grab, two-hand resize, or both. Use Remove to delete it." };
        renderPreservingScroll();
        return;
      }
      commitInteractionInBeatMutation("Edit object action", (record) => {
        const target = interactionInBeatTargetByKey(record, key);
        if (!target || !["oneHandGrabbable", "twoHandScalable"].includes(capability)) return;
        target[capability] = input.checked;
        if (!target.oneHandGrabbable && target.constraints) {
          delete target.constraints.position;
          delete target.constraints.rotation;
        }
        if (!target.oneHandGrabbable) delete target.elasticDragging;
        if (!target.twoHandScalable && target.constraints) delete target.constraints.scale;
      });
    });
  }
  for (const input of root.querySelectorAll("[data-interaction-inbeat-elastic-dragging]")) {
    input.addEventListener("change", () => {
      const key = input.dataset.interactionInbeatTargetKey;
      commitInteractionInBeatMutation("Edit elastic dragging affordance", (record) => {
        const target = interactionInBeatTargetByKey(record, key);
        if (!target?.oneHandGrabbable) return;
        if (input.checked) target.elasticDragging = true;
        else delete target.elasticDragging;
      });
    });
  }
  for (const input of root.querySelectorAll("[data-interaction-inbeat-constraint-toggle]")) {
    input.addEventListener("change", () => {
      const key = input.dataset.interactionInbeatTargetKey;
      const channel = input.dataset.interactionInbeatConstraintToggle;
      commitInteractionInBeatMutation(input.checked ? "Add object movement range" : "Remove object movement range", (record) => {
        const target = interactionInBeatTargetByKey(record, key);
        if (!target || !["position", "rotation", "scale"].includes(channel)) return;
        target.constraints ||= {};
        if (!input.checked) {
          delete target.constraints[channel];
          return;
        }
        const initial = normalizeSpatialTransform(target.initialTransform);
        if (channel === "position") target.constraints.position = { min: cloneJson(initial.position), max: cloneJson(initial.position) };
        if (channel === "rotation") {
          const rotation = interactionTransformEulerDegrees(initial);
          target.constraints.rotation = { minDegrees: cloneJson(rotation), maxDegrees: cloneJson(rotation) };
        }
        if (channel === "scale") target.constraints.scale = { min: cloneJson(initial.scale), max: cloneJson(initial.scale) };
        state.interactionConstraintEndpoint = "max";
        state.interactionConstraintTransformMode = channel === "position" ? "translate" : channel === "rotation" ? "rotate" : "scale";
      });
    });
  }
  for (const input of root.querySelectorAll("[data-interaction-inbeat-range-input]")) {
    input.addEventListener("focus", () => {
      activateInteractionConstraintEndpoint(
        interactionViewer,
        input.dataset.interactionInbeatRangeEndpoint === "max" ? "max" : "min",
      );
    });
    input.addEventListener("change", () => {
      const key = input.dataset.interactionInbeatTargetKey;
      const channel = input.dataset.interactionInbeatRangeInput;
      const endpoint = input.dataset.interactionInbeatRangeEndpoint === "max" ? "max" : "min";
      const axis = Number(input.dataset.interactionInbeatRangeAxis);
      commitInteractionInBeatMutation("Edit object movement range", (record) => {
        const target = interactionInBeatTargetByKey(record, key);
        const range = target?.constraints?.[channel];
        if (!range || !Number.isInteger(axis) || axis < 0 || axis > 2) return;
        const property = channel === "rotation" ? `${endpoint}Degrees` : endpoint;
        const oppositeProperty = channel === "rotation"
          ? `${endpoint === "min" ? "max" : "min"}Degrees`
          : endpoint === "min" ? "max" : "min";
        const requested = Number(input.value);
        const opposite = Number(range[oppositeProperty][axis]);
        range[property][axis] = endpoint === "min"
          ? Math.min(requested, opposite)
          : Math.max(requested, opposite);
      });
    });
  }
  root.querySelector("[data-interaction-inbeat-remove-target]")?.addEventListener("click", (event) => {
    const key = event.currentTarget.dataset.interactionInbeatRemoveTarget;
    commitInteractionInBeatMutation("Remove interactive object", (record) => {
      record.targets = record.targets.filter((target) => interactionInBeatTargetKey(target) !== key);
      state.interactionSelectedInBeatTargetKey = interactionInBeatTargetKey(record.targets[0]) || null;
    });
  });
}

function bindInteractionUiButtonDrag(root) {
  const preview = root.querySelector("[data-interaction-ui-button-preview]");
  const panel = root.querySelector("[data-interaction-ui-panel-preview]");
  if (!preview || !panel) return;
  preview.addEventListener("pointerdown", (event) => {
    if (event.button !== 0) return;
    event.preventDefault();
    const editorContext = interactionEditorContextFromState();
    if (!editorContext?.configuration?.buttons?.[0]) return;
    const historyStarted = beginAuthorHistory("Move UI button", "interaction-control");
    preview.setPointerCapture(event.pointerId);
    const move = (moveEvent) => {
      const rect = panel.getBoundingClientRect();
      if (!rect.width || !rect.height) return;
      const button = editorContext.configuration.buttons[0];
      const normalized = normalizeTextPanelActionPresentation({
        ...button,
        position: [
          (moveEvent.clientX - rect.left) / rect.width,
          (moveEvent.clientY - rect.top) / rect.height,
        ],
      }, { fallbackLabel: "Continue" });
      button.position = normalized.position;
      button.size = normalized.size;
      preview.style.left = `${button.position[0] * 100}%`;
      preview.style.top = `${button.position[1] * 100}%`;
    };
    const finish = () => {
      if (activeStoryvrPointerGestureFinalizer === finish) activeStoryvrPointerGestureFinalizer = null;
      preview.removeEventListener("pointermove", move);
      preview.removeEventListener("pointerup", finish);
      preview.removeEventListener("pointercancel", finish);
      mutateInteractionOptionConfiguration(editorContext, (configuration) => {
        configuration.buttons[0].position = cloneJson(editorContext.configuration.buttons[0].position);
      });
      if (historyStarted) commitAuthorHistory();
      renderPreservingScroll();
    };
    activeStoryvrPointerGestureFinalizer = finish;
    preview.addEventListener("pointermove", move);
    preview.addEventListener("pointerup", finish);
    preview.addEventListener("pointercancel", finish);
  });
}

function bindEnvironmentApplyTargetEvents() {
  document.querySelector("[data-environment-apply-toggle]")?.addEventListener("click", () => {
    state.environmentUi.applyTargetsOpen = !state.environmentUi.applyTargetsOpen;
    state.environmentUi.applyError = false;
    state.environmentUi.applyStatus = "";
    renderPreservingScroll();
  });
  const selectAll = document.querySelector("[data-environment-apply-select-all]");
  selectAll?.addEventListener("change", () => {
    state.environmentUi.applyTargetBeatIds = selectAll.checked
      ? environmentApplyTargetBeats().map((beat) => beat.id)
      : [];
    syncEnvironmentApplyTargetControls();
  });
  for (const checkbox of document.querySelectorAll("[data-environment-apply-target]")) {
    checkbox.addEventListener("change", () => {
      const selected = new Set(state.environmentUi.applyTargetBeatIds || []);
      if (checkbox.checked) selected.add(checkbox.dataset.environmentApplyTarget);
      else selected.delete(checkbox.dataset.environmentApplyTarget);
      state.environmentUi.applyTargetBeatIds = environmentApplyTargetBeats()
        .map((beat) => beat.id)
        .filter((beatId) => selected.has(beatId));
      syncEnvironmentApplyTargetControls();
    });
  }
  document.querySelector("[data-environment-apply-submit]")?.addEventListener("click", () => {
    applyEnvironmentToSelectedBeats();
  });
  syncEnvironmentApplyTargetControls();
}

function syncEnvironmentApplyTargetControls() {
  const otherBeats = environmentApplyTargetBeats();
  const validIds = new Set(otherBeats.map((beat) => beat.id));
  const selectedIds = new Set((state.environmentUi.applyTargetBeatIds || []).filter((id) => validIds.has(id)));
  state.environmentUi.applyTargetBeatIds = otherBeats.map((beat) => beat.id).filter((id) => selectedIds.has(id));
  const selectAll = document.querySelector("[data-environment-apply-select-all]");
  if (selectAll) {
    selectAll.checked = Boolean(otherBeats.length) && selectedIds.size === otherBeats.length;
    selectAll.indeterminate = selectedIds.size > 0 && selectedIds.size < otherBeats.length;
  }
  for (const checkbox of document.querySelectorAll("[data-environment-apply-target]")) {
    const selected = selectedIds.has(checkbox.dataset.environmentApplyTarget);
    checkbox.checked = selected;
    checkbox.closest(".environment-apply-target-row")?.classList.toggle("selected", selected);
  }
  const count = document.querySelector("[data-environment-apply-count]");
  if (count) count.textContent = `${selectedIds.size} selected`;
  const submit = document.querySelector("[data-environment-apply-submit]");
  if (submit) {
    const manifest = environmentManifest();
    submit.disabled = state.environmentUi.operationBusy
      || state.environmentUi.generationBusy
      || selectedIds.size === 0
      || manifest.skipped
      || !manifest.asset;
    submit.textContent = state.environmentUi.operationBusy ? "Applying…" : "Apply to selected story parts";
  }
}

async function applyEnvironmentToSelectedBeats(options = {}) {
  const sceneContext = activeEnvironmentSceneContext();
  const validIds = new Set(environmentApplyTargetBeats(sceneContext).map((beat) => beat.id));
  const targetBeatIds = (state.environmentUi.applyTargetBeatIds || []).filter((beatId) => validIds.has(beatId));
  if (!sceneContext?.beatId || !targetBeatIds.length || state.environmentUi.operationBusy || state.environmentUi.generationBusy) return;
  if (!options.skipHistory) {
    return withAuthorHistory("Apply setting to selected story parts", () => (
      applyEnvironmentToSelectedBeats({ skipHistory: true })
    ), {
      persistent: true,
      componentId: "environment-enhancement",
    }).catch((error) => {
      state.environmentUi.applyError = true;
      state.environmentUi.applyStatus = `Apply failed: ${error.message}`;
      state.output = { error: error.message, diagnostics: error.diagnostics || [] };
      renderPreservingScroll();
    });
  }

  await flushEnvironmentDraft();
  state.environmentUi.operationBusy = true;
  state.environmentUi.applyError = false;
  state.environmentUi.applyStatus = `Applying this setting to ${targetBeatIds.length} selected story part${targetBeatIds.length === 1 ? "" : "s"}…`;
  updateEnvironmentActionAvailability();
  syncEnvironmentApplyTargetControls();
  try {
    const response = await api.post("/api/environment-enhancement/apply", {
      sourceBeatId: sceneContext.beatId,
      targetBeatIds,
      expectedRevision: Number(environmentRawState().revision) || 0,
    });
    applyEnvironmentEnhancementPayload(response, { resetDraft: true });
    markStoryvrCheckpointCompletionPending("environment-enhancement");
    state.environmentUi.applyTargetBeatIds = [];
    state.environmentUi.applyStatus = `Applied to ${targetBeatIds.length} story part${targetBeatIds.length === 1 ? "" : "s"} without generating new images.`;
    state.output = null;
  } catch (error) {
    state.environmentUi.applyError = true;
    state.environmentUi.applyStatus = `Apply failed: ${error.message}`;
    throw error;
  } finally {
    state.environmentUi.operationBusy = false;
    renderPreservingScroll();
  }
}

