async function persistSourceMotionLinks(options = {}) {
  const assignments = sourceMotionAssignmentPayload();
  const changedTracks = sourceMotionTracks().filter(sourceMotionTrackHasUnsavedChanges);
  const changedCount = changedTracks.length;
  if (!changedCount) return 0;
  await api.post("/api/source-motion-links", { assignments });
  for (const componentId of new Set(changedTracks.flatMap(sourceMotionTrackComponents))) {
    markStoryvrCheckpointCompletionPending(componentId);
  }
  if (!options.silent) {
    state.output = {
      sourceMotionLinksSaved: `Saved motion assignments for ${changedCount} source motion${changedCount === 1 ? "" : "s"}.`,
    };
  }
  await refresh();
  return changedCount;
}

async function saveStoryGraphCore(options = {}) {
  if (!state.graphDirty) return state.data.graph;
  state.data.graph = await api.post("/api/story-graph", JSON.parse(state.graphDraft));
  state.graphDirty = false;
  if (!options.silent) {
    state.output = {
      saved: state.data.paths.storyGraphPath,
      inferenceRefreshed: Boolean(state.data.graph.sourceGraphInference?.changed),
    };
  }
  await refresh(false, { savedGraph: true });
  return state.data.graph;
}

async function saveEnvironmentCheckpointCore() {
  await flushEnvironmentDraft();
  if (!environmentCheckpointAssignmentsReady()) {
    throw new Error("Choose a setting for every story part before finishing this step.");
  }
  const response = await api.post("/api/environment-enhancement/save");
  applyEnvironmentEnhancementPayload(response, { resetDraft: true });
  clearStoryvrCheckpointCompletionPending("environment-enhancement");
  await refresh(false);
  return response;
}

async function saveDecisionCheckpointCore(component) {
  if (!component) throw new Error("The current authoring step is unavailable.");
  const payload = {
    authorEdits: currentEditNotesValue(),
  };
  if (isSpatialRelationsComponentId(component.id)) await flushSpatialRelationsAutosave();
  if (component.id === ATTENTION_GUIDANCE_COMPONENT_ID) await flushAttentionGuidanceAutosave();
  if (component.id === "transition-pacing") {
    payload.finalTuningPrompt = currentEditNotesValue();
  } else if (component.id === "interaction-control") {
    const context = interactionBoundaryContext(selectedInteractionControlBase());
    if (!interactionBoundaryContextIsComplete(context)) {
      throw new Error("Choose a reader action for every highlighted scene change before finishing this step.");
    }
    payload.controllerConfiguration = ensureInteractionControllerConfiguration();
    payload.boundaryOverrides = interactionBoundaryOverridesPayload();
    payload.variantOverrides = interactionVariantOverridesPayload();
    payload.inBeatInteractionsSchemaVersion = IN_BEAT_INTERACTIONS_SCHEMA;
    payload.inBeatInteractions = interactionInBeatInteractionsPayload();
  } else {
    const selected = selectedOptionIdForComponent(component);
    if (!selected && component.id !== ATTENTION_GUIDANCE_COMPONENT_ID) {
      throw new Error(`Choose an option in ${participantComponentLabel(component.id, component.label)} before finishing this step.`);
    }
    if (selected) payload.optionId = selected;
    if (isSpatialRelationsComponentId(component.id)) payload.spatialRelations = spatialRelationsForSave(component);
    if (component.id === ATTENTION_GUIDANCE_COMPONENT_ID) payload.attentionGuidance = attentionGuidanceForSave();
  }
  state.data.decisions[component.id] = await api.post(`/api/decisions/${component.id}/save`, payload);
  if (component.id === "interaction-control") resetInteractionControlDraftCaches();
  clearStoryvrCheckpointCompletionPending(component.id);
  await refresh();
  return state.data.decisions[component.id];
}

async function writeRunCommandToClipboard(command) {
  let clipboardError = null;
  if (navigator.clipboard?.writeText) {
    try {
      await navigator.clipboard.writeText(command);
      return;
    } catch (error) {
      clipboardError = error;
    }
  }

  const textarea = document.createElement("textarea");
  textarea.value = command;
  textarea.setAttribute("readonly", "");
  textarea.style.position = "fixed";
  textarea.style.opacity = "0";
  textarea.style.pointerEvents = "none";
  document.body.append(textarea);
  textarea.select();
  const copied = document.execCommand?.("copy");
  textarea.remove();
  if (!copied) throw clipboardError || new Error("Clipboard access is unavailable.");
}

async function copyRunCommand(button) {
  const command = button.closest(".command-field")?.querySelector(".command-line")?.textContent || "";
  if (!command) return;
  const label = button.querySelector("[data-copy-run-command-label]");
  const defaultAriaLabel = button.dataset.defaultAriaLabel || button.getAttribute("aria-label") || "Copy command";
  button.dataset.defaultAriaLabel = defaultAriaLabel;
  window.clearTimeout(button.copyFeedbackTimer);
  button.classList.remove("copied", "copy-error");

  try {
    await writeRunCommandToClipboard(command);
    button.classList.add("copied");
    if (label) label.textContent = "Copied";
    button.setAttribute("aria-label", `${defaultAriaLabel}. Copied.`);
  } catch {
    button.classList.add("copy-error");
    if (label) label.textContent = "Failed";
    button.setAttribute("aria-label", `${defaultAriaLabel}. Copy failed.`);
  }

  button.focus({ preventScroll: true });
  button.copyFeedbackTimer = window.setTimeout(() => {
    button.classList.remove("copied", "copy-error");
    if (label) label.textContent = "Copy";
    button.setAttribute("aria-label", defaultAriaLabel);
  }, 3000);
}

function storyBuildHasLocalAuthoringChanges() {
  return Boolean(
    state.graphDirty
    || state.storyCanvasGroupingUi.flowDirty
    || pendingStoryvrCheckpointCompletions.size
    || checkpointComponents().some((component) => checkpointHasLocalDraft(component.id))
  );
}

function storyBuildCanStart() {
  return !storyBuildHasLocalAuthoringChanges()
    && checkpointComponents().every((component) => checkpointIsCurrent(component.id));
}

async function buildStoryInBackground() {
  if (state.storyBuildUi.busy) return;
  const canBuild = storyBuildCanStart();
  if (!canBuild) {
    state.storyBuildUi.phase = "error";
    state.storyBuildUi.error = true;
    state.storyBuildUi.status = "Finish every story step before building the WebXR story.";
    state.storyBuildUi.output = { error: state.storyBuildUi.status, diagnostics: [] };
    state.storyBuildUi.noticeVisible = true;
    updateStoryBuildDom();
    return;
  }

  const requestId = state.storyBuildUi.requestId + 1;
  state.storyBuildUi.requestId = requestId;
  state.storyBuildUi.busy = true;
  state.storyBuildUi.phase = "building";
  state.storyBuildUi.status = storyBuildRunningStatus();
  state.storyBuildUi.error = false;
  state.storyBuildUi.jobId = null;
  state.storyBuildUi.output = null;
  state.storyBuildUi.noticeVisible = true;
  state.storyBuildUi.startedAuthoringGeneration = state.storyBuildUi.authoringGeneration;
  updateStoryBuildDom();

  try {
    const job = await api.post("/api/story-build");
    if (requestId !== state.storyBuildUi.requestId) return;
    state.storyBuildUi.jobId = job.jobId;
    await waitForStoryBuildJob(job.jobId, requestId);
  } catch (error) {
    if (requestId !== state.storyBuildUi.requestId) return;
    finishStoryBuildWithError(error);
  }
}

async function waitForStoryBuildJob(jobId, requestId) {
  let consecutiveFailures = 0;
  while (requestId === state.storyBuildUi.requestId && state.storyBuildUi.busy) {
    let job;
    let recoveredStatusPolling = false;
    try {
      job = await api.get(`/api/story-build/${encodeURIComponent(jobId)}`);
      if (consecutiveFailures > 0) {
        recoveredStatusPolling = true;
        consecutiveFailures = 0;
      }
    } catch (error) {
      if (requestId !== state.storyBuildUi.requestId) return;
      consecutiveFailures += 1;
      if (consecutiveFailures >= STORY_BUILD_STATUS_MAX_CONSECUTIVE_FAILURES) {
        throw Object.assign(new Error(error?.message || "StoryVR could not check the background build status."), {
          diagnostics: error?.diagnostics || [],
          storyBuildStatusUnavailable: true,
        });
      }
      state.storyBuildUi.status = `The build is still presumed to be running. StoryVR will retry the status check (${consecutiveFailures}/${STORY_BUILD_STATUS_MAX_CONSECUTIVE_FAILURES}).`;
      updateStoryBuildActivityDom();
      await new Promise((resolve) => window.setTimeout(resolve, STORY_BUILD_STATUS_RETRY_MS));
      continue;
    }
    if (requestId !== state.storyBuildUi.requestId) return;
    if (job.status === "built" || job.status === "stale") {
      const localStale = state.storyBuildUi.authoringGeneration !== state.storyBuildUi.startedAuthoringGeneration
        || storyBuildHasLocalAuthoringChanges();
      const stale = job.status === "stale" || job.result?.stale === true || localStale;
      state.storyBuildUi.busy = false;
      state.storyBuildUi.phase = stale ? "stale" : "ready";
      state.storyBuildUi.status = stale
        ? storyBuildStaleStatus()
        : "The WebXR story is built and ready to run.";
      state.storyBuildUi.error = false;
      state.storyBuildUi.output = { ...(job.result || {}), stale };
      updateStoryBuildDom();
      return;
    }
    if (job.status === "failed") {
      finishStoryBuildWithError(Object.assign(
        new Error(job.error?.message || "StoryVR could not build the WebXR story."),
        { diagnostics: job.error?.diagnostics || [] },
      ));
      return;
    }
    if (recoveredStatusPolling) {
      state.storyBuildUi.status = storyBuildRunningStatus();
      updateStoryBuildActivityDom();
    }
    await new Promise((resolve) => window.setTimeout(resolve, STORY_BUILD_STATUS_POLL_MS));
  }
}

function finishStoryBuildWithError(error) {
  const statusUnavailable = error?.storyBuildStatusUnavailable === true;
  state.storyBuildUi.busy = false;
  state.storyBuildUi.phase = "error";
  state.storyBuildUi.status = statusUnavailable
    ? "StoryVR could not confirm the build status after several attempts. The server may still be building; select Build story to reconnect."
    : `Build failed: ${participantStageErrorMessage(error?.message || error)}`;
  state.storyBuildUi.error = true;
  state.storyBuildUi.output = {
    error: statusUnavailable
      ? "StoryVR lost contact with the background build before it could confirm the result."
      : error?.message || String(error),
    diagnostics: error?.diagnostics || [],
    statusUnavailable,
  };
  updateStoryBuildDom();
}

function updateStoryBuildDom() {
  updateStoryBuildActivityDom();
  const compileButton = document.querySelector('[data-action="compile"]');
  if (compileButton) {
    const canBuild = storyBuildCanStart();
    compileButton.disabled = state.busy || state.storyBuildUi.busy || !canBuild;
    compileButton.textContent = state.storyBuildUi.busy ? "Building story…" : "Build story";
    compileButton.setAttribute("aria-busy", state.storyBuildUi.busy ? "true" : "false");
  }
  const error = document.querySelector("[data-story-build-error]");
  if (error) error.innerHTML = storyBuildOutput()?.error
    ? renderStageErrorNotice("transition-pacing", storyBuildOutput())
    : "";
  const runHandoff = document.querySelector("[data-story-build-run-handoff]");
  if (runHandoff) runHandoff.innerHTML = renderReaderRunHandoff();
  const compilerHandoff = document.querySelector("[data-story-build-compiler-handoff]");
  if (compilerHandoff) compilerHandoff.innerHTML = renderCompilerHandoff();
  for (const button of document.querySelectorAll("[data-story-build-panel] [data-copy-run-command]")) {
    button.addEventListener("click", () => copyRunCommand(button));
  }
}

async function handleAction(action, options = {}) {
  const component = componentById(state.activeId);
  const historySpec = options.skipHistory ? null : historySpecForAction(action, component);
  if (historySpec) {
    let completed = false;
    try {
      await withAuthorHistory(historySpec.label, async () => {
        state.output = null;
        await handleAction(action, { skipHistory: true });
        if (state.output?.error) {
          const error = new Error(state.output.error);
          error.diagnostics = state.output.diagnostics || [];
          throw error;
        }
      }, {
        persistent: historySpec.persistent,
        componentId: component.id,
      });
      completed = true;
    } catch (error) {
      state.output = { error: error.message, diagnostics: error.diagnostics || [] };
      render();
    }
    if (completed && (action === "save-graph" || action === "save-checkpoint")) {
      await advanceAfterFinishingStoryvrStep(component.id);
    }
    return;
  }
  if (action === "compile") {
    await buildStoryInBackground();
    return;
  }
  await run(async () => {
    if (action === "save-source-motion-links") {
      await persistSourceMotionLinks();
      return;
    }
    if (action === "save-graph") {
      return saveStoryGraphCore();
    }
    if (action === "apply-animation-probe") {
      const wasDirty = state.graphDirty;
      state.data.graph = await api.post("/api/story-graph/apply-animation-probe", JSON.parse(state.graphDraft));
      state.graphDraft = JSON.stringify(state.data.graph, null, 2);
      const linking = state.data.graph.animationProbeLinking || {};
      if (linking.promotedLinkCount) markGraphDirty();
      else state.graphDirty = wasDirty;
      state.output = {
        animationProbeApplied: linking.promotedLinkCount
          ? `${linking.promotedLinkCount} movement links applied. Finish this step to keep them.`
          : "No matching animation probe links were found.",
      };
      return;
    }
    if (action === "regenerate-graph") {
      state.data.graph = await api.post("/api/story-graph/regenerate");
      state.graphDraft = JSON.stringify(state.data.graph, null, 2);
      state.graphDirty = false;
      state.selectedBeatId = null;
      state.selectedBeatIds = [];
      state.beatSelectionAnchorId = null;
      state.output = { regenerated: state.data.paths.storyGraphPath };
      return refresh(false, { savedGraph: true });
    }
    if (action === "start-codex-login") {
      state.loginOutput = [];
      state.loginState = await api.post("/api/codex/login/start");
      state.loginOutput = state.loginState.output || [];
      connectCodexLoginEvents();
      await refreshCodexStatus();
      state.output = { codexLogin: "started" };
      return;
    }
    if (action === "generate") {
      state.data.proposals[component.id] = await api.post(`/api/proposals/${component.id}`, {
        prompt: currentEditNotesValue(),
      });
      state.selectedOptionId = state.data.proposals[component.id].proposals[0]?.optionId || null;
      state.selectedOptionInspectorOpen = false;
      if (component.id === "asset-topology") {
        state.selectedTopologySwapIndex = 0;
        state.topologyViewerCameraState = null;
      }
      if (component.id === "dynamic-geometry") {
        state.selectedDynamicBeatIndex = 0;
        state.dynamicPreviewRestartToken += 1;
        state.dynamicViewerCameraState = null;
      }
      if (component.id === "inter-beat-dynamics") {
        state.selectedInterBeatTransitionIndex = 0;
        state.interBeatPreviewRestartToken += 1;
        state.interBeatViewerCameraState = null;
      }
      if (component.id === "environment-enhancement") {
        state.selectedContextBeatIndex = 0;
        state.contextViewerCameraState = null;
      }
      if (isSpatialRelationsComponentId(component.id)) {
        state.selectedTextBeatIndex = 0;
        state.textViewerCameraState = null;
        state.textPlacementDraft = null;
        resetSpatialRelationsDraftState();
      }
      return refresh();
    }
    if (action === "save-checkpoint") {
      return saveDecisionCheckpointCore(component);
    }
  });
}

function historySpecForAction(action, component) {
  const displayLabel = participantComponentLabel(component?.id, component?.label);
  const labelByAction = {
    "save-source-motion-links": `Save ${displayLabel} movement links`,
    "save-graph": "Finish Story order",
    "apply-animation-probe": "Apply animation probe links",
    "regenerate-graph": "Refresh Story order",
    generate: `Generate ${displayLabel} options`,
    "save-checkpoint": `Finish ${displayLabel}`,
  };
  const label = labelByAction[action];
  if (!label) return null;
  return {
    label,
    persistent: action !== "apply-animation-probe",
  };
}

async function refresh(clearOutput = false, options = {}) {
  const output = clearOutput ? null : state.output;
  const activeId = state.activeId;
  const selectedOptionId = state.selectedOptionId;
  const selectedBeatIds = state.selectedBeatIds;
  const beatSelectionAnchorId = state.beatSelectionAnchorId;
  const previousStoryCanvasGroupingGenerationSignature = storyCanvasGroupingGenerationSignature();
  state.data = await api.get("/api/state");
  reconcileStoryCanvasGroupingUiAfterRefresh(previousStoryCanvasGroupingGenerationSignature, options);
  syncEnvironmentUiFromState({ resetDraft: true });
  initializeSourceMotionLinkingDraft(true);
  state.graphDraft = JSON.stringify(state.data.graph, null, 2);
  state.graphDirty = false;
  state.activeId = normalizeActiveComponentId(activeId);
  state.selectedOptionId = selectedOptionId;
  state.selectedBeatIds = selectedBeatIds;
  state.beatSelectionAnchorId = beatSelectionAnchorId;
  clearMissingSelectedBeat();
  state.output = output;
}

async function refreshCodexStatus() {
  try {
    state.codexStatus = await api.get("/api/codex/status");
  } catch (error) {
    state.codexStatus = {
      authenticated: false,
      codexAvailable: false,
      authText: error.message,
      authMethod: "codex-cli-device-auth",
    };
  }
}

function connectCodexLoginEvents() {
  if (state.loginEvents) state.loginEvents.close();
  state.loginEvents = new EventSource("/api/codex/login/events");
  state.loginEvents.addEventListener("state", async (event) => {
    state.loginState = JSON.parse(event.data);
    if (!state.loginState.running && state.loginState.startedAt) {
      await refreshCodexStatus();
      state.storyCanvasGroupingUi.attemptedSignature = "";
      state.storyCanvasGroupingUi.error = "";
      state.loginEvents?.close();
      state.loginEvents = null;
    }
    render();
  });
  state.loginEvents.addEventListener("line", (event) => {
    const line = JSON.parse(event.data);
    state.loginOutput.push(line);
    if (line.loginUrl || line.loginCode) {
      state.loginState = {
        ...(state.loginState || {}),
        loginUrl: line.loginUrl || state.loginState?.loginUrl,
        loginCode: line.loginCode || state.loginState?.loginCode,
      };
    }
    render();
  });
}

async function run(task) {
  try {
    state.busy = true;
    updateAuthorBusyDom();
    await task();
  } catch (error) {
    state.output = {
      error: error.message,
      diagnostics: error.diagnostics || [],
    };
  } finally {
    state.busy = false;
    render();
    updateAuthorBusyDom();
  }
}

async function readResponse(response) {
  const text = await response.text();
  const data = text ? JSON.parse(text) : {};
  if (!response.ok) {
    const error = new Error(data.error || `HTTP ${response.status}`);
    error.statusCode = response.status;
    error.diagnostics = data.diagnostics || [];
    throw error;
  }
  return data;
}

function initializeTopologyViewer(active) {
  if (active?.id !== "asset-topology") return;
  const container = document.querySelector("[data-topology-viewer]");
  if (!container) return;

  const component = componentById("asset-topology");
  const proposal = selectedTopologyProposal(component, state.data.proposals[component.id], state.data.decisions[component.id]);
  if (!proposal) return;

  const kind = inferTopologyKind(proposal);
  const layers = cumulativePreviewLayersForComponent("asset-topology", { topologyKind: kind });
  const swapSequence = topologySwapSequence(proposal);
  const activeSwapIndex = swapSequence.applicable ? clampTopologySwapIndex(swapSequence.steps) : 0;
  const assetLinks = swapSequence.applicable ? swapSequence.steps : (proposal.assetLinks || []);
  const width = Math.max(container.clientWidth, 360);
  const height = Math.max(container.clientHeight, 460);
  const scene = new THREE.Scene();
  scene.background = new THREE.Color(0xf8f7ec);

  const camera = new THREE.PerspectiveCamera(42, width / height, 0.02, 1000);
  camera.position.set(4.2, 3.1, 5.2);

  const renderer = new THREE.WebGLRenderer({ antialias: true, alpha: true });
  renderer.setPixelRatio(Math.min(window.devicePixelRatio || 1, 2));
  renderer.setSize(width, height);
  renderer.outputColorSpace = THREE.SRGBColorSpace;
  renderer.domElement.tabIndex = 0;
  renderer.domElement.className = "topology-viewer-canvas";

  const status = document.createElement("div");
  status.className = "topology-viewer-status overlay";
  status.textContent = assetLinks.length ? `Loading ${assetLinks.length} linked assets...` : "No linked assets in this proposal.";
  container.replaceChildren(renderer.domElement, status);
  const metadataOverlay = addPreviewMetadataOverlay(container, previewMetadataEntries({
    componentId: "asset-topology",
    layers,
    activeLink: assetLinks[activeSwapIndex] || assetLinks[0],
    currentValue: topologyKindLabel(kind),
  }));

  const controls = new OrbitControls(camera, renderer.domElement);
  controls.enableDamping = true;
  controls.dampingFactor = 0.08;
  controls.target.set(0, 0.45, 0);
  configureSpatialEditorMouseControls(controls);

  scene.add(new THREE.HemisphereLight(0xffffff, 0x6f7f78, 2.4));
  const keyLight = new THREE.DirectionalLight(0xffffff, 3.2);
  keyLight.position.set(4, 7, 5);
  scene.add(keyLight);
  const rimLight = new THREE.DirectionalLight(0x9edfd5, 1.1);
  rimLight.position.set(-5, 3, -4);
  scene.add(rimLight);

  const root = new THREE.Group();
  scene.add(root);
  if (!swapSequence.applicable) addTopologyConnectionLines(root, kind, assetLinks);

  const viewer = {
    scene,
    camera,
    renderer,
    controls,
    root,
    animationId: null,
    resizeHandler: null,
    keyDownHandler: null,
    keyUpHandler: null,
    pointerDownHandler: null,
    disposed: false,
    focused: false,
    keys: new Set(),
    lastFrameAt: performance.now(),
    elapsed: 0,
    swapSequence,
    activeSwapIndex,
    swapGroups: [],
    swapDuplicates: [],
    swapInterval: DEFAULT_SOURCE_ORDER_CYCLE_SECONDS,
    swapElapsed: 0,
    swapPulse: 0,
    swapFlash: null,
    swapReady: false,
    duplicateCount: topologySwapDuplicateCount(proposal),
    topologyKind: kind,
    layers,
    suppressSceneLabels: true,
    metadataOverlay,
  };
  topologyViewer = viewer;
  const restoredCameraState = restoredPreviewCameraState(viewer, state.topologyViewerCameraState);

  container.addEventListener("pointerdown", () => {
    viewer.focused = true;
    container.classList.add("focused");
    renderer.domElement.focus();
  });
  renderer.domElement.addEventListener("blur", () => {
    viewer.focused = false;
    viewer.keys.clear();
    container.classList.remove("focused");
  });

  viewer.pointerDownHandler = (event) => {
    if (!container.contains(event.target)) {
      viewer.focused = false;
      viewer.keys.clear();
      container.classList.remove("focused");
    }
  };
  viewer.keyDownHandler = (event) => {
    const key = event.key.toLowerCase();
    if (!viewer.focused || !["w", "a", "s", "d"].includes(key)) return;
    event.preventDefault();
    viewer.keys.add(key);
  };
  viewer.keyUpHandler = (event) => {
    const key = event.key.toLowerCase();
    if (!["w", "a", "s", "d"].includes(key)) return;
    viewer.keys.delete(key);
  };
  viewer.resizeHandler = () => {
    if (viewer.disposed) return;
    const nextWidth = Math.max(container.clientWidth, 360);
    const nextHeight = Math.max(container.clientHeight, 460);
    camera.aspect = nextWidth / nextHeight;
    camera.updateProjectionMatrix();
    renderer.setSize(nextWidth, nextHeight);
  };
  document.addEventListener("pointerdown", viewer.pointerDownHandler);
  window.addEventListener("keydown", viewer.keyDownHandler);
  window.addEventListener("keyup", viewer.keyUpHandler);
  window.addEventListener("resize", viewer.resizeHandler);

  if (!assetLinks.length) {
    fitTopologyPreviewCamera(viewer, root);
  } else if (swapSequence.applicable) {
    addTopologySwapCue(viewer);
    let pending = assetLinks.length;
    let failed = 0;
    const finishAsset = (ok) => {
      pending -= 1;
      if (!ok) failed += 1;
      if (viewer.disposed) return;
      fitTopologyPreviewCamera(viewer, root);
      if (pending > 0) {
        status.textContent = `Loading ${pending} more source-order assets...`;
      } else {
        viewer.swapReady = true;
        setTopologyActiveSwapIndex(viewer, activeSwapIndex, { pulse: false });
        if (restoredCameraState) applyTopologyViewerCameraState(viewer, restoredCameraState);
        if (failed) {
          status.textContent = `Loaded swap preview with ${failed} asset issue${failed === 1 ? "" : "s"}.`;
        } else {
          status.remove();
        }
      }
    };
    assetLinks.forEach((step, index) => {
      loadTopologySwapAsset(viewer, step, index, finishAsset);
    });
  } else {
    let pending = assetLinks.length;
    let failed = 0;
    const finishAsset = (ok) => {
      pending -= 1;
      if (!ok) failed += 1;
      if (viewer.disposed) return;
      fitTopologyPreviewCamera(viewer, root);
      if (pending > 0) {
        status.textContent = `Loading ${pending} more assets...`;
      } else {
        if (restoredCameraState) applyTopologyViewerCameraState(viewer, restoredCameraState);
        if (failed) {
          status.textContent = `Loaded with ${failed} asset preview issue${failed === 1 ? "" : "s"}.`;
          return;
        }
        status.remove();
      }
    };
    assetLinks.forEach((assetLink, index) => {
      loadTopologyAsset(viewer, assetLink, index, kind, assetLinks.length, finishAsset);
    });
  }

  const animate = (time) => {
    if (viewer.disposed) return;
    const delta = Math.min((time - viewer.lastFrameAt) / 1000, 0.05);
    viewer.lastFrameAt = time;
    viewer.elapsed += delta;
    updateTopologyKeyboardMovement(viewer, delta);
    animateTopologySwapViewer(viewer, delta);
    controls.update();
    renderer.render(scene, camera);
    viewer.animationId = requestAnimationFrame(animate);
  };
  viewer.animationId = requestAnimationFrame(animate);
}

function addTopologyConnectionLines(root, kind, assetLinks) {
  if (!assetLinks.length) return;
  const points = assetLinks.map((_, index) => topologyAssetPosition3d(kind, index, assetLinks.length));
  const material = new THREE.LineBasicMaterial({ color: 0x007f73, transparent: true, opacity: 0.62 });
  const center = new THREE.Vector3(0, 0.06, 0);
  const segments = [];
  if (kind === "single") {
    for (const point of points) segments.push([center, new THREE.Vector3(point.x, 0.06, point.z)]);
  } else {
    for (let index = 0; index < points.length - 1; index += 1) {
      segments.push([
        new THREE.Vector3(points[index].x, 0.06, points[index].z),
        new THREE.Vector3(points[index + 1].x, 0.06, points[index + 1].z),
      ]);
    }
    if (kind === "constellation" && points.length > 2) {
      segments.push([
        new THREE.Vector3(points[points.length - 1].x, 0.06, points[points.length - 1].z),
        new THREE.Vector3(points[0].x, 0.06, points[0].z),
      ]);
    }
  }
  for (const segment of segments) {
    root.add(new THREE.Line(new THREE.BufferGeometry().setFromPoints(segment), material.clone()));
  }
}

function addTopologySwapCue(viewer) {
  const flash = new THREE.Mesh(
    new THREE.SphereGeometry(0.92, 48, 28),
    new THREE.MeshBasicMaterial({ color: 0xffe7a6, transparent: true, opacity: 0 }),
  );
  flash.position.set(0, 0.72, 0);
  viewer.root.add(flash);
  viewer.swapFlash = flash;
}

function loadTopologySwapAsset(viewer, step, index, finishAsset) {
  const asset = findAssetById(step.assetId);
  const spatialEntity = viewer?.layers?.enabled?.[SPATIAL_RELATIONS_COMPONENT_ID]
    ? lockedSpatialGlbEntityForViewer(viewer, step.assetId, step.entityId)
    : null;
  const finalReviewFraming = finalReviewSpatialFraming(viewer, spatialEntity, index, 1);
  const targetSize = finalReviewFraming?.targetSize
    ?? topologyAssetTargetSize("single", 1);
  const topologyWrapper = new THREE.Group();
  topologyWrapper.name = `StoryVR topology anchor · ${step.assetId}`;
  topologyWrapper.position.set(0, finalReviewFraming?.anchorY ?? 0.16, 0);
  const authorWrapper = new THREE.Group();
  authorWrapper.name = `StoryVR author transform · ${step.assetId}`;
  authorWrapper.userData.assetId = step.assetId;
  authorWrapper.userData.spatialEntityId = step.entityId || spatialEntity?.id || "";
  const group = new THREE.Group();
  group.visible = index === viewer.activeSwapIndex;
  group.position.set(0, 0, 0);
  if (viewer.componentId === "interaction-control" && viewer.kind === "direct") {
    group.userData.interactionDraggable = true;
    group.userData.directManipulationAsset = true;
    if (Array.isArray(viewer.draggableTargets)) viewer.draggableTargets.push(group);
  }
  topologyWrapper.add(authorWrapper);
  authorWrapper.add(group);
  viewer.root.add(topologyWrapper);
  applyLockedSpatialGlbTransform(viewer, step.assetId, authorWrapper, spatialEntity);

  const modelRoot = new THREE.Group();
  group.add(modelRoot);
  const entry = {
    topologyWrapper,
    authorWrapper,
    group,
    modelRoot,
    step,
    assetId: step.assetId,
    entityId: step.entityId || spatialEntity?.id || "",
    basePosition: group.position.clone(),
    duplicates: [],
    opacityMaterials: [],
  };
  viewer.swapGroups[index] = entry;

  const role = step.role || asset?.role || asset?.type || "active specimen";
  const placeholder = viewer.suppressSceneLabels
    ? null
    : makeTopologyPlaceholder(asset?.id || step.assetId, role, asset ? 0x8fbfb7 : 0xc98a8a);
  if (placeholder) modelRoot.add(placeholder);
  if (!viewer.suppressSceneLabels) {
    const label = makeTextSprite(step.label || role, {
      y: 1.42,
      color: "#10201c",
      background: "rgba(255,253,244,0.9)",
      width: 1.32,
    });
    group.add(label);
    entry.opacityMaterials.push(...preparePreviewOpacityTarget(label));
  }

  if (!asset) {
    finishAsset(false);
    return;
  }

  if (isModelAsset(asset)) {
    const url = assetLoadSrc(asset);
    if (!url) {
      finishAsset(false);
      return;
    }
    createGltfLoader().load(
      url,
      (gltf) => {
        if (viewer.disposed) {
          disposeObject(gltf.scene);
          return;
        }
        if (placeholder) {
          modelRoot.remove(placeholder);
          disposeObject(placeholder);
        }
        applySpatialLoaderTransformPolicy(gltf.scene, spatialEntity);
        if (spatialEntity?.preserveSourceGeometry !== true) {
          if (finalReviewFraming) {
            normalizeSpatialRuntimeObject(
              gltf.scene,
              finalReviewFraming.targetSize,
              finalReviewFraming.verticalAlignment,
            );
          } else {
            normalizeTopologyObject(gltf.scene, targetSize);
          }
        }
        entry.opacityMaterials.push(...preparePreviewOpacityTarget(gltf.scene));
        modelRoot.add(gltf.scene);
        entry.sourceScene = gltf.scene;
        if (viewer.componentId !== "interaction-control") attachSourceDynamicsPreviewAnimation(viewer, entry, gltf);
        attachProceduralDynamicsPreviewMotion(viewer, entry, gltf);
        attachFinalReviewSourcePlayback(viewer, entry, gltf);
        applySourceSpatialCueToTextViewer(viewer, entry, gltf);
        applySourceSpatialCuesToInteractionViewer(viewer, entry, gltf);
        if (viewer.componentId === "interaction-control") attachInteractionUpstreamPlayback(viewer, entry, gltf);
        addTopologySwapDuplicateModels(viewer, entry, gltf.scene);
        applyInterBeatSourcePartMaskToEntry(viewer, entry, viewer.playing ? "transition" : "destination");
        setPreviewEntryOpacity(entry, group.visible ? 1 : 0);
        finishAsset(true);
      },
      undefined,
      () => finishAsset(false),
    );
    return;
  }

  const imageSrc = assetPreviewSrc(asset);
  if (imageSrc) {
    new THREE.TextureLoader().load(
      imageSrc,
      (texture) => {
        if (viewer.disposed) {
          texture.dispose();
          return;
        }
        texture.colorSpace = THREE.SRGBColorSpace;
        if (placeholder) {
          modelRoot.remove(placeholder);
          disposeObject(placeholder);
        }
        const plane = makeTopologyImagePlane(texture, targetSize);
        entry.opacityMaterials.push(...preparePreviewOpacityTarget(plane));
        modelRoot.add(plane);
        entry.sourceScene = plane;
        setPreviewEntryOpacity(entry, group.visible ? 1 : 0);
        finishAsset(true);
      },
      undefined,
      () => finishAsset(false),
    );
    return;
  }

  finishAsset(false);
}

function addTopologySwapDuplicateModels(viewer, entry, sourceModel) {
  const count = viewer.duplicateCount || 0;
  if (count <= 0) return;
  for (let index = 0; index < count; index += 1) {
    const angle = (Math.PI * 2 * index) / count;
    const duplicateGroup = new THREE.Group();
    duplicateGroup.position.set(Math.cos(angle) * 1.05, 0.08 + (index % 2) * 0.06, Math.sin(angle) * 0.82);
    duplicateGroup.rotation.y = -angle + Math.PI;
    const clone = sourceModel.clone(true);
    clone.scale.multiplyScalar(0.3 + (index % 3) * 0.045);
    entry.opacityMaterials.push(...preparePreviewOpacityTarget(clone));
    duplicateGroup.add(clone);
    entry.group.add(duplicateGroup);
    const duplicate = { group: duplicateGroup, angle, radiusX: 1.05, radiusZ: 0.82, bobOffset: index * 0.72 };
    entry.duplicates.push(duplicate);
    viewer.swapDuplicates.push(duplicate);
  }
}

function preparePreviewOpacityTarget(object) {
  const materials = [];
  object?.traverse?.((node) => {
    if (!node.material) return;
    const materialList = Array.isArray(node.material) ? node.material : [node.material];
    const prepared = materialList.map((material) => {
      if (!material) return material;
      const originalUserData = material.userData || {};
      const nextMaterial = material;
      nextMaterial.userData = {
        ...nextMaterial.userData,
        storyvrPreviewOpacityMaterial: true,
        storyvrBaseOpacity: Number.isFinite(originalUserData.storyvrBaseOpacity)
          ? originalUserData.storyvrBaseOpacity
          : (Number.isFinite(material.opacity) ? material.opacity : 1),
        storyvrBaseTransparent: originalUserData.storyvrBaseTransparent ?? Boolean(material.transparent),
        storyvrBaseDepthWrite: originalUserData.storyvrBaseDepthWrite ?? material.depthWrite,
        storyvrPreviewOpacity: Number.isFinite(originalUserData.storyvrPreviewOpacity) ? originalUserData.storyvrPreviewOpacity : 1,
        storyvrSourceBindingOpacity: Number.isFinite(originalUserData.storyvrSourceBindingOpacity) ? originalUserData.storyvrSourceBindingOpacity : 1,
      };
      materials.push(nextMaterial);
      return nextMaterial;
    });
    node.material = Array.isArray(node.material) ? prepared : prepared[0];
  });
  return materials;
}

function updatePreviewMaterialOpacity(material) {
  if (!material) return;
  const baseOpacity = Number.isFinite(material.userData?.storyvrBaseOpacity) ? material.userData.storyvrBaseOpacity : 1;
  const baseTransparent = Boolean(material.userData?.storyvrBaseTransparent);
  const baseDepthWrite = material.userData?.storyvrBaseDepthWrite ?? true;
  const previewOpacity = clampSourcePlaybackProgress(material.userData?.storyvrPreviewOpacity, 1);
  const sourceOpacity = clampSourcePlaybackProgress(material.userData?.storyvrSourceBindingOpacity, 1);
  const nextOpacity = baseOpacity * previewOpacity * sourceOpacity;
  const nextTransparent = baseTransparent || baseOpacity < 0.999 || previewOpacity < 0.999 || sourceOpacity < 0.999;
  const nextDepthWrite = previewOpacity >= 0.999 && sourceOpacity >= 0.999 ? baseDepthWrite : false;
  const opacityChanged = Math.abs((Number(material.opacity) || 0) - nextOpacity) > 0.0005;
  const transparentChanged = material.transparent !== nextTransparent;
  const depthWriteChanged = material.depthWrite !== nextDepthWrite;
  if (!opacityChanged && !transparentChanged && !depthWriteChanged) return;
  material.opacity = nextOpacity;
  material.transparent = nextTransparent;
  material.depthWrite = nextDepthWrite;
  if (transparentChanged) material.needsUpdate = true;
}

function updateSourceRenderableVisibility(node) {
  if (!node) return;
  const baseVisible = node.userData?.storyvrSourcePartBaseVisible ?? true;
  const maskVisible = node.userData?.storyvrSourcePartMaskVisible ?? true;
  const bindingVisible = node.userData?.storyvrSourceBindingVisible ?? true;
  node.visible = Boolean(baseVisible && maskVisible && bindingVisible);
}

function setPreviewOpacityMaterials(materials, opacity) {
  const numericOpacity = Number(opacity);
  const clampedOpacity = Math.max(0, Math.min(1, Number.isFinite(numericOpacity) ? numericOpacity : 1));
  for (const material of materials || []) {
    if (!material) continue;
    material.userData = { ...(material.userData || {}), storyvrPreviewOpacity: clampedOpacity };
    updatePreviewMaterialOpacity(material);
  }
}

function setPreviewEntryOpacity(entry, opacity) {
  const visible = Number(opacity) > 0.001;
  if (entry?.group) entry.group.visible = visible;
  setPreviewOpacityMaterials(entry?.opacityMaterials, opacity);
}

function previewAnimationCycleSeconds(viewer) {
  const explicitCycle = Number(viewer?.previewCycleSeconds);
  if (Number.isFinite(explicitCycle) && explicitCycle > 0) return explicitCycle;
  if (viewer?.componentId === "inter-beat-dynamics") return INTER_BEAT_TRANSITION_CYCLE_SECONDS;
  const swapInterval = Number(viewer?.swapInterval);
  if (Number.isFinite(swapInterval) && swapInterval > 0) return swapInterval;
  return DEFAULT_SOURCE_ORDER_CYCLE_SECONDS;
}

function previewClockSeconds(viewer) {
  const sourceElapsed = Number(viewer?.sourceElapsed);
  if (Number.isFinite(sourceElapsed)) return sourceElapsed;
  if (viewer?.cumulativeContext || viewer?.singleAnchorContext) return 0;
  const elapsed = Number(viewer?.elapsed);
  return Number.isFinite(elapsed) ? elapsed : 0;
}

function previewCycleProgress(viewer) {
  const cycleSeconds = previewAnimationCycleSeconds(viewer);
  if (!Number.isFinite(cycleSeconds) || cycleSeconds <= 0) return 0;
  const elapsed = previewClockSeconds(viewer);
  if (viewer?.playOnce) return Math.max(0, Math.min(1, elapsed / cycleSeconds));
  return (((elapsed % cycleSeconds) + cycleSeconds) % cycleSeconds) / cycleSeconds;
}

function previewPlaybackDeltaSeconds(viewer, delta) {
  const numericDelta = Number(delta);
  if (!Number.isFinite(numericDelta) || numericDelta <= 0) return 0;
  if (viewer && "playing" in viewer && !viewer.playing) return 0;
  const speed = Number(viewer?.speed);
  return numericDelta * (Number.isFinite(speed) && speed > 0 ? speed : 1);
}

function resetPreviewCycle(viewer) {
  if (viewer) viewer.sourceElapsed = 0;
}

function setTopologyActiveSwapIndex(viewer, index, options = {}) {
  if (!viewer?.swapSequence?.applicable) return;
  const max = Math.max(viewer.swapSequence.steps.length - 1, 0);
  const nextIndex = Math.max(0, Math.min(max, index));
  viewer.activeSwapIndex = nextIndex;
  state.selectedTopologySwapIndex = nextIndex;
  updatePreviewMetadataEntry(viewer, "active-asset", previewAssetDisplayName(viewer.swapSequence.steps[nextIndex]));
  viewer.swapElapsed = 0;
  if (options.pulse !== false) viewer.swapPulse = 0.7;
  viewer.swapGroups.forEach((entry, groupIndex) => {
    setPreviewEntryOpacity(entry, groupIndex === nextIndex ? 1 : 0);
  });

  const activeLabel = document.querySelector("[data-topology-active-label]");
  if (activeLabel) activeLabel.textContent = topologySwapStatusText(viewer.swapSequence, nextIndex);
  for (const button of document.querySelectorAll("[data-topology-swap-index]")) {
    const selected = Number(button.dataset.topologySwapIndex) === nextIndex;
    button.classList.toggle("selected", selected);
    button.setAttribute("aria-pressed", selected ? "true" : "false");
  }
  for (const button of document.querySelectorAll("[data-topology-swap-step]")) {
    if (button.dataset.topologySwapStep === "prev") button.disabled = nextIndex <= 0;
    if (button.dataset.topologySwapStep === "next") button.disabled = nextIndex >= max;
  }
}

function animateTopologySwapViewer(viewer, delta) {
  if (!viewer?.swapSequence?.applicable) return;
  if (viewer.swapReady && state.topologySwapPlaying && viewer.swapSequence.steps.length > 1) {
    viewer.swapElapsed += delta;
    if (viewer.swapElapsed >= previewAnimationCycleSeconds(viewer)) {
      setTopologyActiveSwapIndex(viewer, (viewer.activeSwapIndex + 1) % viewer.swapSequence.steps.length);
    }
  }
  const time = viewer.elapsed;
  const active = viewer.swapGroups[viewer.activeSwapIndex];
  if (active?.modelRoot) {
    active.modelRoot.position.y = Math.sin(time * 1.7) * 0.055;
    active.modelRoot.rotation.y = time * 0.48;
  }
  for (const duplicate of active?.duplicates || []) {
    const angle = duplicate.angle + time * 0.42;
    duplicate.group.position.x = Math.cos(angle) * duplicate.radiusX;
    duplicate.group.position.z = Math.sin(angle) * duplicate.radiusZ;
    duplicate.group.position.y = 0.08 + Math.sin(time * 1.8 + duplicate.bobOffset) * 0.05;
    duplicate.group.rotation.y = -angle + Math.PI;
  }
  if (viewer.swapFlash) {
    viewer.swapPulse = Math.max(0, viewer.swapPulse - delta);
    const progress = viewer.swapPulse / 0.7;
    viewer.swapFlash.scale.setScalar(0.5 + progress * 1.8);
    viewer.swapFlash.material.opacity = progress * 0.32;
  }
}

function knownDynamicGeometryKind(kind) {
  const value = String(kind || "");
  return ["none", "motion", "flow", "zoom", "focus"].includes(value) ? value : null;
}

function viewerDynamicGeometryKind(viewer) {
  return knownDynamicGeometryKind(viewer?.geometryKind)
    || knownDynamicGeometryKind(viewer?.layers?.dynamicKind)
    || (viewer?.componentId === "dynamic-geometry" ? knownDynamicGeometryKind(viewer?.kind) : null);
}

function animateCumulativeSourceOrderModel(viewer, entry, time, phaseOffset = 0) {
  if (!entry?.modelRoot) return;
  const kind = viewerDynamicGeometryKind(viewer);
  const activeTime = time + phaseOffset;
  entry.modelRoot.position.set(0, 0, 0);
  entry.modelRoot.rotation.set(0, 0, 0);
  entry.modelRoot.scale.setScalar(1);
  const transitionPlaybackActive = updateSourceTransitionPlayback(viewer, entry);
  if (!transitionPlaybackActive && kind === "none") return;
  if (!transitionPlaybackActive && entry.mixer && !entry.sourcePartFrozen) {
    const sourceTime = viewer.componentId === "inter-beat-dynamics"
      ? previewCycleProgress(viewer) * Math.max(Number(entry.sourceMotionDuration) || 0, 0.001)
      : activeTime;
    entry.mixer.setTime(sourceTime);
  }
}

function animateCumulativeSourceOrderDuplicates(entry, time, phaseOffset = 0) {
  const activeTime = time + phaseOffset;
  for (const duplicate of entry?.duplicates || []) {
    const angle = duplicate.angle + activeTime * 0.42;
    duplicate.group.position.x = Math.cos(angle) * duplicate.radiusX;
    duplicate.group.position.z = Math.sin(angle) * duplicate.radiusZ;
    duplicate.group.position.y = 0.08 + Math.sin(activeTime * 1.8 + duplicate.bobOffset) * 0.05;
    duplicate.group.rotation.y = -angle + Math.PI;
  }
}

function contextCumulativeFadeProgress(viewer) {
  if (viewer?.componentId !== "environment-enhancement") return null;
  if (viewer.transitionKind !== "discrete-fade") return null;
  const progress = previewCycleProgress(viewer);
  return progress * progress * (3 - 2 * progress);
}

function advanceInterBeatSourcePlaybackClock(viewer, playbackDelta, cycleSeconds) {
  if (viewer?.componentId !== "inter-beat-dynamics" || !viewer.playOnce || !viewer.sourceMotionTransition || !viewer.swapReady) return false;
  const cycle = Number(cycleSeconds);
  if (!Number.isFinite(cycle) || cycle <= 0) return false;
  const delta = Number(playbackDelta);
  const current = Number(viewer.sourceElapsed);
  const elapsed = Number.isFinite(current) ? current : 0;
  viewer.sourceElapsed = Math.max(0, Math.min(cycle, elapsed + (Number.isFinite(delta) && delta > 0 ? delta : 0)));
  return true;
}

function updateContextCumulativeFadeTargets(viewer, progress) {
  const groups = viewer?.swapGroups || [];
  if (groups.length < 2) return null;
  const max = groups.length - 1;
  const fromIndex = Math.max(0, Math.min(max, viewer.activeSwapIndex || 0));
  const toIndex = fromIndex >= max ? 0 : fromIndex + 1;
  for (const [index, entry] of groups.entries()) {
    let opacity = 0;
    if (index === fromIndex && index === toIndex) opacity = 1;
    else if (index === fromIndex) opacity = 1 - progress;
    else if (index === toIndex) opacity = progress;
    setPreviewEntryOpacity(entry, opacity);
  }
  return toIndex;
}

function animateNarrativeSingleAnchorViewer(viewer, delta) {
  const context = viewer?.cumulativeContext || viewer?.singleAnchorContext;
  if (!context) return false;
  const playbackDelta = previewPlaybackDeltaSeconds(viewer, delta);
  advanceInterBeatSourcePlaybackClock(viewer, playbackDelta, previewAnimationCycleSeconds(viewer));
  const time = viewer.elapsed || 0;
  const active = viewer.swapGroups?.[viewer.activeSwapIndex];
  let fadeTargetIndex = null;
  const fadeProgress = contextCumulativeFadeProgress(viewer);
  if (fadeProgress != null) {
    fadeTargetIndex = updateContextCumulativeFadeTargets(viewer, fadeProgress);
  }
  if (active) {
    animateCumulativeSourceOrderModel(viewer, active, time);
    animateCumulativeSourceOrderDuplicates(active, time);
  }
  if (fadeTargetIndex != null && fadeTargetIndex !== viewer.activeSwapIndex) {
    const target = viewer.swapGroups?.[fadeTargetIndex];
    animateCumulativeSourceOrderModel(viewer, target, time, 0.35);
    animateCumulativeSourceOrderDuplicates(target, time, 0.35);
  }
  return false;
}

function updateTextComfortBeatStatus() {
  const component = componentById("text-comfort");
  if (!component) return;
  const proposal = selectedTopologyProposal(component, state.data.proposals[component.id], state.data.decisions[component.id]);
  const beats = textComfortPreviewBeats(proposal);
  const index = clampTextBeatIndex(beats);
  const beat = beats[index];
  const kind = inferTextComfortKind(proposal);
  const draft = ensureTextPlacementDraft(proposal, beat);
  const placement = effectiveTextPlacementForBeat(draft, beat, kind);
  const hasOverride = Boolean(beat?.id && draft.overridesByBeat?.[beat.id]);
  const metaText = beats.length
    ? `${index + 1} of ${beats.length} · ${hasOverride ? "custom placement" : "global placement"}`
    : "0 story parts";

  const title = document.querySelector("[data-text-beat-title]");
  if (title) title.textContent = beat?.title || "No readable story part selected";
  const meta = document.querySelector("[data-text-beat-meta]");
  if (meta) meta.textContent = metaText;
  const copy = document.querySelector("[data-text-beat-copy]");
  if (copy) copy.textContent = shortText(beat?.text || "No story text is available for this story part.", 240);
  for (const button of document.querySelectorAll("[data-text-step]")) {
    if (button.dataset.textStep === "prev") button.disabled = index <= 0;
    if (button.dataset.textStep === "next") button.disabled = index >= beats.length - 1;
  }
  updateTextComfortSceneBeat(textViewer, beat, kind, placement);
}

function updateTextComfortSceneBeat(viewer, beat, kind, placement) {
  if (!viewer || viewer.disposed) return;
  const sequence = viewer.cumulativeContext?.sequence;
  const activeStep = sequence?.steps?.[viewer.activeSwapIndex] || null;
  const activeAssetId = activeStep?.assetId
    || beat?.linkedAssetIds?.find((assetId) => viewer.assetPositions?.has(assetId))
    || beat?.linkedAssetIds?.[0]
    || null;
  const activeModelPosition = viewer.cumulativeContext
    ? new THREE.Vector3(0, 0, 0)
    : activeAssetId && viewer.assetPositions?.has(activeAssetId)
    ? viewer.assetPositions.get(activeAssetId).clone()
    : new THREE.Vector3(0, 0, 0);
  const activeAnchorPosition = viewer.cumulativeContext
    ? new THREE.Vector3(0, 0.56, 0)
    : activeAssetId && viewer.assetPositions?.has(activeAssetId)
    ? activeModelPosition.clone().add(new THREE.Vector3(0, 0.56, 0))
    : new THREE.Vector3(0, 0.9, 0);
  const nextPlacement = placement || effectiveTextPlacementForBeat(ensureTextPlacementDraft(viewer.proposal, beat), beat, kind);
  const panelPosition = textPlacementWorldPosition(nextPlacement, activeAnchorPosition);

  if (viewer.panel) {
    viewer.panel.removeFromParent();
    disposeObject(viewer.panel);
  }
  if (viewer.anchorMarker) {
    viewer.anchorMarker.removeFromParent();
    disposeObject(viewer.anchorMarker);
  }
  if (viewer.calloutLine) {
    viewer.calloutLine.removeFromParent();
    disposeObject(viewer.calloutLine);
  }
  if (viewer.descriptionCues?.root) {
    viewer.descriptionCues.root.removeFromParent();
    disposeObject(viewer.descriptionCues.root);
  }

  const panel = makeTextComfortPanel(beat, nextPlacement, kind);
  panel.position.copy(panelPosition);
  panel.rotation.set(nextPlacement.rotation.x, nextPlacement.rotation.y, nextPlacement.rotation.z);
  viewer.root.add(panel);
  const anchorMarker = makeTextAnchorMarker(activeAnchorPosition, activeAssetId ? "Active text anchor" : "Reader text zone");
  viewer.root.add(anchorMarker);
  const calloutLine = makeTextPanelCallout(activeAnchorPosition, panel.position);
  viewer.root.add(calloutLine);
  const descriptionCues = null;

  viewer.beat = beat;
  viewer.kind = kind;
  viewer.placement = nextPlacement;
  viewer.activeAssetId = activeAssetId;
  viewer.activeModelPosition = activeModelPosition;
  viewer.activeAnchorPosition = activeAnchorPosition;
  viewer.panel = panel;
  viewer.anchorMarker = anchorMarker;
  viewer.calloutLine = calloutLine;
  viewer.descriptionCues = descriptionCues;
  updatePreviewMetadataEntry(viewer, "beat", shortText(beat?.title || "", 52));
  const activeLink = viewer.cumulativeContext?.sequence?.steps?.[viewer.activeSwapIndex]
    || viewer.assetLinks?.find((assetLink) => assetLink.assetId === activeAssetId);
  updatePreviewMetadataEntry(viewer, "active-asset", previewAssetDisplayName(activeLink));
}

function updateInteractionControlBeatStatus() {
  const component = componentById("interaction-control");
  if (!component) return;
  const baseProposal = selectedInteractionControlBase();
  const context = interactionBoundaryContext(baseProposal);
  const proposal = interactionProposalForBoundary(baseProposal, context.boundary);
  const { beats, beatIndex: index, beat } = context;
  const kind = context.boundary?.effectivePolicy ? inferInteractionControlKind({ label: context.boundary.effectivePolicy }) : null;
  const metaText = beats.length
    ? `${index + 1} of ${beats.length} · ${context.boundary ? context.boundary.effectivePolicy || "unassigned mapped scene change" : "story entry"}`
    : "0 story parts";

  const title = document.querySelector("[data-interaction-beat-title]");
  if (title) title.textContent = beat?.title || "No story part selected";
  const meta = document.querySelector("[data-interaction-beat-meta]");
  if (meta) meta.textContent = metaText;
  const copy = document.querySelector("[data-interaction-beat-copy]");
  if (copy) copy.textContent = shortText(beat?.text || "No story text available for this story part.", 240);

  if (interactionViewer) interactionViewer.proposal = proposal || interactionViewer.proposal;
  updateInteractionControlBeatLabel(interactionViewer, beat);
  updateInteractionControlCumulativeScene(interactionViewer, beat, kind);
}

function updateFinalReviewBeatStatus() {
  const beats = finalReviewBeats();
  const index = clampFinalReviewBeatIndex(beats);
  const sceneContext = finalReviewSelectedSceneContext(beats, index);
  const beat = finalReviewBeatForSceneContext(sceneContext) || beats[index];
  const region = microhabitatForBeat(beat);
  const cumulativeContext = finalReviewCumulativeContextForBeat(beats, index, sceneContext, beat);
  const activeStep = cumulativeContext?.active || null;
  const activeAsset = activeStep?.assetId ? findAssetById(activeStep.assetId) : beat?.linkedAssetIds?.map(findAssetById).find(Boolean);
  const sceneAssetLabel = finalReviewSceneAssetLabel(beat, sceneContext, activeAsset);
  const metaText = beats.length
    ? `${index + 1} of ${beats.length} · ${spatialSceneContextLabel(sceneContext)} · ${sceneAssetLabel}`
    : "0 story parts";

  const title = document.querySelector("[data-final-review-beat-title]");
  if (title) title.textContent = beat?.title || "No story part selected";
  const meta = document.querySelector("[data-final-review-beat-meta]");
  if (meta) meta.textContent = metaText;
  const copy = document.querySelector("[data-final-review-beat-copy]");
  if (copy) copy.textContent = shortText(beat?.text || "No story text available.", 260);
  const regionLabel = document.querySelector("[data-final-review-region-label]");
  if (regionLabel) regionLabel.textContent = region.label;

  for (const button of document.querySelectorAll("[data-final-review-beat-index]")) {
    const selected = button.dataset.finalReviewSceneKey === spatialSceneRequestKey(sceneContext);
    button.classList.toggle("selected", selected);
    button.setAttribute("aria-pressed", selected ? "true" : "false");
    if (selected) button.setAttribute("aria-current", "step");
    else button.removeAttribute("aria-current");
  }
  if (finalReviewViewer) finalReviewViewer.sceneContext = sceneContext;
  updateFinalReviewSceneBeat(finalReviewViewer, beat, region, activeStep?.assetId || activeAsset?.id || null);
}

function updateContextLayeringBeatStatus() {
  const component = componentById("environment-enhancement");
  if (!component) return;
  const proposal = selectedTopologyProposal(component, state.data.proposals[component.id], state.data.decisions[component.id]);
  const beats = contextPreviewBeats(proposal);
  const index = clampContextBeatIndex(beats);
  const beat = beats[index];
  const cumulativeContext = cumulativeSingleAnchorContext(beats, index);
  const linkedCount = beat?.linkedAssetIds?.length || 0;
  const linkedLabel = `${linkedCount} linked asset${linkedCount === 1 ? "" : "s"}`;

  const title = document.querySelector("[data-context-beat-title]");
  if (title) title.textContent = beat?.title || "No linked story part selected";
  const meta = document.querySelector("[data-context-beat-meta]");
  if (meta) {
    meta.textContent = beats.length
      ? `${index + 1} of ${beats.length} · ${linkedLabel}`
      : "0 story parts";
  }
  const copy = document.querySelector("[data-context-beat-copy]");
  if (copy) copy.textContent = shortText(beat?.text || "Link source assets in Story order to preview this setting.", 220);
  for (const button of document.querySelectorAll("[data-context-step]")) {
    if (button.dataset.contextStep === "prev") button.disabled = index <= 0;
    if (button.dataset.contextStep === "next") button.disabled = index >= beats.length - 1;
  }

  updatePreviewMetadataEntry(contextViewer, "beat", shortText(beat?.title || "", 52));
  const activeLink = cumulativeContext?.active
    || contextViewer?.assetLinks?.find((assetLink) => (beat?.linkedAssetIds || []).includes(assetLink.assetId));
  updatePreviewMetadataEntry(contextViewer, "active-asset", previewAssetDisplayName(activeLink));

  const nextLabel = beat?.title ? shortText(beat.title, 34) : "";
  const stage = contextViewer?.contextStage;
  if (!stage || stage.beatLabelText === nextLabel) return;
  if (stage.beatLabel) {
    contextViewer.root.remove(stage.beatLabel);
    disposeObject(stage.beatLabel);
    stage.beatLabel = null;
  }
  stage.beatLabelText = nextLabel;
  if (nextLabel) {
    stage.beatLabel = makeTextSprite(nextLabel, {
      y: 2.15,
      color: "#10201c",
      background: "rgba(255,253,244,0.9)",
      width: 1.75,
    });
    contextViewer.root.add(stage.beatLabel);
  }
}

function loadTopologyAsset(viewer, assetLink, index, kind, total, finishAsset) {
  const asset = findAssetById(assetLink.assetId);
  const targetSize = topologyAssetTargetSize(kind, total);
  const wrapper = new THREE.Group();
  wrapper.position.copy(topologyAssetPosition3d(kind, index, total));
  viewer.root.add(wrapper);

  const role = assetLink.role || asset?.role || asset?.type || "source asset";
  const placeholder = viewer.suppressSceneLabels
    ? null
    : makeTopologyPlaceholder(asset?.id || assetLink.assetId, role, asset ? 0x8fbfb7 : 0xc98a8a);
  if (placeholder) wrapper.add(placeholder);
  if (!viewer.suppressSceneLabels) {
    const label = makeTextSprite(role, {
      y: 1.05,
      color: "#10201c",
      background: "rgba(255,253,244,0.86)",
    });
    wrapper.add(label);
  }

  if (!asset) {
    finishAsset(false);
    return;
  }

  if (isModelAsset(asset)) {
    const url = assetLoadSrc(asset);
    if (!url) {
      finishAsset(false);
      return;
    }
    createGltfLoader().load(
      url,
      (gltf) => {
        if (viewer.disposed) {
          disposeObject(gltf.scene);
          return;
        }
        if (placeholder) {
          wrapper.remove(placeholder);
          disposeObject(placeholder);
        }
        normalizeTopologyObject(gltf.scene, targetSize);
        wrapper.add(gltf.scene);
        finishAsset(true);
      },
      undefined,
      () => finishAsset(false),
    );
    return;
  }

  const imageSrc = assetPreviewSrc(asset);
  if (imageSrc) {
    new THREE.TextureLoader().load(
      imageSrc,
      (texture) => {
        if (viewer.disposed) {
          texture.dispose();
          return;
        }
        texture.colorSpace = THREE.SRGBColorSpace;
        if (placeholder) {
          wrapper.remove(placeholder);
          disposeObject(placeholder);
        }
        wrapper.add(makeTopologyImagePlane(texture, targetSize));
        finishAsset(true);
      },
      undefined,
      () => finishAsset(false),
    );
    return;
  }

  finishAsset(true);
}

function makeTopologyImagePlane(texture, targetSize) {
  const image = texture.image || {};
  const aspect = image.width && image.height ? image.width / image.height : 1.25;
  const width = targetSize * Math.min(Math.max(aspect, 0.75), 1.8);
  const height = width / aspect;
  const mesh = new THREE.Mesh(
    new THREE.PlaneGeometry(width, height),
    new THREE.MeshBasicMaterial({ map: texture, side: THREE.DoubleSide }),
  );
  mesh.position.y = Math.max(height / 2, 0.34);
  return mesh;
}

function makeTopologyPlaceholder(title, subtitle, color) {
  const mesh = new THREE.Mesh(
    new THREE.PlaneGeometry(1.05, 0.72),
    new THREE.MeshBasicMaterial({ transparent: true, opacity: 0, side: THREE.DoubleSide }),
  );
  mesh.position.y = 0.52;
  mesh.visible = false;
  mesh.userData.storyvrArtificialSpatialTextPanel = true;
  mesh.raycast = () => {};
  return mesh;
}

function makeTextSprite(text, options = {}) {
  // Spatial authoring surfaces keep system-generated labels in their DOM
  // inspectors. Only text declared by the source scene itself is rendered
  // inside the Three.js scene.
  const authoredSceneText = options.authoredSceneText === true;
  const texture = authoredSceneText
    ? makeTextCanvasTexture(String(text || "").trim(), "", 0xffffff, options)
    : null;
  const material = new THREE.SpriteMaterial({
    map: texture,
    transparent: true,
    fog: false,
    depthTest: options.depthTest !== false,
    depthWrite: options.depthWrite !== false,
    toneMapped: options.toneMapped !== false,
    alphaTest: authoredSceneText ? 0.01 : 0,
  });
  const sprite = new THREE.Sprite(material);
  sprite.visible = authoredSceneText;
  sprite.renderOrder = authoredSceneText ? Number(options.renderOrder) || 9000 : 0;
  sprite.userData.storyvrArtificialSpatialTextPanel = !authoredSceneText;
  if (!authoredSceneText) sprite.raycast = () => {};
  sprite.scale.set(options.width || 1.15, options.height || 0.28, 1);
  sprite.position.x = options.x ?? 0;
  sprite.position.y = options.y || 0.9;
  sprite.position.z = options.z ?? 0;
  return sprite;
}

function makeTextCanvasTexture(title, subtitle = "", color = 0xffffff, options = {}) {
  const canvas = document.createElement("canvas");
  canvas.height = 192;
  const requestedAspect = Math.max(
    1.5,
    Math.min(14, (Number(options.width) || 1.15) / Math.max(Number(options.height) || 0.28, 0.01)),
  );
  canvas.width = Math.max(288, Math.min(2048, Math.round(canvas.height * requestedAspect)));
  const ctx = canvas.getContext("2d");
  const background = options.background ?? `#${new THREE.Color(color).getHexString()}`;
  const transparentBackground = !background
    || String(background).trim().toLowerCase() === "transparent"
    || /rgba\([^)]*,\s*0(?:\.0+)?\s*\)$/i.test(String(background).trim());
  const lines = (Array.isArray(options.lines) ? options.lines : [title])
    .map((line) => String(line || "").trim())
    .filter(Boolean);
  if (!lines.length) lines.push("");
  ctx.clearRect(0, 0, canvas.width, canvas.height);
  if (!transparentBackground) {
    drawRoundRect(ctx, 2, 2, canvas.width - 4, canvas.height - 4, 22, background);
  }
  ctx.fillStyle = options.color || "#10201c";
  const fontWeight = Math.max(100, Math.min(900, Number(options.fontWeight) || 800));
  const lineHeight = Math.min(150, Math.max(38, Math.floor((canvas.height - 24) / Math.max(lines.length, 1))));
  const fontSize = Math.min(108, Math.max(30, Math.floor(lineHeight * 0.65)));
  ctx.font = `${fontWeight} ${fontSize}px Avenir Next, Gill Sans, sans-serif`;
  ctx.textAlign = "center";
  ctx.textBaseline = "middle";
  const firstLineY = (canvas.height - (lines.length - 1) * lineHeight) / 2;
  lines.forEach((line, index) => {
    ctx.fillText(line, canvas.width / 2, firstLineY + index * lineHeight, canvas.width - 24);
  });
  if (subtitle) {
    ctx.fillStyle = "#5f716c";
    ctx.font = "700 24px Avenir Next, Gill Sans, sans-serif";
    ctx.fillText(subtitle, canvas.width / 2, 122, canvas.width - 78);
  }
  const texture = new THREE.CanvasTexture(canvas);
  texture.colorSpace = THREE.SRGBColorSpace;
  return texture;
}

function drawRoundRect(ctx, x, y, width, height, radius, fillStyle) {
  ctx.beginPath();
  ctx.moveTo(x + radius, y);
  ctx.lineTo(x + width - radius, y);
  ctx.quadraticCurveTo(x + width, y, x + width, y + radius);
  ctx.lineTo(x + width, y + height - radius);
  ctx.quadraticCurveTo(x + width, y + height, x + width - radius, y + height);
  ctx.lineTo(x + radius, y + height);
  ctx.quadraticCurveTo(x, y + height, x, y + height - radius);
  ctx.lineTo(x, y + radius);
  ctx.quadraticCurveTo(x, y, x + radius, y);
  ctx.closePath();
  ctx.fillStyle = fillStyle;
  ctx.fill();
}

function normalizeTopologyObject(object, targetSize) {
  const box = new THREE.Box3().setFromObject(object);
  if (box.isEmpty()) return;
  const center = box.getCenter(new THREE.Vector3());
  const size = box.getSize(new THREE.Vector3());
  const maxSize = Math.max(size.x, size.y, size.z) || 1;
  const scale = targetSize / maxSize;
  object.scale.multiplyScalar(scale);
  object.position.x -= center.x * scale;
  object.position.z -= center.z * scale;
  object.position.y -= box.min.y * scale;
}

function finalReviewSpatialFraming(viewer, spatialEntity, index = 0, total = 1) {
  if (viewer?.componentId !== "transition-pacing" || !spatialEntity) return null;
  return {
    anchorY: 0,
    targetSize: spatialTopologyAssetPose(viewer, index, Math.max(Number(total) || 1, 1)).targetSize,
    verticalAlignment: spatialEntityVerticalAlignment(spatialEntity),
  };
}

function topologyAssetTargetSize(kind, total) {
  if (kind === "map") return total > 5 ? 0.46 : 0.58;
  if (kind === "single") return total > 5 ? 0.62 : 0.74;
  return total > 5 ? 0.54 : 0.68;
}

function topologyAssetPosition3d(kind, index, total) {
  if (kind === "map") {
    const positions = [
      [-1.65, -0.95],
      [-0.55, -1.32],
      [0.75, -1.04],
      [1.65, -0.12],
      [0.9, 1.02],
      [-0.28, 1.22],
      [-1.38, 0.62],
      [0.12, 0.08],
    ];
    const [x, z] = positions[index % positions.length];
    return new THREE.Vector3(x, 0, z);
  }
  const count = Math.max(total, 1);
  const radius = kind === "single" ? 1.05 : 2.05;
  const angle = kind === "constellation"
    ? (-Math.PI * 0.8) + ((Math.PI * 1.6 * index) / Math.max(count - 1, 1))
    : (-Math.PI / 2) + ((Math.PI * 2 * index) / count);
  return new THREE.Vector3(Math.cos(angle) * radius, 0, Math.sin(angle) * radius);
}

function updateTopologyKeyboardMovement(viewer, delta) {
  if (!viewer.keys.size) return;
  const forward = new THREE.Vector3();
  viewer.camera.getWorldDirection(forward);
  forward.y = 0;
  if (forward.lengthSq() === 0) return;
  forward.normalize();
  const right = new THREE.Vector3().crossVectors(forward, viewer.camera.up).normalize();
  const move = new THREE.Vector3();
  if (viewer.keys.has("w")) move.add(forward);
  if (viewer.keys.has("s")) move.sub(forward);
  if (viewer.keys.has("d")) move.add(right);
  if (viewer.keys.has("a")) move.sub(right);
  if (move.lengthSq() === 0) return;
  move.normalize().multiplyScalar(delta * 2.8);
  viewer.camera.position.add(move);
  viewer.controls.target.add(move);
  if (viewer.readerLookPosition) {
    viewer.readerLookPosition.add(move);
  }
}

function syncFinalReviewReaderUiVisibility(viewer) {
  if (!viewer || viewer.disposed) return false;
  if (viewer.readerHandRig?.group) {
    viewer.readerHandRig.group.visible = viewer.renderer?.xr?.isPresenting !== true;
  }
  if (viewer.finalReviewTextGroup) viewer.finalReviewTextGroup.visible = true;
  return true;
}

function finalReviewAuthoredReaderTransform(viewer) {
  const context = viewer?.sceneContext?.beatId
    ? viewer.sceneContext
    : state.selectedFinalReviewSceneContext;
  return context?.beatId ? interactionReaderTransformForContext(context) : null;
}

function applyFinalReviewAuthoredReaderPose(viewer) {
  if (!viewer || viewer.disposed) return false;
  const transform = finalReviewAuthoredReaderTransform(viewer);
  if (!transform) return false;
  const position = new THREE.Vector3().fromArray(transform.position);
  const quaternion = new THREE.Quaternion().fromArray(transform.quaternion).normalize();
  const direction = new THREE.Vector3(0, 0, -1).applyQuaternion(quaternion).normalize();
  const distance = Math.max(
    Number(viewer.readerLookDistance)
      || viewer.camera.position.distanceTo(viewer.controls.target),
    0.35,
  );
  viewer.camera.position.copy(position);
  viewer.camera.quaternion.copy(quaternion);
  viewer.controls.target.copy(position).addScaledVector(direction, distance);
  viewer.camera.lookAt(viewer.controls.target);
  viewer.camera.updateMatrixWorld(true);
  viewer.readerLookPosition ||= new THREE.Vector3();
  viewer.readerLookDirection ||= new THREE.Vector3();
  viewer.readerLookPosition.copy(position);
  viewer.readerLookDirection.copy(direction);
  viewer.readerLookDistance = distance;
  viewer.authoredReaderTransform = transform;
  return true;
}

function resetFinalReviewReaderLookAnchor(viewer) {
  if (!viewer || viewer.disposed) return false;
  viewer.readerLookPosition ||= new THREE.Vector3();
  viewer.readerLookDirection ||= new THREE.Vector3();
  viewer.readerLookPosition.copy(viewer.camera.position);
  viewer.camera.getWorldDirection(viewer.readerLookDirection);
  viewer.readerLookDistance = Math.max(
    viewer.camera.position.distanceTo(viewer.controls.target),
    0.35,
  );
  return true;
}

function stabilizeFinalReviewReaderLook(viewer) {
  if (!viewer || viewer.disposed) return false;
  if (!viewer.readerLookPosition || !Number.isFinite(viewer.readerLookDistance)) {
    return resetFinalReviewReaderLookAnchor(viewer);
  }
  const direction = viewer.readerLookDirection || new THREE.Vector3();
  viewer.readerLookDirection = direction;
  const expectedTarget = viewer.readerLookPosition.clone().addScaledVector(
    direction,
    viewer.readerLookDistance,
  );
  const cameraDelta = viewer.camera.position.clone().sub(viewer.readerLookPosition);
  const targetDelta = viewer.controls.target.clone().sub(expectedTarget);
  const panTolerance = Math.max(1e-12, targetDelta.lengthSq() * 1e-8);
  if (
    targetDelta.lengthSq() > 1e-16
    && cameraDelta.distanceToSquared(targetDelta) <= panTolerance
  ) {
    viewer.readerLookPosition.add(targetDelta);
  }
  viewer.camera.getWorldDirection(direction);
  viewer.camera.position.copy(viewer.readerLookPosition);
  viewer.controls.target.copy(viewer.readerLookPosition).addScaledVector(
    direction,
    viewer.readerLookDistance,
  );
  viewer.camera.lookAt(viewer.controls.target);
  viewer.camera.updateMatrixWorld(true);
  return true;
}

function captureTopologyViewerCameraState() {
  if (!topologyViewer || topologyViewer.disposed) return null;
  return previewCameraState(topologyViewer);
}

function applyTopologyViewerCameraState(viewer, cameraState) {
  if (!shouldRestorePreviewCameraState(viewer, cameraState)) return;
  viewer.camera.position.fromArray(cameraState.position);
  viewer.camera.quaternion.fromArray(cameraState.quaternion);
  viewer.camera.near = cameraState.near;
  viewer.camera.far = cameraState.far;
  viewer.camera.updateProjectionMatrix();
  viewer.controls.target.fromArray(cameraState.target);
  viewer.controls.update();
}

function fitTopologyPreviewCamera(viewer, object) {
  if (!viewer) return;
  fitCameraToObject(viewer.camera, viewer.controls, object);
}

function fitInheritedTopologyPreviewCamera(viewer, object) {
  if (!viewer) return;
  fitTopologyPreviewCamera(viewer, object);
  viewer.previewCameraFramingReady = true;
}

function fitInteractionControlPreviewCamera(viewer, object) {
  if (viewer?.spatialEditorCamera) {
    const framed = fitSpatialEditorCameraOnLoad(viewer);
    if (!framed) fitCameraToObject(viewer.camera, viewer.controls, object);
    viewer.previewCameraFramingReady = true;
    return;
  }
  fitInheritedTopologyPreviewCamera(viewer, object);
}

function interactionPreviewCameraFramingContract(beat, sceneContext = null) {
  return `${INTERACTION_PREVIEW_CAMERA_FRAMING_CONTRACT}:${spatialSceneRequestKey(sceneContext) || beat?.id || "story-entry"}`;
}

const AUTHORING_SPATIAL_CAMERA_CONTRACT = "storyvr-authoring-spatial-camera/v1";
const AUTHORING_SPATIAL_CAMERA_KIND = "outside-reader-rig-v4";

function isAuthoringSpatialCameraViewer(viewer) {
  return Boolean(
    viewer
    && !viewer.thumbnailMode
    && [
      SPATIAL_RELATIONS_COMPONENT_ID,
      "environment-enhancement",
      ATTENTION_GUIDANCE_COMPONENT_ID,
      "dynamic-geometry",
      "inter-beat-dynamics",
      "interaction-control",
    ].includes(viewer.componentId),
  );
}

function authoringSpatialCameraFramingContract(sceneContext) {
  const sceneKey = authoringSpatialCameraSceneKey(sceneContext);
  return sceneKey ? `${AUTHORING_SPATIAL_CAMERA_CONTRACT}:${sceneKey}` : "";
}

function authoringSpatialCameraSceneKey(sceneContext) {
  if (!sceneContext?.beatId) return "";
  return spatialSceneRequestKey(spatialSceneContext(
    sceneContext.beatId,
    sceneContext.variantGroupId,
    sceneContext.variantOptionId,
  ));
}

function configureAuthoringSpatialCameraViewer(viewer, sceneContext = viewer?.sceneContext) {
  if (!viewer || !sceneContext?.beatId) return viewer;
  viewer.sceneContext = sceneContext;
  viewer.spatialEditorCamera = AUTHORING_SPATIAL_CAMERA_KIND;
  viewer.previewCameraFramingContract = authoringSpatialCameraFramingContract(sceneContext);
  viewer.authoringSpatialObjects ||= new Map();
  return viewer;
}

function authoringSpatialCameraStateForViewer(viewer) {
  const key = authoringSpatialCameraSceneKey(viewer?.sceneContext);
  return key ? state.authoringSpatialCameraStates?.[key] || null : null;
}

function captureAuthoringSpatialCameraState(viewer) {
  if (!isAuthoringSpatialCameraViewer(viewer)) return null;
  if (viewer.renderer?.xr?.isPresenting || viewer.sourceCameraCue || viewer.sourceCameraCuePending) return null;
  if (String(viewer.previewCameraFramingContract || "").startsWith("source-playback-camera:")) return null;
  const key = authoringSpatialCameraSceneKey(viewer.sceneContext);
  if (!key || !viewer.previewCameraFramingReady) return null;
  const cameraState = previewCameraState(viewer);
  if (cameraState.previewCameraFramingContract !== viewer.previewCameraFramingContract) return null;
  state.authoringSpatialCameraStates[key] = cameraState;
  return cameraState;
}

function restoreAuthoringSpatialCameraState(viewer) {
  const cameraState = authoringSpatialCameraStateForViewer(viewer);
  if (!shouldRestorePreviewCameraState(viewer, cameraState)) return false;
  applyPreviewViewerCameraState(viewer, cameraState);
  return true;
}

function authoredReaderPoseForViewer(viewer) {
  const entity = viewer?.readerEntity;
  if (!entity) return spatialReaderRigPose();
  const transform = normalizeSpatialTransform(entity.transform, entity.inferredTransform);
  const position = new THREE.Vector3().fromArray(transform.position);
  const quaternion = new THREE.Quaternion().fromArray(transform.quaternion);
  const forward = new THREE.Vector3(0, 0, -1).applyQuaternion(quaternion);
  return { position, target: position.clone().add(forward) };
}

function authoringSpatialSceneBounds(viewer) {
  const bounds = new THREE.Box3();
  for (const object of viewer?.authoringSpatialObjects?.values?.() || []) {
    object.updateWorldMatrix(true, true);
    bounds.expandByObject(object);
  }
  const readerPose = authoredReaderPoseForViewer(viewer);
  if (readerPose?.position) {
    const eye = readerPose.position;
    bounds.expandByPoint(eye.clone().add(new THREE.Vector3(-0.22, -1.55, -0.22)));
    bounds.expandByPoint(eye.clone().add(new THREE.Vector3(0.22, 0.12, 0.22)));
  }
  return bounds;
}

function fitAuthoringSpatialCameraOnLoad(viewer, { force = false } = {}) {
  if (!isAuthoringSpatialCameraViewer(viewer) || viewer.disposed) return false;
  if (!force && viewer.previewCameraFramingReady) return true;
  const bounds = authoringSpatialSceneBounds(viewer);
  if (bounds.isEmpty()) return false;

  const sphere = bounds.getBoundingSphere(new THREE.Sphere());
  const radius = Math.max(sphere.radius, 0.65);
  const verticalFov = THREE.MathUtils.degToRad(viewer.camera.fov);
  const horizontalFov = 2 * Math.atan(Math.tan(verticalFov * 0.5) * Math.max(viewer.camera.aspect, 0.1));
  const limitingFov = Math.max(THREE.MathUtils.degToRad(12), Math.min(verticalFov, horizontalFov));
  const distance = Math.max(1.8, (radius / Math.sin(limitingFov * 0.5)) * 1.42);
  const readerPose = authoredReaderPoseForViewer(viewer);
  const readerPosition = readerPose?.position || sphere.center.clone();
  const readerBack = readerPose?.target
    ? readerPosition.clone().sub(readerPose.target)
    : new THREE.Vector3(0, 0, 1);
  readerBack.y = 0;
  if (readerBack.lengthSq() < 1e-8) readerBack.set(0, 0, 1);
  else readerBack.normalize();
  const readerRight = new THREE.Vector3(readerBack.z, 0, -readerBack.x).normalize();
  const direction = readerPosition.clone().sub(sphere.center);
  direction.y = 0;
  if (direction.lengthSq() < Math.max(radius * radius * 0.0025, 0.0025)) direction.copy(readerBack);
  else direction.normalize();
  direction
    .multiplyScalar(0.82)
    .addScaledVector(readerBack, 0.18)
    .addScaledVector(readerRight, 0.28)
    .addScaledVector(new THREE.Vector3(0, 1, 0), 0.16)
    .normalize();

  viewer.controls.target.copy(sphere.center);
  viewer.camera.position.copy(sphere.center).addScaledVector(direction, distance);
  viewer.camera.near = Math.max(radius / 250, 0.01);
  viewer.camera.far = Math.max(distance + radius * 12, 100);
  viewer.controls.minDistance = Math.max(radius * 0.08, 0.05);
  viewer.controls.maxDistance = Math.max(distance * 5, 20);
  viewer.camera.updateProjectionMatrix();
  viewer.camera.lookAt(sphere.center);
  viewer.controls.update();
  viewer.previewCameraFramingReady = true;
  captureAuthoringSpatialCameraState(viewer);
  return true;
}

function dynamicPreviewAssetTargetSize(viewer, active) {
  return active ? 0.76 : 0.54;
}

function dynamicAssetNormalizationMode(spatialTransformApplied, spatialEntity) {
  if (!spatialTransformApplied) return "topology";
  return spatialEntity?.preserveSourceGeometry === true ? "none" : "spatial";
}

function captureDynamicViewerCameraState() {
  if (!dynamicViewer || dynamicViewer.disposed) return null;
  if (dynamicSourceCameraPlaybackEntry(dynamicViewer)) return null;
  return previewCameraState(dynamicViewer);
}

function applyDynamicViewerCameraState(viewer, cameraState) {
  if (!shouldRestorePreviewCameraState(viewer, cameraState)) return;
  viewer.camera.position.fromArray(cameraState.position);
  viewer.camera.quaternion.fromArray(cameraState.quaternion);
  viewer.camera.near = cameraState.near;
  viewer.camera.far = cameraState.far;
  viewer.camera.updateProjectionMatrix();
  viewer.controls.target.fromArray(cameraState.target);
  viewer.controls.update();
}

function captureInterBeatViewerCameraState() {
  if (!interBeatViewer || interBeatViewer.disposed) return null;
  return previewCameraState(interBeatViewer);
}

function applyInterBeatViewerCameraState(viewer, cameraState) {
  if (!shouldRestorePreviewCameraState(viewer, cameraState)) return;
  viewer.camera.position.fromArray(cameraState.position);
  viewer.camera.quaternion.fromArray(cameraState.quaternion);
  viewer.camera.near = cameraState.near;
  viewer.camera.far = cameraState.far;
  viewer.camera.updateProjectionMatrix();
  viewer.controls.target.fromArray(cameraState.target);
  viewer.controls.update();
}

function captureContextViewerCameraState() {
  if (!contextViewer || contextViewer.disposed) return null;
  return previewCameraState(contextViewer);
}

function applyContextViewerCameraState(viewer, cameraState) {
  if (!shouldRestorePreviewCameraState(viewer, cameraState)) return;
  viewer.camera.position.fromArray(cameraState.position);
  viewer.camera.quaternion.fromArray(cameraState.quaternion);
  viewer.camera.near = cameraState.near;
  viewer.camera.far = cameraState.far;
  viewer.camera.updateProjectionMatrix();
  viewer.controls.target.fromArray(cameraState.target);
  viewer.controls.update();
}

function captureTextViewerCameraState() {
  if (!textViewer || textViewer.disposed) return null;
  return previewCameraState(textViewer);
}

function captureInteractionViewerCameraState() {
  if (!interactionViewer || interactionViewer.disposed) return null;
  return previewCameraState(interactionViewer);
}

function captureFinalReviewViewerCameraState() {
  if (!finalReviewViewer || finalReviewViewer.disposed) return null;
  return previewCameraState(finalReviewViewer);
}

function applyPreviewViewerCameraState(viewer, cameraState) {
  if (!shouldRestorePreviewCameraState(viewer, cameraState)) return;
  viewer.camera.position.fromArray(cameraState.position);
  viewer.camera.quaternion.fromArray(cameraState.quaternion);
  viewer.camera.near = cameraState.near;
  viewer.camera.far = cameraState.far;
  if (Number.isFinite(Number(cameraState.fov)) && viewer.camera.isPerspectiveCamera) {
    viewer.camera.fov = Number(cameraState.fov);
  }
  if (Number.isFinite(Number(cameraState.zoom)) && Number(cameraState.zoom) > 0) {
    viewer.camera.zoom = Number(cameraState.zoom);
  }
  viewer.camera.updateProjectionMatrix();
  viewer.controls.target.fromArray(cameraState.target);
  viewer.controls.update();
  viewer.previewCameraFramingReady = true;
}

function finiteFinalReviewCameraArray(value, length) {
  return Array.isArray(value)
    && value.length === length
    && value.every((entry) => Number.isFinite(Number(entry)));
}

function shouldRestoreFinalReviewViewerCameraState(viewer, cameraState) {
  if (!viewer || viewer.disposed || !cameraState) return false;
  // The compiled reader keeps one continuous reader rig, so a new beat's
  // topology metadata must not invalidate its current pose.
  return finiteFinalReviewCameraArray(cameraState.position, 3)
    && finiteFinalReviewCameraArray(cameraState.quaternion, 4)
    && finiteFinalReviewCameraArray(cameraState.target, 3)
    && Number.isFinite(Number(cameraState.near))
    && Number(cameraState.near) > 0
    && Number.isFinite(Number(cameraState.far))
    && Number(cameraState.far) > Number(cameraState.near);
}

function applyFinalReviewViewerCameraState(viewer, cameraState) {
  if (!shouldRestoreFinalReviewViewerCameraState(viewer, cameraState)) return false;
  viewer.camera.position.fromArray(cameraState.position);
  viewer.camera.quaternion.fromArray(cameraState.quaternion);
  viewer.camera.near = cameraState.near;
  viewer.camera.far = cameraState.far;
  viewer.camera.updateProjectionMatrix();
  viewer.controls.target.fromArray(cameraState.target);
  viewer.controls.update();
  return true;
}

function previewCameraState(viewer) {
  if (!viewer) return null;
  return {
    position: viewer.camera.position.toArray(),
    quaternion: viewer.camera.quaternion.toArray(),
    target: viewer.controls.target.toArray(),
    near: viewer.camera.near,
    far: viewer.camera.far,
    fov: viewer.camera.isPerspectiveCamera ? viewer.camera.fov : null,
    zoom: viewer.camera.zoom,
    spatialEditorCamera: viewer.spatialEditorCamera || null,
    authoringSpatialSceneKey: isAuthoringSpatialCameraViewer(viewer)
      ? authoringSpatialCameraSceneKey(viewer.sceneContext)
      : null,
    topologyKind: viewer.topologyKind || viewer.layoutKind || viewer.decisionKinds?.topology || null,
    previewCameraFramingContract: viewer.previewCameraFramingReady
      ? (viewer.previewCameraFramingContract || null)
      : null,
  };
}

function shouldRestorePreviewCameraState(viewer, cameraState) {
  if (!viewer || !cameraState) return false;
  const expectedFramingContract = viewer.previewCameraFramingContract || null;
  if (expectedFramingContract && cameraState.previewCameraFramingContract !== expectedFramingContract) return false;
  const expectedKind = viewer.topologyKind || viewer.layoutKind || viewer.decisionKinds?.topology || null;
  if (cameraState.topologyKind && expectedKind && cameraState.topologyKind !== expectedKind) return false;
  return true;
}

function captureMountedPreviewCameraState() {
  if (state.suppressNextMountedPreviewCameraCapture) {
    state.suppressNextMountedPreviewCameraCapture = false;
    return;
  }
  if (
    interBeatViewer
    && !interBeatViewer.disposed
    && (interBeatViewer.thumbnailMode || interBeatViewer.sourceCameraCue)
  ) return;
  const viewer = [
    topologyViewer,
    dynamicViewer,
    interBeatViewer,
    contextViewer,
    textViewer,
    interactionViewer,
    finalReviewViewer,
  ].find((candidate) => candidate && !candidate.disposed);
  if (!viewer) return;
  if (isAuthoringSpatialCameraViewer(viewer)) {
    captureAuthoringSpatialCameraState(viewer);
    return;
  }
  if (viewer.componentId === "dynamic-geometry" && dynamicSourceCameraPlaybackEntry(viewer)) return;
  if (viewer.componentId === "interaction-control") {
    state.interactionViewerCameraState = previewCameraState(viewer);
    return;
  }
  if (viewer.componentId === ATTENTION_GUIDANCE_COMPONENT_ID) {
    state.attentionViewerCameraState = previewCameraState(viewer);
    return;
  }
  if (viewer.spatialEditorCamera) {
    state.textViewerCameraState = previewCameraState(viewer);
    return;
  }
  state.sharedPreviewCameraState = previewCameraState(viewer);
}

function restoredPreviewCameraState(viewer, componentCameraState) {
  if (shouldRestorePreviewCameraState(viewer, state.sharedPreviewCameraState)) {
    return state.sharedPreviewCameraState;
  }
  if (shouldRestorePreviewCameraState(viewer, componentCameraState)) {
    return componentCameraState;
  }
  return null;
}

function narrativeSceneAssetLinks(proposal, beats) {
  const proposalLinks = proposal?.assetLinks || [];
  const linkedAssetIds = [];
  const seen = new Set();
  for (const beat of beats || []) {
    for (const assetId of beat.linkedAssetIds || []) {
      if (seen.has(assetId)) continue;
      seen.add(assetId);
      linkedAssetIds.push(assetId);
    }
  }
  return linkedAssetIds.map((assetId) => {
    const proposalLink = proposalLinks.find((link) => link.assetId === assetId);
    const asset = findAssetById(assetId);
    return {
      assetId,
      role: proposalLink?.role || asset?.role || asset?.type || "story-part anchor",
    };
  });
}

function exactSpatialSceneAssetLinkSet(sceneContext, transitionSceneRole) {
  if (!sceneContext?.beatId) return { available: false, links: [] };
  const contract = lockedSpatialRelationsContract();
  const scene = spatialSceneRecordForContext(contract, sceneContext);
  if (!scene) return { available: false, links: [] };
  const links = spatialSceneEntities(contract, sceneContext)
    .filter((entity) => ["glb", "image-plane"].includes(spatialEntityType(entity)))
    .map((entity) => {
      const asset = findAssetById(entity.assetId);
      return {
        assetId: entity.assetId,
        entityId: entity.id,
        kind: spatialEntityType(entity),
        role: entity.role || asset?.role || asset?.type || "Scene asset",
        sceneContext,
        transitionSceneRole,
      };
    });
  return { available: true, links };
}

function interBeatExactBoundaryAssetLinks(beatContext, { includeFrom = true } = {}) {
  const target = exactSpatialSceneAssetLinkSet(
    beatContext?.toSceneContext,
    "to",
  );
  const source = includeFrom
    ? exactSpatialSceneAssetLinkSet(beatContext?.fromSceneContext, "from")
    : { available: false, links: [] };
  return {
    available: target.available || source.available,
    links: target.available
      ? [...(source.available ? source.links : []), ...target.links]
      : source.links,
    sourceLinks: source.links,
    targetLinks: target.links,
  };
}

function interBeatSpatialSceneContextsByEntityId(assetLinks) {
  return new Map((assetLinks || [])
    .filter((link) => link?.entityId && link?.sceneContext?.beatId)
    .map((link) => [String(link.entityId), link.sceneContext]));
}

function narrativeAssetPosition3d(kind, index, total, active, topologyKind = null) {
  if (topologyKind === "single") {
    if (active) return new THREE.Vector3(0, 0, 0);
    const count = Math.max(total - 1, 1);
    const adjusted = index % count;
    const angle = (-Math.PI / 2) + ((Math.PI * 2 * adjusted) / count);
    return new THREE.Vector3(Math.cos(angle) * 1.45, 0, Math.sin(angle) * 1.45);
  }
  if (topologyKind === "map") return topologyAssetPosition3d("map", index, total);
  if (topologyKind === "constellation") return topologyAssetPosition3d("constellation", index, total);
  if (kind === "object") {
    if (active) return new THREE.Vector3(0, 0, 0);
    const count = Math.max(total - 1, 1);
    const adjusted = index % count;
    const angle = (-Math.PI / 2) + ((Math.PI * 2 * adjusted) / count);
    return new THREE.Vector3(Math.cos(angle) * 1.75, 0, Math.sin(angle) * 1.75);
  }
  if (kind === "region") {
    const positions = [
      [-1.45, -0.92],
      [-0.2, -1.35],
      [1.25, -0.6],
      [1.1, 1.0],
      [-0.75, 0.95],
      [0.3, 0.08],
    ];
    const [x, z] = positions[index % positions.length];
    return new THREE.Vector3(x, 0, z);
  }
  if (active) return new THREE.Vector3(0, 0, 0);
  const count = Math.max(total, 1);
  const angle = (-Math.PI * 0.8) + ((Math.PI * 1.6 * index) / Math.max(count - 1, 1));
  return new THREE.Vector3(Math.cos(angle) * 2.05, 0, Math.sin(angle) * 2.05);
}

function initializeDynamicGeometryViewer(active) {
  if (active?.id !== "dynamic-geometry") return;
  const container = document.querySelector("[data-dynamic-viewer]");
  if (!container) return;
  const sceneContext = activeDynamicSceneContext();
  if (!sceneContext) return;

  const component = componentById("dynamic-geometry");
  const proposal = selectedComponentPreview(component);
  if (!proposal) return;

  const kind = inferDynamicGeometryKind(proposal);
  const layers = cumulativePreviewLayersForComponent("dynamic-geometry", { dynamicKind: kind });
  const layoutKind = layers.topologyKind;
  const beat = dynamicPreviewBeatForSceneContext(proposal, sceneContext);
  if (!beat) return;
  const proceduralPlan = activeProceduralDynamicsPlan(sceneContext);
  const proceduralInstances = proceduralPlan
    ? expandProceduralDynamicsInstances(proceduralPlan, { xrPresenting: true })
    : [];
  const proceduralAnchorPosition = proceduralDynamicsReaderAnchorForScene(sceneContext);
  const hasProceduralMotion = proceduralInstances.length > 0;
  const cumulativeContext = null;
  const assetLinks = dynamicSceneAssetLinks(proposal, [beat], sceneContext);
  const readerEntity = spatialSceneEntities(lockedSpatialRelationsContract(), sceneContext)
    .find((entity) => spatialEntityType(entity) === "reader") || null;
  const activeAssetIds = new Set(beat.linkedAssetIds || []);
  const activeAssetIndex = Math.max(assetLinks.findIndex((assetLink) => activeAssetIds.has(assetLink.assetId)), 0);
  const hasSourceAnimation = kind !== "none" && dynamicPreviewHasEmbeddedGlbAnimation(proposal, beat);
  const width = Math.max(container.clientWidth, 360);
  const height = Math.max(container.clientHeight, 520);
  const scene = new THREE.Scene();
  scene.background = new THREE.Color(0xf8f7ec);

  const camera = new THREE.PerspectiveCamera(42, width / height, 0.02, 1000);
  camera.position.set(3.4, 2.3, 4.8);

  const renderer = new THREE.WebGLRenderer({ antialias: true, alpha: true });
  renderer.setPixelRatio(Math.min(window.devicePixelRatio || 1, 2));
  renderer.setSize(width, height);
  renderer.outputColorSpace = THREE.SRGBColorSpace;
  renderer.domElement.tabIndex = 0;
  renderer.domElement.className = "topology-viewer-canvas";

  const status = document.createElement("div");
  status.className = "topology-viewer-status overlay";
  status.textContent = assetLinks.length ? `Loading ${assetLinks.length} dynamic assets...` : "No linked assets available for dynamic preview.";
  container.replaceChildren(renderer.domElement, status);
  const metadataOverlay = addPreviewMetadataOverlay(
    container,
    dynamicPreviewMetadataEntries(
      layers,
      kind,
      assetLinks,
      activeAssetIndex,
      activeAssetIds,
      cumulativeContext,
      hasSourceAnimation,
      hasProceduralMotion,
    ),
  );

  const controls = new OrbitControls(camera, renderer.domElement);
  controls.enableDamping = true;
  controls.dampingFactor = 0.08;
  controls.target.set(0, 0.85, 0);
  controls.maxPolarAngle = Math.PI / 2 - 0.02;
  configureSpatialEditorMouseControls(controls);

  scene.add(new THREE.HemisphereLight(0xffffff, 0x6f7f78, 2.35));
  const keyLight = new THREE.DirectionalLight(0xffffff, 3.1);
  keyLight.position.set(4, 7, 5);
  scene.add(keyLight);
  const rimLight = new THREE.DirectionalLight(0x9edfd5, 1.1);
  rimLight.position.set(-5, 3, -4);
  scene.add(rimLight);

  const root = new THREE.Group();
  scene.add(root);
  const readerEditorLayer = createSpatialReaderRig(root, readerEntity);

  const viewer = {
    scene,
    camera,
    renderer,
    controls,
    root,
    readerRig: readerEditorLayer.rig,
    readerProxy: readerEditorLayer.proxy,
    readerEntity,
    authoringSpatialObjects: new Map(),
    animationId: null,
    resizeHandler: null,
    keyDownHandler: null,
    keyUpHandler: null,
    pointerDownHandler: null,
    disposed: false,
    focused: false,
    keys: new Set(),
    lastFrameAt: performance.now(),
    elapsed: 0,
    playing: (hasSourceAnimation || hasProceduralMotion) && Boolean(state.dynamicPreviewPlaying),
    speed: Number(state.dynamicPreviewSpeed) || 1,
    kind,
    layers,
    layoutKind,
    topologyKind: layoutKind,
    contextKind: layers.contextKind,
    textKind: layers.textKind,
    componentId: "dynamic-geometry",
    beat,
    sceneContext,
    hasSourceAnimation,
    hasProceduralMotion,
    suppressSceneLabels: true,
    metadataOverlay,
    sourceDynamicsAssets: proposal?.sourceDynamics?.assets || [],
    proceduralPlan,
    proceduralInstances,
    proceduralAnchorPosition,
    proceduralPreviewEntries: [],
    cumulativeContext,
    activeSwapIndex: cumulativeContext?.activeIndex || 0,
    swapGroups: [],
    swapDuplicates: [],
    swapReady: false,
    duplicateCount: topologySwapDuplicateCount(state.data?.decisions?.["asset-topology"]?.option),
    assetLinks,
    dynamicObjects: [],
    selectionHelpers: [],
    effects: null,
    descriptionCues: null,
  };
  configureAuthoringSpatialCameraViewer(viewer, sceneContext);
  dynamicViewer = viewer;
  syncDynamicSceneObjectSelection();
  // Reader text is a hand-attached system surface, not scene geometry in the Dynamics editor.
  viewer.inheritedTextLayer = null;
  attachLockedEnvironmentToViewer(viewer);
  const canRestoreCameraState = restoreAuthoringSpatialCameraState(viewer);
  const frameLoadedDynamicCamera = () => {
    if (!canRestoreCameraState) fitAuthoringSpatialCameraOnLoad(viewer);
  };

  container.addEventListener("pointerdown", () => {
    viewer.focused = true;
    container.classList.add("focused");
    renderer.domElement.focus();
  });
  renderer.domElement.addEventListener("blur", () => {
    viewer.focused = false;
    viewer.keys.clear();
    container.classList.remove("focused");
  });

  viewer.pointerDownHandler = (event) => {
    if (!container.contains(event.target)) {
      viewer.focused = false;
      viewer.keys.clear();
      container.classList.remove("focused");
    }
  };
  viewer.keyDownHandler = (event) => {
    const key = event.key.toLowerCase();
    if (!viewer.focused || !["w", "a", "s", "d"].includes(key)) return;
    event.preventDefault();
    viewer.keys.add(key);
  };
  viewer.keyUpHandler = (event) => {
    const key = event.key.toLowerCase();
    if (!["w", "a", "s", "d"].includes(key)) return;
    viewer.keys.delete(key);
  };
  viewer.resizeHandler = () => {
    if (viewer.disposed) return;
    const nextWidth = Math.max(container.clientWidth, 360);
    const nextHeight = Math.max(container.clientHeight, 520);
    camera.aspect = nextWidth / nextHeight;
    camera.updateProjectionMatrix();
    renderer.setSize(nextWidth, nextHeight);
  };
  document.addEventListener("pointerdown", viewer.pointerDownHandler);
  window.addEventListener("keydown", viewer.keyDownHandler);
  window.addEventListener("keyup", viewer.keyUpHandler);
  window.addEventListener("resize", viewer.resizeHandler);

  if (!assetLinks.length) {
    root.add(makeTopologyPlaceholder("No moving objects", "Link source assets in Story order first", 0xc98a8a));
    frameLoadedDynamicCamera();
  } else if (cumulativeContext) {
    let pending = assetLinks.length;
    let failed = 0;
    const finishAsset = (ok) => {
      pending -= 1;
      if (!ok) failed += 1;
      if (viewer.disposed) return;
      syncDynamicSceneObjectSelection();
      if (pending > 0) {
        status.textContent = `Loading ${pending} more active story-part assets...`;
      } else {
        frameLoadedDynamicCamera();
        viewer.swapReady = true;
        if (failed) {
          status.textContent = `Loaded cumulative scene with ${failed} asset issue${failed === 1 ? "" : "s"}.`;
          return;
        }
        status.remove();
      }
    };
    assetLinks.forEach((assetLink, index) => {
      loadTopologySwapAsset(viewer, assetLink, index, finishAsset);
    });
  } else {
    let pending = assetLinks.length;
    let failed = 0;
    const finishAsset = (ok) => {
      pending -= 1;
      if (!ok) failed += 1;
      if (viewer.disposed) return;
      syncDynamicSceneObjectSelection();
      if (pending > 0) {
        status.textContent = `Loading ${pending} more dynamic assets...`;
      } else {
        frameLoadedDynamicCamera();
        if (failed) status.textContent = `Loaded with ${failed} dynamic preview issue${failed === 1 ? "" : "s"}.`;
        else status.remove();
      }
    };
    assetLinks.forEach((assetLink, index) => {
      loadDynamicAsset(viewer, assetLink, index, assetLinks.length, activeAssetIds.has(assetLink.assetId) || index === activeAssetIndex, finishAsset);
    });
  }

  const animate = (time) => {
    if (viewer.disposed) return;
    const delta = Math.min((time - viewer.lastFrameAt) / 1000, 0.05);
    viewer.lastFrameAt = time;
    viewer.elapsed += previewPlaybackDeltaSeconds(viewer, delta);
    updateTopologyKeyboardMovement(viewer, delta);
    if (animateNarrativeSingleAnchorViewer(viewer, delta)) return;
    animateDynamicGeometry(viewer);
    for (const helper of viewer.selectionHelpers) helper.update();
    controls.update();
    renderer.render(scene, camera);
    viewer.animationId = requestAnimationFrame(animate);
  };
  viewer.animationId = requestAnimationFrame(animate);
}

function dynamicSceneObjectForEntityId(viewer, entityId) {
  if (!viewer || !entityId) return null;
  if (viewer.readerEntity?.id === entityId) return viewer.readerRig || null;
  const entry = viewer.dynamicObjects.find((candidate) => candidate.entityId === entityId);
  return entry?.authorWrapper || entry?.sourceScene || entry?.wrapper || null;
}

function syncDynamicSceneObjectSelection() {
  const entities = dynamicSceneObjectEntities();
  const selectedEntityId = ensureDynamicSceneObjectSelection(entities);
  for (const item of document.querySelectorAll("[data-dynamic-select-entity]")) {
    const selected = item.dataset.dynamicSelectEntity === selectedEntityId;
    item.classList.toggle("selected", selected);
    item.classList.toggle("selection-primary", selected);
    item.setAttribute("aria-pressed", String(selected));
  }
  const object = dynamicSceneObjectForEntityId(dynamicViewer, selectedEntityId);
  syncSpatialSelectionHelpers(dynamicViewer, object ? [object] : []);
}

function proceduralDynamicsReaderAnchorForScene(sceneContext) {
  const readerEntity = spatialSceneEntities(lockedSpatialRelationsContract(), sceneContext)
    .find((entity) => spatialEntityType(entity) === "reader");
  const transform = readerEntity?.transform
    || readerEntity?.worldTransform
    || readerEntity?.pose
    || readerEntity?.inferredTransform;
  return transform
    ? new THREE.Vector3().fromArray(normalizeSpatialTransform(transform).position)
    : new THREE.Vector3();
}

function requestInterBeatDynamicsAnimation(viewer) {
  if (!viewer || viewer.disposed || viewer.animationId || typeof viewer.animate !== "function") return;
  viewer.lastFrameAt = performance.now();
  viewer.animationId = requestAnimationFrame(viewer.animate);
}

function markInterBeatThumbnailReady(viewer) {
  if (!viewer?.thumbnailMode || viewer.disposed || viewer.thumbnailReady) return;
  viewer.thumbnailReady = true;
  viewer.elapsed = 0;
  resetPreviewCycle(viewer);
  const shouldPlay = Boolean(viewer.thumbnailAutoplayPending && state.interBeatPreviewPlaying);
  viewer.thumbnailAutoplayPending = false;
  viewer.playing = shouldPlay;
  if (shouldPlay) requestSourceCameraCue(viewer);
  viewer.renderer.render(viewer.scene, viewer.camera);
  if (shouldPlay) requestInterBeatDynamicsAnimation(viewer);
}

function interBeatSourcePlaybackPreviewAssetId(sourcePlaybackSummary) {
  if (
    sourcePlaybackSummary?.contractAvailable !== true
    || sourcePlaybackSummary?.windowState?.mode !== "scrub"
  ) return "";
  return String(sourcePlaybackSummary.assetId || "").trim();
}

function frameInterBeatSourcePlaybackAsset(viewer) {
  const assetId = String(viewer?.sourcePlaybackPreviewAssetId || "").trim();
  if (!assetId) return false;
  const entries = [
    ...(Array.isArray(viewer?.swapGroups) ? viewer.swapGroups : []),
    ...(Array.isArray(viewer?.dynamicObjects) ? viewer.dynamicObjects : []),
  ];
  const entry = entries.find((candidate) => candidate?.assetId === assetId);
  const object = entry?.modelRoot || entry?.sourceScene || entry?.authorWrapper || entry?.wrapper;
  if (!object) return false;
  fitCameraToObject(
    viewer.camera,
    viewer.controls,
    !viewer.thumbnailMode && viewer.readerRig ? viewer.root : object,
  );
  viewer.previewCameraFramingReady = true;
  return true;
}

function initializeInterBeatDynamicsViewer(active) {
  if (active?.id !== "inter-beat-dynamics") return;
  const editorSceneContext = activeInterBeatSceneContext();
  const canvasSceneContext = activeInterBeatCanvasPreviewContext();
  const sceneContext = editorSceneContext || canvasSceneContext;
  const thumbnailMode = !editorSceneContext && Boolean(canvasSceneContext);
  if (!sceneContext) return;
  const container = document.querySelector(thumbnailMode
    ? "[data-inter-beat-thumbnail-viewer]"
    : "[data-inter-beat-viewer]");
  if (!container) return;

  const component = componentById("inter-beat-dynamics");
  const proposal = selectedComponentPreview(component);
  if (!proposal) return;

  const kind = inferInterBeatDynamicsKind(proposal);
  const layers = cumulativePreviewLayersForComponent("inter-beat-dynamics", { transitionKind: kind });
  const layoutKind = layers.topologyKind;
  const previousDynamicKind = layers.dynamicKind;
  const playback = interBeatBoundaryPlaybackSummary(proposal, sceneContext);
  const beatContext = playback.boundary;
  const { transitions, beat, transition } = beatContext;
  const { sourcePartPlaybackMode, sourcePlaybackSummary, canScrub: hasScrubWindow } = playback;
  if (thumbnailMode && !hasScrubWindow) return;
  const frozenSourcePartState = beat?.sourcePartStates?.find((item) => item.playbackMode === "frozen") || null;
  const transitionIndex = Math.max(0, beatContext.beatIndex - 1);
  const legacyCumulativeContext = transition && !sceneContext.variantOptionId
    ? cumulativeSingleAnchorTransitionContext(transitions, transitionIndex)
    : null;
  const selectedBeats = beatContext.from ? [beatContext.from, beatContext.to] : (beatContext.to ? [beatContext.to] : []);
  const exactBoundaryAssets = thumbnailMode
    ? { available: false, links: [], sourceLinks: [], targetLinks: [] }
    : interBeatExactBoundaryAssetLinks(beatContext, { includeFrom: hasScrubWindow });
  const cumulativeContext = exactBoundaryAssets.available ? null : legacyCumulativeContext;
  const assetLinks = exactBoundaryAssets.available
    ? exactBoundaryAssets.links
    : cumulativeContext ? cumulativeContext.sequence.steps : narrativeSceneAssetLinks(proposal, selectedBeats);
  const sourcePlaybackPreviewAssetId = interBeatSourcePlaybackPreviewAssetId(sourcePlaybackSummary);
  const sourcePlaybackPreviewAssetIndex = sourcePlaybackPreviewAssetId
    ? assetLinks.findIndex((assetLink) => assetLink.assetId === sourcePlaybackPreviewAssetId)
    : -1;
  const previewActiveSwapIndex = sourcePlaybackPreviewAssetIndex >= 0
    ? sourcePlaybackPreviewAssetIndex
    : (cumulativeContext?.activeIndex || 0);
  if (!hasScrubWindow) state.interBeatPreviewPlaying = false;
  const fromAssetIds = new Set(exactBoundaryAssets.available
    ? exactBoundaryAssets.sourceLinks.map((link) => link.assetId)
    : cumulativeContext?.active?.assetId ? [cumulativeContext.active.assetId] : (beatContext.from?.linkedAssetIds || []));
  const toAssetIds = new Set(exactBoundaryAssets.available
    ? exactBoundaryAssets.targetLinks.map((link) => link.assetId)
    : cumulativeContext?.target?.assetId ? [cumulativeContext.target.assetId] : (beatContext.to?.linkedAssetIds || []));
  const activeAssetIds = new Set([...fromAssetIds, ...toAssetIds]);
  const fromAssetIndex = cumulativeContext
    ? cumulativeContext.activeIndex
    : Math.max(assetLinks.findIndex((assetLink) => assetLink.transitionSceneRole === "from" || fromAssetIds.has(assetLink.assetId)), 0);
  const toAssetIndex = cumulativeContext?.targetIndex != null
    ? cumulativeContext.targetIndex
    : Math.max(assetLinks.findIndex((assetLink) => assetLink.transitionSceneRole === "to" || toAssetIds.has(assetLink.assetId)), fromAssetIndex);
  const fromPosition = dynamicAssetPosition3d(fromAssetIndex, Math.max(assetLinks.length, 1), layoutKind, true);
  const toPosition = dynamicAssetPosition3d(toAssetIndex, Math.max(assetLinks.length, 1), layoutKind, true);
  const minimumWidth = thumbnailMode ? 176 : 360;
  const minimumHeight = thumbnailMode ? 104 : 520;
  const width = Math.max(container.clientWidth, minimumWidth);
  const height = Math.max(container.clientHeight, minimumHeight);
  const scene = new THREE.Scene();
  scene.background = new THREE.Color(0xf8f7ec);

  const camera = new THREE.PerspectiveCamera(42, width / height, 0.02, 1000);
  camera.position.set(3.4, 2.3, 4.8);

  const renderer = new THREE.WebGLRenderer({ antialias: true, alpha: true });
  renderer.setPixelRatio(Math.min(window.devicePixelRatio || 1, 2));
  renderer.setSize(width, height);
  renderer.outputColorSpace = THREE.SRGBColorSpace;
  renderer.domElement.tabIndex = thumbnailMode ? -1 : 0;
  renderer.domElement.className = `topology-viewer-canvas${thumbnailMode ? " transition-boundary-thumbnail-canvas" : ""}`;

  const status = document.createElement("div");
  status.className = "topology-viewer-status overlay";
  status.textContent = assetLinks.length
    ? (thumbnailMode ? "Loading scene change..." : `Loading ${assetLinks.length} scene-change assets...`)
    : "No linked story-part pairs are available for the scene-change preview.";
  container.replaceChildren(renderer.domElement, status);
  const metadataOverlay = thumbnailMode ? null : addPreviewMetadataOverlay(container, previewMetadataEntries({
      componentId: "inter-beat-dynamics",
      layers,
      currentValue: interBeatDynamicsKindLabel(kind),
      additionalEntries: [
        { id: "from", label: "From", value: interBeatTransitionBeatLabel(beatContext.from, previewAssetDisplayName(assetLinks[fromAssetIndex])) },
        { id: "to", label: "To", value: interBeatTransitionBeatLabel(beatContext.to, previewAssetDisplayName(assetLinks[toAssetIndex])) },
        { id: "source-timeline", label: "Source timeline", value: sourcePlaybackSummary.timelineLabel },
        { id: "source-window", label: "Source window", value: sourcePlaybackSummary.windowLabel },
        { id: "source-contributors", label: "Contributors", value: `${sourcePlaybackSummary.contributorCount} clip${sourcePlaybackSummary.contributorCount === 1 ? "" : "s"}` },
      ],
    }));

  const controls = new OrbitControls(camera, renderer.domElement);
  controls.enabled = !thumbnailMode;
  controls.enableDamping = true;
  controls.dampingFactor = 0.08;
  controls.target.set(0, 0.85, 0);
  if (!thumbnailMode) controls.maxPolarAngle = Math.PI / 2 - 0.02;
  configureSpatialEditorMouseControls(controls);

  scene.add(new THREE.HemisphereLight(0xffffff, 0x6f7f78, 2.35));
  const keyLight = new THREE.DirectionalLight(0xffffff, 3.1);
  keyLight.position.set(4, 7, 5);
  scene.add(keyLight);
  const rimLight = new THREE.DirectionalLight(0x9edfd5, 1.1);
  rimLight.position.set(-5, 3, -4);
  scene.add(rimLight);

  const root = new THREE.Group();
  scene.add(root);
  const readerEntity = thumbnailMode
    ? null
    : spatialSceneEntities(lockedSpatialRelationsContract(), beatContext.toSceneContext || sceneContext)
      .find((entity) => spatialEntityType(entity) === "reader") || null;
  const readerEditorLayer = thumbnailMode
    ? null
    : createSpatialReaderRig(root, readerEntity);

  const viewer = {
    scene,
    container,
    camera,
    renderer,
    controls,
    root,
    readerRig: readerEditorLayer?.rig || null,
    readerProxy: readerEditorLayer?.proxy || null,
    readerEntity,
    animationId: null,
    resizeHandler: null,
    keyDownHandler: null,
    keyUpHandler: null,
    pointerDownHandler: null,
    thumbnailVisibilityObserver: null,
    thumbnailVisible: true,
    disposed: false,
    focused: false,
    keys: new Set(),
    lastFrameAt: performance.now(),
    elapsed: 0,
    playing: thumbnailMode
      ? false
      : sourcePartPlaybackMode !== "frozen" && hasScrubWindow && Boolean(state.interBeatPreviewPlaying),
    thumbnailReady: !thumbnailMode,
    thumbnailAutoplayPending: thumbnailMode && Boolean(state.interBeatPreviewPlaying),
    speed: Number(state.interBeatPreviewSpeed) || 1,
    previewCycleSeconds: INTER_BEAT_TRANSITION_CYCLE_SECONDS,
    playOnce: true,
    kind,
    layers,
    geometryKind: previousDynamicKind || "motion",
    layoutKind,
    topologyKind: layoutKind,
    contextKind: layers.contextKind,
    textKind: layers.textKind,
    sourceDynamicsAssets: proposal?.sourceDynamics?.assets || [],
    sourcePlaybackSummary,
    legacySourceMotionTracks: playback.mappedTracks,
    manualVariantSwitch: playback.manualVariantSwitch,
    routeScopedTransition: playback.routeScopedProgression,
    variantTransitionAnimationSpec: playback.variantTransitionAnimationSpec,
    sourceCameraCuePending: false,
    sourceCameraCue: null,
    sourceMotionTransition: beatContext.fromBeatId ? {
      fromBeatId: beatContext.fromBeatId,
      toBeatId: beatContext.toBeatId || "",
      ...(beatContext.edgeId ? { edgeId: beatContext.edgeId } : {}),
      ...(beatContext.fromSceneContext ? { fromContext: normalizeMotionSceneContext(beatContext.fromSceneContext, beatContext.fromBeatId) } : {}),
      ...(beatContext.toSceneContext ? { toContext: normalizeMotionSceneContext(beatContext.toSceneContext, beatContext.toBeatId) } : {}),
    } : null,
    sourcePartFromBeatId: beatContext.fromBeatId || beatContext.toBeatId || "",
    sourcePartToBeatId: beatContext.toBeatId || "",
    sourcePartPlaybackMode,
    sourcePartFreezeProgress: Number(frozenSourcePartState?.freezeProgress) || 0,
    sourcePartMaskPhase: null,
    transitionFromAssetIds: fromAssetIds,
    transitionToAssetIds: toAssetIds,
    transitionFromAssetIndex: fromAssetIndex,
    transitionToAssetIndex: toAssetIndex,
    componentId: "inter-beat-dynamics",
    thumbnailMode,
    beat: beatContext.to,
    sceneContext: beatContext.toSceneContext,
    spatialSceneContextsByAssetId: interBeatSpatialSceneContextsByAssetId(beatContext),
    spatialSceneContextsByEntityId: interBeatSpatialSceneContextsByEntityId(assetLinks),
    authoringSpatialObjects: new Map(),
    suppressSceneLabels: true,
    metadataOverlay,
    cumulativeContext,
    usesExactSceneComposition: exactBoundaryAssets.available,
    activeSwapIndex: previewActiveSwapIndex,
    sourcePlaybackPreviewAssetId,
    swapGroups: [],
    swapDuplicates: [],
    swapReady: false,
    duplicateCount: topologySwapDuplicateCount(state.data?.decisions?.["asset-topology"]?.option),
    assetLinks,
    dynamicObjects: [],
    effects: addDynamicEffectOverlays(root, previousDynamicKind || "motion", fromPosition, beatContext.from),
    transitionEffects: addInterBeatTransitionOverlays(root, kind, fromPosition, toPosition, playback),
    descriptionCues: null,
  };
  if (!thumbnailMode) configureAuthoringSpatialCameraViewer(viewer, beatContext.toSceneContext || sceneContext);
  interBeatViewer = viewer;
  viewer.inheritedTextLayer = null;
  attachLockedEnvironmentToViewer(viewer);
  const restoredCameraState = thumbnailMode
    ? restoredPreviewCameraState(viewer, state.interBeatViewerCameraState)
    : null;
  const canRestoreCameraState = thumbnailMode
    ? !sourcePlaybackPreviewAssetId && shouldRestorePreviewCameraState(viewer, restoredCameraState)
    : restoreAuthoringSpatialCameraState(viewer);
  if (thumbnailMode && canRestoreCameraState) applyInterBeatViewerCameraState(viewer, restoredCameraState);
  const frameLoadedInterBeatCamera = () => {
    if (thumbnailMode) {
      if (canRestoreCameraState) applyInterBeatViewerCameraState(viewer, restoredCameraState);
      else if (!frameInterBeatSourcePlaybackAsset(viewer)) fitInheritedTopologyPreviewCamera(viewer, root);
      return;
    }
    if (!canRestoreCameraState) fitAuthoringSpatialCameraOnLoad(viewer);
  };

  if (!thumbnailMode) {
    viewer.sourceCameraControlStartHandler = () => cancelSourceCameraCue(viewer);
    controls.addEventListener("start", viewer.sourceCameraControlStartHandler);
    container.addEventListener("pointerdown", () => {
      viewer.focused = true;
      container.classList.add("focused");
      renderer.domElement.focus();
    });
    renderer.domElement.addEventListener("blur", () => {
      viewer.focused = false;
      viewer.keys.clear();
      container.classList.remove("focused");
    });
    viewer.pointerDownHandler = (event) => {
      if (!container.contains(event.target)) {
        viewer.focused = false;
        viewer.keys.clear();
        container.classList.remove("focused");
      }
    };
    viewer.keyDownHandler = (event) => {
      const key = event.key.toLowerCase();
      if (!viewer.focused || !["w", "a", "s", "d"].includes(key)) return;
      event.preventDefault();
      viewer.keys.add(key);
    };
    viewer.keyUpHandler = (event) => {
      const key = event.key.toLowerCase();
      if (!["w", "a", "s", "d"].includes(key)) return;
      viewer.keys.delete(key);
    };
    document.addEventListener("pointerdown", viewer.pointerDownHandler);
    window.addEventListener("keydown", viewer.keyDownHandler);
    window.addEventListener("keyup", viewer.keyUpHandler);
  }
  viewer.resizeHandler = () => {
    if (viewer.disposed) return;
    const nextWidth = Math.max(container.clientWidth, minimumWidth);
    const nextHeight = Math.max(container.clientHeight, minimumHeight);
    camera.aspect = nextWidth / nextHeight;
    camera.updateProjectionMatrix();
    renderer.setSize(nextWidth, nextHeight);
  };
  window.addEventListener("resize", viewer.resizeHandler);
  if (thumbnailMode && "IntersectionObserver" in window) {
    const viewport = container.closest("[data-inter-beat-story-canvas-viewport]");
    viewer.thumbnailVisibilityObserver = new IntersectionObserver((entries) => {
      if (viewer.disposed) return;
      viewer.thumbnailVisible = entries.some((entry) => entry.isIntersecting);
      if (viewer.thumbnailVisible && viewer.playing) requestInterBeatDynamicsAnimation(viewer);
    }, { root: viewport || null, threshold: 0.08 });
    viewer.thumbnailVisibilityObserver.observe(container);
  }

  if (!assetLinks.length) {
    frameLoadedInterBeatCamera();
    markInterBeatThumbnailReady(viewer);
  } else if (cumulativeContext) {
    let pending = assetLinks.length;
    let failed = 0;
    const finishAsset = (ok) => {
      pending -= 1;
      if (!ok) failed += 1;
      if (viewer.disposed) return;
      if (pending > 0) {
        status.textContent = `Loading ${pending} more cumulative scene-change assets...`;
      } else {
        frameLoadedInterBeatCamera();
        viewer.swapReady = true;
        if (failed) {
          status.textContent = `Loaded cumulative scene change with ${failed} asset issue${failed === 1 ? "" : "s"}.`;
        } else {
          status.remove();
        }
        markInterBeatThumbnailReady(viewer);
      }
    };
    assetLinks.forEach((assetLink, index) => {
      loadTopologySwapAsset(viewer, assetLink, index, finishAsset);
    });
  } else {
    let pending = assetLinks.length;
    let failed = 0;
    const finishAsset = (ok) => {
      pending -= 1;
      if (!ok) failed += 1;
      if (viewer.disposed) return;
      if (pending > 0) {
        status.textContent = `Loading ${pending} more scene-change assets...`;
      } else {
        frameLoadedInterBeatCamera();
        applyInterBeatExactSceneVisibility(viewer, viewer.playing ? 0 : 1);
        if (failed) status.textContent = `Loaded with ${failed} scene-change preview issue${failed === 1 ? "" : "s"}.`;
        else status.remove();
        markInterBeatThumbnailReady(viewer);
      }
    };
    assetLinks.forEach((assetLink, index) => {
      loadDynamicAsset(viewer, assetLink, index, assetLinks.length, activeAssetIds.has(assetLink.assetId) || index === fromAssetIndex || index === toAssetIndex, finishAsset);
    });
  }

  const animate = (time) => {
    if (viewer.disposed) return;
    viewer.animationId = null;
    const delta = Math.min((time - viewer.lastFrameAt) / 1000, 0.05);
    viewer.lastFrameAt = time;
    const playbackDelta = previewPlaybackDeltaSeconds(viewer, delta);
    viewer.elapsed += playbackDelta;
    if (!thumbnailMode) updateTopologyKeyboardMovement(viewer, delta);
    if (animateNarrativeSingleAnchorViewer(viewer, delta)) return;
    animateInterBeatDynamics(viewer);
    syncSourceCameraPreview(viewer, thumbnailMode ? playbackDelta : delta);
    controls.update();
    renderer.render(scene, camera);
    if (!thumbnailMode || (viewer.playing && viewer.thumbnailVisible)) requestInterBeatDynamicsAnimation(viewer);
  };
  viewer.animate = animate;
  renderer.render(scene, camera);
  if (!thumbnailMode || viewer.playing) requestInterBeatDynamicsAnimation(viewer);
}

function initializeEnvironmentStoryCanvasPreviews(active) {
  if (active?.id !== "environment-enhancement" || activeEnvironmentSceneContext()) return;
  const backdrops = [...document.querySelectorAll("[data-environment-card-backdrop]")];
  if (!backdrops.length) return;
  const requestId = ++environmentStoryCardPreviewRequestId;
  const pendingBySignature = new Map();
  const applyPreview = (backdrop, dataUrl, source = "reader-environment") => {
    if (!backdrop?.isConnected) return;
    backdrop.style.removeProperty("background");
    backdrop.style.backgroundImage = dataUrl ? `url("${dataUrl}")` : "";
    backdrop.dataset.environmentPreviewSource = source;
    backdrop.classList.toggle("ready", Boolean(dataUrl));
  };

  for (const backdrop of backdrops) {
    const card = backdrop.closest("[data-environment-open-scene]");
    const context = spatialSceneContext(
      card?.dataset.environmentBeatId,
      card?.dataset.environmentVariantGroupId,
      card?.dataset.environmentVariantOptionId,
    );
    const manifest = environmentManifest(context);
    const draft = environmentDraftFromManifest(manifest);
    if (manifest.skipped || !manifest.asset) {
      applyPreview(backdrop, "", "reader-neutral-fallback");
      continue;
    }
    if (draft.rendering.backgroundMode === "fog-color") {
      backdrop.style.background = draft.rendering.fogColor;
      backdrop.style.backgroundImage = "";
      backdrop.dataset.environmentPreviewSource = "reader-fog-color";
      backdrop.classList.add("ready");
      continue;
    }
    if (draft.rendering.backgroundMode === "transparent") {
      applyPreview(backdrop, "", "reader-transparent-background");
      continue;
    }
    const localUrl = String(manifest.asset.localUrl || "").trim();
    const mediaType = environmentNormalizeMediaType(manifest.asset.mediaType || manifest.asset.format, localUrl);
    if (!localUrl || (
      !ENVIRONMENT_HDR_MEDIA_TYPES.has(mediaType)
      && !ENVIRONMENT_EXR_MEDIA_TYPES.has(mediaType)
      && !ENVIRONMENT_PNG_MEDIA_TYPES.has(mediaType)
    )) {
      applyPreview(backdrop, "", "reader-environment-unavailable");
      continue;
    }
    const signature = JSON.stringify({
      url: localUrl,
      sha256: manifest.asset.sha256 || "",
      revision: manifest.revision || 0,
      yaw: draft.transform.rotationY,
      exposure: draft.rendering.exposure,
      backgroundMode: draft.rendering.backgroundMode,
    });
    const cached = environmentStoryCardPreviewCache.get(signature);
    if (cached) {
      applyPreview(backdrop, cached);
      continue;
    }
    const pending = pendingBySignature.get(signature) || {
      signature,
      localUrl,
      mediaType,
      draft,
      backdrops: [],
    };
    pending.backdrops.push(backdrop);
    pendingBySignature.set(signature, pending);
  }

  for (const pending of pendingBySignature.values()) {
    const loader = ENVIRONMENT_PNG_MEDIA_TYPES.has(pending.mediaType)
      ? new THREE.TextureLoader()
      : ENVIRONMENT_EXR_MEDIA_TYPES.has(pending.mediaType) ? new EXRLoader() : new HDRLoader();
    const url = new URL(pending.localUrl, window.location.href).href;
    environmentLoadWithLoader(loader, url).then((texture) => {
      if (requestId !== environmentStoryCardPreviewRequestId || activeEnvironmentSceneContext()) {
        texture.dispose();
        return;
      }
      texture.mapping = THREE.EquirectangularReflectionMapping;
      if (ENVIRONMENT_PNG_MEDIA_TYPES.has(pending.mediaType)) texture.colorSpace = THREE.SRGBColorSpace;
      const width = 480;
      const height = 240;
      const scene = new THREE.Scene();
      scene.background = texture;
      scene.backgroundRotation?.set?.(0, pending.draft.transform.rotationY, 0);
      const camera = new THREE.PerspectiveCamera(70, width / height, 0.01, 10);
      camera.position.set(0, 1.6, 0);
      camera.lookAt(0, 1.6, -1);
      const renderer = new THREE.WebGLRenderer({ antialias: true, alpha: false, preserveDrawingBuffer: true });
      renderer.setPixelRatio(1);
      renderer.setSize(width, height, false);
      renderer.outputColorSpace = THREE.SRGBColorSpace;
      renderer.toneMapping = THREE.ACESFilmicToneMapping;
      renderer.toneMappingExposure = pending.draft.rendering.exposure;
      renderer.render(scene, camera);
      const dataUrl = renderer.domElement.toDataURL("image/jpeg", 0.84);
      texture.dispose();
      renderer.dispose();
      renderer.forceContextLoss?.();
      environmentStoryCardPreviewCache.set(pending.signature, dataUrl);
      while (environmentStoryCardPreviewCache.size > 12) {
        environmentStoryCardPreviewCache.delete(environmentStoryCardPreviewCache.keys().next().value);
      }
      for (const backdrop of pending.backdrops) applyPreview(backdrop, dataUrl);
    }).catch(() => {
      if (requestId !== environmentStoryCardPreviewRequestId) return;
      for (const backdrop of pending.backdrops) applyPreview(backdrop, "", "reader-environment-load-failed");
    });
  }
}

function initializeEnvironmentEnhancementViewer(active) {
  if (active?.id !== "environment-enhancement") return;
  const sceneContext = activeEnvironmentSceneContext();
  if (!sceneContext) return;
  const container = document.querySelector("[data-environment-viewer]");
  if (!container) return;

  const width = Math.max(container.clientWidth, 360);
  const height = Math.max(container.clientHeight, 520);
  const scene = new THREE.Scene();
  scene.background = new THREE.Color(0x080a08);
  scene.fog = new THREE.Fog(0x080a08, 7, 18);

  const camera = new THREE.PerspectiveCamera(42, width / height, 0.01, 4000);
  camera.position.set(3.4, 2.3, 4.8);
  const xrViewerRig = new THREE.Group();
  xrViewerRig.name = "StoryVR environment preview XR reader rig";
  xrViewerRig.add(camera);
  scene.add(xrViewerRig);

  const renderer = new THREE.WebGLRenderer({ antialias: true, alpha: true });
  renderer.setPixelRatio(Math.min(window.devicePixelRatio || 1, 2));
  renderer.setSize(width, height, false);
  renderer.outputColorSpace = THREE.SRGBColorSpace;
  renderer.toneMapping = THREE.ACESFilmicToneMapping;
  renderer.toneMappingExposure = 1;
  renderer.shadowMap.enabled = true;
  renderer.xr.enabled = true;
  renderer.domElement.tabIndex = 0;
  renderer.domElement.className = "topology-viewer-canvas environment-viewer-canvas";
  renderer.domElement.setAttribute("aria-label", "Setting preview canvas");

  const empty = container.querySelector("[data-environment-viewer-empty]");
  const status = container.querySelector("[data-environment-viewer-status]");
  container.prepend(renderer.domElement);

  const controls = new OrbitControls(camera, renderer.domElement);
  controls.enableDamping = true;
  controls.dampingFactor = 0.075;
  controls.target.set(0, 0.85, 0);
  controls.maxPolarAngle = Math.PI / 2 - 0.02;
  configureSpatialEditorMouseControls(controls);

  scene.add(new THREE.HemisphereLight(0xffffff, 0x5b625f, 1.6));
  const keyLight = new THREE.DirectionalLight(0xfff2d8, 2.2);
  keyLight.position.set(4, 7, 5);
  keyLight.castShadow = true;
  scene.add(keyLight);
  const rimLight = new THREE.DirectionalLight(0x9edfd5, 0.9);
  rimLight.position.set(-4, 3, -5);
  scene.add(rimLight);

  const environmentRoot = new THREE.Group();
  environmentRoot.name = "environment-enhancement-root";
  scene.add(environmentRoot);
  const storyRoot = new THREE.Group();
  storyRoot.name = "environment-enhancement-story-root";
  scene.add(storyRoot);
  const neutralFallback = makeEnvironmentNeutralReaderFallback();
  scene.add(neutralFallback);

  const dracoLoader = new DRACOLoader();
  dracoLoader.setDecoderPath(DRACO_DECODER_PATH);
  dracoLoader.setWorkerLimit(2);
  const environmentLoaders = createEnvironmentGltfLoader(renderer);
  const gltfLoader = environmentLoaders.loader;
  gltfLoader.setDRACOLoader(dracoLoader);

  const viewer = {
    componentId: "environment-enhancement",
    scene,
    camera,
    xrViewerRig,
    renderer,
    controls,
    root: storyRoot,
    storyRoot,
    sceneContext,
    readerEntity: null,
    authoringSpatialObjects: new Map(),
    environmentRoot,
    neutralFallback,
    gltfLoader,
    hdrLoader: new HDRLoader(),
    exrLoader: new EXRLoader(),
    textureLoader: new THREE.TextureLoader(),
    dracoLoader,
    ktx2Loader: environmentLoaders.ktx2Loader,
    environmentTexture: null,
    environmentKind: null,
    groundMovementCue: null,
    hasEnvironment: false,
    storyAssetCount: 0,
    storyAssetsPending: 0,
    environmentPending: false,
    disposed: false,
    resizeObserver: null,
    loadToken: 0,
    xrEntryPosePending: false,
    xrEntryWorldPosition: new THREE.Vector3(),
    xrEntryWorldQuaternion: new THREE.Quaternion(),
    xrEntryLocalPosition: new THREE.Vector3(),
    xrEntryLocalQuaternion: new THREE.Quaternion(),
    xrEntryEuler: new THREE.Euler(0, 0, 0, "YXZ"),
  };
  configureAuthoringSpatialCameraViewer(viewer, sceneContext);
  contextViewer = viewer;
  restoreAuthoringSpatialCameraState(viewer);

  viewer.xrSessionStartHandler = () => {
    captureEnvironmentXrEntryPose(viewer);
    controls.enabled = false;
    if (viewer.readerProxy) viewer.readerProxy.visible = false;
  };
  viewer.xrSessionEndHandler = () => {
    viewer.xrEntryPosePending = false;
    viewer.xrViewerRig.position.set(0, 0, 0);
    viewer.xrViewerRig.quaternion.identity();
    viewer.xrViewerRig.updateMatrixWorld(true);
    controls.enabled = true;
    if (viewer.readerProxy) viewer.readerProxy.visible = true;
  };
  renderer.xr.addEventListener("sessionstart", viewer.xrSessionStartHandler);
  renderer.xr.addEventListener("sessionend", viewer.xrSessionEndHandler);

  const xrSlot = document.querySelector("[data-environment-xr-slot]");
  if (xrSlot) {
    const vrButton = VRButton.createButton(renderer);
    vrButton.className = "environment-vr-button";
    vrButton.setAttribute("aria-label", "Enter VR setting preview");
    Object.assign(vrButton.style, {
      position: "static",
      left: "auto",
      right: "auto",
      bottom: "auto",
      width: "auto",
      height: "auto",
      border: "",
      borderRadius: "",
      background: "",
      color: "",
      font: "",
      opacity: "",
      padding: "",
      margin: "",
    });
    xrSlot.append(vrButton);
  }

  viewer.resizeObserver = new ResizeObserver(() => {
    if (viewer.disposed) return;
    const nextWidth = Math.max(container.clientWidth, 360);
    const nextHeight = Math.max(container.clientHeight, 520);
    camera.aspect = nextWidth / nextHeight;
    camera.updateProjectionMatrix();
    renderer.setSize(nextWidth, nextHeight, false);
  });
  viewer.resizeObserver.observe(container);

  applyEnvironmentDraftToViewer(viewer);
  loadEnvironmentPreviewStoryAssets(viewer, status);
  loadEnvironmentPreviewAsset(viewer, environmentManifest(sceneContext), status, empty);
  requestAnimationFrame(() => frameEnvironmentViewer(viewer));

  renderer.setAnimationLoop((_time, xrFrame) => {
    if (viewer.disposed) return;
    alignEnvironmentXrEntryPose(viewer, xrFrame);
    controls.update();
    renderer.render(scene, camera);
  });
}

function captureEnvironmentXrEntryPose(viewer) {
  if (!viewer || viewer.disposed) return;
  viewer.camera.updateWorldMatrix(true, false);
  viewer.camera.getWorldPosition(viewer.xrEntryWorldPosition);
  viewer.camera.getWorldQuaternion(viewer.xrEntryWorldQuaternion);
  if (viewer.readerRig) {
    viewer.readerRig.updateWorldMatrix(true, false);
    viewer.readerRig.getWorldPosition(viewer.xrEntryWorldPosition);
    viewer.readerRig.getWorldQuaternion(viewer.xrEntryWorldQuaternion);
  }
  viewer.xrEntryPosePending = true;
}

function alignEnvironmentXrEntryPose(viewer, xrFrame) {
  if (!viewer?.xrEntryPosePending || !xrFrame) return;
  const referenceSpace = viewer.renderer.xr.getReferenceSpace();
  if (!referenceSpace) return;
  const pose = xrFrame.getViewerPose(referenceSpace);
  if (!pose) return;
  const { position, orientation } = pose.transform;
  viewer.xrEntryLocalPosition.set(position.x, position.y, position.z);
  viewer.xrEntryLocalQuaternion.set(orientation.x, orientation.y, orientation.z, orientation.w);
  const desiredYaw = viewer.xrEntryEuler.setFromQuaternion(viewer.xrEntryWorldQuaternion, "YXZ").y;
  const viewerYaw = viewer.xrEntryEuler.setFromQuaternion(viewer.xrEntryLocalQuaternion, "YXZ").y;
  viewer.xrViewerRig.rotation.set(0, desiredYaw - viewerYaw, 0);
  viewer.xrEntryLocalPosition.applyQuaternion(viewer.xrViewerRig.quaternion);
  viewer.xrViewerRig.position.copy(viewer.xrEntryWorldPosition).sub(viewer.xrEntryLocalPosition);
  viewer.xrViewerRig.updateMatrixWorld(true);
  viewer.xrEntryPosePending = false;
}

function environmentSpatialRelationsPreview() {
  const locked = lockedSpatialRelationsContract();
  if (locked) return { contract: locked, current: true };
  const decision = spatialRelationsDecision();
  const draft = decision?.spatialRelations
    || decision?.option?.spatialRelations
    || state.spatialRelationsDraft
    || null;
  const hasDraft = spatialRelationEntities(draft).length
    || draft?.resolvedByBeat
    || draft?.resolvedByVariant;
  return { contract: hasDraft ? draft : null, current: false };
}

function environmentSpatialRenderableEntities(contract, context, scene = spatialSceneRecordForContext(contract, context)) {
  if (!contract || !context) return [];
  const linkedAssetIds = new Set(uniqueStrings(scene?.linkedAssetIds || []));
  return spatialEditorSceneEntities(contract, context)
    .filter((entity) => ["glb", "image-plane"].includes(spatialEntityType(entity)))
    .filter((entity) => !linkedAssetIds.size || linkedAssetIds.has(entity.assetId));
}

function environmentSpatialScenePreview(context) {
  const relations = environmentSpatialRelationsPreview();
  const scene = spatialSceneRecordForContext(relations.contract, context);
  const entities = environmentSpatialRenderableEntities(relations.contract, context, scene);
  const usesSourceFallback = !scene && !entities.length;
  return {
    ...relations,
    scene,
    entities,
    state: usesSourceFallback ? "source-linked fallback" : relations.current ? "saved" : "draft",
  };
}

function environmentSourceLinkedFallbackAssetIds(context) {
  const beat = spatialSceneBeat(context);
  return uniqueStrings(beat?.linkedAssetIds || beatAssetIds(beat)).filter((assetId) => {
    const asset = findAssetById(assetId);
    if (isImageAsset(asset)) return Boolean(assetPreviewSrc(asset));
    if (isModelAsset(asset)) return Boolean(assetLoadSrc(asset));
    return false;
  });
}

function environmentPreviewStoryAssets() {
  const context = activeEnvironmentSceneContext();
  if (!state.data || !context) return [];
  const spatialPreview = environmentSpatialScenePreview(context);
  if (spatialPreview.state !== "source-linked fallback") return spatialPreview.entities.flatMap((entity) => {
    const asset = findAssetById(entity.assetId);
    const src = spatialEntityType(entity) === "image-plane" ? assetPreviewSrc(asset) : assetLoadSrc(asset);
    return asset && src ? [{ asset, entity, src, kind: spatialEntityType(entity) }] : [];
  });
  return environmentSourceLinkedFallbackAssetIds(context).flatMap((assetId) => {
    const asset = findAssetById(assetId);
    const kind = isImageAsset(asset) ? "image-plane" : isModelAsset(asset) ? "glb" : null;
    const src = kind === "image-plane" ? assetPreviewSrc(asset) : kind === "glb" ? assetLoadSrc(asset) : null;
    return asset && src && kind ? [{ asset, entity: null, src, kind }] : [];
  });
}

function loadEnvironmentPreviewStoryAssets(viewer, status) {
  const entries = environmentPreviewStoryAssets();
  const context = activeEnvironmentSceneContext();
  const spatialPreview = environmentSpatialScenePreview(context);
  const spatialContract = spatialPreview.contract;
  const spatialScene = spatialPreview.scene;
  const spatialEntities = spatialEditorSceneEntities(spatialContract, context);
  const topologyKind = spatialScene?.topology?.kind || spatialScene?.topologyKind || "single";
  const readerEntity = spatialEntities.find((entity) => spatialEntityType(entity) === "reader") || null;
  viewer.spatialScene = spatialScene;
  viewer.spatialSceneCurrent = spatialPreview.state === "saved";
  viewer.spatialSceneState = spatialPreview.state;
  viewer.sceneContext = context;
  viewer.beat = spatialSceneBeat(context);
  viewer.topologyKind = topologyKind;
  viewer.readerEntity = readerEntity;
  if (readerEntity) {
    const readerLayer = createSpatialReaderRig(viewer.storyRoot, readerEntity);
    viewer.readerRig = readerLayer.rig;
    viewer.readerProxy = readerLayer.proxy;
  }
  viewer.storyAssetCount = entries.length;
  viewer.storyAssetsPending = entries.length;
  if (!entries.length) {
    updateEnvironmentViewerStatus(viewer, status);
    return;
  }
  const finish = (loaded) => {
    if (viewer.disposed) return;
    viewer.storyAssetsPending -= 1;
    if (!loaded) viewer.storyAssetFailures = (viewer.storyAssetFailures || 0) + 1;
    updateEnvironmentViewerStatus(viewer, status);
    if (viewer.storyAssetsPending <= 0 && !viewer.environmentPending) frameEnvironmentViewer(viewer);
  };
  entries.forEach((entry, index) => {
    const wrapper = new THREE.Group();
    wrapper.name = `Spatial Relations preview asset · ${entry.asset.id}`;
    viewer.storyRoot.add(wrapper);
    viewer.authoringSpatialObjects?.set(entry.entity?.id || `environment:${entry.asset.id}:${index}`, wrapper);
    if (entry.entity) applySpatialEntityTransformToObject(viewer, entry.entity, wrapper);
    else wrapper.position.copy(spatialTopologyAssetPose({ topologyKind }, index, entries.length).position);
    if (entry.kind === "image-plane") {
      new THREE.TextureLoader().load(entry.src, (texture) => {
        if (viewer.disposed) {
          texture.dispose();
          return;
        }
        texture.colorSpace = THREE.SRGBColorSpace;
        const actualAspect = texture.image?.width && texture.image?.height ? texture.image.width / texture.image.height : null;
        const aspect = Number(entry.entity?.image?.aspectRatio) || actualAspect || 16 / 9;
        const imageWidth = Math.max(0.1, Number(entry.entity?.image?.width) || 1.6);
        const imageHeight = Math.max(0.1, Number(entry.entity?.image?.height) || imageWidth / Math.max(aspect, 0.1));
        wrapper.add(new THREE.Mesh(
          new THREE.PlaneGeometry(imageWidth, imageHeight),
          new THREE.MeshBasicMaterial({ map: texture, transparent: true, side: THREE.DoubleSide, toneMapped: false }),
        ));
        finish(true);
      }, undefined, () => finish(false));
      return;
    }
    createGltfLoader().load(entry.src, (gltf) => {
      if (viewer.disposed) {
        disposeObject(gltf.scene);
        return;
      }
      applySpatialLoaderTransformPolicy(gltf.scene, entry.entity);
      if (entry.entity?.preserveSourceGeometry !== true) {
        const pose = spatialTopologyAssetPose({ topologyKind }, index, entries.length);
        normalizeSpatialRuntimeObject(
          gltf.scene,
          pose.targetSize,
          spatialEntityVerticalAlignment(entry.entity),
        );
      }
      wrapper.add(gltf.scene);
      finish(true);
    }, undefined, () => finish(false));
  });
}

async function loadEnvironmentPreviewAsset(viewer, manifest, status, empty) {
  const asset = manifest.asset;
  const localUrl = String(asset?.localUrl || "").trim();
  if (!asset || !localUrl) {
    updateEnvironmentViewerStatus(viewer, status);
    if (empty) empty.hidden = Boolean(viewer.storyAssetCount);
    return;
  }
  const mediaType = environmentNormalizeMediaType(asset.mediaType || asset.format, localUrl);
  const token = ++viewer.loadToken;
  viewer.environmentPending = true;
  updateEnvironmentViewerStatus(viewer, status);
  try {
    const url = new URL(localUrl, window.location.href).href;
    if (ENVIRONMENT_MODEL_MEDIA_TYPES.has(mediaType)) {
      const gltf = await environmentLoadWithLoader(viewer.gltfLoader, url);
      if (viewer.disposed || token !== viewer.loadToken) {
        disposeObject(gltf.scene);
        return;
      }
      viewer.environmentRoot.add(gltf.scene);
      viewer.environmentKind = "model";
      viewer.hasEnvironment = true;
    } else if (
      ENVIRONMENT_HDR_MEDIA_TYPES.has(mediaType)
      || ENVIRONMENT_EXR_MEDIA_TYPES.has(mediaType)
      || ENVIRONMENT_PNG_MEDIA_TYPES.has(mediaType)
    ) {
      const loader = ENVIRONMENT_PNG_MEDIA_TYPES.has(mediaType)
        ? viewer.textureLoader
        : ENVIRONMENT_EXR_MEDIA_TYPES.has(mediaType) ? viewer.exrLoader : viewer.hdrLoader;
      const texture = await environmentLoadWithLoader(loader, url);
      if (viewer.disposed || token !== viewer.loadToken) {
        texture.dispose();
        return;
      }
      texture.mapping = THREE.EquirectangularReflectionMapping;
      if (ENVIRONMENT_PNG_MEDIA_TYPES.has(mediaType)) texture.colorSpace = THREE.SRGBColorSpace;
      viewer.environmentTexture = texture;
      viewer.environmentKind = "panorama";
      viewer.hasEnvironment = true;
    } else {
      throw new Error(`Unsupported setting media type: ${mediaType || "unknown"}`);
    }
    viewer.environmentPending = false;
    if (viewer.neutralFallback) viewer.neutralFallback.visible = false;
    applyEnvironmentDraftToViewer(viewer);
    if (empty) empty.hidden = true;
    updateEnvironmentViewerStatus(viewer, status);
    frameEnvironmentViewer(viewer);
  } catch (error) {
    if (viewer.disposed || token !== viewer.loadToken) return;
    viewer.environmentPending = false;
    viewer.environmentError = error.message || "Setting asset loading failed.";
    if (viewer.neutralFallback) viewer.neutralFallback.visible = true;
    updateEnvironmentViewerStatus(viewer, status);
    if (empty) {
      empty.hidden = false;
      empty.querySelector("strong").textContent = "Could not load setting";
      empty.querySelector("span").textContent = viewer.environmentError;
    }
  }
}

function environmentLoadWithLoader(loader, url) {
  return new Promise((resolve, reject) => {
    loader.load(url, resolve, undefined, (error) => reject(error instanceof Error ? error : new Error("Asset loading failed.")));
  });
}

function makeEnvironmentNeutralReaderFallback() {
  const root = new THREE.Group();
  root.name = "StoryVR neutral reader fallback";
  const hideGroundCircles = finalReviewTuningDirectives().hideGroundCircles;
  const floor = new THREE.Mesh(
    hideGroundCircles ? new THREE.PlaneGeometry(11, 11) : new THREE.CircleGeometry(6.5, 96),
    new THREE.MeshStandardMaterial({ color: 0x151a15, roughness: 0.92, metalness: 0.02 }),
  );
  floor.rotation.x = -Math.PI / 2;
  floor.receiveShadow = true;
  root.add(floor);
  const grid = new THREE.GridHelper(11, 22, 0x2a3a33, 0x18221e);
  grid.position.y = 0.01;
  root.add(grid);
  return root;
}

function updateEnvironmentViewerStatus(viewer = contextViewer, status = document.querySelector("[data-environment-viewer-status]")) {
  if (!viewer || !status) return;
  const spatialSceneLabel = viewer.spatialSceneState === "saved"
    ? "saved scene"
    : viewer.spatialSceneState === "draft" ? "Unsaved object-placement scene" : "source-linked fallback scene";
  if (viewer.environmentError) {
    status.textContent = `Setting failed to load: ${viewer.environmentError}`;
    status.classList.add("error");
    return;
  }
  const pending = viewer.storyAssetsPending + (viewer.environmentPending ? 1 : 0);
  if (pending > 0) {
    status.textContent = `Loading ${pending} preview asset${pending === 1 ? "" : "s"}…`;
    return;
  }
  if (viewer.storyAssetFailures) {
    status.textContent = `Preview ready with ${viewer.storyAssetFailures} ${spatialSceneLabel} asset issue${viewer.storyAssetFailures === 1 ? "" : "s"}.`;
    return;
  }
  if (viewer.hasEnvironment) status.remove();
  else if (environmentEnhancementSkipped()) status.textContent = viewer.storyAssetCount
    ? `This ${spatialSceneLabel} is loaded with StoryVR's neutral reader setting.`
    : "Using StoryVR's standard neutral scene with no added setting.";
  else status.textContent = viewer.storyAssetCount ? `This ${spatialSceneLabel} is loaded. Generate a setting to surround it.` : "Generate a setting to begin the preview.";
}

function applyEnvironmentDraftToViewer(viewer = contextViewer) {
  if (!viewer || viewer.disposed || viewer.componentId !== "environment-enhancement") return;
  const draft = environmentDraft();
  syncEnvironmentGroundMovementCue(
    viewer,
    environmentEnhancementSkipped() ? null : draft.movementCue,
    draft.transform.rotationY,
  );
  viewer.environmentRoot.position.fromArray(draft.transform.position);
  viewer.environmentRoot.rotation.set(0, draft.transform.rotationY, 0);
  viewer.environmentRoot.scale.setScalar(draft.transform.scale);
  viewer.environmentRoot.updateMatrixWorld(true);
  if (!viewer.hasEnvironment) {
    if (viewer.neutralFallback) viewer.neutralFallback.visible = true;
    viewer.renderer.toneMappingExposure = 1;
    viewer.scene.environment = null;
    viewer.scene.background = new THREE.Color(0x080a08);
    viewer.scene.fog = null;
    viewer.renderer.setClearColor(0x080a08, 1);
    return;
  }
  if (viewer.neutralFallback) viewer.neutralFallback.visible = false;
  viewer.renderer.toneMappingExposure = draft.rendering.exposure;
  viewer.scene.environment = viewer.environmentTexture;
  viewer.scene.environmentRotation?.set?.(0, draft.transform.rotationY, 0);
  viewer.scene.backgroundRotation?.set?.(0, draft.transform.rotationY, 0);
  viewer.scene.fog = draft.rendering.fogDensity > 0
    ? new THREE.FogExp2(new THREE.Color(draft.rendering.fogColor), draft.rendering.fogDensity)
    : null;
  const backgroundMode = environmentNormalizeBackground(draft.rendering.backgroundMode);
  if (backgroundMode === "asset" && viewer.environmentTexture) {
    viewer.scene.background = viewer.environmentTexture;
    viewer.renderer.setClearAlpha(1);
  } else if (backgroundMode === "transparent") {
    viewer.scene.background = null;
    viewer.renderer.setClearColor(0x000000, 0);
  } else {
    viewer.scene.background = new THREE.Color(draft.rendering.fogColor);
    viewer.renderer.setClearAlpha(1);
  }
}

function syncEnvironmentGroundMovementCue(viewer, movementCue, rotationY = 0) {
  if (!viewer || viewer.disposed || viewer.componentId !== "environment-enhancement") return;
  const normalized = normalizeGroundMovementCue({ ...movementCue, rotationY });
  if (!normalized.enabled) {
    viewer.groundMovementCue?.dispose?.();
    viewer.groundMovementCue = null;
    return;
  }
  const textureUrl = environmentGroundTextureUrl(normalized.texture);
  if (viewer.groundMovementCue) {
    viewer.groundMovementCue.update(normalized, { textureUrl });
    return;
  }
  viewer.groundMovementCue = createGroundMovementCue(normalized, {
    renderer: viewer.renderer,
    textureUrl,
  });
  viewer.scene.add(viewer.groundMovementCue.mesh);
}

function environmentGroundTextureUrl(texture) {
  if (!texture || typeof texture !== "object") return null;
  return String(texture.localUrl || texture.localPath || "").trim() || null;
}

function frameEnvironmentViewer(viewer = contextViewer, { force = false } = {}) {
  if (!viewer || viewer.disposed || viewer.componentId !== "environment-enhancement") return false;
  if (!force && viewer.storyAssetsPending > 0) return false;
  return fitAuthoringSpatialCameraOnLoad(viewer, { force });
}

function environmentEnhancementContractForBeat(contract, beatId) {
  if (!contract || typeof contract !== "object" || Array.isArray(contract)) return null;
  if (contract.schemaVersion !== ENVIRONMENT_ENHANCEMENT_ASSIGNMENTS_SCHEMA_VERSION) return contract;
  const assignments = contract.assignmentsByBeat && typeof contract.assignmentsByBeat === "object"
    ? contract.assignmentsByBeat
    : {};
  const normalizedBeatId = String(beatId || "").trim();
  if (normalizedBeatId && Object.prototype.hasOwnProperty.call(assignments, normalizedBeatId)) {
    const assignment = assignments[normalizedBeatId];
    return assignment && typeof assignment === "object" ? assignment : null;
  }
  return contract.defaultEnvironment && typeof contract.defaultEnvironment === "object"
    ? contract.defaultEnvironment
    : null;
}

function lockedEnvironmentPreviewContract(viewer) {
  const decision = state.data?.decisions?.["environment-enhancement"];
  const decisionBundle = checkpointIsCurrent("environment-enhancement") ? decision?.option?.environmentEnhancement : null;
  const beatId = String(viewer?.sceneContext?.beatId || viewer?.beat?.id || "").trim();
  const manifest = environmentManifest(beatId ? spatialSceneContext(beatId) : null);
  const decisionContract = environmentEnhancementContractForBeat(decisionBundle, beatId);
  if (decisionBundle && !decisionContract) return null;
  if (!decisionContract && !manifest.current) return null;
  const contract = decisionContract || manifest;
  const asset = contract.asset || manifest.asset
    ? { ...(manifest.asset || {}), ...(contract.asset || {}) }
    : null;
  return {
    ...manifest,
    ...contract,
    asset,
    transform: contract.transform || manifest.transform,
    rendering: contract.rendering || manifest.rendering,
  };
}

function applyNeutralEnvironmentFallbackToViewer(viewer) {
  if (!viewer?.scene || !viewer?.renderer) return false;
  viewer.lockedEnvironmentActive = false;
  viewer.scene.environment = null;
  viewer.scene.background = new THREE.Color(0x080a08);
  viewer.scene.fog = null;
  viewer.scene.environmentRotation?.set?.(0, 0, 0);
  viewer.scene.backgroundRotation?.set?.(0, 0, 0);
  viewer.renderer.toneMappingExposure = 1;
  viewer.renderer.setClearColor(0x080a08, 1);
  return true;
}

function authoredEnvironmentPolicyExists() {
  const option = state.data?.decisions?.["environment-enhancement"]?.option;
  return Boolean(option && typeof option === "object");
}

function attachLockedEnvironmentToViewer(viewer) {
  if (!applyNeutralEnvironmentFallbackToViewer(viewer)) return;
  viewer.authoredEnvironmentPolicyActive = authoredEnvironmentPolicyExists();
  const contract = lockedEnvironmentPreviewContract(viewer);
  const asset = contract?.asset;
  const localUrl = String(asset?.localUrl || "").trim();
  if (!asset || !localUrl) return;
  viewer.lockedEnvironmentActive = true;

  const transform = environmentDraftFromManifest(contract).transform;
  const rendering = environmentDraftFromManifest(contract).rendering;
  const root = new THREE.Group();
  root.name = "locked-environment-enhancement";
  root.position.fromArray(transform.position);
  root.rotation.set(0, transform.rotationY, 0);
  root.scale.setScalar(transform.scale);
  viewer.scene.add(root);
  viewer.lockedEnvironmentRoot = root;
  viewer.renderer.toneMapping = THREE.ACESFilmicToneMapping;
  viewer.renderer.toneMappingExposure = rendering.exposure;
  viewer.scene.environmentRotation?.set?.(0, transform.rotationY, 0);
  viewer.scene.backgroundRotation?.set?.(0, transform.rotationY, 0);
  viewer.scene.fog = rendering.fogDensity > 0
    ? new THREE.FogExp2(new THREE.Color(rendering.fogColor), rendering.fogDensity)
    : null;
  if (rendering.backgroundMode === "fog-color") viewer.scene.background = new THREE.Color(rendering.fogColor);
  if (rendering.backgroundMode === "transparent") {
    viewer.scene.background = null;
    viewer.renderer.setClearColor(0x000000, 0);
  }

  const mediaType = environmentNormalizeMediaType(asset.mediaType || asset.format, localUrl);
  const absoluteUrl = new URL(localUrl, window.location.href).href;
  if (ENVIRONMENT_MODEL_MEDIA_TYPES.has(mediaType)) {
    const environmentLoaders = createEnvironmentGltfLoader(viewer.renderer);
    const loader = environmentLoaders.loader;
    viewer.lockedEnvironmentKtx2Loader = environmentLoaders.ktx2Loader;
    loader.load(
      absoluteUrl,
      (gltf) => {
        if (viewer.disposed) {
          disposeObject(gltf.scene);
          return;
        }
        root.add(gltf.scene);
        expandViewerCameraForEnvironment(viewer, root);
      },
      undefined,
      (error) => {
        viewer.lockedEnvironmentError = error?.message || "Setting could not be loaded.";
      },
    );
    return;
  }

  if (
    !ENVIRONMENT_HDR_MEDIA_TYPES.has(mediaType)
    && !ENVIRONMENT_EXR_MEDIA_TYPES.has(mediaType)
    && !ENVIRONMENT_PNG_MEDIA_TYPES.has(mediaType)
  ) {
    viewer.lockedEnvironmentError = `Unsupported setting media type: ${mediaType || "unknown"}`;
    return;
  }
  const loader = ENVIRONMENT_PNG_MEDIA_TYPES.has(mediaType)
    ? new THREE.TextureLoader()
    : ENVIRONMENT_EXR_MEDIA_TYPES.has(mediaType) ? new EXRLoader() : new HDRLoader();
  viewer.lockedEnvironmentLoader = loader;
  loader.load(
    absoluteUrl,
    (texture) => {
      if (viewer.disposed) {
        texture.dispose();
        return;
      }
      texture.mapping = THREE.EquirectangularReflectionMapping;
      if (ENVIRONMENT_PNG_MEDIA_TYPES.has(mediaType)) texture.colorSpace = THREE.SRGBColorSpace;
      viewer.lockedEnvironmentTexture = texture;
      viewer.scene.environment = texture;
      if (rendering.backgroundMode === "asset") viewer.scene.background = texture;
      syncLockedEnvironmentGroundMovementCue(viewer, contract, transform.rotationY);
    },
    undefined,
    (error) => {
      viewer.lockedEnvironmentError = error?.message || "360° setting could not be loaded.";
    },
  );
}

function syncLockedEnvironmentGroundMovementCue(viewer, contract, rotationY = 0) {
  if (!viewer?.scene || viewer.disposed) return;
  const movementCue = normalizeGroundMovementCue({
    ...contract?.movementCue,
    rotationY,
  });
  if (!movementCue.enabled) {
    viewer.groundMovementCue?.dispose?.();
    viewer.groundMovementCue = null;
    return;
  }
  const textureUrl = environmentGroundTextureUrl(movementCue.texture);
  try {
    if (viewer.groundMovementCue) {
      viewer.groundMovementCue.update(movementCue, { textureUrl });
      return;
    }
    viewer.groundMovementCue = createGroundMovementCue(movementCue, {
      renderer: viewer.renderer,
      textureUrl,
    });
    viewer.scene.add(viewer.groundMovementCue.mesh);
  } catch (error) {
    viewer.lockedEnvironmentGroundError = error?.message || "Matching ground could not be loaded.";
  }
}

function disposeLockedEnvironmentFromViewer(viewer) {
  viewer?.groundMovementCue?.dispose?.();
  if (viewer) viewer.groundMovementCue = null;
  viewer?.lockedEnvironmentTexture?.dispose?.();
  viewer.lockedEnvironmentTexture = null;
  viewer.lockedEnvironmentLoader?.dispose?.();
  viewer.lockedEnvironmentLoader = null;
  viewer?.lockedEnvironmentKtx2Loader?.dispose?.();
  viewer.lockedEnvironmentKtx2Loader = null;
}

function expandViewerCameraForEnvironment(viewer, root) {
  root.updateMatrixWorld(true);
  const box = new THREE.Box3().setFromObject(root);
  if (box.isEmpty()) return;
  const center = box.getCenter(new THREE.Vector3());
  const size = box.getSize(new THREE.Vector3());
  const radius = Math.max(size.x, size.y, size.z, 1);
  const requiredFar = viewer.camera.position.distanceTo(center) + radius * 3;
  if (requiredFar > viewer.camera.far) {
    viewer.camera.far = Math.max(requiredFar, 500);
    viewer.camera.updateProjectionMatrix();
  }
}

function initializeLegacyContextLayeringViewer(active) {
  if (active?.id !== "environment-enhancement") return;
  const container = document.querySelector("[data-context-viewer]");
  if (!container) return;

  const component = componentById("environment-enhancement");
  const proposal = selectedTopologyProposal(component, state.data.proposals[component.id], state.data.decisions[component.id]);
  if (!proposal) return;

  const kind = inferContextLayerKind(proposal);
  const layers = cumulativePreviewLayersForComponent("environment-enhancement", { contextKind: kind });
  const layoutKind = layers.topologyKind;
  const dynamicKind = layers.dynamicKind;
  const transitionKind = layers.transitionKind;
  const beats = contextPreviewBeats(proposal);
  const beatIndex = clampContextBeatIndex(beats);
  const beat = beats[beatIndex];
  const cumulativeContext = cumulativeSingleAnchorContext(beats, beatIndex);
  const allAssetLinks = contextSceneAssetLinks(proposal, beats);
  const activeAssetIds = new Set(beat?.linkedAssetIds || []);
  const objectOnlyLinks = allAssetLinks.filter((assetLink) => activeAssetIds.has(assetLink.assetId));
  const assetLinks = cumulativeContext
    ? cumulativeContext.sequence.steps
    : (kind === "object" ? objectOnlyLinks : allAssetLinks);
  const effectiveActiveAssetIds = new Set(cumulativeContext?.active?.assetId ? [cumulativeContext.active.assetId] : activeAssetIds);
  const activeAssetIndex = cumulativeContext
    ? cumulativeContext.activeIndex
    : Math.max(assetLinks.findIndex((assetLink) => effectiveActiveAssetIds.has(assetLink.assetId)), 0);
  const activePosition = contextLayerActivePosition(cumulativeContext, activeAssetIndex, Math.max(assetLinks.length, 1), layoutKind);
  const width = Math.max(container.clientWidth, 360);
  const height = Math.max(container.clientHeight, 460);
  const scene = new THREE.Scene();
  scene.background = new THREE.Color(0xf8f7ec);

  const camera = new THREE.PerspectiveCamera(42, width / height, 0.02, 1000);
  camera.position.set(4.3, 3.2, 5.4);

  const renderer = new THREE.WebGLRenderer({ antialias: true, alpha: true });
  renderer.setPixelRatio(Math.min(window.devicePixelRatio || 1, 2));
  renderer.setSize(width, height);
  renderer.outputColorSpace = THREE.SRGBColorSpace;
  renderer.domElement.tabIndex = 0;
  renderer.domElement.className = "topology-viewer-canvas";

  const status = document.createElement("div");
  status.className = "topology-viewer-status overlay";
  status.textContent = assetLinks.length ? `Loading ${assetLinks.length} context assets...` : "No linked assets available for context preview.";
  container.replaceChildren(renderer.domElement, status);
  const metadataOverlay = addPreviewMetadataOverlay(container, previewMetadataEntries({
    componentId: "environment-enhancement",
    layers,
    activeLink: cumulativeContext?.active || assetLinks[activeAssetIndex],
    currentValue: contextLayerKindLabel(kind),
    beat,
  }));

  const controls = new OrbitControls(camera, renderer.domElement);
  controls.enableDamping = true;
  controls.dampingFactor = 0.08;
  controls.target.set(0, 0.5, 0);
  configureSpatialEditorMouseControls(controls);

  scene.add(new THREE.HemisphereLight(0xffffff, 0x6f7f78, 2.35));
  const keyLight = new THREE.DirectionalLight(0xffffff, 3.1);
  keyLight.position.set(4, 7, 5);
  scene.add(keyLight);
  const rimLight = new THREE.DirectionalLight(0x9edfd5, 1.1);
  rimLight.position.set(-5, 3, -4);
  scene.add(rimLight);

  const root = new THREE.Group();
  scene.add(root);
  const contextStage = null;
  const inheritedDynamicBeat = dynamicKind ? {
    ...beat,
    title: `Geometry: ${dynamicGeometryKindLabel(dynamicKind)}`,
  } : null;

  const viewer = {
    scene,
    camera,
    renderer,
    controls,
    root,
    animationId: null,
    resizeHandler: null,
    keyDownHandler: null,
    keyUpHandler: null,
    pointerDownHandler: null,
    disposed: false,
    focused: false,
    keys: new Set(),
    lastFrameAt: performance.now(),
    elapsed: 0,
    kind,
    layers,
    layoutKind,
    topologyKind: layoutKind,
    geometryKind: dynamicKind,
    transitionKind,
    componentId: "environment-enhancement",
    suppressSceneLabels: true,
    metadataOverlay,
    assetLinks,
    cumulativeContext,
    contextStage,
    activeSwapIndex: cumulativeContext?.activeIndex || 0,
    swapGroups: [],
    swapDuplicates: [],
    swapReady: false,
    duplicateCount: topologySwapDuplicateCount(state.data?.decisions?.["asset-topology"]?.option),
    dynamicObjects: [],
    effects: dynamicKind ? addDynamicEffectOverlays(root, dynamicKind, activePosition, inheritedDynamicBeat) : null,
    contextLayers: addContextLayerOverlays(root, kind, activePosition, beat, proposal),
    descriptionCues: null,
  };
  contextViewer = viewer;
  const restoredCameraState = restoredPreviewCameraState(viewer, state.contextViewerCameraState);
  const canRestoreCameraState = shouldRestorePreviewCameraState(viewer, restoredCameraState);
  if (canRestoreCameraState) applyContextViewerCameraState(viewer, restoredCameraState);

  container.addEventListener("pointerdown", () => {
    viewer.focused = true;
    container.classList.add("focused");
    renderer.domElement.focus();
  });
  renderer.domElement.addEventListener("blur", () => {
    viewer.focused = false;
    viewer.keys.clear();
    container.classList.remove("focused");
  });

  viewer.pointerDownHandler = (event) => {
    if (!container.contains(event.target)) {
      viewer.focused = false;
      viewer.keys.clear();
      container.classList.remove("focused");
    }
  };
  viewer.keyDownHandler = (event) => {
    const key = event.key.toLowerCase();
    if (!viewer.focused || !["w", "a", "s", "d"].includes(key)) return;
    event.preventDefault();
    viewer.keys.add(key);
  };
  viewer.keyUpHandler = (event) => {
    const key = event.key.toLowerCase();
    if (!["w", "a", "s", "d"].includes(key)) return;
    viewer.keys.delete(key);
  };
  viewer.resizeHandler = () => {
    if (viewer.disposed) return;
    const nextWidth = Math.max(container.clientWidth, 360);
    const nextHeight = Math.max(container.clientHeight, 520);
    camera.aspect = nextWidth / nextHeight;
    camera.updateProjectionMatrix();
    renderer.setSize(nextWidth, nextHeight);
  };
  document.addEventListener("pointerdown", viewer.pointerDownHandler);
  window.addEventListener("keydown", viewer.keyDownHandler);
  window.addEventListener("keyup", viewer.keyUpHandler);
  window.addEventListener("resize", viewer.resizeHandler);

  if (!assetLinks.length) {
    if (canRestoreCameraState) {
      applyContextViewerCameraState(viewer, restoredCameraState);
    } else {
      fitInheritedTopologyPreviewCamera(viewer, root);
    }
  } else if (cumulativeContext) {
    let pending = assetLinks.length;
    let failed = 0;
    const finishAsset = (ok) => {
      pending -= 1;
      if (!ok) failed += 1;
      if (viewer.disposed) return;
      if (canRestoreCameraState) {
        applyContextViewerCameraState(viewer, restoredCameraState);
      } else {
        fitInheritedTopologyPreviewCamera(viewer, root);
      }
      if (pending > 0) {
        status.textContent = `Loading ${pending} more cumulative context assets...`;
      } else {
        viewer.swapReady = true;
        if (failed) {
          status.textContent = `Loaded cumulative context with ${failed} asset issue${failed === 1 ? "" : "s"}.`;
          return;
        }
        status.remove();
      }
    };
    assetLinks.forEach((assetLink, index) => {
      loadTopologySwapAsset(viewer, assetLink, index, finishAsset);
    });
  } else {
    let pending = assetLinks.length;
    let failed = 0;
    const finishAsset = (ok) => {
      pending -= 1;
      if (!ok) failed += 1;
      if (viewer.disposed) return;
      if (canRestoreCameraState) {
        applyContextViewerCameraState(viewer, restoredCameraState);
      } else {
        fitInheritedTopologyPreviewCamera(viewer, root);
      }
      if (pending > 0) {
        status.textContent = `Loading ${pending} more context assets...`;
      } else if (failed) {
        status.textContent = `Loaded with ${failed} context preview issue${failed === 1 ? "" : "s"}.`;
      } else {
        status.remove();
      }
    };
    assetLinks.forEach((assetLink, index) => {
      loadDynamicAsset(viewer, assetLink, index, assetLinks.length, activeAssetIds.has(assetLink.assetId) || index === activeAssetIndex, finishAsset);
    });
  }

  const animate = (time) => {
    if (viewer.disposed) return;
    const delta = Math.min((time - viewer.lastFrameAt) / 1000, 0.05);
    viewer.lastFrameAt = time;
    viewer.elapsed += delta;
    updateTopologyKeyboardMovement(viewer, delta);
    if (animateNarrativeSingleAnchorViewer(viewer, delta)) return;
    animateContextLayering(viewer);
    controls.update();
    renderer.render(scene, camera);
    viewer.animationId = requestAnimationFrame(animate);
  };
  viewer.animationId = requestAnimationFrame(animate);
}

function initializeInteractionControlViewer(active) {
  if (active?.id !== "interaction-control") return;
  const container = document.querySelector("[data-interaction-viewer]");
  if (!container) return;
  const sceneContext = activeInteractionSceneContext();
  if (!sceneContext) return;

  const baseProposal = selectedInteractionControlBase();
  const editorContext = interactionOptionEditorContext(baseProposal, sceneContext);
  const boundaryContext = editorContext?.boundaryContext || interactionBoundaryContext(baseProposal, sceneContext);
  if (!editorContext?.sceneContext || !boundaryContext.beats.length) return;
  const proposal = interactionProposalForBoundary(baseProposal, editorContext.boundary) || { optionId: editorContext.targetId, label: interactionControlKindLabel(editorContext.kind) };
  const beats = boundaryContext.beats;
  const beat = interactionPreviewBeatForSceneContext(baseProposal, editorContext.sceneContext) || editorContext.beat;
  const beatIndex = Math.max(0, beats.findIndex((candidate) => candidate.id === beat?.id));
  const kind = editorContext.kind;
  const selectedKind = kind;
  const inheritedLayers = cumulativePreviewLayersForComponent("interaction-control", { interactionKind: kind || "unassigned" });
  const spatialContract = lockedSpatialRelationsContract();
  const spatialScene = spatialSceneRecordForContext(spatialContract, editorContext.sceneContext);
  const spatialEntities = spatialSceneEntities(spatialContract, editorContext.sceneContext);
  const readerEntity = spatialEntities.find((entity) => spatialEntityType(entity) === "reader") || null;
  const layoutKind = spatialScene?.topology?.kind || spatialScene?.topologyKind || inheritedLayers.topologyKind || "single";
  const layers = cumulativePreviewLayersForComponent("interaction-control", {
    interactionKind: kind || "unassigned",
    topologyKind: layoutKind,
  });
  const textKind = layers.textKind;
  const dynamicKind = layers.dynamicKind;
  const contextKind = layers.contextKind;
  const cumulativeContext = null;
  const assetEntities = spatialEntities.filter((entity) => ["glb", "image-plane"].includes(spatialEntityType(entity)));
  const assetLinks = assetEntities.length
    ? assetEntities.map((entity) => ({
        assetId: entity.assetId,
        entityId: entity.id,
        kind: spatialEntityType(entity),
        role: entity.role || "Scene asset",
      }))
    : interactionSceneAssetLinks(proposal, [beat]);
  const upstreamBeatState = resolveSpatialUpstreamBeatState(beats, beatIndex, null);
  const usesInheritedSourcePlayback = assetLinks.some((assetLink) => Boolean(sourcePlaybackAssetForId(assetLink.assetId)));
  const width = Math.max(container.clientWidth, 360);
  const height = Math.max(container.clientHeight, 520);
  const scene = new THREE.Scene();
  scene.background = new THREE.Color(0xf8f7ec);

  const camera = new THREE.PerspectiveCamera(42, width / height, 0.02, 1000);
  camera.position.set(3.4, 2.3, 4.8);

  const renderer = new THREE.WebGLRenderer({ antialias: true, alpha: true });
  renderer.setPixelRatio(Math.min(window.devicePixelRatio || 1, 2));
  renderer.setSize(width, height);
  renderer.outputColorSpace = THREE.SRGBColorSpace;
  renderer.domElement.tabIndex = 0;
  renderer.domElement.className = "topology-viewer-canvas text-viewer-canvas spatial-viewer-canvas interaction-viewer-canvas";

  const status = document.createElement("div");
  status.className = "topology-viewer-status overlay";
  status.textContent = assetLinks.length ? `Loading ${assetLinks.length} authored scene assets...` : "No linked assets; showing the authored neutral scene.";
  container.replaceChildren(renderer.domElement, status);

  const controls = new OrbitControls(camera, renderer.domElement);
  controls.enableDamping = true;
  controls.dampingFactor = 0.08;
  controls.maxPolarAngle = Math.PI / 2 - 0.02;
  controls.target.set(0, 0.85, 0);
  configureSpatialEditorMouseControls(controls);

  scene.add(new THREE.HemisphereLight(0xffffff, 0x6f7f78, 2.35));
  const keyLight = new THREE.DirectionalLight(0xffffff, 3.2);
  keyLight.position.set(4, 7, 5);
  scene.add(keyLight);
  const rimLight = new THREE.DirectionalLight(0x9edfd5, 1.15);
  rimLight.position.set(-5, 3, -4);
  scene.add(rimLight);

  const root = new THREE.Group();
  scene.add(root);
  scene.add(makeSpatialEditorFloorGuide(layoutKind));
  const readerEditorLayer = createSpatialReaderRig(root, readerEntity);
  const spatialReaderHands = addInteractionSpatialReaderHands(readerEditorLayer.rig, beat);

  const assetPositions = new Map();
  assetLinks.forEach((assetLink, index) => {
    const position = cumulativeContext
      ? dynamicAssetPosition3d(index, Math.max(assetLinks.length, 1), layoutKind, index === cumulativeContext.activeIndex)
      : spatialTopologyAssetPose({
        topologyKind: layoutKind,
      }, index, Math.max(assetLinks.length, 1)).position;
    assetPositions.set(assetLink.assetId, position);
  });
  const activeAssetId = cumulativeContext?.active?.assetId
    || beat?.linkedAssetIds?.find((assetId) => assetPositions.has(assetId))
    || beat?.linkedAssetIds?.[0]
    || null;
  const activePosition = activeAssetId && assetPositions.has(activeAssetId)
    ? assetPositions.get(activeAssetId).clone()
    : new THREE.Vector3(0, 0, 0);
  const activeAssetLink = cumulativeContext?.active || assetLinks.find((assetLink) => assetLink.assetId === activeAssetId);
  const metadataOverlay = addPreviewMetadataOverlay(container, previewMetadataEntries({
    componentId: "interaction-control",
    layers,
    activeLink: activeAssetLink,
    currentValue: interactionControlKindLabel(kind),
    beat,
  }));
  const configuredDestination = kind === "embodied-control"
    ? interactionLocomotionWorldTransform(editorContext.configuration, readerEditorLayer.rig).position
    : null;
  const route = kind === "embodied-control"
    ? {
        start: readerEditorLayer.rig.position.clone(),
        target: new THREE.Vector3(...(configuredDestination || [0, 0, -1.5])),
        requiresLocomotion: true,
      }
    : null;

  const viewer = {
    scene,
    camera,
    renderer,
    controls,
    root,
    readerRig: readerEditorLayer.rig,
    readerProxy: readerEditorLayer.proxy,
    readerEntity,
    spatialReaderHands,
    textPanel: spatialReaderHands.textPanel,
    textOrientationPolicy: "reader-hand",
    spatialObjects: new Map(),
    authoringSpatialObjects: new Map(),
    spatialPickTargets: [],
    spatialPlaybackEntries: [],
    spatialAssetBounds: new Map(),
    spatialSourceFocus: new Map(),
    spatialContract,
    locked: true,
    transformControls: null,
    transformHelper: null,
    destinationObjects: new Map(),
    interactionTargetCandidates: new Map(),
    interactionTargetCandidateByObject: new WeakMap(),
    interactionConstraintProxy: null,
    interactionConstraintTargetObject: null,
    interactionConstraintGhosts: new Map(),
    interactionConstraintGhostPickTargets: [],
    interactionConstraintRangeVisual: null,
    spatialEditorCamera: AUTHORING_SPATIAL_CAMERA_KIND,
    proposal,
    beat,
    sceneContext: editorContext.sceneContext,
    editorContext,
    interactionConfiguration: editorContext.configuration,
    kind,
    selectedKind,
    textKind,
    layers,
    layoutKind,
    topologyKind: layoutKind,
    geometryKind: dynamicKind,
    contextKind,
    componentId: "interaction-control",
    suppressSceneLabels: true,
    metadataOverlay,
    cumulativeContext,
    activeSwapIndex: cumulativeContext?.activeIndex || 0,
    swapGroups: [],
    swapDuplicates: [],
    swapReady: false,
    duplicateCount: topologySwapDuplicateCount(state.data?.decisions?.["asset-topology"]?.option),
    activeAssetId,
    activePosition,
    assetPositions,
    assetLinks,
    interactionSourceFocus: new Map(),
    usesInheritedSourcePlayback,
    upstreamBeatState,
    sourceMotionTransition: upstreamBeatState.sourceMotionTransition,
    sourcePartFromBeatId: upstreamBeatState.fromBeatId,
    sourcePartToBeatId: upstreamBeatState.toBeatId,
    sourcePartPlaybackMode: upstreamBeatState.sourcePartPlaybackMode,
    sourcePlaybackEntries: [],
    sourcePlaybackReady: false,
    sourceElapsed: 0,
    speed: 1,
    playing: upstreamBeatState.playTransition,
    previewCameraFramingContract: authoringSpatialCameraFramingContract(editorContext.sceneContext),
    previewCameraFramingReady: false,
    embodiedRoute: route,
    actionTargets: [],
    draggableTargets: [],
    manipulationProxy: null,
    manipulationBasePosition: null,
    interactionHandsRig: null,
    embodiedProgressionRig: null,
    animationId: null,
    resizeHandler: null,
    keyDownHandler: null,
    keyUpHandler: null,
    pointerDownHandler: null,
    pointerMoveHandler: null,
    pointerUpHandler: null,
    interactionInBeatPickPointerDownHandler: null,
    interactionInBeatPickPointerMoveHandler: null,
    interactionInBeatPickPointerUpHandler: null,
    interactionInBeatPickPointerCancelHandler: null,
    interactionInBeatPickGesture: null,
    disposed: false,
    focused: false,
    draggingInteraction: false,
    draggingPanel: false,
    dragStartX: 0,
    dragStartOffsetX: 0,
    keys: new Set(),
    lastFrameAt: performance.now(),
    elapsed: 0,
  };
  configureAuthoringSpatialCameraViewer(viewer, editorContext.sceneContext);
  interactionViewer = viewer;
  viewer.resolveSourcePlaybackWindow = (asset) => spatialPlaybackWindowForAsset(viewer.upstreamBeatState, asset);
  attachLockedEnvironmentToViewer(viewer);
  const canRestoreCameraState = restoreAuthoringSpatialCameraState(viewer);

  viewer.effects = !usesInheritedSourcePlayback && dynamicKind ? addDynamicEffectOverlays(root, dynamicKind, activePosition, {
    ...beat,
    title: `Geometry: ${dynamicGeometryKindLabel(dynamicKind)}`,
  }) : null;
  viewer.contextLayers = null;
  viewer.inheritedTextLayer = null;
  viewer.interactionOverlayGroup = new THREE.Group();
  root.add(viewer.interactionOverlayGroup);
  viewer.descriptionCues = null;

  let pendingAssets = assetLinks.length;
  const finishAsset = () => {
    pendingAssets -= 1;
    if (pendingAssets <= 0 && !viewer.disposed) {
      if (cumulativeContext) viewer.swapReady = true;
      viewer.sourcePlaybackReady = true;
      viewer.sourceElapsed = 0;
      if (!canRestoreCameraState) fitAuthoringSpatialCameraOnLoad(viewer);
      initializeInteractionConfigurationGizmo(viewer);
      initializeInteractionInBeatViewportPicking(viewer);
      refreshInteractionInBeatTargetPicker(viewer);
      status.remove();
    }
  };
  if (!assetLinks.length) requestAnimationFrame(() => {
    if (viewer.disposed) return;
    viewer.sourcePlaybackReady = true;
    if (!canRestoreCameraState) fitAuthoringSpatialCameraOnLoad(viewer);
    initializeInteractionConfigurationGizmo(viewer);
    initializeInteractionInBeatViewportPicking(viewer);
    refreshInteractionInBeatTargetPicker(viewer);
    status.remove();
  });
  assetLinks.forEach((assetLink, index) => {
    const kindForAsset = assetLink.kind || (isImageAsset(findAssetById(assetLink.assetId)) ? "image-plane" : "glb");
    if (kindForAsset === "image-plane") loadSpatialRelationsImage(viewer, assetLink, index, assetLinks.length, finishAsset);
    else loadSpatialRelationsGlb(viewer, assetLink, index, assetLinks.length, finishAsset);
  });

  const raycaster = new THREE.Raycaster();
  const pointer = new THREE.Vector2();
  const updatePointer = (event) => {
    const rect = renderer.domElement.getBoundingClientRect();
    pointer.x = ((event.clientX - rect.left) / rect.width) * 2 - 1;
    pointer.y = -((event.clientY - rect.top) / rect.height) * 2 + 1;
  };
  const targetFromHit = (object) => {
    let current = object;
    while (current) {
      if (current.userData?.interactionAction || current.userData?.interactionDraggable) return current;
      current = current.parent;
    }
    return null;
  };

  viewer.pointerDownHandler = (event) => {
    viewer.focused = true;
    container.classList.add("focused");
    renderer.domElement.focus();
    if (event.button !== 0) return;
    updatePointer(event);
    raycaster.setFromCamera(pointer, camera);
    const hits = raycaster.intersectObjects([...viewer.actionTargets, ...viewer.draggableTargets], true);
    const target = hits.length ? targetFromHit(hits[0].object) : null;
    if (!target) return;
    event.preventDefault();
    event.stopPropagation();
    if (target.userData.interactionDraggable) {
      viewer.draggingInteraction = true;
      viewer.draggingPanel = true;
      viewer.dragStartX = event.clientX;
      viewer.dragStartOffsetX = state.interactionManipulationOffset?.x || 0;
      controls.enabled = false;
      renderer.domElement.setPointerCapture?.(event.pointerId);
      return;
    }
    if (target.userData.interactionAction) {
      state.interactionViewerCameraState = captureInteractionViewerCameraState();
      const action = target.userData.interactionAction;
      interactionLogger.recordSemanticClick(event, {
        kind: "interaction-preview-control",
        label: target.userData.interactionLabel || action,
        id: action,
        action,
      });
      applyInteractionAction(action);
      if (action === "embodied-restart" || action === "embodied-step") {
        startEmbodiedProgressionReader(viewer);
        return;
      }
      render();
    }
  };

  viewer.pointerMoveHandler = (event) => {
    if (!viewer.draggingInteraction || viewer.disposed) return;
    const delta = (event.clientX - viewer.dragStartX) / 180;
    const nextX = Math.max(-1.1, Math.min(1.1, viewer.dragStartOffsetX + delta));
    state.interactionManipulationOffset = { x: nextX, y: 0, z: 0 };
    if (viewer.manipulationProxy && viewer.manipulationBasePosition) {
      viewer.manipulationProxy.position.copy(viewer.manipulationBasePosition).add(new THREE.Vector3(nextX, 0, 0));
      updateInteractionReaderHands(viewer);
    }
  };

  viewer.pointerUpHandler = (event) => {
    if (!viewer.draggingInteraction) return;
    viewer.draggingInteraction = false;
    viewer.draggingPanel = false;
    controls.enabled = true;
    if (renderer.domElement.hasPointerCapture?.(event.pointerId)) {
      renderer.domElement.releasePointerCapture?.(event.pointerId);
    }
  };

  renderer.domElement.addEventListener("pointerdown", viewer.pointerDownHandler);
  window.addEventListener("pointermove", viewer.pointerMoveHandler);
  window.addEventListener("pointerup", viewer.pointerUpHandler);
  renderer.domElement.addEventListener("blur", () => {
    viewer.focused = false;
    viewer.keys.clear();
    container.classList.remove("focused");
  });

  viewer.keyDownHandler = (event) => {
    if (!viewer.focused || !["w", "a", "s", "d"].includes(event.key.toLowerCase())) return;
    event.preventDefault();
    viewer.keys.add(event.key.toLowerCase());
  };
  viewer.keyUpHandler = (event) => {
    viewer.keys.delete(event.key.toLowerCase());
  };
  window.addEventListener("keydown", viewer.keyDownHandler);
  window.addEventListener("keyup", viewer.keyUpHandler);

  viewer.resizeHandler = () => {
    if (viewer.disposed) return;
    const nextWidth = Math.max(container.clientWidth, 360);
    const nextHeight = Math.max(container.clientHeight, 520);
    camera.aspect = nextWidth / nextHeight;
    camera.updateProjectionMatrix();
    renderer.setSize(nextWidth, nextHeight);
  };
  window.addEventListener("resize", viewer.resizeHandler);

  const animate = (now) => {
    if (viewer.disposed) return;
    const delta = Math.min((now - viewer.lastFrameAt) / 1000, 0.05);
    viewer.lastFrameAt = now;
    viewer.elapsed += delta;
    moveTextViewerCamera(viewer, delta);
    if (viewer.usesInheritedSourcePlayback) updateInteractionUpstreamPlayback(viewer, delta);
    else if (animateNarrativeSingleAnchorViewer(viewer, delta)) return;
    animateInteractionControlViewer(viewer, viewer.elapsed);
    controls.update();
    renderer.render(scene, camera);
    viewer.animationId = requestAnimationFrame(animate);
  };
  viewer.animationId = requestAnimationFrame(animate);
}

function initializeFinalReviewStoryCanvas(active) {
  if (active?.id !== "transition-pacing") return;
  const viewport = document.querySelector("[data-final-review-story-canvas-viewport]");
  const selected = viewport?.querySelector("[data-final-review-scene-key][aria-current=\"step\"]");
  if (!viewport || !selected) return;
  const viewportRect = viewport.getBoundingClientRect();
  const selectedRect = selected.getBoundingClientRect();
  const centeredLeft = viewport.scrollLeft
    + (selectedRect.left - viewportRect.left)
    - ((viewport.clientWidth - selectedRect.width) / 2);
  viewport.scrollLeft = Math.max(0, centeredLeft);
  if (state.finalReviewPendingSceneFocusKey === selected.dataset.finalReviewSceneKey) {
    state.finalReviewPendingSceneFocusKey = "";
    selected.focus({ preventScroll: true });
  }
}

function initializeFinalReviewViewer(active) {
  if (active?.id !== "transition-pacing") return;
  const container = document.querySelector("[data-final-review-viewer]");
  if (!container) return;

  const beats = finalReviewBeats();
  const beatIndex = clampFinalReviewBeatIndex(beats);
  const baseBeat = beats[beatIndex];
  const sceneContext = finalReviewSelectedSceneContext(beats, beatIndex);
  const beat = finalReviewBeatForSceneContext(sceneContext) || baseBeat;
  const transitionPlayback = finalReviewTransitionPlaybackForContext(sceneContext);
  const transitionBoundary = transitionPlayback?.boundary || null;
  const transitionKind = transitionPlayback
    ? inferInterBeatDynamicsKind(
      sourceDynamicsPreviewForComponent("inter-beat-dynamics")
        || state.data?.decisions?.["inter-beat-dynamics"]?.option,
    )
    : null;
  const proceduralPlan = proceduralDynamicsStoredPlan(sceneContext);
  const proceduralInstances = proceduralPlan
    ? expandProceduralDynamicsInstances(proceduralPlan, { xrPresenting: true })
    : [];
  const proceduralAnchorPosition = proceduralDynamicsReaderAnchorForScene(sceneContext);
  const region = microhabitatForBeat(beat);
  const savedDecisionKinds = finalReviewDecisionKinds();
  const activeProgressionBoundary = finalReviewActiveProgressionBoundary({ beat, sceneContext });
  const activeProgressionPlayback = finalReviewActiveProgressionPlayback(activeProgressionBoundary);
  const routeInteractionKind = recognizedInteractionPolicyKind(activeProgressionBoundary?.effectivePolicy);
  const decisionKinds = { ...savedDecisionKinds, interaction: routeInteractionKind };
  const transitionAssetLinks = finalReviewTransitionAssetLinks(transitionPlayback);
  const savedSpatialSceneAssets = exactSpatialSceneAssetLinkSet(sceneContext);
  const cumulativeContext = finalReviewCumulativeContextForBeat(beats, beatIndex, sceneContext, beat);
  const exactSceneAssetLinks = transitionAssetLinks.length
      ? transitionAssetLinks
      : beat && (proceduralPlan || sceneContext?.variantOptionId)
        ? dynamicSceneAssetLinks(null, [beat], sceneContext)
        : savedSpatialSceneAssets.available
          ? savedSpatialSceneAssets.links
          : [];
  const usesSavedSpatialSceneAssets = !transitionAssetLinks.length
    && !proceduralPlan
    && !sceneContext?.variantOptionId
    && savedSpatialSceneAssets.available;
  const linkedAssetId = cumulativeContext?.active?.assetId
    || exactSceneAssetLinks.find((link) => isModelAsset(findAssetById(link.assetId)))?.assetId
    || exactSceneAssetLinks[0]?.assetId
    || (usesSavedSpatialSceneAssets
      ? null
      : beat?.linkedAssetIds?.find((assetId) => isModelAsset(findAssetById(assetId)))
        || beat?.linkedAssetIds?.[0])
    || null;
  const linkedAsset = linkedAssetId ? findAssetById(linkedAssetId) : null;
  const cumulativeAssetLinks = cumulativeContext?.sequence?.steps || [];
  const width = Math.max(container.clientWidth, 360);
  const height = Math.max(container.clientHeight, 620);
  const scene = new THREE.Scene();
  scene.background = new THREE.Color(0x080a08);
  scene.fog = null;

  const camera = new THREE.PerspectiveCamera(42, width / height, 0.02, 1000);
  camera.position.set(3.8, 2.45, 4.8);
  scene.add(camera);

  const renderer = new THREE.WebGLRenderer({ antialias: true, alpha: true });
  renderer.setPixelRatio(Math.min(window.devicePixelRatio || 1, 2));
  renderer.setSize(width, height);
  renderer.outputColorSpace = THREE.SRGBColorSpace;
  renderer.setClearColor(0x080a08, 1);
  renderer.xr.enabled = true;
  renderer.xr.setFramebufferScaleFactor(0.8);
  renderer.xr.setFoveation(1);
  renderer.domElement.tabIndex = 0;
  renderer.domElement.className = "topology-viewer-canvas final-review-canvas";

  const status = document.createElement("div");
  status.className = "topology-viewer-status overlay";
  status.textContent = exactSceneAssetLinks.length
    ? `Loading ${exactSceneAssetLinks.length} exact-scene asset${exactSceneAssetLinks.length === 1 ? "" : "s"}...`
    : cumulativeContext
    ? `Loading ${cumulativeAssetLinks.length} active story-part assets...`
    : linkedAsset ? `Loading ${linkedAsset.id}...` : "Loading text-only reader state...";
  container.replaceChildren(renderer.domElement, status);
  const layers = cumulativePreviewLayersForComponent("transition-pacing", {
    topologyKind: decisionKinds.topology,
    dynamicKind: decisionKinds.geometry,
    transitionKind: decisionKinds.transition,
    contextKind: decisionKinds.context,
    textKind: decisionKinds.text,
    interactionKind: decisionKinds.interaction,
  });
  const metadataOverlay = addPreviewMetadataOverlay(container, previewMetadataEntries({
    componentId: "transition-pacing",
    layers,
    activeLink: cumulativeContext?.active || (linkedAssetId ? { assetId: linkedAssetId } : null),
    currentValue: "Review story",
    beat,
  }));

  const controls = new OrbitControls(camera, renderer.domElement);
  controls.enableDamping = true;
  controls.dampingFactor = 0.08;
  controls.enableZoom = false;
  controls.target.set(0, 0.78, 0);
  configureSpatialEditorMouseControls(controls);

  scene.add(new THREE.HemisphereLight(0xffffff, 0x6f7f78, 2.4));
  const keyLight = new THREE.DirectionalLight(0xffffff, 3.3);
  keyLight.position.set(4, 7, 5);
  scene.add(keyLight);
  const rimLight = new THREE.DirectionalLight(0x9edfd5, 1.2);
  rimLight.position.set(-5, 3, -4);
  scene.add(rimLight);

  const root = new THREE.Group();
  scene.add(root);
  const directManipulationCueRoot = new THREE.Group();
  directManipulationCueRoot.name = "StoryVR direct manipulation cues · Final Review";
  scene.add(directManipulationCueRoot);
  const stageState = addFinalReviewStage(root, beat, region, decisionKinds);
  const readerHandRig = addFinalReviewReaderHandRig(camera, camera.aspect);

  const viewer = {
    scene,
    camera,
    renderer,
    controls,
    root,
    beat,
    sceneContext,
    spatialSceneContextsByAssetId: transitionPlayback
      ? interBeatSpatialSceneContextsByAssetId(transitionBoundary)
      : new Map(exactSceneAssetLinks.map((link) => [link.assetId, sceneContext])),
    region,
    decisionKinds,
    activeProgressionBoundary,
    geometryKind: decisionKinds.geometry,
    layoutKind: decisionKinds.topology,
    topologyKind: decisionKinds.topology,
    componentId: "transition-pacing",
    suppressSceneLabels: true,
    metadataOverlay,
    layers,
    cumulativeContext,
    assetLinks: exactSceneAssetLinks,
    dynamicObjects: [],
    proceduralPlan,
    proceduralInstances,
    proceduralAnchorPosition,
    proceduralPreviewEntries: [],
    showActiveHalo: false,
    activeSwapIndex: cumulativeContext?.activeIndex || 0,
    swapGroups: [],
    swapDuplicates: [],
    swapReady: false,
    duplicateCount: topologySwapDuplicateCount(state.data?.decisions?.["asset-topology"]?.option),
    activeAssetId: linkedAssetId,
    activeAssetGroup: null,
    duplicateGroups: [],
    regionMarkers: [],
    textPanel: null,
    readerHandRig,
    directManipulationCueRoot,
    directManipulationCues: [],
    directManipulationTargets: [],
    directManipulationCueElapsed: 0,
    finalReviewTransitionPlayback: transitionPlayback,
    transitionKind,
    sourcePlaybackSummary: transitionPlayback?.sourcePlaybackSummary || null,
    legacySourceMotionTracks: transitionPlayback?.mappedTracks || [],
    manualVariantSwitch: transitionPlayback?.manualVariantSwitch === true,
    routeScopedTransition: transitionPlayback?.routeScopedProgression === true,
    variantTransitionAnimationSpec: transitionPlayback?.variantTransitionAnimationSpec || null,
    sourceMotionTransition: transitionBoundary?.fromBeatId ? {
      fromBeatId: transitionBoundary.fromBeatId,
      toBeatId: transitionBoundary.toBeatId || "",
      ...(transitionBoundary.edgeId ? { edgeId: transitionBoundary.edgeId } : {}),
      ...(transitionBoundary.fromSceneContext ? {
        fromContext: normalizeMotionSceneContext(transitionBoundary.fromSceneContext, transitionBoundary.fromBeatId),
      } : {}),
      ...(transitionBoundary.toSceneContext ? {
        toContext: normalizeMotionSceneContext(transitionBoundary.toSceneContext, transitionBoundary.toBeatId),
      } : {}),
    } : null,
    sourcePartFromBeatId: transitionBoundary?.fromBeatId || beat?.id || "",
    sourcePartToBeatId: transitionBoundary?.toBeatId || beat?.id || "",
    sourcePartPlaybackMode: transitionPlayback?.sourcePartPlaybackMode || "held",
    sourcePartFreezeProgress: 0,
    sourcePartMaskPhase: null,
    sourceElapsed: 0,
    transitionPlaying: false,
    transitionStarted: false,
    playOnce: Boolean(transitionPlayback),
    previewCycleSeconds: transitionPlayback?.sourcePlaybackSummary?.windowState?.mode === "scrub"
      ? sourcePlaybackScrubCycleSeconds(
        sourcePlaybackAssetForId(transitionPlayback.sourcePlaybackSummary.assetId),
        transitionPlayback.sourcePlaybackSummary.windowState,
        INTER_BEAT_TRANSITION_CYCLE_SECONDS,
      )
      : INTER_BEAT_TRANSITION_CYCLE_SECONDS,
    transitionFromAssetIds: new Set(transitionBoundary?.from?.linkedAssetIds || []),
    transitionToAssetIds: new Set(transitionBoundary?.to?.linkedAssetIds || []),
    attentionScene: null,
    attentionTargets: [],
    flash: null,
    embodiedRig: null,
    stageTitleLabel: stageState?.titleLabel || null,
    finalReviewTextGroup: null,
    textPanelClickHandler: null,
    textPanelWheelHandler: null,
    textPanelPointerMoveHandler: null,
    textPanelPointerLeaveHandler: null,
    readerHandPointerDownHandler: null,
    readerHandPointerMoveHandler: null,
    readerHandPointerUpHandler: null,
    textPanelPointerCandidate: null,
    draggingTextPanel: false,
    suppressTextPanelClick: false,
    draggingReaderHand: false,
    readerHandDragStartX: 0,
    readerHandDragStartY: 0,
    readerHandDragStartOffset: { x: 0, y: 0 },
    animationId: null,
    resizeHandler: null,
    keyDownHandler: null,
    keyUpHandler: null,
    pointerDownHandler: null,
    disposed: false,
    focused: false,
    keys: new Set(),
    lastFrameAt: performance.now(),
    elapsed: 0,
    playing: Boolean(state.finalReviewPlaying),
    xrControllers: new Map(),
    xrControllersByHand: new Map(),
    xrPreferredHand: "left",
    xrAttachedEntry: null,
    xrGrabEntry: null,
    xrGrabInput: null,
    xrDirectManipulationGrab: null,
    xrScrollGesture: null,
    textScrollLine: 0,
    textPagination: null,
    textContent: null,
    xrRaycaster: new THREE.Raycaster(),
    xrRayRotation: new THREE.Matrix4(),
    xrSessionStartHandler: null,
    xrSessionEndHandler: null,
    readerLookPosition: null,
    readerLookDirection: new THREE.Vector3(),
    readerLookDistance: null,
  };
  finalReviewViewer = viewer;
  controls.enablePan = true;
  const restoredCameraState = state.finalReviewViewerCameraState;
  const canRestoreCameraState = shouldRestoreFinalReviewViewerCameraState(viewer, restoredCameraState);
  // Match the compiled reader: use the authored station only for the initial
  // reader entry, then preserve the captured pose through later beat rebuilds.
  if (canRestoreCameraState) {
    applyFinalReviewViewerCameraState(viewer, restoredCameraState);
  } else {
    applyFinalReviewAuthoredReaderPose(viewer);
  }
  resetFinalReviewReaderLookAnchor(viewer);
  attachLockedEnvironmentToViewer(viewer);
  addFinalReviewTextPanel(viewer, beat, region);
  configureFinalReviewXrTextPanel(viewer);
  addFinalReviewTransitionEffects(
    viewer,
    region,
    transitionKind || decisionKinds.transition,
    transitionPlayback || activeProgressionPlayback,
  );
  if (routeInteractionKind === "embodied-control") {
    addFinalReviewEmbodiedProgression(viewer, region, activeProgressionBoundary?.configuration);
  }
  applyFinalReviewTuningDirectives(viewer, finalReviewTuningDirectives());

  const textPanelRaycaster = new THREE.Raycaster();
  const textPanelPointer = new THREE.Vector2();
  const updateFinalReviewPointer = (event) => {
    const rect = renderer.domElement.getBoundingClientRect();
    if (!rect.width || !rect.height) return null;
    textPanelPointer.x = ((event.clientX - rect.left) / rect.width) * 2 - 1;
    textPanelPointer.y = -((event.clientY - rect.top) / rect.height) * 2 + 1;
    return rect;
  };
  const textPanelControlAtPointer = (event) => {
    const panelGroup = viewer.finalReviewTextGroup;
    if (!panelGroup?.visible) return null;
    const activeRoot = state.finalReviewTextPanelMinimized
      ? panelGroup.userData.minimizedRoot
      : panelGroup.userData.expandedRoot;
    if (!activeRoot?.visible) return null;
    if (!updateFinalReviewPointer(event)) return null;
    const pointerCamera = finalReviewRenderCamera(viewer);
    syncFinalReviewReaderHandRigCamera(viewer, pointerCamera);
    pointerCamera.updateMatrixWorld(true);
    activeRoot.updateWorldMatrix(true, true);
    textPanelRaycaster.setFromCamera(textPanelPointer, pointerCamera);
    const textPanelHits = textPanelRaycaster.intersectObject(activeRoot, true);
    for (const hit of textPanelHits) {
      let control = hit.object;
      while (control && control !== activeRoot.parent) {
        if (control.userData?.finalReviewTextPanelAction) return control;
        control = control.parent;
      }
    }
    return null;
  };
  const readerHandRaycaster = new THREE.Raycaster();
  const readerHandAtPointer = (event) => {
    if (!viewer.readerHandRig?.group?.visible) return null;
    const targets = viewer.readerHandRig?.dragTargets || [];
    if (!targets.length || !updateFinalReviewPointer(event)) return null;
    const pointerCamera = finalReviewRenderCamera(viewer);
    syncFinalReviewReaderHandRigCamera(viewer, pointerCamera);
    pointerCamera.updateMatrixWorld(true);
    viewer.readerHandRig.group.updateWorldMatrix(true, true);
    readerHandRaycaster.setFromCamera(textPanelPointer, pointerCamera);
    return readerHandRaycaster.intersectObjects(targets, true)[0]?.object || null;
  };
  viewer.textPanelClickHandler = (event) => {
    if (viewer.suppressTextPanelClick) {
      viewer.suppressTextPanelClick = false;
      event.preventDefault();
      event.stopPropagation();
      return;
    }
    const control = textPanelControlAtPointer(event);
    const action = control?.userData?.finalReviewTextPanelAction;
    if (!action) return;
    event.preventDefault();
    event.stopPropagation();
    interactionLogger.recordSemanticClick(event, {
      kind: "reader-text-panel-control",
      label: ({
        minimize: "Minimize reader text panel",
        restore: "Restore reader text panel",
        "variant-previous": "Previous reader choice",
        "variant-next": "Next reader choice",
      })[action] || `Reader text panel ${action}`,
      action,
    });
    if (action === "minimize" || action === "restore") {
      setFinalReviewTextPanelMinimized(viewer, action === "minimize");
      return;
    }
    if (action === "variant-previous" || action === "variant-next") {
      if (!control.userData.finalReviewTextPanelDisabled) {
        applyFinalReviewVariantSelection(control.userData.finalReviewVariantTargetContext);
      }
    }
  };
  viewer.textPanelPointerMoveHandler = (event) => {
    if (viewer.draggingTextPanel || viewer.draggingReaderHand) {
      renderer.domElement.style.cursor = viewer.textPanelPointerCandidate?.mode === "scroll"
        ? "ns-resize"
        : "grabbing";
      return;
    }
    const textPanelControl = textPanelControlAtPointer(event);
    renderer.domElement.style.cursor = textPanelControl
      ? textPanelControl.userData.finalReviewTextPanelDisabled
        ? "not-allowed"
        : textPanelControl.userData.finalReviewTextPanelAction === "grab"
          ? "grab"
          : textPanelControl.userData.finalReviewTextPanelAction === "scroll" ? "ns-resize" : "pointer"
      : readerHandAtPointer(event) ? "grab" : "";
  };
  viewer.textPanelPointerLeaveHandler = () => {
    if (!viewer.draggingTextPanel && !viewer.draggingReaderHand) renderer.domElement.style.cursor = "";
  };
  viewer.readerHandPointerDownHandler = (event) => {
    if (event.button !== 0) return;
    const textPanelControl = textPanelControlAtPointer(event);
    if (textPanelControl && !textPanelControl.userData.finalReviewTextPanelDisabled) {
      const action = textPanelControl.userData.finalReviewTextPanelAction;
      event.preventDefault();
      event.stopPropagation();
      viewer.focused = true;
      viewer.textPanelPointerCandidate = {
        pointerId: event.pointerId,
        mode: action === "scroll" ? "scroll" : "grab",
        startX: event.clientX,
        startY: event.clientY,
        startLine: Number(viewer.textScrollLine) || 0,
        maxScrollLine: Math.max(Number(viewer.textPagination?.maxScrollLine) || 0, 0),
        panelPixelHeight: finalReviewTextPanelPixelHeight(viewer),
        startOffset: {
          x: Number(state.finalReviewTextPanelOffset?.x) || 0,
          y: Number(state.finalReviewTextPanelOffset?.y) || 0,
        },
      };
      controls.enabled = false;
      container.classList.add("focused");
      renderer.domElement.focus();
      renderer.domElement.style.cursor = action === "scroll" ? "ns-resize" : "grabbing";
      renderer.domElement.setPointerCapture?.(event.pointerId);
      return;
    }
    if (!readerHandAtPointer(event)) return;
    event.preventDefault();
    event.stopPropagation();
    viewer.focused = true;
    viewer.draggingReaderHand = true;
    viewer.readerHandDragStartX = event.clientX;
    viewer.readerHandDragStartY = event.clientY;
    viewer.readerHandDragStartOffset = {
      x: Number(state.finalReviewReaderHandOffset?.x) || 0,
      y: Number(state.finalReviewReaderHandOffset?.y) || 0,
    };
    controls.enabled = false;
    container.classList.add("focused");
    renderer.domElement.focus();
    renderer.domElement.style.cursor = "grabbing";
    renderer.domElement.setPointerCapture?.(event.pointerId);
  };
  viewer.readerHandPointerMoveHandler = (event) => {
    if (viewer.textPanelPointerCandidate && !viewer.disposed) {
      if (viewer.textPanelPointerCandidate.pointerId !== event.pointerId) return;
      const deltaX = event.clientX - viewer.textPanelPointerCandidate.startX;
      const deltaY = event.clientY - viewer.textPanelPointerCandidate.startY;
      if (!viewer.draggingTextPanel && Math.hypot(deltaX, deltaY) < 4) return;
      viewer.draggingTextPanel = true;
      viewer.suppressTextPanelClick = true;
      if (viewer.textPanelPointerCandidate.mode === "scroll") {
        const lineDelta = Math.round(
          (deltaY / Math.max(viewer.textPanelPointerCandidate.panelPixelHeight, 1))
          * viewer.textPanelPointerCandidate.maxScrollLine,
        );
        setFinalReviewTextPanelScrollLine(
          viewer,
          viewer.textPanelPointerCandidate.startLine + lineDelta,
        );
        renderer.domElement.style.cursor = "ns-resize";
        event.preventDefault();
        return;
      }
      const rect = renderer.domElement.getBoundingClientRect();
      if (!rect.height) return;
      const pointerCamera = finalReviewRenderCamera(viewer);
      const panelPosition = viewer.finalReviewTextGroup?.getWorldPosition(new THREE.Vector3());
      const panelCameraPosition = panelPosition ? pointerCamera.worldToLocal(panelPosition.clone()) : null;
      const depth = Math.max(Math.abs(panelCameraPosition?.z || 0), 0.02);
      const visibleHeight = 2 * depth * Math.tan(THREE.MathUtils.degToRad(pointerCamera.fov * 0.5));
      const worldPerPixel = visibleHeight / rect.height;
      state.finalReviewTextPanelOffset = {
        x: THREE.MathUtils.clamp(
          viewer.textPanelPointerCandidate.startOffset.x + (deltaX * worldPerPixel),
          -0.65,
          0.65,
        ),
        y: THREE.MathUtils.clamp(
          viewer.textPanelPointerCandidate.startOffset.y - (deltaY * worldPerPixel),
          -0.48,
          0.48,
        ),
      };
      updateFinalReviewTextPanelViewport(viewer);
      renderer.domElement.style.cursor = "grabbing";
      event.preventDefault();
      return;
    }
    if (!viewer.draggingReaderHand || viewer.disposed) return;
    const rect = renderer.domElement.getBoundingClientRect();
    if (!rect.height) return;
    const depth = Math.max(Math.abs(viewer.readerHandRig?.group?.position?.z || 0), 0.02);
    const pointerCamera = finalReviewRenderCamera(viewer);
    const visibleHeight = 2 * depth * Math.tan(THREE.MathUtils.degToRad(pointerCamera.fov * 0.5));
    const worldPerPixel = visibleHeight / rect.height;
    state.finalReviewReaderHandOffset = {
      x: THREE.MathUtils.clamp(
        viewer.readerHandDragStartOffset.x + ((event.clientX - viewer.readerHandDragStartX) * worldPerPixel),
        -0.65,
        0.65,
      ),
      y: THREE.MathUtils.clamp(
        viewer.readerHandDragStartOffset.y - ((event.clientY - viewer.readerHandDragStartY) * worldPerPixel),
        -0.48,
        0.48,
      ),
    };
    const renderCamera = finalReviewRenderCamera(viewer);
    updateFinalReviewReaderHandRigViewport(viewer.readerHandRig, renderCamera.aspect, renderCamera.fov);
  };
  viewer.readerHandPointerUpHandler = (event) => {
    if (viewer.textPanelPointerCandidate?.pointerId === event.pointerId) {
      viewer.textPanelPointerCandidate = null;
      viewer.draggingTextPanel = false;
      controls.enabled = !renderer.xr.isPresenting;
      renderer.domElement.style.cursor = "";
      renderer.domElement.releasePointerCapture?.(event.pointerId);
      if (event.type === "pointercancel") viewer.suppressTextPanelClick = false;
      return;
    }
    if (!viewer.draggingReaderHand) return;
    viewer.draggingReaderHand = false;
    controls.enabled = !renderer.xr.isPresenting;
    renderer.domElement.style.cursor = "";
    if (renderer.domElement.hasPointerCapture?.(event.pointerId)) {
      renderer.domElement.releasePointerCapture?.(event.pointerId);
    }
  };
  viewer.textPanelWheelHandler = (event) => {
    const textPanelControl = textPanelControlAtPointer(event);
    if (textPanelControl?.userData?.finalReviewTextPanelAction !== "scroll") return;
    const maxScrollLine = Math.max(Number(viewer.textPagination?.maxScrollLine) || 0, 0);
    if (!maxScrollLine || !event.deltaY) return;
    event.preventDefault();
    event.stopPropagation();
    const lineStep = Math.sign(event.deltaY) * Math.max(1, Math.round(Math.abs(event.deltaY) / 48));
    setFinalReviewTextPanelScrollLine(viewer, (Number(viewer.textScrollLine) || 0) + lineStep);
  };
  renderer.domElement.addEventListener("click", viewer.textPanelClickHandler);
  renderer.domElement.addEventListener("wheel", viewer.textPanelWheelHandler, { passive: false });
  renderer.domElement.addEventListener("pointermove", viewer.textPanelPointerMoveHandler);
  renderer.domElement.addEventListener("pointerleave", viewer.textPanelPointerLeaveHandler);
  renderer.domElement.addEventListener("pointerdown", viewer.readerHandPointerDownHandler);
  window.addEventListener("pointermove", viewer.readerHandPointerMoveHandler);
  window.addEventListener("pointerup", viewer.readerHandPointerUpHandler);
  window.addEventListener("pointercancel", viewer.readerHandPointerUpHandler);

  container.addEventListener("pointerdown", () => {
    viewer.focused = true;
    container.classList.add("focused");
    renderer.domElement.focus();
  });
  renderer.domElement.addEventListener("blur", () => {
    viewer.focused = false;
    viewer.keys.clear();
    container.classList.remove("focused");
  });
  viewer.pointerDownHandler = (event) => {
    if (!container.contains(event.target)) {
      viewer.focused = false;
      viewer.keys.clear();
      container.classList.remove("focused");
    }
  };
  viewer.keyDownHandler = (event) => {
    const key = event.key.toLowerCase();
    if (!viewer.focused || !["w", "a", "s", "d"].includes(key)) return;
    event.preventDefault();
    viewer.keys.add(key);
  };
  viewer.keyUpHandler = (event) => {
    const key = event.key.toLowerCase();
    if (!["w", "a", "s", "d"].includes(key)) return;
    viewer.keys.delete(key);
  };
  viewer.resizeHandler = () => {
    if (viewer.disposed) return;
    const nextWidth = Math.max(container.clientWidth, 360);
    const nextHeight = Math.max(container.clientHeight, 620);
    camera.aspect = nextWidth / nextHeight;
    camera.updateProjectionMatrix();
    renderer.setSize(nextWidth, nextHeight);
    const renderCamera = finalReviewRenderCamera(viewer);
    updateFinalReviewReaderHandRigViewport(viewer.readerHandRig, renderCamera.aspect, renderCamera.fov);
  };
  document.addEventListener("pointerdown", viewer.pointerDownHandler);
  window.addEventListener("keydown", viewer.keyDownHandler);
  window.addEventListener("keyup", viewer.keyUpHandler);
  window.addEventListener("resize", viewer.resizeHandler);

  const startFinalReviewTransition = () => {
    if (!viewer.finalReviewTransitionPlayback || viewer.transitionStarted || viewer.disposed) return false;
    viewer.sourceElapsed = 0;
    viewer.transitionPlaying = true;
    viewer.transitionStarted = true;
    renderer.domElement.dataset.finalReviewTransitionProgress = "0.0000";
    renderer.domElement.dataset.finalReviewTransitionState = "playing";
    applyInterBeatSourcePartMasks(viewer, "transition");
    return true;
  };

  const finish = (ok) => {
    if (viewer.disposed) return;
    resetFinalReviewReaderLookAnchor(viewer);
    refreshFinalReviewDirectManipulationCues(viewer);
    syncFinalReviewAttentionGuidance(viewer);
    startFinalReviewTransition();
    status.textContent = ok ? "" : "Loaded with an asset issue; showing final layout fallback.";
    if (ok) status.remove();
  };

  if (exactSceneAssetLinks.length) {
    let pending = exactSceneAssetLinks.length;
    let failed = 0;
    const finishExactSceneAsset = (ok) => {
      pending -= 1;
      if (!ok) failed += 1;
      if (viewer.disposed) return;
      if (
        !canRestoreCameraState
        && !viewer.readerLookPosition
      ) {
        fitInheritedTopologyPreviewCamera(viewer, root);
      }
      resetFinalReviewReaderLookAnchor(viewer);
      if (pending > 0) {
        status.textContent = `Loading ${pending} more exact-scene asset${pending === 1 ? "" : "s"}...`;
      } else if (failed) {
        status.textContent = `Loaded exact choice scene with ${failed} asset issue${failed === 1 ? "" : "s"}.`;
      } else {
        status.remove();
      }
      if (pending === 0) {
        refreshFinalReviewDirectManipulationCues(viewer);
        syncFinalReviewAttentionGuidance(viewer);
        startFinalReviewTransition();
      }
    };
    const loadNextExactSceneAsset = (index = 0) => {
      const assetLink = exactSceneAssetLinks[index];
      if (!assetLink || viewer.disposed) return;
      loadDynamicAsset(viewer, assetLink, index, exactSceneAssetLinks.length, true, (ok) => {
        finishExactSceneAsset(ok);
        loadNextExactSceneAsset(index + 1);
      });
    };
    loadNextExactSceneAsset();
  } else if (cumulativeContext && cumulativeAssetLinks.length) {
    let pending = cumulativeAssetLinks.length;
    let failed = 0;
    const finishCumulativeAsset = (ok) => {
      pending -= 1;
      if (!ok) failed += 1;
      if (viewer.disposed) return;
      if (
        !canRestoreCameraState
        && !viewer.readerLookPosition
      ) {
        fitInheritedTopologyPreviewCamera(viewer, root);
      }
      resetFinalReviewReaderLookAnchor(viewer);
      if (pending > 0) {
        status.textContent = `Loading ${pending} more cumulative final assets...`;
      } else {
        viewer.swapReady = true;
        refreshFinalReviewDirectManipulationCues(viewer);
        syncFinalReviewAttentionGuidance(viewer);
        startFinalReviewTransition();
        if (failed) {
          status.textContent = `Loaded cumulative final preview with ${failed} asset issue${failed === 1 ? "" : "s"}.`;
          return;
        }
        status.remove();
      }
    };
    const loadNextCumulativeAsset = (index = 0) => {
      const assetLink = cumulativeAssetLinks[index];
      if (!assetLink || viewer.disposed) return;
      loadTopologySwapAsset(viewer, assetLink, index, (ok) => {
        finishCumulativeAsset(ok);
        loadNextCumulativeAsset(index + 1);
      });
    };
    loadNextCumulativeAsset();
  } else if (linkedAsset) {
    loadFinalReviewAsset(viewer, linkedAsset, finish);
  } else {
    addFinalReviewTextOnlyState(viewer, beat, region);
    requestAnimationFrame(() => finish(true));
  }

  const animate = (time) => {
    if (viewer.disposed) return;
    const delta = Math.min((time - viewer.lastFrameAt) / 1000, 0.05);
    viewer.lastFrameAt = time;
    viewer.directManipulationCueElapsed += delta;
    viewer.elapsed += previewPlaybackDeltaSeconds(viewer, delta);
    updateTopologyKeyboardMovement(viewer, delta);
    if (animateNarrativeSingleAnchorViewer(viewer, delta)) return;
    animateFinalReviewViewer(viewer, delta);
    if (!renderer.xr.isPresenting) {
      controls.update();
      stabilizeFinalReviewReaderLook(viewer);
    }
    const renderCamera = finalReviewRenderCamera(viewer);
    updateFinalReviewAttentionGuidance(viewer, renderCamera, delta);
    updateFinalReviewXrTextPanelRays(viewer);
    syncFinalReviewReaderHandRigCamera(viewer, renderCamera);
    renderer.render(scene, renderCamera);
  };
  viewer.animationLoop = animate;
  renderer.setAnimationLoop(animate);
}

function addFinalReviewStage(root, beat, activeRegion, decisionKinds = finalReviewDecisionKinds()) {
  return { titleLabel: null };
}

function addFinalReviewReaderHandRig(camera, aspect = camera?.aspect) {
  const group = new THREE.Group();
  group.name = "StoryVR reader left hand · Final Review";
  group.rotation.set(-0.04, 0.08, -0.08);
  group.userData.attachmentPolicy = "reader-hand";

  const sleeve = new THREE.Mesh(
    new THREE.CapsuleGeometry(0.038, 0.19, 6, 14),
    new THREE.MeshStandardMaterial({ color: 0x007f73, roughness: 0.76 }),
  );
  sleeve.name = "StoryVR reader forearm";
  sleeve.userData.finalReviewReaderHandDrag = true;
  sleeve.position.set(-0.065, -0.15, 0.08);
  sleeve.rotation.z = -0.42;
  group.add(sleeve);

  const hand = makeInteractionHandMesh("left");
  hand.name = "StoryVR reader left hand";
  hand.userData.finalReviewReaderHandDrag = true;
  hand.rotation.set(-0.08, 0.04, -0.08);
  hand.scale.setScalar(0.64);
  group.add(hand);

  const panelAnchor = new THREE.Group();
  panelAnchor.name = "StoryVR reader left-hand panel anchor";
  panelAnchor.userData.attachmentPolicy = "reader-hand";
  group.add(panelAnchor);
  camera.add(group);
  const rig = { group, sleeve, hand, panelAnchor, dragTargets: [sleeve, hand], handedness: "left" };
  updateFinalReviewReaderHandRigViewport(rig, aspect);
  return rig;
}

function updateFinalReviewReaderHandRigViewport(readerHandRig, aspect, fov = FINAL_REVIEW_DESKTOP_PANEL_REFERENCE_FOV) {
  const group = readerHandRig?.group;
  if (!group) return;
  const numericAspect = Number(aspect);
  const compactness = THREE.MathUtils.clamp(
    (0.92 - (Number.isFinite(numericAspect) ? numericAspect : 1)) / 0.46,
    0,
    1,
  );
  const numericFov = Number(fov);
  const referenceTangent = Math.tan(THREE.MathUtils.degToRad(FINAL_REVIEW_DESKTOP_PANEL_REFERENCE_FOV * 0.5));
  const renderTangent = Math.tan(THREE.MathUtils.degToRad(
    THREE.MathUtils.clamp(Number.isFinite(numericFov) ? numericFov : FINAL_REVIEW_DESKTOP_PANEL_REFERENCE_FOV, 5, 140) * 0.5,
  ));
  const viewportScale = THREE.MathUtils.clamp(renderTangent / referenceTangent, 0.28, 2.4);
  const offsetX = Number(state.finalReviewReaderHandOffset?.x) || 0;
  const offsetY = Number(state.finalReviewReaderHandOffset?.y) || 0;
  group.position.set(
    (THREE.MathUtils.lerp(-0.12, -0.06, compactness) * viewportScale) + offsetX,
    (-0.16 * viewportScale) + offsetY,
    THREE.MathUtils.lerp(-0.52, -1.28, compactness),
  );
  group.scale.setScalar(viewportScale);
}

function syncFinalReviewReaderHandRigCamera(viewer, renderCamera = finalReviewRenderCamera(viewer)) {
  const rig = viewer?.readerHandRig;
  const group = rig?.group;
  const targetCamera = renderCamera?.isCamera ? renderCamera : viewer?.camera;
  if (!group || !targetCamera) return false;
  if (group.parent !== targetCamera) targetCamera.add(group);
  updateFinalReviewReaderHandRigViewport(rig, targetCamera.aspect || viewer?.camera?.aspect, targetCamera.fov);
  return true;
}

function updateFinalReviewTextPanelViewport(viewer) {
  const group = viewer?.finalReviewTextGroup;
  if (!group || viewer.renderer?.xr?.isPresenting || viewer.xrGrabEntry) return;
  const side = viewer.readerHandRig?.handedness === "right" ? -1 : 1;
  const camera = finalReviewRenderCamera(viewer);
  const numericAspect = Number(camera?.aspect || viewer?.camera?.aspect);
  const compactness = THREE.MathUtils.clamp(
    (0.92 - (Number.isFinite(numericAspect) ? numericAspect : 1)) / 0.46,
    0,
    1,
  );
  const maximumOffsetX = THREE.MathUtils.lerp(0.2, 0.04, compactness);
  const offsetX = THREE.MathUtils.clamp(
    Number(state.finalReviewTextPanelOffset?.x) || 0,
    -maximumOffsetX,
    maximumOffsetX,
  );
  const maximumOffsetY = THREE.MathUtils.lerp(0.35, 0.12, compactness);
  const offsetY = THREE.MathUtils.clamp(
    Number(state.finalReviewTextPanelOffset?.y) || 0,
    -maximumOffsetY,
    maximumOffsetY,
  );
  const safePanelX = THREE.MathUtils.lerp(0.25, 0.08, compactness);
  group.position.set((safePanelX * side) + offsetX, 0.115 + offsetY, -0.32);
  group.rotation.set(-0.16, -0.12 * side, 0);
}

function finalReviewTextPanelPixelHeight(viewer) {
  const panel = viewer?.finalReviewTextGroup?.userData?.contentMesh;
  const camera = finalReviewRenderCamera(viewer);
  const rect = viewer?.renderer?.domElement?.getBoundingClientRect?.();
  const height = Number(panel?.geometry?.parameters?.height) || FINAL_REVIEW_XR_TEXT_PANEL_HEIGHT;
  if (!panel || !camera || !rect?.height) return 1;
  camera.updateMatrixWorld(true);
  panel.updateWorldMatrix(true, false);
  const top = panel.localToWorld(new THREE.Vector3(0, height / 2, 0)).project(camera);
  const bottom = panel.localToWorld(new THREE.Vector3(0, -height / 2, 0)).project(camera);
  return Math.max(Math.abs(top.y - bottom.y) * rect.height * 0.5, 1);
}

function configureFinalReviewXrTextPanel(viewer) {
  if (!viewer?.renderer?.xr) return;
  for (let index = 0; index < 2; index += 1) {
    const controller = viewer.renderer.xr.getController(index);
    const grip = viewer.renderer.xr.getControllerGrip(index);
    controller.name = `StoryVR Final Review controller ${index + 1}`;
    grip.name = `StoryVR Final Review grip ${index + 1}`;
    controller.add(createFinalReviewXrTextPanelRay());
    const entry = {
      index,
      controller,
      grip,
      anchor: controller,
      handedness: index === 0 ? "left" : "right",
      connected: false,
    };
    viewer.xrControllers.set(controller, entry);
    controller.addEventListener("connected", (event) => handleFinalReviewXrControllerConnected(viewer, entry, event));
    controller.addEventListener("disconnected", () => handleFinalReviewXrControllerDisconnected(viewer, entry));
    controller.addEventListener("selectstart", () => handleFinalReviewXrTextPanelSelectStart(viewer, entry));
    controller.addEventListener("selectend", () => handleFinalReviewXrTextPanelSelectEnd(viewer, entry));
    controller.addEventListener("squeezestart", () => handleFinalReviewXrTextPanelSqueezeStart(viewer, entry));
    controller.addEventListener("squeezeend", () => handleFinalReviewXrSqueezeEnd(viewer, entry));
    viewer.scene.add(controller, grip);
  }

  viewer.xrSessionStartHandler = () => {
    viewer.controls.enabled = false;
    attachFinalReviewTextPanelToPreferredXrHand(viewer);
    syncFinalReviewReaderUiVisibility(viewer);
  };
  viewer.xrSessionEndHandler = () => {
    endFinalReviewXrDirectManipulation(viewer);
    viewer.xrGrabEntry = null;
    viewer.xrGrabInput = null;
    viewer.xrScrollGesture = null;
    viewer.xrAttachedEntry = null;
    for (const entry of viewer.xrControllers.values()) setFinalReviewXrTextPanelRayState(viewer, entry, false);
    if (viewer.finalReviewTextGroup) {
      (viewer.readerHandRig?.panelAnchor || viewer.camera).add(viewer.finalReviewTextGroup);
      updateFinalReviewTextPanelViewport(viewer);
    }
    syncFinalReviewReaderUiVisibility(viewer);
    viewer.controls.enabled = true;
  };
  viewer.renderer.xr.addEventListener("sessionstart", viewer.xrSessionStartHandler);
  viewer.renderer.xr.addEventListener("sessionend", viewer.xrSessionEndHandler);

}

function createFinalReviewXrTextPanelRay() {
  const geometry = new THREE.BufferGeometry().setFromPoints([
    new THREE.Vector3(0, 0, 0),
    new THREE.Vector3(0, 0, -3.2),
  ]);
  const material = new THREE.LineBasicMaterial({ color: 0x6ed8c2, transparent: true, opacity: 0.68 });
  const ray = new THREE.Line(geometry, material);
  ray.name = "StoryVR Final Review text-panel ray";
  ray.visible = false;
  return ray;
}

function handleFinalReviewXrControllerConnected(viewer, entry, event) {
  const previousHand = entry.handedness;
  if (viewer.xrControllersByHand.get(previousHand) === entry) viewer.xrControllersByHand.delete(previousHand);
  entry.handedness = ["left", "right"].includes(event?.data?.handedness)
    ? event.data.handedness
    : (entry.index === 0 ? "left" : "right");
  entry.connected = true;
  entry.inputSource = event?.data || null;
  entry.anchor = event?.data?.gripSpace ? entry.grip : entry.controller;
  viewer.xrControllersByHand.set(entry.handedness, entry);
  if (viewer.renderer.xr.isPresenting) attachFinalReviewTextPanelToPreferredXrHand(viewer);
}

function handleFinalReviewXrControllerDisconnected(viewer, entry) {
  entry.connected = false;
  entry.inputSource = null;
  if (viewer.xrControllersByHand.get(entry.handedness) === entry) viewer.xrControllersByHand.delete(entry.handedness);
  endFinalReviewXrDirectManipulation(viewer, entry);
  if (viewer.xrGrabEntry === entry) {
    viewer.xrGrabEntry = null;
    viewer.xrGrabInput = null;
  }
  if (viewer.xrScrollGesture?.entry === entry) viewer.xrScrollGesture = null;
  if (viewer.xrAttachedEntry === entry) viewer.xrAttachedEntry = null;
  if (viewer.renderer.xr.isPresenting) attachFinalReviewTextPanelToPreferredXrHand(viewer);
}

function preferredFinalReviewXrTextPanelEntry(viewer) {
  const preferred = viewer.xrControllersByHand.get(viewer.xrPreferredHand);
  if (preferred?.connected) return preferred;
  const left = viewer.xrControllersByHand.get("left");
  if (left?.connected) return left;
  const right = viewer.xrControllersByHand.get("right");
  if (right?.connected) return right;
  return [...viewer.xrControllers.values()].find((entry) => entry.connected) || null;
}

function attachFinalReviewTextPanelToPreferredXrHand(viewer) {
  if (!viewer?.finalReviewTextGroup || viewer.xrGrabEntry) return false;
  const entry = preferredFinalReviewXrTextPanelEntry(viewer);
  if (!entry) return false;
  return attachFinalReviewTextPanelToXrHand(viewer, entry);
}

function attachFinalReviewTextPanelToXrHand(viewer, entry) {
  const group = viewer?.finalReviewTextGroup;
  if (!group || !entry?.connected) return false;
  const anchor = entry.anchor || entry.grip || entry.controller;
  if (group.parent !== anchor) anchor.add(group);
  const side = entry.handedness === "right" ? -1 : 1;
  group.position.set(0.105 * side, 0.115, -0.32);
  group.rotation.set(-0.16, -0.12 * side, 0);
  group.scale.set(1, 1, 1);
  viewer.xrAttachedEntry = entry;
  syncFinalReviewReaderUiVisibility(viewer);
  return true;
}

function finalReviewXrTextPanelActiveRoot(viewer) {
  const group = viewer?.finalReviewTextGroup;
  if (!group) return null;
  return viewer.textPanelMinimized ? group.userData.minimizedRoot : group.userData.expandedRoot;
}

function finalReviewXrTextPanelHit(viewer, entry) {
  if (!entry?.connected || !viewer?.finalReviewTextGroup?.visible || entry === viewer.xrAttachedEntry) return null;
  const target = finalReviewXrTextPanelActiveRoot(viewer);
  if (!target?.visible) return null;
  target.updateWorldMatrix(true, true);
  entry.controller.updateWorldMatrix(true, false);
  viewer.xrRayRotation.identity().extractRotation(entry.controller.matrixWorld);
  viewer.xrRaycaster.ray.origin.setFromMatrixPosition(entry.controller.matrixWorld);
  viewer.xrRaycaster.ray.direction.set(0, 0, -1).applyMatrix4(viewer.xrRayRotation).normalize();
  const hit = viewer.xrRaycaster.intersectObject(target, true)[0] || null;
  if (!hit) return null;
  let control = hit.object;
  while (control && control !== target.parent) {
    if (control.userData?.finalReviewTextPanelAction) {
      const declaredAction = control.userData.finalReviewTextPanelAction;
      return {
        action: declaredAction === "grab" ? "scroll" : declaredAction,
        disabled: control.userData.finalReviewTextPanelDisabled === true,
        control,
        uv: hit.uv?.clone?.() || hit.uv || null,
      };
    }
    control = control.parent;
  }
  return {
    action: viewer.textPanelMinimized ? "restore" : "scroll",
    disabled: false,
    control: hit.object,
    uv: hit.uv?.clone?.() || hit.uv || null,
  };
}

function finalReviewXrTextPanelScrollStartHit(viewer, entry) {
  const hit = finalReviewXrTextPanelHit(viewer, entry);
  if (hit) return hit;
  if (
    entry?.connected
    && entry === viewer?.xrAttachedEntry
    && viewer.finalReviewTextGroup?.visible
    && !viewer.textPanelMinimized
    && Number(viewer.textPagination?.maxScrollLine) > 0
  ) {
    return {
      action: "scroll",
      attachedController: true,
      disabled: false,
      control: viewer.finalReviewTextGroup?.userData?.contentMesh || null,
    };
  }
  return null;
}

function handleFinalReviewXrTextPanelSelectStart(viewer, entry) {
  const hit = finalReviewXrTextPanelScrollStartHit(viewer, entry);
  if (!hit) return false;
  if (hit.action === "minimize" || hit.action === "restore") {
    setFinalReviewTextPanelMinimized(viewer, hit.action === "minimize");
    return true;
  }
  if (hit.action === "variant-previous" || hit.action === "variant-next") {
    if (!hit.disabled) applyFinalReviewVariantSelection(hit.control.userData.finalReviewVariantTargetContext);
    return true;
  }
  if (hit.action === "scroll") return beginFinalReviewXrTextPanelScroll(viewer, entry, hit);
  return false;
}

function handleFinalReviewXrTextPanelSelectEnd(viewer, entry) {
  if (viewer?.xrScrollGesture?.entry !== entry) return false;
  viewer.xrScrollGesture = null;
  setFinalReviewXrTextPanelRayState(viewer, entry, false);
  return true;
}

function handleFinalReviewXrTextPanelSqueezeStart(viewer, entry) {
  if (finalReviewXrTextPanelHit(viewer, entry)) return beginFinalReviewXrTextPanelGrab(viewer, entry, "squeeze");
  return beginFinalReviewXrDirectManipulation(viewer, entry);
}

function beginFinalReviewXrTextPanelScroll(viewer, entry, hit) {
  const pagination = viewer?.textPagination;
  if (!viewer?.finalReviewTextGroup || !entry?.connected || hit?.action !== "scroll" || !pagination) return false;
  entry.controller.updateMatrixWorld(true, false);
  const controllerPosition = entry.controller.getWorldPosition(new THREE.Vector3());
  viewer.xrScrollGesture = {
    entry,
    startControllerY: controllerPosition.y,
    startLine: Number(viewer.textScrollLine) || 0,
    maxScrollLine: Math.max(Number(pagination.maxScrollLine) || 0, 0),
  };
  setFinalReviewXrTextPanelRayState(viewer, entry, true, "scroll");
  return true;
}

function updateFinalReviewXrTextPanelScroll(viewer) {
  const gesture = viewer?.xrScrollGesture;
  if (!gesture?.entry?.connected) return false;
  gesture.entry.controller.updateMatrixWorld(true, false);
  const controllerPosition = gesture.entry.controller.getWorldPosition(new THREE.Vector3());
  return setFinalReviewTextPanelScrollLine(
    viewer,
    finalReviewTextPanelScrollLineFromVerticalDrag(
      gesture.startLine,
      gesture.startControllerY,
      controllerPosition.y,
      gesture.maxScrollLine,
      FINAL_REVIEW_XR_TEXT_PANEL_HEIGHT,
    ),
  );
}

function finalReviewTextPanelScrollLineFromVerticalDrag(
  startLine,
  startControllerY,
  currentControllerY,
  maxScrollLine,
  panelHeight,
) {
  const maximum = Math.max(Number(maxScrollLine) || 0, 0);
  const normalizedDrag = ((Number(startControllerY) || 0) - (Number(currentControllerY) || 0))
    / Math.max(Number(panelHeight) || 0, 0.01);
  return THREE.MathUtils.clamp(
    Math.round((Number(startLine) || 0) + (normalizedDrag * maximum)),
    0,
    maximum,
  );
}

function beginFinalReviewXrTextPanelGrab(viewer, entry, input = "squeeze") {
  if (!viewer?.finalReviewTextGroup || !entry?.connected || viewer.xrGrabEntry || viewer.xrDirectManipulationGrab) return false;
  viewer.xrGrabEntry = entry;
  viewer.xrGrabInput = input;
  entry.controller.attach(viewer.finalReviewTextGroup);
  setFinalReviewXrTextPanelRayState(viewer, entry, true, "grab");
  return true;
}

function handleFinalReviewXrTextPanelGrabEnd(viewer, entry, input) {
  if (viewer?.xrGrabEntry !== entry || viewer.xrGrabInput !== input) return false;
  viewer.xrPreferredHand = entry.handedness;
  viewer.xrGrabEntry = null;
  viewer.xrGrabInput = null;
  attachFinalReviewTextPanelToXrHand(viewer, entry);
  setFinalReviewXrTextPanelRayState(viewer, entry, false);
  return true;
}

function finalReviewXrDirectManipulationHit(viewer, entry) {
  if (!entry?.connected) return null;
  const roots = [...new Set((viewer?.directManipulationTargets || []).map((target) => target.root).filter(Boolean))];
  if (!roots.length) return null;
  entry.controller.updateWorldMatrix(true, false);
  viewer.xrRayRotation.identity().extractRotation(entry.controller.matrixWorld);
  viewer.xrRaycaster.ray.origin.setFromMatrixPosition(entry.controller.matrixWorld);
  viewer.xrRaycaster.ray.direction.set(0, 0, -1).applyMatrix4(viewer.xrRayRotation).normalize();
  const hit = viewer.xrRaycaster.intersectObjects(roots, true)[0] || null;
  if (!hit) return null;
  const targetRoots = new Set(roots);
  let root = hit.object;
  while (root && !targetRoots.has(root)) root = root.parent;
  return root ? { action: "direct-manipulation", root, object: hit.object, point: hit.point } : null;
}

function beginFinalReviewXrDirectManipulation(viewer, entry) {
  if (!entry?.connected || viewer?.xrGrabEntry || viewer?.xrDirectManipulationGrab) return false;
  const hit = finalReviewXrDirectManipulationHit(viewer, entry);
  if (!hit?.root?.parent) return false;
  viewer.xrDirectManipulationGrab = {
    entry,
    root: hit.root,
    originalParent: hit.root.parent,
  };
  for (const cue of viewer.directManipulationCues || []) {
    if (cue.root !== hit.root) continue;
    cue.phase = "idle";
    cue.phaseStartedAt = viewer.directManipulationCueElapsed;
    cue.ghost.visible = false;
  }
  entry.controller.attach(hit.root);
  setFinalReviewXrTextPanelRayState(viewer, entry, true, "grab");
  return true;
}

function endFinalReviewXrDirectManipulation(viewer, entry = null) {
  const grab = viewer?.xrDirectManipulationGrab;
  if (!grab || (entry && grab.entry !== entry)) return false;
  grab.originalParent?.attach?.(grab.root);
  grab.root?.updateMatrixWorld?.(true);
  viewer.xrDirectManipulationGrab = null;
  setFinalReviewXrTextPanelRayState(viewer, grab.entry, false);
  return true;
}

function handleFinalReviewXrSqueezeEnd(viewer, entry) {
  if (endFinalReviewXrDirectManipulation(viewer, entry)) return true;
  return handleFinalReviewXrTextPanelGrabEnd(viewer, entry, "squeeze");
}

function updateFinalReviewXrTextPanelRays(viewer) {
  if (!viewer?.renderer?.xr?.isPresenting) return;
  updateFinalReviewXrTextPanelScroll(viewer);
  for (const entry of viewer.xrControllers.values()) {
    const hit = viewer.xrScrollGesture?.entry === entry
      ? { action: "scroll" }
      : viewer.xrGrabEntry === entry || viewer.xrDirectManipulationGrab?.entry === entry
        ? { action: "grab" }
        : finalReviewXrTextPanelScrollStartHit(viewer, entry) || finalReviewXrDirectManipulationHit(viewer, entry);
    setFinalReviewXrTextPanelRayState(viewer, entry, Boolean(hit), hit?.action || "", hit?.disabled === true);
  }
}

function setFinalReviewXrTextPanelRayState(viewer, entry, active, action = "", disabled = false) {
  const ray = entry?.controller?.getObjectByName("StoryVR Final Review text-panel ray");
  if (!ray) return;
  ray.visible = Boolean(viewer?.renderer?.xr?.isPresenting && entry.connected && active);
  ray.material.color.setHex(disabled ? 0x76817d : action === "minimize" || action === "restore" ? 0xe5aa63 : 0x6ed8c2);
  ray.material.opacity = active ? 0.92 : 0.68;
}

function loadFinalReviewAsset(viewer, asset, finishAsset) {
  const spatialEntity = lockedSpatialGlbEntityForViewer(viewer, asset.id);
  const finalReviewFraming = finalReviewSpatialFraming(viewer, spatialEntity);
  const topologyWrapper = new THREE.Group();
  topologyWrapper.name = `StoryVR topology anchor · ${asset.id}`;
  topologyWrapper.position.set(0, finalReviewFraming?.anchorY ?? 0.2, 0);
  const authorWrapper = new THREE.Group();
  authorWrapper.name = `StoryVR author transform · ${asset.id}`;
  authorWrapper.userData.assetId = asset.id;
  authorWrapper.userData.spatialEntityId = spatialEntity?.id || "";
  const group = new THREE.Group();
  topologyWrapper.add(authorWrapper);
  authorWrapper.add(group);
  viewer.root.add(topologyWrapper);
  applyLockedSpatialGlbTransform(viewer, asset.id, authorWrapper, spatialEntity);
  viewer.activeAssetAuthorWrapper = authorWrapper;
  viewer.activeAssetTopologyWrapper = topologyWrapper;
  viewer.activeAssetGroup = group;
  viewer.finalReviewAssetEntry = {
    assetId: asset.id,
    entityId: spatialEntity?.id || "",
    topologyWrapper,
    authorWrapper,
    group,
    sourceScene: null,
  };
  const placeholder = viewer.suppressSceneLabels ? null : makeTopologyPlaceholder(asset.id, "Active reader-visible asset", 0xf0c897);
  if (placeholder) group.add(placeholder);
  const url = assetLoadSrc(asset);
  if (!url) {
    finishAsset(false);
    return;
  }
  if (isModelAsset(asset)) {
    createGltfLoader().load(
      url,
      (gltf) => {
        if (viewer.disposed) {
          disposeObject(gltf.scene);
          return;
        }
        if (placeholder) {
          group.remove(placeholder);
          disposeObject(placeholder);
        }
        applySpatialLoaderTransformPolicy(gltf.scene, spatialEntity);
        if (spatialEntity?.preserveSourceGeometry !== true) {
          if (finalReviewFraming) {
            normalizeSpatialRuntimeObject(
              gltf.scene,
              finalReviewFraming.targetSize,
              finalReviewFraming.verticalAlignment,
            );
          } else {
            normalizeTopologyObject(gltf.scene, 1.12);
          }
        }
        group.add(gltf.scene);
        viewer.finalReviewAssetEntry.sourceScene = gltf.scene;
        attachProceduralDynamicsPreviewMotion(viewer, viewer.finalReviewAssetEntry, gltf);
        attachFinalReviewSourcePlayback(viewer, viewer.finalReviewAssetEntry, gltf);
        finishAsset(true);
      },
      undefined,
      () => finishAsset(false),
    );
    return;
  }
  const imageSrc = assetPreviewSrc(asset);
  if (imageSrc) {
    new THREE.TextureLoader().load(
      imageSrc,
      (texture) => {
        if (viewer.disposed) {
          texture.dispose();
          return;
        }
        texture.colorSpace = THREE.SRGBColorSpace;
        if (placeholder) {
          group.remove(placeholder);
          disposeObject(placeholder);
        }
        const plane = makeTopologyImagePlane(texture, 1.05);
        group.add(plane);
        viewer.finalReviewAssetEntry.sourceScene = plane;
        finishAsset(true);
      },
      undefined,
      () => finishAsset(false),
    );
    return;
  }
  finishAsset(false);
}

function interactionControllerModelUrl(hand) {
  return `${INTERACTION_CONTROLLER_MODEL_PATH}${hand === "left" ? "left" : "right"}.glb`;
}

function interactionControllerComponentCenter(root, nodeName) {
  const component = nodeName ? root.getObjectByName(nodeName) : null;
  if (!component) return null;
  const bounds = new THREE.Box3().setFromObject(component);
  return bounds.isEmpty() ? null : bounds.getCenter(new THREE.Vector3());
}

function cacheInteractionControllerHotspotProjections(viewer) {
  if (!viewer?.modelRoot) return [];
  viewer.modelRoot.updateWorldMatrix(true, true);
  const connectorById = new Map(
    [...viewer.container.querySelectorAll("[data-controller-model-connector]")]
      .map((connector) => [connector.dataset.controllerModelConnector, connector]),
  );
  return [...viewer.container.querySelectorAll("[data-controller-model-node]")].map((hotspot) => {
    const center = interactionControllerComponentCenter(viewer.modelRoot, hotspot.dataset.controllerModelNode);
    if (!center) return null;
    return {
      hotspot,
      connector: connectorById.get(hotspot.dataset.controllerHotspot) || null,
      center,
      projectedCenter: new THREE.Vector3(),
    };
  }).filter(Boolean);
}

function projectInteractionControllerHotspots(viewer) {
  for (const projection of viewer?.hotspotProjections || []) {
    projection.projectedCenter.copy(projection.center).project(viewer.camera);
    const x = THREE.MathUtils.clamp((projection.projectedCenter.x * 0.5 + 0.5) * 100, 8, 92);
    const y = THREE.MathUtils.clamp((-projection.projectedCenter.y * 0.5 + 0.5) * 100, 8, 92);
    const { hotspot, connector } = projection;
    hotspot.style.setProperty("--hotspot-x", `${x}%`);
    hotspot.style.setProperty("--hotspot-y", `${y}%`);
    connector?.setAttribute("x2", String(x));
    connector?.setAttribute("y2", String(y));
  }
}

function highlightInteractionControllerComponents(viewer) {
  const accent = new THREE.Color(0x007f73);
  for (const hotspot of viewer.container.querySelectorAll(".controller-model-hotspot.mapped[data-controller-model-node]")) {
    const component = viewer.modelRoot.getObjectByName(hotspot.dataset.controllerModelNode);
    component?.traverse((object) => {
      if (!object.isMesh || !object.material) return;
      const materials = (Array.isArray(object.material) ? object.material : [object.material]).map((material) => {
        const highlighted = material.clone();
        highlighted.color?.lerp(accent, 0.56);
        if (highlighted.emissive) {
          highlighted.emissive.copy(accent);
          highlighted.emissiveIntensity = 0.22;
        }
        return highlighted;
      });
      object.material = Array.isArray(object.material) ? materials : materials[0];
    });
  }
}

function fitInteractionControllerCamera(viewer) {
  const bounds = new THREE.Box3().setFromObject(viewer.modelRoot);
  if (bounds.isEmpty()) return;
  const sphere = bounds.getBoundingSphere(new THREE.Sphere());
  const distance = sphere.radius / Math.sin(THREE.MathUtils.degToRad(viewer.camera.fov * 0.5)) * 1.12;
  const direction = new THREE.Vector3(viewer.hand === "left" ? 0.28 : -0.28, 2.35, -1.4).normalize();
  viewer.camera.up.set(0, 0, -1);
  viewer.camera.position.copy(sphere.center).addScaledVector(direction, distance);
  viewer.camera.near = Math.max(distance / 100, 0.001);
  viewer.camera.far = Math.max(distance * 20, 2);
  viewer.camera.updateProjectionMatrix();
  viewer.controls.target.copy(sphere.center);
  viewer.controls.minDistance = distance * 0.72;
  viewer.controls.maxDistance = distance * 1.55;
  viewer.controls.update();
}

function initializeInteractionControllerModel(container) {
  const hand = container.dataset.controllerHand === "left" ? "left" : "right";
  const width = Math.max(container.clientWidth, 180);
  const height = Math.max(container.clientHeight, 250);
  const scene = new THREE.Scene();
  const camera = new THREE.PerspectiveCamera(30, width / height, 0.001, 10);
  const renderer = new THREE.WebGLRenderer({ antialias: true, alpha: true });
  renderer.setPixelRatio(Math.min(window.devicePixelRatio || 1, 2));
  renderer.setSize(width, height);
  renderer.setClearColor(0x000000, 0);
  renderer.outputColorSpace = THREE.SRGBColorSpace;
  renderer.toneMapping = THREE.ACESFilmicToneMapping;
  renderer.toneMappingExposure = 1.16;
  renderer.domElement.className = "interaction-controller-model-canvas";
  renderer.domElement.setAttribute("aria-hidden", "true");
  container.prepend(renderer.domElement);

  scene.add(new THREE.HemisphereLight(0xffffff, 0x4f5c59, 3.4));
  const key = new THREE.DirectionalLight(0xffffff, 5.2);
  key.position.set(hand === "left" ? 3 : -3, 5, -4);
  scene.add(key);
  const fill = new THREE.DirectionalLight(0x9edfd5, 2.1);
  fill.position.set(hand === "left" ? -4 : 4, 1, 3);
  scene.add(fill);

  const controls = new OrbitControls(camera, renderer.domElement);
  controls.enableDamping = true;
  controls.dampingFactor = 0.08;
  controls.enablePan = false;
  controls.enableZoom = true;
  controls.rotateSpeed = 0.58;
  controls.zoomSpeed = 0.7;
  configureSpatialEditorMouseControls(controls);

  const viewer = {
    container,
    hand,
    scene,
    camera,
    renderer,
    controls,
    modelRoot: null,
    hotspotProjections: [],
    animationId: null,
    requestFrame: null,
    resizeObserver: null,
    disposed: false,
  };
  interactionControllerModelViewers.push(viewer);

  const requestFrame = () => {
    if (viewer.disposed || viewer.animationId !== null) return;
    viewer.animationId = requestAnimationFrame(() => {
      viewer.animationId = null;
      if (viewer.disposed) return;
      controls.update();
      renderer.render(scene, camera);
      projectInteractionControllerHotspots(viewer);
    });
  };
  viewer.requestFrame = requestFrame;
  controls.addEventListener("change", requestFrame);

  const drawImmediately = () => {
    if (viewer.disposed) return;
    renderer.render(scene, camera);
    projectInteractionControllerHotspots(viewer);
  };

  const resize = () => {
    if (viewer.disposed) return;
    const nextWidth = Math.max(container.clientWidth, 180);
    const nextHeight = Math.max(container.clientHeight, 250);
    camera.aspect = nextWidth / nextHeight;
    camera.updateProjectionMatrix();
    renderer.setSize(nextWidth, nextHeight);
    requestFrame();
  };
  viewer.resizeObserver = new ResizeObserver(resize);
  viewer.resizeObserver.observe(container);

  createGltfLoader().load(interactionControllerModelUrl(hand), (gltf) => {
    if (viewer.disposed) {
      disposeObject(gltf.scene);
      return;
    }
    viewer.modelRoot = gltf.scene;
    viewer.modelRoot.name = `Meta Quest 3 Touch Plus · ${hand}`;
    viewer.modelRoot.traverse((object) => {
      if (!object.isMesh) return;
      object.castShadow = true;
      const materials = Array.isArray(object.material) ? object.material : [object.material];
      for (const material of materials) {
        if (material.map) material.map.anisotropy = Math.min(8, renderer.capabilities.getMaxAnisotropy());
      }
    });
    scene.add(viewer.modelRoot);
    viewer.hotspotProjections = cacheInteractionControllerHotspotProjections(viewer);
    highlightInteractionControllerComponents(viewer);
    fitInteractionControllerCamera(viewer);
    container.querySelector("[data-controller-model-status]")?.remove();
    container.classList.add("loaded");
    requestFrame();
  }, undefined, () => {
    if (viewer.disposed) return;
    const status = container.querySelector("[data-controller-model-status]");
    if (status) status.textContent = "Controller model unavailable";
    container.classList.add("error");
  });
  drawImmediately();
}

function initializeInteractionControllerModels(active) {
  if (active?.id !== "interaction-control") return;
  for (const container of document.querySelectorAll("[data-interaction-controller-model]")) {
    initializeInteractionControllerModel(container);
  }
}

function disposeInteractionControllerModelViewers() {
  for (const viewer of interactionControllerModelViewers) {
    viewer.disposed = true;
    if (viewer.animationId !== null) cancelAnimationFrame(viewer.animationId);
    viewer.resizeObserver?.disconnect();
    if (viewer.requestFrame) viewer.controls?.removeEventListener("change", viewer.requestFrame);
    viewer.controls?.dispose();
    disposeObject(viewer.scene);
    viewer.renderer?.dispose();
    viewer.renderer?.forceContextLoss?.();
  }
  interactionControllerModelViewers = [];
}

function addFinalReviewDuplicateModels(viewer, sourceModel) {
  const count = 5;
  for (let index = 0; index < count; index += 1) {
    const angle = (Math.PI * 2 * index) / count;
    const group = new THREE.Group();
    group.position.set(Math.cos(angle) * 1.02, 0.17 + (index % 2) * 0.08, Math.sin(angle) * 0.82);
    group.rotation.y = -angle + Math.PI;
    const clone = sourceModel.clone(true);
    clone.scale.multiplyScalar(0.34 + (index % 3) * 0.045);
    group.add(clone);
    viewer.root.add(group);
    viewer.duplicateGroups.push({ group, angle, radiusX: 1.02, radiusZ: 0.82, bobOffset: index * 0.72 });
  }
}

function addFinalReviewTextOnlyState(viewer, beat, region) {
  return null;
}

function addFinalReviewTextPanel(viewer, beat, region) {
  const group = new THREE.Group();
  group.name = "StoryVR hand text panel · Final Review";
  group.userData.attachmentPolicy = "reader-hand";

  const expandedRoot = new THREE.Group();
  expandedRoot.name = "StoryVR hand text panel expanded · Final Review";
  const variantState = finalReviewTextPanelVariantState(beat, viewer.sceneContext);
  const texture = makeFinalReviewTextTexture(beat, region, variantState, viewer.textScrollLine);
  const panel = new THREE.Mesh(
    new THREE.PlaneGeometry(FINAL_REVIEW_XR_TEXT_PANEL_WIDTH, FINAL_REVIEW_XR_TEXT_PANEL_HEIGHT),
    new THREE.MeshBasicMaterial({
      map: texture,
      transparent: true,
      side: THREE.DoubleSide,
      depthTest: false,
      depthWrite: false,
      toneMapped: false,
    }),
  );
  panel.renderOrder = READER_UI_RENDER_ORDER;
  panel.userData.finalReviewTextPanelAction = "scroll";
  expandedRoot.add(panel);

  const desktopGrabHandle = new THREE.Mesh(
    new THREE.PlaneGeometry(
      FINAL_REVIEW_XR_TEXT_PANEL_WIDTH * 0.78,
      FINAL_REVIEW_XR_TEXT_PANEL_HEIGHT * 0.22,
    ),
    new THREE.MeshBasicMaterial({
      transparent: true,
      opacity: 0,
      depthTest: false,
      depthWrite: false,
    }),
  );
  desktopGrabHandle.name = "StoryVR Final Review desktop title drag handle";
  desktopGrabHandle.position.set(
    -FINAL_REVIEW_XR_TEXT_PANEL_WIDTH * 0.055,
    FINAL_REVIEW_XR_TEXT_PANEL_HEIGHT * 0.37,
    0.006,
  );
  desktopGrabHandle.userData.finalReviewTextPanelAction = "grab";
  expandedRoot.add(desktopGrabHandle);

  const minimizeButton = makeFinalReviewTextPanelControl("\u2212", "minimize", 0.052);
  minimizeButton.position.set(
    (FINAL_REVIEW_XR_TEXT_PANEL_WIDTH / 2) - 0.034,
    (FINAL_REVIEW_XR_TEXT_PANEL_HEIGHT / 2) - 0.034,
    0.004,
  );
  expandedRoot.add(minimizeButton);

  const variantControlRoot = new THREE.Group();
  variantControlRoot.name = "StoryVR hand text panel variant controls · Final Review";
  const variantPreviousButton = variantState && !variantState.previousDisabled
    ? makeFinalReviewTextPanelButton(
      variantState.previousPresentation || { label: "Previous", position: [0.2, 0.86], size: [0.32, 0.12] },
      "variant-previous",
      variantState.previousTargetContext || null,
      false,
    )
    : null;
  const variantNextButton = variantState && !variantState.nextDisabled
    ? makeFinalReviewTextPanelButton(
      variantState.nextPresentation || { label: "Next", position: [0.8, 0.86], size: [0.32, 0.12] },
      "variant-next",
      variantState.nextTargetContext || null,
      false,
    )
    : null;
  for (const button of [variantPreviousButton, variantNextButton]) {
    if (button) variantControlRoot.add(button);
  }
  variantControlRoot.visible = variantControlRoot.children.length > 0;
  expandedRoot.add(variantControlRoot);

  const minimizedRoot = new THREE.Group();
  minimizedRoot.name = "StoryVR hand text panel minimized · Final Review";
  const restoreButton = makeFinalReviewTextPanelControl("Aa", "restore", 0.105);
  minimizedRoot.add(restoreButton);
  group.add(expandedRoot, minimizedRoot);
  group.userData.expandedRoot = expandedRoot;
  group.userData.minimizedRoot = minimizedRoot;
  group.userData.contentMesh = panel;
  group.userData.desktopGrabHandle = desktopGrabHandle;
  group.userData.minimizeButton = minimizeButton;
  group.userData.variantControlRoot = variantControlRoot;
  group.userData.variantPreviousButton = variantPreviousButton;
  group.userData.variantNextButton = variantNextButton;
  group.userData.restoreButton = restoreButton;

  viewer.textPanel = group;
  viewer.textPagination = texture.userData.storyvrTextPanelPagination;
  viewer.textScrollLine = viewer.textPagination.scrollLine;
  viewer.textContent = { beat, region, variantState };
  viewer.textOrientationPolicy = "reader-hand";
  (viewer.readerHandRig?.panelAnchor || viewer.camera).add(group);
  viewer.finalReviewTextGroup = group;
  updateFinalReviewTextPanelViewport(viewer);
  setFinalReviewTextPanelMinimized(viewer, state.finalReviewTextPanelMinimized);
  if (viewer.renderer?.xr?.isPresenting) attachFinalReviewTextPanelToPreferredXrHand(viewer);
  syncFinalReviewReaderUiVisibility(viewer);
}

function setFinalReviewTextPanelScrollLine(viewer, value) {
  const content = viewer?.textContent;
  const pagination = viewer?.textPagination;
  const material = viewer?.finalReviewTextGroup?.userData?.contentMesh?.material;
  if (!content || !pagination || !material) return false;
  const scrollLine = Math.max(0, Math.min(pagination.maxScrollLine, Math.round(Number(value) || 0)));
  if (scrollLine === viewer.textScrollLine) return false;
  const texture = makeFinalReviewTextTexture(
    content.beat,
    content.region,
    content.variantState,
    scrollLine,
  );
  material.map?.dispose?.();
  material.map = texture;
  material.needsUpdate = true;
  viewer.textPagination = texture.userData.storyvrTextPanelPagination;
  viewer.textScrollLine = viewer.textPagination.scrollLine;
  return true;
}

function makeFinalReviewTextPanelButton(presentation, action, targetContext, disabled) {
  const safePresentation = normalizeTextPanelActionPresentation(presentation);
  const widthRatio = safePresentation.size[0];
  const heightRatio = safePresentation.size[1];
  const [x, y] = safePresentation.position;
  const label = safePresentation.label;
  const mesh = new THREE.Mesh(
    new THREE.PlaneGeometry(
      FINAL_REVIEW_XR_TEXT_PANEL_WIDTH * widthRatio,
      FINAL_REVIEW_XR_TEXT_PANEL_HEIGHT * heightRatio,
    ),
    new THREE.MeshBasicMaterial({
      map: makeFinalReviewTextPanelButtonTexture(label),
      color: disabled ? 0x76817d : 0xffffff,
      opacity: disabled ? 0.48 : 1,
      transparent: true,
      side: THREE.DoubleSide,
      depthTest: false,
      depthWrite: false,
      toneMapped: false,
    }),
  );
  mesh.renderOrder = READER_UI_RENDER_ORDER + 2;
  mesh.position.set(
    (x - 0.5) * FINAL_REVIEW_XR_TEXT_PANEL_WIDTH,
    (0.5 - y) * FINAL_REVIEW_XR_TEXT_PANEL_HEIGHT,
    0.006,
  );
  mesh.name = `${label} variant UI button · Final Review`;
  mesh.userData.finalReviewTextPanelAction = action;
  mesh.userData.finalReviewTextPanelDisabled = Boolean(disabled);
  mesh.userData.finalReviewVariantTargetContext = targetContext;
  mesh.userData.finalReviewTextPanelLabel = label;
  mesh.userData.finalReviewTextPanelButtonId = safePresentation.id || null;
  return mesh;
}

function canvasEllipsizedText(ctx, text, maxWidth) {
  const value = String(text || "");
  if (ctx.measureText(value).width <= maxWidth) return value;
  const characters = Array.from(value);
  let lower = 0;
  let upper = characters.length;
  let fitted = "…";
  while (lower <= upper) {
    const middle = Math.floor((lower + upper) / 2);
    const candidate = `${characters.slice(0, middle).join("").trimEnd()}…`;
    if (ctx.measureText(candidate).width <= maxWidth) {
      fitted = candidate;
      lower = middle + 1;
    } else {
      upper = middle - 1;
    }
  }
  return fitted;
}

function makeFinalReviewTextPanelButtonTexture(label) {
  const canvas = document.createElement("canvas");
  canvas.width = 512;
  canvas.height = 160;
  const context = canvas.getContext("2d");
  context.clearRect(0, 0, canvas.width, canvas.height);
  context.fillStyle = "rgba(8, 22, 19, 0.98)";
  context.fillRect(8, 8, canvas.width - 16, canvas.height - 16);
  context.lineWidth = 10;
  context.strokeStyle = "rgba(110, 216, 194, 0.96)";
  context.strokeRect(8, 8, canvas.width - 16, canvas.height - 16);
  context.fillStyle = "#f6f2e7";
  const buttonLabel = shortText(label || "Select", 80);
  const maximumLabelWidth = canvas.width - 56;
  let fontSize = 58;
  context.font = `800 ${fontSize}px sans-serif`;
  while (fontSize > 24 && context.measureText(buttonLabel).width > maximumLabelWidth) {
    fontSize -= 2;
    context.font = `800 ${fontSize}px sans-serif`;
  }
  const fittedLabel = canvasEllipsizedText(context, buttonLabel, maximumLabelWidth);
  context.textAlign = "center";
  context.textBaseline = "middle";
  context.fillText(fittedLabel, canvas.width / 2, (canvas.height / 2) + 3, maximumLabelWidth);
  const texture = new THREE.CanvasTexture(canvas);
  texture.colorSpace = THREE.SRGBColorSpace;
  return texture;
}

function makeFinalReviewTextPanelControl(label, action, size) {
  const canvas = document.createElement("canvas");
  canvas.width = 192;
  canvas.height = 192;
  const context = canvas.getContext("2d");
  context.clearRect(0, 0, canvas.width, canvas.height);
  context.fillStyle = "rgba(8, 22, 19, 0.98)";
  context.beginPath();
  context.arc(96, 96, 82, 0, Math.PI * 2);
  context.fill();
  context.lineWidth = 10;
  context.strokeStyle = "rgba(110, 216, 194, 0.96)";
  context.stroke();
  context.fillStyle = "#f6f2e7";
  context.font = label === "Aa" ? "800 66px sans-serif" : "800 108px sans-serif";
  context.textAlign = "center";
  context.textBaseline = "middle";
  context.fillText(label, 96, label === "Aa" ? 100 : 88);
  const texture = new THREE.CanvasTexture(canvas);
  texture.colorSpace = THREE.SRGBColorSpace;
  const mesh = new THREE.Mesh(
    new THREE.PlaneGeometry(size, size),
    new THREE.MeshBasicMaterial({
      map: texture,
      transparent: true,
      side: THREE.DoubleSide,
      depthTest: false,
      depthWrite: false,
      toneMapped: false,
    }),
  );
  mesh.renderOrder = READER_UI_RENDER_ORDER + 2;
  mesh.name = `${label === "Aa" ? "Restore" : "Minimize"} text panel · Final Review`;
  mesh.userData.finalReviewTextPanelAction = action;
  return mesh;
}

function setFinalReviewTextPanelMinimized(viewer, minimized) {
  const nextMinimized = Boolean(minimized);
  state.finalReviewTextPanelMinimized = nextMinimized;
  const panelGroup = viewer?.finalReviewTextGroup;
  if (!panelGroup) return;
  panelGroup.userData.expandedRoot.visible = !nextMinimized;
  panelGroup.userData.minimizedRoot.visible = nextMinimized;
  panelGroup.userData.minimized = nextMinimized;
  viewer.textPanelMinimized = nextMinimized;
}

function updateFinalReviewSceneBeat(viewer, beat, region, activeAssetId = null) {
  if (!viewer || viewer.disposed) return;
  viewer.beat = beat;
  viewer.region = region;
  viewer.activeAssetId = activeAssetId;
  viewer.textScrollLine = 0;
  viewer.textPagination = null;
  viewer.textContent = null;
  viewer.xrScrollGesture = null;

  if (viewer.finalReviewTextGroup) {
    viewer.finalReviewTextGroup.removeFromParent();
    disposeObject(viewer.finalReviewTextGroup);
    viewer.finalReviewTextGroup = null;
    viewer.textPanel = null;
  }
  addFinalReviewTextPanel(viewer, beat, region);

  updatePreviewMetadataEntry(viewer, "beat", shortText(beat?.title || "", 52));
  const activeLink = viewer.cumulativeContext?.sequence?.steps?.[viewer.activeSwapIndex]
    || (activeAssetId ? { assetId: activeAssetId } : null);
  updatePreviewMetadataEntry(viewer, "active-asset", previewAssetDisplayName(activeLink));
  refreshFinalReviewDirectManipulationCues(viewer);
}

function finalReviewActiveProgressionBoundary(viewer = finalReviewViewer) {
  const sceneContext = viewer?.sceneContext || state.selectedFinalReviewSceneContext;
  const beatId = String(sceneContext?.beatId || viewer?.beat?.id || "");
  if (!beatId) return null;
  const boundaryContext = interactionBoundaryContext(selectedInteractionControlBase(), sceneContext);
  return boundaryContext.boundaries.find((boundary) => (
    boundary.fromBeatId === beatId
    && sourceGraphTransitionContextMatches(boundary.fromContext, sceneContext || interactionSceneContextForBeat(beatId))
  )) || boundaryContext.boundaries.find((boundary) => (
    boundary.fromBeatId === beatId && !boundary.fromContext?.variantOptionId
  )) || null;
}

function finalReviewActiveProgressionPlayback(boundary) {
  if (!boundary?.toContext?.beatId) return null;
  const transitionEdgeId = boundary.edgeId || boundary.edge?.id || "";
  return interBeatBoundaryPlaybackSummary(
    selectedComponentPreview(componentById("inter-beat-dynamics")),
    {
      ...boundary.toContext,
      ...(transitionEdgeId ? { transitionEdgeId } : {}),
    },
  );
}

function finalReviewDirectManipulationConfigurations(viewer) {
  const beatId = String(viewer?.beat?.id || "");
  if (!beatId) return [];
  const configurations = [];
  const outgoingBoundary = finalReviewActiveProgressionBoundary(viewer);
  if (
    recognizedInteractionPolicyKind(outgoingBoundary?.effectivePolicy) === "direct"
    && interactionKindForConfiguration(outgoingBoundary?.configuration) === "direct"
  ) {
    configurations.push(outgoingBoundary.configuration);
  }

  const sceneContext = viewer.sceneContext;
  if (sceneContext?.variantOptionId) {
    for (const edge of interactionVariantSwitchEdges()) {
      if (
        edge?.from?.beatId !== beatId
        || edge?.from?.variantGroupId !== sceneContext.variantGroupId
        || edge?.from?.variantOptionId !== sceneContext.variantOptionId
      ) continue;
      const record = interactionVariantEdgeControlForEdge(edge);
      if (
        variantInteractionPolicyKind(record.effectivePolicy) === "direct"
        && interactionKindForConfiguration(record.configuration) === "direct"
      ) {
        configurations.push(record.configuration);
      }
    }
  }
  return configurations;
}

function finalReviewDirectTargetCandidates(viewer) {
  const entries = [
    ...(viewer?.dynamicObjects || []),
    ...(viewer?.swapGroups || []).filter(Boolean),
    viewer?.finalReviewAssetEntry || null,
  ].filter(Boolean);
  const candidates = [];
  const seen = new Set();
  for (const entry of entries) {
    if (entry.group?.visible === false || !entry.authorWrapper || seen.has(entry.authorWrapper)) continue;
    const assetId = String(entry.assetId || entry.step?.assetId || entry.authorWrapper.userData?.assetId || "");
    const entityId = String(
      entry.entityId
      || entry.step?.entityId
      || entry.authorWrapper.userData?.spatialEntityId
      || lockedSpatialGlbEntityForViewer(viewer, assetId)?.id
      || "",
    );
    if (!assetId && !entityId) continue;
    seen.add(entry.authorWrapper);
    candidates.push({
      assetId,
      entityId,
      root: entry.authorWrapper,
      sceneRoot: entry.sourceScene || entry.modelRoot || entry.authorWrapper,
    });
  }
  return candidates;
}

function finalReviewDirectRootForTarget(target, candidates) {
  const assetId = String(target?.assetId || "");
  const entityId = String(target?.entityId || "");
  if (!assetId && !entityId) return null;
  const candidate = candidates.find((entry) => (
    (!assetId || entry.assetId === assetId)
    && (!entityId || entry.entityId === entityId)
  )) || null;
  if (!candidate || !target?.nodePath) return candidate;
  const selector = String(target.nodePath).trim();
  const normalizedSelector = selector.replace(/^\/+|\/+$/g, "").toLowerCase();
  if (!normalizedSelector || !candidate.sceneRoot?.traverse) return null;
  const exact = [];
  const compatible = [];
  candidate.sceneRoot.traverse((object) => {
    if (!object?.parent || object.isBone || object.isSkinnedMesh) return;
    const path = sourcePartNodePath(object, candidate.sceneRoot).toLowerCase();
    if (path === normalizedSelector || String(object.name || "").toLowerCase() === normalizedSelector) exact.push(object);
    else if (sourcePartSelectorMatchesNode(selector, object, candidate.sceneRoot)) compatible.push(object);
  });
  const root = exact[0] || compatible[0] || null;
  return root ? { ...candidate, root, nodePath: selector } : null;
}

function finalReviewObjectWorldTransform(root) {
  if (!root) return null;
  root.updateWorldMatrix(true, true);
  const position = new THREE.Vector3();
  const quaternion = new THREE.Quaternion();
  const scale = new THREE.Vector3();
  root.matrixWorld.decompose(position, quaternion, scale);
  return { position, quaternion: quaternion.normalize(), scale };
}

function finalReviewDirectDestinationWorldTransform(root, target) {
  if (!root || !target?.destinationTransform) return null;
  const transform = normalizeSpatialTransform(target.destinationTransform);
  const local = target.coordinateSpace === "local";
  const current = local
    ? { position: root.position.clone(), quaternion: root.quaternion.clone(), scale: root.scale.clone() }
    : finalReviewObjectWorldTransform(root);
  const position = interactionDirectUsesTriggerComponent(target, "position")
    ? new THREE.Vector3().fromArray(transform.position)
    : current.position.clone();
  const quaternion = interactionDirectUsesTriggerComponent(target, "rotation")
    ? new THREE.Quaternion().fromArray(transform.quaternion).normalize()
    : current.quaternion.clone();
  const scale = interactionDirectUsesTriggerComponent(target, "scale")
    ? new THREE.Vector3().fromArray(transform.scale)
    : current.scale.clone();
  const matrix = new THREE.Matrix4().compose(position, quaternion, scale);
  if (local && root.parent) {
    root.parent.updateWorldMatrix(true, false);
    matrix.premultiply(root.parent.matrixWorld);
  }
  matrix.decompose(position, quaternion, scale);
  return { position, quaternion: quaternion.normalize(), scale };
}

function finalReviewDirectGhostTravelSeconds(distanceMeters) {
  return THREE.MathUtils.clamp(
    Math.max(0, Number(distanceMeters) || 0) / FINAL_REVIEW_DIRECT_GHOST_VELOCITY_METERS_PER_SECOND,
    FINAL_REVIEW_DIRECT_GHOST_MIN_TRAVEL_SECONDS,
    FINAL_REVIEW_DIRECT_GHOST_MAX_TRAVEL_SECONDS,
  );
}

function createFinalReviewDirectGhostMaterial(sourceMaterial) {
  const material = sourceMaterial?.clone?.() || new THREE.MeshBasicMaterial({ color: 0x6ed8c2 });
  const sourceOpacity = Number.isFinite(Number(sourceMaterial?.opacity)) ? Number(sourceMaterial.opacity) : 1;
  material.transparent = true;
  material.opacity = Math.min(Math.max(sourceOpacity, 0), 1) * FINAL_REVIEW_DIRECT_GHOST_OPACITY;
  material.depthWrite = false;
  material.blending = THREE.AdditiveBlending;
  material.toneMapped = false;
  material.fog = false;
  material.polygonOffset = true;
  material.polygonOffsetFactor = -2;
  material.polygonOffsetUnits = -2;
  if (material.emissive?.isColor) {
    const glowColor = material.color?.isColor ? material.color.clone() : new THREE.Color(0x6ed8c2);
    glowColor.lerp(new THREE.Color(0x6ed8c2), 0.28);
    material.emissive.copy(glowColor);
    material.emissiveIntensity = Math.max(Number(material.emissiveIntensity) || 0, 0.38);
  }
  material.needsUpdate = true;
  return material;
}

function createFinalReviewDirectGhostModel(root) {
  if (!root) return null;
  const ghost = cloneSkinnedObject(root);
  const materials = [];
  ghost.name = `StoryVR manipulation ghost · Final Review · ${root.name || root.uuid}`;
  ghost.userData = { ...ghost.userData, storyvrDirectManipulationGhost: true };
  ghost.traverse((node) => {
    node.userData = { ...node.userData, storyvrDirectManipulationGhost: true };
    node.raycast = () => {};
    if (node.isCamera || node.isLight || node.isAudio) {
      node.visible = false;
      return;
    }
    if (!node.isMesh && !node.isLine && !node.isPoints) return;
    const sourceMaterials = Array.isArray(node.material)
      ? node.material
      : node.material ? [node.material] : [];
    const ghostMaterials = sourceMaterials.length
      ? sourceMaterials.map((material) => createFinalReviewDirectGhostMaterial(material))
      : [createFinalReviewDirectGhostMaterial(null)];
    materials.push(...ghostMaterials);
    node.material = Array.isArray(node.material) ? ghostMaterials : ghostMaterials[0];
    node.castShadow = false;
    node.receiveShadow = false;
    node.renderOrder = (Number(node.renderOrder) || 0) + 2;
  });
  return { ghost, materials };
}

function applyFinalReviewDirectGhostTransform(object, transform) {
  if (!object || !transform) return;
  object.position.copy(transform.position);
  object.quaternion.copy(transform.quaternion);
  object.scale.copy(transform.scale);
  object.updateMatrixWorld(true);
}

function startFinalReviewDirectManipulationCue(viewer, cue, startedAt = viewer?.directManipulationCueElapsed || 0) {
  const start = finalReviewObjectWorldTransform(cue?.root);
  const destination = finalReviewDirectDestinationWorldTransform(cue?.root, cue?.target);
  if (!cue?.ghost || !start || !destination) return false;
  cue.start = start;
  cue.destination = destination;
  cue.travelSeconds = finalReviewDirectGhostTravelSeconds(start.position.distanceTo(destination.position));
  cue.phase = "travel";
  cue.phaseStartedAt = startedAt;
  cue.ghost.visible = true;
  applyFinalReviewDirectGhostTransform(cue.ghost, start);
  return true;
}

function createFinalReviewDirectManipulationCue(viewer, root, target) {
  const result = createFinalReviewDirectGhostModel(root);
  if (!result || !viewer?.directManipulationCueRoot) return null;
  const cue = {
    root,
    target,
    ghost: result.ghost,
    materials: result.materials,
    phase: "idle",
    phaseStartedAt: viewer.directManipulationCueElapsed,
    start: null,
    destination: null,
    travelSeconds: FINAL_REVIEW_DIRECT_GHOST_MIN_TRAVEL_SECONDS,
  };
  viewer.directManipulationCueRoot.add(cue.ghost);
  startFinalReviewDirectManipulationCue(viewer, cue);
  return cue;
}

function disposeFinalReviewDirectManipulationCue(cue) {
  cue?.ghost?.removeFromParent();
  for (const material of cue?.materials || []) material.dispose?.();
  if (cue) {
    cue.ghost = null;
    cue.materials = [];
  }
}

function clearFinalReviewDirectManipulationCues(viewer) {
  endFinalReviewXrDirectManipulation(viewer);
  for (const cue of viewer?.directManipulationCues || []) disposeFinalReviewDirectManipulationCue(cue);
  if (viewer) {
    viewer.directManipulationCues = [];
    viewer.directManipulationTargets = [];
  }
}

function refreshFinalReviewDirectManipulationCues(viewer) {
  if (!viewer || viewer.disposed) return;
  clearFinalReviewDirectManipulationCues(viewer);
  const candidates = finalReviewDirectTargetCandidates(viewer);
  if (!candidates.length) return;
  const cuesByKey = new Set();
  for (const configuration of finalReviewDirectManipulationConfigurations(viewer)) {
    for (const target of configuration.targets || []) {
      const candidate = finalReviewDirectRootForTarget(target, candidates);
      if (!candidate) continue;
      const cueKey = [
        candidate.root.uuid,
        target.coordinateSpace || "scene",
        target.nodePath || "whole-object",
        JSON.stringify(target.destinationTransform || {}),
      ].join("|");
      if (cuesByKey.has(cueKey)) continue;
      cuesByKey.add(cueKey);
      viewer.directManipulationTargets.push({ root: candidate.root, target });
      const cue = createFinalReviewDirectManipulationCue(viewer, candidate.root, target);
      if (!cue) continue;
      viewer.directManipulationCues.push(cue);
    }
  }
}

function updateFinalReviewDirectManipulationCues(viewer) {
  const now = viewer?.directManipulationCueElapsed || 0;
  for (const cue of viewer?.directManipulationCues || []) {
    if (!cue.ghost) continue;
    if (cue.phase === "idle") {
      if (now - cue.phaseStartedAt >= FINAL_REVIEW_DIRECT_GHOST_INACTIVITY_REPLAY_SECONDS) {
        startFinalReviewDirectManipulationCue(viewer, cue, now);
      }
      continue;
    }
    if (cue.phase === "travel") {
      const progress = THREE.MathUtils.clamp((now - cue.phaseStartedAt) / cue.travelSeconds, 0, 1);
      const eased = THREE.MathUtils.smootherstep(progress, 0, 1);
      cue.ghost.position.lerpVectors(cue.start.position, cue.destination.position, eased);
      cue.ghost.quaternion.slerpQuaternions(cue.start.quaternion, cue.destination.quaternion, eased);
      cue.ghost.scale.lerpVectors(cue.start.scale, cue.destination.scale, eased);
      cue.ghost.updateMatrixWorld(true);
      if (progress >= 1) {
        applyFinalReviewDirectGhostTransform(cue.ghost, cue.destination);
        cue.phase = "hold";
        cue.phaseStartedAt = now;
      }
      continue;
    }
    if (cue.phase === "hold" && now - cue.phaseStartedAt >= FINAL_REVIEW_DIRECT_GHOST_DESTINATION_HOLD_SECONDS) {
      cue.ghost.visible = false;
      cue.phase = "idle";
      cue.phaseStartedAt = now;
    }
  }
}

function finalReviewTextPanelVariantLayout(canvasHeight) {
  const height = Number.isFinite(Number(canvasHeight)) && Number(canvasHeight) > 0
    ? Number(canvasHeight)
    : 512;
  return {
    bodyMaxLines: 3,
    statusBaseline: Math.round(height * 0.66),
    footerBaseline: Math.round(height * 0.735),
    controlBandTop: Math.round(height * 0.77),
  };
}

function makeFinalReviewTextTexture(beat, region, variantState = null, requestedScrollLine = 0) {
  const canvas = document.createElement("canvas");
  canvas.width = 1024;
  canvas.height = 512;
  const ctx = canvas.getContext("2d");
  const variantLayout = variantState ? finalReviewTextPanelVariantLayout(canvas.height) : null;
  ctx.clearRect(0, 0, canvas.width, canvas.height);
  drawRoundRect(ctx, 24, 24, canvas.width - 48, canvas.height - 48, 34, "rgba(255,253,244,1)");
  ctx.fillStyle = "#10201c";
  drawFittedFinalReviewTitle(ctx, beat?.title || "Story part", 64, 96, 800);
  ctx.fillStyle = "#354842";
  ctx.font = "700 30px Avenir Next, Gill Sans, sans-serif";
  const pagination = wrapCanvasText(
    ctx,
    beat?.text || "No story text available.",
    64,
    228,
    900,
    38,
    variantLayout?.bodyMaxLines || 6,
    requestedScrollLine,
  );
  if (variantState) {
    ctx.fillStyle = "#53645f";
    ctx.font = "700 25px Avenir Next, Gill Sans, sans-serif";
    ctx.fillText(
      `${variantState.selectedOption.label} · ${variantState.selectedIndex + 1} of ${variantState.group.options.length}`,
      64,
      variantLayout.statusBaseline,
      896,
    );
    ctx.strokeStyle = "rgba(83, 100, 95, 0.24)";
    ctx.lineWidth = 2;
    ctx.beginPath();
    ctx.moveTo(64, variantLayout.controlBandTop);
    ctx.lineTo(canvas.width - 64, variantLayout.controlBandTop);
    ctx.stroke();
  }
  ctx.fillStyle = "#53645f";
  ctx.font = "700 22px Avenir Next, Gill Sans, sans-serif";
  const footer = pagination.maxScrollLine > 0
    ? `Drag / wheel / Trigger-drag to scroll · lines ${pagination.scrollLine + 1}–${Math.min(pagination.lineCount, pagination.scrollLine + pagination.maxLines)} of ${pagination.lineCount} · Grip / title to move`
    : "Trigger for UI buttons · Grip to grab";
  ctx.fillText(footer, 64, variantLayout?.footerBaseline || 478, 896);
  const texture = new THREE.CanvasTexture(canvas);
  texture.colorSpace = THREE.SRGBColorSpace;
  texture.userData.storyvrTextPanelPagination = pagination;
  return texture;
}

function canvasWrappedTextLines(ctx, text, maxWidth) {
  const words = String(text || "").split(/\s+/).filter(Boolean);
  const lines = [];
  let line = "";
  for (const word of words) {
    const chunks = [];
    let chunk = "";
    for (const character of Array.from(word)) {
      const nextChunk = `${chunk}${character}`;
      if (chunk && ctx.measureText(nextChunk).width > maxWidth) {
        chunks.push(chunk);
        chunk = character;
      } else {
        chunk = nextChunk;
      }
    }
    if (chunk) chunks.push(chunk);
    for (const [chunkIndex, wordChunk] of chunks.entries()) {
      const separator = line && chunkIndex === 0 ? " " : "";
      const next = `${line}${separator}${wordChunk}`;
      if (line && ctx.measureText(next).width > maxWidth) {
        lines.push(line);
        line = wordChunk;
      } else {
        line = next;
      }
    }
  }
  if (line) lines.push(line);
  return lines.length ? lines : [""];
}

function drawFittedFinalReviewTitle(ctx, text, x, y, maxWidth) {
  const title = shortText(text || "Story part", 86);
  const maximumLines = 2;
  const minimumFontSize = 32;
  let fontSize = 48;
  let lineHeight = 54;
  let lines = [];
  do {
    ctx.font = `900 ${fontSize}px Avenir Next, Gill Sans, sans-serif`;
    lineHeight = Math.round(fontSize * 1.125);
    lines = canvasWrappedTextLines(ctx, title, maxWidth);
    if (lines.length <= maximumLines || fontSize === minimumFontSize) break;
    fontSize = Math.max(minimumFontSize, fontSize - 2);
  } while (fontSize >= minimumFontSize);
  const visibleLines = lines.slice(0, maximumLines);
  if (lines.length > maximumLines && visibleLines.length) {
    const lastIndex = visibleLines.length - 1;
    visibleLines[lastIndex] = canvasEllipsizedText(ctx, `${visibleLines[lastIndex]}…`, maxWidth);
  }
  visibleLines.forEach((line, index) => {
    ctx.fillText(line, x, y + (index * lineHeight), maxWidth);
  });
  return {
    fontSize,
    lineHeight,
    lineCount: lines.length,
    renderedLineCount: visibleLines.length,
    truncated: lines.length > maximumLines,
  };
}

function wrapCanvasText(ctx, text, x, y, maxWidth, lineHeight, maxLines, requestedScrollLine = 0) {
  const lines = canvasWrappedTextLines(ctx, text, maxWidth);
  const maxScrollLine = Math.max(0, lines.length - maxLines);
  const scrollLine = Math.max(0, Math.min(maxScrollLine, Math.round(Number(requestedScrollLine) || 0)));
  lines.slice(scrollLine, scrollLine + maxLines).forEach((line, index) => {
    ctx.fillText(line, x, y + index * lineHeight);
  });
  return {
    lineCount: lines.length,
    maxLines,
    maxScrollLine,
    scrollLine,
  };
}

function addFinalReviewTransitionEffects(viewer, region, transitionKind = null, playback = null) {
  if (playback?.canScrub !== true || transitionKind !== "discrete-pop") return;
  const flash = new THREE.Mesh(
    new THREE.SphereGeometry(0.78, 48, 28),
    new THREE.MeshBasicMaterial({ color: 0xfff0b5, transparent: true, opacity: 0 }),
  );
  flash.position.set(0, 0.72, 0);
  viewer.root.add(flash);
  viewer.flash = flash;

  const burst = new THREE.Group();
  const burstCount = transitionKind === "discrete-pop" ? 8 : 5;
  for (let index = 0; index < burstCount; index += 1) {
    const angle = (Math.PI * 2 * index) / 8;
    const shard = new THREE.Mesh(
      new THREE.BoxGeometry(0.08, 0.08, 0.34),
      new THREE.MeshBasicMaterial({ color: region.color, transparent: true, opacity: 0.28 }),
    );
    shard.position.set(Math.cos(angle) * 0.52, 0.42 + (index % 3) * 0.08, Math.sin(angle) * 0.52);
    shard.rotation.y = angle;
    burst.add(shard);
  }
  viewer.root.add(burst);
  viewer.regionMarkers.push(burst);
}

function finalReviewAttentionCompletionKey(attentionScene, marker) {
  const sceneKey = String(attentionScene?.sceneKey || spatialSceneRequestKey({
    beatId: attentionScene?.beatId,
    variantGroupId: attentionScene?.variantGroupId,
    variantOptionId: attentionScene?.variantOptionId,
  }) || "unknown-scene");
  return `${sceneKey}::${String(marker?.id || marker?.assetId || "unknown-target")}`;
}

function finalReviewAttentionEntries(viewer) {
  return [...new Set([
    ...(viewer?.dynamicObjects || []),
    ...(viewer?.swapGroups || []),
    ...(viewer?.proceduralPreviewEntries || []),
    viewer?.finalReviewAssetEntry || null,
  ].filter(Boolean))];
}

function finalReviewAttentionTargetForMarker(viewer, attentionScene, marker) {
  if (!marker || marker.coordinateSpace !== "spatial-scene") return null;
  const targetKind = String(marker.targetKind || "").trim();
  if (targetKind === "spatial-point") {
    if (!attentionPosition(marker.position)) return null;
    const group = { root: viewer.root, meshes: [], bounds: new THREE.Box3() };
    return {
      key: finalReviewAttentionCompletionKey(attentionScene, marker),
      marker,
      root: viewer.root,
      pointRoot: viewer.root,
      pointTarget: true,
      groups: [group],
      rootsByMesh: new Map(),
      meshes: [],
      bounds: new THREE.Box3(),
      meshBounds: new THREE.Box3(),
      arrow: null,
      completed: false,
    };
  }
  if (!marker.assetId) return null;
  const matches = finalReviewAttentionEntries(viewer).filter((entry) => entry?.assetId === marker.assetId);
  const entityId = String(marker.entityId || "").trim();
  const entries = entityId
    ? matches.filter((candidate) => (
      String(candidate?.authorWrapper?.userData?.spatialEntityId || candidate?.entityId || "") === entityId
    ))
    : matches;
  const selector = String(marker.partSelector || "").trim();
  if (selector && (targetKind !== "named-renderable-part" || !attentionSelectorIsNarrow(selector))) return null;
  if (!selector && !["standalone-glb", "standalone-image"].includes(targetKind)) return null;
  const groups = entries.flatMap((entry) => {
    const root = entry?.sourceScene || entry?.modelRoot || entry?.group || entry?.authorWrapper || null;
    if (!root?.traverse) return [];
    const meshes = [];
    root.traverse((object) => {
      if (
        !object?.isMesh
        || !object.geometry
      ) return;
      if (!selector || sourcePartSelectorMatchesNode(selector, object, root)) meshes.push(object);
    });
    return meshes.length ? [{ entry, root, meshes, bounds: new THREE.Box3() }] : [];
  });
  const meshes = groups.flatMap((group) => group.meshes);
  if (!meshes.length) return null;
  return {
    key: finalReviewAttentionCompletionKey(attentionScene, marker),
    marker,
    entry: groups[0].entry,
    entries: groups.map((group) => group.entry),
    root: groups[0].root,
    groups,
    rootsByMesh: new Map(groups.flatMap((group) => group.meshes.map((mesh) => [mesh, group.root]))),
    meshes,
    bounds: new THREE.Box3(),
    meshBounds: new THREE.Box3(),
    arrow: null,
    completed: false,
  };
}

function finalReviewAttentionTargetBounds(target, visibleMeshes) {
  target.bounds.makeEmpty();
  if (target?.pointTarget) {
    const position = attentionPosition(target.marker?.position);
    if (!position || !target.pointRoot) return null;
    const center = new THREE.Vector3(position.x, position.y, position.z);
    target.pointRoot.updateWorldMatrix(true, false);
    target.pointRoot.localToWorld(center);
    target.bounds.min.copy(center);
    target.bounds.max.copy(center);
    if (target.groups?.[0]?.bounds) target.groups[0].bounds.copy(target.bounds);
    return target.bounds;
  }
  const visibleSet = new Set(visibleMeshes || []);
  const groups = target?.groups?.length
    ? target.groups
    : [{
        meshes: target?.meshes?.length ? target.meshes : [...visibleSet],
        bounds: new THREE.Box3(),
      }];
  for (const group of groups) {
    group.bounds.makeEmpty();
    for (const mesh of group.meshes) {
      if (!visibleSet.has(mesh)) continue;
      mesh.updateWorldMatrix(true, false);
      target.meshBounds.makeEmpty();
      if (mesh.isSkinnedMesh || mesh.isInstancedMesh) {
        mesh.computeBoundingBox?.();
        if (mesh.boundingBox) target.meshBounds.copy(mesh.boundingBox).applyMatrix4(mesh.matrixWorld);
      } else if (Array.isArray(mesh.morphTargetInfluences) && mesh.morphTargetInfluences.length) {
        target.meshBounds.setFromObject(mesh, true);
      } else {
        if (!mesh.geometry.boundingBox) mesh.geometry.computeBoundingBox();
        if (mesh.geometry.boundingBox) target.meshBounds.copy(mesh.geometry.boundingBox).applyMatrix4(mesh.matrixWorld);
      }
      if (!target.meshBounds.isEmpty()) {
        group.bounds.union(target.meshBounds);
        target.bounds.union(target.meshBounds);
      }
    }
  }
  return target.bounds.isEmpty() ? null : target.bounds;
}

function finalReviewAttentionTargetDistanceToPoint(target, point) {
  const activeBounds = (target?.groups || [])
    .map((group) => group.bounds)
    .filter((bounds) => bounds && !bounds.isEmpty());
  if (activeBounds.length) {
    return Math.min(...activeBounds.map((bounds) => bounds.distanceToPoint(point)));
  }
  return target?.bounds && !target.bounds.isEmpty()
    ? target.bounds.distanceToPoint(point)
    : Infinity;
}

function publishFinalReviewAttentionDiagnostics(viewer) {
  const canvas = viewer?.renderer?.domElement;
  if (!canvas?.dataset) return;
  const targets = viewer.attentionTargets || [];
  const sparkleEffects = targets.flatMap((target) => (
    (target.groups || []).map((group) => group.investigationEffect).filter(Boolean)
  ));
  delete canvas.dataset.storyvrAttentionGlowCount;
  delete canvas.dataset.storyvrAttentionVisibleGlowCount;
  canvas.dataset.storyvrAttentionTargetCount = String(targets.length);
  canvas.dataset.storyvrAttentionGroupCount = String(
    targets.reduce((total, target) => total + (target.groups?.length || 0), 0),
  );
  canvas.dataset.storyvrAttentionSparkleCount = String(sparkleEffects.length);
  canvas.dataset.storyvrAttentionVisibleSparkleCount = String(
    sparkleEffects.filter((effect) => effect.root?.visible === true).length,
  );
  canvas.dataset.storyvrAttentionCompletedCount = String(
    targets.filter((target) => (
      target.completed || state.finalReviewCompletedAttentionKeys.has(target.key)
    )).length,
  );
}

function createFinalReviewAttentionArrow(marker) {
  const shape = new THREE.Shape();
  shape.moveTo(0, 0.105);
  shape.lineTo(-0.052, 0.018);
  shape.lineTo(-0.021, 0.018);
  shape.lineTo(-0.021, -0.085);
  shape.lineTo(0.021, -0.085);
  shape.lineTo(0.021, 0.018);
  shape.lineTo(0.052, 0.018);
  shape.closePath();
  const mesh = new THREE.Mesh(
    new THREE.ShapeGeometry(shape),
    new THREE.MeshBasicMaterial({
      color: 0xe5aa63,
      transparent: true,
      opacity: 0.86,
      depthTest: false,
      depthWrite: false,
      side: THREE.DoubleSide,
      toneMapped: false,
      fog: false,
    }),
  );
  mesh.renderOrder = 10_000;
  mesh.frustumCulled = false;
  const arrow = new THREE.Group();
  arrow.name = `StoryVR attention arrow · Final Review · ${marker?.id || "target"}`;
  arrow.userData.storyvrFinalReviewAttentionArrow = true;
  arrow.frustumCulled = false;
  arrow.visible = false;
  arrow.add(mesh);
  return arrow;
}

function createFinalReviewInvestigationTexture(kind) {
  const canvas = document.createElement("canvas");
  canvas.width = 128;
  canvas.height = 128;
  const context = canvas.getContext("2d");
  if (!context) return null;
  if (kind === "flare") {
    context.translate(64, 64);
    const diamond = (radiusX, radiusY, color) => {
      context.beginPath();
      context.moveTo(0, -radiusY);
      context.lineTo(radiusX, 0);
      context.lineTo(0, radiusY);
      context.lineTo(-radiusX, 0);
      context.closePath();
      context.fillStyle = color;
      context.fill();
    };
    diamond(12, 62, "rgba(255, 211, 108, 0.16)");
    diamond(62, 12, "rgba(255, 211, 108, 0.16)");
    diamond(6, 52, "rgba(255, 245, 203, 0.72)");
    diamond(52, 6, "rgba(255, 245, 203, 0.72)");
    diamond(3, 35, "rgba(255, 255, 247, 1)");
    diamond(35, 3, "rgba(255, 255, 247, 1)");
    const core = context.createRadialGradient(0, 0, 0, 0, 0, 18);
    core.addColorStop(0, "rgba(255, 255, 255, 1)");
    core.addColorStop(0.25, "rgba(255, 247, 207, 0.98)");
    core.addColorStop(1, "rgba(255, 201, 83, 0)");
    context.fillStyle = core;
    context.fillRect(-18, -18, 36, 36);
  } else {
    const innerRadius = kind === "mote" ? 1 : 5;
    const outerRadius = kind === "mote" ? 58 : 64;
    const gradient = context.createRadialGradient(64, 64, innerRadius, 64, 64, outerRadius);
    gradient.addColorStop(0, "rgba(255, 255, 250, 1)");
    gradient.addColorStop(0.12, "rgba(255, 247, 206, 0.98)");
    gradient.addColorStop(kind === "mote" ? 0.34 : 0.28, "rgba(255, 196, 73, 0.72)");
    gradient.addColorStop(kind === "mote" ? 0.7 : 0.62, "rgba(255, 161, 43, 0.2)");
    gradient.addColorStop(1, "rgba(255, 152, 28, 0)");
    context.fillStyle = gradient;
    context.fillRect(0, 0, 128, 128);
  }
  const texture = new THREE.CanvasTexture(canvas);
  texture.colorSpace = THREE.SRGBColorSpace;
  return texture;
}

function createFinalReviewAttentionSparkle(viewer, groupIndex = 0) {
  if (!viewer?.scene) return null;
  const bloomTexture = createFinalReviewInvestigationTexture("bloom");
  const flareTexture = createFinalReviewInvestigationTexture("flare");
  const moteTexture = createFinalReviewInvestigationTexture("mote");
  if (!bloomTexture || !flareTexture || !moteTexture) {
    bloomTexture?.dispose?.();
    flareTexture?.dispose?.();
    moteTexture?.dispose?.();
    return null;
  }
  const root = new THREE.Group();
  root.name = "StoryVR investigation sparkle · Final Review";
  root.userData.storyvrFinalReviewAttentionEffect = true;
  root.frustumCulled = false;
  root.visible = false;

  const createSprite = (texture, color, opacity, blending = THREE.AdditiveBlending) => {
    const material = new THREE.SpriteMaterial({
      map: texture,
      color,
      transparent: true,
      opacity,
      blending,
      depthTest: true,
      depthWrite: false,
      toneMapped: false,
      fog: false,
    });
    const sprite = new THREE.Sprite(material);
    sprite.userData.storyvrFinalReviewAttentionEffect = true;
    sprite.renderOrder = 3_000;
    sprite.frustumCulled = false;
    root.add(sprite);
    return sprite;
  };

  const bloom = createSprite(bloomTexture, 0xffbd52, 0.76, THREE.NormalBlending);
  const shaft = createSprite(bloomTexture, 0xffd06d, 0.46);
  const flare = createSprite(flareTexture, 0xffffea, 1);
  const flareSecondary = createSprite(flareTexture, 0xffcf65, 0.82);
  const motes = Array.from({ length: 7 }, (_, index) => {
    const mote = createSprite(moteTexture, index % 2 ? 0xffec9b : 0xffffff, 0.8);
    mote.userData.storyvrMoteIndex = index;
    return mote;
  });
  viewer.scene.add(root);
  return {
    root,
    bloom,
    shaft,
    flare,
    flareSecondary,
    motes,
    materials: [bloom.material, shaft.material, flare.material, flareSecondary.material, ...motes.map((mote) => mote.material)],
    textures: [bloomTexture, flareTexture, moteTexture],
    elapsedSeconds: 0,
    phase: groupIndex * 1.61803398875,
  };
}

function syncFinalReviewAttentionSparkle(
  effect,
  bounds,
  visible,
  deltaSeconds = 1 / 60,
  anchorAtBoundsCenter = false,
) {
  if (!effect?.root) return;
  effect.root.visible = Boolean(visible);
  if (!visible || !bounds || bounds.isEmpty()) return;
  effect.elapsedSeconds += THREE.MathUtils.clamp(Number(deltaSeconds) || 0, 0, 0.1);
  const time = effect.elapsedSeconds + effect.phase;
  const pulse = (Math.sin(time * 5.4) + 1) * 0.5;
  const sphere = bounds.getBoundingSphere(new THREE.Sphere());
  const effectScale = THREE.MathUtils.clamp(sphere.radius * 0.52, 0.22, 0.48);
  if (anchorAtBoundsCenter) {
    effect.root.position.copy(sphere.center);
  } else {
    effect.root.position.set(
      sphere.center.x,
      bounds.max.y + THREE.MathUtils.clamp(sphere.radius * 0.14, 0.05, 0.16),
      sphere.center.z,
    );
  }
  effect.root.scale.setScalar(effectScale);

  const bloomScale = 1.55 + pulse * 0.28;
  effect.bloom.scale.set(bloomScale, bloomScale, 1);
  effect.bloom.material.opacity = 0.68 + pulse * 0.18;
  effect.shaft.scale.set(0.42 + pulse * 0.08, 2.3 + pulse * 0.3, 1);
  effect.shaft.material.opacity = 0.34 + pulse * 0.2;
  const flareScale = 1.08 + pulse * 0.18;
  effect.flare.scale.set(flareScale, flareScale, 1);
  effect.flare.material.opacity = 0.9 + pulse * 0.1;
  effect.flare.material.rotation = time * 0.42;
  const secondaryPulse = (Math.sin(time * 7.1 + 1.7) + 1) * 0.5;
  const secondaryScale = 0.66 + secondaryPulse * 0.26;
  effect.flareSecondary.scale.set(secondaryScale, secondaryScale, 1);
  effect.flareSecondary.material.opacity = 0.5 + secondaryPulse * 0.42;
  effect.flareSecondary.material.rotation = -time * 0.68 + Math.PI / 4;

  for (let index = 0; index < effect.motes.length; index += 1) {
    const mote = effect.motes[index];
    const cycle = ((time * (0.3 + (index % 3) * 0.035)) + index / effect.motes.length) % 1;
    const angle = time * (0.72 + (index % 2) * 0.18) + index * 2.399963;
    const radius = 0.42 + (index % 3) * 0.1;
    const life = Math.sin(Math.PI * cycle);
    mote.position.set(
      Math.cos(angle) * radius,
      -0.48 + cycle * 1.52,
      Math.sin(angle) * radius * 0.34,
    );
    const moteScale = 0.1 + life * (0.13 + (index % 2) * 0.04);
    mote.scale.set(moteScale, moteScale, 1);
    mote.material.opacity = 0.18 + life * 0.82;
  }
}

function applyFinalReviewAttentionSparkles(viewer, target, enabled, deltaSeconds = 1 / 60) {
  for (let index = 0; index < (target?.groups || []).length; index += 1) {
    const group = target.groups[index];
    const visible = enabled && group.bounds && !group.bounds.isEmpty();
    if (visible && !group.investigationEffect) {
      group.investigationEffect = createFinalReviewAttentionSparkle(viewer, index);
    }
    if (group.investigationEffect) {
      syncFinalReviewAttentionSparkle(
        group.investigationEffect,
        group.bounds,
        visible,
        deltaSeconds,
        target?.pointTarget === true,
      );
    }
  }
}

function disposeFinalReviewAttentionSparkle(effect) {
  if (!effect) return;
  effect.root?.removeFromParent?.();
  for (const material of effect.materials || []) material?.dispose?.();
  for (const texture of effect.textures || []) texture?.dispose?.();
}

function disposeFinalReviewAttentionTarget(target) {
  for (const group of target?.groups || []) {
    disposeFinalReviewAttentionSparkle(group.investigationEffect);
    group.investigationEffect = null;
  }
  if (target?.arrow) {
    target.arrow.removeFromParent();
    target.arrow.traverse((object) => {
      object.geometry?.dispose?.();
      const materials = Array.isArray(object.material) ? object.material : [object.material].filter(Boolean);
      for (const material of materials) material.dispose?.();
    });
  }
}

function clearFinalReviewAttentionGuidance(viewer) {
  for (const target of viewer?.attentionTargets || []) disposeFinalReviewAttentionTarget(target);
  if (viewer) {
    viewer.attentionTargets = [];
    viewer.attentionScene = null;
  }
}

function syncFinalReviewAttentionGuidance(viewer) {
  clearFinalReviewAttentionGuidance(viewer);
  if (!viewer?.sceneContext?.beatId || viewer.disposed) return 0;
  const attentionScene = attentionSceneRecordForContext(
    attentionGuidanceSourceContract(),
    viewer.sceneContext,
  );
  viewer.attentionScene = attentionScene || null;
  if (attentionScene?.evaluated !== true) return 0;
  for (const marker of attentionSceneMarkers(attentionScene)) {
    const target = finalReviewAttentionTargetForMarker(viewer, attentionScene, marker);
    if (!target || state.finalReviewCompletedAttentionKeys.has(target.key)) continue;
    target.arrow = createFinalReviewAttentionArrow(marker);
    viewer.scene.add(target.arrow);
    viewer.attentionTargets.push(target);
  }
  return viewer.attentionTargets.length;
}

function finalReviewAttentionTargetInView(bounds, camera) {
  if (!bounds || bounds.isEmpty() || !camera?.projectionMatrix || !camera?.matrixWorld) return false;
  camera.updateWorldMatrix(true, false);
  camera.matrixWorldInverse.copy(camera.matrixWorld).invert();
  const projection = new THREE.Matrix4().multiplyMatrices(camera.projectionMatrix, camera.matrixWorldInverse);
  return new THREE.Frustum().setFromProjectionMatrix(projection).intersectsBox(bounds);
}

function smoothAttentionArrowAngle(previousAngle, nextAngle, deltaSeconds) {
  if (!Number.isFinite(nextAngle)) return Number.isFinite(previousAngle) ? previousAngle : 0;
  const normalizedNext = Math.atan2(Math.sin(nextAngle), Math.cos(nextAngle));
  if (!Number.isFinite(previousAngle)) return normalizedNext;
  const delta = Math.max(0, Math.min(Number(deltaSeconds) || 0, 0.1));
  if (!delta) return previousAngle;
  const difference = Math.atan2(
    Math.sin(normalizedNext - previousAngle),
    Math.cos(normalizedNext - previousAngle),
  );
  const responseStep = difference * (1 - Math.exp(-ATTENTION_ARROW_DIRECTION_RESPONSE * delta));
  const maximumStep = ATTENTION_ARROW_MAX_ANGULAR_SPEED_RADIANS_PER_SECOND * delta;
  const next = previousAngle + THREE.MathUtils.clamp(responseStep, -maximumStep, maximumStep);
  return Math.atan2(Math.sin(next), Math.cos(next));
}

function positionFinalReviewAttentionArrow(viewer, target, camera, targetIndex, deltaSeconds = 1 / 60) {
  if (!target?.arrow || !target?.bounds || target.bounds.isEmpty() || !camera) return false;
  const worldTarget = new THREE.Vector3();
  const manualPosition = target.marker?.manual === true ? attentionPosition(target.marker.position) : null;
  if (manualPosition) {
    worldTarget.set(manualPosition.x, manualPosition.y, manualPosition.z);
    viewer.root.localToWorld(worldTarget);
  } else target.bounds.getCenter(worldTarget);
  const ndc = worldTarget.clone().project(camera);
  const localTarget = worldTarget.clone();
  camera.worldToLocal(localTarget);
  let x = ndc.x;
  let y = ndc.y;
  if (localTarget.z >= -0.001 || !Number.isFinite(x) || !Number.isFinite(y)) {
    x = localTarget.x;
    y = localTarget.y;
  }
  const previousAngle = Number(target.arrow.userData.storyvrAttentionArrowAngle);
  if (Math.abs(x) + Math.abs(y) < 0.0001) {
    x = Number.isFinite(previousAngle) ? Math.cos(previousAngle) : 1;
    y = Number.isFinite(previousAngle) ? Math.sin(previousAngle) : 0;
  }
  const smoothedAngle = smoothAttentionArrowAngle(previousAngle, Math.atan2(y, x), deltaSeconds);
  target.arrow.userData.storyvrAttentionArrowAngle = smoothedAngle;
  x = Math.cos(smoothedAngle);
  y = Math.sin(smoothedAngle);
  const edgeScale = 0.82 / Math.max(Math.abs(x), Math.abs(y), 0.0001);
  x *= edgeScale;
  y *= edgeScale;
  const lane = ((Math.max(0, targetIndex) % 3) - 1) * 0.035;
  const length = Math.hypot(x, y) || 1;
  const laneX = (-y / length) * lane;
  const laneY = (x / length) * lane;
  x = THREE.MathUtils.clamp(x + laneX, -0.79, 0.79);
  y = THREE.MathUtils.clamp(y + laneY, -0.79, 0.79);
  const arrowWorld = new THREE.Vector3(x, y, 0).unproject(camera);
  const cameraPosition = camera.getWorldPosition(new THREE.Vector3());
  arrowWorld.sub(cameraPosition).normalize().multiplyScalar(0.62).add(cameraPosition);
  target.arrow.position.copy(arrowWorld);
  target.arrow.quaternion.copy(camera.getWorldQuaternion(new THREE.Quaternion()));
  target.arrow.rotateZ(Math.atan2(y, x) - Math.PI / 2);
  target.arrow.scale.setScalar(0.72);
  return true;
}

function updateFinalReviewAttentionGuidance(viewer, renderCamera = viewer?.camera, deltaSeconds = 1 / 60) {
  if (!viewer?.attentionTargets?.length || !renderCamera) return;
  const camera = viewer.renderer?.xr?.isPresenting
    ? viewer.renderer.xr.getCamera(renderCamera)
    : renderCamera;
  const readerPosition = camera.getWorldPosition(new THREE.Vector3());
  for (let index = 0; index < viewer.attentionTargets.length; index += 1) {
    const target = viewer.attentionTargets[index];
    const completed = target.completed || state.finalReviewCompletedAttentionKeys.has(target.key);
    const visibleMeshes = completed
      ? []
      : target.meshes.filter((mesh) => attentionRenderableIsVisible(
        mesh,
        target.rootsByMesh?.get(mesh) || target.root,
      ));
    const bounds = finalReviewAttentionTargetBounds(target, visibleMeshes);
    const targetVisible = Boolean(bounds);
    const distance = bounds
      ? finalReviewAttentionTargetDistanceToPoint(target, readerPosition)
      : Infinity;
    const shouldComplete = !completed
      && targetVisible
      && Number.isFinite(distance)
      && distance <= 3;
    if (shouldComplete) {
      target.completed = true;
      state.finalReviewCompletedAttentionKeys.add(target.key);
      applyFinalReviewAttentionSparkles(viewer, target, false, deltaSeconds);
      if (target.arrow) target.arrow.visible = false;
      continue;
    }
    const active = !completed && targetVisible;
    applyFinalReviewAttentionSparkles(viewer, target, active, deltaSeconds);
    if (!target.arrow) continue;
    target.arrow.visible = active && !finalReviewAttentionTargetInView(bounds, camera);
    if (!target.arrow.visible) {
      delete target.arrow.userData.storyvrAttentionArrowAngle;
      continue;
    }
    if (!positionFinalReviewAttentionArrow(viewer, target, camera, index, deltaSeconds)) {
      target.arrow.visible = false;
    }
  }
  publishFinalReviewAttentionDiagnostics(viewer);
}

function addFinalReviewEmbodiedProgression(viewer, region, configuration = null) {
  let configuredTransform = interactionKindForConfiguration(configuration) === "embodied-control"
    ? normalizeSpatialTransform(configuration.destination?.transform)
    : null;
  if (configuredTransform && configuration.destination?.coordinateSpace === "reader-start") {
    const sourceReader = interactionReaderTransformForContext(viewer?.activeProgressionBoundary?.fromContext);
    if (sourceReader) {
      const sourcePosition = new THREE.Vector3().fromArray(sourceReader.position);
      const sourceQuaternion = new THREE.Quaternion().fromArray(sourceReader.quaternion).normalize();
      const position = new THREE.Vector3().fromArray(configuredTransform.position)
        .applyQuaternion(sourceQuaternion)
        .add(sourcePosition);
      const quaternion = sourceQuaternion.clone()
        .multiply(new THREE.Quaternion().fromArray(configuredTransform.quaternion))
        .normalize();
      configuredTransform = {
        ...configuredTransform,
        position: position.toArray(),
        quaternion: quaternion.toArray(),
      };
    }
  }
  const configuredPosition = configuredTransform
    ? new THREE.Vector3().fromArray(configuredTransform.position)
    : null;
  const targetRadius = THREE.MathUtils.clamp(
    Number(configuration?.tolerance?.distanceMeters) || 0.32,
    0.18,
    1.5,
  );
  const route = {
    start: new THREE.Vector3(0.9, 0, 1.55),
    target: configuredPosition || region.position.clone().multiplyScalar(0.82),
  };
  const group = new THREE.Group();
  const targetRing = markFinalTuningGroundCircle(new THREE.Mesh(
    new THREE.RingGeometry(targetRadius * 0.78, targetRadius, 48),
    new THREE.MeshBasicMaterial({ color: region.color, transparent: true, opacity: 0.5, side: THREE.DoubleSide }),
  ));
  targetRing.rotation.x = -Math.PI / 2;
  targetRing.position.copy(route.target);
  targetRing.position.y = 0.06;
  group.add(targetRing);
  const label = makeTextSprite("enter region to advance", {
    color: "#007f73",
    background: "rgba(255,253,244,0.9)",
    width: 1.34,
    height: 0.2,
  });
  label.position.copy(route.target).add(new THREE.Vector3(0, 0.42, 0));
  group.add(label);
  const path = new THREE.Line(
    new THREE.BufferGeometry().setFromPoints([
      route.start.clone().setY(0.07),
      route.start.clone().lerp(route.target, 0.5).setY(0.07),
      route.target.clone().setY(0.07),
    ]),
    new THREE.LineBasicMaterial({ color: region.color, transparent: true, opacity: 0.58 }),
  );
  group.add(path);
  viewer.root.add(group);
  viewer.embodiedRig = { group, targetRing, label, route };
  applyFinalReviewTuningDirectives(viewer, finalReviewTuningDirectives());
}

function finalReviewSourcePlaybackEntry(viewer) {
  if (!viewer || viewer.componentId !== "transition-pacing") return null;
  const activeAssetId = String(viewer.activeAssetId || viewer.beat?.linkedAssetIds?.[0] || "");
  const activeSwapEntry = viewer.swapGroups?.[viewer.activeSwapIndex] || null;
  const dynamicEntries = Array.isArray(viewer.dynamicObjects) ? viewer.dynamicObjects : [];
  const preferredDynamicEntry = dynamicEntries.find((entry) => entry?.assetId === activeAssetId) || null;
  const candidates = [
    activeSwapEntry,
    preferredDynamicEntry,
    viewer.finalReviewAssetEntry || null,
    ...dynamicEntries,
    ...(viewer.swapGroups || []),
  ];
  const seen = new Set();
  return candidates.find((entry) => {
    if (!entry || seen.has(entry)) return false;
    seen.add(entry);
    return entry.sourcePlayback?.asset?.mode === "shared-timeline"
      && entry.sourcePlaybackContractActive === true;
  }) || null;
}

function syncFinalReviewSourceCameraRenderProxy(viewer, sourceCamera) {
  const readerCamera = viewer?.camera;
  if (!viewer?.scene || !readerCamera || !sourceCamera?.isCamera) return readerCamera;
  let proxy = viewer.sourceCameraRenderProxy;
  if (!proxy || proxy.type !== sourceCamera.type) {
    proxy?.removeFromParent?.();
    proxy = sourceCamera.clone(false);
    proxy.name = "StoryVR source camera render proxy · Final Review";
    viewer.scene.add(proxy);
    viewer.sourceCameraRenderProxy = proxy;
  }
  sourceCamera.updateWorldMatrix(true, false);
  viewer.sourceCameraRenderPosition ||= new THREE.Vector3();
  viewer.sourceCameraRenderQuaternion ||= new THREE.Quaternion();
  proxy.position.copy(sourceCamera.getWorldPosition(viewer.sourceCameraRenderPosition));
  proxy.quaternion.copy(sourceCamera.getWorldQuaternion(viewer.sourceCameraRenderQuaternion));
  proxy.scale.set(1, 1, 1);
  proxy.near = Math.max(Number(sourceCamera.near) || readerCamera.near, 0.001);
  proxy.far = Math.max(Number(sourceCamera.far) || readerCamera.far, proxy.near + 1);
  if (proxy.isPerspectiveCamera && sourceCamera.isPerspectiveCamera) {
    proxy.aspect = readerCamera.aspect;
    proxy.fov = Number(sourceCamera.fov) || readerCamera.fov;
    proxy.zoom = Number(sourceCamera.zoom) || 1;
    proxy.focus = Number(sourceCamera.focus) || proxy.focus;
    proxy.filmGauge = Number(sourceCamera.filmGauge) || proxy.filmGauge;
    proxy.filmOffset = Number(sourceCamera.filmOffset) || 0;
  } else if (proxy.isOrthographicCamera && sourceCamera.isOrthographicCamera) {
    proxy.left = sourceCamera.left;
    proxy.right = sourceCamera.right;
    proxy.top = sourceCamera.top;
    proxy.bottom = sourceCamera.bottom;
    proxy.zoom = Number(sourceCamera.zoom) || 1;
  }
  proxy.updateProjectionMatrix();
  proxy.updateMatrixWorld(true);
  return proxy;
}

function sourcePlaybackPresentationBackground(asset) {
  const value = asset?.presentation?.backgroundColor;
  if (Array.isArray(value) && value.length >= 3) {
    const components = value.slice(0, 3).map(Number);
    if (components.every(Number.isFinite)) return new THREE.Color().setRGB(...components);
  }
  const text = String(value || "").trim();
  if (!text) return null;
  try {
    return new THREE.Color(text);
  } catch {
    return null;
  }
}

function syncFinalReviewSourcePresentation(viewer, playback) {
  if (
    !viewer?.scene
    || !viewer?.renderer
    || viewer.lockedEnvironmentActive
    || viewer.authoredEnvironmentPolicyActive
  ) return;
  const background = sourcePlaybackPresentationBackground(playback?.asset);
  if (!background) return;
  const signature = background.getHexString();
  if (viewer.sourcePlaybackPresentationSignature === signature) return;
  viewer.sourcePlaybackPresentationSignature = signature;
  viewer.scene.background = background;
  viewer.scene.fog = null;
  viewer.renderer.setClearColor(background, 1);
}

function finalReviewRenderCamera(viewer) {
  const readerCamera = viewer?.camera;
  const playback = finalReviewSourcePlaybackEntry(viewer)?.sourcePlayback;
  syncFinalReviewSourcePresentation(viewer, playback);
  // Final Review is the authored reader experience. Source cameras may still
  // drive captured animation and presentation state, but rendering through one
  // would bypass the Spatial Relations reader pose and the camera controlled by
  // reader look direction.
  return readerCamera;
}

function updateFinalReviewTransitionExecution(viewer, delta) {
  if (!viewer?.finalReviewTransitionPlayback) return false;
  const cycleSeconds = Math.max(previewAnimationCycleSeconds(viewer), 0.001);
  if (viewer.transitionPlaying) {
    const playbackDelta = Math.max(0, Number(delta) || 0) * Math.max(Number(viewer.speed) || 1, 0.001);
    viewer.sourceElapsed = Math.min(cycleSeconds, (Number(viewer.sourceElapsed) || 0) + playbackDelta);
  }
  const progress = previewCycleProgress(viewer);
  const completed = progress >= 1;
  const canvas = viewer.renderer?.domElement;
  if (canvas) {
    canvas.dataset.finalReviewTransitionProgress = progress.toFixed(4);
    canvas.dataset.finalReviewTransitionState = completed ? "complete" : "playing";
  }
  applyInterBeatSourcePartMasks(viewer, completed ? "destination" : "transition");
  const entries = [
    ...(viewer.dynamicObjects || []),
    ...(viewer.swapGroups || []),
  ];
  for (const entry of entries) {
    if (entry?.sourcePlayback) {
      updateSourceTransitionPlayback(viewer, entry);
      continue;
    }
    if (!entry?.mixer || entry.sourcePartFrozen) continue;
    const start = Number.isFinite(Number(entry.sourceMotionStartProgress))
      ? Number(entry.sourceMotionStartProgress)
      : 0;
    const end = Number.isFinite(Number(entry.sourceMotionEndProgress))
      ? Number(entry.sourceMotionEndProgress)
      : 1;
    const duration = Math.max(Number(entry.sourceMotionDuration) || 0, 0.001);
    entry.mixer.setTime(duration * THREE.MathUtils.lerp(start, end, progress));
  }
  if (completed) viewer.transitionPlaying = false;
  return true;
}

function animateFinalReviewViewer(viewer, delta = 0) {
  const time = viewer.elapsed;
  const sourcePlaybackEntry = finalReviewSourcePlaybackEntry(viewer);
  const transitionExecuted = updateFinalReviewTransitionExecution(viewer, delta);
  if (sourcePlaybackEntry && !transitionExecuted) {
    updateSourceTransitionPlayback(viewer, sourcePlaybackEntry);
    updateSourcePlaybackAnnotations(sourcePlaybackEntry.sourcePlayback);
  }
  animateProceduralDynamicsPreview(viewer, time);
  updateFinalReviewDirectManipulationCues(viewer);
  if (viewer.activeAssetGroup && sourcePlaybackEntry !== viewer.finalReviewAssetEntry) {
    viewer.activeAssetGroup.position.set(0, Math.sin(time * 1.7) * 0.055, 0);
    viewer.activeAssetGroup.rotation.y = time * 0.55;
  }
  for (const duplicate of viewer.duplicateGroups) {
    const angle = duplicate.angle + time * 0.42;
    duplicate.group.position.x = Math.cos(angle) * duplicate.radiusX;
    duplicate.group.position.z = Math.sin(angle) * duplicate.radiusZ;
    duplicate.group.position.y = 0.17 + Math.sin(time * 1.8 + duplicate.bobOffset) * 0.05;
    duplicate.group.rotation.y = -angle + Math.PI;
  }
  if (viewer.flash) {
    const flashProgress = Math.max(0, 1 - (time % 5) / 0.9);
    viewer.flash.scale.setScalar(0.45 + flashProgress * 1.8);
    viewer.flash.material.opacity = flashProgress * 0.34;
  }
  viewer.regionMarkers.forEach((marker, index) => {
    const pulse = 1 + (Math.sin(time * 2.2 + index * 0.7) * 0.5 + 0.5) * 0.2;
    marker.scale.setScalar(pulse);
  });
  if (viewer.embodiedRig?.targetRing) {
    viewer.embodiedRig.targetRing.scale.setScalar(1 + (Math.sin(time * 2.4) * 0.5 + 0.5) * 0.28);
  }
  if (viewer.textPanel && ["reader-facing", "reader-facing-yaw"].includes(viewer.textOrientationPolicy)) {
    if (viewer.textOrientationPolicy === "reader-facing-yaw") {
      const target = viewer.camera.position.clone();
      target.y = viewer.textPanel.getWorldPosition(new THREE.Vector3()).y;
      viewer.textPanel.lookAt(target);
    } else viewer.textPanel.lookAt(viewer.camera.position);
  }
}

function addInteractionControlStage(root, kind, layers = null, options = {}) {
  if (options.allowSyntheticGeometry !== true) return null;
  const grid = new THREE.GridHelper(7, 14, 0x9edfd5, 0xd7e7e0);
  grid.position.y = -0.02;
  root.add(grid);
  const stage = new THREE.Mesh(
    new THREE.RingGeometry(1.4, 1.45, 64),
    new THREE.MeshBasicMaterial({ color: 0x007f73, transparent: true, opacity: 0.28, side: THREE.DoubleSide }),
  );
  stage.rotation.x = -Math.PI / 2;
  stage.position.y = 0.02;
  root.add(stage);
  const label = makeTextSprite(interactionControlKindLabel(kind), {
    fontSize: 54,
    background: "rgba(255,253,244,0.94)",
    color: "#0f211d",
    padding: 18,
  });
  label.position.set(0, 1.25, 1.35);
  label.scale.set(0.82, 0.28, 1);
  root.add(label);
  if (layers) {
    addCumulativeLayerLabels(root, layers, "interaction-control", { limit: 6, startX: -3.04, spacing: 1.22, z: -2.05, width: 1.16 });
  }
}

function addInteractionControlOverlays(viewer, kind, activePosition, beat) {
  const group = new THREE.Group();
  const active = activePosition.clone();
  active.y += 0.08;

  if (kind === "direct") {
    const grip = makeTextSprite("reader hands manipulate object", {
      fontSize: 44,
      background: "rgba(255,253,244,0.94)",
      color: "#0f211d",
      padding: 12,
    });
    grip.position.copy(activePosition).add(new THREE.Vector3(0, 0.95, 0));
    grip.scale.set(0.92, 0.22, 1);
    group.add(grip);
  } else if (kind === "embodied-control") {
    const route = viewer.embodiedRoute || { start: activePosition.clone().add(new THREE.Vector3(-0.34, 0, 0.82)), target: activePosition.clone().add(new THREE.Vector3(0, 0, -0.62)) };
    const locomotionMode = interactionLocomotionMode(viewer.proposal);
    const zoneLabel = route.requiresLocomotion === false
      ? "reading station"
      : locomotionMode === "virtual-teleport" ? "teleport here" : "enter zone";
    const zone = makeInteractionButton(zoneLabel, "embodied-restart", 0x007f73);
    zone.position.copy(route.target).add(new THREE.Vector3(0, 0.08, 0));
    zone.scale.set(1.12, 1.12, 1.12);
    viewer.actionTargets.push(zone);
    group.add(zone);
    (route.requiresLocomotion !== false && locomotionMode === "physical-walking" ? [0, 1, 2] : []).forEach((index) => {
      const foot = new THREE.Mesh(
        new THREE.RingGeometry(0.16, 0.2, 28),
        new THREE.MeshBasicMaterial({ color: 0x007f73, transparent: true, opacity: 0.3, side: THREE.DoubleSide }),
      );
      foot.rotation.x = -Math.PI / 2;
      foot.position.set(-0.24 + index * 0.24, 0.045, 0.74 - index * 0.28);
      group.add(foot);
    });
    addEmbodiedProgressionReaderRig(viewer, route);
  } else if (kind === "branching-control") {
    const branchA = makeInteractionButton("Path A", "branch-a", state.interactionBranchChoice === "A" ? 0x007f73 : 0x8fbfb7);
    branchA.position.copy(activePosition).add(new THREE.Vector3(-0.72, 0.58, -0.55));
    const branchB = makeInteractionButton("Path B", "branch-b", state.interactionBranchChoice === "B" ? 0xc75f1f : 0x8fbfb7);
    branchB.position.copy(activePosition).add(new THREE.Vector3(0.72, 0.58, -0.55));
    viewer.actionTargets.push(branchA, branchB);
    group.add(branchA, branchB);
  }

  viewer.interactionOverlayGroup = group;
  viewer.interactionBeatLabel = null;
  viewer.interactionBeatLabelPosition = null;
  return group;
}

function interactionObjectTransform(object) {
  return normalizeSpatialTransform({
    position: object.position.toArray(),
    quaternion: object.quaternion.toArray(),
    scale: object.scale.toArray(),
  });
}

function applyInteractionTransformToObject(object, transform) {
  const normalized = normalizeSpatialTransform(transform);
  object.position.fromArray(normalized.position);
  object.quaternion.fromArray(normalized.quaternion);
  object.scale.fromArray(normalized.scale);
  object.updateMatrixWorld(true);
}

function interactionLocomotionWorldTransform(configuration, readerRig) {
  const transform = normalizeSpatialTransform(configuration.destination?.transform);
  if (configuration.destination?.coordinateSpace !== "reader-start" || !readerRig) return transform;
  const readerPosition = readerRig.getWorldPosition(new THREE.Vector3());
  const readerQuaternion = readerRig.getWorldQuaternion(new THREE.Quaternion());
  const position = new THREE.Vector3(...transform.position).applyQuaternion(readerQuaternion).add(readerPosition);
  const quaternion = readerQuaternion.clone().multiply(new THREE.Quaternion(...transform.quaternion)).normalize();
  return { ...transform, position: position.toArray(), quaternion: quaternion.toArray() };
}

function makeInteractionLocomotionDestination(configuration, readerRig) {
  const group = new THREE.Group();
  group.name = "StoryVR locomotion destination";
  group.userData.interactionDestinationKind = "locomotion";
  const radius = configuration.tolerance.distanceMeters;
  const disc = new THREE.Mesh(
    new THREE.CircleGeometry(radius, 64),
    new THREE.MeshBasicMaterial({ color: 0x007f73, transparent: true, opacity: 0.16, side: THREE.DoubleSide, depthWrite: false }),
  );
  disc.rotation.x = -Math.PI / 2;
  disc.position.y = 0.012;
  const ring = new THREE.Mesh(
    new THREE.RingGeometry(Math.max(0.02, radius - 0.035), radius, 64),
    new THREE.MeshBasicMaterial({ color: 0x007f73, transparent: true, opacity: 0.92, side: THREE.DoubleSide }),
  );
  ring.rotation.x = -Math.PI / 2;
  ring.position.y = 0.018;
  const arrow = new THREE.Mesh(
    new THREE.ConeGeometry(0.09, 0.26, 24),
    new THREE.MeshStandardMaterial({ color: 0xc75f1f, emissive: 0xc75f1f, emissiveIntensity: 0.12 }),
  );
  arrow.rotation.x = -Math.PI / 2;
  arrow.position.set(0, 0.18, -Math.min(radius * 0.56, 0.38));
  const label = makeTextSprite("Scene-change destination", {
    fontSize: 44,
    background: "rgba(255,253,244,0.96)",
    color: "#007f73",
    padding: 12,
  });
  label.position.set(0, 0.42, 0);
  label.scale.set(0.86, 0.22, 1);
  group.add(disc, ring, arrow, label);
  applyInteractionTransformToObject(group, interactionLocomotionWorldTransform(configuration, readerRig));
  return group;
}

function makeInteractionDirectDestination(target, selected, viewer = null) {
  const outsideRange = !interactionDirectDestinationIsReachable(target);
  const accent = outsideRange ? 0xb12e4b : selected ? 0xc75f1f : 0x007f73;
  const group = new THREE.Group();
  group.name = `StoryVR manipulation destination · ${target.entityId}`;
  group.userData.interactionDestinationKind = "direct";
  group.userData.interactionEntityId = target.entityId;
  group.userData.interactionNodePath = target.nodePath || "";
  group.userData.interactionNodeIndex = target.nodeIndex ?? null;
  const box = new THREE.Mesh(
    new THREE.BoxGeometry(0.7, 0.7, 0.7),
    new THREE.MeshStandardMaterial({
      color: accent,
      emissive: accent,
      emissiveIntensity: outsideRange ? 0.2 : 0.08,
      transparent: true,
      opacity: outsideRange ? 0.32 : selected ? 0.25 : 0.13,
      wireframe: true,
      depthWrite: false,
    }),
  );
  const label = makeTextSprite(
    outsideRange
      ? `Outside range · ${target.nodePath || target.assetId || "object"}`
      : target.nodePath ? `Destination · ${target.nodePath}` : "Object destination",
    {
      fontSize: 42,
      background: "rgba(255,253,244,0.94)",
      color: outsideRange ? "#9d2440" : selected ? "#a84416" : "#007f73",
      padding: 10,
    },
  );
  label.position.set(0, 0.55, 0);
  label.scale.set(0.78, 0.2, 1);
  group.add(box, label);
  const candidate = viewer?.interactionTargetCandidates?.get?.(interactionDirectTargetKey(target));
  applyInteractionTransformToObject(group, candidate
    ? interactionWorldTransformForLocal(candidate.object.parent, target.destinationTransform)
    : target.destinationTransform);
  return group;
}

function interactionInBeatCandidateForObject(viewer, object) {
  const configuredKeys = new Set(interactionInBeatTargetsForContext(viewer?.editorContext?.sceneContext)
    .map((target) => interactionInBeatTargetKey(target)));
  let deepestCandidate = null;
  let current = object || null;
  while (current) {
    const candidate = viewer?.interactionTargetCandidateByObject?.get?.(current) || null;
    if (candidate) {
      deepestCandidate ||= candidate;
      if (configuredKeys.has(interactionInBeatTargetKey(candidate))) return candidate;
    }
    current = current.parent || null;
  }
  return deepestCandidate;
}

function interactionInBeatHitObjectIsVisible(viewer, object) {
  let current = object || null;
  while (current && current !== viewer?.scene) {
    if (current.visible === false) return false;
    current = current.parent || null;
  }
  return Boolean(object);
}

function selectInteractionInBeatCandidateFromViewer(viewer, candidate) {
  if (viewer?.editorContext?.targetType !== "in-beat" || !candidate) return false;
  const key = interactionInBeatTargetKey(candidate);
  if (!key) return false;
  const configured = interactionInBeatTargetsForContext(viewer.editorContext.sceneContext)
    .some((target) => interactionInBeatTargetKey(target) === key);
  if (!configured) {
    state.interactionViewerCameraState = captureInteractionViewerCameraState();
    return addInteractionInBeatCandidate(candidate);
  }
  if (state.interactionSelectedInBeatTargetKey === key) return true;
  expandInteractionInBeatCandidateGroup(candidate);
  state.interactionSelectedInBeatTargetKey = key;
  state.interactionViewerCameraState = captureInteractionViewerCameraState();
  renderPreservingScroll();
  return true;
}

function initializeInteractionInBeatViewportPicking(viewer) {
  if (
    viewer?.editorContext?.targetType !== "in-beat"
    || viewer.disposed
    || viewer.interactionInBeatPickPointerDownHandler
  ) return;
  const canvas = viewer.renderer?.domElement;
  if (!canvas || !viewer.camera) return;
  const raycaster = new THREE.Raycaster();
  const pointer = new THREE.Vector2();
  const clickMovementThresholdSquared = 36;

  viewer.interactionInBeatPickPointerDownHandler = (event) => {
    if (
      event.button !== 0
      || event.isPrimary === false
      || viewer.disposed
      || viewer.draggingInteraction
      || viewer.transformControls?.dragging
      || viewer.transformControls?.axis
      || viewer.controls?.enabled === false
    ) return;
    viewer.interactionInBeatPickGesture = {
      pointerId: event.pointerId,
      clientX: event.clientX,
      clientY: event.clientY,
      moved: false,
      blocked: false,
    };
  };

  viewer.interactionInBeatPickPointerMoveHandler = (event) => {
    const gesture = viewer.interactionInBeatPickGesture;
    if (!gesture || gesture.pointerId !== event.pointerId) return;
    const deltaX = event.clientX - gesture.clientX;
    const deltaY = event.clientY - gesture.clientY;
    if (deltaX * deltaX + deltaY * deltaY > clickMovementThresholdSquared) gesture.moved = true;
  };

  viewer.interactionInBeatPickPointerUpHandler = (event) => {
    const gesture = viewer.interactionInBeatPickGesture;
    if (!gesture || gesture.pointerId !== event.pointerId) return;
    viewer.interactionInBeatPickGesture = null;
    const deltaX = event.clientX - gesture.clientX;
    const deltaY = event.clientY - gesture.clientY;
    const moved = gesture.moved || deltaX * deltaX + deltaY * deltaY > clickMovementThresholdSquared;
    if (
      event.button !== 0
      || moved
      || gesture.blocked
      || viewer.disposed
      || viewer.draggingInteraction
      || viewer.transformControls?.dragging
      || viewer.transformControls?.axis
      || viewer.controls?.enabled === false
    ) return;
    const rect = canvas.getBoundingClientRect();
    if (
      !rect.width
      || !rect.height
      || event.clientX < rect.left
      || event.clientX > rect.right
      || event.clientY < rect.top
      || event.clientY > rect.bottom
    ) return;
    pointer.x = ((event.clientX - rect.left) / rect.width) * 2 - 1;
    pointer.y = -((event.clientY - rect.top) / rect.height) * 2 + 1;
    raycaster.setFromCamera(pointer, viewer.camera);
    const ghostEndpoint = interactionConstraintEndpointFromHits(
      viewer,
      raycaster.intersectObjects(viewer.interactionConstraintGhostPickTargets || [], true)
        .filter((candidateHit) => interactionInBeatHitObjectIsVisible(viewer, candidateHit.object)),
    );
    if (ghostEndpoint) {
      event.preventDefault();
      event.stopPropagation();
      interactionLogger.recordSemanticClick(event, {
        kind: "interaction-constraint-endpoint",
        label: `${ghostEndpoint === "max" ? "Maximum" : "Minimum"} movement limit`,
        id: ghostEndpoint,
        action: "select-movement-limit",
      });
      activateInteractionConstraintEndpoint(viewer, ghostEndpoint);
      return;
    }
    const hit = raycaster.intersectObjects(viewer.spatialPickTargets || [], true)
      .find((candidateHit) => interactionInBeatHitObjectIsVisible(viewer, candidateHit.object)) || null;
    const candidate = interactionInBeatCandidateForObject(viewer, hit?.object);
    if (!candidate) return;
    event.preventDefault();
    event.stopPropagation();
    interactionLogger.recordSemanticClick(event, {
      kind: "interaction-scene-object",
      label: candidate.label || candidate.assetId || candidate.entityId,
      id: interactionInBeatTargetKey(candidate),
      assetId: candidate.assetId,
      entityId: candidate.entityId,
      action: "select-interaction-object",
    });
    selectInteractionInBeatCandidateFromViewer(viewer, candidate);
  };

  viewer.interactionInBeatPickPointerCancelHandler = (event) => {
    if (viewer.interactionInBeatPickGesture?.pointerId === event.pointerId) {
      viewer.interactionInBeatPickGesture = null;
    }
  };

  canvas.addEventListener("pointerdown", viewer.interactionInBeatPickPointerDownHandler);
  window.addEventListener("pointermove", viewer.interactionInBeatPickPointerMoveHandler);
  window.addEventListener("pointerup", viewer.interactionInBeatPickPointerUpHandler);
  window.addEventListener("pointercancel", viewer.interactionInBeatPickPointerCancelHandler);
}

function registerInteractionInBeatTargetCandidate(viewer, candidate) {
  if (viewer?.componentId !== "interaction-control" || !candidate?.object || !candidate.entityId || !candidate.assetId) return null;
  const normalized = {
    entityId: String(candidate.entityId),
    assetId: String(candidate.assetId),
    ...(candidate.nodePath ? { nodePath: String(candidate.nodePath) } : {}),
    ...(candidate.nodeIndex != null ? { nodeIndex: Number(candidate.nodeIndex) } : {}),
    coordinateSpace: "local",
    label: String(candidate.label || candidate.nodePath || candidate.assetId),
    object: candidate.object,
    initialTransform: normalizeSpatialTransform(candidate.initialTransform || interactionObjectTransform(candidate.object)),
  };
  const key = interactionInBeatTargetKey(normalized);
  if (!key) return null;
  viewer.interactionTargetCandidates.set(key, normalized);
  viewer.interactionTargetCandidateByObject.set(candidate.object, normalized);
  if (!candidate.suppressRefresh) refreshInteractionInBeatTargetPicker(viewer);
  return normalized;
}

function interactionGltfNodeIndex(parser, object) {
  const association = parser?.associations?.get?.(object);
  const value = association?.nodes;
  return Number.isSafeInteger(Number(value)) && Number(value) >= 0 ? Number(value) : null;
}

function interactionGltfPartHasExternalSkeleton(object) {
  if (!object?.traverse) return false;
  const subtree = new Set();
  const skinnedMeshes = [];
  object.traverse((descendant) => {
    subtree.add(descendant);
    if (descendant.isSkinnedMesh) skinnedMeshes.push(descendant);
  });
  return skinnedMeshes.some((mesh) => mesh.skeleton?.bones?.some((bone) => !subtree.has(bone)));
}

function registerInteractionInBeatGltfParts(viewer, { entityId, assetId, label, sceneRoot, parser }) {
  if (viewer?.componentId !== "interaction-control" || !sceneRoot?.traverse) return [];
  const registered = [];
  sceneRoot.traverse((object) => {
    if (registered.length >= 160 || object === sceneRoot || !object?.parent || object.isBone || object.isSkinnedMesh) return;
    if (!object.isMesh && !object.isGroup) return;
    if (interactionGltfPartHasExternalSkeleton(object)) return;
    const nodeIndex = interactionGltfNodeIndex(parser, object);
    const nodePath = sourcePartNodePath(object, sceneRoot);
    if (!nodePath && nodeIndex == null) return;
    if (nodeIndex != null) object.userData.storyvrGltfNodeIndex = nodeIndex;
    const candidate = registerInteractionInBeatTargetCandidate(viewer, {
      entityId,
      assetId,
      nodePath,
      ...(nodeIndex != null ? { nodeIndex } : {}),
      label: `${label || assetId} · ${nodePath || `Node ${nodeIndex}`}`,
      object,
      initialTransform: interactionObjectTransform(object),
      suppressRefresh: true,
    });
    if (candidate) registered.push(candidate);
  });
  refreshInteractionInBeatTargetPicker(viewer);
  return registered;
}

function interactionInBeatCandidateGroups(viewer) {
  const candidates = [...(viewer?.interactionTargetCandidates?.values?.() || [])];
  const groupsByEntity = new Map();
  for (const candidate of candidates) {
    const key = String(candidate.entityId || candidate.assetId || interactionInBeatTargetKey(candidate));
    const group = groupsByEntity.get(key) || { key, label: "", candidates: [] };
    const part = Boolean(candidate.nodePath || candidate.nodeIndex != null);
    if (!part) group.label = candidate.label;
    group.candidates.push(candidate);
    groupsByEntity.set(key, group);
  }
  return [...groupsByEntity.values()]
    .map((group) => ({
      ...group,
      label: group.label || group.candidates[0]?.assetId || group.key,
      candidates: group.candidates.sort((left, right) => {
        const leftPart = left.nodePath || left.nodeIndex != null ? 1 : 0;
        const rightPart = right.nodePath || right.nodeIndex != null ? 1 : 0;
        return leftPart - rightPart
          || String(left.nodePath || left.label).localeCompare(String(right.nodePath || right.label));
      }),
    }))
    .sort((left, right) => left.label.localeCompare(right.label));
}

function interactionInBeatCandidateRows(viewer) {
  return interactionInBeatCandidateGroups(viewer).flatMap((group) => group.candidates);
}

function expandInteractionInBeatCandidateGroup(candidate) {
  const part = Boolean(candidate?.nodePath || candidate?.nodeIndex != null);
  const key = String(candidate?.entityId || candidate?.assetId || "");
  if (!part || !key) return false;
  state.interactionExpandedInBeatCandidateGroups.add(key);
  return true;
}

function addInteractionInBeatCandidate(candidate) {
  if (!candidate) return false;
  expandInteractionInBeatCandidateGroup(candidate);
  const key = interactionInBeatTargetKey(candidate);
  return commitInteractionInBeatMutation("Add interactive object", (record) => {
    record.targets = record.targets.filter((target) => {
      if (target.entityId !== candidate.entityId) return true;
      const existingPart = Boolean(target.nodePath || target.nodeIndex != null);
      const nextPart = Boolean(candidate.nodePath || candidate.nodeIndex != null);
      if (!existingPart || !nextPart) return false;
      if (target.nodePath && candidate.nodePath) {
        return !target.nodePath.startsWith(`${candidate.nodePath}/`)
          && !candidate.nodePath.startsWith(`${target.nodePath}/`);
      }
      return interactionInBeatTargetKey(target) !== key;
    });
    record.targets.push({
      entityId: candidate.entityId,
      assetId: candidate.assetId,
      ...(candidate.nodePath ? { nodePath: candidate.nodePath } : {}),
      ...(candidate.nodeIndex != null ? { nodeIndex: candidate.nodeIndex } : {}),
      coordinateSpace: "local",
      oneHandGrabbable: true,
      twoHandScalable: false,
      initialTransform: cloneJson(candidate.initialTransform),
    });
    state.interactionSelectedInBeatTargetKey = key;
  });
}

function removeInteractionInBeatCandidate(key) {
  return commitInteractionInBeatMutation("Remove interactive object", (record) => {
    record.targets = record.targets.filter((target) => interactionInBeatTargetKey(target) !== key);
    state.interactionSelectedInBeatTargetKey = interactionInBeatTargetKey(record.targets[0]) || null;
  });
}

function refreshInteractionInBeatTargetPicker(viewer) {
  if (viewer?.editorContext?.targetType !== "in-beat" || viewer.disposed) return;
  const container = document.querySelector("[data-interaction-inbeat-candidates]");
  if (!container) return;
  const configuredTargets = interactionInBeatTargetsForContext(viewer.editorContext.sceneContext);
  const configuredByKey = new Map(configuredTargets.map((target) => [interactionInBeatTargetKey(target), target]));
  const candidateGroups = interactionInBeatCandidateGroups(viewer);
  const candidates = candidateGroups.flatMap((group) => group.candidates);
  const loadedKeys = new Set(candidates.map((candidate) => interactionInBeatTargetKey(candidate)));
  const unavailableByEntity = new Map();
  for (const target of configuredTargets) {
    const key = interactionInBeatTargetKey(target);
    if (loadedKeys.has(key)) continue;
    const entityKey = String(target.entityId || target.assetId || key);
    const unavailable = unavailableByEntity.get(entityKey) || [];
    unavailable.push(target);
    unavailableByEntity.set(entityKey, unavailable);
  }
  const renderCandidateRow = (candidate, unavailable = false) => {
    const key = interactionInBeatTargetKey(candidate);
    const configured = configuredByKey.get(key) || null;
    const part = Boolean(candidate.nodePath || candidate.nodeIndex != null);
    const label = part
      ? candidate.nodePath || `Node ${candidate.nodeIndex}`
      : candidate.label || candidate.assetId;
    return `
      <label class="interaction-inbeat-candidate ${part ? "part" : "whole"} ${configured ? "configured" : ""} ${state.interactionSelectedInBeatTargetKey === key ? "selected" : ""} ${unavailable ? "unavailable" : ""}">
        <input type="checkbox" data-interaction-inbeat-candidate="${escapeHtml(key)}" ${configured ? "checked" : ""}/>
        <button type="button" data-interaction-inbeat-select-candidate="${escapeHtml(key)}"><strong>${escapeHtml(label)}</strong><small>${escapeHtml(unavailable ? "Saved object unavailable in loaded 3D model" : part ? "Model part" : "Whole model")}</small></button>
      </label>`;
  };
  const rows = candidateGroups.map((group) => {
    const unavailable = unavailableByEntity.get(group.key) || [];
    unavailableByEntity.delete(group.key);
    const wholeRows = group.candidates
      .filter((candidate) => !candidate.nodePath && candidate.nodeIndex == null)
      .map((candidate) => renderCandidateRow(candidate));
    const partRows = [
      ...group.candidates.filter((candidate) => candidate.nodePath || candidate.nodeIndex != null),
      ...unavailable.filter((target) => target.nodePath || target.nodeIndex != null),
    ].map((candidate) => renderCandidateRow(candidate, !loadedKeys.has(interactionInBeatTargetKey(candidate))));
    const unavailableWholeRows = unavailable
      .filter((target) => !target.nodePath && target.nodeIndex == null)
      .map((target) => renderCandidateRow(target, true));
    const expanded = state.interactionExpandedInBeatCandidateGroups.has(group.key);
    return `<div class="interaction-inbeat-candidate-group" role="group" aria-label="${escapeHtml(group.label)}">
      ${wholeRows.join("")}
      ${unavailableWholeRows.join("")}
      ${partRows.length ? `<details class="interaction-inbeat-candidate-parts" data-interaction-inbeat-candidate-parts="${escapeHtml(group.key)}" ${expanded ? "open" : ""}>
        <summary>${partRows.length} model part${partRows.length === 1 ? "" : "s"}</summary>
        <div class="interaction-inbeat-candidate-children">${partRows.join("")}</div>
      </details>` : ""}
    </div>`;
  });
  for (const [entityKey, unavailable] of unavailableByEntity) {
    rows.push(`<div class="interaction-inbeat-candidate-group unavailable" role="group" aria-label="${escapeHtml(entityKey)}">${unavailable.map((target) => renderCandidateRow(target, true)).join("")}</div>`);
  }
  container.innerHTML = rows.join("") || `<p class="muted">No 3D models are available in this exact scene.</p>`;
  for (const checkbox of container.querySelectorAll("[data-interaction-inbeat-candidate]")) {
    checkbox.addEventListener("change", () => {
      const key = checkbox.dataset.interactionInbeatCandidate;
      if (!checkbox.checked) {
        removeInteractionInBeatCandidate(key);
        return;
      }
      addInteractionInBeatCandidate(viewer.interactionTargetCandidates.get(key));
    });
  }
  for (const button of container.querySelectorAll("[data-interaction-inbeat-select-candidate]")) {
    button.addEventListener("click", () => {
      const key = button.dataset.interactionInbeatSelectCandidate;
      if (!configuredByKey.has(key)) {
        addInteractionInBeatCandidate(viewer.interactionTargetCandidates.get(key));
        return;
      }
      state.interactionSelectedInBeatTargetKey = key;
      renderPreservingScroll();
    });
  }
  for (const details of container.querySelectorAll("[data-interaction-inbeat-candidate-parts]")) {
    details.addEventListener("toggle", () => {
      const key = details.dataset.interactionInbeatCandidateParts;
      if (details.open) state.interactionExpandedInBeatCandidateGroups.add(key);
      else state.interactionExpandedInBeatCandidateGroups.delete(key);
    });
  }
  requestAnimationFrame(() => {
    if (viewer.disposed || !container.isConnected || !state.interactionSelectedInBeatTargetKey) return;
    const selectedButton = [...container.querySelectorAll("[data-interaction-inbeat-select-candidate]")]
      .find((button) => button.dataset.interactionInbeatSelectCandidate === state.interactionSelectedInBeatTargetKey);
    selectedButton?.closest(".interaction-inbeat-candidate")?.scrollIntoView({ block: "nearest", inline: "nearest" });
  });
}

function interactionConstraintEndpointLocalTransform(target, requestedEndpoint = state.interactionConstraintEndpoint) {
  const transform = normalizeSpatialTransform(target?.initialTransform);
  const endpoint = requestedEndpoint === "max" ? "max" : "min";
  if (target?.constraints?.position) transform.position = cloneJson(target.constraints.position[endpoint]);
  if (target?.constraints?.rotation) {
    const values = target.constraints.rotation[`${endpoint}Degrees`];
    const euler = new THREE.Euler(...values.map((value) => THREE.MathUtils.degToRad(value)), "XYZ");
    transform.quaternion = new THREE.Quaternion().setFromEuler(euler).normalize().toArray();
  }
  if (target?.constraints?.scale) transform.scale = cloneJson(target.constraints.scale[endpoint]);
  return transform;
}

function interactionWorldTransformForLocal(parent, transform) {
  const normalized = normalizeSpatialTransform(transform);
  const matrix = new THREE.Matrix4().compose(
    new THREE.Vector3(...normalized.position),
    new THREE.Quaternion(...normalized.quaternion).normalize(),
    new THREE.Vector3(...normalized.scale),
  );
  if (parent) {
    parent.updateWorldMatrix(true, false);
    matrix.premultiply(parent.matrixWorld);
  }
  const position = new THREE.Vector3();
  const quaternion = new THREE.Quaternion();
  const scale = new THREE.Vector3();
  matrix.decompose(position, quaternion, scale);
  return { position: position.toArray(), quaternion: quaternion.normalize().toArray(), scale: scale.toArray() };
}

function interactionLocalTransformForWorld(parent, object) {
  object.updateWorldMatrix(true, true);
  const matrix = object.matrixWorld.clone();
  if (parent) {
    parent.updateWorldMatrix(true, false);
    matrix.premultiply(parent.matrixWorld.clone().invert());
  }
  const position = new THREE.Vector3();
  const quaternion = new THREE.Quaternion();
  const scale = new THREE.Vector3();
  matrix.decompose(position, quaternion, scale);
  return normalizeSpatialTransform({ position: position.toArray(), quaternion: quaternion.normalize().toArray(), scale: scale.toArray() });
}

function interactionConstraintEndpointColor(endpoint) {
  return endpoint === "max" ? 0xc75f1f : 0x007f73;
}

function makeInteractionConstraintGhostMaterial(sourceMaterial, endpoint) {
  const color = new THREE.Color(interactionConstraintEndpointColor(endpoint));
  const material = sourceMaterial?.isShaderMaterial
    ? new THREE.MeshBasicMaterial({ color })
    : sourceMaterial?.clone?.() || new THREE.MeshStandardMaterial({ color, roughness: 0.42, metalness: 0.04 });
  if (material.color?.isColor) material.color.lerp(color, 0.62);
  if (material.emissive?.isColor) {
    material.emissive.copy(color);
    material.emissiveIntensity = Math.max(Number(material.emissiveIntensity) || 0, 0.42);
  }
  material.transparent = true;
  material.opacity = 0.34;
  material.depthWrite = false;
  material.depthTest = true;
  material.polygonOffset = true;
  material.polygonOffsetFactor = endpoint === "max" ? -2.4 : -1.6;
  material.polygonOffsetUnits = endpoint === "max" ? -2.4 : -1.6;
  material.userData = {
    ...(material.userData || {}),
    storyvrInteractionConstraintGhost: true,
    storyvrInteractionConstraintGhostOpacity: material.opacity,
  };
  material.needsUpdate = true;
  return material;
}

function makeInteractionConstraintGhost(candidate, target, endpoint) {
  let handle = null;
  try {
    handle = cloneSkinnedObject(candidate.object);
  } catch {
    handle = candidate.object.clone?.(true) || null;
  }
  if (!handle) return null;
  const materials = [];
  const ownedGeometries = [];
  const skeletons = new Set();
  let renderableCount = 0;
  handle.name = `StoryVR ${endpoint} interaction constraint ghost · ${target.nodePath || target.assetId}`;
  handle.traverse((node) => {
    node.userData = {
      ...(node.userData || {}),
      interactionConstraintEndpoint: endpoint,
      storyvrInteractionConstraintGhost: true,
    };
    if (node.isCamera || node.isLight || node.isAudio) {
      node.visible = false;
      return;
    }
    if (node.isSkinnedMesh && node.skeleton) skeletons.add(node.skeleton);
    if (!node.isMesh && !node.isLine && !node.isPoints) return;
    const sourceMaterials = Array.isArray(node.material)
      ? node.material
      : node.material ? [node.material] : [];
    const ghostMaterials = sourceMaterials.length
      ? sourceMaterials.map((material) => makeInteractionConstraintGhostMaterial(material, endpoint))
      : [makeInteractionConstraintGhostMaterial(null, endpoint)];
    materials.push(...ghostMaterials);
    node.material = Array.isArray(node.material) ? ghostMaterials : ghostMaterials[0];
    node.castShadow = false;
    node.receiveShadow = false;
    node.renderOrder = endpoint === "max" ? 32 : 31;
    renderableCount += 1;
  });
  if (!renderableCount) {
    const geometry = new THREE.BoxGeometry(0.42, 0.42, 0.42);
    const material = makeInteractionConstraintGhostMaterial(null, endpoint);
    const fallback = new THREE.Mesh(geometry, material);
    fallback.userData.interactionConstraintEndpoint = endpoint;
    fallback.userData.storyvrInteractionConstraintGhost = true;
    handle.add(fallback);
    materials.push(material);
    ownedGeometries.push(geometry);
  }
  applyInteractionTransformToObject(
    handle,
    interactionWorldTransformForLocal(
      candidate.object.parent,
      interactionConstraintEndpointLocalTransform(target, endpoint),
    ),
  );
  const label = makeTextSprite(`${endpoint === "max" ? "Maximum" : "Minimum"} · ${target.nodePath || target.assetId}`, {
    fontSize: 42,
    background: endpoint === "max" ? "rgba(255,239,223,0.96)" : "rgba(225,247,242,0.96)",
    color: endpoint === "max" ? "#a84416" : "#006b62",
    padding: 10,
    width: 0.98,
    height: 0.24,
  });
  label.name = `StoryVR ${endpoint} interaction constraint label`;
  label.userData.interactionConstraintEndpoint = endpoint;
  label.userData.storyvrInteractionConstraintGhost = true;
  label.material.depthTest = false;
  label.renderOrder = endpoint === "max" ? 42 : 41;
  return {
    endpoint,
    handle,
    label,
    materials,
    ownedGeometries,
    skeletons,
    pickTargets: [handle],
  };
}

function updateInteractionConstraintGhostLabel(record) {
  if (!record?.handle || !record.label) return;
  record.handle.updateWorldMatrix(true, true);
  const bounds = new THREE.Box3().setFromObject(record.handle);
  const center = record.handle.getWorldPosition(new THREE.Vector3());
  let top = center.y + 0.38;
  let width = 0.5;
  if (!bounds.isEmpty()) {
    bounds.getCenter(center);
    const size = bounds.getSize(new THREE.Vector3());
    top = bounds.max.y + Math.max(0.16, Math.min(size.y * 0.16, 0.42));
    width = Math.max(size.x, size.z, 0.5);
  }
  const sideOffset = Math.max(0.16, Math.min(width * 0.16, 0.34));
  record.label.position.set(
    center.x + (record.endpoint === "max" ? sideOffset : -sideOffset),
    top,
    center.z,
  );
}

function makeInteractionConstraintRangeVisual() {
  const group = new THREE.Group();
  group.name = "StoryVR interaction movement range";
  group.matrixAutoUpdate = false;
  const geometry = new THREE.BoxGeometry(1, 1, 1);
  const fillMaterial = new THREE.MeshBasicMaterial({
    color: 0x5eac96,
    transparent: true,
    opacity: 0.07,
    depthWrite: false,
    side: THREE.DoubleSide,
  });
  const fill = new THREE.Mesh(geometry, fillMaterial);
  const edgesGeometry = new THREE.EdgesGeometry(geometry);
  const edgesMaterial = new THREE.LineBasicMaterial({ color: 0x2e776c, transparent: true, opacity: 0.56, depthWrite: false });
  const edges = new THREE.LineSegments(edgesGeometry, edgesMaterial);
  for (const object of [fill, edges]) {
    object.raycast = () => {};
    object.renderOrder = 24;
    group.add(object);
  }
  group.visible = false;
  return {
    group,
    fill,
    edges,
    geometries: [geometry, edgesGeometry],
    materials: [fillMaterial, edgesMaterial],
  };
}

function interactionConstraintTargetForViewer(viewer) {
  const key = state.interactionSelectedInBeatTargetKey;
  return interactionInBeatTargetsForContext(viewer?.editorContext?.sceneContext)
    .find((candidate) => interactionInBeatTargetKey(candidate) === key) || null;
}

function refreshInteractionConstraintRangeVisual(viewer) {
  const visual = viewer?.interactionConstraintRangeVisual;
  const target = interactionConstraintTargetForViewer(viewer);
  const candidate = viewer?.interactionTargetCandidates?.get?.(state.interactionSelectedInBeatTargetKey);
  const minGhost = viewer?.interactionConstraintGhosts?.get?.("min");
  const maxGhost = viewer?.interactionConstraintGhosts?.get?.("max");
  if (!visual || !target || !candidate || !minGhost || !maxGhost) return false;
  for (const ghost of [minGhost, maxGhost]) updateInteractionConstraintGhostLabel(ghost);
  const visible = Boolean(
    target.constraints?.position
    && state.interactionConstraintTransformMode === "translate",
  );
  visual.group.visible = visible;
  if (!visible) return false;
  const minLocal = interactionLocalTransformForWorld(candidate.object.parent, minGhost.handle).position;
  const maxLocal = interactionLocalTransformForWorld(candidate.object.parent, maxGhost.handle).position;
  const ordered = interactionInBeatOrderedRange(minLocal, maxLocal);
  const center = ordered.min.map((value, index) => (value + ordered.max[index]) / 2);
  const size = ordered.min.map((value, index) => Math.max(0.012, ordered.max[index] - value));
  candidate.object.parent?.updateWorldMatrix(true, false);
  visual.group.matrix.copy(candidate.object.parent?.matrixWorld || new THREE.Matrix4());
  for (const object of [visual.fill, visual.edges]) {
    object.position.fromArray(center);
    object.quaternion.identity();
    object.scale.fromArray(size);
  }
  visual.group.updateMatrixWorld(true);
  return true;
}

function syncInteractionConstraintGhostAppearance(viewer) {
  const activeEndpoint = state.interactionConstraintEndpoint === "max" ? "max" : "min";
  for (const [endpoint, record] of viewer?.interactionConstraintGhosts || []) {
    const active = endpoint === activeEndpoint;
    for (const material of record.materials || []) {
      const base = Number(material.userData?.storyvrInteractionConstraintGhostOpacity) || 0.34;
      material.opacity = active ? Math.min(0.5, base * 1.28) : base * 0.68;
      material.needsUpdate = true;
    }
    record.label.material.opacity = active ? 1 : 0.72;
    record.label.scale.set(active ? 1.02 : 0.9, active ? 0.25 : 0.22, 1);
  }
}

function syncInteractionConstraintEndpointControls(endpoint) {
  for (const button of document.querySelectorAll("[data-interaction-constraint-endpoint]")) {
    const selected = button.dataset.interactionConstraintEndpoint === endpoint;
    button.classList.toggle("selected", selected);
    button.setAttribute("aria-pressed", String(selected));
  }
  for (const row of document.querySelectorAll("[data-interaction-inbeat-range-row]")) {
    row.classList.toggle("selected", row.dataset.interactionInbeatRangeRow === endpoint);
  }
  const status = document.querySelector("[data-interaction-constraint-endpoint-status]");
  if (status) status.textContent = endpoint === "max" ? "Maximum ghost active" : "Minimum ghost active";
}

function activateInteractionConstraintEndpoint(viewer, requestedEndpoint) {
  if (viewer?.editorContext?.targetType !== "in-beat" || viewer.disposed) return false;
  const endpoint = requestedEndpoint === "max" ? "max" : "min";
  const ghost = viewer.interactionConstraintGhosts?.get?.(endpoint);
  if (!ghost?.handle || !viewer.transformControls) return false;
  state.interactionConstraintEndpoint = endpoint;
  viewer.interactionConstraintProxy = ghost.handle;
  viewer.transformControls.attach(ghost.handle);
  syncInteractionConstraintGhostAppearance(viewer);
  syncInteractionConstraintEndpointControls(endpoint);
  refreshInteractionConstraintRangeVisual(viewer);
  return true;
}

function interactionConstraintEndpointForObject(viewer, object) {
  let current = object || null;
  while (current && current !== viewer?.scene) {
    const endpoint = current.userData?.interactionConstraintEndpoint;
    if (["min", "max"].includes(endpoint) && viewer?.interactionConstraintGhosts?.has?.(endpoint)) return endpoint;
    current = current.parent || null;
  }
  return null;
}

function interactionConstraintEndpointFromHits(viewer, hits) {
  const endpoints = new Map();
  for (const hit of hits || []) {
    const endpoint = interactionConstraintEndpointForObject(viewer, hit?.object);
    if (endpoint && !endpoints.has(endpoint)) endpoints.set(endpoint, Number(hit.distance) || 0);
  }
  const ordered = [...endpoints.entries()].sort((left, right) => left[1] - right[1]);
  if (!ordered.length) return null;
  const active = state.interactionConstraintEndpoint === "max" ? "max" : "min";
  const inactive = ordered.find(([endpoint]) => endpoint !== active);
  if (inactive && Math.abs(inactive[1] - ordered[0][1]) <= 1e-4) return inactive[0];
  return ordered[0][0];
}

function syncInteractionConstraintGhostTransforms(viewer) {
  const target = interactionConstraintTargetForViewer(viewer);
  const candidate = viewer?.interactionTargetCandidates?.get?.(state.interactionSelectedInBeatTargetKey);
  if (!target || !candidate) return false;
  for (const [endpoint, ghost] of viewer.interactionConstraintGhosts || []) {
    applyInteractionTransformToObject(
      ghost.handle,
      interactionWorldTransformForLocal(
        candidate.object.parent,
        interactionConstraintEndpointLocalTransform(target, endpoint),
      ),
    );
    updateInteractionConstraintGhostLabel(ghost);
  }
  refreshInteractionConstraintRangeVisual(viewer);
  return true;
}

function clearInteractionConstraintGhosts(viewer) {
  if (!viewer) return;
  const handles = new Set([...(viewer.interactionConstraintGhosts?.values?.() || [])].map((record) => record.handle));
  if (handles.has(viewer.transformControls?.object)) viewer.transformControls.detach();
  for (const record of viewer.interactionConstraintGhosts?.values?.() || []) {
    record.handle?.removeFromParent();
    record.label?.removeFromParent();
    for (const material of record.materials || []) material.dispose?.();
    for (const geometry of record.ownedGeometries || []) geometry.dispose?.();
    for (const skeleton of record.skeletons || []) skeleton.dispose?.();
    record.label?.material?.map?.dispose?.();
    record.label?.material?.dispose?.();
  }
  viewer.interactionConstraintGhosts?.clear?.();
  viewer.interactionConstraintGhostPickTargets = [];
  const visual = viewer.interactionConstraintRangeVisual;
  visual?.group?.removeFromParent();
  for (const geometry of visual?.geometries || []) geometry.dispose?.();
  for (const material of visual?.materials || []) material.dispose?.();
  viewer.interactionConstraintRangeVisual = null;
  viewer.interactionConstraintProxy = null;
  viewer.interactionConstraintTargetObject = null;
}

function initializeInteractionInBeatConstraintGizmo(viewer) {
  const key = state.interactionSelectedInBeatTargetKey;
  const target = interactionInBeatTargetsForContext(viewer.editorContext.sceneContext)
    .find((candidate) => interactionInBeatTargetKey(candidate) === key);
  const candidate = viewer.interactionTargetCandidates.get(key);
  const modes = interactionInBeatConstraintModes(target);
  if (!target || !candidate || !modes.length) return;
  if (!modes.some((item) => item.mode === state.interactionConstraintTransformMode)) {
    state.interactionConstraintTransformMode = modes[0].mode;
  }
  clearInteractionConstraintGhosts(viewer);
  for (const endpoint of ["min", "max"]) {
    const ghost = makeInteractionConstraintGhost(candidate, target, endpoint);
    if (!ghost) continue;
    viewer.interactionConstraintGhosts.set(endpoint, ghost);
    viewer.interactionConstraintGhostPickTargets.push(...ghost.pickTargets);
    viewer.scene.add(ghost.handle, ghost.label);
    updateInteractionConstraintGhostLabel(ghost);
  }
  if (viewer.interactionConstraintGhosts.size !== 2) {
    clearInteractionConstraintGhosts(viewer);
    return;
  }
  viewer.interactionConstraintRangeVisual = makeInteractionConstraintRangeVisual();
  viewer.scene.add(viewer.interactionConstraintRangeVisual.group);
  viewer.interactionConstraintTargetObject = candidate.object;
  const transformControls = new TransformControls(viewer.camera, viewer.renderer.domElement);
  transformControls.setMode(state.interactionConstraintTransformMode);
  transformControls.setSpace("local");
  transformControls.setSize(0.74);
  const helper = transformControls.getHelper();
  viewer.scene.add(helper);
  viewer.transformControls = transformControls;
  viewer.transformHelper = helper;
  activateInteractionConstraintEndpoint(viewer, state.interactionConstraintEndpoint);
  transformControls.addEventListener("dragging-changed", (event) => { viewer.controls.enabled = !event.value; });
  transformControls.addEventListener("mouseDown", () => {
    if (viewer.interactionInBeatPickGesture) viewer.interactionInBeatPickGesture.blocked = true;
    viewer.navigationTransformFinalized = false;
    viewer.destinationHistoryStarted = beginAuthorHistory("Edit object movement range", "interaction-control");
  });
  transformControls.addEventListener("objectChange", () => {
    syncInteractionInBeatRangeInputsFromViewer(viewer);
    refreshInteractionConstraintRangeVisual(viewer);
  });
  transformControls.addEventListener("mouseUp", () => {
    if (viewer.navigationTransformFinalized) {
      viewer.navigationTransformFinalized = false;
      return;
    }
    const activeGhost = transformControls.object;
    const local = interactionLocalTransformForWorld(candidate.object.parent, activeGhost);
    const endpoint = activeGhost?.userData?.interactionConstraintEndpoint === "max" ? "max" : "min";
    const changed = mutateInteractionInBeatRecord(viewer.editorContext.sceneContext, (record) => {
      const nextTarget = interactionInBeatTargetByKey(record, key);
      if (!nextTarget) return;
      if (state.interactionConstraintTransformMode === "translate" && nextTarget.constraints?.position) {
        const opposite = nextTarget.constraints.position[endpoint === "min" ? "max" : "min"];
        nextTarget.constraints.position[endpoint] = local.position.map((value, index) => (
          endpoint === "min" ? Math.min(value, opposite[index]) : Math.max(value, opposite[index])
        ));
      }
      if (state.interactionConstraintTransformMode === "rotate" && nextTarget.constraints?.rotation) {
        const values = interactionTransformEulerDegrees(
          local,
          nextTarget.constraints.rotation[`${endpoint}Degrees`],
        );
        const opposite = nextTarget.constraints.rotation[`${endpoint === "min" ? "max" : "min"}Degrees`];
        nextTarget.constraints.rotation[`${endpoint}Degrees`] = values.map((value, index) => (
          endpoint === "min" ? Math.min(value, opposite[index]) : Math.max(value, opposite[index])
        ));
      }
      if (state.interactionConstraintTransformMode === "scale" && nextTarget.constraints?.scale) {
        const opposite = nextTarget.constraints.scale[endpoint === "min" ? "max" : "min"];
        nextTarget.constraints.scale[endpoint] = local.scale.map((value, index) => (
          endpoint === "min" ? Math.min(value, opposite[index]) : Math.max(value, opposite[index])
        ));
      }
    });
    if (viewer.destinationHistoryStarted && changed) commitAuthorHistory();
    viewer.destinationHistoryStarted = false;
    syncInteractionConstraintGhostTransforms(viewer);
    syncInteractionInBeatRangeInputsFromViewer(viewer);
  });
}

function syncInteractionInBeatRangeInputsFromViewer(viewer) {
  const proxy = viewer?.interactionConstraintProxy;
  const targetObject = viewer?.interactionConstraintTargetObject;
  if (!proxy || !targetObject) return;
  const endpoint = proxy.userData?.interactionConstraintEndpoint === "max" ? "max" : "min";
  state.interactionConstraintEndpoint = endpoint;
  const transform = interactionLocalTransformForWorld(targetObject.parent, proxy);
  const channel = state.interactionConstraintTransformMode === "translate"
    ? "position"
    : state.interactionConstraintTransformMode === "rotate" ? "rotation" : "scale";
  const target = interactionConstraintTargetForViewer(viewer);
  const values = channel === "rotation"
    ? interactionTransformEulerDegrees(
        transform,
        target?.constraints?.rotation?.[`${endpoint}Degrees`],
      )
    : transform[channel];
  for (const input of document.querySelectorAll(`[data-interaction-inbeat-range-input="${channel}"][data-interaction-inbeat-range-endpoint="${endpoint}"]`)) {
    const axis = Number(input.dataset.interactionInbeatRangeAxis);
    if (values?.[axis] != null) input.value = formatNumber(values[axis]);
  }
}

function initializeInteractionConfigurationGizmo(viewer) {
  if (!viewer || viewer.disposed || viewer.transformControls) return;
  if (viewer.editorContext?.targetType === "in-beat") {
    initializeInteractionInBeatConstraintGizmo(viewer);
    return;
  }
  const configuration = viewer.interactionConfiguration;
  let selectedObject = null;
  if (viewer.kind === "embodied-control") {
    const destination = makeInteractionLocomotionDestination(configuration, viewer.readerRig);
    viewer.root.add(destination);
    viewer.destinationObjects.set("locomotion", destination);
    selectedObject = destination;
  } else if (viewer.kind === "direct") {
    for (const target of configuration.targets) {
      const selected = interactionDirectTargetKey(target) === state.interactionSelectedDirectTargetKey;
      const destination = makeInteractionDirectDestination(target, selected, viewer);
      viewer.root.add(destination);
      const key = `${target.entityId}|${target.nodePath || ""}`;
      viewer.destinationObjects.set(key, destination);
      if (selected || !selectedObject) selectedObject = destination;
    }
  }
  if (!selectedObject) return;
  const transformControls = new TransformControls(viewer.camera, viewer.renderer.domElement);
  transformControls.setMode(state.interactionDestinationTransformMode);
  transformControls.setSpace(viewer.kind === "direct" ? "local" : "world");
  transformControls.setSize(0.74);
  const helper = transformControls.getHelper();
  viewer.scene.add(helper);
  transformControls.attach(selectedObject);
  viewer.transformControls = transformControls;
  viewer.transformHelper = helper;
  transformControls.addEventListener("dragging-changed", (event) => {
    viewer.controls.enabled = !event.value;
  });
  transformControls.addEventListener("mouseDown", () => {
    viewer.navigationTransformFinalized = false;
    viewer.destinationHistoryStarted = beginAuthorHistory("Edit object destination", "interaction-control");
  });
  transformControls.addEventListener("objectChange", () => syncInteractionDestinationInputsFromViewer(viewer));
  transformControls.addEventListener("mouseUp", () => {
    if (viewer.navigationTransformFinalized) {
      viewer.navigationTransformFinalized = false;
      return;
    }
    const editorContext = interactionEditorContextFromState();
    const object = transformControls.object;
    if (!editorContext || !object) return;
    const candidate = viewer.interactionTargetCandidates.get(interactionDirectTargetKey({
      entityId: object.userData.interactionEntityId,
      nodePath: object.userData.interactionNodePath || "",
      nodeIndex: object.userData.interactionNodeIndex,
    }));
    const transform = candidate
      ? interactionLocalTransformForWorld(candidate.object.parent, object)
      : interactionObjectTransform(object);
    const changed = mutateInteractionOptionConfiguration(editorContext, (next) => {
      if (editorContext.kind === "embodied-control") {
        next.destination.coordinateSpace = "world";
        next.destination.transform = transform;
      }
      else {
        const target = next.targets.find((candidate) => (
          candidate.entityId === object.userData.interactionEntityId
          && interactionDirectTargetKey(candidate) === interactionDirectTargetKey({
            entityId: object.userData.interactionEntityId,
            nodePath: object.userData.interactionNodePath || "",
            nodeIndex: object.userData.interactionNodeIndex,
          })
        ));
        if (target) {
          target.destinationTransform = transform;
          target.destinationAuthored = true;
          target.suggested = false;
          target.source = "author";
        }
      }
    });
    if (viewer.destinationHistoryStarted && changed) commitAuthorHistory();
    viewer.destinationHistoryStarted = false;
    if (viewer.kind === "direct") {
      state.interactionViewerCameraState = captureInteractionViewerCameraState();
      renderPreservingScroll();
      return;
    }
    syncInteractionDestinationInputsFromViewer(viewer);
  });
}

function syncInteractionDestinationInputsFromViewer(viewer) {
  const object = viewer?.transformControls?.object;
  if (!object) return;
  const candidate = viewer.kind === "direct"
    ? viewer.interactionTargetCandidates?.get?.(interactionDirectTargetKey({
        entityId: object.userData.interactionEntityId,
        nodePath: object.userData.interactionNodePath || "",
        nodeIndex: object.userData.interactionNodeIndex,
      }))
    : null;
  const transform = candidate
    ? interactionLocalTransformForWorld(candidate.object.parent, object)
    : interactionObjectTransform(object);
  const directTarget = viewer.kind === "direct"
    ? viewer.interactionConfiguration?.targets?.find((target) => interactionDirectTargetKey(target) === interactionDirectTargetKey({
        entityId: object.userData.interactionEntityId,
        nodePath: object.userData.interactionNodePath || "",
        nodeIndex: object.userData.interactionNodeIndex,
      }))
    : null;
  const rotation = interactionTransformEulerDegrees(
    transform,
    interactionRotationRangeReference(directTarget?.constraints?.rotation),
  );
  for (const input of document.querySelectorAll("[data-interaction-transform-input]")) {
    const part = input.dataset.interactionTransformPart;
    const index = Number(input.dataset.interactionTransformAxis);
    const values = part === "rotation" ? rotation : transform[part];
    if (values?.[index] != null) input.value = formatNumber(values[index]);
  }
}

function updateInteractionControlBeatLabel(viewer, beat) {
  updatePreviewMetadataEntry(viewer, "beat", shortText(beat?.title || "", 52));
}

function activeInteractionPositionForBeat(viewer, beat) {
  const activeStep = viewer?.cumulativeContext?.sequence?.steps?.[viewer.activeSwapIndex];
  const activeAssetId = activeStep?.assetId
    || beat?.linkedAssetIds?.find((assetId) => viewer?.assetPositions?.has(assetId))
    || beat?.linkedAssetIds?.[0]
    || null;
  const activePosition = viewer?.cumulativeContext
    ? new THREE.Vector3(0, 0, 0)
    : activeAssetId && viewer?.assetPositions?.has(activeAssetId)
    ? viewer.assetPositions.get(activeAssetId).clone()
    : new THREE.Vector3(0, 0, 0);
  return { activeAssetId, activePosition };
}

function interactionRouteAssetPositions(viewer, activeAssetId, activePosition) {
  const positions = new Map(viewer?.assetPositions || []);
  if (activeAssetId) positions.set(activeAssetId, activePosition.clone());
  return positions;
}

function lockedTextPlacementForBeat(beat, textKind, readerKind, sceneContext = null) {
  const contract = lockedSpatialRelationsContract();
  const context = sceneContext?.beatId
    ? spatialSceneContext(sceneContext.beatId, sceneContext.variantGroupId, sceneContext.variantOptionId)
    : null;
  const scene = context ? spatialSceneRecordForContext(contract, context) : null;
  const sceneRelation = context
    ? spatialSceneEntities(contract, context).find((entity) => (
      spatialEntityType(entity) === "text-panel"
      && (!beat?.id || entity.beatId === beat.id || String(entity.id || "").startsWith(`text-panel:${beat.id}`))
    ))
    : null;
  const relation = sceneRelation
    || (!scene ? spatialRelationEntityById(contract, beat?.id ? `text-panel:${beat.id}` : "") : null);
  if (relation) {
    const transform = normalizeSpatialTransform(relation.transform, relation.inferredTransform);
    const rotation = new THREE.Euler().setFromQuaternion(new THREE.Quaternion(...transform.quaternion), "XYZ");
    const anchor = normalizeSpatialAnchor(relation.anchor, relation);
    return {
      coordinateSpace: anchor.type === "source-focus" ? "source-focus" : anchor.type === "asset" ? "asset" : anchor.type === "reader" ? "reader" : "world",
      position: { x: transform.position[0], y: transform.position[1], z: transform.position[2] },
      rotation: { x: rotation.x, y: rotation.y, z: rotation.z },
      scale: 1,
      spatialScale: transform.scale,
      spatialQuaternion: transform.quaternion,
      width: Number(relation.panel?.width) || 1.35,
      height: Number(relation.panel?.height) || 0.72,
      facesReader: relation.orientationPolicy === "reader-facing" || relation.orientationPolicy === "reader-facing-yaw",
      orientationPolicy: relation.orientationPolicy || "fixed",
      anchorAssetId: anchor.assetId || null,
      spatialRelation: relation,
    };
  }
  const decisionPlacement = state.data?.decisions?.[LEGACY_TEXT_COMFORT_COMPONENT_ID]?.textPlacement;
  return effectiveTextPlacementForBeat(decisionPlacement, beat, textKind, readerKind);
}

function addInheritedTextComfortLayer(root, textKind, readerKind, activePosition, beat, sceneContext = null) {
  if (!root || !textKind) return null;
  const group = new THREE.Group();
  root.add(group);
  const activeAnchorPosition = activePosition.clone().add(new THREE.Vector3(0, 0.56, 0));
  const placement = lockedTextPlacementForBeat(beat, textKind, readerKind, sceneContext);
  const panel = makeTextComfortPanel(beat, placement, textKind);
  panel.position.copy(textPlacementWorldPosition(placement, activeAnchorPosition));
  if (placement.spatialQuaternion) panel.quaternion.fromArray(placement.spatialQuaternion);
  else panel.rotation.set(placement.rotation.x, placement.rotation.y, placement.rotation.z);
  if (placement.spatialScale) panel.scale.fromArray(placement.spatialScale);
  group.add(panel);
  const anchorMarker = makeTextAnchorMarker(activeAnchorPosition, "Inherited text anchor");
  group.add(anchorMarker);
  const calloutLine = makeTextPanelCallout(activeAnchorPosition, panel.position);
  group.add(calloutLine);
  return { group, panel, anchorMarker, calloutLine, placement, activeAnchorPosition, orientationPolicy: placement.orientationPolicy || (placement.facesReader ? "reader-facing" : "fixed") };
}

function disposeInteractionCumulativeScene(viewer) {
  for (const object of [
    viewer?.effects?.root,
    viewer?.contextLayers?.root,
    viewer?.inheritedTextLayer?.group,
    viewer?.interactionOverlayGroup,
    viewer?.embodiedProgressionRig?.group,
    viewer?.interactionHandsRig?.group,
    viewer?.descriptionCues?.root,
  ]) {
    if (!object) continue;
    object.removeFromParent();
    disposeObject(object);
  }
  viewer.effects = null;
  viewer.contextLayers = null;
  viewer.inheritedTextLayer = null;
  viewer.interactionOverlayGroup = null;
  viewer.interactionBeatLabel = null;
  viewer.interactionBeatLabelPosition = null;
  viewer.embodiedProgressionRig = null;
  viewer.interactionHandsRig = null;
  viewer.actionTargets = [];
}

function setInteractionDirectManipulationTarget(viewer) {
  if (!viewer || viewer.kind !== "direct") return;
  const entry = viewer.swapGroups?.[viewer.activeSwapIndex];
  const target = entry?.group || viewer.manipulationProxy;
  if (!target) return;
  target.userData.interactionDraggable = true;
  target.userData.directManipulationAsset = true;
  if (!viewer.draggableTargets.includes(target)) viewer.draggableTargets.push(target);
  const offset = state.interactionManipulationOffset || { x: 0, y: 0, z: 0 };
  const basePosition = entry?.basePosition?.clone?.() || viewer.manipulationBasePosition?.clone?.() || target.position.clone();
  target.position.copy(basePosition).add(new THREE.Vector3(offset.x || 0, offset.y || 0, offset.z || 0));
  viewer.manipulationProxy = target;
  viewer.manipulationBasePosition = basePosition;
  if (!viewer.spatialReaderHands) addInteractionReaderHandsRig(viewer, target);
}

function updateInteractionControlCumulativeScene(viewer, beat, kind) {
  if (!viewer?.root || viewer.disposed) return;
  const { activeAssetId, activePosition } = activeInteractionPositionForBeat(viewer, beat);
  viewer.activeAssetId = activeAssetId;
  viewer.activePosition = activePosition;
  viewer.beat = beat;
  viewer.kind = kind;
  const beats = interactionPreviewBeats(viewer.proposal);
  viewer.embodiedRoute = kind === "embodied-control"
    ? embodiedProgressionRouteForBeat(
      beats,
      interactionRouteAssetPositions(viewer, activeAssetId, activePosition),
      clampInteractionBeatIndex(beats),
      viewer.interactionSourceFocus,
    )
    : null;
  disposeInteractionCumulativeScene(viewer);
  viewer.effects = !viewer.usesInheritedSourcePlayback && viewer.geometryKind ? addDynamicEffectOverlays(viewer.root, viewer.geometryKind, activePosition, {
    ...beat,
    title: `Geometry: ${dynamicGeometryKindLabel(viewer.geometryKind)}`,
  }) : null;
  viewer.contextLayers = null;
  viewer.inheritedTextLayer = null;
  viewer.root.add(addInteractionControlOverlays(viewer, kind, activePosition, beat));
  viewer.descriptionCues = null;
  updatePreviewMetadataEntry(viewer, "current-option", interactionControlKindLabel(kind));
  const activeLink = viewer.cumulativeContext?.sequence?.steps?.[viewer.activeSwapIndex]
    || viewer.assetLinks?.find((assetLink) => assetLink.assetId === activeAssetId);
  updatePreviewMetadataEntry(viewer, "active-asset", previewAssetDisplayName(activeLink));
  setInteractionDirectManipulationTarget(viewer);
}

function applyInteractionSourceFocusToInheritedTextLayer(viewer, beat) {
  const layer = viewer?.inheritedTextLayer;
  if (!layer?.panel || layer.placement?.coordinateSpace !== "source-focus") return false;
  const assetId = layer.placement.anchorAssetId || beat?.linkedAssetIds?.[0] || null;
  const focus = assetId ? viewer.interactionSourceFocus?.get(`${beat?.id}:${assetId}`) : null;
  if (!focus) return false;
  layer.activeAnchorPosition.copy(focus);
  layer.panel.position.copy(textPlacementWorldPosition(layer.placement, focus));
  layer.anchorMarker?.position.copy(focus);
  if (layer.calloutLine) updateTextPanelCallout(layer.calloutLine, focus, layer.panel.position);
  return true;
}

function makeInteractionButton(label, action, color) {
  const group = new THREE.Group();
  group.userData.interactionAction = action;
  group.userData.interactionLabel = label;
  const button = new THREE.Mesh(
    new THREE.BoxGeometry(0.62, 0.3, 0.12),
    new THREE.MeshStandardMaterial({ color, roughness: 0.48, emissive: color, emissiveIntensity: 0.06 }),
  );
  button.userData.interactionAction = action;
  button.userData.interactionLabel = label;
  group.add(button);
  const text = makeTextSprite(label, {
    fontSize: 46,
    background: "rgba(255,253,244,0.94)",
    color: "#0f211d",
    padding: 12,
  });
  text.position.set(0, 0.27, 0.04);
  text.scale.set(0.5, 0.18, 1);
  group.add(text);
  return group;
}

function animateInteractionControlViewer(viewer, elapsed) {
  if (!viewer?.root) return;
  const geometryKind = viewerDynamicGeometryKind(viewer);
  if (!viewer.usesInheritedSourcePlayback && geometryKind) animateDynamicEffectOverlays(viewer.effects, geometryKind, elapsed);
  animateContextLayerEffects(viewer, elapsed);
  if (viewer.inheritedTextLayer?.panel) {
    const placement = viewer.inheritedTextLayer.placement;
    if (placement?.facesReader || viewer.textKind === "reader-facing" || viewer.textKind === "near-body" || viewer.textKind === "object-attached") {
      viewer.inheritedTextLayer.panel.lookAt(viewer.camera.position);
    }
    if (viewer.inheritedTextLayer.calloutLine) {
      updateTextPanelCallout(
        viewer.inheritedTextLayer.calloutLine,
        viewer.inheritedTextLayer.activeAnchorPosition,
        viewer.inheritedTextLayer.panel.position,
      );
    }
  }
  updateEmbodiedProgressionReader(viewer, elapsed);
}

function attachInteractionUpstreamPlayback(viewer, entry, gltf) {
  if (viewer?.componentId !== "interaction-control" || !entry || !gltf?.scene) return false;
  entry.sourceScene = gltf.scene;
  const attached = attachSourceTransitionPlayback(viewer, entry, gltf);
  if (!attached) {
    entry.sourcePlaybackContractActive = true;
    gltf.scene.visible = true;
    return false;
  }
  if (entry.sourcePlayback?.asset?.mode === "shared-timeline") {
    applySourcePartMask(gltf.scene, []);
  } else {
    applySourcePartMask(gltf.scene, sourcePartSelectorsForBeatAsset(viewer.sourcePartToBeatId, entry.assetId));
  }
  entry.interactionTransitionPlaying = Boolean(
    viewer.upstreamBeatState?.playTransition
    && entry.sourcePlayback?.windowState?.mode === "scrub",
  );
  entry.interactionTransitionDuration = entry.interactionTransitionPlaying
    ? sourcePlaybackScrubCycleSeconds(
      entry.sourcePlayback.asset,
      entry.sourcePlayback.windowState,
      INTER_BEAT_TRANSITION_CYCLE_SECONDS,
      entry.sourcePlayback.masterDuration,
    )
    : 0;
  viewer.sourcePlaybackEntries.push(entry);
  return true;
}

function updateInteractionUpstreamPlayback(viewer, delta) {
  if (!viewer?.sourcePlaybackReady || !viewer.usesInheritedSourcePlayback) return;
  if (state.topologySwapPlaying) {
    const playbackDelta = Number(delta) * (Number(viewer.speed) || 1);
    viewer.sourceElapsed += Number.isFinite(playbackDelta) && playbackDelta > 0 ? playbackDelta : 0;
  }
  for (const entry of viewer.sourcePlaybackEntries || []) {
    const runtime = entry?.sourcePlayback;
    if (!runtime) continue;
    if (entry.interactionTransitionPlaying) {
      const duration = Math.max(Number(entry.interactionTransitionDuration) || 0, 0.001);
      const holdSeconds = 0.75;
      const cycleElapsed = viewer.sourceElapsed % (duration + holdSeconds);
      const transitionProgress = Math.max(0, Math.min(1, cycleElapsed / duration));
      const sourceProgress = runtime.windowState.startProgress + transitionProgress * (
        runtime.windowState.endProgress - runtime.windowState.startProgress
      );
      seekSourceTransitionPlayback(entry, sourceProgress, viewer.sourceElapsed);
    } else {
      applySourcePlaybackBindings(runtime);
      updateSourcePlaybackAnnotations(runtime);
    }
  }
}

function interactionTraversalStationForBeat(traversal, beat, index) {
  const stations = Array.isArray(traversal?.orderedStations) ? traversal.orderedStations : [];
  return stations.find((station) => station?.beatId === beat?.id
    || station?.readerEntityId === `reader:beat:${beat?.id}`
    || station?.panelEntityId === `text-panel:${beat?.id}`)
    || stations[index]
    || null;
}

function interactionRouteVector(value) {
  if (Array.isArray(value)) return new THREE.Vector3(Number(value[0]) || 0, Number(value[1]) || 0, Number(value[2]) || 0);
  if (value && typeof value === "object") return new THREE.Vector3(Number(value.x) || 0, Number(value.y) || 0, Number(value.z) || 0);
  return null;
}

function interactionAssetAnchorPosition(assetPositions, assetId) {
  const base = assetId && assetPositions?.has(assetId)
    ? assetPositions.get(assetId).clone()
    : new THREE.Vector3();
  const entity = assetId ? spatialRelationEntityById(lockedSpatialRelationsContract(), `glb:${assetId}`) : null;
  if (entity) base.add(new THREE.Vector3(...normalizeSpatialTransform(entity.transform, entity.inferredTransform).position));
  return base;
}

function interactionResolvedReadingPosition(station, beat, assetPositions, previous, sourceFocus = null) {
  const readerPosition = station?.readerPosition && typeof station.readerPosition === "object"
    ? station.readerPosition
    : null;
  const coordinateSpace = readerPosition?.coordinateSpace || station?.anchorType || "world";
  if (coordinateSpace === "reader" || station?.anchorType === "reader") {
    return previous?.clone() || new THREE.Vector3(0, 0, 1.05);
  }
  let position = interactionRouteVector(readerPosition?.position) || interactionRouteVector(station?.position);
  const assetId = readerPosition?.anchorAssetId || station?.anchorAssetId || beat?.linkedAssetIds?.[0] || null;
  if (position) {
    if (coordinateSpace === "source-focus" && sourceFocus?.has(`${beat?.id}:${assetId}`)) {
      position.add(sourceFocus.get(`${beat.id}:${assetId}`));
    } else if (coordinateSpace === "asset" || coordinateSpace === "source-focus") {
      position.add(interactionAssetAnchorPosition(assetPositions, assetId));
    }
    position.y = 0;
    return position;
  }

  const relation = spatialRelationEntityById(lockedSpatialRelationsContract(), beat?.id ? `text-panel:${beat.id}` : "");
  if (!relation) return null;
  const anchor = normalizeSpatialAnchor(relation.anchor, relation);
  if (anchor.type === "reader") return previous?.clone() || new THREE.Vector3(0, 0, 1.05);
  const transform = normalizeSpatialTransform(relation.transform, relation.inferredTransform);
  const panelPosition = new THREE.Vector3(...transform.position);
  if (anchor.type === "source-focus" && sourceFocus?.has(`${beat?.id}:${anchor.assetId || assetId}`)) {
    panelPosition.add(sourceFocus.get(`${beat.id}:${anchor.assetId || assetId}`));
  } else if (anchor.type === "asset" || anchor.type === "source-focus") {
    panelPosition.add(interactionAssetAnchorPosition(assetPositions, anchor.assetId || assetId));
  }
  const panelNormal = new THREE.Vector3(0, 0, 1).applyQuaternion(new THREE.Quaternion(...transform.quaternion));
  panelNormal.y = 0;
  if (panelNormal.lengthSq() < 0.001) panelNormal.set(0, 0, 1);
  panelNormal.normalize();
  panelPosition.addScaledVector(panelNormal, 1.05);
  panelPosition.y = 0;
  return panelPosition;
}

function embodiedProgressionRouteStops(beats, assetPositions, sourceFocus = null) {
  const stops = [];
  const traversal = interactionSpatialTraversal();
  const hasCanonicalSpatialRelations = spatialRelationEntities(lockedSpatialRelationsContract()).some((entity) => spatialEntityType(entity) === "reader");
  let previous = null;
  for (const [index, beat] of (beats || []).entries()) {
    const station = interactionTraversalStationForBeat(traversal, beat, index);
    const resolved = interactionResolvedReadingPosition(station, beat, assetPositions, previous, sourceFocus);
    if (resolved) {
      stops.push(resolved);
      previous = resolved;
      continue;
    }
    if (hasCanonicalSpatialRelations || station) {
      const retained = previous?.clone() || new THREE.Vector3(0, 0, 1.05);
      stops.push(retained);
      previous = retained;
      continue;
    }
    const linkedAssetId = beat?.linkedAssetIds?.find((assetId) => assetPositions.has(assetId));
    if (linkedAssetId) {
      const fallback = assetPositions.get(linkedAssetId).clone().add(new THREE.Vector3(0, 0, -0.62));
      stops.push(fallback);
      previous = fallback;
      continue;
    }
    const laneSpacing = 0.42;
    const laneX = ((index % 5) - 2) * laneSpacing;
    const laneZ = 1.38 + Math.floor(index / 5) * 0.42;
    const fallback = new THREE.Vector3(laneX, 0, laneZ);
    stops.push(fallback);
    previous = fallback;
  }
  return stops;
}

function embodiedProgressionRouteForBeat(beats, assetPositions, index, sourceFocus = null) {
  const stops = embodiedProgressionRouteStops(beats, assetPositions, sourceFocus);
  const target = stops[index]?.clone() || new THREE.Vector3(0, 0, -0.62);
  const start = index > 0 && stops[index - 1]
    ? stops[index - 1].clone()
    : target.clone().add(new THREE.Vector3(-0.34, 0, 0.82));
  const traversal = interactionSpatialTraversal();
  const beat = beats?.[index];
  const station = interactionTraversalStationForBeat(traversal, beat, index);
  const transition = (traversal?.transitions || []).find((item) => (
    item?.toStationId === station?.stationId || item?.toBeatId === beat?.id
  ));
  const requiresLocomotion = Boolean(station?.locomotionRequiredFromPrevious ?? transition?.requiresLocomotion);
  return { start, target, stops, requiresLocomotion };
}

function addEmbodiedProgressionReaderRig(viewer, route) {
  if (!viewer || viewer.kind !== "embodied-control") return null;
  const group = new THREE.Group();
  const start = route?.start?.clone?.() || new THREE.Vector3(-0.34, 0, 0.82);
  const target = route?.target?.clone?.() || new THREE.Vector3(0, 0, -0.62);
  const torso = new THREE.Mesh(
    new THREE.CapsuleGeometry(0.13, 0.46, 8, 18),
    new THREE.MeshStandardMaterial({ color: 0x007f73, roughness: 0.72, emissive: 0x002d28, emissiveIntensity: 0.04 }),
  );
  torso.position.copy(start).add(new THREE.Vector3(0, 0.64, 0));
  group.add(torso);
  const head = new THREE.Mesh(
    new THREE.SphereGeometry(0.14, 24, 18),
    new THREE.MeshStandardMaterial({ color: 0xffd6aa, roughness: 0.58 }),
  );
  head.position.copy(start).add(new THREE.Vector3(0, 1.05, 0));
  group.add(head);
  const leftFoot = new THREE.Mesh(
    new THREE.RingGeometry(0.09, 0.12, 24),
    new THREE.MeshBasicMaterial({ color: 0x007f73, transparent: true, opacity: 0.55, side: THREE.DoubleSide }),
  );
  leftFoot.rotation.x = -Math.PI / 2;
  group.add(leftFoot);
  const rightFoot = leftFoot.clone();
  rightFoot.material = leftFoot.material.clone();
  group.add(rightFoot);
  const locomotionMode = interactionLocomotionMode(viewer.proposal);
  const requiresLocomotion = route?.requiresLocomotion !== false;
  const label = makeTextSprite(!requiresLocomotion ? "reading pose settled" : locomotionMode === "virtual-teleport" ? "teleport to reading station" : "walk to reading station", {
    fontSize: 42,
    background: "rgba(255,253,244,0.9)",
    color: "#007f73",
    padding: 12,
  });
  label.scale.set(0.76, 0.2, 1);
  group.add(label);
  const previousStance = new THREE.Mesh(
    new THREE.RingGeometry(0.18, 0.23, 32),
    new THREE.MeshBasicMaterial({ color: 0x8fbfb7, transparent: true, opacity: 0.35, side: THREE.DoubleSide }),
  );
  previousStance.rotation.x = -Math.PI / 2;
  previousStance.position.copy(start).add(new THREE.Vector3(0, 0.045, 0));
  group.add(previousStance);
  const previousLabel = makeTextSprite("previous story-part end", {
    fontSize: 34,
    background: "rgba(255,253,244,0.82)",
    color: "#5f716b",
    padding: 10,
  });
  previousLabel.position.copy(start).add(new THREE.Vector3(0, 0.24, 0));
  previousLabel.scale.set(0.5, 0.16, 1);
  group.add(previousLabel);
  const targetStance = new THREE.Mesh(
    new THREE.RingGeometry(0.24, 0.3, 40),
    new THREE.MeshBasicMaterial({ color: 0x007f73, transparent: true, opacity: 0.52, side: THREE.DoubleSide }),
  );
  targetStance.rotation.x = -Math.PI / 2;
  targetStance.position.copy(target).add(new THREE.Vector3(0, 0.05, 0));
  group.add(targetStance);
  const targetLabel = makeTextSprite("current story-part zone", {
    fontSize: 34,
    background: "rgba(255,253,244,0.9)",
    color: "#007f73",
    padding: 10,
  });
  targetLabel.position.copy(target).add(new THREE.Vector3(0, 0.3, 0));
  targetLabel.scale.set(0.5, 0.16, 1);
  group.add(targetLabel);
  if (requiresLocomotion) {
    const pathGeometry = new THREE.BufferGeometry().setFromPoints([
      start.clone().add(new THREE.Vector3(0, 0.05, 0)),
      start.clone().lerp(target, 0.5).add(new THREE.Vector3(0, 0.05, 0)),
      target.clone().add(new THREE.Vector3(0, 0.05, 0)),
    ]);
    group.add(new THREE.Line(
      pathGeometry,
      new THREE.LineBasicMaterial({ color: 0x007f73, transparent: true, opacity: 0.62 }),
    ));
  }
  viewer.root.add(group);
  viewer.embodiedProgressionRig = {
    group,
    torso,
    head,
    leftFoot,
    rightFoot,
    label,
    start,
    target,
    locomotionMode,
    requiresLocomotion,
    playing: false,
    progress: 0,
    startedAt: null,
    duration: !requiresLocomotion ? 0.001 : locomotionMode === "virtual-teleport" ? 0.7 : 1.7,
  };
  updateEmbodiedProgressionReader(viewer, Number(viewer.elapsed) || 0);
  return viewer.embodiedProgressionRig;
}

function startEmbodiedProgressionReader(viewer) {
  const rig = viewer?.embodiedProgressionRig;
  if (!rig || viewer.disposed || viewer.kind !== "embodied-control") return false;
  rig.startedAt = Number(viewer.elapsed) || 0;
  rig.progress = rig.requiresLocomotion ? 0 : 1;
  rig.playing = rig.requiresLocomotion;
  updateEmbodiedProgressionReader(viewer, rig.startedAt);
  return true;
}

function updateEmbodiedProgressionReader(viewer, elapsed) {
  const rig = viewer?.embodiedProgressionRig;
  if (!rig || viewer.disposed || viewer.kind !== "embodied-control") return;
  const rawProgress = rig.playing
    ? Math.min(1, Math.max(0, (elapsed - rig.startedAt) / rig.duration))
    : Math.min(1, Math.max(0, Number(rig.progress) || 0));
  const eased = rawProgress * rawProgress * (3 - 2 * rawProgress);
  const teleporting = rig.locomotionMode === "virtual-teleport";
  const settled = rig.requiresLocomotion === false;
  const base = settled
    ? rig.target.clone()
    : teleporting
    ? (rawProgress >= 0.5 ? rig.target.clone() : rig.start.clone())
    : rig.start.clone().lerp(rig.target, eased);
  const moving = rig.playing && rawProgress < 1;
  const bounce = moving && !teleporting ? Math.sin(eased * Math.PI) * 0.08 : 0;
  const opacity = teleporting && rig.playing ? Math.max(0.08, Math.abs(rawProgress - 0.5) * 2) : 1;
  for (const object of [rig.torso, rig.head]) {
    if (!object?.material) continue;
    object.material.transparent = teleporting;
    object.material.opacity = opacity;
  }
  rig.torso.position.copy(base).add(new THREE.Vector3(0, 0.64 + bounce, 0));
  rig.head.position.copy(base).add(new THREE.Vector3(0, 1.05 + bounce, 0));
  rig.torso.lookAt(rig.target.x, rig.torso.position.y, rig.target.z);
  rig.head.lookAt(rig.target.x, rig.head.position.y, rig.target.z);
  const stride = moving && !teleporting ? Math.sin(elapsed * 5) * 0.08 : 0;
  rig.leftFoot.position.copy(base).add(new THREE.Vector3(-0.09, 0.04, stride));
  rig.rightFoot.position.copy(base).add(new THREE.Vector3(0.09, 0.04, -stride));
  rig.label.position.copy(base).add(new THREE.Vector3(0, 1.32 + bounce, 0));
  rig.progress = rawProgress;
  if (rawProgress >= 1) rig.playing = false;
}

function addInteractionReaderHandsRig(viewer, activeObject) {
  if (!viewer || viewer.kind !== "direct" || !activeObject) return null;
  if (viewer.interactionHandsRig?.group) {
    viewer.interactionHandsRig.group.removeFromParent();
    disposeObject(viewer.interactionHandsRig.group);
  }
  const group = new THREE.Group();
  const torso = new THREE.Mesh(
    new THREE.CapsuleGeometry(0.13, 0.44, 8, 18),
    new THREE.MeshStandardMaterial({ color: 0x007f73, roughness: 0.72, emissive: 0x002d28, emissiveIntensity: 0.04 }),
  );
  group.add(torso);
  const head = new THREE.Mesh(
    new THREE.SphereGeometry(0.14, 24, 18),
    new THREE.MeshStandardMaterial({ color: 0xffd6aa, roughness: 0.58 }),
  );
  group.add(head);
  const readerLabel = makeTextSprite("reader dragging", {
    fontSize: 42,
    background: "rgba(255,253,244,0.9)",
    color: "#007f73",
    padding: 12,
  });
  readerLabel.scale.set(0.62, 0.2, 1);
  group.add(readerLabel);

  const leftHand = makeInteractionHandMesh("left");
  const rightHand = makeInteractionHandMesh("right");
  const leftArm = makeInteractionArmLine();
  const rightArm = makeInteractionArmLine();
  group.add(leftArm, rightArm, leftHand, rightHand);
  viewer.root.add(group);
  viewer.interactionHandsRig = {
    group,
    activeObject,
    leftHand,
    rightHand,
    leftArm,
    rightArm,
    torso,
    head,
    readerLabel,
    leftShoulder: new THREE.Vector3(),
    rightShoulder: new THREE.Vector3(),
  };
  updateInteractionReaderHands(viewer);
  return viewer.interactionHandsRig;
}

function updateInteractionReaderHands(viewer) {
  const rig = viewer?.interactionHandsRig;
  if (!rig || !rig.activeObject || viewer.disposed) return;
  const objectPosition = new THREE.Vector3();
  rig.activeObject.getWorldPosition(objectPosition);
  viewer.root.worldToLocal(objectPosition);
  const base = interactionReaderBaseForObject(viewer, objectPosition);
  rig.torso.position.copy(base.torso);
  rig.head.position.copy(base.head);
  rig.readerLabel.position.copy(base.label);
  rig.torso.lookAt(objectPosition.x, base.torso.y, objectPosition.z);
  rig.head.lookAt(objectPosition.x, base.head.y, objectPosition.z);
  rig.leftShoulder.copy(base.leftShoulder);
  rig.rightShoulder.copy(base.rightShoulder);
  const leftHandPosition = objectPosition.clone().add(base.leftHandOffset);
  const rightHandPosition = objectPosition.clone().add(base.rightHandOffset);
  rig.leftHand.position.copy(leftHandPosition);
  rig.rightHand.position.copy(rightHandPosition);
  updateInteractionArmLine(rig.leftArm, rig.leftShoulder, leftHandPosition);
  updateInteractionArmLine(rig.rightArm, rig.rightShoulder, rightHandPosition);
}

function interactionReaderBaseForObject(viewer, objectPosition) {
  const fromCenter = new THREE.Vector3(objectPosition.x, 0, objectPosition.z);
  if (fromCenter.lengthSq() < 0.01) fromCenter.set(0, 0, 1);
  fromCenter.normalize();
  const side = new THREE.Vector3(-fromCenter.z, 0, fromCenter.x).multiplyScalar(0.08);
  const readerGround = objectPosition.clone()
    .add(fromCenter.clone().multiplyScalar(0.55))
    .add(side);
  readerGround.y = 0;
  const torso = readerGround.clone().add(new THREE.Vector3(0, 0.62, 0));
  const head = readerGround.clone().add(new THREE.Vector3(0, 1.02, 0));
  const label = readerGround.clone().add(new THREE.Vector3(0, 1.28, 0));
  const leftShoulder = readerGround.clone().add(new THREE.Vector3(-0.13, 0.86, 0));
  const rightShoulder = readerGround.clone().add(new THREE.Vector3(0.13, 0.86, 0));
  return {
    torso,
    head,
    label,
    leftShoulder,
    rightShoulder,
    leftHandOffset: new THREE.Vector3(-0.16, 0.38, 0.02),
    rightHandOffset: new THREE.Vector3(0.16, 0.38, 0.02),
  };
}

function makeInteractionHandMesh(side) {
  const group = new THREE.Group();
  const palm = new THREE.Mesh(
    new THREE.SphereGeometry(0.075, 20, 14),
    new THREE.MeshStandardMaterial({ color: 0xffd6aa, roughness: 0.5 }),
  );
  palm.scale.set(1.2, 0.82, 0.78);
  group.add(palm);
  const thumb = new THREE.Mesh(
    new THREE.CapsuleGeometry(0.022, 0.08, 5, 10),
    new THREE.MeshStandardMaterial({ color: 0xffc895, roughness: 0.52 }),
  );
  thumb.rotation.z = side === "left" ? -0.75 : 0.75;
  thumb.position.set(side === "left" ? 0.075 : -0.075, -0.018, 0);
  group.add(thumb);
  return group;
}

function addInteractionSpatialReaderHands(readerRig, beat) {
  const group = new THREE.Group();
  group.name = "StoryVR reader hands · Interaction Control";
  group.userData.spatialEditorOnly = true;

  const leftShoulder = new THREE.Vector3(-0.12, -0.2, -0.02);
  const rightShoulder = new THREE.Vector3(0.12, -0.2, -0.02);
  const leftHandPosition = new THREE.Vector3(-0.28, -0.4, -0.31);
  const rightHandPosition = new THREE.Vector3(0.28, -0.4, -0.31);
  const leftArm = makeInteractionArmLine();
  const rightArm = makeInteractionArmLine();
  updateInteractionArmLine(leftArm, leftShoulder, leftHandPosition);
  updateInteractionArmLine(rightArm, rightShoulder, rightHandPosition);

  const leftHand = makeInteractionHandMesh("left");
  leftHand.name = "StoryVR reader left hand · Interaction Control";
  leftHand.position.copy(leftHandPosition);
  leftHand.rotation.set(-0.28, 0.08, -0.18);
  const rightHand = makeInteractionHandMesh("right");
  rightHand.name = "StoryVR reader right hand · Interaction Control";
  rightHand.position.copy(rightHandPosition);
  rightHand.rotation.set(-0.28, -0.08, 0.18);
  group.add(leftArm, rightArm, leftHand, rightHand);

  const panelAnchor = new THREE.Group();
  panelAnchor.name = "StoryVR reader left-hand panel anchor · Interaction Control";
  panelAnchor.position.set(-0.14, 0.14, -0.16);
  panelAnchor.rotation.set(-0.08, 0.16, 0.04);
  panelAnchor.userData.attachmentPolicy = "reader-hand";
  panelAnchor.userData.handedness = "left";
  leftHand.add(panelAnchor);

  const textPanel = new THREE.Group();
  textPanel.name = "StoryVR hand text panel · Interaction Control";
  textPanel.userData.attachmentPolicy = "reader-hand";
  textPanel.userData.handedness = "left";
  const panel = new THREE.Mesh(
    new THREE.PlaneGeometry(FINAL_REVIEW_XR_TEXT_PANEL_WIDTH, FINAL_REVIEW_XR_TEXT_PANEL_HEIGHT),
    new THREE.MeshBasicMaterial({
      map: makeFinalReviewTextTexture(beat, null),
      transparent: true,
      side: THREE.DoubleSide,
      depthTest: false,
      depthWrite: false,
      toneMapped: false,
    }),
  );
  panel.renderOrder = READER_UI_RENDER_ORDER;
  panel.name = "StoryVR readable text surface · Interaction Control";
  textPanel.add(panel);
  panelAnchor.add(textPanel);
  readerRig.add(group);

  return {
    group,
    leftArm,
    rightArm,
    leftHand,
    rightHand,
    panelAnchor,
    textPanel,
    handedness: "left",
  };
}

function makeInteractionArmLine() {
  const geometry = new THREE.BufferGeometry().setFromPoints([new THREE.Vector3(), new THREE.Vector3()]);
  return new THREE.Line(
    geometry,
    new THREE.LineBasicMaterial({ color: 0x007f73, transparent: true, opacity: 0.78 }),
  );
}

function updateInteractionArmLine(line, from, to) {
  line.geometry.setFromPoints([from, to]);
  line.geometry.attributes.position.needsUpdate = true;
}

function initializeSpatialRelationsViewer(active) {
  if (!isSpatialRelationsComponentId(active?.id)) return;
  const container = document.querySelector("[data-spatial-viewer]");
  if (!container) return;
  const component = spatialRelationsComponent();
  const proposal = component
    ? selectedTopologyProposal(component, spatialRelationsProposalBundle(), spatialRelationsDecision())
    : null;
  const draft = ensureSpatialRelationsDraft(component, proposal);
  const sceneContext = activeSpatialSceneContext();
  if (!sceneContext) return;
  const beats = spatialPreviewBeats();
  const beatIndex = Math.max(0, beats.findIndex((candidate) => candidate.id === sceneContext.beatId));
  const beat = spatialSceneBeat(sceneContext);
  const sceneContract = spatialSceneRecordForContext(draft, sceneContext);
  const upstreamBeatState = resolveSpatialUpstreamBeatState(beats, beatIndex, state.spatialPendingTransition);
  state.spatialPendingTransition = null;
  ensureSpatialSelection(draft, beat, sceneContext);
  const sceneEntities = spatialEditorSceneEntities(draft, sceneContext);
  const readerEntity = sceneEntities.find((entity) => spatialEntityType(entity) === "reader") || null;
  const assetLinks = sceneEntities
    .filter((entity) => spatialEntityType(entity) === "glb" || spatialEntityType(entity) === "image-plane")
    .map((entity) => ({
      assetId: entity.assetId,
      entityId: entity.id,
      kind: spatialEntityType(entity),
      role: entity.role || entity.sourceRole || "Scene asset",
      entity,
    }));
  const layoutKind = sceneContract?.topology?.kind || sceneContract?.topologyKind || "single";
  const layers = cumulativePreviewLayersForComponent(spatialRelationsComponentId(), {
    textKind: "spatial-relations",
    topologyKind: layoutKind,
  });
  const width = Math.max(container.clientWidth, 360);
  const height = Math.max(container.clientHeight, 520);
  const scene = new THREE.Scene();
  scene.background = new THREE.Color(0xf8f7ec);
  const camera = new THREE.PerspectiveCamera(42, width / height, 0.02, 1000);
  camera.position.set(3.4, 2.3, 4.8);
  scene.add(camera);
  const renderer = new THREE.WebGLRenderer({ antialias: true, alpha: true });
  renderer.setPixelRatio(Math.min(window.devicePixelRatio || 1, 2));
  renderer.setSize(width, height);
  renderer.outputColorSpace = THREE.SRGBColorSpace;
  renderer.domElement.tabIndex = 0;
  renderer.domElement.className = "topology-viewer-canvas text-viewer-canvas spatial-viewer-canvas";
  const status = document.createElement("div");
  status.className = "topology-viewer-status overlay";
  status.textContent = assetLinks.length ? `Loading ${assetLinks.length} linked scene asset${assetLinks.length === 1 ? "" : "s"}...` : "This scene has no linked visual assets to arrange.";
  container.replaceChildren(renderer.domElement, status);
  const selectionMarquee = document.createElement("div");
  selectionMarquee.className = "spatial-selection-marquee";
  selectionMarquee.hidden = true;
  selectionMarquee.setAttribute("aria-hidden", "true");
  container.append(selectionMarquee);
  const controls = new OrbitControls(camera, renderer.domElement);
  controls.enableDamping = true;
  controls.dampingFactor = 0.08;
  controls.screenSpacePanning = false;
  controls.maxPolarAngle = Math.PI / 2 - 0.02;
  controls.target.set(0, 0.85, 0);
  configureSpatialEditorMouseControls(controls);
  scene.add(new THREE.HemisphereLight(0xffffff, 0x6f7f78, 2.4));
  const keyLight = new THREE.DirectionalLight(0xffffff, 3.1);
  keyLight.position.set(4, 7, 5);
  scene.add(keyLight);
  const fillLight = new THREE.DirectionalLight(0xbcece4, 1.25);
  fillLight.position.set(-4, 3, -4);
  scene.add(fillLight);
  const root = new THREE.Group();
  scene.add(root);
  scene.add(makeSpatialEditorFloorGuide(layoutKind));
  const readerEditorLayer = createSpatialReaderRig(root, readerEntity);
  const assetPositions = new Map();
  assetLinks.forEach((assetLink, index) => {
    assetPositions.set(assetLink.assetId, spatialTopologyAssetPose({ topologyKind: layoutKind }, index, Math.max(assetLinks.length, 1)).position);
  });
  const viewer = {
    container,
    scene,
    camera,
    renderer,
    controls,
    root,
    readerRig: readerEditorLayer.rig,
    readerProxy: readerEditorLayer.proxy,
    readerEntity,
    proposal,
    beat,
    beatIndex,
    componentId: SPATIAL_RELATIONS_COMPONENT_ID,
    topologyKind: layoutKind,
    layoutKind,
    layers,
    assetLinks,
    assetPositions,
    spatialObjects: new Map(),
    authoringSpatialObjects: new Map(),
    spatialPickTargets: [],
    spatialPlaybackEntries: [],
    spatialPlaybackReady: false,
    sourceElapsed: 0,
    speed: 1,
    playOnce: true,
    playing: false,
    upstreamBeatState,
    sourceMotionTransition: upstreamBeatState.sourceMotionTransition,
    sourcePartFromBeatId: upstreamBeatState.fromBeatId,
    sourcePartToBeatId: upstreamBeatState.toBeatId,
    sourcePartPlaybackMode: upstreamBeatState.sourcePartPlaybackMode,
    sourceCameraCuePending: false,
    sourceCamera: null,
    spatialAssetBounds: new Map(),
    spatialSourceFocus: new Map(),
    transformControls: null,
    transformHelper: null,
    transformScaleStart: null,
    transformScaleDriverIndex: null,
    transformSelectionGroup: null,
    transformSelectionStart: null,
    transformMutationActive: false,
    spatialTransformDrag: null,
    selectionHelpers: [],
    selectionPointerGesture: null,
    selectionMarquee,
    spatialEditorCamera: AUTHORING_SPATIAL_CAMERA_KIND,
    locked: false,
    animationId: null,
    resizeHandler: null,
    keyDownHandler: null,
    pointerDownHandler: null,
    pointerMoveHandler: null,
    pointerUpHandler: null,
    pointerCancelHandler: null,
    disposed: false,
    lastFrameAt: performance.now(),
    elapsed: 0,
  };
  configureAuthoringSpatialCameraViewer(viewer, sceneContext);
  textViewer = viewer;
  if (readerEntity) {
    viewer.spatialObjects.set(readerEntity.id, readerEditorLayer.rig);
    viewer.spatialPickTargets.push(readerEditorLayer.proxy);
  }
  if (
    selectedSpatialRelationEntities(draft).some((entity) => spatialEntityType(entity) === "reader")
    && state.spatialTransformMode === "scale"
  ) {
    state.spatialTransformMode = "translate";
  }

  const transformControls = new TransformControls(camera, renderer.domElement);
  transformControls.enabled = true;
  transformControls.setMode(state.spatialTransformMode);
  transformControls.setSpace("world");
  transformControls.setSize(0.72);
  const transformHelper = transformControls.getHelper();
  scene.add(transformHelper);
  viewer.transformControls = transformControls;
  viewer.transformHelper = transformHelper;
  transformControls.addEventListener("dragging-changed", (event) => {
    controls.enabled = !event.value;
  });
  transformControls.addEventListener("mouseDown", () => {
    if (viewer.locked || !spatialSelectionCanTransform(transformControls.mode, draft)) return;
    viewer.navigationTransformFinalized = false;
    pushSpatialUndoSnapshot();
    const selectedEntities = selectedSpatialRelationEntities(draft);
    const primaryEntity = selectedSpatialRelationEntity(draft) || selectedEntities[0] || null;
    viewer.spatialTransformDrag = primaryEntity
      ? {
          pointerId: null,
          startedAt: null,
          moved: false,
          operation: String(transformControls.mode || state.spatialTransformMode || "translate"),
          axis: String(transformControls.axis || ""),
          semanticTarget: {
            kind: "spatial-scene-object",
            label: spatialRelationEntityLabel(primaryEntity) || primaryEntity.id,
            entityId: primaryEntity.id,
            assetId: primaryEntity.assetId,
            action: "drag-spatial-object",
          },
          objects: selectedEntities.map(spatialTransformDragObjectSnapshot).filter(Boolean),
          path: [],
        }
      : null;
    viewer.transformScaleStart = transformControls.object?.scale?.clone?.() || null;
    viewer.transformScaleDriverIndex = null;
    viewer.transformSelectionStart = selectedEntities.length > 1
      ? captureSpatialSelectionTransformStart(viewer)
      : null;
  });
  transformControls.addEventListener("objectChange", () => {
    if (
      viewer.locked
      || !spatialSelectionCanTransform(transformControls.mode, draft)
      || viewer.transformMutationActive
      || !transformControls.object
    ) return;
    viewer.transformMutationActive = true;
    try {
      if (state.spatialScaleRatioLocked && transformControls.mode === "scale" && viewer.transformScaleStart) {
        const start = viewer.transformScaleStart.toArray();
        const current = transformControls.object.scale.toArray();
        const driverIndex = spatialLockedScaleDriverIndex(
          start,
          current,
          transformControls.axis,
          viewer.transformScaleDriverIndex,
        );
        viewer.transformScaleDriverIndex = driverIndex;
        transformControls.object.scale.fromArray(
          spatialLockedScaleForAxis(start, driverIndex, current[driverIndex]),
        );
      }
      if (viewer.transformSelectionStart) applySpatialSelectionTransformFromGizmo(viewer);
      else persistSpatialObjectTransform(viewer, transformControls.object);
      syncSpatialInspectorFromSelection();
    } finally {
      viewer.transformMutationActive = false;
    }
  });
  transformControls.addEventListener("mouseUp", () => {
    if (viewer.navigationTransformFinalized) {
      viewer.navigationTransformFinalized = false;
      return;
    }
    if (viewer.locked || !spatialSelectionCanTransform(transformControls.mode, draft)) return;
    viewer.transformScaleStart = null;
    viewer.transformScaleDriverIndex = null;
    viewer.transformSelectionStart = null;
    commitSpatialDraftMutation();
    finalizePersistentAuthorHistory(flushSpatialRelationsAutosave);
    syncSpatialSelectionInViewer();
  });

  const canRestoreCameraState = restoreAuthoringSpatialCameraState(viewer);

  let pending = assetLinks.length;
  const finishAsset = () => {
    pending -= 1;
    if (pending <= 0 && !viewer.disposed) {
      viewer.spatialPlaybackReady = true;
      viewer.sourceElapsed = 0;
      viewer.playing = upstreamBeatState.playTransition
        && viewer.spatialPlaybackEntries.some((entry) => entry.spatialTransitionPlaying);
      status.remove();
      syncSpatialSelectionInViewer();
      if (!canRestoreCameraState) fitAuthoringSpatialCameraOnLoad(viewer);
    }
  };
  if (!assetLinks.length) requestAnimationFrame(() => {
    if (viewer.disposed) return;
    viewer.spatialPlaybackReady = true;
    status.remove();
    syncSpatialSelectionInViewer();
    if (!canRestoreCameraState) fitAuthoringSpatialCameraOnLoad(viewer);
  });
  assetLinks.forEach((assetLink, index) => {
    if (assetLink.kind === "image-plane") loadSpatialRelationsImage(viewer, assetLink, index, assetLinks.length, finishAsset);
    else loadSpatialRelationsGlb(viewer, assetLink, index, assetLinks.length, finishAsset);
  });

  const raycaster = new THREE.Raycaster();
  raycaster.params.Line.threshold = 0.035;
  raycaster.params.Points.threshold = 0.035;
  const pointer = new THREE.Vector2();
  const clickMovementThresholdSquared = 36;
  const spatialEntityIdAtPointer = (event) => {
    const rect = renderer.domElement.getBoundingClientRect();
    if (
      !rect.width
      || !rect.height
      || event.clientX < rect.left
      || event.clientX > rect.right
      || event.clientY < rect.top
      || event.clientY > rect.bottom
    ) return null;
    pointer.x = ((event.clientX - rect.left) / rect.width) * 2 - 1;
    pointer.y = -((event.clientY - rect.top) / rect.height) * 2 + 1;
    raycaster.setFromCamera(pointer, camera);
    for (const hit of raycaster.intersectObjects(viewer.spatialPickTargets, true)) {
      if (!spatialObjectIsEffectivelyVisible(hit.object, viewer.scene)) continue;
      let target = hit.object;
      while (target && !target.userData?.spatialEntityId) target = target.parent;
      const entityId = target?.userData?.spatialEntityId || null;
      if (!entityId) continue;
      const entityRoot = viewer.spatialObjects.get(entityId);
      if (entityRoot?.userData?.spatialPlaybackActive === false) continue;
      return entityId;
    }

    // Animated and skinned GLBs can have stale per-mesh raycast bounds while
    // their rendered root is still visible. Fall back to precise bounds made
    // only from currently visible renderables.
    let closestGlb = null;
    for (const [entityId, object] of viewer.spatialObjects) {
      const entity = spatialRelationEntityById(state.spatialRelationsDraft, entityId);
      if (
        spatialEntityType(entity) !== "glb"
        || !object?.visible
        || object.userData?.spatialPlaybackActive === false
      ) continue;
      for (const bounds of preciseVisibleSpatialBounds(object, viewer.scene)) {
        const hitPoint = raycaster.ray.intersectBox(bounds, new THREE.Vector3());
        if (!hitPoint) continue;
        const distance = raycaster.ray.origin.distanceToSquared(hitPoint);
        if (!closestGlb || distance < closestGlb.distance) closestGlb = { entityId, distance };
      }
    }
    return closestGlb?.entityId || null;
  };
  const hideSelectionMarquee = () => {
    selectionMarquee.hidden = true;
  };
  viewer.pointerDownHandler = (event) => {
    if (event.button !== 0 || event.isPrimary === false) return;
    const startedOnTransformGizmo = Boolean(transformControls.dragging || transformControls.axis);
    if (startedOnTransformGizmo && viewer.spatialTransformDrag) {
      viewer.spatialTransformDrag.pointerId = event.pointerId;
      viewer.spatialTransformDrag.startedAt = spatialTransformDragEventTime(event);
      viewer.spatialTransformDrag.eventTarget = event.target || renderer.domElement;
      appendSpatialTransformDragPoint(viewer.spatialTransformDrag, event);
    }
    const entityId = startedOnTransformGizmo ? null : spatialEntityIdAtPointer(event);
    viewer.selectionPointerGesture = {
      pointerId: event.pointerId,
      clientX: event.clientX,
      clientY: event.clientY,
      currentX: event.clientX,
      currentY: event.clientY,
      moved: false,
      startedOnTransformGizmo,
      entityId,
      additive: event.shiftKey,
      toggle: event.metaKey || event.ctrlKey,
    };
    renderer.domElement.focus();
    if (!startedOnTransformGizmo) renderer.domElement.setPointerCapture?.(event.pointerId);
  };
  viewer.pointerMoveHandler = (event) => {
    const gesture = viewer.selectionPointerGesture;
    if (!gesture || gesture.pointerId !== event.pointerId) return;
    appendSpatialTransformDragPoint(viewer.spatialTransformDrag, event);
    const deltaX = event.clientX - gesture.clientX;
    const deltaY = event.clientY - gesture.clientY;
    gesture.currentX = event.clientX;
    gesture.currentY = event.clientY;
    if (deltaX * deltaX + deltaY * deltaY <= clickMovementThresholdSquared) return;
    gesture.moved = true;
    if (gesture.startedOnTransformGizmo) {
      if (viewer.spatialTransformDrag?.pointerId === event.pointerId) {
        viewer.spatialTransformDrag.moved = true;
      }
      return;
    }
    event.preventDefault();
    updateSpatialSelectionMarquee(
      selectionMarquee,
      normalizeSpatialSelectionRectangle(
        gesture.clientX,
        gesture.clientY,
        gesture.currentX,
        gesture.currentY,
      ),
      container.getBoundingClientRect(),
    );
  };
  viewer.pointerUpHandler = (event) => {
    const gesture = viewer.selectionPointerGesture;
    if (!gesture || gesture.pointerId !== event.pointerId) return;
    viewer.selectionPointerGesture = null;
    hideSelectionMarquee();
    if (renderer.domElement.hasPointerCapture?.(event.pointerId)) {
      renderer.domElement.releasePointerCapture?.(event.pointerId);
    }
    const deltaX = event.clientX - gesture.clientX;
    const deltaY = event.clientY - gesture.clientY;
    const moved = gesture.moved || deltaX * deltaX + deltaY * deltaY > clickMovementThresholdSquared;
    if (gesture.startedOnTransformGizmo) {
      if (viewer.spatialTransformDrag?.pointerId === event.pointerId) {
        viewer.spatialTransformDrag.moved ||= moved;
      }
      if (event.button === 0 && !viewer.disposed && !transformControls.dragging) {
        finalizeSpatialTransformDrag(viewer, event);
      } else viewer.spatialTransformDrag = null;
      return;
    }
    if (
      event.button !== 0
      || viewer.disposed
      || transformControls.dragging
    ) return;
    if (moved) {
      event.preventDefault();
      const selectionRectangle = normalizeSpatialSelectionRectangle(
        gesture.clientX,
        gesture.clientY,
        event.clientX,
        event.clientY,
      );
      const hitEntityIds = spatialEntityIdsInSelectionRectangle(viewer, selectionRectangle);
      if (!hitEntityIds.length) return;
      const orderedEntityIds = spatialEditorSceneEntities(
        state.spatialRelationsDraft,
        activeSpatialSceneContext(),
      ).map((entity) => entity.id);
      const entityIds = spatialSelectionForRectangle(
        orderedEntityIds,
        selectedSpatialRelationEntityIds(),
        hitEntityIds,
        { additive: gesture.additive, toggle: gesture.toggle },
      );
      const primaryEntityId = [...hitEntityIds].reverse().find((entityId) => entityIds.includes(entityId))
        || entityIds[entityIds.length - 1]
        || null;
      setSpatialRelationSelection(entityIds, {
        primaryEntityId,
        anchorEntityId: primaryEntityId,
      });
      return;
    }
    const entityId = gesture.entityId || spatialEntityIdAtPointer(event);
    if (entityId) {
      const entity = spatialRelationEntityById(state.spatialRelationsDraft, entityId);
      const asset = findAssetById(entity?.assetId);
      interactionLogger.recordSemanticClick(event, {
        kind: "spatial-scene-object",
        label: entity?.partSelector || asset?.filename || asset?.label || entity?.assetId || entityId,
        entityId,
        assetId: entity?.assetId,
        action: "select-spatial-object",
      });
      selectSpatialRelationEntityInViewer(entityId, {
        additive: gesture.additive,
        toggle: gesture.toggle,
      });
    } else if (!gesture.additive && !gesture.toggle) {
      clearSpatialRelationSelection();
    }
  };
  viewer.pointerCancelHandler = (event) => {
    if (viewer.spatialTransformDrag?.pointerId === event.pointerId) {
      const gesture = viewer.selectionPointerGesture;
      if (gesture?.pointerId === event.pointerId) {
        const deltaX = event.clientX - gesture.clientX;
        const deltaY = event.clientY - gesture.clientY;
        viewer.spatialTransformDrag.moved ||= gesture.moved
          || deltaX * deltaX + deltaY * deltaY > clickMovementThresholdSquared;
      }
      hideSelectionMarquee();
      finalizeInterruptedSpatialTransformDrag(viewer, event);
      return;
    }
    if (viewer.selectionPointerGesture?.pointerId !== event.pointerId) return;
    viewer.selectionPointerGesture = null;
    hideSelectionMarquee();
    if (renderer.domElement.hasPointerCapture?.(event.pointerId)) {
      renderer.domElement.releasePointerCapture?.(event.pointerId);
    }
  };
  renderer.domElement.addEventListener("pointerdown", viewer.pointerDownHandler);
  window.addEventListener("pointermove", viewer.pointerMoveHandler);
  window.addEventListener("pointerup", viewer.pointerUpHandler);
  window.addEventListener("pointercancel", viewer.pointerCancelHandler);
  viewer.keyDownHandler = (event) => {
    if (viewer.locked) return;
    const editable = /^(input|textarea|select)$/i.test(event.target?.tagName || "") || event.target?.isContentEditable;
    const modifier = event.metaKey || event.ctrlKey;
    const key = event.key.toLowerCase();
    if (!editable && !event.altKey && modifier && !event.repeat && (key === "c" || key === "v")) {
      const handled = key === "c" ? copySelectedSpatialGlb() : pasteSpatialGlbInstance();
      if (handled) event.preventDefault();
      return;
    }
    if (modifier || event.altKey || editable) return;
    const mode = { w: "translate", e: "rotate", r: "scale" }[key];
    if (!mode) return;
    event.preventDefault();
    setSpatialTransformMode(mode);
  };
  window.addEventListener("keydown", viewer.keyDownHandler);
  viewer.resizeHandler = () => {
    if (viewer.disposed) return;
    const nextWidth = Math.max(container.clientWidth, 360);
    const nextHeight = Math.max(container.clientHeight, 520);
    camera.aspect = nextWidth / nextHeight;
    camera.updateProjectionMatrix();
    renderer.setSize(nextWidth, nextHeight);
  };
  window.addEventListener("resize", viewer.resizeHandler);
  const animate = (now) => {
    if (viewer.disposed) return;
    const delta = Math.min((now - viewer.lastFrameAt) / 1000, 0.05);
    viewer.lastFrameAt = now;
    viewer.elapsed += delta;
    updateSpatialUpstreamPlayback(viewer, delta);
    for (const helper of viewer.selectionHelpers || []) helper.update?.();
    controls.update();
    renderer.render(scene, camera);
    viewer.animationId = requestAnimationFrame(animate);
  };
  viewer.animationId = requestAnimationFrame(animate);
}

function initializeAttentionGuidanceViewer(active) {
  if (active?.id !== ATTENTION_GUIDANCE_COMPONENT_ID) return;
  const container = document.querySelector("[data-attention-viewer]");
  if (!container) return;
  const draft = ensureAttentionGuidanceDraft();
  const sceneContext = activeAttentionSceneContext();
  if (!sceneContext) return;
  const beat = spatialSceneBeat(sceneContext);
  const beats = spatialPreviewBeats();
  const beatIndex = Math.max(0, beats.findIndex((candidate) => candidate.id === sceneContext.beatId));
  const attentionScene = attentionSceneRecordForContext(draft, sceneContext);
  const spatialContract = lockedSpatialRelationsContract();
  const spatialScene = spatialSceneRecordForContext(spatialContract, sceneContext);
  const spatialEntities = spatialSceneEntities(spatialContract, sceneContext);
  const assetEntities = spatialEntities.filter((entity) => ["glb", "image-plane"].includes(spatialEntityType(entity)));
  const readerEntity = spatialEntities.find((entity) => spatialEntityType(entity) === "reader") || null;
  const layoutKind = spatialScene?.topology?.kind || spatialScene?.topologyKind || "single";
  const layers = cumulativePreviewLayersForComponent(ATTENTION_GUIDANCE_COMPONENT_ID, {
    textKind: "spatial-relations",
    topologyKind: layoutKind,
  });
  const upstreamBeatState = resolveSpatialUpstreamBeatState(beats, beatIndex, null);
  const width = Math.max(container.clientWidth, 360);
  const height = Math.max(container.clientHeight, 520);
  const scene = new THREE.Scene();
  scene.background = new THREE.Color(0xf8f7ec);
  const camera = new THREE.PerspectiveCamera(42, width / height, 0.02, 1000);
  camera.position.set(3.4, 2.3, 4.8);
  scene.add(camera);
  const renderer = new THREE.WebGLRenderer({ antialias: true, alpha: true });
  renderer.setPixelRatio(Math.min(window.devicePixelRatio || 1, 2));
  renderer.setSize(width, height);
  renderer.outputColorSpace = THREE.SRGBColorSpace;
  renderer.domElement.tabIndex = 0;
  renderer.domElement.className = "topology-viewer-canvas text-viewer-canvas spatial-viewer-canvas attention-viewer-canvas";
  const status = document.createElement("div");
  status.className = "topology-viewer-status overlay";
  status.textContent = assetEntities.length
    ? `Loading ${assetEntities.length} saved scene asset${assetEntities.length === 1 ? "" : "s"} and checking visible objects...`
    : "No linked model or image is available; a focus marker can still be placed manually.";
  container.replaceChildren(renderer.domElement, status);
  const selectionMarquee = document.createElement("div");
  selectionMarquee.className = "spatial-selection-marquee";
  selectionMarquee.hidden = true;
  selectionMarquee.setAttribute("aria-hidden", "true");
  container.append(selectionMarquee);
  const controls = new OrbitControls(camera, renderer.domElement);
  controls.enableDamping = true;
  controls.dampingFactor = 0.08;
  controls.screenSpacePanning = false;
  controls.maxPolarAngle = Math.PI / 2 - 0.02;
  controls.target.set(0, 0.85, 0);
  configureSpatialEditorMouseControls(controls);
  scene.add(new THREE.HemisphereLight(0xffffff, 0x6f7f78, 2.4));
  const keyLight = new THREE.DirectionalLight(0xffffff, 3.1);
  keyLight.position.set(4, 7, 5);
  scene.add(keyLight);
  const fillLight = new THREE.DirectionalLight(0xffc3a8, 1.1);
  fillLight.position.set(-4, 3, -4);
  scene.add(fillLight);
  const root = new THREE.Group();
  root.name = "Attention Guidance saved spatial scene";
  scene.add(root);
  scene.add(makeSpatialEditorFloorGuide(layoutKind));
  const readerEditorLayer = createSpatialReaderRig(root, readerEntity);
  const locked = false;
  const viewer = {
    container,
    scene,
    camera,
    renderer,
    controls,
    root,
    readerRig: readerEditorLayer.rig,
    readerProxy: readerEditorLayer.proxy,
    readerEntity,
    beat,
    beatIndex,
    sceneContext,
    attentionScene,
    spatialScene,
    spatialContract,
    componentId: ATTENTION_GUIDANCE_COMPONENT_ID,
    topologyKind: layoutKind,
    layoutKind,
    layers,
    locked,
    storyObjects: new Map(),
    authoringSpatialObjects: new Map(),
    attentionAssetEntries: new Map(),
    attentionMarkerObjects: new Map(),
    attentionPickTargets: [],
    attentionObjectSelectionHelpers: [],
    spatialPlaybackEntries: [],
    spatialPlaybackReady: false,
    spatialObjects: new Map(),
    spatialAssetBounds: new Map(),
    spatialSourceFocus: new Map(),
    assetPositions: new Map(),
    sourceElapsed: 0,
    speed: 1,
    playOnce: true,
    playing: false,
    upstreamBeatState,
    sourceMotionTransition: null,
    sourcePartFromBeatId: upstreamBeatState.fromBeatId,
    sourcePartToBeatId: upstreamBeatState.toBeatId,
    sourcePartPlaybackMode: upstreamBeatState.sourcePartPlaybackMode,
    sourceCameraCuePending: false,
    sourceCamera: null,
    panel: null,
    manualAttentionPlacementActive: false,
    spatialEditorCamera: AUTHORING_SPATIAL_CAMERA_KIND,
    animationId: null,
    resizeHandler: null,
    pointerDownHandler: null,
    pointerMoveHandler: null,
    pointerUpHandler: null,
    pointerCancelHandler: null,
    selectionPointerGesture: null,
    selectionMarquee,
    disposed: false,
    lastFrameAt: performance.now(),
    elapsed: 0,
  };
  configureAuthoringSpatialCameraViewer(viewer, sceneContext);
  textViewer = viewer;
  attachLockedEnvironmentToViewer(viewer);

  const canRestoreCameraState = restoreAuthoringSpatialCameraState(viewer);

  let pending = assetEntities.length;
  const finishAssets = () => {
    pending -= 1;
    if (pending > 0 || viewer.disposed) return;
    viewer.spatialPlaybackReady = true;
    updateSpatialUpstreamPlayback(viewer, 0);
    root.updateWorldMatrix(true, true);
    const evaluationChanged = evaluateAttentionGuidanceScene(viewer);
    status.remove();
    syncAttentionManualTargetControls(viewer);
    ensureAttentionMarkerSelection(attentionScene);
    selectAttentionMarkerInViewer(state.selectedAttentionMarkerId);
    if (!canRestoreCameraState) fitAuthoringSpatialCameraOnLoad(viewer);
    if (evaluationChanged && !viewer.locked) requestAnimationFrame(() => {
      if (textViewer === viewer && !viewer.disposed) render();
    });
  };
  if (!assetEntities.length) requestAnimationFrame(finishAssets);
  assetEntities.forEach((entity, index) => {
    if (spatialEntityType(entity) === "image-plane") loadAttentionGuidanceImage(viewer, entity, finishAssets);
    else loadAttentionGuidanceGlb(viewer, entity, index, assetEntities.length, finishAssets);
  });

  const raycaster = new THREE.Raycaster();
  raycaster.params.Line.threshold = 0.035;
  raycaster.params.Points.threshold = 0.035;
  const pointer = new THREE.Vector2();
  const clickMovementThresholdSquared = 36;
  const attentionSelectionAtPointer = (event) => {
    const rect = renderer.domElement.getBoundingClientRect();
    if (
      !rect.width
      || !rect.height
      || event.clientX < rect.left
      || event.clientX > rect.right
      || event.clientY < rect.top
      || event.clientY > rect.bottom
    ) return { markerId: null, candidateId: null };
    pointer.x = ((event.clientX - rect.left) / rect.width) * 2 - 1;
    pointer.y = -((event.clientY - rect.top) / rect.height) * 2 + 1;
    raycaster.setFromCamera(pointer, camera);
    const hit = raycaster.intersectObjects(viewer.attentionPickTargets, true)[0];
    let target = hit?.object || null;
    while (target && !target.userData?.attentionMarkerId) target = target.parent;
    if (target?.userData?.attentionMarkerId) return { markerId: target.userData.attentionMarkerId, candidateId: null };
    const candidate = attentionTargetObjectCandidateAtRay(viewer, raycaster);
    return { markerId: null, candidateId: candidate?.id || null };
  };
  const hideSelectionMarquee = () => {
    selectionMarquee.hidden = true;
  };
  viewer.pointerDownHandler = (event) => {
    if (event.button !== 0 || event.isPrimary === false) return;
    if (viewer.manualAttentionPlacementActive) {
      const rect = renderer.domElement.getBoundingClientRect();
      pointer.x = ((event.clientX - rect.left) / rect.width) * 2 - 1;
      pointer.y = -((event.clientY - rect.top) / rect.height) * 2 + 1;
      raycaster.setFromCamera(pointer, camera);
      event.preventDefault();
      const position = attentionManualPlacementPosition(viewer, raycaster);
      if (position) {
        interactionLogger.recordSemanticClick(event, {
          kind: "attention-manual-position",
          label: "Place focus marker manually",
          action: "place-attention-marker",
        });
        addManualAttentionTargetAtPosition(position, viewer);
      }
      return;
    }
    viewer.selectionPointerGesture = {
      pointerId: event.pointerId,
      clientX: event.clientX,
      clientY: event.clientY,
      currentX: event.clientX,
      currentY: event.clientY,
      moved: false,
      selection: attentionSelectionAtPointer(event),
      additive: event.shiftKey,
      toggle: event.metaKey || event.ctrlKey,
    };
    renderer.domElement.focus();
    renderer.domElement.setPointerCapture?.(event.pointerId);
  };
  viewer.pointerMoveHandler = (event) => {
    const gesture = viewer.selectionPointerGesture;
    if (!gesture || gesture.pointerId !== event.pointerId) return;
    const deltaX = event.clientX - gesture.clientX;
    const deltaY = event.clientY - gesture.clientY;
    gesture.currentX = event.clientX;
    gesture.currentY = event.clientY;
    if (deltaX * deltaX + deltaY * deltaY <= clickMovementThresholdSquared) return;
    gesture.moved = true;
    event.preventDefault();
    updateSpatialSelectionMarquee(
      selectionMarquee,
      normalizeSpatialSelectionRectangle(
        gesture.clientX,
        gesture.clientY,
        gesture.currentX,
        gesture.currentY,
      ),
      container.getBoundingClientRect(),
    );
  };
  viewer.pointerUpHandler = (event) => {
    const gesture = viewer.selectionPointerGesture;
    if (!gesture || gesture.pointerId !== event.pointerId) return;
    viewer.selectionPointerGesture = null;
    hideSelectionMarquee();
    if (renderer.domElement.hasPointerCapture?.(event.pointerId)) {
      renderer.domElement.releasePointerCapture?.(event.pointerId);
    }
    const deltaX = event.clientX - gesture.clientX;
    const deltaY = event.clientY - gesture.clientY;
    const moved = gesture.moved || deltaX * deltaX + deltaY * deltaY > clickMovementThresholdSquared;
    if (event.button !== 0 || viewer.disposed) return;
    if (moved) {
      event.preventDefault();
      const selectionRectangle = normalizeSpatialSelectionRectangle(
        gesture.clientX,
        gesture.clientY,
        event.clientX,
        event.clientY,
      );
      const hitCandidateIds = attentionTargetCandidateIdsInSelectionRectangle(viewer, selectionRectangle);
      if (!hitCandidateIds.length) return;
      const orderedCandidateIds = attentionManualTargetOptions(viewer.attentionScene).map((candidate) => candidate.id);
      const candidateIds = spatialSelectionForRectangle(
        orderedCandidateIds,
        selectedAttentionTargetObjectCandidateIds(viewer.attentionScene),
        hitCandidateIds,
        { additive: gesture.additive, toggle: gesture.toggle },
      );
      const primaryCandidateId = [...hitCandidateIds].reverse().find((candidateId) => candidateIds.includes(candidateId))
        || candidateIds[candidateIds.length - 1]
        || null;
      setAttentionTargetObjectSelection(candidateIds, viewer, { primaryCandidateId, focusViewer: true });
      return;
    }
    const selection = gesture.selection?.markerId || gesture.selection?.candidateId
      ? gesture.selection
      : attentionSelectionAtPointer(event);
    if (selection.markerId) {
      const marker = attentionSceneMarkers(viewer.attentionScene)
        .find((candidate) => candidate.id === selection.markerId);
      interactionLogger.recordSemanticClick(event, {
        kind: "attention-marker",
        label: attentionMarkerLabel(marker),
        markerId: selection.markerId,
        assetId: marker?.assetId,
        action: "select-attention-marker",
      });
      selectAttentionMarkerInViewer(selection.markerId);
      return;
    }
    if (selection.candidateId) {
      const candidate = attentionManualTargetOptions(viewer.attentionScene)
        .find((option) => option.id === selection.candidateId);
      interactionLogger.recordSemanticClick(event, {
        kind: "attention-target-object",
        label: attentionManualTargetLabel(candidate),
        candidateId: selection.candidateId,
        entityId: candidate?.entityId,
        assetId: candidate?.assetId,
        action: "select-attention-target",
      });
      selectAttentionTargetObjectInViewer(selection.candidateId, viewer, {
        additive: gesture.additive,
        toggle: gesture.toggle,
        focusViewer: true,
      });
      return;
    }
    if (!gesture.additive && !gesture.toggle) clearAttentionTargetObjectSelection(viewer);
  };
  viewer.pointerCancelHandler = (event) => {
    if (viewer.selectionPointerGesture?.pointerId !== event.pointerId) return;
    viewer.selectionPointerGesture = null;
    hideSelectionMarquee();
    if (renderer.domElement.hasPointerCapture?.(event.pointerId)) {
      renderer.domElement.releasePointerCapture?.(event.pointerId);
    }
  };
  renderer.domElement.addEventListener("pointerdown", viewer.pointerDownHandler);
  window.addEventListener("pointermove", viewer.pointerMoveHandler);
  window.addEventListener("pointerup", viewer.pointerUpHandler);
  window.addEventListener("pointercancel", viewer.pointerCancelHandler);
  viewer.keyDownHandler = (event) => {
    const editable = /^(input|textarea|select)$/i.test(event.target?.tagName || "") || event.target?.isContentEditable;
    if (
      !editable
      && !event.metaKey
      && !event.ctrlKey
      && !event.altKey
      && !event.repeat
      && ["Backspace", "Delete"].includes(event.key)
    ) {
      if (removeSelectedAttentionMarker(viewer)) event.preventDefault();
      return;
    }
    if (event.key !== "Escape" || !viewer.manualAttentionPlacementActive) return;
    event.preventDefault();
    cancelManualAttentionTargetPlacement(viewer);
  };
  window.addEventListener("keydown", viewer.keyDownHandler);
  viewer.resizeHandler = () => {
    if (viewer.disposed) return;
    const nextWidth = Math.max(container.clientWidth, 360);
    const nextHeight = Math.max(container.clientHeight, 520);
    camera.aspect = nextWidth / nextHeight;
    camera.updateProjectionMatrix();
    renderer.setSize(nextWidth, nextHeight);
  };
  window.addEventListener("resize", viewer.resizeHandler);
  const animate = (now) => {
    if (viewer.disposed) return;
    const delta = Math.min((now - viewer.lastFrameAt) / 1000, 0.05);
    viewer.lastFrameAt = now;
    viewer.elapsed += delta;
    updateSpatialUpstreamPlayback(viewer, delta);
    for (const object of viewer.attentionMarkerObjects.values()) {
      const ring = object.userData.attentionFacingRing;
      if (ring) ring.quaternion.copy(camera.quaternion);
    }
    updateAttentionTargetObjectSelectionHelpers(viewer);
    controls.update();
    renderer.render(scene, camera);
    viewer.animationId = requestAnimationFrame(animate);
  };
  viewer.animationId = requestAnimationFrame(animate);
}

function applyAttentionSpatialEntityTransform(entity, object) {
  if (!entity || !object) return;
  const transform = normalizeSpatialTransform(entity.transform, entity.inferredTransform);
  object.position.fromArray(transform.position);
  object.quaternion.fromArray(transform.quaternion);
  object.scale.fromArray(transform.scale);
  object.userData.attentionStoryObject = true;
}

function loadAttentionGuidanceGlb(viewer, entity, index, total, done) {
  const asset = findAssetById(entity.assetId);
  const src = asset && assetLoadSrc(asset);
  const wrapper = new THREE.Group();
  wrapper.name = `Fixed story object · ${entity.assetId}`;
  wrapper.userData.attentionStoryObject = true;
  wrapper.userData.spatialEntityId = entity.id;
  wrapper.userData.assetId = entity.assetId;
  viewer.root.add(wrapper);
  viewer.storyObjects.set(entity.id, wrapper);
  viewer.authoringSpatialObjects?.set(entity.id, wrapper);
  viewer.spatialObjects.set(entity.id, wrapper);
  applyAttentionSpatialEntityTransform(entity, wrapper);
  const placeholder = makeTextComfortPlaceholder(asset?.filename || entity.assetId, "3D model");
  placeholder.userData.attentionStoryObject = true;
  wrapper.add(placeholder);
  if (!src) {
    done(false);
    return;
  }
  const topologyPose = spatialTopologyAssetPose(viewer, index, Math.max(total, 1));
  const entry = {
    assetId: entity.assetId,
    entityId: entity.id,
    step: { assetId: entity.assetId, entityId: entity.id },
    authorWrapper: wrapper,
    wrapper,
    opacityMaterials: [],
    sourceScene: null,
    sourcePlayback: null,
  };
  createGltfLoader().load(src, (gltf) => {
    if (viewer.disposed) {
      disposeObject(gltf.scene);
      return;
    }
    wrapper.remove(placeholder);
    disposeObject(placeholder);
    applySpatialLoaderTransformPolicy(gltf.scene, entity);
    if (entity?.preserveSourceGeometry !== true) {
      normalizeSpatialRuntimeObject(
        gltf.scene,
        topologyPose.targetSize,
        spatialEntityVerticalAlignment(entity),
      );
    }
    gltf.scene.userData.attentionStoryObject = true;
    gltf.scene.traverse((object) => { object.userData.attentionStoryObject = true; });
    wrapper.add(gltf.scene);
    attachSpatialUpstreamPlayback(viewer, entry, gltf);
    wrapper.updateWorldMatrix(true, true);
    const bounds = new THREE.Box3().setFromObject(gltf.scene, true);
    if (!bounds.isEmpty()) {
      viewer.spatialAssetBounds.set(entity.assetId, {
        object: wrapper,
        local: wrapper.worldToLocal(bounds.getCenter(new THREE.Vector3())),
      });
    }
    viewer.attentionAssetEntries.set(entity.id, entry);
    done(true);
  }, undefined, () => done(false));
}

function loadAttentionGuidanceImage(viewer, entity, done) {
  const asset = findAssetById(entity.assetId);
  const src = asset && assetPreviewSrc(asset);
  const wrapper = new THREE.Group();
  wrapper.name = `Fixed story image · ${entity.assetId}`;
  wrapper.userData.attentionStoryObject = true;
  wrapper.userData.spatialEntityId = entity.id;
  wrapper.userData.assetId = entity.assetId;
  viewer.root.add(wrapper);
  viewer.storyObjects.set(entity.id, wrapper);
  viewer.authoringSpatialObjects?.set(entity.id, wrapper);
  applyAttentionSpatialEntityTransform(entity, wrapper);
  if (!src) {
    done(false);
    return;
  }
  new THREE.TextureLoader().load(src, (texture) => {
    if (viewer.disposed) {
      texture.dispose();
      return;
    }
    texture.colorSpace = THREE.SRGBColorSpace;
    const image = entity.image || {};
    const actualAspect = texture.image?.width && texture.image?.height ? texture.image.width / texture.image.height : null;
    const aspect = Number(image.aspectRatio) || actualAspect || 16 / 9;
    const width = Math.max(0.1, Number(image.width) || 1.6);
    const height = Math.max(0.1, Number(image.height) || width / Math.max(aspect, 0.1));
    const plane = new THREE.Mesh(
      new THREE.PlaneGeometry(width, height),
      new THREE.MeshBasicMaterial({ map: texture, transparent: true, side: THREE.DoubleSide }),
    );
    plane.userData.attentionStoryObject = true;
    wrapper.add(plane);
    viewer.attentionAssetEntries.set(entity.id, {
      assetId: entity.assetId,
      entityId: entity.id,
      authorWrapper: wrapper,
      wrapper,
      sourceScene: wrapper,
      sourcePlayback: null,
    });
    done(true);
  }, undefined, () => done(false));
}

function attentionSelectorIsNarrow(selector) {
  const value = String(selector || "").trim();
  return Boolean(value) && !/[\*{}]|\.\.|\s+plus\s+/i.test(value);
}

function attentionRenderableHasVisibleMaterial(object) {
  const materials = Array.isArray(object?.material) ? object.material : [object?.material].filter(Boolean);
  if (!materials.length) return true;
  return materials.some((material) => (
    material?.visible !== false
    && material?.colorWrite !== false
    && (!Number.isFinite(Number(material?.opacity)) || Number(material.opacity) > 0.02)
  ));
}

function attentionRenderableIsVisible(object, root) {
  if (!object?.isMesh || !object.geometry || !attentionRenderableHasVisibleMaterial(object)) return false;
  const positionCount = Number(object.geometry.attributes?.position?.count) || 0;
  const drawCount = Number(object.geometry.drawRange?.count);
  if (positionCount <= 0 || (Number.isFinite(drawCount) && drawCount <= 0)) return false;
  let reachedRoot = false;
  let current = object;
  while (current) {
    if (current.visible === false) return false;
    if (current === root) reachedRoot = true;
    current = current.parent;
  }
  return reachedRoot;
}

function attentionCandidateMeshes(entry, candidate) {
  const root = entry?.sourceScene;
  if (!root || !candidate) return [];
  root.updateWorldMatrix(true, true);
  const visibleMeshes = [];
  root.traverse((object) => {
    if (attentionRenderableIsVisible(object, root)) visibleMeshes.push(object);
  });
  if (candidate.targetKind === "standalone-glb") {
    const mode = String(entry.sourcePlayback?.asset?.mode || sourcePlaybackAssetForId(entry.assetId)?.mode || "").toLowerCase();
    const manuallySelected = String(candidate.provenance?.source || "").startsWith("author-manual");
    return mode === "shared-timeline" && !manuallySelected ? [] : visibleMeshes;
  }
  if (candidate.targetKind === "standalone-image") return visibleMeshes;
  if (candidate.targetKind !== "named-renderable-part" || !attentionSelectorIsNarrow(candidate.partSelector)) return [];
  return visibleMeshes.filter((object) => sourcePartSelectorMatchesNode(candidate.partSelector, object, root));
}

function attentionCandidateAssetEntry(viewer, candidate) {
  return candidate?.entityId
    ? viewer?.attentionAssetEntries?.get(candidate.entityId)
    : [...(viewer?.attentionAssetEntries?.values?.() || [])].find((value) => value?.assetId === candidate?.assetId);
}

function attentionVisibleMeshWorldBounds(mesh) {
  if (!mesh?.geometry) return null;
  mesh.updateWorldMatrix(true, false);
  if (mesh.isSkinnedMesh || mesh.isInstancedMesh) mesh.computeBoundingBox?.();
  else if (!mesh.geometry.boundingBox) mesh.geometry.computeBoundingBox?.();
  const localBounds = (mesh.isSkinnedMesh || mesh.isInstancedMesh)
    ? mesh.boundingBox
    : mesh.geometry.boundingBox;
  if (!localBounds || localBounds.isEmpty()) return null;
  return localBounds.clone().applyMatrix4(mesh.matrixWorld);
}

function attentionCandidateWorldBounds(viewer, candidate) {
  const entry = attentionCandidateAssetEntry(viewer, candidate);
  const meshes = attentionCandidateMeshes(entry, candidate);
  if (!meshes.length) return null;
  const bounds = new THREE.Box3();
  for (const mesh of meshes) {
    const meshBounds = attentionVisibleMeshWorldBounds(mesh);
    if (meshBounds) bounds.union(meshBounds);
  }
  if (bounds.isEmpty()) return null;
  const size = bounds.getSize(new THREE.Vector3());
  if (![size.x, size.y, size.z].every(Number.isFinite) || Math.max(size.x, size.y, size.z) <= 0.0001) return null;
  return bounds;
}

function attentionCandidatePosition(viewer, candidate) {
  const bounds = attentionCandidateWorldBounds(viewer, candidate);
  if (!bounds) return null;
  const center = bounds.getCenter(new THREE.Vector3());
  viewer.root.updateWorldMatrix(true, false);
  viewer.root.worldToLocal(center);
  if (![center.x, center.y, center.z].every(Number.isFinite)) return null;
  return { x: center.x, y: center.y, z: center.z };
}

function attentionTargetObjectCandidateFromPicks(exactPicks, fallbackPicks) {
  const closestForegroundPick = (picks) => [...(picks || [])]
    .filter((pick) => !pick.enclosesCamera)
    .sort((left, right) => left.distance - right.distance)[0] || null;
  return closestForegroundPick(exactPicks)?.candidate
    || closestForegroundPick(fallbackPicks)?.candidate
    || null;
}

function attentionTargetObjectCandidateAtRay(viewer, raycaster) {
  if (!viewer?.attentionScene || !raycaster?.ray) return null;
  const candidates = attentionManualTargetOptions(viewer.attentionScene);
  const candidateByEntityId = new Map(candidates.map((candidate) => [candidate.entityId, candidate]));
  const storyRoots = [...(viewer.storyObjects?.values?.() || [])].filter(Boolean);
  const cameraPosition = viewer.camera?.getWorldPosition?.(new THREE.Vector3()) || raycaster.ray.origin;
  const candidatePick = (candidate, distance) => {
    const object = viewer.storyObjects?.get(candidate?.entityId);
    if (
      !candidate
      || !object
      || object.userData?.spatialPlaybackActive === false
    ) return null;
    const bounds = attentionCandidateWorldBounds(viewer, candidate);
    if (!bounds) return null;
    return {
      candidate,
      distance,
      enclosesCamera: bounds.containsPoint(cameraPosition),
    };
  };
  const registerClosestPick = (map, pick) => {
    if (!pick) return;
    const previous = map.get(pick.candidate.id);
    if (!previous || pick.distance < previous.distance) map.set(pick.candidate.id, pick);
  };
  const exactPicksByCandidateId = new Map();
  for (const hit of raycaster.intersectObjects(storyRoots, true)) {
    if (!spatialObjectIsEffectivelyVisible(hit.object, viewer.scene)) continue;
    let target = hit.object;
    while (target && !target.userData?.spatialEntityId) target = target.parent;
    const candidate = candidateByEntityId.get(target?.userData?.spatialEntityId);
    registerClosestPick(exactPicksByCandidateId, candidatePick(candidate, hit.distance));
  }
  const fallbackPicksByCandidateId = new Map();
  for (const candidate of candidates) {
    if (candidate.targetKind !== "standalone-glb") continue;
    const object = viewer.storyObjects?.get(candidate.entityId);
    if (!object?.visible || object.userData?.spatialPlaybackActive === false) continue;
    let closestDistance = Number.POSITIVE_INFINITY;
    for (const bounds of preciseVisibleSpatialBounds(object, viewer.scene)) {
      const hitPoint = raycaster.ray.intersectBox(bounds, new THREE.Vector3());
      if (!hitPoint) continue;
      closestDistance = Math.min(closestDistance, raycaster.ray.origin.distanceTo(hitPoint));
    }
    if (Number.isFinite(closestDistance)) {
      registerClosestPick(fallbackPicksByCandidateId, candidatePick(candidate, closestDistance));
    }
  }
  const exactPicks = [...exactPicksByCandidateId.values()];
  const fallbackPicks = [...fallbackPicksByCandidateId.values()];
  return attentionTargetObjectCandidateFromPicks(exactPicks, fallbackPicks);
}

function attentionTargetCandidateIdsInSelectionRectangle(viewer, selectionRectangle) {
  const viewportRect = viewer?.renderer?.domElement?.getBoundingClientRect?.();
  const frustum = spatialSelectionFrustum(viewer?.camera, viewportRect, selectionRectangle);
  if (!viewer?.attentionScene || !frustum) return [];
  return attentionManualTargetOptions(viewer.attentionScene)
    .filter((candidate) => {
      const object = viewer.storyObjects?.get(candidate.entityId);
      if (!object || object.userData?.spatialPlaybackActive === false) return false;
      const bounds = attentionCandidateWorldBounds(viewer, candidate);
      return Boolean(bounds && frustum.intersectsBox(bounds));
    })
    .map((candidate) => candidate.id);
}

function attentionManualPlacementPosition(viewer, raycaster) {
  if (!viewer?.root || !raycaster?.ray) return null;
  const storyRoots = [...(viewer.storyObjects?.values?.() || [])].filter(Boolean);
  const storyHit = raycaster.intersectObjects(storyRoots, true).find((hit) => {
    let object = hit.object;
    while (object) {
      if (object.userData?.attentionMarkerId) return false;
      if (object.userData?.attentionStoryObject) return true;
      object = object.parent;
    }
    return false;
  });
  let worldPosition = storyHit?.point?.clone?.() || null;
  if (!worldPosition) {
    worldPosition = raycaster.ray.intersectPlane(
      new THREE.Plane(new THREE.Vector3(0, 1, 0), 0),
      new THREE.Vector3(),
    );
  }
  if (!worldPosition) {
    const target = viewer.controls?.target || new THREE.Vector3(0, 0.85, 0);
    const distance = Math.max(1.5, raycaster.ray.origin.distanceTo(target));
    worldPosition = raycaster.ray.at(distance, new THREE.Vector3());
  }
  viewer.root.updateWorldMatrix(true, false);
  const local = viewer.root.worldToLocal(worldPosition.clone());
  if (![local.x, local.y, local.z].every(Number.isFinite)) return null;
  return { x: local.x, y: local.y, z: local.z };
}

function evaluateAttentionGuidanceScene(viewer) {
  const scene = viewer?.attentionScene;
  if (!scene) return false;
  const allCandidates = attentionSceneCandidates(scene);
  const dismissedCandidateIds = new Set(attentionDismissedCandidateIds(scene));
  const candidates = allCandidates.filter((candidate) => !dismissedCandidateIds.has(candidate.id));
  const existing = new Map(attentionSceneMarkers(scene).map((marker) => [marker.id, marker]));
  const markers = [];
  let rejectedCandidateCount = 0;
  for (const candidate of candidates) {
    const saved = existing.get(candidate.id);
    const inferredPosition = candidate.targetKind === "spatial-point"
      ? attentionPosition(saved?.inferredPosition)
      : attentionCandidatePosition(viewer, candidate);
    if (!inferredPosition) {
      rejectedCandidateCount += 1;
      continue;
    }
    const savedPosition = saved ? attentionPosition(saved.position) : null;
    const marker = normalizeAttentionMarker({
      ...candidate,
      ...(saved || {}),
      id: candidate.id,
      assetId: candidate.assetId,
      entityId: candidate.entityId || saved?.entityId,
      targetKind: candidate.targetKind,
      partSelector: candidate.partSelector || saved?.partSelector,
      coordinateSpace: "spatial-scene",
      inferredPosition,
      position: savedPosition || inferredPosition,
      confidence: candidate.confidence ?? saved?.confidence,
      provenance: saved?.provenance || candidate.provenance,
      channels: candidate.channels,
      reconciliationStatus: candidate.reconciliationStatus,
      reviewRequired: candidate.reviewRequired,
    });
    if (marker) markers.push(marker);
  }
  for (const marker of markers) mountAttentionMarkerObject(viewer, marker);
  const previousSignature = JSON.stringify({
    evaluated: scene.evaluated === true,
    markers: attentionSceneMarkers(scene),
    resolvedCandidateCount: scene.evaluation?.resolvedCandidateCount,
    rejectedCandidateCount: scene.evaluation?.rejectedCandidateCount,
  });
  const nextSignature = JSON.stringify({
    evaluated: true,
    markers,
    resolvedCandidateCount: markers.length,
    rejectedCandidateCount,
  });
  if (viewer.locked) return false;
  scene.markers = markers;
  scene.evaluated = true;
  scene.reconciliation = attentionSceneReconciliation(scene);
  scene.evaluation = {
    status: "evaluated",
    resolvedCandidateCount: markers.length,
    rejectedCandidateCount,
    intentionallyEmpty: candidates.length === 0,
    reason: candidates.length === 0
      ? allCandidates.length ? "author-removed-focus-markers" : "no-clear-visible-candidates"
      : null,
  };
  const changed = previousSignature !== nextSignature;
  if (changed) {
    scene.evaluatedAt = new Date().toISOString();
    commitAttentionDraftMutation({ immediate: true });
  }
  return changed;
}

function makeAttentionMarkerObject(marker) {
  const group = new THREE.Group();
  group.name = `Attention target · ${marker.id}`;
  group.userData.attentionMarkerId = marker.id;
  const sphere = new THREE.Mesh(
    new THREE.SphereGeometry(0.14, 28, 18),
    new THREE.MeshStandardMaterial({
      color: 0xff5a1f,
      emissive: 0xc62d00,
      emissiveIntensity: 0.75,
      roughness: 0.32,
      metalness: 0.02,
      transparent: true,
      opacity: 0.92,
      depthTest: false,
    }),
  );
  sphere.renderOrder = 50;
  sphere.userData.attentionMarkerId = marker.id;
  group.add(sphere);
  const halo = new THREE.Mesh(
    new THREE.RingGeometry(0.2, 0.235, 40),
    new THREE.MeshBasicMaterial({
      color: 0xffb08f,
      transparent: true,
      opacity: 0.9,
      side: THREE.DoubleSide,
      depthTest: false,
      depthWrite: false,
    }),
  );
  halo.renderOrder = 51;
  halo.userData.attentionMarkerId = marker.id;
  group.userData.attentionFacingRing = halo;
  group.add(halo);
  return group;
}

function mountAttentionMarkerObject(viewer, marker) {
  if (!viewer || !marker || viewer.attentionMarkerObjects.has(marker.id)) return viewer?.attentionMarkerObjects?.get(marker.id) || null;
  const position = attentionPosition(marker.position);
  if (!position) return null;
  const object = makeAttentionMarkerObject(marker);
  object.position.set(position.x, position.y, position.z);
  viewer.root.add(object);
  viewer.attentionMarkerObjects.set(marker.id, object);
  viewer.attentionPickTargets.push(object);
  return object;
}

function selectAttentionMarkerInViewer(markerId) {
  const scene = attentionSceneRecordForContext(state.attentionGuidanceDraft, activeAttentionSceneContext());
  const marker = attentionSceneMarkers(scene).find((candidate) => candidate.id === markerId) || null;
  state.selectedAttentionMarkerId = marker?.id || null;
  for (const item of document.querySelectorAll("[data-attention-select-marker]")) {
    item.classList.toggle("selected", item.dataset.attentionSelectMarker === marker?.id);
  }
  const pill = document.querySelector(".attention-preview-card .attention-kind-pill");
  if (pill) pill.textContent = marker ? attentionMarkerLabel(marker) : "No focus marker";
  syncAttentionMarkerListFromSelection();
}

function syncAttentionMarkerListFromSelection() {
  const scene = attentionSceneRecordForContext(state.attentionGuidanceDraft, activeAttentionSceneContext());
  const marker = selectedAttentionMarker(scene);
  if (!marker) return;
  for (const item of document.querySelectorAll("[data-attention-select-marker]")) {
    if (item.dataset.attentionSelectMarker !== marker.id) continue;
    const status = item.querySelector("em");
    if (status) {
      status.textContent = marker.manual ? attentionMarkerEditLabel(marker) : "inferred";
      status.classList.toggle("inferred", !marker.manual);
    }
  }
}

function attentionSceneBounds(viewer) {
  const bounds = new THREE.Box3();
  for (const object of viewer?.storyObjects?.values?.() || []) {
    object.updateWorldMatrix(true, true);
    bounds.expandByObject(object);
  }
  for (const object of viewer?.attentionMarkerObjects?.values?.() || []) {
    object.updateWorldMatrix(true, true);
    bounds.expandByObject(object);
  }
  if (viewer?.readerProxy) {
    viewer.readerProxy.updateWorldMatrix(true, true);
    bounds.expandByObject(viewer.readerProxy);
  }
  return bounds;
}

function frameAttentionBounds(viewer, bounds) {
  if (!viewer || !bounds || bounds.isEmpty()) return false;
  const sphere = bounds.getBoundingSphere(new THREE.Sphere());
  const radius = Math.max(sphere.radius, 0.45);
  const fov = THREE.MathUtils.degToRad(viewer.camera.fov);
  const distance = Math.max(1.3, (radius / Math.sin(fov * 0.5)) * 1.35);
  viewer.camera.position.copy(sphere.center).add(new THREE.Vector3(1, 0.62, 1).normalize().multiplyScalar(distance));
  viewer.controls.target.copy(sphere.center);
  viewer.camera.near = Math.max(distance / 1000, 0.005);
  viewer.camera.far = Math.max(distance * 35, 100);
  viewer.camera.updateProjectionMatrix();
  viewer.controls.update();
  return true;
}

function fitAttentionEditorCameraOnLoad(viewer) {
  return fitAuthoringSpatialCameraOnLoad(viewer);
}

function spatialBeatScenePresence(beat) {
  if (!beat?.id) return "empty";
  const declaredStates = sourcePlaybackAssets()
    .map((asset) => sourcePlaybackBeatStateForAsset(asset, beat.id))
    .filter(Boolean);
  if (declaredStates.length) return declaredStates.some((beatState) => beatState.presence !== "inactive") ? "active" : "inactive";
  return (beat.linkedAssetIds || []).length ? "active" : "inactive";
}

function resolveSpatialUpstreamBeatState(beats, beatIndex, pendingTransition = null) {
  const list = Array.isArray(beats) ? beats : [];
  const beat = list[Math.max(0, Math.min(list.length - 1, Number(beatIndex) || 0))] || null;
  const pendingFrom = String(pendingTransition?.fromBeatId || "").trim();
  const pendingTo = String(pendingTransition?.toBeatId || "").trim();
  const playTransition = Boolean(beat?.id && pendingFrom && pendingTo === beat.id && pendingFrom !== pendingTo);
  const naturalPrevious = list[Math.max(0, (Number(beatIndex) || 0) - 1)] || null;
  const fromBeatId = playTransition ? pendingFrom : naturalPrevious?.id || beat?.id || "";
  const toBeatId = beat?.id || pendingTo || "";
  return {
    beat,
    fromBeatId,
    toBeatId,
    playTransition,
    sourceMotionTransition: playTransition ? { fromBeatId, toBeatId } : null,
    sourcePartPlaybackMode: beatSourcePartPlaybackMode(beat),
    cumulativeContext: cumulativeSingleAnchorContext(list, Math.max(0, Number(beatIndex) || 0)),
  };
}

function spatialPlaybackWindowForAsset(context, asset) {
  if (!asset || !context?.toBeatId) return { mode: "none", reason: "missing-spatial-upstream-state", boundary: null, beatState: null };
  if (context.playTransition && context.sourceMotionTransition) {
    const { fromBeatId, toBeatId } = context.sourceMotionTransition;
    const transitionWindow = sourcePlaybackWindowForAsset(asset, fromBeatId, toBeatId, { beatId: toBeatId });
    if (transitionWindow.boundary || transitionWindow.mode !== "none") return transitionWindow;
  }
  const beatState = sourcePlaybackBeatStateForAsset(asset, context.toBeatId);
  if (beatState?.presence !== "inactive" && beatState?.localProgress != null) {
    return {
      mode: "hold",
      holdProgress: clampSourcePlaybackProgress(beatState.localProgress, 0),
      contributorCount: Array.isArray(beatState.contributorClipIndexes) ? beatState.contributorClipIndexes.length : 0,
      boundary: null,
      beatState,
    };
  }
  return { mode: "none", reason: "inactive-or-unmapped-spatial-beat", boundary: null, beatState };
}

function spatialTopologyAssetPose(viewer, index, total) {
  return {
    position: new THREE.Vector3(0, 1.18, 0),
    targetSize: 1.9,
  };
}

function normalizeSpatialVerticalAlignment(value, fallback = "center") {
  const supplied = String(value || "").trim().toLowerCase();
  if (["ground", "grounded", "floor"].includes(supplied)) return "ground";
  if (["center", "centered", "centre", "centred"].includes(supplied)) return "center";
  return String(fallback || "").trim().toLowerCase() === "ground" ? "ground" : "center";
}

function spatialEntityVerticalAlignment(entity) {
  if (spatialEntityType(entity) !== "glb") return "center";
  return normalizeSpatialVerticalAlignment(
    entity?.verticalAlignment,
    "ground",
  );
}

function normalizeSpatialRuntimeObject(object, targetSize, verticalAlignment = "center") {
  const box = new THREE.Box3().setFromObject(object);
  if (box.isEmpty()) return;
  const center = box.getCenter(new THREE.Vector3());
  const size = box.getSize(new THREE.Vector3());
  const maxSize = Math.max(size.x, size.y, size.z) || 1;
  const scale = targetSize / maxSize;
  object.scale.multiplyScalar(scale);
  object.position.x -= center.x * scale;
  object.position.z -= center.z * scale;
  object.position.y -= (
    normalizeSpatialVerticalAlignment(verticalAlignment) === "ground"
      ? box.min.y
      : center.y
  ) * scale;
}

function applySpatialLoaderTransformPolicy(root, entity) {
  if (!root || entity?.loaderTransformPolicy !== "reset-immediate-child-scale") return false;
  const target = String(entity.loaderTransformTarget || "").trim().toLowerCase().replace(/_/g, "-");
  const targetRoot = target === "first-scene-child-children"
    ? root.children?.[0]
    : ["immediate-children", "default", "legacy"].includes(target)
      ? root
      : null;
  if (!targetRoot) return false;
  for (const child of targetRoot.children || []) child.scale.set(1, 1, 1);
  root.updateMatrixWorld(true);
  return true;
}

function makeSpatialEditorFloorGuide(topologyKind) {
  const targetSize = spatialTopologyAssetPose({ topologyKind }, 0, 1).targetSize;
  const size = Math.max(7, targetSize * 1.8);
  const grid = new THREE.GridHelper(size, 20, 0x72a89d, 0xb7cec7);
  grid.name = "StoryVR editor floor guide";
  grid.position.y = 0.005;
  grid.userData.spatialEditorOnly = true;
  const materials = Array.isArray(grid.material) ? grid.material : [grid.material];
  for (const material of materials) {
    material.transparent = true;
    material.opacity = 0.28;
    material.depthWrite = false;
  }
  return grid;
}

function spatialSourceCameraCanDriveReader(runtime) {
  const policy = String(runtime?.asset?.camera?.xrPolicy || "source").trim().toLowerCase();
  return !["preserve-viewer-camera", "preserve-viewer", "viewer", "author", "orbit", "manual", "disabled"].includes(policy);
}

function syncSpatialReaderRigToSourceCamera(viewer, entry) {
  const runtime = entry?.sourcePlayback;
  const sourceCamera = runtime?.sourceCamera;
  if (!viewer?.readerRig || !viewer?.root || !sourceCamera || entry?.sourcePlaybackContractActive === false) return false;
  if (entry?.entity?.authoredInstance === true) return false;
  if (viewer.readerEntity?.manual === true) return false;
  if (
    viewer.transformControls?.dragging
    && (
      viewer.transformControls.object === viewer.readerRig
      || viewer.transformSelectionStart?.entries?.some((entry) => entry.object === viewer.readerRig)
    )
  ) return false;
  if (!spatialSourceCameraCanDriveReader(runtime)) return false;
  const linkedAssetIds = new Set(viewer.beat?.linkedAssetIds || []);
  if (linkedAssetIds.size && !linkedAssetIds.has(entry.assetId)) return false;
  sourceCamera.updateWorldMatrix(true, false);
  viewer.root.updateWorldMatrix(true, false);
  const worldPosition = sourceCamera.getWorldPosition(new THREE.Vector3());
  const worldQuaternion = sourceCamera.getWorldQuaternion(new THREE.Quaternion());
  const rootQuaternion = viewer.root.getWorldQuaternion(new THREE.Quaternion()).invert();
  viewer.readerRig.position.copy(viewer.root.worldToLocal(worldPosition));
  viewer.readerRig.quaternion.copy(rootQuaternion.multiply(worldQuaternion));
  viewer.readerRig.updateWorldMatrix(true, true);
  updateSpatialReaderProxyUpright(viewer.readerRig, viewer.readerProxy);
  return true;
}

function updateSpatialUpstreamPlayback(viewer, delta) {
  if (!viewer?.spatialPlaybackReady) return;
  if (viewer.playing) viewer.sourceElapsed += previewPlaybackDeltaSeconds(viewer, delta);
  let transitionStillPlaying = false;
  let readerSynced = false;
  for (const entry of viewer.spatialPlaybackEntries || []) {
    const runtime = entry?.sourcePlayback;
    if (!runtime) continue;
    if (entry.spatialTransitionPlaying) {
      const duration = Math.max(Number(entry.spatialTransitionDuration) || 0, 0.001);
      const transitionProgress = Math.max(0, Math.min(1, viewer.sourceElapsed / duration));
      const sourceProgress = runtime.windowState.startProgress + transitionProgress * (
        runtime.windowState.endProgress - runtime.windowState.startProgress
      );
      seekSourceTransitionPlayback(entry, sourceProgress, viewer.sourceElapsed);
      if (transitionProgress < 1) transitionStillPlaying = true;
      else {
        entry.spatialTransitionPlaying = false;
        applySpatialSourcePartMask(viewer, entry);
      }
    } else {
      applySourcePlaybackBindings(runtime);
      updateSourcePlaybackAnnotations(runtime);
    }
    if (!readerSynced) readerSynced = syncSpatialReaderRigToSourceCamera(viewer, entry);
  }
  if (viewer.playing && !transitionStillPlaying) viewer.playing = false;
}

function createSpatialReaderRig(root, readerEntity = null) {
  const pose = spatialReaderRigPose();
  const rig = new THREE.Group();
  rig.name = "StoryVR reader anchor · editor proxy";
  if (readerEntity) {
    const transform = normalizeSpatialTransform(readerEntity.transform, readerEntity.inferredTransform);
    rig.position.fromArray(transform.position);
    rig.quaternion.fromArray(transform.quaternion);
    rig.scale.set(1, 1, 1);
    rig.userData.spatialEntityId = readerEntity.id;
  } else {
    rig.position.copy(pose.position);
    const poseCamera = new THREE.PerspectiveCamera();
    poseCamera.position.copy(pose.position);
    poseCamera.lookAt(pose.target);
    rig.quaternion.copy(poseCamera.quaternion);
  }
  rig.userData.spatialEditorOnly = true;
  root.add(rig);

  const proxy = makeSpatialReaderProxy(pose.position.y);
  if (readerEntity) proxy.userData.spatialEntityId = readerEntity.id;
  rig.add(proxy);
  updateSpatialReaderProxyUpright(rig, proxy);
  return { rig, proxy };
}

function spatialReaderRigPose() {
  return {
    position: new THREE.Vector3(0, 1.55, 5.2),
    target: new THREE.Vector3(0, 1.25, 0),
  };
}

function updateSpatialReaderProxyUpright(rig, proxy) {
  const upright = proxy?.userData?.spatialUprightGroup;
  if (!rig || !upright) return;
  upright.quaternion.copy(rig.quaternion).invert();
  upright.updateWorldMatrix(true, true);
}

function makeSpatialReaderProxy(eyeHeight = 1.35) {
  const proxy = new THREE.Group();
  proxy.name = "StoryVR reader proxy · editor only";
  proxy.userData.spatialEditorOnly = true;

  const upright = new THREE.Group();
  upright.name = "StoryVR grounded reader silhouette";
  upright.userData.spatialEditorOnly = true;
  proxy.userData.spatialUprightGroup = upright;
  proxy.add(upright);

  const head = new THREE.Mesh(
    new THREE.SphereGeometry(0.1, 20, 16),
    new THREE.MeshStandardMaterial({ color: 0x0f211d, roughness: 0.72 }),
  );
  upright.add(head);

  const bodyHeight = Math.max(0.48, Number(eyeHeight) - 0.12);
  const body = new THREE.Mesh(
    new THREE.CylinderGeometry(0.075, 0.115, 1, 18),
    new THREE.MeshStandardMaterial({ color: 0x007f73, roughness: 0.72 }),
  );
  body.scale.y = bodyHeight;
  body.position.y = -(0.12 + bodyHeight * 0.5);
  upright.add(body);

  const feet = new THREE.Mesh(
    new THREE.RingGeometry(0.12, 0.18, 32),
    new THREE.MeshBasicMaterial({ color: 0x007f73, transparent: true, opacity: 0.72, side: THREE.DoubleSide }),
  );
  feet.rotation.x = -Math.PI / 2;
  feet.position.y = -Number(eyeHeight) + 0.012;
  upright.add(feet);

  const corners = [
    new THREE.Vector3(-0.22, 0.14, -0.55),
    new THREE.Vector3(0.22, 0.14, -0.55),
    new THREE.Vector3(0.22, -0.14, -0.55),
    new THREE.Vector3(-0.22, -0.14, -0.55),
  ];
  const eye = new THREE.Vector3();
  const linePoints = [];
  for (const corner of corners) linePoints.push(eye.clone(), corner);
  for (let index = 0; index < corners.length; index += 1) {
    linePoints.push(corners[index], corners[(index + 1) % corners.length]);
  }
  const frustum = new THREE.LineSegments(
    new THREE.BufferGeometry().setFromPoints(linePoints),
    new THREE.LineBasicMaterial({ color: 0x007f73, transparent: true, opacity: 0.62 }),
  );
  proxy.add(frustum);

  const label = makeTextSprite("Reader", {
    y: 0.24,
    z: 0.02,
    width: 0.58,
    height: 0.16,
    color: "#007f73",
    background: "rgba(255,253,244,0.9)",
  });
  upright.add(label);
  return proxy;
}

function applySpatialSourcePartMask(viewer, entry) {
  if (!entry?.sourceScene) return null;
  if (entry.sourcePlayback?.asset?.mode === "shared-timeline") return { applied: false, contractOwned: true };
  const selectors = sourcePartSelectorsForBeatAsset(viewer?.sourcePartToBeatId, entry.assetId);
  const result = applySourcePartMask(entry.sourceScene, selectors);
  entry.sourcePartMaskResult = result;
  return result;
}

function updateSpatialSourceFocus(viewer, entry) {
  const cue = sourceSpatialCueForBeat(viewer?.beat?.id, entry?.assetId);
  const runtime = entry?.sourcePlayback;
  if (!cue || !runtime?.sourceCamera) return false;
  const previousProgress = runtime.progress;
  seekSourceTransitionPlayback(entry, cue.sourceProgress, runtime.clockSeconds);
  const evaluation = sourceCameraSceneEvaluation(runtime.sourceCamera, runtime.root);
  if (evaluation.focus && evaluation.focusHit) {
    viewer.spatialSourceFocus.set(`${viewer.beat.id}:${entry.assetId}`, {
      object: entry.authorWrapper,
      local: entry.authorWrapper.worldToLocal(evaluation.focus.clone()),
      status: evaluation.status,
    });
  }
  if (previousProgress != null) seekSourceTransitionPlayback(entry, previousProgress, runtime.clockSeconds);
  return Boolean(evaluation.focus && evaluation.focusHit);
}

function attachSpatialUpstreamPlayback(viewer, entry, gltf) {
  entry.sourceScene = gltf.scene;
  viewer.resolveSourcePlaybackWindow = (asset) => spatialPlaybackWindowForAsset(viewer.upstreamBeatState, asset);
  const attached = attachSourceTransitionPlayback(viewer, entry, gltf);
  if (!attached) {
    entry.sourcePlaybackContractActive = true;
    gltf.scene.visible = true;
  }
  entry.authorWrapper.userData.spatialPlaybackActive = entry.sourcePlaybackContractActive !== false;
  if (entry.sourcePlayback?.asset?.mode !== "shared-timeline") {
    entry.sourcePartMaskResult = applySourcePartMask(
      gltf.scene,
      sourcePartSelectorsForBeatAsset(viewer.sourcePartToBeatId, entry.assetId),
    );
  }
  entry.spatialTransitionPlaying = Boolean(
    viewer.upstreamBeatState?.playTransition
    && entry.sourcePlayback?.windowState?.mode === "scrub",
  );
  entry.spatialTransitionDuration = entry.spatialTransitionPlaying
    ? sourcePlaybackScrubCycleSeconds(
      entry.sourcePlayback.asset,
      entry.sourcePlayback.windowState,
      INTER_BEAT_TRANSITION_CYCLE_SECONDS,
      entry.sourcePlayback.masterDuration,
    )
    : 0;
  viewer.spatialPlaybackEntries.push(entry);
  updateSpatialSourceFocus(viewer, entry);
  syncSpatialReaderRigToSourceCamera(viewer, entry);
  return attached;
}

function loadSpatialRelationsGlb(viewer, assetLink, index, total, done) {
  const asset = findAssetById(assetLink.assetId);
  const entityId = assetLink.entityId || `glb:${assetLink.assetId}:beat:${viewer.beat?.id || "scene"}`;
  const topologyPose = spatialTopologyAssetPose(viewer, index, Math.max(total, 1));
  const topologyWrapper = new THREE.Group();
  topologyWrapper.name = `StoryVR scene anchor · ${assetLink.assetId}`;
  const authorWrapper = new THREE.Group();
  authorWrapper.name = `StoryVR author transform · ${assetLink.assetId}`;
  authorWrapper.userData.spatialEntityId = entityId;
  authorWrapper.userData.assetId = assetLink.assetId;
  topologyWrapper.add(authorWrapper);
  const entity = spatialRelationEntityById(viewer.spatialContract || state.spatialRelationsDraft, entityId);
  viewer.root.add(topologyWrapper);
  viewer.spatialObjects.set(entityId, authorWrapper);
  viewer.authoringSpatialObjects?.set(entityId, authorWrapper);
  const placeholder = makeTextComfortPlaceholder(asset?.filename || assetLink.assetId, "3D model");
  placeholder.userData.spatialEntityId = entityId;
  placeholder.traverse((object) => { object.userData.spatialEntityId = entityId; });
  authorWrapper.add(placeholder);
  viewer.spatialPickTargets.push(placeholder);
  if (entity) applySpatialEntityTransformToObject(viewer, entity, authorWrapper);
  registerInteractionInBeatTargetCandidate(viewer, {
    entityId,
    assetId: assetLink.assetId,
    label: spatialRelationEntityLabel(entity || assetLink),
    object: authorWrapper,
    initialTransform: interactionObjectTransform(authorWrapper),
  });
  if (
    !viewer.locked
    && spatialEntityTransformEditable(entity)
    && selectedSpatialRelationEntityIds().length === 1
    && state.selectedSpatialEntityId === entityId
  ) viewer.transformControls?.attach(authorWrapper);
  const src = asset && assetLoadSrc(asset);
  if (!asset || !src) {
    done(false);
    return;
  }
  const entry = {
    assetId: assetLink.assetId,
    entity,
    step: assetLink,
    topologyWrapper,
    authorWrapper,
    wrapper: authorWrapper,
    opacityMaterials: [],
    sourceScene: null,
    sourcePlayback: null,
  };
  createGltfLoader().load(src, (gltf) => {
    if (viewer.disposed) {
      disposeObject(gltf.scene);
      return;
    }
    authorWrapper.remove(placeholder);
    disposeObject(placeholder);
    viewer.spatialPickTargets = viewer.spatialPickTargets.filter((object) => object !== placeholder);
    applySpatialLoaderTransformPolicy(gltf.scene, entity);
    if (entity?.preserveSourceGeometry !== true) {
      normalizeSpatialRuntimeObject(
        gltf.scene,
        topologyPose.targetSize,
        spatialEntityVerticalAlignment(entity),
      );
    }
    gltf.scene.userData.spatialEntityId = entityId;
    gltf.scene.traverse((object) => { object.userData.spatialEntityId = entityId; });
    authorWrapper.add(gltf.scene);
    viewer.spatialPickTargets.push(gltf.scene);
    attachSpatialUpstreamPlayback(viewer, entry, gltf);
    registerInteractionInBeatGltfParts(viewer, {
      entityId,
      assetId: assetLink.assetId,
      label: spatialRelationEntityLabel(entity || assetLink),
      sceneRoot: gltf.scene,
      parser: gltf.parser,
    });
    authorWrapper.updateWorldMatrix(true, true);
    const bounds = new THREE.Box3().setFromObject(gltf.scene);
    if (!bounds.isEmpty()) {
      const center = bounds.getCenter(new THREE.Vector3());
      const size = bounds.getSize(new THREE.Vector3());
      center.y += size.y * 0.32;
      viewer.spatialAssetBounds.set(assetLink.assetId, {
        object: authorWrapper,
        local: authorWrapper.worldToLocal(center.clone()),
      });
    }
    done(true);
  }, undefined, () => done(false));
}

function loadSpatialRelationsImage(viewer, assetLink, index, total, done) {
  const asset = findAssetById(assetLink.assetId);
  const entityId = assetLink.entityId || `image:${assetLink.assetId}:beat:${viewer.beat?.id || "scene"}`;
  const entity = spatialRelationEntityById(viewer.spatialContract || state.spatialRelationsDraft, entityId);
  const authorWrapper = new THREE.Group();
  authorWrapper.name = `StoryVR image-plane transform · ${assetLink.assetId}`;
  authorWrapper.userData.spatialEntityId = entityId;
  authorWrapper.userData.assetId = assetLink.assetId;
  viewer.root.add(authorWrapper);
  viewer.spatialObjects.set(entityId, authorWrapper);
  viewer.authoringSpatialObjects?.set(entityId, authorWrapper);
  const placeholder = makeTextComfortPlaceholder(asset?.filename || assetLink.assetId, "IMG");
  placeholder.userData.spatialEntityId = entityId;
  placeholder.traverse((object) => { object.userData.spatialEntityId = entityId; });
  authorWrapper.add(placeholder);
  viewer.spatialPickTargets.push(placeholder);
  if (entity) applySpatialEntityTransformToObject(viewer, entity, authorWrapper);
  if (
    !viewer.locked
    && spatialEntityTransformEditable(entity)
    && selectedSpatialRelationEntityIds().length === 1
    && state.selectedSpatialEntityId === entityId
  ) viewer.transformControls?.attach(authorWrapper);
  const src = asset && assetPreviewSrc(asset);
  if (!asset || !src) {
    done(false);
    return;
  }
  new THREE.TextureLoader().load(src, (texture) => {
    if (viewer.disposed) {
      texture.dispose();
      return;
    }
    texture.colorSpace = THREE.SRGBColorSpace;
    authorWrapper.remove(placeholder);
    disposeObject(placeholder);
    viewer.spatialPickTargets = viewer.spatialPickTargets.filter((object) => object !== placeholder);
    const image = entity?.image || {};
    const actualAspect = texture.image?.width && texture.image?.height ? texture.image.width / texture.image.height : null;
    const aspect = Number(image.aspectRatio) || actualAspect || 16 / 9;
    const width = Math.max(0.1, Number(image.width) || 1.6);
    const height = Math.max(0.1, Number(image.height) || width / Math.max(aspect, 0.1));
    const plane = new THREE.Mesh(
      new THREE.PlaneGeometry(width, height),
      new THREE.MeshBasicMaterial({ map: texture, transparent: true, side: THREE.DoubleSide }),
    );
    plane.userData.spatialEntityId = entityId;
    authorWrapper.add(plane);
    viewer.spatialPickTargets.push(plane);
    done(true);
  }, undefined, () => done(false));
}

function spatialTextPlacementFromEntity(entity) {
  const transform = normalizeSpatialTransform(entity?.transform, entity?.inferredTransform);
  const panel = entity?.panel || {};
  return {
    coordinateSpace: normalizeSpatialAnchor(entity?.anchor, entity).type,
    position: { x: 0, y: 0, z: 0 },
    rotation: { x: 0, y: 0, z: 0 },
    scale: 1,
    width: Number(panel.width) || 1.35,
    height: Number(panel.height) || 0.72,
    facesReader: entity?.orientationPolicy === "reader-facing" || entity?.orientationPolicy === "reader-facing-yaw",
    transform,
  };
}

function spatialAnchorWorldPosition(viewer, entity) {
  const anchor = normalizeSpatialAnchor(entity?.anchor, entity);
  if (anchor.type === "reader") return viewer?.readerRig?.getWorldPosition(new THREE.Vector3()) || new THREE.Vector3();
  if (anchor.type === "asset" || anchor.type === "source-focus") {
    const assetId = anchor.assetId || viewer?.beat?.linkedAssetIds?.[0] || null;
    const focus = anchor.type === "source-focus" && assetId
      ? viewer?.spatialSourceFocus?.get(`${entity?.beatId || viewer?.beat?.id}:${assetId}`)
      : null;
    if (focus?.object && focus?.local) {
      focus.object.updateWorldMatrix(true, false);
      return focus.object.localToWorld(focus.local.clone());
    }
    const boundsAnchor = assetId ? viewer?.spatialAssetBounds?.get(assetId) : null;
    if (boundsAnchor?.object && boundsAnchor?.local) {
      boundsAnchor.object.updateWorldMatrix(true, false);
      return boundsAnchor.object.localToWorld(boundsAnchor.local.clone());
    }
    const object = assetId ? [...(viewer?.spatialObjects?.entries?.() || [])]
      .find(([entityId]) => spatialRelationEntityById(state.spatialRelationsDraft, entityId)?.assetId === assetId)?.[1] : null;
    if (object) {
      object.updateWorldMatrix(true, false);
      return object.getWorldPosition(new THREE.Vector3());
    }
    if (assetId && viewer?.assetPositions?.has(assetId)) return viewer.assetPositions.get(assetId).clone();
  }
  return new THREE.Vector3();
}

function applySpatialEntityTransformToObject(viewer, entity, object) {
  if (!entity || !object) return;
  const transform = normalizeSpatialTransform(entity.transform, entity.inferredTransform);
  const position = new THREE.Vector3(...transform.position);
  const isText = spatialEntityType(entity) === "text-panel";
  const isReader = spatialEntityType(entity) === "reader";
  const anchor = isText ? normalizeSpatialAnchor(entity.anchor, entity) : null;
  if (!isText) {
    object.position.copy(position);
    object.quaternion.fromArray(transform.quaternion);
    if (isReader) object.scale.set(1, 1, 1);
    else object.scale.fromArray(transform.scale);
    object.userData.spatialEntityId = entity.id;
    if (isReader) updateSpatialReaderProxyUpright(object, viewer?.readerProxy);
    return;
  }
  if (anchor.type === "reader") {
    if (object.parent !== viewer.readerRig) {
      object.removeFromParent();
      viewer.readerRig.add(object);
    }
  } else {
    if (object.parent !== viewer.root) {
      object.removeFromParent();
      viewer.root.add(object);
    }
    position.add(spatialAnchorWorldPosition(viewer, entity));
  }
  object.position.copy(position);
  object.quaternion.fromArray(transform.quaternion);
  object.scale.fromArray(transform.scale);
  object.userData.spatialEntityId = entity.id;
}

function lockedSpatialGlbEntityForViewer(viewer, assetId, entityId = "", explicitSceneContext = null) {
  const contract = lockedSpatialRelationsContract();
  const asset = findAssetById(assetId);
  const expectedType = isImageAsset(asset) ? "image-plane" : "glb";
  const requestedEntityId = String(entityId || "").trim();
  const matchesAssetEntity = (candidate) => (
    spatialEntityType(candidate) === expectedType
    && (
      candidate.assetId === assetId
      || candidate.id === `${expectedType === "image-plane" ? "image" : "glb"}:${assetId}`
      || String(candidate.id || "").startsWith(`${expectedType === "image-plane" ? "image" : "glb"}:${assetId}:`)
    )
  );
  const mappedEntityContext = requestedEntityId
    ? viewer?.spatialSceneContextsByEntityId?.get?.(requestedEntityId) || null
    : null;
  const mappedContext = viewer?.spatialSceneContextsByAssetId?.get?.(assetId) || null;
  const viewerContext = explicitSceneContext?.beatId
    ? explicitSceneContext
    : mappedEntityContext || mappedContext || (viewer?.sceneContext?.beatId ? viewer.sceneContext : null);
  const context = viewerContext?.beatId
    ? spatialSceneContext(
      viewerContext.beatId,
      viewerContext.variantGroupId,
      viewerContext.variantOptionId,
    )
    : viewer?.beat?.id
      ? spatialSceneContext(viewer.beat.id, viewer.beat.variantGroupId, viewer.beat.variantOptionId)
      : null;
  if (context?.beatId) {
    const scene = spatialSceneRecordForContext(contract, context);
    const sceneEntities = spatialSceneEntities(contract, context);
    const entity = requestedEntityId
      ? sceneEntities.find((candidate) => (
        String(candidate?.id || "") === requestedEntityId && matchesAssetEntity(candidate)
      ))
      : sceneEntities.find(matchesAssetEntity);
    if (entity || scene || contract?.schemaVersion === "storyvr-spatial-relations/v2") return entity || null;
  }
  if (requestedEntityId) {
    const entity = spatialRelationEntityById(contract, requestedEntityId);
    return matchesAssetEntity(entity) ? entity : null;
  }
  return spatialRelationEntityById(contract, `${expectedType === "image-plane" ? "image" : "glb"}:${assetId}`);
}

function applyLockedSpatialGlbTransform(viewer, assetId, authorWrapper, resolvedEntity = null) {
  if (!viewer?.layers?.enabled?.[SPATIAL_RELATIONS_COMPONENT_ID] || !authorWrapper || !assetId) return false;
  const entity = resolvedEntity || lockedSpatialGlbEntityForViewer(viewer, assetId);
  if (!entity) return false;
  const transform = normalizeSpatialTransform(entity.transform, entity.inferredTransform);
  authorWrapper.position.fromArray(transform.position);
  authorWrapper.quaternion.fromArray(transform.quaternion);
  authorWrapper.scale.fromArray(transform.scale);
  authorWrapper.userData.spatialEntityId = entity.id;
  return true;
}

function persistSpatialObjectTransform(viewer, object) {
  if (viewer?.locked) return;
  const entityId = object?.userData?.spatialEntityId;
  const entity = spatialRelationEntityById(state.spatialRelationsDraft, entityId);
  if (!entity || !spatialEntityTransformEditable(entity)) return;
  const isReader = spatialEntityType(entity) === "reader";
  const position = object.position.clone();
  if (spatialEntityType(entity) === "text-panel" && normalizeSpatialAnchor(entity.anchor, entity).type !== "reader") {
    position.sub(spatialAnchorWorldPosition(viewer, entity));
  }
  entity.transform = normalizeSpatialTransform({
    position: position.toArray(),
    quaternion: object.quaternion.toArray(),
    scale: isReader ? [1, 1, 1] : object.scale.toArray(),
  }, entity.inferredTransform);
  if (isReader) {
    object.scale.set(1, 1, 1);
    entity.transform.scale = [1, 1, 1];
    updateSpatialReaderProxyUpright(object, viewer.readerProxy);
  }
  entity.manual = entity.authoredInstance === true
    || !spatialTransformsEqual(entity.transform, entity.inferredTransform)
    || JSON.stringify(normalizeSpatialAnchor(entity.anchor, entity)) !== JSON.stringify(entity._inferredAnchor)
    || entity.orientationPolicy !== entity._inferredOrientationPolicy;
}

function updateSpatialAnchoredTextPanel(viewer) {
  if (!viewer?.panel || !viewer?.beat?.id) return;
  const entity = spatialRelationEntityById(state.spatialRelationsDraft, `text-panel:${viewer.beat.id}`);
  if (!entity) return;
  if (viewer.transformControls?.object !== viewer.panel || !viewer.transformControls?.dragging) {
    applySpatialEntityTransformToObject(viewer, entity, viewer.panel);
  }
  const anchor = spatialAnchorWorldPosition(viewer, entity);
  viewer.anchorMarker?.position.copy(anchor);
  if (viewer.calloutLine) updateTextPanelCallout(viewer.calloutLine, anchor, spatialPanelScenePosition(viewer, viewer.panel));
}

function spatialPanelScenePosition(viewer, panel) {
  if (!panel) return new THREE.Vector3();
  panel.updateWorldMatrix(true, false);
  const position = panel.getWorldPosition(new THREE.Vector3());
  if (viewer?.root) viewer.root.worldToLocal(position);
  return position;
}

function applySpatialTextOrientationInEditor(viewer) {
  if (!viewer?.panel || viewer.transformControls?.dragging) return;
  const entity = spatialRelationEntityById(state.spatialRelationsDraft, viewer.panel.userData.spatialEntityId);
  if (!entity || viewer.panel.parent === viewer.readerRig) return;
  const policy = String(entity.orientationPolicy || "fixed");
  if (!["reader-facing-yaw", "reader-facing"].includes(policy)) return;
  const target = viewer.readerRig?.getWorldPosition(new THREE.Vector3()) || new THREE.Vector3();
  if (policy === "reader-facing-yaw") target.y = viewer.panel.getWorldPosition(new THREE.Vector3()).y;
  viewer.panel.lookAt(target);
}

function applySpatialTextCollisionClearanceInEditor(viewer) {
  if (!viewer?.panel || !viewer?.beat?.id || viewer.transformControls?.dragging) return;
  const entity = spatialRelationEntityById(state.spatialRelationsDraft, `text-panel:${viewer.beat.id}`);
  const clearance = normalizeSpatialPanelClearance(entity?.clearance, false);
  const anchor = normalizeSpatialAnchor(entity?.anchor, entity);
  if (!clearance.enabled || !["source-focus", "asset"].includes(anchor.type) || !anchor.assetId) {
    viewer.panel.userData.spatialClearanceStatus = "disabled";
    return;
  }
  const entry = (viewer.spatialPlaybackEntries || []).find((candidate) => candidate.assetId === anchor.assetId);
  const collisionRoot = entry?.sourceScene;
  if (!collisionRoot) {
    viewer.panel.userData.spatialClearanceStatus = "unresolved-anchor";
    return;
  }
  const clearanceCamera = anchor.type === "source-focus" ? entry?.sourcePlayback?.sourceCamera : null;
  const cameraPosition = clearanceCamera?.getWorldPosition?.(new THREE.Vector3())
    || viewer.readerRig?.getWorldPosition(new THREE.Vector3())
    || viewer.camera?.getWorldPosition(new THREE.Vector3());
  if (!cameraPosition) return;
  resolveSpatialTextPanelClearance(
    viewer.panel,
    collisionRoot,
    cameraPosition,
    clearance,
    viewer.playing === true,
    `${viewer.beat.id}:${anchor.assetId}`,
    entity.orientationPolicy,
  );
  if (viewer.calloutLine) {
    const anchorPosition = spatialAnchorWorldPosition(viewer, entity);
    updateTextPanelCallout(viewer.calloutLine, anchorPosition, spatialPanelScenePosition(viewer, viewer.panel));
  }
}

function resolveSpatialTextPanelClearance(
  panel,
  collisionRoot,
  cameraPosition,
  clearance,
  sceneChanging = false,
  cacheKey = "",
  orientationPolicy = "fixed",
) {
  const panelMesh = panel?.children?.find((node) => node.isMesh && node.geometry?.type === "PlaneGeometry");
  if (!panelMesh || !collisionRoot || !cameraPosition) return 0;
  const basePosition = panel.position.clone();
  const direction = cameraPosition.clone().sub(basePosition);
  const cameraDistance = direction.length();
  if (cameraDistance <= 0.5) return 0;
  direction.normalize();
  const maximum = Math.min(clearance.maxPushDistance, Math.max(0, cameraDistance - 0.5));
  const correctionMargin = Math.min(0.02, Math.max(0.005, clearance.minSurfaceDistance * 0.075));
  const now = performance.now();
  const previous = panel.userData.spatialClearanceState || (cacheKey ? spatialTextClearanceCache.get(cacheKey) : null);
  const baseMoved = !previous?.basePosition || previous.basePosition.distanceToSquared(basePosition) > 0.0004;
  const cameraMoved = !previous?.cameraPosition || previous.cameraPosition.distanceToSquared(cameraPosition) > 0.0004;
  let pushDistance = previous?.pushDistance || 0;
  let saturated = previous?.saturated === true;
  const settledAfterAnimation = previous?.sceneChanging === true && !sceneChanging;
  const recheckDue = !previous || settledAfterAnimation || (
    now - (previous?.checkedAt || 0) >= clearance.recheckIntervalMs
    && (sceneChanging || baseMoved || cameraMoved)
  );
  if (recheckDue) {
    const resetForSettledPose = !previous || settledAfterAnimation || (!sceneChanging && (baseMoved || cameraMoved));
    if (resetForSettledPose) {
      pushDistance = 0;
      saturated = false;
    }
    collisionRoot.updateWorldMatrix(true, true);
    const collisionProxy = spatialVisibleTextCollisionProxy(collisionRoot);
    const iterationCount = resetForSettledPose ? 4 : 1;
    for (let iteration = 0; iteration < iterationCount; iteration += 1) {
      panel.position.copy(basePosition).addScaledVector(direction, pushDistance);
      orientSpatialTextPanelForClearance(panel, cameraPosition, orientationPolicy);
      panel.updateWorldMatrix(true, true);
      const deficit = spatialPanelClearanceDeficit(
        panelMesh,
        collisionProxy,
        cameraPosition,
        clearance.minSurfaceDistance,
        clearance.sampleGrid,
      );
      if (deficit <= 0.002) break;
      const nextPush = Math.min(maximum, pushDistance + deficit + correctionMargin);
      if (nextPush <= pushDistance + 0.001) {
        saturated = true;
        break;
      }
      pushDistance = nextPush;
      if (pushDistance >= maximum - 0.001) saturated = true;
    }
    const nextState = {
      basePosition: basePosition.clone(),
      cameraPosition: cameraPosition.clone(),
      checkedAt: now,
      pushDistance,
      saturated,
      sceneChanging,
    };
    panel.userData.spatialClearanceState = nextState;
    if (cacheKey) {
      if (spatialTextClearanceCache.size >= 128 && !spatialTextClearanceCache.has(cacheKey)) {
        spatialTextClearanceCache.delete(spatialTextClearanceCache.keys().next().value);
      }
      spatialTextClearanceCache.set(cacheKey, nextState);
    }
  } else if (previous) {
    panel.userData.spatialClearanceState = previous;
  }
  panel.position.copy(basePosition).addScaledVector(direction, pushDistance);
  orientSpatialTextPanelForClearance(panel, cameraPosition, orientationPolicy);
  panel.userData.spatialClearanceStatus = saturated ? "maximum-push" : pushDistance > 0.002 ? "cleared" : "clear";
  panel.userData.spatialClearancePushDistance = pushDistance;
  return pushDistance;
}

function orientSpatialTextPanelForClearance(panel, cameraPosition, orientationPolicy) {
  const policy = String(orientationPolicy || "fixed");
  if (!panel || !cameraPosition || !["reader-facing-yaw", "reader-facing"].includes(policy)) return;
  const target = cameraPosition.clone();
  if (policy === "reader-facing-yaw") {
    panel.updateWorldMatrix(true, false);
    target.y = panel.getWorldPosition(new THREE.Vector3()).y;
  }
  panel.lookAt(target);
}

function spatialVisibleTextCollisionProxy(collisionRoot) {
  const proxy = [];
  collisionRoot.traverseVisible((object) => {
    if (!object.isMesh || !object.geometry) return;
    const deforming = object.isSkinnedMesh || (Array.isArray(object.morphTargetInfluences) && object.morphTargetInfluences.length > 0);
    let bounds = null;
    if (!deforming) {
      if (!object.geometry.boundingBox) object.geometry.computeBoundingBox();
      if (object.geometry.boundingBox) {
        bounds = spatialTextCollisionBoundsByMesh.get(object) || new THREE.Box3();
        bounds.copy(object.geometry.boundingBox).applyMatrix4(object.matrixWorld);
        spatialTextCollisionBoundsByMesh.set(object, bounds);
      }
    }
    proxy.push({ mesh: object, bounds });
  });
  return proxy;
}

function spatialPanelClearanceDeficit(panelMesh, collisionProxy, cameraPosition, minimumDistance, gridSize) {
  const width = Number(panelMesh.geometry?.parameters?.width) || 1.35;
  const height = Number(panelMesh.geometry?.parameters?.height) || 0.72;
  const grid = Math.max(2, Math.min(5, Math.round(Number(gridSize) || 3)));
  const raycaster = new THREE.Raycaster();
  const point = new THREE.Vector3();
  const direction = new THREE.Vector3();
  const candidateMeshes = [];
  const hits = [];
  let requiredPush = 0;
  for (let yIndex = 0; yIndex < grid; yIndex += 1) {
    for (let xIndex = 0; xIndex < grid; xIndex += 1) {
      point.set(
        (xIndex / (grid - 1) - 0.5) * width,
        (yIndex / (grid - 1) - 0.5) * height,
        0,
      );
      panelMesh.localToWorld(point);
      direction.copy(point).sub(cameraPosition);
      const panelDistance = direction.length();
      if (panelDistance <= 0.001) continue;
      direction.normalize();
      raycaster.set(cameraPosition, direction);
      raycaster.near = 0.001;
      raycaster.far = panelDistance + Math.max(5, minimumDistance * 4);
      candidateMeshes.length = 0;
      for (const entry of collisionProxy || []) {
        if (!entry.bounds || raycaster.ray.intersectsBox(entry.bounds)) candidateMeshes.push(entry.mesh);
      }
      if (!candidateMeshes.length) continue;
      hits.length = 0;
      raycaster.intersectObjects(candidateMeshes, false, hits);
      const hit = hits[0];
      if (!hit) continue;
      const surfaceGap = hit.distance - panelDistance;
      requiredPush = Math.max(requiredPush, minimumDistance - surfaceGap);
    }
  }
  return Math.max(0, requiredPush);
}

function applySpatialDraftToViewer(viewer) {
  if (!viewer?.spatialObjects) return;
  for (const entity of spatialRelationEntities(state.spatialRelationsDraft)) {
    const object = viewer.spatialObjects.get(entity.id);
    if (object) applySpatialEntityTransformToObject(viewer, entity, object);
  }
  updateSpatialAnchoredTextPanel(viewer);
}

function normalizeSpatialSelectionRectangle(startX, startY, endX, endY) {
  const left = Math.min(Number(startX) || 0, Number(endX) || 0);
  const top = Math.min(Number(startY) || 0, Number(endY) || 0);
  const right = Math.max(Number(startX) || 0, Number(endX) || 0);
  const bottom = Math.max(Number(startY) || 0, Number(endY) || 0);
  return {
    left,
    top,
    right,
    bottom,
    width: right - left,
    height: bottom - top,
  };
}

function spatialObjectIsEffectivelyVisible(object, scene) {
  for (let current = object; current; current = current.parent) {
    if (current.visible === false) return false;
    if (current === scene) return true;
  }
  return false;
}

function preciseVisibleSpatialBounds(object, scene) {
  const bounds = [];
  const point = new THREE.Vector3();
  const localBox = new THREE.Box3();
  const worldBox = new THREE.Box3();
  const instanceMatrix = new THREE.Matrix4();
  const worldMatrix = new THREE.Matrix4();
  if (!object) return bounds;
  object.updateWorldMatrix(true, true);
  object.traverse((renderable) => {
    if (!spatialObjectIsEffectivelyVisible(renderable, scene)) return;
    const geometry = renderable.geometry;
    const position = geometry?.getAttribute?.("position");
    if (!position) return;
    if (renderable.isInstancedMesh) {
      if (geometry.boundingBox === null) geometry.computeBoundingBox();
      if (!geometry.boundingBox) return;
      localBox.copy(geometry.boundingBox);
      for (let index = 0; index < renderable.count; index += 1) {
        renderable.getMatrixAt(index, instanceMatrix);
        worldMatrix.multiplyMatrices(renderable.matrixWorld, instanceMatrix);
        worldBox.copy(localBox).applyMatrix4(worldMatrix);
        bounds.push(worldBox.clone());
      }
      return;
    }
    const renderableBounds = new THREE.Box3();
    for (let index = 0; index < position.count; index += 1) {
      if (renderable.isMesh && typeof renderable.getVertexPosition === "function") {
        renderable.getVertexPosition(index, point);
      } else point.fromBufferAttribute(position, index);
      renderableBounds.expandByPoint(point.applyMatrix4(renderable.matrixWorld));
    }
    if (!renderableBounds.isEmpty()) bounds.push(renderableBounds);
  });
  return bounds;
}

function spatialSelectionFrustum(camera, viewportRect, selectionRectangle) {
  if (!camera || !viewportRect?.width || !viewportRect?.height || !selectionRectangle) return null;
  const left = (THREE.MathUtils.clamp(
    (selectionRectangle.left - viewportRect.left) / viewportRect.width,
    0,
    1,
  ) * 2) - 1;
  const right = (THREE.MathUtils.clamp(
    (selectionRectangle.right - viewportRect.left) / viewportRect.width,
    0,
    1,
  ) * 2) - 1;
  const top = 1 - (THREE.MathUtils.clamp(
    (selectionRectangle.top - viewportRect.top) / viewportRect.height,
    0,
    1,
  ) * 2);
  const bottom = 1 - (THREE.MathUtils.clamp(
    (selectionRectangle.bottom - viewportRect.top) / viewportRect.height,
    0,
    1,
  ) * 2);
  if (right - left <= 1e-9 || top - bottom <= 1e-9) return null;
  camera.updateWorldMatrix(true, false);
  const crop = new THREE.Matrix4().set(
    2 / (right - left), 0, 0, -(right + left) / (right - left),
    0, 2 / (top - bottom), 0, -(top + bottom) / (top - bottom),
    0, 0, 1, 0,
    0, 0, 0, 1,
  );
  const projectionView = new THREE.Matrix4().multiplyMatrices(
    camera.projectionMatrix,
    camera.matrixWorldInverse,
  );
  crop.multiply(projectionView);
  return new THREE.Frustum().setFromProjectionMatrix(crop, camera.coordinateSystem);
}

function spatialEntityIdsInSelectionRectangle(viewer, selectionRectangle) {
  const viewportRect = viewer?.renderer?.domElement?.getBoundingClientRect?.();
  const frustum = spatialSelectionFrustum(viewer?.camera, viewportRect, selectionRectangle);
  if (!viewer?.spatialObjects || !frustum) return [];
  return spatialEditorSceneEntities(state.spatialRelationsDraft, activeSpatialSceneContext())
    .filter((entity) => ["glb", "image-plane", "reader"].includes(spatialEntityType(entity)))
    .filter((entity) => {
      const object = viewer.spatialObjects.get(entity.id);
      if (!object || object.userData?.spatialPlaybackActive === false) return false;
      return preciseVisibleSpatialBounds(object, viewer.scene)
        .some((bounds) => frustum.intersectsBox(bounds));
    })
    .map((entity) => entity.id);
}

function spatialSelectionForRectangle(
  orderedEntityIds,
  selectedEntityIds,
  hitEntityIds,
  options = {},
) {
  const orderedIds = [...new Set((orderedEntityIds || []).filter(Boolean))];
  const selected = new Set((selectedEntityIds || []).filter((entityId) => orderedIds.includes(entityId)));
  const hits = [...new Set((hitEntityIds || []).filter((entityId) => orderedIds.includes(entityId)))];
  if (options.toggle === true) {
    for (const entityId of hits) {
      if (selected.has(entityId)) selected.delete(entityId);
      else selected.add(entityId);
    }
  } else if (options.additive === true) {
    for (const entityId of hits) selected.add(entityId);
  } else {
    selected.clear();
    for (const entityId of hits) selected.add(entityId);
  }
  if (!selected.size && hits.length) selected.add(hits[hits.length - 1]);
  return orderedIds.filter((entityId) => selected.has(entityId));
}

function updateSpatialSelectionMarquee(element, selectionRectangle, containerRect) {
  if (!element || !selectionRectangle || !containerRect) return;
  element.hidden = false;
  element.style.left = `${selectionRectangle.left - containerRect.left}px`;
  element.style.top = `${selectionRectangle.top - containerRect.top}px`;
  element.style.width = `${selectionRectangle.width}px`;
  element.style.height = `${selectionRectangle.height}px`;
}

function spatialTransformDragEventTime(event) {
  const eventTime = Number(event?.timeStamp);
  if (Number.isFinite(eventTime) && eventTime >= 0) return eventTime;
  const performanceTime = Number(globalThis.performance?.now?.());
  return Number.isFinite(performanceTime) ? performanceTime : Date.now();
}

function appendSpatialTransformDragPoint(drag, event) {
  if (!drag || drag.pointerId !== event?.pointerId) return false;
  const clientX = Number(event.clientX);
  const clientY = Number(event.clientY);
  if (!Number.isFinite(clientX) || !Number.isFinite(clientY)) return false;
  const startedAt = Number.isFinite(drag.startedAt)
    ? drag.startedAt
    : spatialTransformDragEventTime(event);
  const point = {
    clientX,
    clientY,
    elapsedMs: Math.max(0, spatialTransformDragEventTime(event) - startedAt),
  };
  if (!Array.isArray(drag.path)) drag.path = [];
  if (drag.path.length >= MAX_SPATIAL_TRANSFORM_DRAG_PATH_POINTS) {
    const compacted = [drag.path[0]];
    for (let index = 2; index < drag.path.length; index += 2) compacted.push(drag.path[index]);
    drag.path = compacted;
  }
  drag.path.push(point);
  return true;
}

function spatialTransformDragObjectSnapshot(entity) {
  if (!entity?.id) return null;
  return {
    entityId: String(entity.id),
    assetId: entity.assetId ? String(entity.assetId) : null,
    label: spatialRelationEntityLabel(entity) || String(entity.id),
    before: normalizeSpatialTransform(entity.transform, entity.inferredTransform),
  };
}

function finalizeSpatialTransformDrag(viewer, event, options = {}) {
  const drag = viewer?.spatialTransformDrag;
  if (!drag || drag.pointerId !== event?.pointerId) return false;
  appendSpatialTransformDragPoint(drag, event);
  viewer.spatialTransformDrag = null;
  const endedAt = spatialTransformDragEventTime(event);
  const startedAt = Number.isFinite(drag.startedAt) ? drag.startedAt : endedAt;
  const durationMs = Math.max(0, endedAt - startedAt);
  const objects = drag.objects.map((object) => {
    const entity = spatialRelationEntityById(state.spatialRelationsDraft, object.entityId);
    return {
      ...object,
      after: entity
        ? normalizeSpatialTransform(entity.transform, entity.inferredTransform)
        : normalizeSpatialTransform(object.before),
    };
  });
  const transformChanged = objects.some((object) => !spatialTransformsEqual(object.before, object.after));
  if (!drag.moved && !transformChanged) return false;
  const path = drag.path.map((point) => ({
    ...point,
    elapsedMs: Math.min(durationMs, point.elapsedMs),
  }));
  return interactionLogger.recordDrag(event, drag.semanticTarget, {
    durationMs,
    path,
    operation: drag.operation,
    axis: drag.axis,
    objects,
    ...(options.interrupted === true ? { interrupted: true } : {}),
  });
}

function spatialTransformDragInterruptionEvent(viewer, event = null) {
  const drag = viewer?.spatialTransformDrag;
  if (!drag) return null;
  if (event?.pointerId === drag.pointerId) return event;
  const lastPoint = Array.isArray(drag.path) ? drag.path[drag.path.length - 1] : null;
  return {
    type: "pointercancel",
    pointerId: drag.pointerId,
    clientX: Number.isFinite(lastPoint?.clientX) ? lastPoint.clientX : 0,
    clientY: Number.isFinite(lastPoint?.clientY) ? lastPoint.clientY : 0,
    button: 0,
    target: drag.eventTarget || viewer?.renderer?.domElement || null,
    timeStamp: spatialTransformDragEventTime(null),
  };
}

function finalizeInterruptedSpatialTransformDrag(viewer, event = null) {
  const drag = viewer?.spatialTransformDrag;
  if (!drag) return false;
  const interruptionEvent = spatialTransformDragInterruptionEvent(viewer, event);
  const transformControls = viewer?.transformControls;
  const domElement = transformControls?.domElement || viewer?.renderer?.domElement;
  if (transformControls?._onPointerMove && domElement?.removeEventListener) {
    domElement.removeEventListener("pointermove", transformControls._onPointerMove);
  }
  let controlError = null;
  try {
    if (transformControls?.dragging) {
      if (typeof transformControls.pointerUp === "function") transformControls.pointerUp(null);
      else transformControls.dispatchEvent?.({ type: "mouseUp" });
    }
  } catch (error) {
    controlError = error;
  } finally {
    if (transformControls) {
      transformControls.dragging = false;
      transformControls.axis = null;
    }
    if (viewer?.controls) viewer.controls.enabled = true;
  }
  const pointerId = drag.pointerId;
  let logged = false;
  try {
    logged = finalizeSpatialTransformDrag(viewer, interruptionEvent, { interrupted: true });
  } finally {
    if (domElement?.hasPointerCapture?.(pointerId)) domElement.releasePointerCapture?.(pointerId);
    if (viewer.selectionPointerGesture?.pointerId === pointerId) viewer.selectionPointerGesture = null;
  }
  if (controlError) throw controlError;
  return logged;
}

function syncSpatialSelectionHelpers(viewer, objects) {
  if (!viewer?.scene) return;
  for (const helper of viewer.selectionHelpers || []) {
    helper.removeFromParent();
    helper.geometry?.dispose?.();
    helper.material?.dispose?.();
  }
  viewer.selectionHelpers = [];
  for (const object of objects || []) {
    if (!object) continue;
    const helper = new THREE.BoxHelper(object, 0x007f73);
    helper.name = "StoryVR selected spatial object";
    helper.material.transparent = true;
    helper.material.opacity = 0.9;
    helper.material.depthTest = false;
    helper.material.depthWrite = false;
    helper.renderOrder = 1000;
    viewer.scene.add(helper);
    viewer.selectionHelpers.push(helper);
  }
}

function spatialSelectionObjects(viewer, entities = selectedSpatialRelationEntities()) {
  return entities.map((entity) => ({
    entity,
    object: viewer?.spatialObjects?.get(entity.id) || null,
  }));
}

function spatialSelectionWorldCenter(entries) {
  const bounds = new THREE.Box3();
  const fallbackCenter = new THREE.Vector3();
  let fallbackCount = 0;
  for (const { object } of entries || []) {
    if (!object) continue;
    object.updateWorldMatrix(true, true);
    const objectBounds = new THREE.Box3().setFromObject(object);
    if (!objectBounds.isEmpty()) bounds.union(objectBounds);
    fallbackCenter.add(object.getWorldPosition(new THREE.Vector3()));
    fallbackCount += 1;
  }
  if (!bounds.isEmpty()) return bounds.getCenter(new THREE.Vector3());
  return fallbackCount ? fallbackCenter.multiplyScalar(1 / fallbackCount) : new THREE.Vector3();
}

function syncSpatialTransformSelectionGroup(viewer, entries) {
  if (!viewer?.scene || !entries?.length) return null;
  if (!viewer.transformSelectionGroup) {
    const group = new THREE.Group();
    group.name = "StoryVR multi-selection transform center";
    group.userData.spatialSelectionGroup = true;
    viewer.scene.add(group);
    viewer.transformSelectionGroup = group;
  }
  const group = viewer.transformSelectionGroup;
  const worldCenter = spatialSelectionWorldCenter(entries);
  group.position.copy(viewer.scene.worldToLocal(worldCenter.clone()));
  group.quaternion.identity();
  group.scale.set(1, 1, 1);
  group.updateWorldMatrix(true, false);
  return group;
}

function captureSpatialSelectionTransformStart(viewer) {
  const entities = selectedSpatialRelationEntities();
  const entries = spatialSelectionObjects(viewer, entities)
    .filter(({ entity, object }) => spatialEntityTransformEditable(entity) && object?.parent)
    .map(({ entity, object }) => {
      object.parent.updateWorldMatrix(true, false);
      object.updateWorldMatrix(true, false);
      return {
        entityId: entity.id,
        object,
        worldMatrix: object.matrixWorld.clone(),
        parentWorldInverse: object.parent.matrixWorld.clone().invert(),
      };
    });
  const group = viewer?.transformSelectionGroup;
  if (entries.length < 2 || !group) return null;
  group.updateWorldMatrix(true, false);
  return {
    pivotMatrix: group.matrixWorld.clone(),
    entries,
  };
}

function applySpatialSelectionTransformFromGizmo(viewer) {
  const start = viewer?.transformSelectionStart;
  const group = viewer?.transformSelectionGroup;
  if (!start?.entries?.length || !group) return false;
  group.updateWorldMatrix(true, false);
  const deltaMatrix = group.matrixWorld.clone().multiply(start.pivotMatrix.clone().invert());
  for (const entry of start.entries) {
    const localMatrix = entry.parentWorldInverse.clone()
      .multiply(deltaMatrix)
      .multiply(entry.worldMatrix);
    localMatrix.decompose(entry.object.position, entry.object.quaternion, entry.object.scale);
    entry.object.updateMatrix();
    entry.object.updateWorldMatrix(true, true);
    persistSpatialObjectTransform(viewer, entry.object);
  }
  return true;
}

function syncSpatialSelectionInViewer() {
  const entities = selectedSpatialRelationEntities();
  const selectedIds = new Set(entities.map((entity) => entity.id));
  const primaryEntity = selectedSpatialRelationEntity();
  const includesReader = entities.some((entity) => spatialEntityType(entity) === "reader");
  if (includesReader && state.spatialTransformMode === "scale") {
    state.spatialTransformMode = "translate";
    textViewer?.transformControls?.setMode("translate");
  }
  const entries = spatialSelectionObjects(textViewer, entities);
  const loadedObjects = entries.map(({ object }) => object).filter(Boolean);
  const canTransform = entities.length === loadedObjects.length
    && spatialSelectionCanTransform(state.spatialTransformMode);
  if (textViewer?.transformControls) {
    textViewer.transformControls.enabled = canTransform;
    if (!canTransform) textViewer.transformControls.detach();
    else if (entities.length === 1) textViewer.transformControls.attach(loadedObjects[0]);
    else {
      const group = syncSpatialTransformSelectionGroup(textViewer, entries);
      if (group) textViewer.transformControls.attach(group);
      else textViewer.transformControls.detach();
    }
  }
  syncSpatialSelectionHelpers(textViewer, loadedObjects);
  for (const item of document.querySelectorAll("[data-spatial-select-entity]")) {
    const selected = selectedIds.has(item.dataset.spatialSelectEntity);
    item.classList.toggle("selected", selected);
    item.classList.toggle("selection-primary", item.dataset.spatialSelectEntity === state.selectedSpatialEntityId);
    item.setAttribute("aria-pressed", String(selected));
  }
  const title = document.querySelector(".spatial-preview-card .topology-kind-pill");
  if (title) title.textContent = spatialSelectionLabel(entities);
  syncSpatialToolbarState();
  syncSpatialInspectorFromSelection();
}

function selectSpatialRelationEntityInViewer(entityId, options = {}) {
  const entity = spatialRelationEntityById(state.spatialRelationsDraft, entityId);
  if (!entity) return;
  const orderedEntityIds = spatialEditorSceneEntities(
    state.spatialRelationsDraft,
    activeSpatialSceneContext(),
  ).map((candidate) => candidate.id);
  const entityIds = spatialSelectionForRectangle(
    orderedEntityIds,
    selectedSpatialRelationEntityIds(),
    [entityId],
    options,
  );
  const primaryEntityId = entityIds.includes(entityId)
    ? entityId
    : entityIds[entityIds.length - 1] || null;
  setSpatialRelationSelection(entityIds, {
    primaryEntityId,
    anchorEntityId: primaryEntityId,
  });
}

function clearSpatialRelationSelection() {
  setSpatialRelationSelection([], {
    primaryEntityId: null,
    anchorEntityId: null,
    explicitClear: true,
  });
}

function syncSpatialInspectorFromSelection() {
  const entity = selectedSpatialRelationEntity();
  const inspector = document.querySelector(".spatial-inspector");
  const inspectorHasSelection = Boolean(inspector?.querySelector("[data-spatial-inspector-title]"));
  if (inspector && inspectorHasSelection !== Boolean(entity)) {
    inspector.outerHTML = renderSpatialRelationsInspector(entity);
    bindSpatialInspectorEvents();
  }
  if (!entity) return;
  const selectedEntities = selectedSpatialRelationEntities();
  const multipleSelected = selectedEntities.length > 1;
  const transform = multipleSelected
    ? spatialSelectionTransformSummary(selectedEntities)
    : normalizeSpatialTransform(entity.transform, entity.inferredTransform);
  const transformBlocked = selectedEntities.some((selected) => !spatialEntityTransformEditable(selected));
  const values = { position: transform.position, rotation: spatialEulerDegrees(transform.quaternion), scale: transform.scale };
  for (const input of document.querySelectorAll("[data-spatial-transform-field]")) {
    const [group, indexText] = input.dataset.spatialTransformField.split(".");
    input.value = formatSpatialNumber(values[group]?.[Number(indexText)] ?? 0);
    input.disabled = transformBlocked;
  }
  const badge = document.querySelector(".spatial-inspector-head .text-comfort-badge");
  if (badge) {
    const selectionChanged = selectedEntities.some((selected) => selected.manual);
    badge.textContent = multipleSelected
      ? `${selectedEntities.length} selected`
      : entity.manual
        ? "manual"
        : "inferred";
    badge.classList.toggle("warning", selectionChanged);
    badge.classList.toggle("good", !selectionChanged);
  }
  const title = document.querySelector("[data-spatial-inspector-title]");
  if (title) title.textContent = spatialSelectionLabel(selectedEntities);
  const scope = document.querySelector("[data-spatial-inspector-scope]");
  if (scope) scope.textContent = "Transform";
  const isReader = selectedEntities.some((selected) => spatialEntityType(selected) === "reader");
  const scaleSection = document.querySelector("[data-spatial-scale-section]");
  if (scaleSection) scaleSection.hidden = isReader;
  const ratio = document.querySelector("[data-spatial-ratio-lock]");
  if (ratio) ratio.disabled = transformBlocked || isReader;
  const multiNote = document.querySelector("[data-spatial-multi-selection-note]");
  if (multiNote) multiNote.hidden = !multipleSelected;
  const reset = document.querySelector("[data-spatial-reset-selected]");
  if (reset) {
    reset.disabled = transformBlocked;
    reset.textContent = multipleSelected
      ? `Reset ${selectedEntities.length} selected objects`
      : "Reset to suggested placement";
  }
  for (const item of document.querySelectorAll("[data-spatial-select-entity]")) {
    const itemEntity = spatialRelationEntityById(
      state.spatialRelationsDraft,
      item.dataset.spatialSelectEntity,
    );
    if (!itemEntity) continue;
    const status = item.querySelector("em");
    if (status) {
      status.textContent = itemEntity.manual
        ? "edited"
        : "inferred";
      status.classList.toggle("inferred", !itemEntity.manual);
    }
  }
}

function setSpatialTransformMode(mode) {
  if (textViewer?.locked) return;
  if (!["translate", "rotate", "scale"].includes(mode)) return;
  if (!spatialSelectionCanTransform(mode)) return;
  state.spatialTransformMode = mode;
  textViewer?.transformControls?.setMode(mode);
  syncSpatialSelectionInViewer();
  syncSpatialToolbarState();
}

function syncSpatialToolbarState() {
  const selectedEntities = selectedSpatialRelationEntities();
  const readerSelected = selectedEntities.some((selected) => spatialEntityType(selected) === "reader");
  const transformBlocked = selectedEntities.some((selected) => !spatialEntityTransformEditable(selected));
  for (const button of document.querySelectorAll("[data-spatial-transform-mode]")) {
    const mode = button.dataset.spatialTransformMode;
    button.classList.toggle("selected", button.dataset.spatialTransformMode === state.spatialTransformMode);
    button.disabled = !selectedEntities.length || transformBlocked || (mode === "scale" && readerSelected);
    button.title = transformBlocked
      ? "This selection cannot be transformed"
      : mode === "scale" && readerSelected
        ? "Reader scale is fixed"
        : selectedEntities.length ? "" : "Select an object";
  }
  syncSpatialClipboardControls();
  syncSpatialPropagationControls();
}

function fitSpatialEditorCameraOnLoad(viewer) {
  if (!viewer || viewer.disposed) return false;
  const bounds = new THREE.Box3();
  for (const object of viewer.spatialObjects?.values?.() || []) {
    if (object.userData?.spatialPlaybackActive === false) continue;
    object.updateWorldMatrix(true, true);
    bounds.expandByObject(object);
  }
  if (viewer.readerProxy) {
    viewer.readerProxy.updateWorldMatrix(true, true);
    bounds.expandByObject(viewer.readerProxy);
  }
  if (bounds.isEmpty()) return false;

  const sphere = bounds.getBoundingSphere(new THREE.Sphere());
  const radius = Math.max(sphere.radius, 0.65);
  const verticalFov = THREE.MathUtils.degToRad(viewer.camera.fov);
  const horizontalFov = 2 * Math.atan(Math.tan(verticalFov * 0.5) * Math.max(viewer.camera.aspect, 0.1));
  const limitingFov = Math.max(THREE.MathUtils.degToRad(12), Math.min(verticalFov, horizontalFov));
  const distance = Math.max(1.8, (radius / Math.sin(limitingFov * 0.5)) * 1.42);
  const readerPosition = viewer.readerRig?.getWorldPosition(new THREE.Vector3()) || sphere.center.clone();
  const readerQuaternion = viewer.readerRig?.getWorldQuaternion(new THREE.Quaternion()) || new THREE.Quaternion();
  const readerBack = new THREE.Vector3(0, 0, 1).applyQuaternion(readerQuaternion);
  readerBack.y = 0;
  readerBack.normalize();
  const readerRight = new THREE.Vector3(1, 0, 0).applyQuaternion(readerQuaternion);
  readerRight.y = 0;
  readerRight.normalize();
  const direction = readerPosition.clone().sub(sphere.center);
  direction.y = 0;
  if (direction.lengthSq() < Math.max(radius * radius * 0.0025, 0.0025)) direction.copy(readerBack);
  else direction.normalize();
  direction
    .multiplyScalar(0.82)
    .addScaledVector(readerBack, 0.18)
    .addScaledVector(readerRight, 0.28)
    .addScaledVector(new THREE.Vector3(0, 1, 0), 0.16)
    .normalize();

  viewer.controls.target.copy(sphere.center);
  viewer.camera.position.copy(sphere.center).addScaledVector(direction, distance);
  viewer.camera.near = Math.max(radius / 250, 0.01);
  viewer.camera.far = Math.max(distance + radius * 12, 100);
  viewer.controls.minDistance = Math.max(radius * 0.08, 0.05);
  viewer.controls.maxDistance = Math.max(distance * 5, 20);
  viewer.camera.updateProjectionMatrix();
  viewer.camera.lookAt(sphere.center);
  viewer.controls.update();
  return true;
}

function initializeTextComfortViewer(active) {
  if (active?.id !== "text-comfort") return;
  const container = document.querySelector("[data-text-viewer]");
  if (!container) return;

  const component = componentById("text-comfort");
  const proposal = selectedTopologyProposal(component, state.data.proposals[component.id], state.data.decisions[component.id]);
  if (!proposal) return;

  const kind = inferTextComfortKind(proposal);
  const layers = cumulativePreviewLayersForComponent("text-comfort", { textKind: kind });
  const layoutKind = layers.topologyKind;
  const dynamicKind = layers.dynamicKind;
  const contextKind = layers.contextKind;
  const transitionKind = layers.transitionKind;
  const beats = textComfortPreviewBeats(proposal);
  const beatIndex = clampTextBeatIndex(beats);
  const beat = beats[beatIndex];
  const cumulativeContext = cumulativeSingleAnchorContext(beats, beatIndex);
  const assetLinks = cumulativeContext ? cumulativeContext.sequence.steps : textSceneAssetLinks(proposal, beats);
  const draft = ensureTextPlacementDraft(proposal, beat);
  const placement = effectiveTextPlacementForBeat(draft, beat, kind);
  const width = Math.max(container.clientWidth, 360);
  const height = Math.max(container.clientHeight, 520);
  const scene = new THREE.Scene();
  scene.background = new THREE.Color(0xf8f7ec);

  const camera = new THREE.PerspectiveCamera(42, width / height, 0.02, 1000);
  camera.position.set(3.4, 2.3, 4.8);

  const renderer = new THREE.WebGLRenderer({ antialias: true, alpha: true });
  renderer.setPixelRatio(Math.min(window.devicePixelRatio || 1, 2));
  renderer.setSize(width, height);
  renderer.outputColorSpace = THREE.SRGBColorSpace;
  renderer.domElement.tabIndex = 0;
  renderer.domElement.className = "topology-viewer-canvas text-viewer-canvas";

  const status = document.createElement("div");
  status.className = "topology-viewer-status overlay";
  status.textContent = assetLinks.length ? `Loading ${assetLinks.length} scene assets...` : "No linked assets; showing text panel in a neutral reading zone.";
  container.replaceChildren(renderer.domElement, status);

  const controls = new OrbitControls(camera, renderer.domElement);
  controls.enableDamping = true;
  controls.dampingFactor = 0.08;
  controls.target.set(0, 0.85, 0);
  configureSpatialEditorMouseControls(controls);

  scene.add(new THREE.HemisphereLight(0xffffff, 0x6f7f78, 2.4));
  const keyLight = new THREE.DirectionalLight(0xffffff, 3.1);
  keyLight.position.set(4, 7, 5);
  scene.add(keyLight);
  const fillLight = new THREE.DirectionalLight(0xbcece4, 1.25);
  fillLight.position.set(-4, 3, -4);
  scene.add(fillLight);

  const root = new THREE.Group();
  scene.add(root);
  addTextComfortStage(root, kind, layers);

  const assetPositions = new Map();
  assetLinks.forEach((assetLink, index) => {
    const position = cumulativeContext
      ? dynamicAssetPosition3d(index, Math.max(assetLinks.length, 1), layoutKind, index === cumulativeContext.activeIndex)
      : textAssetPosition3d(index, Math.max(assetLinks.length, 1), layoutKind);
    assetPositions.set(assetLink.assetId, position);
  });
  const activeAssetId = cumulativeContext?.active?.assetId
    || beat?.linkedAssetIds?.find((assetId) => assetPositions.has(assetId))
    || beat?.linkedAssetIds?.[0]
    || null;
  const activeModelPosition = cumulativeContext
    ? new THREE.Vector3(0, 0, 0)
    : activeAssetId && assetPositions.has(activeAssetId)
    ? assetPositions.get(activeAssetId).clone()
    : new THREE.Vector3(0, 0, 0);
  const activeAnchorPosition = cumulativeContext
    ? new THREE.Vector3(0, 0.56, 0)
    : activeAssetId && assetPositions.has(activeAssetId)
    ? assetPositions.get(activeAssetId).clone().add(new THREE.Vector3(0, 0.56, 0))
    : new THREE.Vector3(0, 0.9, 0);
  const activeAssetLink = cumulativeContext?.active || assetLinks.find((assetLink) => assetLink.assetId === activeAssetId);
  const metadataOverlay = addPreviewMetadataOverlay(container, previewMetadataEntries({
    componentId: "text-comfort",
    layers,
    activeLink: activeAssetLink,
    currentValue: textComfortKindLabel(kind),
    beat,
    additionalEntries: kind === "object-attached" ? [
      { id: "source-camera-focus", label: "Camera focus", value: sourceSpatialCueForBeat(beat?.id, activeAssetId) ? "Evaluating source cue..." : "No source camera cue" },
    ] : [],
  }));
  const panelPosition = textPlacementWorldPosition(placement, activeAnchorPosition);
  const panel = makeTextComfortPanel(beat, placement, kind);
  panel.position.copy(panelPosition);
  panel.rotation.set(placement.rotation.x, placement.rotation.y, placement.rotation.z);
  root.add(panel);

  const anchorMarker = makeTextAnchorMarker(activeAnchorPosition, activeAssetId ? "Active text anchor" : "Reader text zone");
  root.add(anchorMarker);
  const calloutLine = makeTextPanelCallout(activeAnchorPosition, panel.position);
  root.add(calloutLine);
  const descriptionCues = null;

  const viewer = {
    scene,
    camera,
    renderer,
    controls,
    root,
    panel,
    anchorMarker,
    calloutLine,
    activeAnchorPosition,
    activeAssetId,
    proposal,
    beat,
    kind,
    layers,
    layoutKind,
    topologyKind: layoutKind,
    geometryKind: dynamicKind,
    transitionKind,
    contextKind,
    componentId: "text-comfort",
    suppressSceneLabels: true,
    metadataOverlay,
    cumulativeContext,
    descriptionCues,
    activeSwapIndex: cumulativeContext?.activeIndex || 0,
    swapGroups: [],
    swapDuplicates: [],
    swapReady: false,
    duplicateCount: topologySwapDuplicateCount(state.data?.decisions?.["asset-topology"]?.option),
    placement,
    assetPositions,
    assetLinks,
    activeModelPosition,
    effects: dynamicKind ? addDynamicEffectOverlays(root, dynamicKind, activeModelPosition, {
      ...beat,
      title: `Geometry: ${dynamicGeometryKindLabel(dynamicKind)}`,
    }) : null,
    contextLayers: null,
    animationId: null,
    resizeHandler: null,
    keyDownHandler: null,
    keyUpHandler: null,
    pointerDownHandler: null,
    pointerMoveHandler: null,
    pointerUpHandler: null,
    disposed: false,
    focused: false,
    draggingPanel: false,
    keys: new Set(),
    lastFrameAt: performance.now(),
    elapsed: 0,
  };
  textViewer = viewer;
  attachLockedEnvironmentToViewer(viewer);
  const restoredCameraState = restoredPreviewCameraState(viewer, state.textViewerCameraState);
  const canRestoreCameraState = shouldRestorePreviewCameraState(viewer, restoredCameraState);
  if (canRestoreCameraState) applyPreviewViewerCameraState(viewer, restoredCameraState);

  let pendingAssets = assetLinks.length;
  const finishAsset = () => {
    pendingAssets -= 1;
    if (pendingAssets <= 0 && !viewer.disposed) {
      if (cumulativeContext) viewer.swapReady = true;
      if (cumulativeContext && !canRestoreCameraState) fitInheritedTopologyPreviewCamera(viewer, root);
      status.remove();
    }
  };
  if (!assetLinks.length) requestAnimationFrame(() => status.remove());
  assetLinks.forEach((assetLink, index) => {
    if (cumulativeContext) {
      loadTopologySwapAsset(viewer, assetLink, index, finishAsset);
    } else {
      loadTextComfortSceneAsset(root, assetLink, assetPositions.get(assetLink.assetId), viewer, finishAsset);
    }
  });

  const raycaster = new THREE.Raycaster();
  const pointer = new THREE.Vector2();
  const dragPlane = new THREE.Plane();
  const dragOffset = new THREE.Vector3();
  const dragPoint = new THREE.Vector3();

  const updatePointer = (event) => {
    const rect = renderer.domElement.getBoundingClientRect();
    pointer.x = ((event.clientX - rect.left) / rect.width) * 2 - 1;
    pointer.y = -((event.clientY - rect.top) / rect.height) * 2 + 1;
  };

  viewer.pointerDownHandler = (event) => {
    viewer.focused = true;
    container.classList.add("focused");
    renderer.domElement.focus();
    if (event.button !== 0) return;
    updatePointer(event);
    raycaster.setFromCamera(pointer, camera);
    const hits = viewer.panel ? raycaster.intersectObject(viewer.panel, true) : [];
    if (!hits.length) return;
    event.preventDefault();
    event.stopPropagation();
    viewer.draggingPanel = true;
    controls.enabled = false;
    const normal = new THREE.Vector3();
    camera.getWorldDirection(normal);
    dragPlane.setFromNormalAndCoplanarPoint(normal, viewer.panel.position);
    if (raycaster.ray.intersectPlane(dragPlane, dragPoint)) {
      dragOffset.copy(viewer.panel.position).sub(dragPoint);
    } else {
      dragOffset.set(0, 0, 0);
    }
    renderer.domElement.setPointerCapture?.(event.pointerId);
  };

  viewer.pointerMoveHandler = (event) => {
    if (!viewer.draggingPanel || viewer.disposed) return;
    updatePointer(event);
    raycaster.setFromCamera(pointer, camera);
    if (!raycaster.ray.intersectPlane(dragPlane, dragPoint)) return;
    if (!viewer.panel) return;
    viewer.panel.position.copy(dragPoint.add(dragOffset));
    if (viewer.calloutLine) updateTextPanelCallout(viewer.calloutLine, viewer.activeAnchorPosition, viewer.panel.position);
    persistDraggedTextPanelPosition(viewer);
  };

  viewer.pointerUpHandler = (event) => {
    if (!viewer.draggingPanel) return;
    viewer.draggingPanel = false;
    controls.enabled = true;
    renderer.domElement.releasePointerCapture?.(event.pointerId);
  };

  renderer.domElement.addEventListener("pointerdown", viewer.pointerDownHandler);
  window.addEventListener("pointermove", viewer.pointerMoveHandler);
  window.addEventListener("pointerup", viewer.pointerUpHandler);
  renderer.domElement.addEventListener("blur", () => {
    viewer.focused = false;
    viewer.keys.clear();
    container.classList.remove("focused");
  });

  viewer.keyDownHandler = (event) => {
    if (!viewer.focused || !["w", "a", "s", "d"].includes(event.key.toLowerCase())) return;
    event.preventDefault();
    viewer.keys.add(event.key.toLowerCase());
  };
  viewer.keyUpHandler = (event) => {
    viewer.keys.delete(event.key.toLowerCase());
  };
  window.addEventListener("keydown", viewer.keyDownHandler);
  window.addEventListener("keyup", viewer.keyUpHandler);

  viewer.resizeHandler = () => {
    if (viewer.disposed) return;
    const nextWidth = Math.max(container.clientWidth, 360);
    const nextHeight = Math.max(container.clientHeight, 520);
    camera.aspect = nextWidth / nextHeight;
    camera.updateProjectionMatrix();
    renderer.setSize(nextWidth, nextHeight);
  };
  window.addEventListener("resize", viewer.resizeHandler);

  const animate = (now) => {
    if (viewer.disposed) return;
    const delta = Math.min((now - viewer.lastFrameAt) / 1000, 0.05);
    viewer.lastFrameAt = now;
    viewer.elapsed += delta;
    moveTextViewerCamera(viewer, delta);
    if (animateNarrativeSingleAnchorViewer(viewer, delta)) return;
    animateTextComfortViewer(viewer);
    if (viewer.placement?.facesReader || viewer.kind === "reader-facing" || viewer.kind === "near-body" || viewer.kind === "object-attached") {
      viewer.panel?.lookAt(camera.position);
    }
    if (viewer.calloutLine && viewer.panel) updateTextPanelCallout(viewer.calloutLine, viewer.activeAnchorPosition, viewer.panel.position);
    controls.update();
    renderer.render(scene, camera);
    viewer.animationId = requestAnimationFrame(animate);
  };
  viewer.animationId = requestAnimationFrame(animate);
}

function addTextComfortStage(root, kind, layers = null) {
  const reader = new THREE.Group();
  const body = new THREE.Mesh(
    new THREE.CapsuleGeometry(0.12, 0.48, 8, 16),
    new THREE.MeshStandardMaterial({ color: 0x007f73, roughness: 0.75 }),
  );
  body.position.set(0, 0.72, 1.05);
  reader.add(body);
  const head = new THREE.Mesh(
    new THREE.SphereGeometry(0.14, 24, 16),
    new THREE.MeshStandardMaterial({ color: 0x0f211d, roughness: 0.8 }),
  );
  head.position.set(0, 1.16, 1.05);
  reader.add(head);
  root.add(reader);
}

function loadTextComfortSceneAsset(root, assetLink, position, viewer, done, options = {}) {
  const asset = findAssetById(assetLink.assetId);
  const topologyWrapper = new THREE.Group();
  topologyWrapper.name = `StoryVR topology anchor · ${assetLink.assetId}`;
  topologyWrapper.position.copy(position || new THREE.Vector3());
  const authorWrapper = new THREE.Group();
  authorWrapper.name = `StoryVR author transform · ${assetLink.assetId}`;
  authorWrapper.userData.assetId = assetLink.assetId;
  const wrapper = new THREE.Group();
  wrapper.userData.assetId = assetLink.assetId;
  const isDirectManipulationTarget = viewer?.kind === "direct" && viewer?.activeAssetId === assetLink.assetId;
  if (isDirectManipulationTarget) {
    const offset = state.interactionManipulationOffset || { x: 0, y: 0, z: 0 };
    wrapper.position.add(new THREE.Vector3(offset.x || 0, offset.y || 0, offset.z || 0));
    wrapper.userData.interactionDraggable = true;
    wrapper.userData.directManipulationAsset = true;
    viewer.draggableTargets.push(wrapper);
    viewer.manipulationProxy = wrapper;
    viewer.manipulationBasePosition = new THREE.Vector3();
    if (!viewer.spatialReaderHands) addInteractionReaderHandsRig(viewer, wrapper);
  }
  topologyWrapper.add(authorWrapper);
  authorWrapper.add(wrapper);
  root.add(topologyWrapper);
  applyLockedSpatialGlbTransform(viewer, assetLink.assetId, authorWrapper);
  const placeholder = viewer?.suppressSceneLabels
    ? null
    : makeTextComfortPlaceholder(asset?.filename || assetLink.assetId || "asset", asset?.type || "asset");
  if (placeholder) wrapper.add(placeholder);
  if (!asset) {
    done();
    return;
  }
  const modelSrc = assetLoadSrc(asset);
  if (isModelAsset(asset) && modelSrc) {
    createGltfLoader().load(
      modelSrc,
      (gltf) => {
        if (viewer.disposed) {
          disposeObject(gltf.scene);
          return;
        }
        if (placeholder) {
          wrapper.remove(placeholder);
          disposeObject(placeholder);
        }
        const targetSize = Number(options.targetSize);
        if (options.centerModel && Number.isFinite(targetSize) && targetSize > 0) {
          normalizeSpatialRuntimeObject(gltf.scene, targetSize);
        } else {
          normalizeTopologyObject(gltf.scene, 0.76);
        }
        wrapper.add(gltf.scene);
        const entry = { group: wrapper, modelRoot: wrapper, authorWrapper, sourceScene: gltf.scene, assetId: assetLink.assetId };
        applySourceSpatialCueToTextViewer(viewer, entry, gltf);
        applySourceSpatialCuesToInteractionViewer(viewer, entry, gltf);
        if (viewer?.componentId === "interaction-control") attachInteractionUpstreamPlayback(viewer, entry, gltf);
        done();
      },
      undefined,
      () => done(),
    );
    return;
  }
  const imageSrc = assetPreviewSrc(asset);
  if (imageSrc) {
    new THREE.TextureLoader().load(
      imageSrc,
      (texture) => {
        if (viewer.disposed) {
          texture.dispose();
          return;
        }
        texture.colorSpace = THREE.SRGBColorSpace;
        if (placeholder) {
          wrapper.remove(placeholder);
          disposeObject(placeholder);
        }
        wrapper.add(makeTextComfortImagePlane(texture));
        done();
      },
      undefined,
      () => done(),
    );
    return;
  }
  done();
}

function makeTextComfortPlaceholder(label, type) {
  const group = new THREE.Group();
  group.visible = false;
  group.userData.storyvrArtificialSpatialTextPanel = true;
  const card = new THREE.Mesh(
    new THREE.BoxGeometry(0.72, 0.5, 0.08),
    new THREE.MeshStandardMaterial({ color: 0xf3ead8, roughness: 0.8, metalness: 0.02 }),
  );
  card.position.y = 0.3;
  group.add(card);
  const sprite = makeTextSprite(`${String(type || "asset").toUpperCase()}\n${shortText(label, 18)}`, {
    fontSize: 46,
    background: "rgba(255,253,244,0.96)",
    color: "#0f211d",
    padding: 16,
  });
  sprite.position.set(0, 0.32, 0.08);
  sprite.scale.set(0.62, 0.28, 1);
  group.add(sprite);
  group.traverse((object) => {
    object.raycast = () => {};
  });
  return group;
}

function makeTextComfortImagePlane(texture) {
  const aspect = texture.image?.width && texture.image?.height ? texture.image.width / texture.image.height : 1.3;
  const width = Math.min(0.88, Math.max(0.58, aspect * 0.46));
  const height = width / Math.max(aspect, 0.1);
  const plane = new THREE.Mesh(
    new THREE.PlaneGeometry(width, height),
    new THREE.MeshBasicMaterial({ map: texture, transparent: true, side: THREE.DoubleSide }),
  );
  plane.position.y = 0.42;
  return plane;
}

function makeTextComfortPanel(beat, placement, kind) {
  const texture = makeTextPanelTexture(beat, placement, kind);
  const panel = new THREE.Group();
  panel.userData.textPanel = true;
  const material = new THREE.MeshBasicMaterial({ map: texture, transparent: true, side: THREE.DoubleSide });
  const mesh = new THREE.Mesh(new THREE.PlaneGeometry(placement.width, placement.height), material);
  mesh.userData.textPanel = true;
  panel.add(mesh);
  const handle = new THREE.Mesh(
    new THREE.BoxGeometry(placement.width * 0.42, 0.045, 0.035),
    new THREE.MeshStandardMaterial({ color: 0x007f73, roughness: 0.6 }),
  );
  handle.position.set(0, placement.height / 2 + 0.055, 0.016);
  handle.userData.textPanel = true;
  panel.add(handle);
  panel.scale.setScalar(placement.scale);
  return panel;
}

function makeTextPanelTexture(beat, placement, kind) {
  const canvas = document.createElement("canvas");
  canvas.width = 1200;
  canvas.height = 680;
  const ctx = canvas.getContext("2d");
  ctx.clearRect(0, 0, canvas.width, canvas.height);
  const gradient = ctx.createLinearGradient(0, 0, canvas.width, canvas.height);
  gradient.addColorStop(0, "#fffdf4");
  gradient.addColorStop(1, kind === "near-body" ? "#e6f8ef" : "#f8edda");
  ctx.fillStyle = gradient;
  ctx.strokeStyle = "#98c8bd";
  ctx.lineWidth = 8;
  ctx.beginPath();
  ctx.roundRect(28, 28, canvas.width - 56, canvas.height - 56, 44);
  ctx.fill();
  ctx.stroke();
  ctx.fillStyle = "#0f211d";
  ctx.font = "900 54px Georgia, serif";
  drawWrappedCanvasText(ctx, beat?.title || "Story part", 72, 108, canvas.width - 144, 62, 2);
  ctx.fillStyle = "#344943";
  ctx.font = "500 42px Georgia, serif";
  drawWrappedCanvasText(ctx, beat?.text || "No story text available for this story part.", 72, 252, canvas.width - 144, 54, 6);
  const texture = new THREE.CanvasTexture(canvas);
  texture.colorSpace = THREE.SRGBColorSpace;
  texture.anisotropy = 4;
  return texture;
}

function drawWrappedCanvasText(ctx, text, x, y, maxWidth, lineHeight, maxLines) {
  const lines = canvasWrappedTextLines(ctx, text, maxWidth);
  const visibleLines = lines.slice(0, maxLines);
  if (lines.length > maxLines && visibleLines.length) {
    const lastIndex = visibleLines.length - 1;
    visibleLines[lastIndex] = canvasEllipsizedText(ctx, `${visibleLines[lastIndex]}…`, maxWidth);
  }
  visibleLines.forEach((line, index) => {
    ctx.fillText(line, x, y + (index * lineHeight), maxWidth);
  });
}

function makeTextAnchorMarker(position, labelText) {
  const group = new THREE.Group();
  group.position.copy(position);
  const marker = new THREE.Mesh(
    new THREE.SphereGeometry(0.08, 24, 16),
    new THREE.MeshStandardMaterial({ color: 0xc75f1f, emissive: 0x602300, emissiveIntensity: 0.12 }),
  );
  group.add(marker);
  return group;
}

function makeTextPanelCallout(from, to) {
  const geometry = new THREE.BufferGeometry().setFromPoints([from, to]);
  const line = new THREE.Line(
    geometry,
    new THREE.LineBasicMaterial({ color: 0xc75f1f, transparent: true, opacity: 0.72 }),
  );
  return line;
}

function updateTextPanelCallout(line, from, to) {
  const points = [from, to];
  line.geometry.setFromPoints(points);
  line.geometry.attributes.position.needsUpdate = true;
}

function textAssetPosition3d(index, total, layoutKind = null) {
  if (layoutKind) return dynamicAssetPosition3d(index, total, layoutKind, false);
  if (total <= 1) return new THREE.Vector3(0, 0, 0);
  const angle = (index / total) * Math.PI * 2 - Math.PI / 2;
  const radius = Math.min(2.4, Math.max(1.2, total * 0.16 + 1.15));
  return new THREE.Vector3(Math.cos(angle) * radius, 0, Math.sin(angle) * radius * 0.72);
}

function textPlacementWorldPosition(placement, activeAnchorPosition) {
  const position = new THREE.Vector3(placement.position.x, placement.position.y, placement.position.z);
  if (placement.coordinateSpace === "asset" || placement.coordinateSpace === "source-focus") return activeAnchorPosition.clone().add(position);
  if (placement.coordinateSpace === "reader") return new THREE.Vector3(position.x, position.y, 1.05 + position.z);
  return position;
}

function persistDraggedTextPanelPosition(viewer) {
  if (!viewer?.beat?.id) return;
  const draft = ensureTextPlacementDraft(viewer.proposal, viewer.beat);
  const current = effectiveTextPlacementForBeat(draft, viewer.beat, viewer.kind);
  const localPosition = viewer.panel.position.clone();
  if (current.coordinateSpace === "asset" || current.coordinateSpace === "source-focus") localPosition.sub(viewer.activeAnchorPosition);
  if (current.coordinateSpace === "reader") localPosition.z -= 1.05;
  draft.overridesByBeat[viewer.beat.id] = sanitizeTextPlacementEntry({
    ...current,
    position: { x: localPosition.x, y: localPosition.y, z: localPosition.z },
    rotation: { x: viewer.panel.rotation.x, y: viewer.panel.rotation.y, z: viewer.panel.rotation.z },
    anchorAssetId: ["asset", "source-focus"].includes(current.coordinateSpace) ? viewer.activeAssetId : current.anchorAssetId,
  }, current);
}

function moveTextViewerCamera(viewer, delta) {
  if (!viewer.focused || !viewer.keys.size || viewer.draggingPanel) return;
  const forward = new THREE.Vector3();
  viewer.camera.getWorldDirection(forward);
  forward.y = 0;
  forward.normalize();
  const right = new THREE.Vector3().crossVectors(forward, new THREE.Vector3(0, 1, 0)).normalize();
  const movement = new THREE.Vector3();
  if (viewer.keys.has("w")) movement.add(forward);
  if (viewer.keys.has("s")) movement.sub(forward);
  if (viewer.keys.has("d")) movement.add(right);
  if (viewer.keys.has("a")) movement.sub(right);
  if (!movement.lengthSq()) return;
  movement.normalize().multiplyScalar(delta * 2.1);
  viewer.camera.position.add(movement);
  viewer.controls.target.add(movement);
}

function contextLayerActivePosition(cumulativeContext, activeIndex, total, layoutKind) {
  if (cumulativeContext) return new THREE.Vector3(0, 0, 0);
  return dynamicAssetPosition3d(activeIndex, total, layoutKind, true);
}

function addContextStage(root, kind, beat, options = {}) {
  const stageOptions = typeof options === "string" ? { transitionKind: options } : options;
  if (stageOptions?.allowSyntheticGeometry !== true) return { beatLabel: null, beatLabelText: "" };
  const dynamicKind = stageOptions?.dynamicKind || null;
  const transitionKind = stageOptions?.transitionKind || null;
  const stage = { beatLabel: null, beatLabelText: "" };
  const floorRadius = kind === "nested" ? 3.7 : (kind === "environment" ? 3.25 : 2.25);
  if (kind !== "environment") {
    const floor = new THREE.Mesh(
      new THREE.CircleGeometry(floorRadius, 80),
      new THREE.MeshStandardMaterial({
        color: kind === "object" ? 0xfffbef : 0xf3efe1,
        roughness: 0.94,
        metalness: 0,
        side: THREE.DoubleSide,
      }),
    );
    floor.rotation.x = -Math.PI / 2;
    floor.position.y = -0.035;
    root.add(floor);

    const grid = new THREE.GridHelper(floorRadius * 2, kind === "object" ? 8 : 14, 0x7fbab2, 0xd3dfd7);
    grid.material.transparent = true;
    grid.material.opacity = kind === "object" ? 0.14 : 0.26;
    root.add(grid);
  }
  root.add(makeTextSprite(contextLayerKindLabel(kind), { y: 0.34, color: "#007f73", width: 1.55 }));
  if (stageOptions?.ids) {
    addCumulativeLayerLabels(root, stageOptions, "environment-enhancement", { limit: 4, startX: -2.35, spacing: 1.55, z: -2.06 });
  } else {
    addPriorDecisionLabel(root, "Geometry", dynamicKind ? dynamicGeometryKindLabel(dynamicKind) : "", { x: -1.84, z: -2.06, width: 1.58 });
    addPriorDecisionLabel(root, "Scene changes", transitionKind ? interBeatDynamicsKindLabel(transitionKind) : "", { x: 1.02, z: -2.06, width: 1.64 });
  }
  if (beat?.title) {
    stage.beatLabelText = shortText(beat.title, 34);
    stage.beatLabel = makeTextSprite(stage.beatLabelText, {
      y: 2.15,
      color: "#10201c",
      background: "rgba(255,253,244,0.9)",
      width: 1.75,
    });
    root.add(stage.beatLabel);
  }
  return stage;
}

function addFullEnvironmentContext(root, activeRegion, options = {}) {
  if (options.allowSyntheticGeometry !== true) {
    const emptyRoot = new THREE.Group();
    root.add(emptyRoot);
    return { root: emptyRoot, rings: [], zones: [], nested: [], labels: [] };
  }
  const regions = finalReviewRegionSpecs();
  const selectedRegion = activeRegion || regions[0];
  const activePosition = previewCueVector(options.activePosition || options.position);
  const regionOffset = selectedRegion?.position ? selectedRegion.position.clone().multiplyScalar(-1) : new THREE.Vector3();
  const floorRadius = options.floorRadius || 3.35;
  const hideGroundCircles = Boolean(options.hideGroundCircles);
  const environmentRoot = new THREE.Group();
  environmentRoot.position.copy(activePosition);
  root.add(environmentRoot);

  const effects = { root: environmentRoot, rings: [], zones: [], nested: [], labels: [] };
  const floorGeometry = hideGroundCircles
    ? new THREE.PlaneGeometry(floorRadius * 2, floorRadius * 2)
    : new THREE.CircleGeometry(floorRadius, 96);
  const floor = new THREE.Mesh(
    floorGeometry,
    new THREE.MeshStandardMaterial({
      color: 0xf3efe1,
      roughness: 0.95,
      metalness: 0,
      side: THREE.DoubleSide,
    }),
  );
  floor.rotation.x = -Math.PI / 2;
  floor.position.y = -0.06;
  if (!hideGroundCircles) markFinalTuningGroundCircle(floor);
  environmentRoot.add(floor);

  const grid = new THREE.GridHelper(floorRadius * 2, 14, 0x7fbab2, 0xd3dfd7);
  grid.material.transparent = true;
  grid.material.opacity = 0.24;
  grid.position.y = -0.015;
  environmentRoot.add(grid);

  if (!hideGroundCircles) {
    const roomRing = markFinalTuningGroundCircle(new THREE.Mesh(
      new THREE.RingGeometry(floorRadius * 0.88, floorRadius * 0.9, 96),
      new THREE.MeshBasicMaterial({ color: 0x007f73, transparent: true, opacity: 0.18, side: THREE.DoubleSide }),
    ));
    roomRing.rotation.x = -Math.PI / 2;
    roomRing.position.y = 0.025;
    environmentRoot.add(roomRing);
    effects.rings.push(roomRing);
  }

  const backWall = new THREE.Mesh(
    new THREE.BoxGeometry(floorRadius * 1.72, 1.12, 0.08),
    new THREE.MeshStandardMaterial({ color: 0xdfeee6, roughness: 0.88, transparent: true, opacity: 0.42 }),
  );
  backWall.position.set(0, 0.52, -floorRadius * 0.64);
  environmentRoot.add(backWall);

  const sideWall = new THREE.Mesh(
    new THREE.BoxGeometry(0.08, 0.92, floorRadius * 1.08),
    new THREE.MeshStandardMaterial({ color: 0xf0dfcf, roughness: 0.88, transparent: true, opacity: 0.32 }),
  );
  sideWall.position.set(-floorRadius * 0.62, 0.44, -floorRadius * 0.1);
  environmentRoot.add(sideWall);

  for (const region of regions) {
    const selected = region.kind === selectedRegion.kind;
    const marker = new THREE.Group();
    marker.position.copy(region.position).add(regionOffset);
    marker.userData.fullEnvironmentRegion = region.kind;
    environmentRoot.add(marker);

    const plane = new THREE.Mesh(
      new THREE.PlaneGeometry(selected ? 1.14 : 0.84, selected ? 0.72 : 0.5),
      new THREE.MeshBasicMaterial({
        color: selected ? region.color : 0x8fbfb7,
        transparent: true,
        opacity: selected ? 0.34 : 0.13,
        side: THREE.DoubleSide,
      }),
    );
    plane.rotation.x = -Math.PI / 2;
    marker.add(plane);

    if (!hideGroundCircles) {
      const ring = markFinalTuningGroundCircle(new THREE.Mesh(
        new THREE.RingGeometry(selected ? 0.64 : 0.42, selected ? 0.72 : 0.48, 56),
        new THREE.MeshBasicMaterial({
          color: selected ? 0xc75f1f : region.color,
          transparent: true,
          opacity: selected ? 0.46 : 0.2,
          side: THREE.DoubleSide,
        }),
      ));
      ring.rotation.x = -Math.PI / 2;
      ring.position.y = 0.025;
      marker.add(ring);
      effects.rings.push(ring);
    }

    const cueEffects = addMicrohabitatCueSet(marker, environmentRegionCueKind(region), new THREE.Vector3(0, 0.02, 0), {
      includeLabel: false,
      hideGroundCircles,
    });
    effects.rings.push(...cueEffects.rings);
    effects.zones.push(...cueEffects.zones);

    const label = makeTextSprite(region.label, {
      y: selected ? (options.labelY || 0.5) : 0.34,
      color: selected ? "#10201c" : "#5f716c",
      background: selected ? "rgba(255,244,222,0.94)" : "rgba(255,253,244,0.76)",
      width: selected ? 1.2 : 0.96,
      height: 0.22,
    });
    marker.add(label);
    effects.labels.push(label);
  }

  return effects;
}

function environmentRegionCueKind(region) {
  if (region?.kind === "air") return "droplets";
  if (region?.kind === "face") return "skin";
  if (region?.kind === "bed") return "crevice";
  if (region?.kind === "surface") return "contact";
  if (region?.kind === "dark") return "dark-corner";
  return "room";
}

function addContextLayerOverlays(root, kind, activePosition, beat, proposal = null) {
  const layerRoot = new THREE.Group();
  root.add(layerRoot);
  return { root: layerRoot, rings: [], zones: [], nested: [], labels: [] };
}

function animateContextLayering(viewer) {
  const time = viewer.elapsed;
  if (viewerDynamicGeometryKind(viewer)) {
    animateDynamicGeometry(viewer);
  } else {
    for (const item of viewer.dynamicObjects || []) {
      item.wrapper.position.copy(item.basePosition);
      item.wrapper.rotation.set(0, 0, 0);
      item.wrapper.scale.setScalar(item.spatialTransformApplied ? 1 : item.active ? item.baseScale : 0.9);
      if (item.active && !item.spatialTransformApplied) item.wrapper.position.y += Math.sin(time * 1.4) * 0.035;
    }
    animateDynamicEffectOverlays(viewer.effects, viewer.geometryKind, time);
  }
  animateContextLayerEffects(viewer, time);
}

function animateContextLayerEffects(viewer, time = viewer?.elapsed || 0) {
  viewer.contextLayers?.rings?.forEach((ring, index) => {
    const pulse = 1 + (Math.sin(time * 1.8 + index) * 0.5 + 0.5) * 0.18;
    ring.scale.setScalar(pulse);
  });
  viewer.contextLayers?.zones?.forEach((zone, index) => {
    if (zone.material) zone.material.opacity = 0.1 + (Math.sin(time * 0.8 + index) * 0.5 + 0.5) * 0.09;
  });
  viewer.contextLayers?.nested?.forEach((item, index) => {
    item.rotation.z += 0.003 + index * 0.001;
    const pulse = 1 + (Math.sin(time * 1.2 + index) * 0.5 + 0.5) * 0.08;
    item.scale.setScalar(pulse);
  });
}

function animateTextComfortViewer(viewer) {
  const time = viewer?.elapsed || 0;
  const geometryKind = viewerDynamicGeometryKind(viewer);
  if (geometryKind) animateDynamicEffectOverlays(viewer.effects, geometryKind, time);
  animateContextLayerEffects(viewer, time);
}

function addDynamicEffectOverlays(root, kind, activePosition, beat) {
  return null;
}

function addInterBeatTransitionOverlays(root, kind, fromPosition, toPosition, playback) {
  if (playback?.canScrub !== true || kind === "none") return null;
  const group = new THREE.Group();
  root.add(group);

  const from = fromPosition.clone();
  const to = toPosition.clone();
  const fromRaised = from.clone().add(new THREE.Vector3(0, 0.18, 0));
  const toRaised = to.clone().add(new THREE.Vector3(0, 0.18, 0));
  const midpoint = from.clone().lerp(to, 0.5);
  const effects = {
    group,
    line: null,
    marker: null,
    from,
    to,
    fromRaised,
    toRaised,
    midpoint,
    fromStop: null,
    toStop: null,
    wipe: null,
    flash: null,
    readerAvatar: null,
    passiveGhost: null,
    readerTarget: null,
    particles: null,
    rings: [],
    coincidentAnchors: from.distanceToSquared(to) < 0.000001,
  };

  // A single persistent source model changes state in place. Spatial endpoint
  // markers collapse onto that same anchor and only create decorative balls.
  if (effects.coincidentAnchors) return effects;

  const lineGeometry = new THREE.BufferGeometry().setFromPoints([fromRaised, toRaised]);
  const line = new THREE.Line(
    lineGeometry,
    new THREE.LineBasicMaterial({ color: 0xc75f1f, transparent: true, opacity: 0.62 }),
  );
  group.add(line);
  effects.line = line;

  const makeStop = (position, color) => {
    const stop = new THREE.Group();
    stop.position.copy(position);
    const ring = new THREE.Mesh(
      new THREE.RingGeometry(0.38, 0.44, 44),
      new THREE.MeshBasicMaterial({ color, transparent: true, opacity: 0.52, side: THREE.DoubleSide }),
    );
    ring.rotation.x = -Math.PI / 2;
    ring.position.y = 0.055;
    stop.add(ring);
    group.add(stop);
    return { stop, ring };
  };

  const fromStop = makeStop(from, 0x007f73);
  const toStop = makeStop(to, 0xc75f1f);
  effects.fromStop = fromStop;
  effects.toStop = toStop;
  const marker = new THREE.Mesh(
    new THREE.SphereGeometry(0.13, 32, 32),
    new THREE.MeshStandardMaterial({ color: 0xc75f1f, roughness: 0.34, emissive: 0x321104 }),
  );
  marker.position.copy(fromRaised);
  group.add(marker);
  effects.marker = marker;

  if (kind === "discrete-wipe") {
    const direction = to.clone().sub(from);
    const wipe = new THREE.Mesh(
      new THREE.BoxGeometry(0.09, 1.28, 1.05),
      new THREE.MeshBasicMaterial({ color: 0x007f73, transparent: true, opacity: 0.28, side: THREE.DoubleSide }),
    );
    wipe.position.copy(from.clone().add(new THREE.Vector3(0, 0.72, 0)));
    wipe.rotation.y = Math.atan2(direction.x, direction.z);
    group.add(wipe);
    effects.wipe = wipe;
  } else if (kind === "discrete-pop") {
    const flash = new THREE.Mesh(
      new THREE.SphereGeometry(0.34, 36, 20),
      new THREE.MeshBasicMaterial({ color: 0xfff0b5, transparent: true, opacity: 0.0 }),
    );
    flash.position.copy(midpoint.clone().add(new THREE.Vector3(0, 0.62, 0)));
    group.add(flash);
    effects.flash = flash;
  } else if (kind === "continuous-active") {
    const avatar = new THREE.Group();
    avatar.position.copy(fromRaised);
    const body = new THREE.Mesh(
      new THREE.CylinderGeometry(0.075, 0.095, 0.42, 20),
      new THREE.MeshStandardMaterial({ color: 0x007f73, roughness: 0.4, emissive: 0x00332e }),
    );
    body.position.y = 0.22;
    avatar.add(body);
    const head = new THREE.Mesh(
      new THREE.SphereGeometry(0.11, 24, 24),
      new THREE.MeshStandardMaterial({ color: 0xffd7a6, roughness: 0.45 }),
    );
    head.position.y = 0.52;
    avatar.add(head);
    group.add(avatar);
    effects.readerAvatar = avatar;

    const positions = [];
    for (let index = 0; index < 70; index += 1) {
      const progress = index / 69;
      const point = fromRaised.clone().lerp(toRaised, progress);
      point.y += Math.sin(progress * Math.PI) * 0.32;
      positions.push(point.x, point.y, point.z);
    }
    const geometry = new THREE.BufferGeometry();
    geometry.setAttribute("position", new THREE.Float32BufferAttribute(positions, 3));
    const particles = markFinalTuningDecorativeParticles(new THREE.Points(
      geometry,
      new THREE.PointsMaterial({ color: 0x007f73, size: 0.038, transparent: true, opacity: 0.58 }),
    ));
    group.add(particles);
    effects.particles = particles;
  } else if (kind === "continuous-passive") {
    const readerTarget = new THREE.Group();
    readerTarget.position.set(0, 0, 0);
    const readerRing = new THREE.Mesh(
      new THREE.RingGeometry(0.34, 0.4, 48),
      new THREE.MeshBasicMaterial({ color: 0x007f73, transparent: true, opacity: 0.36, side: THREE.DoubleSide }),
    );
    readerRing.rotation.x = -Math.PI / 2;
    readerRing.position.y = 0.06;
    readerTarget.add(readerRing);
    group.add(readerTarget);
    effects.readerTarget = readerTarget;

    const ghost = new THREE.Mesh(
      new THREE.SphereGeometry(0.18, 32, 32),
      new THREE.MeshStandardMaterial({ color: 0xc75f1f, transparent: true, opacity: 0.54, roughness: 0.3, emissive: 0x321104 }),
    );
    ghost.position.copy(toRaised);
    group.add(ghost);
    effects.passiveGhost = ghost;
  } else if (kind === "discrete-fade") {
    [0.24, 0.5, 0.76].forEach((progress) => {
      const ring = new THREE.Mesh(
        new THREE.RingGeometry(0.18, 0.22, 36),
        new THREE.MeshBasicMaterial({ color: 0xc75f1f, transparent: true, opacity: 0.2, side: THREE.DoubleSide }),
      );
      ring.rotation.x = -Math.PI / 2;
      ring.position.copy(from.clone().lerp(to, progress));
      ring.position.y = 0.08;
      group.add(ring);
      effects.rings.push(ring);
    });
  }
  return effects;
}

function loadDynamicAsset(viewer, assetLink, index, total, active, finishAsset) {
  const asset = findAssetById(assetLink.assetId);
  const wrapper = new THREE.Group();
  const authorWrapper = new THREE.Group();
  authorWrapper.name = `StoryVR author transform · ${assetLink.assetId}`;
  authorWrapper.userData.assetId = assetLink.assetId;
  authorWrapper.visible = true;
  const spatialEntity = viewer?.layers?.enabled?.[SPATIAL_RELATIONS_COMPONENT_ID]
    ? lockedSpatialGlbEntityForViewer(viewer, assetLink.assetId, assetLink.entityId, assetLink.sceneContext)
    : null;
  const spatialEntityId = assetLink.entityId || spatialEntity?.id || "";
  authorWrapper.userData.spatialEntityId = spatialEntityId;
  const spatialTransformApplied = applyLockedSpatialGlbTransform(viewer, assetLink.assetId, authorWrapper, spatialEntity);
  const basePosition = spatialTransformApplied
    ? new THREE.Vector3()
    : dynamicAssetPosition3d(index, total, viewer.layoutKind, active);
  const targetSize = spatialTransformApplied
    ? spatialTopologyAssetPose(viewer, index, Math.max(total, 1)).targetSize
    : dynamicPreviewAssetTargetSize(viewer, active);
  wrapper.position.copy(basePosition);
  wrapper.add(authorWrapper);
  viewer.root.add(wrapper);
  const authoringObjectKey = spatialEntityId || `${assetLink.assetId}:${index}`;
  if (assetLink.transitionSceneRole !== "from") {
    viewer.authoringSpatialObjects?.set(authoringObjectKey, spatialTransformApplied ? authorWrapper : wrapper);
  }
  const dynamicEntry = {
    wrapper,
    authorWrapper,
    basePosition: basePosition.clone(),
    active,
    baseScale: spatialTransformApplied ? 1 : active ? 1.08 : 0.92,
    spatialTransformApplied,
    assetId: assetLink.assetId,
    entityId: spatialEntityId,
    transitionSceneRole: assetLink.transitionSceneRole || null,
    sceneContext: assetLink.sceneContext || null,
    index,
    opacityMaterials: [],
  };
  viewer.dynamicObjects.push(dynamicEntry);

  const role = assetLink.role || asset?.role || asset?.type || "dynamic asset";
  const placeholder = viewer.suppressSceneLabels
    ? null
    : makeTopologyPlaceholder(asset?.id || assetLink.assetId, active ? `Active effect: ${role}` : role, asset ? (active ? 0xf0c897 : 0x8fbfb7) : 0xc98a8a);
  if (placeholder) {
    placeholder.scale.multiplyScalar(active ? 1.05 : 0.9);
    authorWrapper.add(placeholder);
  }
  if (!viewer.suppressSceneLabels) {
    const label = makeTextSprite(active ? `Active effect: ${role}` : role, {
      y: active ? 1.22 : 0.95,
      color: "#10201c",
      background: active ? "rgba(255,244,222,0.94)" : "rgba(255,253,244,0.82)",
      width: active ? 1.6 : 1.15,
    });
    wrapper.add(label);
    dynamicEntry.opacityMaterials.push(...preparePreviewOpacityTarget(label));
  }

  if (active && viewer.showActiveHalo === true) {
    const halo = new THREE.Mesh(
      new THREE.RingGeometry(0.5, 0.56, 48),
      new THREE.MeshBasicMaterial({ color: 0xc75f1f, transparent: true, opacity: 0.48, side: THREE.DoubleSide }),
    );
    halo.rotation.x = -Math.PI / 2;
    halo.position.y = 0.03;
    wrapper.add(halo);
    dynamicEntry.opacityMaterials.push(...preparePreviewOpacityTarget(halo));
  }

  if (!asset) {
    finishAsset(false);
    return;
  }

  if (isModelAsset(asset)) {
    const url = assetLoadSrc(asset);
    if (!url) {
      finishAsset(false);
      return;
    }
    createGltfLoader().load(
      url,
      (gltf) => {
        if (viewer.disposed) {
          disposeObject(gltf.scene);
          return;
        }
        if (placeholder) {
          authorWrapper.remove(placeholder);
          disposeObject(placeholder);
        }
        applySpatialLoaderTransformPolicy(gltf.scene, spatialEntity);
        const normalizationMode = dynamicAssetNormalizationMode(spatialTransformApplied, spatialEntity);
        if (normalizationMode === "spatial") {
          normalizeSpatialRuntimeObject(
            gltf.scene,
            targetSize,
            spatialEntityVerticalAlignment(spatialEntity),
          );
        } else if (normalizationMode === "topology") {
          normalizeTopologyObject(gltf.scene, targetSize);
        }
        dynamicEntry.opacityMaterials.push(...preparePreviewOpacityTarget(gltf.scene));
        authorWrapper.add(gltf.scene);
        dynamicEntry.sourceScene = gltf.scene;
        attachSourceDynamicsPreviewAnimation(viewer, dynamicEntry, gltf);
        attachProceduralDynamicsPreviewMotion(viewer, dynamicEntry, gltf);
        attachFinalReviewSourcePlayback(viewer, dynamicEntry, gltf);
        applyInterBeatSourcePartMaskToEntry(viewer, dynamicEntry, viewer.playing ? "transition" : "destination");
        finishAsset(true);
      },
      undefined,
      () => finishAsset(false),
    );
    return;
  }

  const imageSrc = assetPreviewSrc(asset);
  if (imageSrc) {
    new THREE.TextureLoader().load(
      imageSrc,
      (texture) => {
        if (viewer.disposed) {
          texture.dispose();
          return;
        }
        texture.colorSpace = THREE.SRGBColorSpace;
        if (placeholder) {
          authorWrapper.remove(placeholder);
          disposeObject(placeholder);
        }
        const image = spatialEntity?.image || {};
        const actualAspect = texture.image?.width && texture.image?.height ? texture.image.width / texture.image.height : null;
        const aspect = Number(image.aspectRatio) || actualAspect || 16 / 9;
        const width = Math.max(0.1, Number(image.width) || targetSize);
        const height = Math.max(0.1, Number(image.height) || width / Math.max(aspect, 0.1));
        const plane = spatialEntity && spatialEntityType(spatialEntity) === "image-plane"
          ? new THREE.Mesh(
            new THREE.PlaneGeometry(width, height),
            new THREE.MeshBasicMaterial({ map: texture, transparent: true, side: THREE.DoubleSide, toneMapped: false }),
          )
          : makeTopologyImagePlane(texture, targetSize);
        dynamicEntry.opacityMaterials.push(...preparePreviewOpacityTarget(plane));
        authorWrapper.add(plane);
        dynamicEntry.sourceScene = plane;
        finishAsset(true);
      },
      undefined,
      () => finishAsset(false),
    );
    return;
  }

  finishAsset(true);
}

function proceduralDynamicsInstanceEntityId(instance) {
  return String(
    instance?.entityId
      || instance?.targetEntityId
      || instance?.actor?.entityId
      || "",
  ).trim();
}

function proceduralDynamicsClipForInstance(instance, clips) {
  const available = Array.isArray(clips) ? clips : [];
  const clipSpec = instance?.clip || instance?.animation?.clip || instance?.actor?.clip || {};
  const requestedIndex = Number(
    clipSpec?.index
      ?? clipSpec?.clipIndex
      ?? instance?.clipIndex
      ?? instance?.animation?.clipIndex
      ?? instance?.actor?.animation?.clipIndex,
  );
  if (Number.isInteger(requestedIndex) && requestedIndex >= 0 && available[requestedIndex]) {
    return available[requestedIndex];
  }
  const requestedName = String(
    clipSpec?.name
      || clipSpec?.clipName
      || instance?.animation?.clipName
      || instance?.actor?.animation?.clipName
      || "",
  ).trim();
  if (requestedName) {
    const named = available.find((clip) => clip.name === requestedName);
    if (named) return named;
  }
  return available[0] || null;
}

function attachProceduralDynamicsAnimation(entry, gltf, instance) {
  if (entry.proceduralMixer) {
    entry.proceduralMixer.stopAllAction?.();
    if (entry.sourceScene) entry.proceduralMixer.uncacheRoot?.(entry.sourceScene);
    entry.proceduralMixer = null;
  }
  if (instance?.animationMode === "none") {
    return;
  }
  const clip = proceduralDynamicsClipForInstance(instance, gltf?.animations);
  if (!clip || !entry?.sourceScene) return;
  const mixer = new THREE.AnimationMixer(entry.sourceScene);
  const action = mixer.clipAction(clip);
  action.reset();
  action.setLoop(THREE.LoopRepeat, Infinity);
  action.play();
  entry.proceduralMixer = mixer;
  entry.proceduralAction = action;
  entry.proceduralSourceMotionDuration = Math.max(Number(clip.duration) || 0, 0.001);
  entry.proceduralAnimationTimeScale = Math.max(0.05, Math.min(4, Number(
    instance?.animationTimeScale
      ?? instance?.animation?.timeScale
      ?? instance?.clip?.timeScale
      ?? instance?.actor?.animation?.timeScale
      ?? 1,
  ) || 1));
  entry.proceduralAnimationPhase01 = Math.max(0, Math.min(1, Number(
    instance?.animationPhase01
      ?? instance?.animation?.phase01
      ?? 0,
  ) || 0));
}

function proceduralDynamicsAuthoredRoot(entry) {
  return entry?.wrapper
    || entry?.topologyWrapper
    || entry?.authorWrapper
    || null;
}

function attachProceduralDynamicsPreviewMotion(viewer, dynamicEntry, gltf) {
  if (!viewer?.proceduralPlan || !dynamicEntry?.sourceScene) return 0;
  const entityId = String(
    dynamicEntry.entityId
      || dynamicEntry.authorWrapper?.userData?.spatialEntityId
      || "",
  ).trim();
  if (!entityId) return 0;
  const instance = (viewer.proceduralInstances || [])
    .find((candidate) => proceduralDynamicsInstanceEntityId(candidate) === entityId);
  if (!instance || String(instance.assetId || "") !== String(dynamicEntry.assetId || "")) return 0;
  if (!viewer.proceduralAssignedEntityIds) viewer.proceduralAssignedEntityIds = new Set();
  if (viewer.proceduralAssignedEntityIds.has(entityId)) return 0;
  const authoredRoot = proceduralDynamicsAuthoredRoot(dynamicEntry);
  const originalParent = authoredRoot?.parent || null;
  if (!authoredRoot || !originalParent) return 0;

  viewer.proceduralAssignedEntityIds.add(entityId);
  const originalIndex = originalParent.children.indexOf(authoredRoot);
  const motionRoot = new THREE.Group();
  motionRoot.name = `StoryVR generated motion offset · ${entityId}`;
  originalParent.add(motionRoot);
  motionRoot.add(authoredRoot);
  const appendedIndex = originalParent.children.indexOf(motionRoot);
  if (originalIndex >= 0 && appendedIndex >= 0 && originalIndex !== appendedIndex) {
    originalParent.children.splice(appendedIndex, 1);
    originalParent.children.splice(originalIndex, 0, motionRoot);
  }

  dynamicEntry.proceduralMotionBound = true;
  dynamicEntry.proceduralInstance = instance;
  dynamicEntry.proceduralMotionRoot = motionRoot;
  dynamicEntry.proceduralAuthoredRoot = authoredRoot;
  dynamicEntry.proceduralOriginalParent = originalParent;
  dynamicEntry.proceduralOriginalIndex = originalIndex;
  dynamicEntry.proceduralAnchorPosition = viewer.proceduralAnchorPosition?.clone?.() || new THREE.Vector3();
  dynamicEntry.proceduralTargetQuaternion = new THREE.Quaternion();
  dynamicEntry.proceduralOriginalPreviewOpacities = (dynamicEntry.opacityMaterials || []).map((material) => (
    Number.isFinite(Number(material?.userData?.storyvrPreviewOpacity))
      ? Number(material.userData.storyvrPreviewOpacity)
      : 1
  ));
  attachProceduralDynamicsAnimation(dynamicEntry, gltf, instance);
  viewer.proceduralPreviewEntries.push(dynamicEntry);
  return 1;
}

function proceduralDynamicsYawOffsetRadians(instance) {
  const direct = Number(instance?.yawOffsetRadians);
  if (Number.isFinite(direct)) return direct;
  const orientation = instance?.orientation || instance?.actor?.orientation || {};
  const degrees = Number(
    orientation.yawOffsetDegrees
      ?? orientation.yawDegrees
      ?? instance?.yawOffsetDegrees
      ?? 0,
  );
  return THREE.MathUtils.degToRad(Number.isFinite(degrees) ? degrees : 0);
}

function proceduralDynamicsForwardAxisOffset(instance) {
  const axis = String(instance?.modelForwardAxis || "+Z").toUpperCase();
  if (axis === "-Z") return Math.PI;
  if (axis === "+X") return -Math.PI / 2;
  if (axis === "-X") return Math.PI / 2;
  return 0;
}

const proceduralDynamicsPreviewUpAxis = new THREE.Vector3(0, 1, 0);

function applyProceduralDynamicsPreviewTransform(entry, elapsedSeconds, deltaSeconds = 0) {
  const instance = entry?.proceduralInstance;
  const motionRoot = entry?.proceduralMotionRoot;
  if (!instance || !motionRoot) return false;
  const sample = sampleProceduralDynamicsTransform(instance, elapsedSeconds);
  if (!sample) return false;
  const position = sample.position;
  if (Array.isArray(position) && position.length >= 3) {
    motionRoot.position.fromArray(position).add(entry.proceduralAnchorPosition);
  } else if (position && typeof position === "object") {
    motionRoot.position
      .set(Number(position.x) || 0, Number(position.y) || 0, Number(position.z) || 0)
      .add(entry.proceduralAnchorPosition);
  }
  const tangent = sample.tangent;
  if (instance.orientationKind !== "fixed" && Array.isArray(tangent) && tangent.length >= 3) {
    const x = Number(tangent[0]) || 0;
    const z = Number(tangent[2]) || 0;
    if (Math.hypot(x, z) > 1e-5) {
      const yaw = Math.atan2(x, z)
        + proceduralDynamicsForwardAxisOffset(instance)
        + proceduralDynamicsYawOffsetRadians(instance);
      entry.proceduralTargetQuaternion.setFromAxisAngle(
        proceduralDynamicsPreviewUpAxis,
        yaw,
      );
      const smoothing = Math.max(0, Number(instance.orientationSmoothingSeconds) || 0);
      const blend = smoothing > 0 && deltaSeconds > 0
        ? 1 - Math.exp(-deltaSeconds / smoothing)
        : 1;
      motionRoot.quaternion.slerp(entry.proceduralTargetQuaternion, blend);
    }
  }
  if (Number.isFinite(Number(sample.opacity))) {
    setPreviewOpacityMaterials(entry.opacityMaterials, Number(sample.opacity));
  }
  return true;
}

function animateDynamicGeometry(viewer) {
  const time = viewer.elapsed;
  const kind = viewerDynamicGeometryKind(viewer) || knownDynamicGeometryKind(viewer.kind) || "motion";
  for (const item of viewer.dynamicObjects) {
    item.wrapper.position.copy(item.basePosition);
    item.wrapper.rotation.set(0, 0, 0);
    item.wrapper.scale.setScalar(item.spatialTransformApplied ? 1 : item.active ? item.baseScale : 0.92);
    if (!updateSourceTransitionPlayback(viewer, item) && item.mixer && !item.sourcePartFrozen) {
      const duration = Math.max(Number(item.sourceMotionDuration) || 0, 0.001);
      const sourceTime = viewer.componentId === "inter-beat-dynamics"
        ? (Number(item.sourceMotionStartProgress) + previewCycleProgress(viewer) * (
          Number(item.sourceMotionEndProgress) - Number(item.sourceMotionStartProgress)
        )) * duration
        : (
          time * (Number(item.proceduralAnimationTimeScale) || 1)
          + duration * (Number(item.proceduralAnimationPhase01) || 0)
        );
      item.mixer.setTime(sourceTime);
    }
  }
  animateProceduralDynamicsPreview(viewer, time);
}

function animateProceduralDynamicsPreview(viewer, time = viewer?.elapsed || 0) {
  const previousTime = Number(viewer?.proceduralPreviewPreviousTime);
  const deltaSeconds = Number.isFinite(previousTime)
    ? Math.max(0, Math.min(time - previousTime, 0.05))
    : 1 / 60;
  if (viewer) viewer.proceduralPreviewPreviousTime = time;
  for (const item of viewer?.proceduralPreviewEntries || []) {
    if (item.proceduralMixer) {
      const duration = Math.max(Number(item.proceduralSourceMotionDuration) || 0, 0.001);
      item.proceduralMixer.setTime(
        time * (Number(item.proceduralAnimationTimeScale) || 1)
        + duration * (Number(item.proceduralAnimationPhase01) || 0),
      );
    }
    applyProceduralDynamicsPreviewTransform(item, time, deltaSeconds);
  }
}

function disposeProceduralDynamicsPreview(viewer) {
  for (const entry of viewer?.proceduralPreviewEntries || []) {
    if (entry.proceduralMixer) {
      entry.proceduralMixer.stopAllAction();
      if (entry.sourceScene) entry.proceduralMixer.uncacheRoot(entry.sourceScene);
    }
    const motionRoot = entry.proceduralMotionRoot;
    const authoredRoot = entry.proceduralAuthoredRoot;
    const originalParent = entry.proceduralOriginalParent;
    if (motionRoot && authoredRoot && originalParent) {
      motionRoot.remove(authoredRoot);
      originalParent.add(authoredRoot);
      const appendedIndex = originalParent.children.indexOf(authoredRoot);
      const originalIndex = Number(entry.proceduralOriginalIndex);
      if (originalIndex >= 0 && appendedIndex >= 0 && originalIndex !== appendedIndex) {
        originalParent.children.splice(appendedIndex, 1);
        originalParent.children.splice(Math.min(originalIndex, originalParent.children.length), 0, authoredRoot);
      }
      motionRoot.removeFromParent();
    }
    (entry.opacityMaterials || []).forEach((material, index) => {
      setPreviewOpacityMaterials(
        [material],
        entry.proceduralOriginalPreviewOpacities?.[index] ?? 1,
      );
    });
    entry.proceduralMixer = null;
    entry.proceduralAction = null;
    entry.proceduralMotionBound = false;
    entry.proceduralInstance = null;
    entry.proceduralMotionRoot = null;
    entry.proceduralAuthoredRoot = null;
    entry.proceduralOriginalParent = null;
    entry.proceduralOriginalPreviewOpacities = null;
  }
  if (viewer) {
    viewer.proceduralPreviewEntries = [];
    viewer.proceduralPreviewPreviousTime = null;
    viewer.proceduralAssignedEntityIds = new Set();
  }
}

function sourcePlaybackDiagnostic(runtime, code, detail = "") {
  if (!runtime) return;
  const key = `${code}:${detail}`;
  if (runtime.diagnosticKeys.has(key)) return;
  runtime.diagnosticKeys.add(key);
  runtime.diagnostics.push({ code, detail });
  console.warn(`[StoryVR source playback] ${code}${detail ? `: ${detail}` : ""}`);
}

function sourcePlaybackNodeReference(value) {
  if (typeof value === "string") return value.trim();
  if (!value || typeof value !== "object") return "";
  return String(value.node || value.nodeName || value.name || value.selector || "").trim();
}

function sourcePlaybackFindNode(root, reference) {
  const name = sourcePlaybackNodeReference(reference);
  if (!root || !name) return null;
  const direct = root.getObjectByName?.(name);
  if (direct) return direct;
  const normalizedPath = name.replace(/^\/+|\/+$/g, "");
  let match = null;
  root.traverse?.((node) => {
    if (match) return;
    const nodePath = sourcePartNodePath(node, root);
    if (node.name === name || nodePath === normalizedPath) match = node;
  });
  return match;
}

function sourcePlaybackReadPath(target, path, fallback = null) {
  if (!target) return fallback;
  const parts = String(path || "").split(".").map((part) => part.trim()).filter(Boolean);
  if (!parts.length) return fallback;
  let value = target;
  for (const part of parts) {
    if (value == null || !(part in Object(value))) return fallback;
    value = value[part];
  }
  const number = Number(value);
  return Number.isFinite(number) ? number : fallback;
}

function sourcePlaybackBindingValue(bindingEntry, runtime = null) {
  const binding = bindingEntry.binding;
  const source = binding.source && typeof binding.source === "object" ? binding.source : {};
  const sourceType = String(source.type || binding.sourceType || "").trim().toLowerCase().replace(/_/g, "-");
  let raw = null;
  if (sourceType === "timeline-progress") raw = runtime?.progress ?? null;
  if (sourceType === "timeline-time") {
    const progress = finiteSourcePlaybackNumber(runtime?.progress);
    const duration = finiteSourcePlaybackNumber(runtime?.masterDuration, runtime?.asset?.timeline?.durationSeconds);
    raw = progress == null || duration == null ? null : progress * duration;
  }
  if (sourceType === "wall-clock-time") raw = finiteSourcePlaybackNumber(runtime?.clockSeconds);
  if (sourceType === "constant") raw = finiteSourcePlaybackNumber(source.value, binding.value);
  const declaredValue = finiteSourcePlaybackNumber(binding.value);
  if (raw == null && declaredValue != null) raw = declaredValue;
  const parameters = binding.parameters && typeof binding.parameters === "object" ? binding.parameters : {};
  if (raw == null && ["", "node", "node-property", "property"].includes(sourceType)) {
    const path = String(source.path || binding.sourcePath || binding.path || "scale.x");
    raw = sourcePlaybackReadPath(bindingEntry.sourceNode, path, null);
  }
  if (raw == null) return null;
  const multiplier = finiteSourcePlaybackNumber(parameters.multiplier, binding.multiplier, binding.factor, source.multiplier, 1);
  const offset = finiteSourcePlaybackNumber(parameters.offset, binding.offset, source.offset, 0);
  let value = raw * multiplier + offset;
  if (parameters.invert === true || binding.invert === true || source.invert === true) value = 1 - value;
  const range = Array.isArray(parameters.clamp)
    ? parameters.clamp
    : Array.isArray(binding.clamp) ? binding.clamp : Array.isArray(source.clamp) ? source.clamp : [];
  const minimum = finiteSourcePlaybackNumber(parameters.minimum, parameters.min, binding.minimum, binding.min, range[0]);
  const maximum = finiteSourcePlaybackNumber(parameters.maximum, parameters.max, binding.maximum, binding.max, range[1]);
  if (minimum != null) value = Math.max(minimum, value);
  if (maximum != null) value = Math.min(maximum, value);
  return value;
}

function sourcePlaybackMaterialRecipeName(value) {
  return String(value || "").trim().toLowerCase().replace(/[\s_]+/g, "-");
}

function sourcePlaybackMaterialSide(value, fallback = THREE.FrontSide) {
  const side = String(value || "").trim().toLowerCase();
  if (["double", "double-side", "double-sided"].includes(side)) return THREE.DoubleSide;
  if (["back", "back-side", "back-sided"].includes(side)) return THREE.BackSide;
  if (["front", "front-side", "front-sided"].includes(side)) return THREE.FrontSide;
  return fallback;
}

function sourcePlaybackMaterialBlending(value, fallback = THREE.NormalBlending) {
  const blending = String(value || "").trim().toLowerCase();
  if (blending === "additive") return THREE.AdditiveBlending;
  if (blending === "multiply") return THREE.MultiplyBlending;
  if (blending === "subtractive") return THREE.SubtractiveBlending;
  if (blending === "normal") return THREE.NormalBlending;
  return fallback;
}

function sourcePlaybackDataChannel(value) {
  const channel = String(value || "r").trim().toLowerCase();
  if (channel === "g" || channel === "green") return new THREE.Vector4(0, 1, 0, 0);
  if (channel === "b" || channel === "blue") return new THREE.Vector4(0, 0, 1, 0);
  if (channel === "a" || channel === "alpha") return new THREE.Vector4(0, 0, 0, 1);
  return new THREE.Vector4(1, 0, 0, 0);
}

function sourcePlaybackAtlasOffset(value) {
  if (Array.isArray(value)) {
    return new THREE.Vector2(
      finiteSourcePlaybackNumber(value[0], 0) ?? 0,
      finiteSourcePlaybackNumber(value[1], 0) ?? 0,
    );
  }
  if (value && typeof value === "object") {
    return new THREE.Vector2(
      finiteSourcePlaybackNumber(value.x, value.u, 0) ?? 0,
      finiteSourcePlaybackNumber(value.y, value.v, 0) ?? 0,
    );
  }
  return new THREE.Vector2(0, 0);
}

function sourcePlaybackScalarFieldColor(value) {
  if (Array.isArray(value) && value.length >= 3) {
    const components = value.slice(0, 3).map((component) => Number(component));
    if (components.every(Number.isFinite)) return components;
  }
  if (value && typeof value === "object") {
    const components = [value.r, value.g, value.b].map((component) => Number(component));
    if (components.every(Number.isFinite)) return components;
  }
  try {
    const color = new THREE.Color(value);
    return [color.r, color.g, color.b];
  } catch {
    return null;
  }
}

function sourcePlaybackScalarFieldColorRamp(value) {
  const declared = Array.isArray(value) ? value : [];
  const stops = declared.flatMap((entry) => {
    const stop = Array.isArray(entry)
      ? finiteSourcePlaybackNumber(entry[0])
      : finiteSourcePlaybackNumber(entry?.stop, entry?.position);
    const colorValue = Array.isArray(entry) ? entry[1] : entry?.color;
    const color = colorValue == null ? null : sourcePlaybackScalarFieldColor(colorValue);
    return stop == null || !color ? [] : [{ stop: Math.max(0, Math.min(1, stop)), color }];
  }).sort((left, right) => left.stop - right.stop);
  const uniqueStops = [];
  for (const stop of stops) {
    const existing = uniqueStops.findIndex((item) => item.stop === stop.stop);
    if (existing >= 0) uniqueStops[existing] = stop;
    else uniqueStops.push(stop);
  }
  return uniqueStops.length >= 2
    ? uniqueStops
    : [{ stop: 0, color: [0, 0, 0] }, { stop: 1, color: [1, 1, 1] }];
}

function sourcePlaybackShaderNumber(value) {
  const number = Number(value);
  if (!Number.isFinite(number)) return "0.0";
  return Number.isInteger(number) ? `${number}.0` : String(number);
}

function sourcePlaybackScalarFieldColorShader(value) {
  const stops = sourcePlaybackScalarFieldColorRamp(value);
  const colorLiteral = (color) => `vec3(${color.map(sourcePlaybackShaderNumber).join(", ")})`;
  const lines = [
    "value = clamp(value, 0.0, 1.0);",
    `vec3 color = ${colorLiteral(stops[0].color)};`,
  ];
  for (let index = 1; index < stops.length; index += 1) {
    const previous = stops[index - 1];
    const current = stops[index];
    lines.push(
      `color = mix(color, ${colorLiteral(current.color)}, ramp(${sourcePlaybackShaderNumber(previous.stop)}, ${sourcePlaybackShaderNumber(current.stop)}, value));`,
    );
  }
  lines.push("return color;");
  return `vec3 scalarFieldColor(float value) { ${lines.join(" ")} }`;
}

function createSourcePlaybackMaterial(definition, originalMaterial) {
  const recipe = sourcePlaybackMaterialRecipeName(definition?.recipe || definition?.type);
  const parameters = definition?.parameters && typeof definition.parameters === "object" ? definition.parameters : {};
  const commonUniforms = {
    showAmt: { value: finiteSourcePlaybackNumber(parameters.showAmt, 1) ?? 1 },
    storyvrOpacity: { value: 1 },
  };
  const vertexShader = `
    varying vec2 vUv;
    void main() {
      vUv = uv;
      gl_Position = projectionMatrix * modelViewMatrix * vec4(position, 1.0);
    }
  `;
  let material = null;
  if (recipe === "uv-stripe-flow") {
    material = new THREE.ShaderMaterial({
      uniforms: {
        ...commonUniforms,
        time: { value: finiteSourcePlaybackNumber(parameters.time, 0) ?? 0 },
        color: { value: new THREE.Color(parameters.color || "#40b5b5") },
        maxAlpha: { value: finiteSourcePlaybackNumber(parameters.maxAlpha, 0.5) ?? 0.5 },
        speed: { value: finiteSourcePlaybackNumber(parameters.speed, 0.08) ?? 0.08 },
        density: { value: finiteSourcePlaybackNumber(parameters.density, 0.2) ?? 0.2 },
        gap: { value: finiteSourcePlaybackNumber(parameters.gap, 0.35) ?? 0.35 },
        timeScale: { value: finiteSourcePlaybackNumber(parameters.timeScale, 0.6) ?? 0.6 },
      },
      vertexShader,
      fragmentShader: `
        uniform float time;
        uniform float showAmt;
        uniform float storyvrOpacity;
        uniform vec3 color;
        uniform float maxAlpha;
        uniform float speed;
        uniform float density;
        uniform float gap;
        uniform float timeScale;
        varying vec2 vUv;
        void main() {
          const float PI = 3.14159265359;
          float x = vUv.x * density * 500.0 - time * timeScale * speed;
          float intensity = fract(x / PI);
          intensity = smoothstep(gap, 1.0, intensity);
          gl_FragColor = vec4(color, min(intensity, maxAlpha) * showAmt * storyvrOpacity);
        }
      `,
    });
  } else if (recipe === "texture-background-fade") {
    const map = originalMaterial?.map || null;
    if (!map) return null;
    const backgroundColor = sourcePlaybackScalarFieldColor(parameters.backgroundColor) || [0.91, 0.92, 0.93];
    material = new THREE.ShaderMaterial({
      uniforms: {
        ...commonUniforms,
        map: { value: map },
        backgroundColor: { value: new THREE.Color().setRGB(...backgroundColor) },
        fadeOpacity: { value: finiteSourcePlaybackNumber(parameters.fadeOpacity, 1) ?? 1 },
      },
      vertexShader,
      fragmentShader: `
        uniform sampler2D map;
        uniform vec3 backgroundColor;
        uniform float fadeOpacity;
        uniform float showAmt;
        uniform float storyvrOpacity;
        varying vec2 vUv;
        void main() {
          float fade = clamp(fadeOpacity, 0.0, 1.0);
          vec3 textureColor = texture2D(map, vUv).rgb;
          gl_FragColor = vec4(
            mix(backgroundColor, textureColor, fade),
            fade * showAmt * storyvrOpacity
          );
        }
      `,
    });
  } else if (recipe === "texture-atlas-scalar-field") {
    const map = originalMaterial?.map || null;
    if (!map) return null;
    if ("colorSpace" in map) map.colorSpace = THREE.NoColorSpace;
    material = new THREE.ShaderMaterial({
      uniforms: {
        ...commonUniforms,
        map: { value: map },
        progress: { value: finiteSourcePlaybackNumber(parameters.progress, 0) ?? 0 },
        frameCount: { value: Math.max(2, finiteSourcePlaybackNumber(parameters.frameCount, 8) ?? 8) },
        dataChannel: { value: sourcePlaybackDataChannel(parameters.channel || parameters.dataChannel) },
      },
      vertexShader,
      fragmentShader: `
        uniform sampler2D map;
        uniform float progress;
        uniform float frameCount;
        uniform float showAmt;
        uniform float storyvrOpacity;
        uniform vec4 dataChannel;
        varying vec2 vUv;
        float ramp(float startValue, float endValue, float value) {
          return clamp((value - startValue) / (endValue - startValue), 0.0, 1.0);
        }
        vec3 concentrationColor(float value) {
          value = clamp(value, 0.0, 1.0);
          vec3 color = mix(vec3(1.0, 1.0, 0.988235), vec3(0.988235, 0.988235, 0.741176), ramp(0.0, 0.1, value));
          color = mix(color, vec3(0.980392, 0.945098, 0.576471), ramp(0.1, 0.2, value));
          color = mix(color, vec3(0.968627, 0.862745, 0.388235), ramp(0.2, 0.3, value));
          color = mix(color, vec3(0.94902, 0.741176, 0.219608), ramp(0.3, 0.4, value));
          color = mix(color, vec3(0.929412, 0.607843, 0.094118), ramp(0.4, 0.5, value));
          color = mix(color, vec3(0.909804, 0.486275, 0.035294), ramp(0.5, 0.6, value));
          color = mix(color, vec3(0.8, 0.305882, 0.0), ramp(0.6, 0.7, value));
          color = mix(color, vec3(0.678431, 0.180392, 0.011765), ramp(0.7, 0.8, value));
          color = mix(color, vec3(0.501961, 0.054902, 0.031373), ramp(0.8, 0.9, value));
          return mix(color, vec3(0.301961, 0.047059, 0.090196), ramp(0.9, 1.0, value));
        }
        void main() {
          float frames = max(2.0, frameCount);
          float frameWidth = 1.0 / frames;
          float framePosition = clamp(progress, 0.0, 0.9999) * (frames - 1.0);
          float firstFrame = floor(framePosition);
          float secondFrame = min(firstFrame + 1.0, frames - 1.0);
          float frameMix = fract(framePosition);
          vec2 firstUv = vec2(vUv.x * frameWidth + firstFrame * frameWidth, vUv.y);
          vec2 secondUv = vec2(vUv.x * frameWidth + secondFrame * frameWidth, vUv.y);
          float firstValue = dot(texture2D(map, firstUv), dataChannel);
          float secondValue = dot(texture2D(map, secondUv), dataChannel);
          float concentration = mix(firstValue, secondValue, frameMix);
          gl_FragColor = vec4(concentrationColor(concentration), concentration * showAmt * storyvrOpacity);
        }
      `,
    });
  } else if (recipe === "layered-texture-atlas-scalar-field") {
    const map = originalMaterial?.map || null;
    if (!map) return null;
    if ("colorSpace" in map) map.colorSpace = THREE.NoColorSpace;
    material = new THREE.ShaderMaterial({
      uniforms: {
        ...commonUniforms,
        map: { value: map },
        sliceY: { value: finiteSourcePlaybackNumber(parameters.sliceY, 0) ?? 0 },
        atlasColumns: { value: Math.max(1, finiteSourcePlaybackNumber(parameters.atlasColumns, 1) ?? 1) },
        atlasRows: { value: Math.max(1, finiteSourcePlaybackNumber(parameters.atlasRows, 1) ?? 1) },
        sampleCount: { value: Math.max(1, finiteSourcePlaybackNumber(parameters.sampleCount, 1) ?? 1) },
        dataChannel: { value: sourcePlaybackDataChannel(parameters.dataChannel || parameters.channel) },
        scalarGain: { value: finiteSourcePlaybackNumber(parameters.scalarGain, 1) ?? 1 },
        alphaFloor: { value: Math.max(0, finiteSourcePlaybackNumber(parameters.alphaFloor, 0) ?? 0) },
        atlasOffset: { value: sourcePlaybackAtlasOffset(parameters.atlasOffset) },
      },
      vertexShader,
      fragmentShader: `
        uniform sampler2D map;
        uniform float sliceY;
        uniform float atlasColumns;
        uniform float atlasRows;
        uniform float sampleCount;
        uniform float scalarGain;
        uniform float alphaFloor;
        uniform float showAmt;
        uniform float storyvrOpacity;
        uniform vec2 atlasOffset;
        uniform vec4 dataChannel;
        varying vec2 vUv;
        float ramp(float startValue, float endValue, float value) {
          return clamp((value - startValue) / max(endValue - startValue, 0.000001), 0.0, 1.0);
        }
        ${sourcePlaybackScalarFieldColorShader(parameters.colorRamp)}
        vec4 sampleAtlas(float sampleIndex) {
          float columns = max(1.0, atlasColumns);
          float rows = max(1.0, atlasRows);
          float column = mod(sampleIndex, columns);
          float row = floor(sampleIndex / columns);
          vec2 atlasUv = (vUv + vec2(column, row)) / vec2(columns, rows) + atlasOffset;
          return texture2D(map, atlasUv);
        }
        void main() {
          float capacity = max(1.0, atlasColumns * atlasRows);
          float samples = clamp(sampleCount, 1.0, capacity);
          float samplePosition = clamp(sliceY, 0.0, 1.0) * (samples - 1.0);
          float firstSample = floor(samplePosition);
          float secondSample = min(firstSample + 1.0, samples - 1.0);
          float sampleMix = fract(samplePosition);
          vec4 data = mix(sampleAtlas(firstSample), sampleAtlas(secondSample), sampleMix);
          float scalar = clamp(dot(data, dataChannel) * scalarGain, 0.0, 1.0);
          float alpha = max(scalar, alphaFloor) * showAmt * storyvrOpacity;
          gl_FragColor = vec4(scalarFieldColor(scalar), alpha);
        }
      `,
    });
  }
  if (!material) return null;
  const render = definition?.render && typeof definition.render === "object" ? definition.render : {};
  material.name = String(definition.id || `${recipe}-material`);
  material.side = sourcePlaybackMaterialSide(render.side, originalMaterial?.side ?? THREE.FrontSide);
  material.transparent = render.transparent !== false;
  material.depthWrite = render.depthWrite === true;
  material.depthTest = render.depthTest !== false;
  material.blending = sourcePlaybackMaterialBlending(render.blending, originalMaterial?.blending ?? THREE.NormalBlending);
  material.opacity = Number.isFinite(originalMaterial?.opacity) ? originalMaterial.opacity : 1;
  material.toneMapped = render.toneMapped === true;
  material.userData = {
    ...(originalMaterial?.userData || {}),
    storyvrMaterialRecipe: recipe,
    storyvrMaterialRecipeId: String(definition.id || ""),
    storyvrBaseOpacity: material.opacity,
    storyvrBaseTransparent: material.transparent,
    storyvrBaseDepthWrite: material.depthWrite,
    storyvrPreviewOpacity: 1,
    storyvrSourceBindingOpacity: 1,
    storyvrOpaqueAtUniform: sourcePlaybackMaterialOpaqueAtUniform(definition),
  };
  material.onBeforeRender = () => {
    if (material.uniforms?.storyvrOpacity) material.uniforms.storyvrOpacity.value = Number.isFinite(material.opacity) ? material.opacity : 1;
  };
  return material;
}

function sourcePlaybackMaterialOpaqueAtUniform(definition) {
  const rule = definition?.render?.opaqueAtUniform;
  if (!rule || typeof rule !== "object") return null;
  const uniform = String(rule.uniform || "").trim();
  const threshold = finiteSourcePlaybackNumber(rule.threshold);
  return uniform && threshold != null ? { uniform, threshold } : null;
}

function applySourcePlaybackMaterialOpaqueAtUniform(material, uniformName, value) {
  const rule = material?.userData?.storyvrOpaqueAtUniform;
  if (!rule || rule.uniform !== uniformName || !Number.isFinite(value)) return false;
  const nextTransparent = value < rule.threshold;
  material.userData.storyvrBaseTransparent = nextTransparent;
  updatePreviewMaterialOpacity(material);
  return true;
}

function initializeSourcePlaybackMaterials(runtime) {
  runtime.materialRecipes = new Map();
  for (const [index, definition] of (runtime.asset.materials || []).entries()) {
    const id = String(definition?.id || `material:${index}`).trim();
    const targetReference = definition?.target || definition?.node || definition?.targetNode;
    const target = sourcePlaybackFindNode(runtime.root, targetReference);
    if (!target) {
      sourcePlaybackDiagnostic(runtime, "material-target-unavailable", id);
      continue;
    }
    const recursive = definition?.recursive !== false && definition?.parameters?.recursive !== false;
    const materials = [];
    const nodes = [];
    for (const node of sourcePlaybackRenderableNodes(target, recursive)) {
      const originals = Array.isArray(node.material) ? node.material : [node.material];
      const replacements = originals.map((original) => createSourcePlaybackMaterial(definition, original)).filter(Boolean);
      if (!replacements.length) continue;
      node.material = Array.isArray(node.material) ? replacements : replacements[0];
      const renderOrder = finiteSourcePlaybackNumber(definition?.render?.renderOrder, definition?.renderOrder);
      if (renderOrder != null) node.renderOrder = renderOrder;
      nodes.push(node);
      materials.push(...replacements);
    }
    if (!materials.length) {
      sourcePlaybackDiagnostic(runtime, "material-recipe-unavailable", `${id}:${definition?.recipe || "missing"}`);
      continue;
    }
    runtime.materialRecipes.set(id, { id, definition, target, nodes, materials });
  }
}

function sourcePlaybackBindingMaterials(bindingEntry, runtime) {
  const target = bindingEntry.binding.target && typeof bindingEntry.binding.target === "object" ? bindingEntry.binding.target : {};
  const materialId = String(target.material || target.materialId || bindingEntry.binding.material || bindingEntry.binding.materialId || "").trim();
  if (materialId) return runtime.materialRecipes?.get(materialId)?.materials || [];
  if (!bindingEntry.targetNode) return [];
  return sourcePlaybackRenderableNodes(bindingEntry.targetNode, target.recursive !== false)
    .flatMap((node) => Array.isArray(node.material) ? node.material : node.material ? [node.material] : []);
}

function applySourcePlaybackMaterialUniform(bindingEntry, runtime) {
  const value = sourcePlaybackBindingValue(bindingEntry, runtime);
  const target = bindingEntry.binding.target && typeof bindingEntry.binding.target === "object" ? bindingEntry.binding.target : {};
  const uniformName = String(target.uniform || bindingEntry.binding.uniform || "").trim();
  const materials = sourcePlaybackBindingMaterials(bindingEntry, runtime);
  if (value == null || !uniformName || !materials.length) {
    sourcePlaybackDiagnostic(runtime, "material-uniform-unavailable", `${bindingEntry.id}:${uniformName || "missing"}`);
    return;
  }
  let applied = false;
  for (const material of materials) {
    if (!material?.uniforms || !(uniformName in material.uniforms)) continue;
    material.uniforms[uniformName].value = value;
    applySourcePlaybackMaterialOpaqueAtUniform(material, uniformName, value);
    applied = true;
  }
  if (!applied) sourcePlaybackDiagnostic(runtime, "material-uniform-unavailable", `${bindingEntry.id}:${uniformName}`);
}

function applySourcePlaybackVisibility(bindingEntry, runtime) {
  const value = sourcePlaybackBindingValue(bindingEntry, runtime);
  if (value == null || !bindingEntry.targetNode) {
    sourcePlaybackDiagnostic(runtime, "binding-target-unavailable", bindingEntry.id);
    return;
  }
  const binding = bindingEntry.binding;
  const parameters = binding.parameters && typeof binding.parameters === "object" ? binding.parameters : {};
  const threshold = finiteSourcePlaybackNumber(parameters.visibleThreshold, parameters.threshold, binding.visibleThreshold, binding.threshold, 0.001);
  const visible = value >= threshold;
  for (const node of sourcePlaybackRenderableNodes(bindingEntry.targetNode, parameters.recursive !== false && binding.recursive !== false)) {
    if (!("storyvrSourcePartBaseVisible" in node.userData)) node.userData.storyvrSourcePartBaseVisible = node.visible !== false;
    node.userData.storyvrSourceBindingVisible = visible;
    updateSourceRenderableVisibility(node);
  }
}

function sourcePlaybackRenderableNodes(target, recursive = true) {
  if (!target) return [];
  const renderables = [];
  const collect = (node) => {
    if (node?.isMesh || node?.isPoints || node?.isLine) renderables.push(node);
  };
  if (recursive && target.traverse) target.traverse(collect);
  else collect(target);
  return renderables;
}

function snapVisibilityOpacityEndpoint(opacity, opacityMaximum, fullOpacityThreshold = 0.99) {
  const value = Number(opacity);
  const maximum = Number(opacityMaximum);
  const threshold = Number(fullOpacityThreshold);
  if (!Number.isFinite(value) || !Number.isFinite(maximum)) return opacity;
  if (maximum < 0.999 || !Number.isFinite(threshold)) return value;
  return value >= threshold ? maximum : value;
}

function applySourcePlaybackVisibilityOpacity(bindingEntry, runtime) {
  const value = sourcePlaybackBindingValue(bindingEntry, runtime);
  if (value == null || !bindingEntry.targetNode) {
    sourcePlaybackDiagnostic(runtime, "binding-target-unavailable", bindingEntry.id);
    return;
  }
  const binding = bindingEntry.binding;
  const parameters = binding.parameters && typeof binding.parameters === "object" ? binding.parameters : {};
  const threshold = finiteSourcePlaybackNumber(parameters.visibleThreshold, binding.visibleThreshold, binding.threshold, 0.001);
  const opacityMinimum = finiteSourcePlaybackNumber(parameters.opacityMinimum, parameters.minOpacity, binding.opacityMinimum, binding.minOpacity, 0);
  const opacityMaximum = finiteSourcePlaybackNumber(parameters.opacityMaximum, parameters.maxOpacity, binding.opacityMaximum, binding.maxOpacity, 1);
  const fullOpacityThreshold = finiteSourcePlaybackNumber(
    parameters.fullOpacityThreshold,
    parameters.opaqueThreshold,
    binding.fullOpacityThreshold,
    binding.opaqueThreshold,
    0.99,
  );
  const clampedOpacity = Math.max(opacityMinimum, Math.min(opacityMaximum, value));
  const opacity = snapVisibilityOpacityEndpoint(clampedOpacity, opacityMaximum, fullOpacityThreshold);
  const visible = binding.visibility === false ? true : value >= threshold;
  const renderables = sourcePlaybackRenderableNodes(bindingEntry.targetNode, parameters.recursive !== false && binding.recursive !== false);
  for (const node of renderables) {
    if (!("storyvrSourcePartBaseVisible" in node.userData)) node.userData.storyvrSourcePartBaseVisible = node.visible !== false;
    node.userData.storyvrSourceBindingVisible = visible;
    updateSourceRenderableVisibility(node);
    const materials = Array.isArray(node.material) ? node.material : [node.material];
    for (const material of materials) {
      if (!material) continue;
      material.userData = { ...(material.userData || {}), storyvrSourceBindingOpacity: opacity };
      updatePreviewMaterialOpacity(material);
    }
  }
}

function applySourcePlaybackDrawRange(bindingEntry, runtime) {
  const value = sourcePlaybackBindingValue(bindingEntry, runtime);
  if (value == null || !bindingEntry.targetNode) {
    sourcePlaybackDiagnostic(runtime, "binding-target-unavailable", bindingEntry.id);
    return;
  }
  const progress = clampSourcePlaybackProgress(value, 0);
  const parameters = bindingEntry.binding.parameters && typeof bindingEntry.binding.parameters === "object" ? bindingEntry.binding.parameters : {};
  for (const node of sourcePlaybackRenderableNodes(bindingEntry.targetNode, parameters.recursive !== false && bindingEntry.binding.recursive !== false)) {
    const geometry = node.geometry;
    if (!geometry?.setDrawRange) continue;
    if (!geometry.userData.storyvrSourceDrawRange) {
      const availableCount = Number.isFinite(geometry.drawRange?.count) && geometry.drawRange.count !== Infinity
        ? geometry.drawRange.count
        : geometry.index?.count || geometry.attributes?.position?.count || 0;
      geometry.userData.storyvrSourceDrawRange = {
        start: Number.isFinite(geometry.drawRange?.start) ? geometry.drawRange.start : 0,
        count: Math.max(0, availableCount),
      };
    }
    const base = geometry.userData.storyvrSourceDrawRange;
    const reverse = (parameters.direction || bindingEntry.binding.direction) === "reverse";
    const count = Math.max(0, Math.round(base.count * progress));
    const start = reverse ? base.start + Math.max(0, base.count - count) : base.start;
    geometry.setDrawRange(start, count);
  }
}

function applySourcePlaybackCameraFocalLength(bindingEntry, runtime) {
  const value = sourcePlaybackBindingValue(bindingEntry, runtime);
  const camera = bindingEntry.targetNode?.isCamera ? bindingEntry.targetNode : runtime.sourceCamera;
  if (value == null || !camera?.setFocalLength) {
    sourcePlaybackDiagnostic(runtime, "camera-focal-target-unavailable", bindingEntry.id);
    return;
  }
  if (!Number.isFinite(camera.userData.storyvrSourceBaseFocalLength)) {
    camera.userData.storyvrSourceBaseFocalLength = camera.getFocalLength?.() || 35;
  }
  const parameters = bindingEntry.binding.parameters && typeof bindingEntry.binding.parameters === "object" ? bindingEntry.binding.parameters : {};
  const declaredBase = finiteSourcePlaybackNumber(parameters.baseFocalLength, parameters.baseValue, bindingEntry.binding.baseFocalLength, bindingEntry.binding.baseValue);
  const base = declaredBase ?? camera.userData.storyvrSourceBaseFocalLength;
  const focalLength = Math.max(0.001, base + value);
  camera.setFocalLength(focalLength);
  camera.updateProjectionMatrix?.();
}

function applySourcePlaybackAnnotationOpacity(bindingEntry, runtime) {
  const value = sourcePlaybackBindingValue(bindingEntry, runtime);
  const annotationId = String(
    bindingEntry.binding.target?.annotationId
    || bindingEntry.binding.annotationId
    || bindingEntry.binding.targetAnnotationId
    || "",
  ).trim();
  const annotation = runtime.annotations.get(annotationId);
  if (value == null || !annotation) {
    sourcePlaybackDiagnostic(runtime, "annotation-target-unavailable", bindingEntry.id || annotationId);
    return;
  }
  const parameters = bindingEntry.binding.parameters && typeof bindingEntry.binding.parameters === "object" ? bindingEntry.binding.parameters : {};
  const opacity = clampSourcePlaybackProgress(value, 0);
  annotation.opacity = opacity;
  annotation.sprite.visible = opacity > (finiteSourcePlaybackNumber(parameters.visibleThreshold, parameters.threshold, bindingEntry.binding.visibleThreshold, bindingEntry.binding.threshold, 0.001));
  annotation.sprite.material.userData = { ...(annotation.sprite.material.userData || {}), storyvrSourceBindingOpacity: opacity };
  updatePreviewMaterialOpacity(annotation.sprite.material);
}

function sourcePlaybackAnnotationPresentation(asset, definition) {
  const assetStyle = asset?.presentation?.annotations;
  const definitionStyle = definition?.presentation;
  return {
    ...(assetStyle && typeof assetStyle === "object" ? assetStyle : {}),
    ...(definitionStyle && typeof definitionStyle === "object" ? definitionStyle : {}),
  };
}

function sourcePlaybackAnnotationLines(text, maxLineCharacters = 44) {
  const words = String(text || "").trim().split(/\s+/).filter(Boolean);
  if (!words.length) return [""];
  const maximum = Math.max(18, Math.min(72, Math.round(Number(maxLineCharacters) || 44)));
  const lines = [];
  let line = "";
  for (const word of words) {
    const candidate = line ? `${line} ${word}` : word;
    if (line && candidate.length > maximum) {
      lines.push(line);
      line = word;
    } else {
      line = candidate;
    }
  }
  if (line) lines.push(line);
  return lines.slice(0, 3);
}

function sourcePlaybackAnnotationLayout(text, definition, presentation) {
  const lines = sourcePlaybackAnnotationLines(
    text,
    finiteSourcePlaybackNumber(definition?.maxLineCharacters, presentation?.maxLineCharacters, 44),
  );
  const longestLine = lines.reduce((longest, line) => Math.max(longest, line.length), 0);
  const defaultHeight = lines.length === 1 ? 0.28 : 0.08 + lines.length * 0.22;
  return {
    lines,
    width: finiteSourcePlaybackNumber(
      definition?.width,
      presentation?.width,
      THREE.MathUtils.clamp(0.38 + longestLine * 0.06, 0.7, 4),
    ),
    height: finiteSourcePlaybackNumber(definition?.height, presentation?.height, defaultHeight),
  };
}

function initializeFinalReviewSourcePlaybackAnnotationElement(viewer, id, text, definition, presentation) {
  if (viewer?.componentId !== "transition-pacing" || !viewer.renderer?.domElement?.parentElement) return null;
  const container = viewer.renderer.domElement.parentElement;
  const element = document.createElement("div");
  const background = definition.background ?? presentation.background ?? "rgba(255,253,244,0.9)";
  const transparentBackground = !background || String(background).trim().toLowerCase() === "transparent";
  element.dataset.storyvrSourceAnnotation = id;
  element.textContent = text;
  Object.assign(element.style, {
    position: "absolute",
    left: "0",
    top: "0",
    zIndex: "4",
    pointerEvents: "none",
    padding: transparentBackground ? "0" : "0.28rem 0.5rem",
    borderRadius: transparentBackground ? "0" : "0.35rem",
    color: String(definition.color ?? presentation.color ?? "#10201c"),
    background: String(background || "transparent"),
    font: `${Number(definition.fontWeight ?? presentation.fontWeight) || 600} 12px/1.25 system-ui, sans-serif`,
    maxWidth: String(definition.maxWidth ?? presentation.maxWidth ?? "min(32rem, calc(100% - 24px))"),
    whiteSpace: String(definition.whiteSpace ?? presentation.whiteSpace ?? "normal"),
    textAlign: "center",
    opacity: "0",
    visibility: "hidden",
    transform: "translate(-50%, -100%)",
  });
  container.appendChild(element);
  return element;
}

function initializeSourcePlaybackAnnotations(viewer, entry, runtime) {
  // Contract annotations belong to the source asset's coordinate space. Keeping
  // them under the normalized GLB root preserves their intended scale and stops
  // fixed-size authoring sprites from expanding scene-fit bounds.
  const parent = runtime.root || entry.wrapper || entry.group || viewer.root;
  for (const [index, definition] of runtime.asset.annotations.entries()) {
    if (!sourcePlaybackAnnotationIsReaderVisible(definition)) continue;
    const id = String(definition.id || definition.annotationId || `annotation:${index}`).trim();
    const text = String(definition.text || definition.label || "").trim();
    if (!text) {
      sourcePlaybackDiagnostic(runtime, "annotation-text-missing", id);
      continue;
    }
    const mode = String(definition.mode || definition.placement || "world").trim().toLowerCase();
    if (!["world", "fixed", "node"].includes(mode)) {
      sourcePlaybackDiagnostic(runtime, "unsupported-annotation-mode", `${id}:${mode}`);
      continue;
    }
    const position = definition.position && typeof definition.position === "object" ? definition.position : {};
    const presentation = sourcePlaybackAnnotationPresentation(runtime.asset, definition);
    const layout = sourcePlaybackAnnotationLayout(text, definition, presentation);
    const sprite = makeTextSprite(text, {
      authoredSceneText: true,
      width: layout.width,
      height: layout.height,
      lines: layout.lines,
      x: finiteSourcePlaybackNumber(position.x, definition.x, 0),
      y: finiteSourcePlaybackNumber(position.y, definition.y, 0.9),
      z: finiteSourcePlaybackNumber(position.z, definition.z, 0),
      color: definition.color ?? presentation.color ?? "#10201c",
      background: definition.background ?? presentation.background ?? "rgba(255,253,244,0.9)",
      fontWeight: definition.fontWeight ?? presentation.fontWeight,
      depthTest: definition.depthTest ?? presentation.depthTest ?? false,
      depthWrite: definition.depthWrite ?? presentation.depthWrite ?? false,
      toneMapped: definition.toneMapped ?? presentation.toneMapped ?? false,
      renderOrder: definition.renderOrder ?? presentation.renderOrder ?? 9000,
    });
    parent.add(sprite);
    entry.opacityMaterials?.push(...preparePreviewOpacityTarget(sprite));
    const targetNode = sourcePlaybackFindNode(runtime.root, definition.node || definition.nodeName || definition.target);
    const element = initializeFinalReviewSourcePlaybackAnnotationElement(
      viewer,
      id,
      text,
      definition,
      presentation,
    );
    runtime.annotations.set(id, {
      id,
      definition,
      presentation,
      sprite,
      element,
      parent,
      targetNode,
      opacity: 1,
      projectedPosition: new THREE.Vector3(),
      worldPosition: new THREE.Vector3(),
    });
  }
}

function updateSourcePlaybackAnnotations(runtime) {
  const worldPosition = new THREE.Vector3();
  for (const annotation of runtime.annotations.values()) {
    if (annotation.targetNode) {
      annotation.targetNode.updateWorldMatrix?.(true, false);
      annotation.targetNode.getWorldPosition(worldPosition);
      annotation.parent.updateWorldMatrix?.(true, false);
      annotation.sprite.position.copy(annotation.parent.worldToLocal(worldPosition.clone()));
      const offset = annotation.definition.offset;
      if (offset && typeof offset === "object") {
        annotation.sprite.position.x += Number(offset.x) || 0;
        annotation.sprite.position.y += Number(offset.y) || 0;
        annotation.sprite.position.z += Number(offset.z) || 0;
      }
    }
    const opacitySource = annotation.definition.opacitySource;
    if (opacitySource && typeof opacitySource === "object") {
      const sourceNode = sourcePlaybackFindNode(runtime.root, opacitySource.node || opacitySource.nodeName);
      const value = sourcePlaybackReadPath(sourceNode, opacitySource.path || "scale.x", annotation.opacity);
      annotation.opacity = clampSourcePlaybackProgress(value, annotation.opacity);
      annotation.sprite.visible = annotation.opacity > (finiteSourcePlaybackNumber(annotation.definition.visibleThreshold, annotation.definition.threshold, 0.001));
      annotation.sprite.material.userData = { ...(annotation.sprite.material.userData || {}), storyvrSourceBindingOpacity: annotation.opacity };
      updatePreviewMaterialOpacity(annotation.sprite.material);
    }
    const visibleThreshold = finiteSourcePlaybackNumber(
      annotation.definition.visibleThreshold,
      annotation.definition.threshold,
      0.001,
    );
    const annotationVisible = annotation.opacity > visibleThreshold;
    const viewer = runtime.viewer;
    const xrPresenting = viewer?.renderer?.xr?.isPresenting === true;
    annotation.sprite.visible = annotationVisible && (!annotation.element || xrPresenting);
    if (!annotation.element || !viewer?.renderer?.domElement) continue;
    if (!annotationVisible || xrPresenting) {
      annotation.element.style.visibility = "hidden";
      annotation.element.style.opacity = "0";
      continue;
    }
    const renderCamera = finalReviewRenderCamera(viewer);
    annotation.sprite.updateWorldMatrix?.(true, false);
    annotation.sprite.getWorldPosition(annotation.worldPosition);
    annotation.projectedPosition.copy(annotation.worldPosition).project(renderCamera);
    const canvasBounds = viewer.renderer.domElement.getBoundingClientRect();
    const containerBounds = viewer.renderer.domElement.parentElement.getBoundingClientRect();
    const elementBounds = annotation.element.getBoundingClientRect();
    const margin = Math.max(
      0,
      Number(annotation.definition.viewportMargin ?? annotation.presentation.viewportMargin) || 12,
    );
    const x = canvasBounds.left - containerBounds.left
      + (annotation.projectedPosition.x * 0.5 + 0.5) * canvasBounds.width;
    const y = canvasBounds.top - containerBounds.top
      + (-annotation.projectedPosition.y * 0.5 + 0.5) * canvasBounds.height;
    const minimumLeft = canvasBounds.left - containerBounds.left + margin + elementBounds.width / 2;
    const maximumLeft = canvasBounds.right - containerBounds.left - margin - elementBounds.width / 2;
    const minimumTop = canvasBounds.top - containerBounds.top + margin + elementBounds.height;
    const maximumTop = canvasBounds.bottom - containerBounds.top - margin;
    const left = maximumLeft >= minimumLeft
      ? THREE.MathUtils.clamp(x, minimumLeft, maximumLeft)
      : canvasBounds.left - containerBounds.left + canvasBounds.width / 2;
    const top = maximumTop >= minimumTop
      ? THREE.MathUtils.clamp(y, minimumTop, maximumTop)
      : canvasBounds.top - containerBounds.top + canvasBounds.height / 2;
    annotation.element.style.left = `${left}px`;
    annotation.element.style.top = `${top}px`;
    annotation.element.style.opacity = String(annotation.opacity);
    annotation.element.style.visibility = annotation.projectedPosition.z >= -1 && annotation.projectedPosition.z <= 1
      ? "visible"
      : "hidden";
  }
}

function initializeSourcePlaybackBindings(runtime) {
  const supported = new Set(["visibility", "visibility-opacity", "draw-range", "draw-range-progress", "material-uniform", "camera-focal-length", "annotation-opacity"]);
  runtime.bindingEntries = runtime.asset.bindings.map((binding, index) => {
    const operation = String(binding.operation || binding.op || "").trim().toLowerCase().replace(/_/g, "-");
    const source = binding.source && typeof binding.source === "object" ? binding.source : {};
    const target = binding.target && typeof binding.target === "object" ? binding.target : {};
    const targetCameraIndex = finiteSourcePlaybackNumber(target.cameraIndex, binding.targetCameraIndex);
    const entry = {
      id: String(binding.id || `binding:${index}`),
      operation,
      binding,
      sourceNode: sourcePlaybackFindNode(runtime.root, source.node || source.nodeName || binding.sourceNode || binding.driverNode),
      targetNode: Number.isInteger(targetCameraIndex) && targetCameraIndex >= 0
        ? runtime.cameras?.[targetCameraIndex] || null
        : sourcePlaybackFindNode(runtime.root, target.node || target.nodeName || binding.targetNode),
    };
    const sourceType = String(source.type || binding.sourceType || "").trim().toLowerCase().replace(/_/g, "-");
    const sourceNeedsNode = !["timeline-progress", "timeline-time", "wall-clock-time", "constant"].includes(sourceType)
      && finiteSourcePlaybackNumber(binding.value) == null;
    if (!supported.has(operation)) sourcePlaybackDiagnostic(runtime, "unsupported-binding-operation", `${entry.id}:${operation || "missing"}`);
    else if (sourceNeedsNode && !entry.sourceNode) sourcePlaybackDiagnostic(runtime, "binding-source-unavailable", entry.id);
    return entry;
  });
}

function applySourcePlaybackBindings(runtime) {
  for (const bindingEntry of runtime.bindingEntries || []) {
    if (bindingEntry.operation === "visibility") applySourcePlaybackVisibility(bindingEntry, runtime);
    else if (bindingEntry.operation === "visibility-opacity") applySourcePlaybackVisibilityOpacity(bindingEntry, runtime);
    else if (["draw-range", "draw-range-progress"].includes(bindingEntry.operation)) applySourcePlaybackDrawRange(bindingEntry, runtime);
    else if (bindingEntry.operation === "material-uniform") applySourcePlaybackMaterialUniform(bindingEntry, runtime);
    else if (bindingEntry.operation === "camera-focal-length") applySourcePlaybackCameraFocalLength(bindingEntry, runtime);
    else if (bindingEntry.operation === "annotation-opacity") applySourcePlaybackAnnotationOpacity(bindingEntry, runtime);
  }
}

function sourcePlaybackClipDescriptors(asset, windowState) {
  const descriptors = [...asset.coordinatedClips];
  const cameraIndexes = Array.isArray(asset.camera?.clipIndexes) ? asset.camera.clipIndexes : [];
  for (const clipIndex of cameraIndexes) {
    const descriptor = normalizeSourcePlaybackClip(clipIndex);
    if (descriptor && !descriptors.some((candidate) => candidate.clipIndex === descriptor.clipIndex)) descriptors.push(descriptor);
  }
  if (asset.mode === "shared-timeline") return descriptors;
  const requestedIndexes = new Set([
    ...(windowState.boundary?.contributorClipIndexes || []),
    ...(Array.isArray(windowState.beatState?.clipIndexes) ? windowState.beatState.clipIndexes : []),
  ].map(Number).filter((index) => Number.isInteger(index) && index >= 0));
  if (!requestedIndexes.size) return [];
  return descriptors.filter((descriptor) => descriptor.clipIndex != null && requestedIndexes.has(descriptor.clipIndex));
}

function sourcePlaybackAnimationClips(descriptors, clips) {
  const selected = [];
  const seen = new Set();
  for (const descriptor of descriptors) {
    const clip = descriptor.clipIndex != null ? clips[descriptor.clipIndex] : clips.find((candidate) => candidate.name === descriptor.clipName);
    if (!clip || seen.has(clip)) continue;
    seen.add(clip);
    selected.push({ descriptor, clip });
  }
  return selected;
}

function configureSourcePlaybackAction(action, loopMode) {
  if (!action) return null;
  const mode = String(loopMode || "once").trim().toLowerCase();
  action.reset();
  action.clampWhenFinished = false;
  if (["repeat", "loop"].includes(mode)) action.setLoop(THREE.LoopRepeat, Infinity);
  else if (["ping-pong", "pingpong"].includes(mode)) action.setLoop(THREE.LoopPingPong, Infinity);
  else {
    action.setLoop(THREE.LoopOnce, 1);
    action.clampWhenFinished = true;
  }
  action.play();
  return action;
}

function sourcePlaybackCameraIndex(camera) {
  const value = camera?.cameraIndex;
  if (value == null || value === "") return null;
  const index = Number(value);
  return Number.isInteger(index) && index >= 0 ? index : null;
}

function sourcePlaybackAssetUsesDesktopSourceCamera(asset) {
  if (asset?.mode !== "shared-timeline" || sourcePlaybackCameraIndex(asset.camera) == null) return false;
  const policy = String(asset.camera?.desktopPolicy || "").trim().toLowerCase();
  return ["render-source-camera", "source-camera"].includes(policy);
}

function dynamicPreviewDeclaresSharedSourceCamera(viewer) {
  if (viewer?.componentId !== "dynamic-geometry" || !viewer?.beat?.id) return false;
  const assetIds = (viewer.assetLinks || [])
    .map((link) => String(link?.assetId || "").trim())
    .filter(Boolean);
  return assetIds.some((assetId) => {
    const asset = sourcePlaybackAssetForId(assetId);
    if (!sourcePlaybackAssetUsesDesktopSourceCamera(asset)) return false;
    const windowState = sourcePlaybackWindowForAsset(asset, "", viewer.beat.id, {
      beatId: viewer.beat.id,
      forceHold: true,
    });
    return sourcePlaybackWindowKeepsAssetActive(windowState);
  });
}

function dynamicSourceCameraPlaybackEntry(viewer) {
  if (viewer?.componentId !== "dynamic-geometry") return null;
  const entries = [
    ...(Array.isArray(viewer.dynamicObjects) ? viewer.dynamicObjects : []),
    ...(Array.isArray(viewer.swapGroups) ? viewer.swapGroups : []),
  ];
  return entries.find((entry) => (
    entry?.sourcePlaybackContractActive === true
    && sourcePlaybackAssetUsesDesktopSourceCamera(entry.sourcePlayback?.asset)
    && entry.sourcePlayback?.sourceCamera
  )) || null;
}

function sourcePlaybackUsesDeclaredCamera(viewer) {
  return Boolean(viewer?.sourcePlaybackCameraDeclared && viewer?.sourceCamera && viewer?.sourcePlaybackCameraPolicy !== "disabled");
}

function seekSourceTransitionPlayback(entry, progress, clockSeconds = 0) {
  const runtime = entry?.sourcePlayback;
  const normalizedProgress = clampSourcePlaybackProgress(progress, null);
  if (!runtime?.mixer || normalizedProgress == null) return false;
  runtime.progress = normalizedProgress;
  runtime.clockSeconds = Number(clockSeconds) || 0;
  runtime.mixer.setTime(runtime.masterDuration * normalizedProgress);
  applySourcePlaybackBindings(runtime);
  updateSourcePlaybackAnnotations(runtime);
  updateStoryVrPointCloudEffects(runtime.root, runtime.masterDuration * normalizedProgress);
  return true;
}

function updateSourceTransitionPlayback(viewer, entry) {
  const runtime = entry?.sourcePlayback;
  if (!runtime) return false;
  runtime.clockSeconds = Number(viewer?.elapsed) || 0;
  if (runtime.windowState.mode === "scrub" && !entry.sourcePartFrozen) {
    const cycleProgress = previewCycleProgress(viewer);
    const sourceProgress = runtime.windowState.startProgress + cycleProgress * (
      runtime.windowState.endProgress - runtime.windowState.startProgress
    );
    seekSourceTransitionPlayback(entry, sourceProgress, viewer.elapsed);
  } else applySourcePlaybackBindings(runtime);
  return true;
}

function attachFinalReviewSourcePlayback(viewer, entry, gltf) {
  if (viewer?.componentId !== "transition-pacing") return false;
  if (viewer.finalReviewTransitionPlayback) {
    return Boolean(entry?.sourcePlayback || entry?.mixer);
  }
  const assetId = entry?.assetId || entry?.step?.assetId;
  const asset = sourcePlaybackAssetForId(assetId);
  if (asset?.mode !== "shared-timeline") return false;
  return attachSourceTransitionPlayback(viewer, entry, gltf);
}

function sourcePlaybackSceneVisibleForViewer(viewer, entry, contractActive) {
  if (contractActive === true) return true;
  // Transition owns appearance while it is actively presenting a boundary.
  // Every other authoring preview inherits scene membership from Spatial
  // Relations, so an absent motion window may pause a model but cannot remove
  // an explicitly saved scene entity.
  if (viewerExecutesInterBeatTransition(viewer)) return false;
  if (viewer?.componentId === SPATIAL_RELATIONS_COMPONENT_ID) return true;
  const spatialEntityId = entry?.entity?.id
    || entry?.entityId
    || entry?.step?.entityId
    || entry?.authorWrapper?.userData?.spatialEntityId
    || "";
  return Boolean(String(spatialEntityId).trim());
}

function attachSourceTransitionPlayback(viewer, entry, gltf) {
  const assetId = entry.assetId || entry.step?.assetId;
  const asset = sourcePlaybackAssetForId(assetId);
  if (!asset) {
    return false;
  }
  entry.usesSourceAnimation = true;
  const destinationBeatId = viewer.sourceMotionTransition?.toBeatId
    || viewer.sourcePartToBeatId
    || viewer.beat?.id
    || "";
  const windowState = typeof viewer.resolveSourcePlaybackWindow === "function"
    ? viewer.resolveSourcePlaybackWindow(asset)
    : sourcePlaybackWindowForAsset(
      asset,
      viewer.sourceMotionTransition?.fromBeatId || "",
      destinationBeatId,
      { beatId: destinationBeatId, forceHold: viewer.sourcePartPlaybackMode === "frozen" || !viewer.sourceMotionTransition },
    );
  const runtime = {
    asset,
    viewer,
    root: gltf.scene,
    windowState,
    mixer: null,
    actions: [],
    masterDuration: asset.timeline.durationSeconds,
    bindings: [],
    bindingEntries: [],
    materialRecipes: new Map(),
    annotations: new Map(),
    diagnostics: [],
    diagnosticKeys: new Set(),
    cameras: Array.isArray(gltf?.cameras) ? gltf.cameras : [],
    sourceCamera: null,
    progress: null,
    clockSeconds: 0,
  };
  entry.sourcePlayback = runtime;
  entry.sourcePlaybackDiagnostics = runtime.diagnostics;
  entry.sourcePlaybackContractActive = sourcePlaybackWindowKeepsAssetActive(windowState);
  gltf.scene.visible = sourcePlaybackSceneVisibleForViewer(viewer, entry, entry.sourcePlaybackContractActive);
  if (windowState.mode === "none") {
    if (![SPATIAL_RELATIONS_COMPONENT_ID, "interaction-control"].includes(viewer.componentId)) {
      sourcePlaybackDiagnostic(runtime, "no-mapped-source-window", `${viewer.sourceMotionTransition?.fromBeatId || ""}->${viewer.sourceMotionTransition?.toBeatId || viewer.sourcePartToBeatId || ""}`);
    }
    return true;
  }
  if (!Array.isArray(gltf?.animations) || !gltf.animations.length) {
    sourcePlaybackDiagnostic(runtime, "asset-has-no-animation-clips", asset.assetId);
    return true;
  }
  const selectedClips = sourcePlaybackAnimationClips(sourcePlaybackClipDescriptors(asset, windowState), gltf.animations);
  if (!selectedClips.length) {
    sourcePlaybackDiagnostic(runtime, "coordinated-clips-unavailable", asset.assetId);
    return true;
  }
  if (!(runtime.masterDuration > 0)) {
    runtime.masterDuration = Math.max(...selectedClips.map(({ clip }) => Number(clip.duration) || 0), 0);
  }
  if (!(runtime.masterDuration > 0)) {
    sourcePlaybackDiagnostic(runtime, "timeline-duration-unavailable", asset.assetId);
    return true;
  }
  if (viewer.sourcePlaybackSummary?.assetId === asset.assetId) {
    viewer.previewCycleSeconds = sourcePlaybackScrubCycleSeconds(asset, windowState, viewer.previewCycleSeconds, runtime.masterDuration);
  }
  const mixer = new THREE.AnimationMixer(gltf.scene);
  runtime.mixer = mixer;
  runtime.actions = selectedClips.map(({ descriptor, clip }) => {
    const action = mixer.clipAction(clip);
    const loopMode = String(descriptor.loopMode || asset.timeline.defaultLoopMode || "once").toLowerCase();
    return configureSourcePlaybackAction(action, loopMode);
  });
  entry.mixer = mixer;
  entry.sourceMotionDuration = runtime.masterDuration;
  entry.sourceMotionStartProgress = windowState.startProgress ?? windowState.holdProgress ?? 0;
  entry.sourceMotionEndProgress = windowState.endProgress ?? windowState.holdProgress ?? entry.sourceMotionStartProgress;
  const cameraIndex = sourcePlaybackCameraIndex(asset.camera);
  runtime.sourceCamera = cameraIndex != null ? gltf?.cameras?.[cameraIndex] || null : null;
  if (runtime.sourceCamera) {
    const desktopPolicy = String(asset.camera?.desktopPolicy || "source").trim().toLowerCase();
    viewer.sourceCamera = runtime.sourceCamera;
    viewer.sourcePlaybackCameraDeclared = true;
    viewer.sourcePlaybackCameraPolicy = ["disabled", "author", "orbit", "manual"].includes(desktopPolicy) ? "disabled" : "source";
    if (viewer.sourceCameraCuePending || state.sourceCameraPreviewEnabled) requestSourceCameraCue(viewer);
  }
  initializeSourcePlaybackMaterials(runtime);
  initializeSourcePlaybackAnnotations(viewer, entry, runtime);
  initializeSourcePlaybackBindings(runtime);
  const initialProgress = windowState.mode === "scrub" ? windowState.startProgress : windowState.holdProgress;
  entry.sourcePartFrozen = windowState.mode !== "scrub";
  seekSourceTransitionPlayback(entry, initialProgress, 0);
  if (viewer.componentId === "inter-beat-dynamics") updateSourceCameraEvidenceFromRuntime(viewer, entry);
  return true;
}

function dynamicSourceMotionTracksForPreview(viewer, assetId) {
  if (viewer?.componentId !== "dynamic-geometry" || !assetId || !viewer?.beat?.id) return [];
  const beatIds = new Set(uniqueMotionBeatIds([viewer.beat.id, ...(viewer.beat.atomicBeatIds || [])]));
  return eligibleSourceMotionTracks("dynamic-geometry").filter((track) => (
    track.assetId === assetId
    && uniqueMotionBeatIds(sourceMotionDraftForTrack(track)?.beatIds || []).some((beatId) => beatIds.has(beatId))
  ));
}

function uniqueSourceMotionClips(tracks, clips) {
  const selected = [];
  const seen = new Set();
  for (const clip of tracks.flatMap((track) => sourceMotionClipsForTrack(track, clips))) {
    const key = clip.uuid || `${clip.name}|${clip.duration}`;
    if (seen.has(key)) continue;
    seen.add(key);
    selected.push(clip);
  }
  return selected;
}

function viewerExecutesInterBeatTransition(viewer) {
  return Boolean(
    viewer?.componentId === "inter-beat-dynamics"
    || (
      viewer?.componentId === "transition-pacing"
      && viewer.finalReviewTransitionPlayback
    )
  );
}

function attachSourceDynamicsPreviewAnimation(viewer, entry, gltf) {
  if (!viewer || (viewer.componentId !== "dynamic-geometry" && !viewerExecutesInterBeatTransition(viewer))) return;
  const assetId = entry.assetId || entry.step?.assetId;
  if (
    viewer.componentId === "dynamic-geometry"
    && sourcePlaybackAssetForId(assetId)?.mode === "shared-timeline"
    && attachSourceTransitionPlayback(viewer, entry, gltf)
  ) return;
  if (viewerExecutesInterBeatTransition(viewer)) {
    if (!viewer.manualVariantSwitch && !viewer.routeScopedTransition && attachSourceTransitionPlayback(viewer, entry, gltf)) return;
    if (viewer.sourcePartPlaybackMode === "frozen") {
      attachFrozenSourcePartPose(viewer, entry, gltf);
      return;
    }
  }
  const variantAnimationSpec = viewer.manualVariantSwitch
    ? viewer.variantTransitionAnimationSpec
    : null;
  const selectedTrack = viewerExecutesInterBeatTransition(viewer)
    ? (variantAnimationSpec?.tracks || []).find((track) => track.assetId === assetId)
      || (viewer.legacySourceMotionTracks || []).find((track) => track.assetId === assetId)
      || (viewer.thumbnailMode ? null : selectedSourceMotionTrack(viewer.componentId))
    : null;
  if (
    viewerExecutesInterBeatTransition(viewer)
    && selectedTrack?.assetId === assetId
    && (viewer.thumbnailMode || state.sourceCameraPreviewEnabled)
    && sourceMotionTrackIsCamera(selectedTrack)
  ) {
    const cameraIndex = Number.isFinite(Number(selectedTrack.cameraIndex)) ? Number(selectedTrack.cameraIndex) : 0;
    const sourceCamera = gltf?.cameras?.[cameraIndex] || gltf?.cameras?.[0] || null;
    if (sourceCamera) {
      viewer.sourceCamera = sourceCamera;
      viewer.sourceCameraTrackId = selectedTrack.id;
      if (!viewer.thumbnailMode) requestSourceCameraCue(viewer);
    }
  }
  if (!Array.isArray(gltf?.animations) || !gltf.animations.length) return;
  if (viewer.componentId === "dynamic-geometry" && viewerDynamicGeometryKind(viewer) === "none") return;
  const tracks = viewer.componentId === "dynamic-geometry"
    ? dynamicSourceMotionTracksForPreview(viewer, assetId)
    : variantAnimationSpec?.assetId === assetId
      ? variantAnimationSpec.tracks || []
      : (selectedTrack?.assetId === assetId ? [selectedTrack] : []);
  const sourceDynamics = sourceDynamicsForPreviewAsset(viewer, assetId);
  const sourceBeatIds = new Set(uniqueMotionBeatIds(sourceDynamics?.beatIds || []));
  const currentBeatIds = new Set(uniqueMotionBeatIds([viewer?.beat?.id, ...(viewer?.beat?.atomicBeatIds || [])]));
  const sourceDynamicsMatchesBeat = !sourceBeatIds.size || [...currentBeatIds].some((beatId) => sourceBeatIds.has(beatId));
  const fallbackToEmbeddedClips = (
    viewer.componentId === "dynamic-geometry"
    && !tracks.length
    && !eligibleSourceMotionTracks("dynamic-geometry").length
    && sourceDynamics?.hasEmbeddedAnimation
    && sourceDynamicsMatchesBeat
  ) || (
    viewer.manualVariantSwitch
    && variantAnimationSpec?.assetId === assetId
    && variantAnimationSpec.useAllEmbeddedClips
  );
  const clips = fallbackToEmbeddedClips
    ? gltf.animations
    : uniqueSourceMotionClips(tracks, gltf.animations);
  if (!clips.length) return;
  const mixer = new THREE.AnimationMixer(gltf.scene);
  const actions = clips.map((clip) => mixer.clipAction(clip));
  for (const action of actions) {
    action.reset();
    if (viewerExecutesInterBeatTransition(viewer)) {
      action.setLoop(THREE.LoopOnce, 1);
      action.clampWhenFinished = true;
    } else {
      action.setLoop(THREE.LoopRepeat, Infinity);
    }
    action.play();
  }
  entry.mixer = mixer;
  entry.usesSourceAnimation = true;
  entry.sourceMotionTrackIds = tracks.map((track) => track.id);
  entry.sourceMotionTrackId = tracks[0]?.id || null;
  entry.sourceMotionDuration = Math.max(...clips.map((clip) => Number(clip.duration) || 0), ...tracks.map((track) => Number(track.duration) || 0), 0.001);
  const previewTransition = sourceMotionTransitionAssignmentForPreview(selectedTrack, viewer);
  entry.sourceMotionStartProgress = Number.isFinite(Number(previewTransition?.startProgress)) ? Number(previewTransition.startProgress) : 0;
  entry.sourceMotionEndProgress = Number.isFinite(Number(previewTransition?.endProgress)) ? Number(previewTransition.endProgress) : 1;
}

function attachFrozenSourcePartPose(viewer, entry, gltf) {
  const assetId = entry.assetId || entry.step?.assetId;
  const partState = sourcePartStatesForPreviewBeat(viewer.sourcePartToBeatId, assetId)
    .find((item) => item.playbackMode === "frozen");
  if (!partState || !Array.isArray(gltf?.animations) || !gltf.animations.length) return;
  const requestedIndexes = new Set((partState.animations || [])
    .map((animation) => Number(animation.clipIndex))
    .filter((index) => Number.isInteger(index) && index >= 0));
  const requestedNames = new Set((partState.animations || []).map((animation) => animation.clipName).filter(Boolean));
  const clips = gltf.animations.filter((clip, index) => requestedIndexes.has(index) || requestedNames.has(clip.name));
  if (!clips.length) return;
  const freezeProgress = Math.max(0, Math.min(1, Number(partState.freezeProgress) || 0));
  const mixer = new THREE.AnimationMixer(gltf.scene);
  const actions = clips.map((clip) => mixer.clipAction(clip));
  for (const action of actions) {
    action.reset();
    action.setLoop(THREE.LoopOnce, 1);
    action.clampWhenFinished = true;
    action.play();
    action.paused = true;
    action.time = (Number(action.getClip()?.duration) || 0) * freezeProgress;
  }
  mixer.update(0);
  entry.mixer = mixer;
  entry.usesSourceAnimation = true;
  entry.sourcePartFrozen = true;
  entry.sourcePartFreezeProgress = freezeProgress;
}

function sourceMotionTransitionAssignmentForPreview(track, viewer) {
  const active = viewer?.sourceMotionTransition;
  if (!track || !active?.fromBeatId || !active?.toBeatId) return null;
  const authored = active.edgeId
    ? authoredMotionTransitions({ includeSameBeat: true }).find((transition) => transition.edgeId === active.edgeId)
    : null;
  if (authored) return motionTransitionAssignmentForAuthoredTransition(sourceMotionDraftForTrack(track)?.transitions, authored);
  return normalizeMotionTransitions(sourceMotionDraftForTrack(track)?.transitions).find((transition) => (
    transition.fromBeatId === active.fromBeatId && transition.toBeatId === active.toBeatId
  )) || null;
}

function sourceMotionClipsForTrack(track, clips) {
  if (!track || track.kind !== "clip" && !sourceMotionTrackIsCamera(track)) return [];
  const indexes = [
    ...(Array.isArray(track.clipIndexes) ? track.clipIndexes : []),
    track.clipIndex,
  ].filter((value) => value !== null && value !== undefined && value !== "")
    .map(Number)
    .filter((index, position, values) => Number.isInteger(index) && index >= 0 && values.indexOf(index) === position);
  if (indexes.length) return indexes.map((index) => clips[index]).filter(Boolean);
  const animationName = String(track.animationName || "");
  if (animationName) return clips.filter((clip) => clip.name === animationName);
  return [];
}

function requestSourceCameraCue(viewer) {
  if (!viewer || viewer.componentId !== "inter-beat-dynamics") return false;
  if (!viewer.thumbnailMode && !state.sourceCameraPreviewEnabled) return false;
  viewer.sourceCameraCuePending = true;
  if (!viewer.sourceCamera || (!sourcePlaybackUsesDeclaredCamera(viewer) && !state.sourceCameraPreviewEnabled)) return false;
  const targetDistance = Math.max(0.4, viewer.camera.position.distanceTo(viewer.controls.target));
  viewer.sourceCameraCue = {
    elapsed: 0,
    duration: SOURCE_CAMERA_CUE_SECONDS,
    startPosition: viewer.camera.position.clone(),
    startQuaternion: viewer.camera.quaternion.clone(),
    startTarget: viewer.controls.target.clone(),
    startFov: Number(viewer.camera.fov) || 42,
    startNear: Number(viewer.camera.near) || 0.02,
    startFar: Number(viewer.camera.far) || 1000,
    startZoom: Number(viewer.camera.zoom) || 1,
    targetDistance,
  };
  viewer.sourceCameraCuePending = false;
  return true;
}

function cancelSourceCameraCue(viewer) {
  if (!viewer) return false;
  const hadCue = Boolean(viewer.sourceCameraCue || viewer.sourceCameraCuePending);
  viewer.sourceCameraCue = null;
  viewer.sourceCameraCuePending = false;
  return hadCue;
}

function syncSourceCameraPreview(viewer, delta = 0) {
  if (viewer?.componentId === "dynamic-geometry") {
    const playbackEntry = dynamicSourceCameraPlaybackEntry(viewer);
    const sourceCamera = playbackEntry?.sourcePlayback?.sourceCamera;
    if (!sourceCamera || !viewer.camera || !viewer.controls) return false;
    sourceCamera.updateWorldMatrix(true, false);
    const targetPosition = sourceCamera.getWorldPosition(new THREE.Vector3());
    const targetQuaternion = sourceCamera.getWorldQuaternion(new THREE.Quaternion());
    const targetForward = new THREE.Vector3(0, 0, -1).applyQuaternion(targetQuaternion).normalize();
    const targetDistance = Math.max(0.4, viewer.camera.position.distanceTo(viewer.controls.target));
    viewer.camera.position.copy(targetPosition);
    viewer.camera.quaternion.copy(targetQuaternion);
    viewer.controls.target.copy(targetPosition).addScaledVector(targetForward, targetDistance);
    viewer.camera.near = Math.max(Number(sourceCamera.near) || viewer.camera.near, 0.001);
    viewer.camera.far = Math.max(Number(sourceCamera.far) || viewer.camera.far, viewer.camera.near + 1);
    if (sourceCamera.isPerspectiveCamera && viewer.camera.isPerspectiveCamera) {
      viewer.camera.fov = Number(sourceCamera.fov) || viewer.camera.fov;
      viewer.camera.zoom = Number(sourceCamera.zoom) || 1;
    }
    viewer.camera.updateProjectionMatrix();
    viewer.previewCameraFramingReady = true;
    viewer.previewCameraFramingContract = `source-playback-camera:${playbackEntry.sourcePlayback.asset.assetId}`;
    return true;
  }
  const cue = viewer?.sourceCameraCue;
  if (!cue || !viewer?.sourceCamera || viewer.componentId !== "inter-beat-dynamics") return false;
  const sourceCamera = viewer.sourceCamera;
  sourceCamera.updateWorldMatrix(true, false);
  sourceCamera.matrixWorldInverse.copy(sourceCamera.matrixWorld).invert();
  const targetPosition = sourceCamera.getWorldPosition(new THREE.Vector3());
  const targetQuaternion = sourceCamera.getWorldQuaternion(new THREE.Quaternion());
  const targetForward = new THREE.Vector3(0, 0, -1).applyQuaternion(targetQuaternion).normalize();
  const targetControlsTarget = targetPosition.clone().addScaledVector(targetForward, cue.targetDistance);
  cue.elapsed += Math.max(0, Number(delta) || 0);
  const progress = Math.max(0, Math.min(1, cue.elapsed / Math.max(cue.duration, 0.001)));
  const smooth = progress * progress * (3 - 2 * progress);
  viewer.camera.position.lerpVectors(cue.startPosition, targetPosition, smooth);
  viewer.camera.quaternion.slerpQuaternions(cue.startQuaternion, targetQuaternion, smooth);
  viewer.controls.target.lerpVectors(cue.startTarget, targetControlsTarget, smooth);
  if (sourceCamera.isPerspectiveCamera && viewer.camera.isPerspectiveCamera) {
    const targetFov = Number(sourceCamera.fov) || cue.startFov;
    const targetNear = Math.max(Number(sourceCamera.near) || cue.startNear, 0.001);
    const targetFar = Math.max(Number(sourceCamera.far) || cue.startFar, targetNear + 1);
    const targetZoom = Number(sourceCamera.zoom) || 1;
    viewer.camera.fov = THREE.MathUtils.lerp(cue.startFov, targetFov, smooth);
    viewer.camera.near = THREE.MathUtils.lerp(cue.startNear, targetNear, smooth);
    viewer.camera.far = THREE.MathUtils.lerp(cue.startFar, targetFar, smooth);
    viewer.camera.zoom = THREE.MathUtils.lerp(cue.startZoom, targetZoom, smooth);
    viewer.camera.updateProjectionMatrix();
  }
  if (progress >= 1 && !viewer.playing) viewer.sourceCameraCue = null;
  return true;
}

function seekGltfToSourceSpatialCue(gltf, cue) {
  if (!gltf || !cue) return null;
  const playback = sourcePlaybackAssetForId(cue.assetId);
  if (!playback || !Array.isArray(gltf.animations) || !gltf.animations.length) return null;
  const windowState = {
    mode: "initialize",
    beatState: { beatId: cue.beatId, localProgress: cue.sourceProgress },
    contributorClipIndexes: cue.cameraClipIndexes || [],
  };
  const selectedClips = sourcePlaybackAnimationClips(sourcePlaybackClipDescriptors(playback, windowState), gltf.animations);
  if (!selectedClips.length) return null;
  const duration = Number(playback.timeline?.durationSeconds)
    || Math.max(...selectedClips.map(({ clip }) => Number(clip.duration) || 0), 0);
  if (!(duration > 0)) return null;
  const mixer = new THREE.AnimationMixer(gltf.scene);
  const actions = selectedClips.map(({ descriptor, clip }) => configureSourcePlaybackAction(
    mixer.clipAction(clip),
    descriptor.loopMode || playback.timeline?.defaultLoopMode,
  ));
  mixer.setTime(duration * clampSourcePlaybackProgress(cue.sourceProgress, 0));
  gltf.scene.updateWorldMatrix(true, true);
  const cameraIndex = Number(cue.cameraIndex);
  const sourceCamera = Number.isInteger(cameraIndex) && cameraIndex >= 0
    ? gltf.cameras?.[cameraIndex] || null
    : null;
  return { mixer, actions, duration, sourceCamera };
}

function sourceCameraSceneEvaluation(sourceCamera, sceneRoot) {
  if (!sourceCamera || !sceneRoot) return { status: "unverified", focus: null, visibleRenderables: 0, renderables: 0, focusHit: false };
  sourceCamera.updateWorldMatrix(true, false);
  sourceCamera.matrixWorldInverse.copy(sourceCamera.matrixWorld).invert();
  sourceCamera.updateProjectionMatrix?.();
  const renderables = [];
  sceneRoot.traverse?.((node) => {
    if ((node.isMesh || node.isPoints || node.isLine) && node.visible !== false) renderables.push(node);
  });
  const projectionView = new THREE.Matrix4().multiplyMatrices(sourceCamera.projectionMatrix, sourceCamera.matrixWorldInverse);
  const frustum = new THREE.Frustum().setFromProjectionMatrix(projectionView);
  const visibleRenderables = renderables.filter((node) => {
    try {
      return frustum.intersectsObject(node);
    } catch {
      return false;
    }
  });
  const origin = sourceCamera.getWorldPosition(new THREE.Vector3());
  const direction = sourceCamera.getWorldDirection(new THREE.Vector3()).normalize();
  const raycaster = new THREE.Raycaster(origin, direction, 0.001, Number(sourceCamera.far) || 1000);
  const focusTargets = visibleRenderables.filter((node) => node.isMesh);
  const hit = raycaster.intersectObjects(focusTargets, false)[0] || null;
  const fallbackBox = new THREE.Box3();
  for (const node of visibleRenderables.length ? visibleRenderables : renderables) fallbackBox.expandByObject(node);
  const focus = hit?.point?.clone?.()
    || (!fallbackBox.isEmpty() ? fallbackBox.getCenter(new THREE.Vector3()) : origin.clone().addScaledVector(direction, 1.5));
  const status = hit ? "aligned" : visibleRenderables.length ? "partial" : "unverified";
  return {
    status,
    focus,
    visibleRenderables: visibleRenderables.length,
    renderables: renderables.length,
    focusHit: Boolean(hit),
  };
}

function applySourceSpatialCueToTextViewer(viewer, entry, gltf) {
  if (viewer?.componentId !== "text-comfort" || viewer.kind !== "object-attached" || !viewer.beat?.id) return false;
  const assetId = entry?.assetId || entry?.step?.assetId;
  const cue = sourceSpatialCueForBeat(viewer.beat.id, assetId);
  if (!cue || !gltf?.scene) return false;
  applySourcePartMask(gltf.scene, sourcePartSelectorsForBeatAsset(viewer.beat.id, assetId));
  const pose = seekGltfToSourceSpatialCue(gltf, cue);
  const evaluation = sourceCameraSceneEvaluation(pose?.sourceCamera, gltf.scene);
  if (!evaluation.focus) return false;
  viewer.sourceSpatialCue = cue;
  viewer.sourceSpatialEvaluation = evaluation;
  viewer.activeAssetId = assetId;
  viewer.activeAnchorPosition.copy(evaluation.focus);
  viewer.anchorMarker?.position.copy(evaluation.focus);
  if (viewer.placement?.coordinateSpace === "source-focus") {
    viewer.panel?.position.copy(textPlacementWorldPosition(viewer.placement, evaluation.focus));
  }
  if (viewer.calloutLine && viewer.panel) updateTextPanelCallout(viewer.calloutLine, evaluation.focus, viewer.panel.position);
  updatePreviewMetadataEntry(viewer, "source-camera-focus", `${sourceSpatialCueStatusLabel(evaluation.status)} · ${evaluation.visibleRenderables}/${evaluation.renderables} visible parts`);
  return true;
}

function applySourceSpatialCuesToInteractionViewer(viewer, entry, gltf) {
  if (viewer?.componentId !== "interaction-control" || !gltf?.scene) return false;
  const assetId = entry?.assetId || entry?.step?.assetId;
  if (!assetId) return false;
  const traversal = interactionSpatialTraversal(viewer.proposal);
  const stations = (traversal?.orderedStations || []).filter((station) => (
    station?.anchorType === "source-focus"
    && station?.anchorAssetId === assetId
    && station?.beatId
  ));
  if (!stations.length) return false;
  let resolved = 0;
  for (const station of stations) {
    const cue = sourceSpatialCueForBeat(station.beatId, assetId);
    if (!cue) continue;
    applySourcePartMask(gltf.scene, sourcePartSelectorsForBeatAsset(station.beatId, assetId));
    const pose = seekGltfToSourceSpatialCue(gltf, cue);
    viewer.root.updateWorldMatrix(true, true);
    const evaluation = sourceCameraSceneEvaluation(pose?.sourceCamera, gltf.scene);
    pose?.mixer?.stopAllAction?.();
    if (!evaluation.focus) continue;
    const rootPosition = viewer.root.worldToLocal(evaluation.focus.clone());
    viewer.interactionSourceFocus.set(`${station.beatId}:${assetId}`, rootPosition);
    resolved += 1;
  }
  if (viewer.beat?.id) {
    applySourcePartMask(gltf.scene, sourcePartSelectorsForBeatAsset(viewer.beat.id, assetId));
    const currentCue = sourceSpatialCueForBeat(viewer.beat.id, assetId);
    if (currentCue) seekGltfToSourceSpatialCue(gltf, currentCue);
  }
  return resolved > 0;
}

function sourceSpatialCueStatusLabel(status) {
  if (status === "aligned") return "Aligned";
  if (status === "partial") return "Partial";
  return "Unverified";
}

function updateSourceCameraEvidenceFromRuntime(viewer, entry) {
  const runtime = entry?.sourcePlayback;
  const assetId = entry?.assetId || entry?.step?.assetId;
  const beatId = viewer?.sourcePartToBeatId || viewer?.sourceMotionTransition?.toBeatId;
  const cue = sourceSpatialCueForBeat(beatId, assetId);
  if (!runtime?.sourceCamera || !cue) return false;
  const previousProgress = runtime.progress;
  seekSourceTransitionPlayback(entry, cue.sourceProgress, runtime.clockSeconds);
  const evaluation = sourceCameraSceneEvaluation(runtime.sourceCamera, runtime.root);
  if (previousProgress != null) seekSourceTransitionPlayback(entry, previousProgress, runtime.clockSeconds);
  const status = document.querySelector("[data-source-camera-evidence-status]");
  const correctness = document.querySelector("[data-source-camera-evidence-correctness]");
  if (status) status.textContent = `${sourceSpatialCueStatusLabel(evaluation.status)} · ${evaluation.visibleRenderables}/${evaluation.renderables} visible parts`;
  if (correctness) {
    correctness.textContent = evaluation.status === "aligned"
      ? `Camera focus intersects the active 3D model state at source ${Math.round((Number(cue.sourceProgress) || 0) * 100)}%.`
      : evaluation.status === "partial"
        ? `Active model parts enter the camera view, but the focus direction is unclear.`
        : `The linked 3D model state could not be verified from this camera cue.`;
  }
  entry.sourceCameraEvidence = { cue, evaluation };
  return true;
}

function sourceDynamicsForPreviewAsset(viewer, assetId) {
  return (viewer?.sourceDynamicsAssets || []).find((item) => item.assetId === assetId) || null;
}

function animateDynamicEffectOverlays(effects, kind, time) {
  if (!effects) return;
  if (effects.root) {
    effects.root.rotation.y = kind === "flow" ? time * 0.55 : 0;
  }
  if (effects.halo) {
    const pulse = 1 + (Math.sin(time * 2.3) * 0.5 + 0.5) * 0.24;
    effects.halo.scale.setScalar(pulse);
  }
  if (effects.particles) {
    effects.particles.rotation.y = time * 0.85;
    effects.particles.rotation.x = Math.sin(time * 0.6) * 0.18;
  }
  effects.rings?.forEach((ring, index) => {
    const pulse = 1 + (Math.sin(time * 2 + index * 0.75) * 0.5 + 0.5) * 0.34;
    ring.scale.setScalar(pulse);
    if (ring.material) ring.material.opacity = 0.16 + (Math.sin(time * 2 + index) * 0.5 + 0.5) * 0.28;
  });
  effects.markers?.forEach((marker, index) => {
    const pulse = 1 + (Math.sin(time * 3 + index) * 0.5 + 0.5) * 0.45;
    marker.scale.setScalar(pulse);
  });
}

function animateInterBeatDynamics(viewer) {
  const progress = previewCycleProgress(viewer);
  const completed = viewer.playOnce && progress >= 1;
  applyInterBeatSourcePartMasks(viewer, completed || !viewer.sourceMotionTransition ? "destination" : "transition");
  if (completed && viewer.playing) {
    viewer.playing = false;
    state.interBeatPreviewPlaying = false;
    const playButton = document.querySelector("[data-inter-beat-play]");
    if (playButton) {
      playButton.textContent = "Play";
      playButton.setAttribute("aria-pressed", "false");
      if (playButton.dataset.interBeatPlayLabel) {
        playButton.setAttribute("aria-label", `Play ${playButton.dataset.interBeatPlayLabel}`);
      }
    }
  }
  animateDynamicGeometry(viewer);
  applyInterBeatExactSceneVisibility(viewer, progress);
  const effects = viewer.transitionEffects;
  if (!effects) return;
  const time = viewer.elapsed;
  const smooth = progress * progress * (3 - 2 * progress);
  const phaseOnB = progress >= 0.5;
  const setOpacity = (object, opacity) => {
    if (object?.material) object.material.opacity = opacity;
  };
  const setStop = (stop, opacity, scale = 1) => {
    if (!stop?.ring) return;
    stop.ring.scale.setScalar(scale);
    setOpacity(stop.ring, opacity);
  };

  if (viewer.kind === "discrete-hard") {
    const hardProgress = phaseOnB ? 1 : 0;
    effects.marker?.position.lerpVectors(effects.fromRaised, effects.toRaised, hardProgress);
    setStop(effects.fromStop, phaseOnB ? 0.12 : 0.62, phaseOnB ? 0.92 : 1.22);
    setStop(effects.toStop, phaseOnB ? 0.68 : 0.12, phaseOnB ? 1.24 : 0.92);
    if (effects.line?.material) effects.line.material.opacity = phaseOnB ? 0.24 : 0.1;
  } else if (viewer.kind === "discrete-fade") {
    updateInterBeatFadeTargets(viewer, smooth);
    effects.marker?.position.lerpVectors(effects.fromRaised, effects.toRaised, smooth);
    setStop(effects.fromStop, 0.68 * (1 - smooth), 1 + (1 - smooth) * 0.18);
    setStop(effects.toStop, 0.68 * smooth, 1 + smooth * 0.18);
    if (effects.line?.material) effects.line.material.opacity = 0.18 + Math.sin(progress * Math.PI) * 0.32;
  } else if (viewer.kind === "discrete-wipe") {
    effects.marker?.position.lerpVectors(effects.fromRaised, effects.toRaised, smooth);
    if (effects.wipe) {
      effects.wipe.position.copy(effects.from.clone().lerp(effects.to, smooth).add(new THREE.Vector3(0, 0.72, 0)));
      effects.wipe.scale.setScalar(1 + Math.sin(progress * Math.PI) * 0.2);
      setOpacity(effects.wipe, 0.16 + Math.sin(progress * Math.PI) * 0.32);
    }
    setStop(effects.fromStop, progress < 0.65 ? 0.55 : 0.16, 1.06);
    setStop(effects.toStop, progress > 0.35 ? 0.62 : 0.16, 1.08);
  } else if (viewer.kind === "discrete-pop") {
    const pop = Math.max(0, 1 - Math.abs(progress - 0.55) / 0.18);
    effects.marker?.position.copy(progress < 0.55 ? effects.fromRaised : effects.toRaised);
    if (effects.flash) {
      effects.flash.scale.setScalar(0.6 + pop * 2.4);
      setOpacity(effects.flash, pop * 0.62);
    }
    setStop(effects.fromStop, progress < 0.52 ? 0.6 : 0.12, progress < 0.52 ? 1.14 : 0.92);
    setStop(effects.toStop, progress >= 0.52 ? 0.72 : 0.1, 1 + pop * 0.55);
  } else if (viewer.kind === "continuous-active") {
    effects.marker?.position.lerpVectors(effects.fromRaised, effects.toRaised, smooth);
    if (effects.readerAvatar) {
      effects.readerAvatar.position.lerpVectors(effects.fromRaised, effects.toRaised, smooth);
      effects.readerAvatar.position.y += Math.sin(progress * Math.PI * 4) * 0.035;
      effects.readerAvatar.rotation.y = Math.sin(time * 1.4) * 0.22;
    }
    if (effects.particles) {
      effects.particles.rotation.y = Math.sin(time * 0.65) * 0.16;
      effects.particles.position.y = Math.sin(time * 1.4) * 0.04;
    }
    setStop(effects.fromStop, 0.58 * (1 - smooth) + 0.16, 1 + (1 - smooth) * 0.12);
    setStop(effects.toStop, 0.22 + smooth * 0.48, 1 + smooth * 0.2);
  } else if (viewer.kind === "continuous-passive") {
    const readerPosition = new THREE.Vector3(0, 0.18, 0);
    effects.marker?.position.lerpVectors(effects.toRaised, readerPosition, smooth);
    if (effects.passiveGhost) {
      effects.passiveGhost.position.lerpVectors(effects.toRaised, readerPosition, smooth);
      effects.passiveGhost.scale.setScalar(1 + Math.sin(progress * Math.PI) * 0.48);
      setOpacity(effects.passiveGhost, 0.24 + smooth * 0.44);
    }
    if (effects.readerTarget) {
      effects.readerTarget.scale.setScalar(1 + smooth * 0.22);
    }
    setStop(effects.fromStop, 0.28, 0.96);
    setStop(effects.toStop, 0.66 * (1 - smooth) + 0.16, 1 + (1 - smooth) * 0.18);
  }

  if (effects.line?.material && viewer.kind !== "discrete-hard") {
    effects.line.material.opacity = Math.max(effects.line.material.opacity || 0, 0.18 + Math.sin(progress * Math.PI) * 0.22);
  }
  if (effects.marker) {
    effects.marker.scale.setScalar(1 + (Math.sin(time * 3.2) * 0.5 + 0.5) * 0.2);
  }
  effects.rings?.forEach((ring, index) => {
    const pulse = 1 + (Math.sin(time * 2.6 + index * 0.8) * 0.5 + 0.5) * 0.36;
    ring.scale.setScalar(pulse);
    if (ring.material) ring.material.opacity = 0.16 + (Math.sin(time * 2.1 + index) * 0.5 + 0.5) * 0.28;
  });
}

function applyInterBeatExactSceneVisibility(viewer, progress) {
  if (!viewer?.usesExactSceneComposition) return false;
  const rawProgress = Math.max(0, Math.min(1, Number(progress) || 0));
  const clamped = !viewer.playing && rawProgress <= 0 ? 1 : rawProgress;
  const smooth = clamped * clamped * (3 - 2 * clamped);
  const hardSwitch = ["discrete-hard", "discrete-pop"].includes(viewer.kind);
  const destinationOpacity = hardSwitch ? (clamped >= 0.5 ? 1 : 0) : smooth;
  for (const item of viewer.dynamicObjects || []) {
    if (item.transitionSceneRole === "from") setDynamicPreviewObjectOpacity(item, 1 - destinationOpacity);
    else if (item.transitionSceneRole === "to") setDynamicPreviewObjectOpacity(item, destinationOpacity);
  }
  return true;
}

function updateInterBeatFadeTargets(viewer, progress) {
  if (applyInterBeatExactSceneVisibility(viewer, progress)) return;
  if (viewer.cumulativeContext || viewer.singleAnchorContext) {
    updateCumulativeInterBeatFadeTargets(viewer, progress);
    return;
  }
  for (const item of viewer.dynamicObjects || []) {
    const isFrom = viewer.transitionFromAssetIds?.has(item.assetId) || item.index === viewer.transitionFromAssetIndex;
    const isTo = viewer.transitionToAssetIds?.has(item.assetId) || item.index === viewer.transitionToAssetIndex;
    let opacity = item.active ? 1 : 0.34;
    if (isFrom && !isTo) opacity = 1 - progress;
    if (isTo && !isFrom) opacity = progress;
    if (isFrom && isTo) opacity = 1;
    setDynamicPreviewObjectOpacity(item, opacity);
  }
}

function updateCumulativeInterBeatFadeTargets(viewer, progress) {
  const groups = viewer.swapGroups || [];
  if (!groups.length) return;
  const max = groups.length - 1;
  const fromIndex = Math.max(0, Math.min(max, viewer.activeSwapIndex || 0));
  const toIndex = Math.max(0, Math.min(max, fromIndex + 1));
  for (const [index, entry] of groups.entries()) {
    let opacity = 0;
    if (index === fromIndex && index === toIndex) opacity = 1;
    else if (index === fromIndex) opacity = 1 - progress;
    else if (index === toIndex) opacity = progress;
    setPreviewEntryOpacity(entry, opacity);
  }
}

function setDynamicPreviewObjectOpacity(item, opacity) {
  const visible = Number(opacity) > 0.001;
  if (item?.wrapper) item.wrapper.visible = visible;
  setPreviewOpacityMaterials(item?.opacityMaterials, opacity);
}

function dynamicAssetPosition3d(index, total, layoutKind = null, active = false) {
  if (layoutKind === "object") {
    if (active) return new THREE.Vector3(0, 0, 0);
    const count = Math.max(total - 1, 1);
    const adjusted = index % count;
    const angle = (-Math.PI / 2) + ((Math.PI * 2 * adjusted) / count);
    return new THREE.Vector3(Math.cos(angle) * 1.55, 0, Math.sin(angle) * 1.55);
  }
  if (layoutKind === "region") return narrativeAssetPosition3d("region", index, total, active);
  if (layoutKind === "overview") return narrativeAssetPosition3d("overview", index, total, active);
  if (layoutKind === "single" || layoutKind === "map" || layoutKind === "constellation") {
    return narrativeAssetPosition3d("object", index, total, active, layoutKind);
  }
  const count = Math.max(total, 1);
  const angle = (-Math.PI * 0.8) + ((Math.PI * 1.6 * index) / Math.max(count - 1, 1));
  return new THREE.Vector3(Math.cos(angle) * 2.05, 0, Math.sin(angle) * 2.05);
}

function syncSelectedModelWithActiveContext() {
  if (!state.selectedModelAssetId) return;
  const asset = findAssetById(state.selectedModelAssetId);
  if (!asset || !isModelAsset(asset)) {
    state.selectedModelAssetId = null;
    return;
  }
  if (state.activeId === "asset-topology" || state.activeId === "dynamic-geometry" || state.activeId === "inter-beat-dynamics" || state.activeId === "environment-enhancement") {
    const component = componentById(state.activeId);
    const proposal = selectedComponentPreview(component);
    const linked = (proposal?.assetLinks || []).some((assetLink) => assetLink.assetId === state.selectedModelAssetId);
    if (!linked) state.selectedModelAssetId = null;
    return;
  }
  if (state.activeId !== "source-graph") {
    state.selectedModelAssetId = null;
    return;
  }
  const beat = selectedBeat();
  const linked = beatAssetIds(beat).includes(state.selectedModelAssetId);
  if (!beat || !linked) state.selectedModelAssetId = null;
}

function sourceGraphSpatialPreviewContract() {
  const locked = lockedSpatialRelationsContract();
  if (locked) return locked;
  const saved = spatialRelationsDecision()?.spatialRelations;
  if (
    spatialRelationEntities(saved).length
    || saved?.resolvedByBeat
    || saved?.resolvedByVariant
  ) return saved;
  return null;
}

function sourceGraphSpatialPreviewEntries(preview, contract) {
  const linkedAssetIds = new Set(preview.linkedAssetIds);
  const sceneEntities = spatialSceneEntities(contract, preview.sceneContext)
    .filter((entity) => {
      const kind = spatialEntityType(entity);
      return (kind === "glb" || kind === "image-plane") && linkedAssetIds.has(entity.assetId);
    });
  const coveredAssetIds = new Set(sceneEntities.map((entity) => entity.assetId));
  const entries = sceneEntities.map((entity) => ({
    assetId: entity.assetId,
    entity,
    kind: spatialEntityType(entity),
  }));
  for (const assetId of preview.linkedAssetIds) {
    if (coveredAssetIds.has(assetId)) continue;
    const asset = findAssetById(assetId);
    if (!asset || (!isModelAsset(asset) && !isImageAsset(asset))) continue;
    entries.push({
      assetId,
      entity: null,
      kind: isImageAsset(asset) ? "image-plane" : "glb",
    });
  }
  return entries;
}

function applySourceGraphSpatialPreviewFallbackTransform(wrapper, index, total) {
  if (total <= 1) {
    wrapper.position.set(0, 0, 0);
    return;
  }
  const columns = Math.min(3, total);
  const rows = Math.ceil(total / columns);
  const column = index % columns;
  const row = Math.floor(index / columns);
  wrapper.position.set(
    (column - ((columns - 1) / 2)) * 2.15,
    0,
    (row - ((rows - 1) / 2)) * 1.7,
  );
}

function frameSourceGraphSpatialPreview(viewer) {
  const candidates = viewer.selectedObjects.length ? viewer.selectedObjects : [...viewer.spatialObjects.values()];
  const bounds = new THREE.Box3();
  for (const object of candidates) {
    object.updateWorldMatrix(true, true);
    bounds.union(new THREE.Box3().setFromObject(object, true));
  }
  if (bounds.isEmpty()) return;
  const center = bounds.getCenter(new THREE.Vector3());
  const size = bounds.getSize(new THREE.Vector3());
  const maxSize = Math.max(size.x, size.y, size.z, 0.7);
  const distance = maxSize / (2 * Math.tan(THREE.MathUtils.degToRad(viewer.camera.fov / 2)));
  const direction = new THREE.Vector3(1, 0.72, 1).normalize();
  viewer.camera.position.copy(center).add(direction.multiplyScalar(distance * 2.05));
  viewer.camera.near = Math.max(distance / 100, 0.01);
  viewer.camera.far = Math.max(distance * 100, 100);
  viewer.camera.updateProjectionMatrix();
  viewer.controls.target.copy(center);
  viewer.controls.update();
}

function markSourceGraphSpatialPreviewSelection(viewer, object, assetId) {
  if (assetId !== viewer.preview.assetId) return;
  viewer.selectedObjects.push(object);
  const helper = new THREE.BoxHelper(object, 0x007f73);
  helper.name = "Selected asset preview highlight";
  helper.material.transparent = true;
  helper.material.opacity = 0.95;
  helper.material.depthTest = false;
  helper.renderOrder = 20;
  viewer.scene.add(helper);
  viewer.highlightHelpers.push(helper);
}

function loadSourceGraphSpatialPreviewGlb(viewer, entry, index, total, done) {
  const asset = findAssetById(entry.assetId);
  const src = asset && assetLoadSrc(asset);
  const wrapper = new THREE.Group();
  wrapper.name = `Read-only scene object · ${entry.assetId}`;
  wrapper.userData.assetId = entry.assetId;
  viewer.root.add(wrapper);
  viewer.spatialObjects.set(entry.entity?.id || `preview:${entry.assetId}:${index}`, wrapper);
  if (entry.entity) applySpatialEntityTransformToObject(viewer, entry.entity, wrapper);
  else applySourceGraphSpatialPreviewFallbackTransform(wrapper, index, total);
  if (!src) {
    done(false);
    return;
  }
  createGltfLoader().load(src, (gltf) => {
    if (viewer.disposed) {
      disposeObject(gltf.scene);
      return;
    }
    applySpatialLoaderTransformPolicy(gltf.scene, entry.entity);
    if (entry.entity?.preserveSourceGeometry !== true) {
      normalizeSpatialRuntimeObject(
        gltf.scene,
        spatialTopologyAssetPose(viewer, index, Math.max(total, 1)).targetSize,
        spatialEntityVerticalAlignment(entry.entity),
      );
    }
    wrapper.add(gltf.scene);
    wrapper.updateWorldMatrix(true, true);
    markSourceGraphSpatialPreviewSelection(viewer, wrapper, entry.assetId);
    done(true);
  }, undefined, () => done(false));
}

function loadSourceGraphSpatialPreviewImage(viewer, entry, index, total, done) {
  const asset = findAssetById(entry.assetId);
  const src = asset && assetPreviewSrc(asset);
  const wrapper = new THREE.Group();
  wrapper.name = `Read-only scene image · ${entry.assetId}`;
  wrapper.userData.assetId = entry.assetId;
  viewer.root.add(wrapper);
  viewer.spatialObjects.set(entry.entity?.id || `preview:${entry.assetId}:${index}`, wrapper);
  if (entry.entity) applySpatialEntityTransformToObject(viewer, entry.entity, wrapper);
  else {
    applySourceGraphSpatialPreviewFallbackTransform(wrapper, index, total);
    wrapper.position.y = 1;
  }
  if (!src) {
    done(false);
    return;
  }
  new THREE.TextureLoader().load(src, (texture) => {
    if (viewer.disposed) {
      texture.dispose();
      return;
    }
    texture.colorSpace = THREE.SRGBColorSpace;
    const image = entry.entity?.image || {};
    const actualAspect = texture.image?.width && texture.image?.height
      ? texture.image.width / texture.image.height
      : null;
    const aspect = Number(image.aspectRatio) || actualAspect || 16 / 9;
    const width = Math.max(0.1, Number(image.width) || 1.6);
    const height = Math.max(0.1, Number(image.height) || width / Math.max(aspect, 0.1));
    const plane = new THREE.Mesh(
      new THREE.PlaneGeometry(width, height),
      new THREE.MeshBasicMaterial({ map: texture, transparent: true, side: THREE.DoubleSide }),
    );
    wrapper.add(plane);
    wrapper.updateWorldMatrix(true, true);
    markSourceGraphSpatialPreviewSelection(viewer, wrapper, entry.assetId);
    done(true);
  }, undefined, () => done(false));
}

function initializeSourceGraphSpatialPreview(active) {
  if (active?.id !== "source-graph") return;
  const container = document.querySelector("[data-source-graph-spatial-preview-viewer]");
  const preview = sourceGraphSpatialPreviewState();
  if (!container || !preview) return;
  const contract = sourceGraphSpatialPreviewContract();
  const sceneRecord = spatialSceneRecordForContext(contract, preview.sceneContext);
  const entries = sourceGraphSpatialPreviewEntries(preview, contract);
  const width = Math.max(container.clientWidth, 280);
  const height = Math.max(container.clientHeight, 190);
  const scene = new THREE.Scene();
  scene.background = new THREE.Color(0xf8f7ec);
  const camera = new THREE.PerspectiveCamera(40, width / height, 0.01, 1000);
  camera.position.set(3.2, 2.2, 4.2);
  const renderer = new THREE.WebGLRenderer({ antialias: true, alpha: true });
  renderer.setPixelRatio(Math.min(window.devicePixelRatio || 1, 2));
  renderer.setSize(width, height);
  renderer.outputColorSpace = THREE.SRGBColorSpace;
  renderer.domElement.tabIndex = 0;
  renderer.domElement.className = "source-graph-spatial-preview-canvas spatial-editor-mouse-controls";
  const status = container.querySelector(".source-graph-spatial-preview-status") || document.createElement("div");
  status.className = "source-graph-spatial-preview-status";
  status.textContent = entries.length ? "Loading scene…" : "No spatial assets to preview.";
  container.replaceChildren(renderer.domElement, status);
  const controls = new OrbitControls(camera, renderer.domElement);
  configureSpatialEditorMouseControls(controls);
  controls.enableDamping = true;
  controls.dampingFactor = 0.08;
  controls.screenSpacePanning = false;
  controls.maxPolarAngle = Math.PI / 2 - 0.02;
  controls.target.set(0, 0.9, 0);
  scene.add(new THREE.HemisphereLight(0xffffff, 0x6f7f78, 2.5));
  const keyLight = new THREE.DirectionalLight(0xffffff, 3);
  keyLight.position.set(4, 7, 5);
  scene.add(keyLight);
  const fillLight = new THREE.DirectionalLight(0xbcece4, 1.2);
  fillLight.position.set(-4, 3, -4);
  scene.add(fillLight);
  const root = new THREE.Group();
  root.name = "Source Graph read-only spatial preview";
  scene.add(root);
  const layoutKind = sceneRecord?.topology?.kind || sceneRecord?.topologyKind || "single";
  scene.add(makeSpatialEditorFloorGuide(layoutKind));
  const viewer = {
    container,
    preview,
    scene,
    camera,
    renderer,
    controls,
    root,
    layoutKind,
    topologyKind: layoutKind,
    spatialObjects: new Map(),
    selectedObjects: [],
    highlightHelpers: [],
    animationId: null,
    resizeHandler: null,
    disposed: false,
  };
  sourceGraphSpatialPreviewViewer = viewer;
  let pending = entries.length;
  let loaded = 0;
  const finishEntry = (success) => {
    pending -= 1;
    if (success) loaded += 1;
    if (pending > 0 || viewer.disposed) return;
    if (loaded) status.remove();
    else status.textContent = "Preview unavailable.";
    frameSourceGraphSpatialPreview(viewer);
  };
  entries.forEach((entry, index) => {
    if (entry.kind === "image-plane") {
      loadSourceGraphSpatialPreviewImage(viewer, entry, index, entries.length, finishEntry);
    } else loadSourceGraphSpatialPreviewGlb(viewer, entry, index, entries.length, finishEntry);
  });
  if (!entries.length) requestAnimationFrame(() => {
    if (!viewer.disposed) frameSourceGraphSpatialPreview(viewer);
  });
  viewer.resizeHandler = () => {
    if (viewer.disposed) return;
    const nextWidth = Math.max(container.clientWidth, 280);
    const nextHeight = Math.max(container.clientHeight, 190);
    camera.aspect = nextWidth / nextHeight;
    camera.updateProjectionMatrix();
    renderer.setSize(nextWidth, nextHeight);
  };
  window.addEventListener("resize", viewer.resizeHandler);
  const animate = () => {
    if (viewer.disposed) return;
    for (const helper of viewer.highlightHelpers) helper.update();
    controls.update();
    renderer.render(scene, camera);
    viewer.animationId = requestAnimationFrame(animate);
  };
  animate();
}

function initializeSelectedModelViewer() {
  const container = document.querySelector("[data-model-viewer]");
  if (!container || !state.selectedModelAssetId) return;

  const asset = findAssetById(state.selectedModelAssetId);
  const url = assetLoadSrc(asset);
  if (!asset || !url) {
    container.innerHTML = `<div class="model-viewer-status error">Model URL is unavailable.</div>`;
    return;
  }

  const width = Math.max(container.clientWidth, 280);
  const height = Math.max(container.clientHeight, 260);
  const scene = new THREE.Scene();
  scene.background = new THREE.Color(0xf8f7ec);

  const camera = new THREE.PerspectiveCamera(38, width / height, 0.01, 1000);
  camera.position.set(2.4, 1.6, 2.4);

  const renderer = new THREE.WebGLRenderer({ antialias: true, alpha: true });
  renderer.setPixelRatio(Math.min(window.devicePixelRatio || 1, 2));
  renderer.setSize(width, height);
  renderer.outputColorSpace = THREE.SRGBColorSpace;
  container.replaceChildren(renderer.domElement);

  const controls = new OrbitControls(camera, renderer.domElement);
  controls.enableDamping = true;
  controls.dampingFactor = 0.08;

  scene.add(new THREE.HemisphereLight(0xffffff, 0x6f7f78, 2.2));
  const keyLight = new THREE.DirectionalLight(0xffffff, 2.8);
  keyLight.position.set(4, 6, 5);
  scene.add(keyLight);
  const fillLight = new THREE.DirectionalLight(0x9edfd5, 1.2);
  fillLight.position.set(-4, 2, -3);
  scene.add(fillLight);

  const viewer = {
    scene,
    camera,
    renderer,
    controls,
    animationId: null,
    resizeHandler: null,
    disposed: false,
  };
  modelViewer = viewer;

  const loader = createGltfLoader();
  loader.load(
    url,
    (gltf) => {
      if (viewer.disposed) {
        disposeObject(gltf.scene);
        return;
      }
      scene.add(gltf.scene);
      fitCameraToObject(camera, controls, gltf.scene);
    },
    undefined,
    (error) => {
      if (viewer.disposed) return;
      container.innerHTML = `<div class="model-viewer-status error">Could not load model preview: ${escapeHtml(error.message || "unknown error")}</div>`;
    },
  );

  viewer.resizeHandler = () => {
    if (viewer.disposed) return;
    const nextWidth = Math.max(container.clientWidth, 280);
    const nextHeight = Math.max(container.clientHeight, 260);
    camera.aspect = nextWidth / nextHeight;
    camera.updateProjectionMatrix();
    renderer.setSize(nextWidth, nextHeight);
  };
  window.addEventListener("resize", viewer.resizeHandler);

  const animate = () => {
    if (viewer.disposed) return;
    controls.update();
    renderer.render(scene, camera);
    viewer.animationId = requestAnimationFrame(animate);
  };
  animate();
}

function fitCameraToObject(camera, controls, object) {
  const box = new THREE.Box3().setFromObject(object);
  if (box.isEmpty()) return;

  const center = box.getCenter(new THREE.Vector3());
  const size = box.getSize(new THREE.Vector3());
  const maxSize = Math.max(size.x, size.y, size.z) || 1;
  const distance = maxSize / (2 * Math.tan(THREE.MathUtils.degToRad(camera.fov / 2)));
  const direction = new THREE.Vector3(1, 0.65, 1).normalize();

  camera.position.copy(center).add(direction.multiplyScalar(distance * 1.8));
  camera.near = Math.max(distance / 100, 0.01);
  camera.far = Math.max(distance * 100, 100);
  camera.updateProjectionMatrix();
  controls.target.copy(center);
  controls.update();
}

function disposeSourceGraphSpatialPreviewViewer() {
  if (!sourceGraphSpatialPreviewViewer) return;
  sourceGraphSpatialPreviewViewer.disposed = true;
  if (sourceGraphSpatialPreviewViewer.animationId) {
    cancelAnimationFrame(sourceGraphSpatialPreviewViewer.animationId);
  }
  if (sourceGraphSpatialPreviewViewer.resizeHandler) {
    window.removeEventListener("resize", sourceGraphSpatialPreviewViewer.resizeHandler);
  }
  sourceGraphSpatialPreviewViewer.controls?.dispose();
  disposeObject(sourceGraphSpatialPreviewViewer.scene);
  sourceGraphSpatialPreviewViewer.renderer?.dispose();
  sourceGraphSpatialPreviewViewer.renderer?.forceContextLoss?.();
  sourceGraphSpatialPreviewViewer = null;
}

