function disposeTextComfortViewer() {
  if (!textViewer) return;
  if (textViewer.spatialTransformDrag) finalizeInterruptedSpatialTransformDrag(textViewer);
  textViewer.disposed = true;
  if (textViewer.animationId) cancelAnimationFrame(textViewer.animationId);
  if (textViewer.resizeHandler) window.removeEventListener("resize", textViewer.resizeHandler);
  if (textViewer.keyDownHandler) window.removeEventListener("keydown", textViewer.keyDownHandler);
  if (textViewer.keyUpHandler) window.removeEventListener("keyup", textViewer.keyUpHandler);
  if (textViewer.pointerMoveHandler) window.removeEventListener("pointermove", textViewer.pointerMoveHandler);
  if (textViewer.pointerUpHandler) window.removeEventListener("pointerup", textViewer.pointerUpHandler);
  if (textViewer.pointerCancelHandler) window.removeEventListener("pointercancel", textViewer.pointerCancelHandler);
  if (textViewer.pointerDownHandler) textViewer.renderer?.domElement?.removeEventListener("pointerdown", textViewer.pointerDownHandler);
  if (textViewer.selectionPointerGesture) {
    const pointerId = textViewer.selectionPointerGesture.pointerId;
    if (textViewer.renderer?.domElement?.hasPointerCapture?.(pointerId)) {
      textViewer.renderer.domElement.releasePointerCapture?.(pointerId);
    }
    textViewer.selectionPointerGesture = null;
  }
  textViewer.spatialTransformDrag = null;
  textViewer.selectionMarquee?.remove?.();
  textViewer.transformControls?.detach?.();
  textViewer.transformControls?.dispose?.();
  textViewer.transformHelper?.removeFromParent?.();
  for (const entry of textViewer.spatialPlaybackEntries || []) entry.sourcePlayback?.mixer?.stopAllAction?.();
  textViewer.controls?.dispose();
  disposeLockedEnvironmentFromViewer(textViewer);
  disposeObject(textViewer.scene);
  textViewer.renderer?.dispose();
  textViewer.renderer?.forceContextLoss?.();
  textViewer = null;
}

