function disposeFinalReviewViewer() {
  if (!finalReviewViewer) return;
  finalReviewViewer.disposed = true;
  finalReviewViewer.renderer?.setAnimationLoop?.(null);
  if (finalReviewViewer.animationId) cancelAnimationFrame(finalReviewViewer.animationId);
  if (finalReviewViewer.resizeHandler) window.removeEventListener("resize", finalReviewViewer.resizeHandler);
  if (finalReviewViewer.keyDownHandler) window.removeEventListener("keydown", finalReviewViewer.keyDownHandler);
  if (finalReviewViewer.keyUpHandler) window.removeEventListener("keyup", finalReviewViewer.keyUpHandler);
  if (finalReviewViewer.pointerDownHandler) document.removeEventListener("pointerdown", finalReviewViewer.pointerDownHandler);
  if (finalReviewViewer.textPanelClickHandler) finalReviewViewer.renderer?.domElement?.removeEventListener("click", finalReviewViewer.textPanelClickHandler);
  if (finalReviewViewer.textPanelWheelHandler) finalReviewViewer.renderer?.domElement?.removeEventListener("wheel", finalReviewViewer.textPanelWheelHandler);
  if (finalReviewViewer.textPanelPointerMoveHandler) finalReviewViewer.renderer?.domElement?.removeEventListener("pointermove", finalReviewViewer.textPanelPointerMoveHandler);
  if (finalReviewViewer.textPanelPointerLeaveHandler) finalReviewViewer.renderer?.domElement?.removeEventListener("pointerleave", finalReviewViewer.textPanelPointerLeaveHandler);
  if (finalReviewViewer.readerHandPointerDownHandler) finalReviewViewer.renderer?.domElement?.removeEventListener("pointerdown", finalReviewViewer.readerHandPointerDownHandler);
  if (finalReviewViewer.readerHandPointerMoveHandler) window.removeEventListener("pointermove", finalReviewViewer.readerHandPointerMoveHandler);
  if (finalReviewViewer.readerHandPointerUpHandler) window.removeEventListener("pointerup", finalReviewViewer.readerHandPointerUpHandler);
  if (finalReviewViewer.readerHandPointerUpHandler) window.removeEventListener("pointercancel", finalReviewViewer.readerHandPointerUpHandler);
  if (finalReviewViewer.xrSessionStartHandler) finalReviewViewer.renderer?.xr?.removeEventListener?.("sessionstart", finalReviewViewer.xrSessionStartHandler);
  if (finalReviewViewer.xrSessionEndHandler) finalReviewViewer.renderer?.xr?.removeEventListener?.("sessionend", finalReviewViewer.xrSessionEndHandler);
  clearFinalReviewDirectManipulationCues(finalReviewViewer);
  clearFinalReviewAttentionGuidance(finalReviewViewer);
  finalReviewViewer.controls?.dispose();
  disposeProceduralDynamicsPreview(finalReviewViewer);
  disposeLockedEnvironmentFromViewer(finalReviewViewer);
  disposeObject(finalReviewViewer.scene);
  finalReviewViewer.renderer?.dispose();
  finalReviewViewer.renderer?.forceContextLoss?.();
  finalReviewViewer = null;
}

function disposeObject(object) {
  if (!object) return;
  object.traverse?.((child) => {
    if (child.geometry) child.geometry.dispose();
    if (Array.isArray(child.material)) {
      child.material.forEach(disposeMaterial);
    } else if (child.material) {
      disposeMaterial(child.material);
    }
  });
}

function disposeMaterial(material) {
  for (const value of Object.values(material)) {
    if (value?.isTexture) value.dispose();
  }
  material.dispose?.();
}

function checkpointComponents() {
  return visibleFlowComponents().filter((component) => component.id !== "source-graph");
}

function checkpointIndex(componentId) {
  return checkpointComponents().findIndex((component) => component.id === componentId);
}

function isDecisionOptionCurrent(component, option) {
  if (!component || !option) return false;
  if (component.id === "transition-pacing") return option.optionId === "transition-pacing-final-review-saved";
  if (component.id === "inter-beat-dynamics") return Boolean(inferInterBeatDynamicsKind(option));
  return true;
}

function lockedDecisionKind(componentId) {
  if (isSpatialRelationsComponentId(componentId)) return lockedSpatialTextKind();
  if (!checkpointIsCurrent(componentId)) return null;
  const option = state.data?.decisions?.[componentId]?.option;
  if (!option) return null;
  if (componentId === "asset-topology") return inferTopologyKind(option);
  if (componentId === "dynamic-geometry") return inferDynamicGeometryKind(option);
  if (componentId === "inter-beat-dynamics") return inferInterBeatDynamicsKind(option);
  if (componentId === "environment-enhancement") return inferContextLayerKind(option);
  if (componentId === "interaction-control") return inferInteractionControlKind(option);
  return null;
}

function upstreamSpatialLayoutKind() {
  return lockedDecisionKind("asset-topology") || null;
}

function cumulativePreviewLayersForComponent(componentId, overrides = {}) {
  const enabled = cumulativePreviewLayerMap(componentId);
  const spatialEnabled = enabled[SPATIAL_RELATIONS_COMPONENT_ID] || enabled[LEGACY_TEXT_COMFORT_COMPONENT_ID];
  return {
    componentId,
    ids: cumulativePreviewLayerIds(componentId),
    enabled,
    topologyKind: enabled.topology ? (overrides.topologyKind || lockedDecisionKind("asset-topology")) : null,
    dynamicKind: enabled["dynamic-geometry"] ? (overrides.dynamicKind || lockedDecisionKind("dynamic-geometry")) : null,
    transitionKind: enabled["inter-beat-dynamics"] ? (overrides.transitionKind || lockedDecisionKind("inter-beat-dynamics")) : null,
    contextKind: enabled["environment-enhancement"] ? (overrides.contextKind || lockedDecisionKind("environment-enhancement")) : null,
    textKind: spatialEnabled ? (overrides.textKind || lockedSpatialTextKind()) : null,
    spatialRelations: spatialEnabled ? lockedSpatialRelationsContract() : null,
    interactionKind: enabled["interaction-control"] ? (overrides.interactionKind || lockedDecisionKind("interaction-control")) : null,
  };
}

function cumulativeLayerLabelEntries(layers, activeComponentId) {
  const activeLayerId = activeComponentId === "asset-topology"
    ? "topology"
    : activeComponentId;
  const entries = [
    { id: "topology", label: "Topology", value: layers?.topologyKind ? topologyKindLabel(layers.topologyKind) : "" },
    { id: "dynamic-geometry", label: "Geometry", value: layers?.dynamicKind ? dynamicGeometryKindLabel(layers.dynamicKind) : "" },
    { id: "inter-beat-dynamics", label: "Scene changes", value: layers?.transitionKind ? interBeatDynamicsKindLabel(layers.transitionKind) : "" },
    { id: "environment-enhancement", label: "Setting", value: layers?.contextKind ? contextLayerKindLabel(layers.contextKind) : "" },
    { id: SPATIAL_RELATIONS_COMPONENT_ID, label: "Spatial", value: layers?.textKind ? (layers.textKind === "spatial-relations" ? "Authored transforms" : textComfortKindLabel(layers.textKind)) : "" },
    { id: "interaction-control", label: "Reader actions", value: layers?.interactionKind ? interactionControlKindLabel(layers.interactionKind) : "" },
  ];
  return entries.filter((entry) => entry.value && entry.id !== activeLayerId && layers?.enabled?.[entry.id]);
}

function dynamicPreviewMetadataEntries(
  layers,
  kind,
  assetLinks,
  activeAssetIndex,
  activeAssetIds,
  cumulativeContext,
  hasSourceAnimation = false,
  hasProceduralMotion = false,
) {
  const activeLink = cumulativeContext?.active
    || assetLinks?.[activeAssetIndex]
    || assetLinks?.find((assetLink) => activeAssetIds?.has(assetLink.assetId));
  const currentValue = hasProceduralMotion
    ? (hasSourceAnimation ? "Generated path + 3D model animation" : "Generated path movement")
    : hasSourceAnimation
      ? "3D model animation"
      : "Static 3D model pose";
  return previewMetadataEntries({
    componentId: "dynamic-geometry",
    layers,
    activeLink,
    activeLabel: "Active effect",
    currentValue,
  });
}

function previewMetadataEntries(options = {}) {
  const activeValue = previewAssetDisplayName(options.activeLink);
  return [
    Object.hasOwn(options, "activeLink") ? { id: "active-asset", label: options.activeLabel || "Active asset", value: activeValue } : null,
    options.currentValue ? { id: "current-option", value: options.currentValue } : null,
    Object.hasOwn(options, "beat") ? { id: "beat", label: "Story part", value: shortText(options.beat?.title || "", 52) } : null,
    ...(options.additionalEntries || []),
    ...(options.layers ? cumulativeLayerLabelEntries(options.layers, options.componentId).reverse() : []),
  ].filter(Boolean);
}

function previewAssetDisplayName(assetLink) {
  if (!assetLink) return "";
  const asset = assetLink.assetId ? findAssetById(assetLink.assetId) : null;
  return String(
    assetLink.role
    || assetLink.label
    || asset?.role
    || asset?.filename
    || asset?.id
    || assetLink.assetId
    || "",
  ).trim();
}

function addPreviewMetadataOverlay(container, entries) {
  const visibleEntries = (entries || []).filter(Boolean);
  if (!container || !visibleEntries.length) return null;
  const overlay = document.createElement("details");
  overlay.className = "preview-metadata-overlay";
  overlay.setAttribute("aria-label", "Preview metadata");
  const toggle = document.createElement("summary");
  toggle.className = "preview-metadata-toggle";
  const toggleLabel = document.createElement("span");
  toggleLabel.textContent = "Preview details";
  const toggleChevron = document.createElement("span");
  toggleChevron.className = "preview-metadata-chevron";
  toggleChevron.setAttribute("aria-hidden", "true");
  toggle.append(toggleLabel, toggleChevron);
  overlay.append(toggle);
  for (const entry of visibleEntries) {
    const row = document.createElement("div");
    row.className = `preview-metadata-row${entry.label ? "" : " standalone"}`;
    if (entry.id) row.dataset.previewMetadataId = entry.id;
    row.hidden = !String(entry.value || "").trim();
    if (entry.label) {
      const label = document.createElement("span");
      label.textContent = `${entry.label}:`;
      row.append(label);
    }
    const value = document.createElement("strong");
    value.className = "preview-metadata-value";
    value.textContent = entry.value;
    row.append(value);
    overlay.append(row);
  }
  container.append(overlay);
  return overlay;
}

function updatePreviewMetadataEntry(viewer, id, value) {
  if (!viewer?.metadataOverlay || !id) return;
  const row = [...viewer.metadataOverlay.querySelectorAll("[data-preview-metadata-id]")]
    .find((candidate) => candidate.dataset.previewMetadataId === id);
  if (!row) return;
  const nextValue = String(value || "").trim();
  row.hidden = !nextValue;
  const target = row.querySelector(".preview-metadata-value");
  if (target) target.textContent = nextValue;
}

function addCumulativeLayerLabels(root, layers, activeComponentId, options = {}) {
  const entries = cumulativeLayerLabelEntries(layers, activeComponentId).slice(-(options.limit || 4));
  const startX = options.startX ?? -2.35;
  const spacing = options.spacing ?? 1.55;
  const z = options.z ?? -2.12;
  const y = options.y ?? 0.52;
  entries.forEach((entry, index) => {
    addPriorDecisionLabel(root, entry.label, entry.value, {
      x: startX + index * spacing,
      y,
      z,
      width: options.width || 1.42,
    });
  });
}

function addPriorDecisionLabel(root, label, value, options = {}) {
  if (!value) return;
  const sprite = makeTextSprite(`${label}: ${value}`, {
    y: options.y ?? 0.52,
    color: "#10201c",
    background: "rgba(255,253,244,0.9)",
    width: options.width || 1.8,
    height: options.height || 0.24,
  });
  sprite.position.x = options.x ?? -1.72;
  sprite.position.z = options.z ?? -2.05;
  root.add(sprite);
}

function addPreviewDescriptionCues(root, componentId, proposal, options = {}) {
  if (options.allowSyntheticGeometry !== true) return null;
  if (!root || !proposal) return null;
  if (componentId === "inter-beat-dynamics" && options.playback?.canScrub !== true) return null;
  const specs = previewDescriptionCueSpecs(componentId, proposal, options);
  if (!specs.length) return null;
  const group = new THREE.Group();
  group.name = `${componentId}-description-cues`;
  group.position.copy(previewCueVector(options.position));
  root.add(group);

  if (options.includeLabel !== false) {
    const label = makeTextSprite(previewDescriptionCueLabel(componentId, proposal, options), {
      y: options.labelY ?? 1.72,
      color: "#10201c",
      background: "rgba(255,253,244,0.92)",
      width: options.labelWidth || 1.72,
      height: 0.26,
    });
    group.add(label);
  }

  for (const spec of specs) addPreviewCueVisual(group, spec);
  return { root: group, specs };
}

function previewDescriptionCueSpecs(componentId, proposal, options = {}) {
  const kind = options.kind || selectedProposalKind(componentId, proposal);
  const text = previewCueCorpus(proposal, options.item, options.extraText);
  if (componentId === "asset-topology") {
    if (kind === "single") {
      return [
        { type: "ring", radius: 0.78, outerRadius: 0.86, color: 0xc75f1f, opacity: 0.38, y: 0.11 },
        { type: "path", color: 0xc75f1f, points: [[-0.92, 0.16, 0.18], [-0.34, 0.18, 0.02], [0.28, 0.18, -0.02], [0.92, 0.16, -0.18]] },
      ];
    }
    if (kind === "map") {
      return [
        { type: "plane", width: 1.18, depth: 0.62, x: -0.68, z: -0.22, color: 0xf2d4bf, opacity: 0.42 },
        { type: "plane", width: 1.18, depth: 0.62, x: 0.7, z: 0.2, color: 0xcfe8df, opacity: 0.42 },
        { type: "path", color: 0x007f73, points: [[-1.22, 0.12, -0.5], [-0.35, 0.12, -0.1], [0.32, 0.12, 0.18], [1.2, 0.12, 0.52]] },
      ];
    }
    return [
      { type: "ring", radius: 1.0, outerRadius: 1.04, color: 0x007f73, opacity: 0.32 },
      { type: "sphere", x: -0.74, z: -0.28, color: 0x8fbfb7 },
      { type: "sphere", x: 0.76, z: -0.2, color: 0xc75f1f },
      { type: "sphere", x: 0.1, z: 0.72, color: 0x007f73 },
    ];
  }

  if (componentId === "dynamic-geometry") {
    if (kind === "none") return [];
    if (kind === "flow" || /\b(droplet|particle|flake|dust|germ|mote|field)\b/.test(text)) {
      return [
        { type: "particles", color: 0x007f73, count: 70, radius: 0.72, height: 0.7, opacity: 0.56 },
        { type: "ring", radius: 0.64, outerRadius: 0.7, color: 0x007f73, opacity: 0.3 },
      ];
    }
    if (kind === "zoom") {
      return [
        { type: "ring", radius: 0.42, outerRadius: 0.47, color: 0xc75f1f, opacity: 0.34 },
        { type: "ring", radius: 0.74, outerRadius: 0.79, color: 0xc75f1f, opacity: 0.26 },
        { type: "ring", radius: 1.06, outerRadius: 1.11, color: 0xc75f1f, opacity: 0.18 },
      ];
    }
    if (kind === "focus") {
      return [
        { type: "sphere", x: -0.22, y: 0.72, z: 0.18, radius: 0.07, color: 0xc75f1f, opacity: 0.86 },
        { type: "sphere", x: 0.24, y: 0.9, z: -0.14, radius: 0.06, color: 0xc75f1f, opacity: 0.82 },
        { type: "ring", radius: 0.52, outerRadius: 0.6, color: 0xc75f1f, opacity: 0.32 },
      ];
    }
    return [
      { type: "path", color: 0xc75f1f, points: [[-0.72, 0.18, 0.22], [-0.22, 0.24, 0.06], [0.34, 0.22, -0.04], [0.82, 0.18, -0.24]] },
      { type: "ring", radius: 0.62, outerRadius: 0.68, color: 0xc75f1f, opacity: 0.26 },
    ];
  }

  if (componentId === "inter-beat-dynamics") {
    if (kind === "none") return [];
    const base = previewCueVector(options.position);
    const from = previewCueVector(options.fromPosition).sub(base);
    const to = previewCueVector(options.toPosition).sub(base);
    if (kind === "discrete-wipe") return [{ type: "path", color: 0x007f73, points: [from.toArray(), [0, 0.22, 0], to.toArray()] }, { type: "box", width: 0.12, height: 1.1, depth: 0.92, y: 0.62, color: 0x007f73, opacity: 0.24 }];
    if (kind === "discrete-pop") return [{ type: "sphere", y: 0.58, radius: 0.34, color: 0xfff0b5, opacity: 0.42 }, { type: "ring", radius: 0.72, outerRadius: 0.82, color: 0xc75f1f, opacity: 0.32 }];
    if (kind === "continuous-active") return [{ type: "path", color: 0x007f73, points: [from.toArray(), [0, 0.42, 0], to.toArray()] }, { type: "sphere", y: 0.72, radius: 0.1, color: 0x007f73, opacity: 0.86 }];
    if (kind === "continuous-passive") return [{ type: "path", color: 0xc75f1f, points: [to.toArray(), [0, 0.18, 0], from.toArray()] }, { type: "ring", radius: 0.58, outerRadius: 0.66, color: 0x007f73, opacity: 0.34 }];
    if (kind === "discrete-fade") return [{ type: "particles", color: 0x8fbfb7, count: 54, radius: 0.82, height: 0.58, opacity: 0.44 }];
    return [{ type: "line", color: 0xc75f1f, from: from.toArray(), to: to.toArray() }];
  }

  if (componentId === "environment-enhancement") {
    if (kind === "none") return [];
    if (kind === "environment") return [{ type: "ring", radius: 0.9, outerRadius: 0.98, color: 0x007f73, opacity: 0.32 }];
    if (kind === "nested") {
      return [
        { type: "ring", radius: 0.62, outerRadius: 0.68, color: 0xc75f1f, opacity: 0.34 },
        { type: "ring", radius: 1.08, outerRadius: 1.14, color: 0x007f73, opacity: 0.28 },
        { type: "sphere", x: 0.58, y: 0.64, z: -0.36, radius: 0.15, color: 0xfff0b5, opacity: 0.5 },
      ];
    }
    return [{ type: "ring", radius: 0.48, outerRadius: 0.55, color: 0xc75f1f, opacity: 0.36 }];
  }

  if (componentId === "text-comfort") {
    const base = previewCueVector(options.position);
    const target = previewCueVector(options.targetPosition).sub(base);
    if (kind === "near-body") return [{ type: "ring", radius: 0.42, outerRadius: 0.5, color: 0x007f73, opacity: 0.3 }, { type: "sphere", x: -0.22, y: 0.12, z: 0.18, radius: 0.06, color: 0xffd7a6 }];
    if (kind === "object-attached") return [{ type: "line", color: 0xc75f1f, from: [0, 0, 0], to: target.toArray() }, { type: "ring", radius: 0.34, outerRadius: 0.4, color: 0xc75f1f, opacity: 0.28 }];
    if (kind === "reader-facing") return [{ type: "ring", radius: 0.52, outerRadius: 0.58, color: 0x007f73, opacity: 0.32 }];
    return [{ type: "box", width: 0.78, height: 0.04, depth: 0.1, y: -0.08, color: 0x10201c, opacity: 0.28 }];
  }

  if (componentId === "interaction-control") {
    if (kind === "direct") return [{ type: "sphere", x: -0.24, y: 0.62, z: 0.36, radius: 0.08, color: 0xffd7a6 }, { type: "sphere", x: 0.24, y: 0.62, z: 0.36, radius: 0.08, color: 0xffd7a6 }];
    if (kind === "embodied-control") return [{ type: "path", color: 0x007f73, points: [[-0.44, 0.08, 0.72], [-0.12, 0.1, 0.22], [0.26, 0.08, -0.36]] }, { type: "ring", radius: 0.38, outerRadius: 0.46, color: 0x007f73, opacity: 0.3 }];
    if (kind === "branching-control") return [{ type: "box", width: 0.42, height: 0.24, depth: 0.1, x: -0.42, y: 0.58, z: -0.36, color: 0x007f73, opacity: 0.72 }, { type: "box", width: 0.42, height: 0.24, depth: 0.1, x: 0.42, y: 0.58, z: -0.36, color: 0xc75f1f, opacity: 0.72 }];
    return [];
  }

  return [];
}

function previewDescriptionCueLabel(componentId, proposal, options = {}) {
  if (componentId === "environment-enhancement" && options.kind === "environment") {
    return microhabitatCueLabel(previewMicrohabitatCueKind(proposal, options.item));
  }
  const kind = options.kind || selectedProposalKind(componentId, proposal);
  const labels = {
    "asset-topology": kind === "single" ? "source-order anchor" : kind === "map" ? "habitat map cue" : "visible specimen set",
    "dynamic-geometry": kind === "none" ? "no object movement" : kind === "flow" ? "particle flow cue" : kind === "zoom" ? "scale pulse cue" : kind === "focus" ? "focus cue" : "movement cue",
    "inter-beat-dynamics": interBeatDynamicsKindLabel(kind),
    "environment-enhancement": kind === "none" ? "no added setting" : kind === "nested" ? "nested scale cue" : "object focus cue",
    "text-comfort": textComfortKindLabel(kind),
    "interaction-control": interactionControlKindLabel(kind),
  };
  return labels[componentId] || shortText(proposal?.label || "selected option", 26);
}

function addPreviewCueVisual(group, spec) {
  const color = spec.color ?? 0x007f73;
  const opacity = spec.opacity ?? 0.38;
  if (spec.type === "ring") {
    const mesh = markFinalTuningGroundCircle(new THREE.Mesh(
      new THREE.RingGeometry(spec.radius || 0.5, spec.outerRadius || (spec.radius || 0.5) + 0.06, 64),
      new THREE.MeshBasicMaterial({ color, transparent: true, opacity, side: THREE.DoubleSide }),
    ));
    mesh.rotation.x = -Math.PI / 2;
    mesh.position.set(spec.x || 0, spec.y ?? 0.045, spec.z || 0);
    group.add(mesh);
    return mesh;
  }
  if (spec.type === "plane") {
    const mesh = new THREE.Mesh(
      new THREE.PlaneGeometry(spec.width || 0.8, spec.depth || 0.5),
      new THREE.MeshBasicMaterial({ color, transparent: true, opacity, side: THREE.DoubleSide }),
    );
    mesh.rotation.x = -Math.PI / 2;
    mesh.position.set(spec.x || 0, spec.y ?? 0.025, spec.z || 0);
    group.add(mesh);
    return mesh;
  }
  if (spec.type === "box") {
    const mesh = new THREE.Mesh(
      new THREE.BoxGeometry(spec.width || 0.4, spec.height || 0.18, spec.depth || 0.1),
      new THREE.MeshBasicMaterial({ color, transparent: true, opacity }),
    );
    mesh.position.set(spec.x || 0, spec.y ?? 0.2, spec.z || 0);
    if (Number.isFinite(spec.rotationY)) mesh.rotation.y = spec.rotationY;
    group.add(mesh);
    return mesh;
  }
  if (spec.type === "sphere") {
    const mesh = new THREE.Mesh(
      new THREE.SphereGeometry(spec.radius || 0.09, 24, 18),
      new THREE.MeshBasicMaterial({ color, transparent: true, opacity: spec.opacity ?? 0.72 }),
    );
    mesh.position.set(spec.x || 0, spec.y ?? 0.38, spec.z || 0);
    group.add(mesh);
    return mesh;
  }
  if (spec.type === "line") {
    const from = previewCueVector(spec.from);
    const to = previewCueVector(spec.to);
    const line = new THREE.Line(
      new THREE.BufferGeometry().setFromPoints([from, to]),
      new THREE.LineBasicMaterial({ color, transparent: true, opacity: spec.opacity ?? 0.78 }),
    );
    group.add(line);
    return line;
  }
  if (spec.type === "path") {
    const points = (spec.points || []).map((point) => previewCueVector(point));
    if (points.length < 2) return null;
    const line = new THREE.Line(
      new THREE.BufferGeometry().setFromPoints(points),
      new THREE.LineBasicMaterial({ color, transparent: true, opacity: spec.opacity ?? 0.72 }),
    );
    group.add(line);
    return line;
  }
  if (spec.type === "particles") {
    const geometry = new THREE.BufferGeometry();
    const positions = [];
    const count = spec.count || 42;
    const radius = spec.radius || 0.55;
    const height = spec.height || 0.52;
    for (let index = 0; index < count; index += 1) {
      const angle = index * 0.72;
      const band = index % 9;
      const localRadius = radius * (0.32 + (band / 8) * 0.68);
      positions.push(
        Math.cos(angle) * localRadius,
        0.22 + ((index % 7) / 6) * height,
        Math.sin(angle) * localRadius,
      );
    }
    geometry.setAttribute("position", new THREE.Float32BufferAttribute(positions, 3));
    const particles = markFinalTuningDecorativeParticles(new THREE.Points(
      geometry,
      new THREE.PointsMaterial({ color, size: spec.size || 0.04, transparent: true, opacity }),
    ));
    group.add(particles);
    return particles;
  }
  return null;
}

function addMicrohabitatCueSet(parent, cueKind, activePosition, options = {}) {
  const group = new THREE.Group();
  group.position.copy(previewCueVector(activePosition));
  parent.add(group);
  const effects = { group, zones: [], rings: [], labels: [] };
  for (const spec of microhabitatCueSpecs(cueKind)) {
    if (options.hideGroundCircles && spec.type === "ring") continue;
    const object = addPreviewCueVisual(group, spec);
    if (!object) continue;
    if (spec.type === "ring") effects.rings.push(object);
    else effects.zones.push(object);
  }
  if (options.includeLabel !== false) {
    const label = makeTextSprite(microhabitatCueLabel(cueKind), {
      y: options.labelY ?? 1.35,
      color: "#10201c",
      background: "rgba(255,253,244,0.9)",
      width: options.labelWidth || 1.44,
      height: 0.24,
    });
    group.add(label);
    effects.labels.push(label);
  }
  return effects;
}

function microhabitatCueSpecs(cueKind) {
  if (cueKind === "droplets") {
    return [
      { type: "particles", color: 0x007f73, count: 76, radius: 0.78, height: 0.66, opacity: 0.52 },
      { type: "ring", radius: 0.72, outerRadius: 0.8, color: 0x6a8fbf, opacity: 0.28 },
    ];
  }
  if (cueKind === "skin") {
    const specs = [
      { type: "plane", width: 1.36, depth: 0.72, color: 0xffd7a6, opacity: 0.36 },
      { type: "ring", radius: 0.52, outerRadius: 0.6, color: 0xc75f1f, opacity: 0.28 },
    ];
    for (let index = 0; index < 7; index += 1) {
      specs.push({ type: "box", width: 0.018, height: 0.035, depth: 0.32, x: -0.42 + index * 0.14, y: 0.12, z: -0.48, color: 0x10201c, opacity: 0.58, rotationY: -0.45 + index * 0.14 });
    }
    return specs;
  }
  if (cueKind === "crevice") {
    return [
      { type: "plane", width: 1.5, depth: 0.9, color: 0xd9e7df, opacity: 0.44 },
      { type: "box", width: 1.32, height: 0.035, depth: 0.07, y: 0.08, z: -0.34, color: 0x4b3b32, opacity: 0.62 },
      { type: "ring", radius: 0.46, outerRadius: 0.54, color: 0xc75f1f, opacity: 0.3 },
    ];
  }
  if (cueKind === "contact") {
    return [
      { type: "plane", width: 1.45, depth: 0.82, color: 0xf2d4bf, opacity: 0.38 },
      { type: "particles", color: 0xc75f1f, count: 42, radius: 0.52, height: 0.24, opacity: 0.5, size: 0.035 },
      { type: "path", color: 0xc75f1f, points: [[-0.62, 0.08, -0.26], [-0.22, 0.1, -0.08], [0.32, 0.1, 0.08], [0.66, 0.08, 0.3]] },
    ];
  }
  if (cueKind === "dark-corner") {
    return [
      { type: "box", width: 1.15, height: 0.9, depth: 0.08, y: 0.45, z: -0.66, color: 0x40352e, opacity: 0.3 },
      { type: "box", width: 0.08, height: 0.85, depth: 1.0, x: -0.58, y: 0.42, z: -0.18, color: 0x10201c, opacity: 0.34 },
      { type: "ring", radius: 0.48, outerRadius: 0.56, color: 0xc75f1f, opacity: 0.26 },
    ];
  }
  return [
    { type: "plane", width: 1.35, depth: 0.82, x: -0.24, z: -0.22, color: 0xcfe8df, opacity: 0.36 },
    { type: "plane", width: 0.95, depth: 0.64, x: 0.58, z: 0.42, color: 0xd6e1ef, opacity: 0.32 },
    { type: "ring", radius: 0.62, outerRadius: 0.7, color: 0x007f73, opacity: 0.28 },
  ];
}

function previewMicrohabitatCueKind(proposal, item) {
  const itemText = previewItemCorpus(item);
  const itemCue = microhabitatCueKindFromText(itemText);
  if (itemCue) return itemCue;
  return microhabitatCueKindFromText(previewCueCorpus(proposal, null, "")) || "room";
}

function microhabitatCueKindFromText(text) {
  const value = String(text || "").toLowerCase();
  if (/\b(flu|influenza|virus|breath|air|lung|droplet|microbe)\b/.test(value)) return "droplets";
  if (/\b(face|mite|skin|eyelash|follicle|cheek)\b/.test(value)) return "skin";
  if (/\b(bedbug|bed|mattress|crevice|sleep|blanket|furniture|luggage)\b/.test(value)) return "crevice";
  if (/\b(housefly|fly|arm|waste|fecal|contact|surface|kitchen)\b/.test(value)) return "contact";
  if (/\b(cockroach|cabinet|dark|moist|corner|basement|home)\b/.test(value)) return "dark-corner";
  if (/\b(room|carpet|shower|habitat|refrigerator|saltshaker|washing machine)\b/.test(value)) return "room";
  return null;
}

function microhabitatCueLabel(cueKind) {
  if (cueKind === "droplets") return "droplets / breath";
  if (cueKind === "skin") return "skin / eyelash";
  if (cueKind === "crevice") return "mattress crevice";
  if (cueKind === "contact") return "contact surface";
  if (cueKind === "dark-corner") return "dark moist corner";
  return "room habitat";
}

function previewCueCorpus(proposal, item, extraText = "") {
  return [
    proposal?.label,
    proposal?.description,
    proposal?.readerImpact,
    ...(proposal?.implementationHints || []),
    ...(proposal?.assetLinks || []).map((link) => `${link.assetId || ""} ${link.role || ""}`),
    previewItemCorpus(item),
    extraText,
  ].filter(Boolean).join(" ").toLowerCase();
}

function previewItemCorpus(item) {
  if (!item) return "";
  if (item.from || item.to) return `${previewItemCorpus(item.from)} ${previewItemCorpus(item.to)}`;
  return [
    item.id,
    item.title,
    item.text,
    item.quote,
    item.reason,
    ...(item.linkedAssetIds || []),
  ].filter(Boolean).join(" ").toLowerCase();
}

function previewCueVector(value) {
  if (value?.isVector3 || value instanceof THREE.Vector3) return value.clone();
  if (Array.isArray(value)) return new THREE.Vector3(Number(value[0]) || 0, Number(value[1]) || 0, Number(value[2]) || 0);
  if (value && typeof value === "object") return new THREE.Vector3(Number(value.x) || 0, Number(value.y) || 0, Number(value.z) || 0);
  return new THREE.Vector3();
}

function selectedOptionIdForComponent(component) {
  if (isSourceDynamicsPreviewComponentId(component.id)) {
    return sourceDynamicsPreviewForComponent(component.id)?.optionId || state.data.decisions[component.id]?.option?.optionId || null;
  }
  if (component.id === "inter-beat-dynamics") {
    const proposal = selectedInterBeatProposal(component, state.data.proposals[component.id], state.data.decisions[component.id]);
    return proposal?.optionId || null;
  }
  return state.selectedOptionId
    || state.data.decisions[component.id]?.option?.optionId
    || state.data.proposals[component.id]?.proposals?.[0]?.optionId
    || null;
}

function isSourceDynamicsPreviewComponentId(componentId) {
  return componentId === "dynamic-geometry" || componentId === "inter-beat-dynamics";
}

function sourceDynamicsPreviewForComponent(componentId) {
  return state.data?.sourceDynamicsPreviews?.[componentId] || null;
}

function selectedComponentPreview(component) {
  if (!component) return null;
  if (component.id === "interaction-control") return selectedInteractionControlBase();
  if (isSourceDynamicsPreviewComponentId(component.id)) {
    return sourceDynamicsPreviewForComponent(component.id)
      || (state.data.decisions[component.id]?.option?.sourceDynamicsPreview ? state.data.decisions[component.id].option : null);
  }
  if (component.id === "inter-beat-dynamics") {
    return selectedInterBeatProposal(component, state.data.proposals[component.id], state.data.decisions[component.id]);
  }
  return selectedTopologyProposal(component, state.data.proposals[component.id], state.data.decisions[component.id]);
}

function selectedInteractionControlBase() {
  return state.data?.interactionControlDraft?.option
    || {
      component: "interaction-control",
      optionId: "interaction-control-controller-button-press",
      label: "Controller button press",
      assetLinks: [],
    };
}

function selectedTopologyProposal(component, proposalBundle, decision) {
  const proposals = proposalBundle?.proposals || [];
  const selectedId = state.selectedOptionId || decision?.option?.optionId || proposalBundle?.defaultOptionId;
  return proposals.find((proposal) => proposal.optionId === selectedId)
    || decision?.option
    || proposals.find((proposal) => proposal.optionId === proposalBundle?.defaultOptionId)
    || proposals[0]
    || null;
}

function interBeatValidProposals(proposalBundle) {
  return (proposalBundle?.proposals || []).filter((proposal) => Boolean(inferInterBeatDynamicsKind(proposal)));
}

function interBeatDecisionIsStale(decision) {
  return Boolean(decision?.option) && !inferInterBeatDynamicsKind(decision.option);
}

function selectedInterBeatProposal(component, proposalBundle, decision) {
  const proposals = interBeatValidProposals(proposalBundle);
  const decisionOption = decision?.option && !interBeatDecisionIsStale(decision) ? decision.option : null;
  const selectedId = state.selectedOptionId || decisionOption?.optionId || proposalBundle?.defaultOptionId;
  return proposals.find((proposal) => proposal.optionId === selectedId)
    || decisionOption
    || proposals.find((proposal) => proposal.optionId === proposalBundle?.defaultOptionId)
    || proposals[0]
    || null;
}

function selectedModelAssetForTopology(proposal) {
  if (!state.selectedModelAssetId) return null;
  const linked = (proposal?.assetLinks || []).some((assetLink) => assetLink.assetId === state.selectedModelAssetId);
  const asset = findAssetById(state.selectedModelAssetId);
  return linked && asset && isModelAsset(asset) ? asset : null;
}

function topologySwapSequence(proposal) {
  if (inferTopologyKind(proposal) !== "single" || !topologyProposalIndicatesSwapping(proposal)) {
    return { applicable: false, steps: [] };
  }
  return topologySourceOrderSequence(proposal);
}

function topologySourceOrderSequence(proposal) {
  if (inferTopologyKind(proposal) !== "single") {
    return { applicable: false, steps: [] };
  }
  const proposalLinks = proposal?.assetLinks || [];
  const proposalAssetIds = new Set(proposalLinks.map((link) => link.assetId).filter(Boolean));
  const roleById = new Map(proposalLinks.filter((link) => link.assetId).map((link) => [link.assetId, link.role || "active specimen"]));
  const graphSteps = topologyGraphSwapSteps(proposalAssetIds, roleById);
  const proposalSteps = topologyProposalSwapSteps(proposalLinks, roleById);
  const steps = graphSteps.length > 1 ? graphSteps : proposalSteps;
  return {
    applicable: steps.length > 1,
    steps,
  };
}

function topologyGraphSwapSteps(proposalAssetIds, roleById) {
  const steps = [];
  const seen = new Set();
  for (const beat of state.data?.graph?.beats || []) {
    for (const assetId of beatAssetIds(beat)) {
      if (seen.has(assetId)) continue;
      if (proposalAssetIds.size && !proposalAssetIds.has(assetId)) continue;
      const asset = findAssetById(assetId);
      if (!isVisualTopologyAsset(asset)) continue;
      seen.add(assetId);
      steps.push({
        assetId,
        label: topologySpeciesLabel(asset, beat, assetId),
        role: roleById.get(assetId) || "active specimen",
        beatId: beat.id,
      });
    }
  }
  return steps;
}

function topologyProposalSwapSteps(assetLinks, roleById) {
  const steps = [];
  const seen = new Set();
  for (const assetLink of assetLinks || []) {
    const assetId = assetLink.assetId;
    if (!assetId || seen.has(assetId)) continue;
    const asset = findAssetById(assetId);
    if (!isVisualTopologyAsset(asset)) continue;
    seen.add(assetId);
    steps.push({
      assetId,
      label: topologySpeciesLabel(asset, null, assetId),
      role: roleById.get(assetId) || assetLink.role || "active specimen",
      beatId: null,
    });
  }
  return steps;
}

function topologyProposalIndicatesSwapping(proposal) {
  const text = topologyProposalText(proposal);
  return /\b(source order|active (specimen|species|creature|model|asset)|one species owns|one [a-z\s-]+ at a time|advances? through|swaps?|replaces?|rotate[s]? through|temporal|carousel|claim one region)\b/.test(text);
}

function topologyProposalText(proposal) {
  return [
    proposal?.label,
    proposal?.description,
    proposal?.readerImpact,
    ...(proposal?.implementationHints || []),
  ].join(" ").toLowerCase();
}

function isVisualTopologyAsset(asset) {
  return isSelectableAssetLink(asset);
}

function topologySpeciesLabel(asset, beat, assetId) {
  const shortBeatTitle = String(beat?.title || "").trim();
  if (shortBeatTitle && shortBeatTitle.length <= 36) return shortBeatTitle;
  const base = String(asset?.id || assetId || "Active specimen")
    .replace(/\.[^.]+$/, "")
    .replace(/_static.*$/i, "")
    .replace(/[-_][0-9a-f]{8,}$/i, "")
    .replace(/[-_]+/g, " ")
    .trim();
  return base ? titleCase(base) : "Active specimen";
}

function titleCase(value) {
  return String(value || "").replace(/\w\S*/g, (word) => word.charAt(0).toUpperCase() + word.slice(1).toLowerCase());
}

function topologySwapDuplicateCount(proposal) {
  const text = topologyProposalText(proposal);
  const range = text.match(/\b(\d+)\s*(?:to|-)\s*(\d+)\s+duplicate/);
  if (range) return Math.max(1, Math.min(10, Math.round((Number(range[1]) + Number(range[2])) / 2)));
  const exact = text.match(/\b(\d+)\s+duplicate/);
  if (exact) return Math.max(1, Math.min(10, Number(exact[1])));
  return 0;
}

function topologySwapStatusText(sequence, index) {
  const steps = sequence?.steps || [];
  const active = steps[index] || steps[0];
  if (!active) return "No active species";
  return `${index + 1}/${steps.length} ${active.label}`;
}

function clampTopologySwapIndex(steps) {
  const max = Math.max((steps || []).length - 1, 0);
  if (!Number.isFinite(state.selectedTopologySwapIndex)) state.selectedTopologySwapIndex = 0;
  state.selectedTopologySwapIndex = Math.max(0, Math.min(max, state.selectedTopologySwapIndex));
  return state.selectedTopologySwapIndex;
}

function lockedSingleAnchorSourceOrderSequence() {
  const decision = state.data?.decisions?.["asset-topology"];
  const option = checkpointIsCurrent("asset-topology") ? decision?.option : null;
  if (!option || inferTopologyKind(option) !== "single") return { applicable: false, steps: [] };
  return topologySourceOrderSequence(option);
}

function narrativeSingleAnchorContext(beats, beatIndex) {
  const sequence = lockedSingleAnchorSourceOrderSequence();
  if (!sequence.applicable) return null;
  const activeIndex = narrativeSourceIndexForBeat(beats, beatIndex, sequence);
  state.selectedTopologySwapIndex = activeIndex;
  return {
    sequence,
    activeIndex,
    active: sequence.steps[activeIndex] || sequence.steps[0] || null,
  };
}

function narrativeSourceIndexForBeat(beats, beatIndex, sequence) {
  const steps = sequence?.steps || [];
  if (!steps.length) return 0;
  const clampedBeatIndex = Math.max(0, Math.min((beats || []).length - 1, beatIndex));
  const beat = beats?.[clampedBeatIndex];
  const linkedAssetIds = new Set(beat?.linkedAssetIds || []);
  const directIndex = steps.findIndex((step) => step.beatId === beat?.id || linkedAssetIds.has(step.assetId));
  if (directIndex >= 0) return directIndex;
  return Math.max(0, Math.min(steps.length - 1, clampedBeatIndex));
}

function narrativeBeatIndexForSourceIndex(beats, sequence, sourceIndex) {
  const maxBeatIndex = Math.max((beats || []).length - 1, 0);
  const steps = sequence?.steps || [];
  const step = steps[Math.max(0, Math.min(steps.length - 1, sourceIndex))];
  if (!step) return Math.max(0, Math.min(maxBeatIndex, sourceIndex));
  const directIndex = (beats || []).findIndex((beat) => {
    if (beat.id === step.beatId) return true;
    return (beat.linkedAssetIds || []).includes(step.assetId);
  });
  if (directIndex >= 0) return directIndex;
  return Math.max(0, Math.min(maxBeatIndex, sourceIndex));
}

function syncTopologySourceIndexForNarrativeBeat(beats, beatIndex) {
  const sequence = lockedSingleAnchorSourceOrderSequence();
  if (!sequence.applicable) return;
  state.selectedTopologySwapIndex = narrativeSourceIndexForBeat(beats, beatIndex, sequence);
}

function cumulativeSingleAnchorContext(beats, beatIndex) {
  return narrativeSingleAnchorContext(beats, beatIndex);
}

function cumulativeSingleAnchorTransitionContext(transitions, transitionIndex) {
  const sequence = lockedSingleAnchorSourceOrderSequence();
  if (!sequence.applicable) return null;
  const transition = transitions?.[Math.max(0, Math.min((transitions || []).length - 1, transitionIndex))];
  const activeIndex = narrativeSourceIndexForBeat([transition?.from].filter(Boolean), 0, sequence);
  const targetIndex = narrativeSourceIndexForBeat([transition?.to].filter(Boolean), 0, sequence);
  state.selectedTopologySwapIndex = activeIndex;
  return {
    sequence,
    activeIndex,
    targetIndex,
    active: sequence.steps[activeIndex] || sequence.steps[0] || null,
    target: sequence.steps[targetIndex] || null,
  };
}

function selectedProposalForComponentId(componentId) {
  if (componentId === "transition-pacing") return null;
  const component = componentById(componentId);
  if (!component) return null;
  return selectedComponentPreview(component);
}

function cumulativeItemsForComponent(componentId, proposal = selectedProposalForComponentId(componentId)) {
  if (componentId === "dynamic-geometry") return dynamicPreviewBeats(proposal);
  if (componentId === "inter-beat-dynamics") return interBeatPreviewTransitions(proposal);
  if (componentId === "environment-enhancement") return contextPreviewBeats(proposal);
  if (isSpatialRelationsComponentId(componentId)) return textComfortPreviewBeats(proposal);
  if (componentId === "interaction-control") return interactionPreviewBeats(proposal);
  if (componentId === "transition-pacing") return finalReviewBeats();
  return [];
}

function cumulativeSelectedIndexForComponent(componentId, items = cumulativeItemsForComponent(componentId)) {
  const max = Math.max((items || []).length - 1, 0);
  if (componentId === "dynamic-geometry") return Math.max(0, Math.min(max, state.selectedDynamicBeatIndex));
  if (componentId === "inter-beat-dynamics") return Math.max(0, Math.min(max, state.selectedInterBeatTransitionIndex));
  if (componentId === "environment-enhancement") return Math.max(0, Math.min(max, state.selectedContextBeatIndex));
  if (isSpatialRelationsComponentId(componentId)) return Math.max(0, Math.min(max, state.selectedTextBeatIndex));
  if (componentId === "interaction-control") return Math.max(0, Math.min(max, state.selectedInteractionBeatIndex));
  if (componentId === "transition-pacing") return Math.max(0, Math.min(max, state.selectedFinalReviewBeatIndex));
  return 0;
}

function syncCumulativeSourceIndexForComponent(componentId) {
  const sequence = lockedSingleAnchorSourceOrderSequence();
  if (!sequence.applicable) return;
  const items = cumulativeItemsForComponent(componentId);
  const selectedIndex = cumulativeSelectedIndexForComponent(componentId, items);
  if (componentId === "inter-beat-dynamics") {
    const transition = items[selectedIndex];
    state.selectedTopologySwapIndex = narrativeSourceIndexForBeat([transition?.from].filter(Boolean), 0, sequence);
    return;
  }
  state.selectedTopologySwapIndex = narrativeSourceIndexForBeat(items, selectedIndex, sequence);
}

function finalReviewBeats() {
  return spatialPreviewBeats();
}

function finalReviewSceneAssetLabel(beat, sceneContext, fallbackAsset = null) {
  const savedSpatialSceneAssets = exactSpatialSceneAssetLinkSet(sceneContext);
  if (savedSpatialSceneAssets.available) {
    const count = savedSpatialSceneAssets.links.length;
    return count ? `${count} scene object${count === 1 ? "" : "s"}` : "text-only state";
  }
  const asset = fallbackAsset || beat?.linkedAssetIds?.map(findAssetById).find(Boolean);
  return asset ? (asset.type || "asset") : "text-only state";
}

function finalReviewCumulativeContextForBeat(beats, beatIndex, sceneContext, beat) {
  if (
    !beat
    || sceneContext?.variantOptionId
    || exactSpatialSceneAssetLinkSet(sceneContext).available
    || !(beat.linkedAssetIds || []).length
  ) return null;
  return cumulativeSingleAnchorContext(beats, beatIndex);
}

function finalReviewSceneContextsForBeat(beat) {
  if (!beat?.id) return [];
  const group = variantGroupForBeat(beat);
  const defaultOption = sourceGraphDefaultVariantOption(group);
  if (!group || !defaultOption) return [spatialSceneContext(beat.id)];
  return [
    spatialSceneContext(beat.id, group.id, defaultOption.id),
    ...(group.options || [])
      .filter((option) => option.id !== defaultOption.id)
      .map((option) => spatialSceneContext(beat.id, group.id, option.id)),
  ];
}

function finalReviewSelectedSceneContext(beats = finalReviewBeats(), beatIndex = state.selectedFinalReviewBeatIndex) {
  const beat = beats?.[Math.max(0, Math.min((beats || []).length - 1, beatIndex))];
  const contexts = finalReviewSceneContextsForBeat(beat);
  if (!contexts.length) {
    state.selectedFinalReviewSceneContext = null;
    return null;
  }
  const stored = state.selectedFinalReviewSceneContext?.beatId
    ? spatialSceneContext(
      state.selectedFinalReviewSceneContext.beatId,
      state.selectedFinalReviewSceneContext.variantGroupId,
      state.selectedFinalReviewSceneContext.variantOptionId,
    )
    : null;
  const selected = stored
    ? contexts.find((context) => sourceGraphTransitionContextMatches(context, stored)) || contexts[0]
    : contexts[0];
  state.selectedFinalReviewSceneContext = selected;
  return selected;
}

function finalReviewBeatForSceneContext(context) {
  return dynamicPreviewBeatForSceneContext(null, context) || spatialSceneBeat(context);
}

function finalReviewDecisionKinds() {
  return {
    topology: lockedDecisionKind("asset-topology"),
    geometry: lockedDecisionKind("dynamic-geometry"),
    transition: lockedDecisionKind("inter-beat-dynamics"),
    context: lockedDecisionKind("environment-enhancement"),
    text: lockedSpatialTextKind(),
    interaction: lockedDecisionKind("interaction-control"),
  };
}

function finalReviewTransitionPlaybackForContext(context) {
  const pending = state.finalReviewPendingTransition;
  state.finalReviewPendingTransition = null;
  if (
    !pending?.fromContext?.beatId
    || !pending?.toContext?.beatId
    || !sourceGraphTransitionContextMatches(pending.toContext, context)
  ) return null;
  const proposal = sourceDynamicsPreviewForComponent("inter-beat-dynamics")
    || state.data?.decisions?.["inter-beat-dynamics"]?.option
    || null;
  if (!proposal) return null;
  const playback = interBeatBoundaryPlaybackSummary(proposal, {
    ...context,
    ...(pending.edgeId ? { transitionEdgeId: pending.edgeId } : {}),
  });
  const fromContext = playback?.boundary?.fromSceneContext
    || (playback?.boundary?.fromBeatId ? interBeatDefaultSceneContextForBeat(playback.boundary.fromBeatId) : null);
  const toContext = playback?.boundary?.toSceneContext
    || (playback?.boundary?.toBeatId ? interBeatDefaultSceneContextForBeat(playback.boundary.toBeatId) : null);
  if (
    !sourceGraphTransitionContextMatches(fromContext, pending.fromContext)
    || !sourceGraphTransitionContextMatches(toContext, pending.toContext)
    || playback?.canScrub !== true
  ) return null;
  return playback;
}

function finalReviewTransitionAssetLinks(playback) {
  const boundary = playback?.boundary;
  if (!boundary?.from || !boundary?.to) return [];
  return narrativeSceneAssetLinks(
    sourceDynamicsPreviewForComponent("inter-beat-dynamics"),
    [boundary.from, boundary.to],
  );
}

function finalReviewVariantSteppedOption(group, current, direction) {
  const options = sourceGraphDisplayedVariantOptions(group);
  if (!options.length || !current || !direction) return null;
  const currentIndex = Math.max(0, options.findIndex((option) => option.id === current.id));
  let nextIndex = currentIndex + Math.sign(direction);
  if (group.control?.wrap !== false) nextIndex = (nextIndex + options.length) % options.length;
  else if (nextIndex < 0 || nextIndex >= options.length) return null;
  return options[nextIndex] || null;
}

function finalReviewVariantInteractionForEdge(group, fromOptionId, toOptionId) {
  if (!group || !fromOptionId || !toOptionId) return null;
  const edge = interactionVariantSwitchEdges().find((candidate) => (
    candidate.from?.variantGroupId === group.id
    && candidate.from?.variantOptionId === fromOptionId
    && candidate.to?.variantGroupId === group.id
    && candidate.to?.variantOptionId === toOptionId
  ));
  return edge ? interactionVariantEdgeControlForEdge(edge) : null;
}

function finalReviewVariantHasEdgeContract(group) {
  return Boolean(group && interactionVariantSwitchEdges().some((edge) => (
    edge.from?.variantGroupId === group.id || edge.to?.variantGroupId === group.id
  )));
}

function finalReviewVariantUiButtonAllowed(group, fromOptionId, toOptionId, beat) {
  if (!group || !fromOptionId || !toOptionId) return false;
  if (!finalReviewVariantHasEdgeContract(group)) {
    const record = interactionVariantControlForBeat(beat, interactionVariantControlRecords());
    return variantInteractionPolicyKind(record?.effectivePolicy) === "ui-button-press";
  }
  const record = finalReviewVariantInteractionForEdge(group, fromOptionId, toOptionId);
  return variantInteractionPolicyKind(record?.effectivePolicy) === "ui-button-press";
}

function finalReviewVariantButtonPresentation(record, fallbackLabel, fallbackPosition) {
  const configuration = record?.configuration;
  const button = Array.isArray(configuration?.buttons)
    ? configuration.buttons.find((candidate) => String(candidate?.action || "") === "select-variant")
      || configuration.buttons[0]
    : null;
  const authoredLayout = record?.overridden === true || record?.authored === true;
  const position = authoredLayout && Array.isArray(button?.position) ? button.position : fallbackPosition;
  const size = authoredLayout && Array.isArray(button?.size) ? button.size : [0.32, 0.08];
  const finiteValue = (value, fallback) => Number.isFinite(Number(value)) ? Number(value) : fallback;
  return {
    id: String(button?.id || ""),
    label: String(button?.label || fallbackLabel || "Select").trim(),
    position: [
      THREE.MathUtils.clamp(finiteValue(position?.[0], fallbackPosition[0]), 0, 1),
      THREE.MathUtils.clamp(finiteValue(position?.[1], fallbackPosition[1]), 0, 1),
    ],
    size: [
      THREE.MathUtils.clamp(finiteValue(size?.[0], 0.32), 0.04, 1),
      THREE.MathUtils.clamp(finiteValue(size?.[1], 0.08), 0.04, 1),
    ],
  };
}

function finalReviewTextPanelVariantState(beat, sceneContext) {
  const group = variantGroupForBeat(beat);
  const orderedOptions = sourceGraphDisplayedVariantOptions(group);
  const selectedOption = group?.options?.find((option) => option.id === sceneContext?.variantOptionId)
    || sourceGraphDefaultVariantOption(group);
  if (!group || !selectedOption) return null;
  const previousOption = finalReviewVariantSteppedOption(group, selectedOption, -1);
  const nextOption = finalReviewVariantSteppedOption(group, selectedOption, 1);
  const previousInteraction = previousOption
    ? finalReviewVariantInteractionForEdge(group, selectedOption.id, previousOption.id)
    : null;
  const nextInteraction = nextOption
    ? finalReviewVariantInteractionForEdge(group, selectedOption.id, nextOption.id)
    : null;
  const beatId = sceneContext?.beatId || beat.id;
  const previousDisabled = !previousOption
    || !finalReviewVariantUiButtonAllowed(group, selectedOption.id, previousOption.id, beat);
  const nextDisabled = !nextOption
    || !finalReviewVariantUiButtonAllowed(group, selectedOption.id, nextOption.id, beat);
  let previousPresentation = finalReviewVariantButtonPresentation(
    previousInteraction,
    group.control?.previousLabel || "Previous",
    [0.2, TEXT_PANEL_ACTION_CENTER_Y],
  );
  let nextPresentation = finalReviewVariantButtonPresentation(
    nextInteraction,
    group.control?.nextLabel || "Next",
    [0.8, TEXT_PANEL_ACTION_CENTER_Y],
  );
  [previousPresentation, nextPresentation] = normalizeTextPanelActionPair(
    previousPresentation,
    nextPresentation,
    { leftVisible: !previousDisabled, rightVisible: !nextDisabled },
  );
  return {
    group,
    selectedOption,
    selectedIndex: Math.max(0, orderedOptions.findIndex((option) => option.id === selectedOption.id)),
    previousDisabled,
    nextDisabled,
    previousPresentation,
    nextPresentation,
    previousTargetContext: previousOption
      ? spatialSceneContext(beatId, group.id, previousOption.id)
      : null,
    nextTargetContext: nextOption
      ? spatialSceneContext(beatId, group.id, nextOption.id)
      : null,
  };
}

async function openFinalReviewScene(targetContext) {
  if (!targetContext?.beatId || storyvrNavigationRequestPending) return false;
  const beats = finalReviewBeats();
  const selectedIndex = beats.findIndex((beat) => beat.id === targetContext.beatId);
  const beat = beats[selectedIndex];
  if (!beat) return false;
  const validContext = finalReviewSceneContextsForBeat(beat)
    .find((context) => sourceGraphTransitionContextMatches(context, targetContext));
  if (!validContext) return false;
  const currentContext = finalReviewSelectedSceneContext(beats, state.selectedFinalReviewBeatIndex);
  if (
    selectedIndex === state.selectedFinalReviewBeatIndex
    && sourceGraphTransitionContextMatches(validContext, currentContext)
  ) return false;
  const authoredTransition = authoredMotionTransitions({ preserveParallel: true, includeSameBeat: true })
    .find((candidate) => (
      sourceGraphTransitionContextMatches(candidate.fromContext, currentContext)
      && sourceGraphTransitionContextMatches(candidate.toContext, validContext)
    )) || null;
  state.finalReviewPendingTransition = authoredTransition ? {
    edgeId: authoredTransition.edgeId || authoredTransition.key || "",
    fromContext: cloneJson(currentContext),
    toContext: cloneJson(validContext),
  } : null;
  state.finalReviewViewerCameraState = captureFinalReviewViewerCameraState();
  const currentEntry = storyvrNavigationFromHistoryState(window.history.state);
  const opened = await requestStoryvrBrowserNavigation(
    createStoryvrNavigationRoute("transition-pacing", validContext),
    { parentEntryId: currentEntry?.entryId },
  );
  if (!opened) state.finalReviewPendingTransition = null;
  return opened;
}

async function applyFinalReviewVariantSelection(targetContext) {
  if (!targetContext?.variantOptionId) return false;
  return openFinalReviewScene(targetContext);
}

function currentFinalTuningPrompt() {
  if (state.activeId === "transition-pacing") return currentEditNotesValue();
  return finalTuningPromptForDecision(state.data?.decisions?.["transition-pacing"]);
}

function finalReviewTuningDirectives(prompt = currentFinalTuningPrompt()) {
  const text = String(prompt || "").toLowerCase();
  const suppress = /\b(no|not|hide|remove|disable|without|exclude|avoid|clear|suppress)\b/.test(text);
  const ground = /\b(ground|floor|surface|base|stage)\b/.test(text);
  const circles = /\b(circle|circles|ring|rings|halo|halos|outline|outlines)\b/.test(text);
  const particles = /\b(particle|particles|particle-field|particlefield|specks|sparkles)\b/.test(text);
  return {
    hideGroundCircles: suppress && ground && circles,
    hideDecorativeParticles: suppress && particles,
  };
}

function markFinalTuningGroundCircle(object) {
  if (object?.userData) object.userData.finalTuningGroundCircle = true;
  return object;
}

function markFinalTuningDecorativeParticles(object) {
  if (object?.userData) object.userData.finalTuningDecorativeParticles = true;
  return object;
}

function applyFinalReviewTuningDirectives(viewer, directives = finalReviewTuningDirectives()) {
  if (!viewer?.scene) return;
  const groundCirclesVisible = !directives.hideGroundCircles;
  const decorativeParticlesVisible = !directives.hideDecorativeParticles;
  viewer.scene.traverse((object) => {
    if (object.userData?.finalTuningGroundCircle) object.visible = groundCirclesVisible;
    if (object.userData?.finalTuningDecorativeParticles) object.visible = decorativeParticlesVisible;
  });
}

function updateFinalReviewTuningFromPrompt() {
  applyFinalReviewTuningDirectives(finalReviewViewer, finalReviewTuningDirectives());
}

function clampFinalReviewBeatIndex(beats) {
  const max = Math.max((beats || []).length - 1, 0);
  if (!Number.isFinite(state.selectedFinalReviewBeatIndex)) state.selectedFinalReviewBeatIndex = 0;
  state.selectedFinalReviewBeatIndex = Math.max(0, Math.min(max, state.selectedFinalReviewBeatIndex));
  return state.selectedFinalReviewBeatIndex;
}

function finalReviewRegionSpecs() {
  return [
    { kind: "story", label: "story context", color: 0x007f73, position: new THREE.Vector3(0, 0, 0) },
  ];
}

function microhabitatForBeat(beat) {
  return finalReviewRegionSpecs()[0];
}

function dynamicPreviewBeats(proposal) {
  const graphBeats = state.data.graph.beats || [];
  const evidenceByBeat = new Map((proposal?.sourceEvidence || [])
    .filter((item) => item.beatId)
    .map((item) => [item.beatId, item]));
  return graphBeats
    .filter((beat) => beatAssetIds(beat).length)
    .map((beat) => {
      const linkedAssetIds = beatAssetIds(beat);
      const evidence = evidenceByBeat.get(beat.id);
      return {
        id: beat.id,
        atomicBeatIds: uniqueMotionBeatIds(beat.atomicBeatIds || []),
        title: beat.title || beat.id,
        text: beat.text || beat.section || evidence?.quote || "",
        linkedAssetIds,
        quote: evidence?.quote || "",
        reason: evidence?.reason || "",
        evidence,
      };
    });
}

function dynamicPreviewHasEmbeddedGlbAnimation(proposal, beat) {
  if (!beat?.id) return false;
  const linkedAssetIds = new Set(beat.linkedAssetIds || []);
  const hasSharedTimelineState = [...linkedAssetIds].some((assetId) => {
    const playback = sourcePlaybackAssetForId(assetId);
    const beatState = sourcePlaybackBeatStateForAsset(playback, beat.id);
    return playback?.mode === "shared-timeline"
      && beatState?.presence !== "inactive"
      && beatState?.localProgress != null;
  });
  if (hasSharedTimelineState) return true;
  const motionTracks = eligibleSourceMotionTracks("dynamic-geometry");
  if (motionTracks.length) {
    return dynamicMotionTracksForBeat(beat).some((track) => (
      !linkedAssetIds.size || linkedAssetIds.has(track.assetId)
    ));
  }
  const beatIds = new Set(uniqueMotionBeatIds([beat.id, ...(beat.atomicBeatIds || [])]));
  return (proposal?.sourceDynamics?.assets || []).some((asset) => {
    if (!asset?.hasEmbeddedAnimation || !linkedAssetIds.has(asset.assetId)) return false;
    const assignedBeatIds = uniqueMotionBeatIds(asset.beatIds || []);
    return !assignedBeatIds.length || assignedBeatIds.some((beatId) => beatIds.has(beatId));
  });
}

function clampDynamicBeatIndex(beats) {
  const max = Math.max((beats || []).length - 1, 0);
  if (!Number.isFinite(state.selectedDynamicBeatIndex)) state.selectedDynamicBeatIndex = 0;
  state.selectedDynamicBeatIndex = Math.max(0, Math.min(max, state.selectedDynamicBeatIndex));
  return state.selectedDynamicBeatIndex;
}

function dynamicSceneAssetLinks(proposal, beats, sceneContext = null) {
  const assetLinks = narrativeSceneAssetLinks(proposal, beats);
  const resolvedSceneContext = sceneContext?.beatId ? sceneContext : activeDynamicSceneContext();
  if (!resolvedSceneContext?.beatId) return assetLinks;
  const linkByAssetId = new Map(assetLinks.map((link) => [String(link.assetId), link]));
  const placedEntities = spatialSceneEntities(lockedSpatialRelationsContract(), resolvedSceneContext)
    .filter((entity) => (
      ["glb", "image-plane"].includes(spatialEntityType(entity))
      && entity?.id
      && entity?.assetId
    ));
  if (!placedEntities.length) return assetLinks;
  const representedAssetIds = new Set();
  const placedLinks = placedEntities.map((entity) => {
    const assetId = String(entity.assetId);
    const sourceLink = linkByAssetId.get(assetId);
    const asset = findAssetById(assetId);
    representedAssetIds.add(assetId);
    return {
      ...(sourceLink || {}),
      assetId,
      entityId: String(entity.id),
      role: sourceLink?.role || entity.role || asset?.role || asset?.type || "dynamic asset",
    };
  });
  return [
    ...placedLinks,
    ...assetLinks.filter((link) => !representedAssetIds.has(String(link.assetId))),
  ];
}

function contextPreviewBeats(proposal) {
  return dynamicPreviewBeats(proposal);
}

function clampContextBeatIndex(beats) {
  const max = Math.max((beats || []).length - 1, 0);
  if (!Number.isFinite(state.selectedContextBeatIndex)) state.selectedContextBeatIndex = 0;
  state.selectedContextBeatIndex = Math.max(0, Math.min(max, state.selectedContextBeatIndex));
  return state.selectedContextBeatIndex;
}

function contextSceneAssetLinks(proposal, beats) {
  return narrativeSceneAssetLinks(proposal, beats);
}

const SPATIAL_RELATIONS_COMPONENT_ID = "spatial-relations";
const LEGACY_TEXT_COMFORT_COMPONENT_ID = "text-comfort";
const ATTENTION_GUIDANCE_COMPONENT_ID = "attention-guidance";

function spatialSceneContext(beatId, variantGroupId = null, variantOptionId = null) {
  return {
    beatId: String(beatId || "").trim(),
    variantGroupId: String(variantGroupId || "").trim() || null,
    variantOptionId: String(variantOptionId || "").trim() || null,
  };
}

function activeDynamicSceneContext() {
  const context = state.dynamicEditorScene;
  if (!context?.beatId) return null;
  const normalized = spatialSceneContext(context.beatId, context.variantGroupId, context.variantOptionId);
  return spatialSceneBeat(normalized) ? normalized : null;
}

function dynamicStorySceneContexts() {
  const contexts = [];
  for (const beat of state.data?.graph?.beats || []) {
    const group = variantGroupForBeat(beat);
    const defaultOption = sourceGraphDefaultVariantOption(group);
    contexts.push(spatialSceneContext(beat.id, group?.id, defaultOption?.id));
    if (!group || !defaultOption) continue;
    for (const option of group.options || []) {
      if (option.id === defaultOption.id) continue;
      contexts.push(spatialSceneContext(beat.id, group.id, option.id));
    }
  }
  return contexts;
}

function dynamicMotionTracksForBeat(beat) {
  if (!beat?.id) return [];
  const beatIds = new Set(uniqueMotionBeatIds([beat.id, ...(beat.atomicBeatIds || [])]));
  return eligibleSourceMotionTracks("dynamic-geometry").filter((track) => (
    uniqueMotionBeatIds(sourceMotionDraftForTrack(track)?.beatIds || []).some((beatId) => beatIds.has(beatId))
  ));
}

function dynamicSharedTimelineStatesForSceneContext(context) {
  const beat = spatialSceneBeat(context);
  if (!beat) return [];
  const graphBeat = (state.data?.graph?.beats || []).find((candidate) => candidate.id === context.beatId) || beat;
  const scene = spatialSceneRecordForContext(lockedSpatialRelationsContract(), context);
  const sceneAssetIds = spatialSceneLinkedAssetIds(scene, graphBeat, sourceGraphVariantOption(context));
  return uniqueStrings(sceneAssetIds).flatMap((assetId) => {
    const playback = sourcePlaybackAssetForId(assetId);
    const beatState = sourcePlaybackBeatStateForAsset(playback, beat.id);
    return playback?.mode === "shared-timeline"
      && beatState?.presence !== "inactive"
      && beatState?.localProgress != null
      ? [{ assetId, playback, beatState }]
      : [];
  });
}

function dynamicMotionTracksForSceneContext(context) {
  const beat = spatialSceneBeat(context);
  if (!beat) return [];
  const graphBeat = (state.data?.graph?.beats || []).find((candidate) => candidate.id === context.beatId) || beat;
  const scene = spatialSceneRecordForContext(lockedSpatialRelationsContract(), context);
  const sceneAssetIds = new Set(spatialSceneLinkedAssetIds(scene, graphBeat, sourceGraphVariantOption(context)));
  return dynamicMotionTracksForBeat(beat).filter((track) => sceneAssetIds.has(track.assetId));
}

function dynamicPreviewBeatForSceneContext(proposal, context) {
  const beat = spatialSceneBeat(context);
  if (!beat) return null;
  const graphBeat = (state.data?.graph?.beats || []).find((candidate) => candidate.id === context.beatId) || beat;
  const option = sourceGraphVariantOption(context);
  const spatialContract = lockedSpatialRelationsContract();
  const spatialScene = spatialSceneRecordForContext(spatialContract, context);
  const savedSceneAssetIds = spatialSceneLinkedAssetIds(spatialScene, graphBeat, option, context);
  const evidence = (proposal?.sourceEvidence || []).find((item) => item.beatId === beat.id);
  return {
    ...beat,
    atomicBeatIds: uniqueMotionBeatIds(beat.atomicBeatIds || []),
    linkedAssetIds: uniqueStrings(savedSceneAssetIds),
    quote: evidence?.quote || "",
    reason: evidence?.reason || "",
    evidence,
  };
}

function activeInterBeatSceneContext() {
  const context = state.interBeatEditorScene;
  if (!context?.beatId) return null;
  const normalized = spatialSceneContext(context.beatId, context.variantGroupId, context.variantOptionId);
  if (context.transitionEdgeId) normalized.transitionEdgeId = context.transitionEdgeId;
  return spatialSceneBeat(normalized) ? normalized : null;
}

function activeInterBeatCanvasPreviewContext() {
  const context = state.interBeatCanvasPreviewScene;
  if (!context?.beatId) return null;
  const normalized = spatialSceneContext(context.beatId, context.variantGroupId, context.variantOptionId);
  if (context.transitionEdgeId) normalized.transitionEdgeId = context.transitionEdgeId;
  return spatialSceneBeat(normalized) ? normalized : null;
}

function activeInteractionSceneContext() {
  const context = state.interactionEditorScene;
  if (!context?.beatId) return null;
  const normalized = spatialSceneContext(context.beatId, context.variantGroupId, context.variantOptionId);
  if (!spatialSceneBeat(normalized)) return null;
  return {
    ...normalized,
    ...(context.interactionTargetType && context.interactionTargetId && context.interactionKind ? {
      interactionTargetType: context.interactionTargetType,
      interactionTargetId: context.interactionTargetId,
      interactionKind: context.interactionKind,
    } : {}),
  };
}

function activeInteractionNavigationScene() {
  const context = state.interactionEditorScene;
  const sceneContext = activeInteractionSceneContext();
  if (!sceneContext) return null;
  return {
    ...sceneContext,
    ...(context?.interactionTargetType && context?.interactionTargetId && context?.interactionKind ? {
      interactionTargetType: context.interactionTargetType,
      interactionTargetId: context.interactionTargetId,
      interactionKind: context.interactionKind,
    } : {}),
  };
}

function interactionPreviewBeatForSceneContext(proposal, context) {
  return dynamicPreviewBeatForSceneContext(proposal, context) || spatialSceneBeat(context);
}

function interBeatStorySceneContexts() {
  return dynamicStorySceneContexts();
}

function interBeatDefaultSceneContextForBeat(beatId) {
  const beat = (state.data?.graph?.beats || []).find((candidate) => candidate.id === beatId);
  const group = beat ? variantGroupForBeat(beat) : null;
  const defaultOption = sourceGraphDefaultVariantOption(group);
  return spatialSceneContext(beatId, group?.id, defaultOption?.id);
}

function interBeatPreviewBeatForSceneContext(proposal, context) {
  const beat = dynamicPreviewBeatForSceneContext(proposal, context);
  if (!beat) return null;
  const isTextOnly = isAuthoredTextOnlyTimelineBeat(beat);
  const sceneAssetIds = new Set(beat.linkedAssetIds || []);
  const sourcePartStates = sourcePartStatesForPreviewBeat(context.beatId).filter((item) => (
    sceneAssetIds.size
      ? !item.assetId || sceneAssetIds.has(item.assetId)
      : isTextOnly && item.playbackMode === "frozen"
  ));
  return {
    ...beat,
    isTextOnly,
    sourcePartStates,
  };
}

function interBeatBoundaryForSceneContext(proposal, context) {
  const toSceneContext = spatialSceneContext(context?.beatId, context?.variantGroupId, context?.variantOptionId);
  if (context?.transitionEdgeId) toSceneContext.transitionEdgeId = context.transitionEdgeId;
  const beats = interBeatStoryBeats(proposal);
  const foundBeatIndex = beats.findIndex((beat) => beat.id === toSceneContext.beatId);
  const beatIndex = Math.max(0, foundBeatIndex);
  const baseBeat = beats[beatIndex] || null;
  const beat = interBeatPreviewBeatForSceneContext(proposal, toSceneContext) || baseBeat;
  const authoredTransitions = authoredMotionTransitions();
  const authoredTransitionCandidates = authoredMotionTransitions({ preserveParallel: true, includeSameBeat: true });
  const authoredTransition = (toSceneContext.transitionEdgeId
    ? authoredTransitionCandidates.find((candidate) => candidate.edgeId === toSceneContext.transitionEdgeId)
    : null)
    || authoredTransitionCandidates.find((candidate) => (
      sourceGraphTransitionContextMatches(candidate.toContext, toSceneContext)
    ))
    || authoredTransitions.find((candidate) => candidate.to.id === toSceneContext.beatId)
    || null;
  const fromBaseBeat = authoredTransition
    ? beats.find((candidate) => candidate.id === authoredTransition.from.id) || null
    : null;
  const fromSceneContext = authoredTransition?.fromContext || null;
  const fromBeat = fromSceneContext
    ? interBeatPreviewBeatForSceneContext(proposal, fromSceneContext) || fromBaseBeat
    : null;
  const transitions = interBeatPreviewTransitions(proposal);
  const baseTransition = authoredTransition
    ? transitions.find((candidate) => candidate.edgeId === authoredTransition.edgeId) || null
    : null;
  const transition = baseTransition && beatSourcePartPlaybackMode(beat) !== "frozen"
    ? { ...baseTransition, from: fromBeat || baseTransition.from, to: beat || baseTransition.to }
    : null;
  const scopedTransitions = transition
    ? transitions.map((candidate) => candidate.edgeId === transition.edgeId ? transition : candidate)
    : transitions;
  return {
    beats,
    beatIndex,
    beat,
    from: fromBeat,
    to: beat,
    fromBeat,
    toBeat: beat,
    fromBeatId: fromBeat?.id || null,
    toBeatId: beat?.id || null,
    transitions: scopedTransitions,
    transition,
    authoredTransition,
    edgeId: authoredTransition?.edgeId || null,
    sceneContext: toSceneContext,
    fromSceneContext,
    toSceneContext,
  };
}

function sourceGraphTransitionContextMatches(left, right) {
  return Boolean(
    left?.beatId
    && right?.beatId
    && left.beatId === right.beatId
    && (left.variantGroupId || null) === (right.variantGroupId || null)
    && (left.variantOptionId || null) === (right.variantOptionId || null),
  );
}

function interBeatMotionTransitionIndex(boundary) {
  const routeKey = boundary?.authoredTransition?.key || boundary?.edgeId || boundary?.transition?.key;
  if (!routeKey) return 0;
  const index = authoredMotionTransitions().findIndex((candidate) => candidate.key === routeKey);
  return Math.max(0, index);
}

function interBeatVariantTransitionAnimationSpec(proposal, boundary, mappedTracks) {
  if (!boundary?.authoredTransition?.manualVariantSwitch || !boundary.toSceneContext) return null;
  for (const assetId of boundary.to?.linkedAssetIds || []) {
    const asset = findAssetById(assetId);
    const spec = dynamicModelThumbnailAnimationSpec(asset, boundary.toSceneContext, proposal, mappedTracks);
    if (spec) return spec;
  }
  return null;
}

function interBeatBoundaryPlaybackSummary(proposal, context) {
  const boundary = interBeatBoundaryForSceneContext(proposal, context);
  const { to: beat } = boundary;
  const manualVariantSwitch = boundary.authoredTransition?.manualVariantSwitch === true;
  const routeScopedProgression = Boolean(
    !manualVariantSwitch
    && boundary.authoredTransition?.fromContext?.variantOptionId
    && boundary.authoredTransition?.from?.id !== boundary.authoredTransition?.to?.id,
  );
  const sourcePartPlaybackMode = beatSourcePartPlaybackMode(beat);
  const forceHold = !boundary.fromBeatId || sourcePartPlaybackMode === "frozen";
  const sourcePlaybackSummary = sourcePlaybackPreviewSummary(
    uniqueStrings([
      ...(boundary.from?.linkedAssetIds || []),
      ...(boundary.to?.linkedAssetIds || []),
    ]),
    boundary.fromBeatId || "",
    boundary.toBeatId || "",
    { beatId: boundary.toBeatId || "", forceHold },
  );
  const mappedTracks = manualVariantSwitch
    ? dynamicMotionTracksForSceneContext(boundary.toSceneContext)
    : interBeatMappedTracksForBoundary(boundary);
  const variantTransitionAnimationSpec = manualVariantSwitch
    ? interBeatVariantTransitionAnimationSpec(proposal, boundary, mappedTracks)
    : null;
  const canScrub = Boolean(boundary.fromBeatId)
    && sourcePartPlaybackMode !== "frozen"
    && (
      manualVariantSwitch
        ? Boolean(variantTransitionAnimationSpec)
        : !routeScopedProgression && sourcePlaybackSummary.contractAvailable
        ? sourcePlaybackSummary.windowState.mode === "scrub"
        : mappedTracks.length > 0
    );
  return {
    boundary,
    manualVariantSwitch,
    routeScopedProgression,
    sourcePartPlaybackMode,
    sourcePlaybackSummary,
    mappedTracks,
    variantTransitionAnimationSpec,
    canScrub,
  };
}

function interBeatMappedTracksForBoundary(boundary) {
  const fromBeatId = boundary?.fromBeatId;
  const toBeatId = boundary?.toBeatId;
  if (!fromBeatId || !toBeatId) return [];
  const authored = boundary?.authoredTransition || null;
  const routeAssetIds = new Set([
    ...(boundary?.from?.linkedAssetIds || []),
    ...(boundary?.to?.linkedAssetIds || []),
  ]);
  return eligibleSourceMotionTracks("inter-beat-dynamics").filter((track) => (
    (!track.assetId || routeAssetIds.has(track.assetId))
    && (authored
      ? Boolean(motionTransitionAssignmentForAuthoredTransition(sourceMotionDraftForTrack(track)?.transitions, authored))
      : normalizeMotionTransitions(sourceMotionDraftForTrack(track)?.transitions).some((transition) => (
          transition.fromBeatId === fromBeatId && transition.toBeatId === toBeatId
        )))
  ));
}

function interBeatBoundaryStatus(proposal, context) {
  const playback = interBeatBoundaryPlaybackSummary(proposal, context);
  const {
    boundary,
    manualVariantSwitch,
    routeScopedProgression,
    sourcePartPlaybackMode,
    sourcePlaybackSummary,
    mappedTracks,
    canScrub,
  } = playback;
  if (manualVariantSwitch) {
    return canScrub
      ? { className: "mapped", label: "Saved scene change" }
      : { className: "no-dynamics", label: "No saved scene change" };
  }
  if (!boundary.fromBeatId) return { className: "static", label: "Story starts here" };
  if (sourcePartPlaybackMode === "frozen") return { className: "static", label: "Previous scene stays visible" };
  if (!routeScopedProgression && sourcePlaybackSummary.contractAvailable) {
    if (sourcePlaybackSummary.windowState.mode === "scrub") return { className: "mapped", label: "Saved scene change" };
    if (sourcePlaybackSummary.windowState.mode === "initialize") return { className: "static", label: "Story starts here" };
    if (sourcePlaybackSummary.windowState.mode === "hold") return { className: "static", label: "Previous scene stays visible" };
    return { className: "no-dynamics", label: "No saved scene change" };
  }
  return mappedTracks.length
    ? { className: "mapped", label: "Saved scene change" }
    : { className: "no-dynamics", label: "No saved scene change" };
}

function interBeatSpatialSceneContextsByAssetId(boundary) {
  const contexts = new Map();
  for (const assetId of boundary?.from?.linkedAssetIds || []) {
    if (boundary.fromSceneContext) contexts.set(assetId, boundary.fromSceneContext);
  }
  for (const assetId of boundary?.to?.linkedAssetIds || []) {
    if (boundary.toSceneContext) contexts.set(assetId, boundary.toSceneContext);
  }
  return contexts;
}

function activeEnvironmentSceneContext() {
  const context = state.environmentEditorScene;
  if (!context?.beatId) return null;
  const normalized = spatialSceneContext(context.beatId, context.variantGroupId, context.variantOptionId);
  return spatialSceneBeat(normalized) ? normalized : null;
}

function activeSpatialSceneContext() {
  const context = state.spatialEditorScene;
  if (!context?.beatId) return null;
  const normalized = spatialSceneContext(context.beatId, context.variantGroupId, context.variantOptionId);
  return spatialSceneBeat(normalized) ? normalized : null;
}

function spatialSceneRequestKey(context) {
  if (!context?.beatId) return "";
  const sceneKey = context.variantOptionId
    ? `${context.beatId}::${context.variantGroupId || "variant"}::${context.variantOptionId}`
    : context.beatId;
  return context.transitionEdgeId ? `${sceneKey}::edge::${context.transitionEdgeId}` : sceneKey;
}

function spatialPreviewBeats() {
  return (state.data?.graph?.beats || []).map((beat, index) => ({
    ...beat,
    id: beat.id || `beat-${index + 1}`,
    title: beat.title || beat.section || `Story part ${index + 1}`,
    text: beat.text || beat.excerpt || beat.summary || beat.title || "",
    linkedAssetIds: beatAssetIds(beat),
  }));
}

function spatialSceneBeat(context) {
  if (!context?.beatId) return null;
  const beat = spatialPreviewBeats().find((candidate) => candidate.id === context.beatId);
  if (!beat) return null;
  if (!context.variantOptionId) return beat;
  const group = variantGroupForBeat(beat);
  const option = (group?.options || []).find((candidate) => candidate.id === context.variantOptionId);
  if (!option) return beat;
  return {
    ...beat,
    title: option.label || beat.title,
    text: option.text || beat.text,
    linkedAssetIds: variantOptionAssetIds(option),
    variantGroupId: group?.id || context.variantGroupId,
    variantOptionId: option.id,
  };
}

function spatialSceneContextLabel(context) {
  if (!context?.variantOptionId) return "Story-part scene";
  const beat = (state.data?.graph?.beats || []).find((candidate) => candidate.id === context.beatId);
  const group = beat ? variantGroupForBeat(beat) : null;
  const option = (group?.options || []).find((candidate) => candidate.id === context.variantOptionId);
  return `Choice scene · ${option?.label || context.variantOptionId}`;
}

function spatialAllSceneRecords(contract) {
  const records = [];
  const seen = new Set();
  for (const collection of [contract?.resolvedByBeat, contract?.resolvedByVariant]) {
    if (!collection || typeof collection !== "object") continue;
    for (const scene of Object.values(collection)) {
      if (!scene || typeof scene !== "object" || seen.has(scene)) continue;
      seen.add(scene);
      records.push(scene);
    }
  }
  return records;
}

function spatialSceneRecordForContext(contract, context) {
  if (!contract || !context?.beatId) return null;
  const matches = (scene) => {
    if (!scene || String(scene.beatId || "") !== context.beatId) return false;
    if (context.variantOptionId) return String(scene.variantOptionId || "") === context.variantOptionId;
    return !scene.variantOptionId;
  };
  if (context.variantOptionId) {
    const variants = contract.resolvedByVariant;
    if (variants && typeof variants === "object") {
      const exact = Object.values(variants).find(matches);
      if (exact) return exact;
    }
  } else {
    const direct = contract.resolvedByBeat?.[context.beatId];
    if (direct && matches(direct)) return direct;
    const beatScene = Object.values(contract.resolvedByBeat || {}).find(matches);
    if (beatScene) return beatScene;
  }
  return spatialAllSceneRecords(contract).find(matches) || null;
}

function spatialSceneEntities(contract, context = activeSpatialSceneContext()) {
  const scene = spatialSceneRecordForContext(contract, context);
  if (scene?.entities) {
    const sceneEntities = spatialRelationEntities(scene);
    if (!context?.variantOptionId || sceneEntities.some((entity) => spatialEntityType(entity) === "reader")) return sceneEntities;
    const baseReader = spatialRelationEntities(contract?.resolvedByBeat?.[context.beatId])
      .find((entity) => spatialEntityType(entity) === "reader");
    return baseReader ? [baseReader, ...sceneEntities] : sceneEntities;
  }
  if (!context?.beatId) return spatialRelationEntities(contract);
  const linkedAssetIds = new Set(scene?.linkedAssetIds || spatialSceneBeat(context)?.linkedAssetIds || []);
  return spatialRelationEntities(contract).filter((entity) => {
    const id = String(entity.id || "");
    const entityBeatId = String(entity.beatId || "");
    const entityVariantOptionId = String(entity.variantOptionId || "");
    if (context.variantOptionId) {
      if (entityVariantOptionId) return entityBeatId === context.beatId && entityVariantOptionId === context.variantOptionId;
      if (id.includes(":variant:")) return id.endsWith(`:variant:${context.variantOptionId}`) && (entityBeatId === context.beatId || id.includes(`:beat:${context.beatId}`) || id.startsWith(`text-panel:${context.beatId}:`));
      return false;
    }
    if (entityVariantOptionId || id.includes(":variant:")) return false;
    if (spatialEntityType(entity) === "text-panel") return entityBeatId === context.beatId || id === `text-panel:${context.beatId}`;
    if (entityBeatId) return entityBeatId === context.beatId;
    return linkedAssetIds.has(entity.assetId);
  });
}

function spatialEditorSceneEntities(contract, context = activeSpatialSceneContext()) {
  return spatialSceneEntities(contract, context)
    .filter((entity) => spatialEntityType(entity) !== "text-panel");
}

function spatialSceneLinkedAssetIds(scene, beat, option = null, contextInput = null) {
  const context = contextInput?.beatId
    ? spatialSceneContext(
      contextInput.beatId,
      contextInput.variantGroupId,
      contextInput.variantOptionId,
    )
    : scene?.beatId
      ? spatialSceneContext(scene.beatId, scene.variantGroupId, scene.variantOptionId)
      : beat?.id
        ? spatialSceneContext(beat.id, beat.variantGroupId, option?.id || beat.variantOptionId)
        : null;
  if (Array.isArray(scene?.linkedAssetIds)) return uniqueStrings(scene.linkedAssetIds);
  return option ? variantOptionAssetIds(option) : beatAssetIds(beat);
}

function spatialSceneCardStatus(scene) {
  if (!scene) return { className: "needs-review", changed: false };
  const entities = spatialRelationEntities(scene).filter((entity) => spatialEntityType(entity) !== "text-panel");
  if (entities.some((entity) => entity.manual)) return { className: "edited", changed: true };
  return { className: "inferred", changed: false };
}

function spatialSceneTopologyLabel(scene) {
  const kind = scene?.topology?.kind || scene?.topologyKind;
  if (!kind) return "Inferred scene layout";
  return scene?.topology?.label || topologyKindLabel(kind);
}

function isSpatialRelationsComponentId(componentId) {
  return componentId === SPATIAL_RELATIONS_COMPONENT_ID || componentId === LEGACY_TEXT_COMFORT_COMPONENT_ID;
}

function spatialRelationsComponentId() {
  return state.data?.components?.some((component) => component.id === SPATIAL_RELATIONS_COMPONENT_ID)
    ? SPATIAL_RELATIONS_COMPONENT_ID
    : LEGACY_TEXT_COMFORT_COMPONENT_ID;
}

function spatialRelationsComponent() {
  return state.data?.components?.find((component) => isSpatialRelationsComponentId(component.id)) || null;
}

function spatialRelationsProposalBundle() {
  return state.data?.proposals?.[SPATIAL_RELATIONS_COMPONENT_ID]
    || state.data?.proposals?.[LEGACY_TEXT_COMFORT_COMPONENT_ID]
    || null;
}

function spatialRelationsDecision() {
  return state.data?.decisions?.[SPATIAL_RELATIONS_COMPONENT_ID]
    || state.data?.decisions?.[LEGACY_TEXT_COMFORT_COMPONENT_ID]
    || null;
}

function lockedSpatialRelationsContract() {
  const componentId = spatialRelationsComponentId();
  if (!checkpointIsCurrent(componentId)) return null;
  const canonical = state.data?.decisions?.[SPATIAL_RELATIONS_COMPONENT_ID]?.spatialRelations;
  if (spatialRelationEntities(canonical).length || canonical?.resolvedByBeat || canonical?.resolvedByVariant) return canonical;
  const legacyDecision = state.data?.decisions?.[LEGACY_TEXT_COMFORT_COMPONENT_ID];
  if (spatialRelationEntities(legacyDecision?.spatialRelations).length || legacyDecision?.spatialRelations?.resolvedByBeat || legacyDecision?.spatialRelations?.resolvedByVariant) return legacyDecision.spatialRelations;
  if (legacyDecision?.textPlacement) {
    const proposal = legacyDecision.option || null;
    return {
      schemaVersion: "storyvr-spatial-relations/v1",
      inputSignature: "legacy-text-comfort",
      entities: fallbackSpatialRelationEntities(proposal, legacyDecision.textPlacement),
    };
  }
  return null;
}

function lockedSpatialTextKind() {
  if (spatialRelationEntities(lockedSpatialRelationsContract()).length) return "spatial-relations";
  const legacyOption = state.data?.decisions?.[LEGACY_TEXT_COMFORT_COMPONENT_ID]?.option;
  return legacyOption ? inferTextComfortKind(legacyOption) : null;
}

function resetSpatialRelationsDraftState() {
  if (state.spatialAutosaveTimer) clearTimeout(state.spatialAutosaveTimer);
  state.spatialRelationsDraft = null;
  state.spatialRelationsDraftKey = "";
  state.selectedSpatialEntityId = null;
  state.selectedSpatialEntityIds = [];
  state.spatialSelectionAnchorEntityId = null;
  state.spatialSelectionClearedSceneKey = "";
  state.spatialPropagationSelectionId = null;
  state.spatialPropagationTargetsOpen = false;
  state.spatialPropagationTargetBeatIds = [];
  state.spatialPropagationStatus = "";
  state.spatialDraftRevision = 0;
  state.spatialAutosaveTimer = null;
  state.spatialAutosaveStatus = "Draft ready";
  state.spatialEditorScene = null;
}

function activeAttentionSceneContext() {
  const context = state.attentionEditorScene;
  if (!context?.beatId) return null;
  const normalized = spatialSceneContext(context.beatId, context.variantGroupId, context.variantOptionId);
  return spatialSceneBeat(normalized) ? normalized : null;
}

function attentionGuidanceDecision() {
  return state.data?.decisions?.[ATTENTION_GUIDANCE_COMPONENT_ID] || null;
}

function attentionGuidanceProposalBundle() {
  return state.data?.proposals?.[ATTENTION_GUIDANCE_COMPONENT_ID] || null;
}

function attentionGuidanceSourceContract() {
  const decisionContract = attentionGuidanceDecision()?.attentionGuidance;
  if (decisionContract && typeof decisionContract === "object") return decisionContract;
  const bundle = attentionGuidanceProposalBundle();
  const proposalContract = bundle?.attentionGuidance
    || bundle?.inference?.attentionGuidance
    || bundle?.proposals?.find((proposal) => proposal?.attentionGuidance)?.attentionGuidance
    || null;
  return proposalContract && typeof proposalContract === "object" ? proposalContract : null;
}

function attentionAllSceneRecords(contract) {
  return spatialAllSceneRecords(contract);
}

function attentionSceneRecordForContext(contract, context) {
  return spatialSceneRecordForContext(contract, context);
}

function attentionPosition(value) {
  const source = Array.isArray(value)
    ? { x: value[0], y: value[1], z: value[2] }
    : value && typeof value === "object" ? value : null;
  if (!source) return null;
  const coordinates = [source.x, source.y, source.z];
  if (!coordinates.every((coordinate) => typeof coordinate === "number" && Number.isFinite(coordinate))) return null;
  return { x: coordinates[0], y: coordinates[1], z: coordinates[2] };
}

function attentionPositionsEqual(left, right) {
  const a = attentionPosition(left);
  const b = attentionPosition(right);
  return Boolean(a && b && ["x", "y", "z"].every((axis) => Math.abs(a[axis] - b[axis]) < 0.0001));
}

const ATTENTION_RECONCILIATION_STATUSES = new Set([
  "confirmed",
  "compatible",
  "runtime-only",
  "semantic-only",
  "conflict",
  "unresolved",
]);

function attentionReconciliationStatus(value) {
  const status = String(value || "").trim().toLowerCase();
  return ATTENTION_RECONCILIATION_STATUSES.has(status) ? status : "unresolved";
}

function attentionReconciliationPresentation(value) {
  const status = attentionReconciliationStatus(value);
  return {
    status,
    className: `is-${status}`,
    label: {
      confirmed: "Confirmed",
      compatible: "Compatible",
      "runtime-only": "Visible model only",
      "semantic-only": "Semantic only",
      conflict: "Conflict",
      unresolved: "Unresolved",
    }[status],
    provisional: status === "runtime-only" || status === "semantic-only",
  };
}

function normalizeAttentionCandidate(value) {
  if (!value || typeof value !== "object") return null;
  const id = String(value.id || "").trim();
  const assetId = String(value.assetId || "").trim();
  const entityId = String(value.entityId || "").trim();
  const targetKind = String(value.targetKind || "").trim();
  if (!id || !["standalone-glb", "standalone-image", "named-renderable-part", "spatial-point"].includes(targetKind)) return null;
  if (targetKind !== "spatial-point" && !assetId) return null;
  const partSelector = String(value.partSelector || "").trim();
  if (targetKind === "named-renderable-part" && !partSelector) return null;
  const channels = [...new Set((Array.isArray(value.channels) ? value.channels : [])
    .map((channel) => String(channel || "").trim().toLowerCase())
    .filter((channel) => channel === "runtime" || channel === "semantic"))];
  const reconciliationStatus = attentionReconciliationStatus(value.reconciliationStatus);
  const reviewRequired = value.reviewRequired === true
    || reconciliationStatus === "runtime-only"
    || reconciliationStatus === "semantic-only"
    || reconciliationStatus === "conflict";
  const normalized = {
    ...value,
    id,
    targetKind,
    ...(partSelector ? { partSelector } : {}),
    channels,
    reconciliationStatus,
    reviewRequired,
  };
  if (assetId) normalized.assetId = assetId;
  else delete normalized.assetId;
  if (entityId) normalized.entityId = entityId;
  else delete normalized.entityId;
  return normalized;
}

function normalizeAttentionMarker(value) {
  if (!value || typeof value !== "object") return null;
  const id = String(value.id || "").trim();
  const assetId = String(value.assetId || "").trim();
  const entityId = String(value.entityId || "").trim();
  const targetKind = String(value.targetKind || "").trim();
  const inferredPosition = attentionPosition(value.inferredPosition);
  const position = attentionPosition(value.position);
  if (!id || !inferredPosition || !position) return null;
  if (targetKind === "spatial-point") {
    delete value.assetId;
    delete value.entityId;
  } else if (!assetId) return null;
  value.id = id;
  if (assetId) value.assetId = assetId;
  if (entityId) value.entityId = entityId;
  value.coordinateSpace = "spatial-scene";
  value.inferredPosition = inferredPosition;
  value.position = position;
  value.manual = Boolean(value.manual || !attentionPositionsEqual(position, inferredPosition));
  return value;
}

function attentionSceneMarkers(scene) {
  return (Array.isArray(scene?.markers) ? scene.markers : []).map(normalizeAttentionMarker).filter(Boolean);
}

function attentionSceneCandidates(scene) {
  return (Array.isArray(scene?.candidates) ? scene.candidates : []).map(normalizeAttentionCandidate).filter(Boolean);
}

function attentionDismissedCandidateIds(scene) {
  const candidateIds = new Set(attentionSceneCandidates(scene).map((candidate) => candidate.id));
  return uniqueStrings(scene?.dismissedCandidateIds || []).filter((candidateId) => candidateIds.has(candidateId));
}

function dedupeAttentionCandidates(candidates) {
  return [...new Map((candidates || []).filter(Boolean).map((candidate) => [candidate.id, candidate])).values()];
}

function attentionManualTargetOptions(scene) {
  return (Array.isArray(scene?.manualTargetOptions) ? scene.manualTargetOptions : [])
    .map(normalizeAttentionCandidate)
    .filter((candidate) => ["standalone-glb", "standalone-image"].includes(candidate?.targetKind) && candidate?.entityId);
}

function attentionAvailableManualTargetOptions(scene) {
  const markerIds = new Set(attentionSceneMarkers(scene).map((marker) => marker.id));
  return attentionManualTargetOptions(scene).filter((candidate) => !markerIds.has(candidate.id));
}

function ensureAttentionTargetObjectSelection(scene) {
  const orderedIds = attentionManualTargetOptions(scene).map((candidate) => candidate.id);
  const selected = new Set([
    ...(Array.isArray(state.selectedAttentionTargetCandidateIds) ? state.selectedAttentionTargetCandidateIds : []),
    state.selectedAttentionTargetCandidateId,
  ].filter(Boolean));
  state.selectedAttentionTargetCandidateIds = orderedIds.filter((candidateId) => selected.has(candidateId));
  state.selectedAttentionTargetCandidateId = state.selectedAttentionTargetCandidateIds.includes(state.selectedAttentionTargetCandidateId)
    ? state.selectedAttentionTargetCandidateId
    : state.selectedAttentionTargetCandidateIds.at(-1) || null;
}

function selectedAttentionTargetObjectCandidateIds(scene) {
  ensureAttentionTargetObjectSelection(scene);
  return [...state.selectedAttentionTargetCandidateIds];
}

function selectedAttentionTargetObjectCandidates(scene) {
  const selectedIds = new Set(selectedAttentionTargetObjectCandidateIds(scene));
  return attentionManualTargetOptions(scene).filter((candidate) => selectedIds.has(candidate.id));
}

function attentionManualPositionTargetOption(scene) {
  return (Array.isArray(scene?.manualTargetOptions) ? scene.manualTargetOptions : [])
    .map(normalizeAttentionCandidate)
    .find((candidate) => candidate?.targetKind === "spatial-point") || null;
}

function attentionAvailableManualPositionTarget(scene) {
  const candidate = attentionManualPositionTargetOption(scene);
  if (!candidate) return null;
  return attentionSceneMarkers(scene).some((marker) => marker.id === candidate.id) ? null : candidate;
}

function attentionManualTargetLabel(candidate) {
  const asset = findAssetById(candidate?.assetId);
  return asset?.filename || asset?.label || candidate?.assetId || candidate?.entityId || "Visible object";
}

function attentionSceneChannelCandidates(scene, channel) {
  const key = channel === "runtime" ? "runtimeCandidates" : "semanticCandidates";
  const direct = (Array.isArray(scene?.[key]) ? scene[key] : []).map(normalizeAttentionCandidate).filter(Boolean);
  if (direct.length) return direct;
  return attentionSceneCandidates(scene).filter((candidate) => candidate.channels.includes(channel));
}

function attentionSceneReconciliation(scene) {
  const source = scene?.reconciliation && typeof scene.reconciliation === "object" ? scene.reconciliation : {};
  const status = attentionReconciliationStatus(source.status);
  return {
    ...source,
    status,
    reviewRequired: source.reviewRequired === true
      || status === "runtime-only"
      || status === "semantic-only"
      || status === "conflict",
    reviewed: true,
    reviewedAt: typeof source.reviewedAt === "string" ? source.reviewedAt : null,
    runtimeCandidateIds: Array.isArray(source.runtimeCandidateIds) ? source.runtimeCandidateIds.map(String) : [],
    semanticCandidateIds: Array.isArray(source.semanticCandidateIds) ? source.semanticCandidateIds.map(String) : [],
    conflicts: Array.isArray(source.conflicts) ? source.conflicts.filter((conflict) => conflict && typeof conflict === "object") : [],
  };
}

function attentionSceneDiagnostics(scene) {
  const diagnostics = (Array.isArray(scene?.diagnostics) ? scene.diagnostics : [])
    .filter((diagnostic) => diagnostic && typeof diagnostic === "object")
    .map((diagnostic) => ({
      ...diagnostic,
      code: String(diagnostic.code || "").trim(),
      channel: String(diagnostic.channel || "").trim(),
      message: String(diagnostic.message || "").trim(),
      candidateIds: Array.isArray(diagnostic.candidateIds) ? diagnostic.candidateIds.map(String) : [],
      evidenceRefs: Array.isArray(diagnostic.evidenceRefs) ? diagnostic.evidenceRefs.map(String) : [],
    }));
  const rejectedCount = Number(scene?.evaluation?.rejectedCandidateCount) || 0;
  const dismissedCandidateIds = new Set(attentionDismissedCandidateIds(scene));
  if (scene?.evaluated === true && rejectedCount > 0 && !diagnostics.some((diagnostic) => diagnostic.code === "live-geometry-rejected")) {
    diagnostics.push({
      code: "live-geometry-rejected",
      channel: "validation",
      message: `${rejectedCount} inferred target${rejectedCount === 1 ? "" : "s"} failed live visible-geometry validation.`,
      candidateIds: attentionSceneCandidates(scene)
        .filter((candidate) => !dismissedCandidateIds.has(candidate.id))
        .filter((candidate) => !attentionSceneMarkers(scene).some((marker) => marker.id === candidate.id))
        .map((candidate) => candidate.id),
      evidenceRefs: [],
    });
  }
  return diagnostics;
}

function ensureAttentionGuidanceDraft() {
  const source = attentionGuidanceSourceContract();
  const contexts = spatialSceneContextsFromGraph();
  const signature = source?.inputSignature
    || attentionGuidanceProposalBundle()?.inputSignature
    || "frontend-fallback";
  const draftKey = `${signature}:${source?.schemaVersion || "storyvr-attention-guidance/v1"}:${contexts.length}`;
  if (!state.attentionGuidanceDraft || state.attentionGuidanceDraftKey !== draftKey) {
    const resolvedByBeat = {};
    const resolvedByVariant = {};
    for (const context of contexts) {
      const sourceScene = attentionSceneRecordForContext(source, context);
      const sceneKey = sourceScene?.sceneKey || spatialSceneRequestKey(context);
      const scene = {
        ...(sourceScene ? cloneJson(sourceScene) : {}),
        sceneKey,
        sceneId: sourceScene?.sceneId || sceneKey,
        beatId: context.beatId,
        ...(context.variantGroupId ? { variantGroupId: context.variantGroupId } : {}),
        ...(context.variantOptionId ? { variantOptionId: context.variantOptionId } : {}),
        candidates: attentionSceneCandidates(sourceScene),
        reconciliation: attentionSceneReconciliation(sourceScene),
        markers: attentionSceneMarkers(sourceScene),
        evaluated: sourceScene?.evaluated === true,
      };
      if (context.variantOptionId) resolvedByVariant[sceneKey] = scene;
      else resolvedByBeat[context.beatId] = scene;
    }
    state.attentionGuidanceDraft = {
      ...(source ? cloneJson(source) : {}),
      schemaVersion: "storyvr-attention-guidance/v1",
      inferenceVersion: source?.inferenceVersion || "dual-runtime-semantic-v3",
      inputSignature: signature,
      coordinateSpace: "spatial-scene",
      resolvedByBeat,
      resolvedByVariant,
    };
    state.attentionGuidanceDraftKey = draftKey;
    state.attentionDraftRevision = 0;
    state.attentionDraftDirty = false;
  }
  return state.attentionGuidanceDraft;
}

function attentionGuidanceForSave() {
  const draft = ensureAttentionGuidanceDraft();
  const clean = cleanSpatialRelationsValue(draft);
  clean.schemaVersion = "storyvr-attention-guidance/v1";
  clean.inferenceVersion = clean.inferenceVersion || "dual-runtime-semantic-v3";
  clean.coordinateSpace = "spatial-scene";
  for (const scene of attentionAllSceneRecords(clean)) {
    scene.candidates = attentionSceneCandidates(scene);
    scene.dismissedCandidateIds = attentionDismissedCandidateIds(scene);
    scene.reconciliation = attentionSceneReconciliation(scene);
    scene.markers = attentionSceneMarkers(scene);
    scene.evaluated = scene.evaluated === true;
  }
  return clean;
}

function attentionMarkerLabel(marker) {
  if (!marker) return "No focus marker";
  if (marker.targetKind === "spatial-point") return "Placed focus marker";
  const asset = findAssetById(marker.assetId);
  const assetLabel = asset?.filename || asset?.label || marker.assetId;
  return marker.partSelector ? `${marker.partSelector} · ${assetLabel}` : assetLabel;
}

function attentionMarkerEditLabel(marker) {
  return String(marker?.provenance?.source || "").startsWith("author-manual-attention-") ? "placed" : "moved";
}

function attentionTargetKindLabel(marker) {
  if (marker?.targetKind === "spatial-point") return "Manual scene position";
  if (marker?.targetKind === "standalone-image") return "Visible image";
  return marker?.partSelector ? "Visible model part" : "Visible 3D model";
}

function ensureAttentionMarkerSelection(scene) {
  const markers = attentionSceneMarkers(scene);
  if (markers.some((marker) => marker.id === state.selectedAttentionMarkerId)) return;
  state.selectedAttentionMarkerId = markers[0]?.id || null;
}

function selectedAttentionMarker(scene = attentionSceneRecordForContext(state.attentionGuidanceDraft, activeAttentionSceneContext())) {
  return attentionSceneMarkers(scene).find((marker) => marker.id === state.selectedAttentionMarkerId) || null;
}

function setAttentionAutosaveStatus(value) {
  state.attentionAutosaveStatus = value;
  const status = document.querySelector("[data-attention-autosave-status]");
  if (status) status.textContent = `${value} · revision ${state.attentionDraftRevision}`;
}

function commitAttentionDraftMutation(options = {}) {
  state.attentionDraftRevision += 1;
  state.attentionDraftDirty = true;
  markStoryvrCheckpointCompletionPending(ATTENTION_GUIDANCE_COMPONENT_ID);
  if (options.immediate) {
    const requestId = state.attentionAutosaveRequestId + 1;
    state.attentionAutosaveRequestId = requestId;
    setAttentionAutosaveStatus("Saving draft...");
    startAttentionGuidanceAutosave(requestId).catch(() => {});
  } else scheduleAttentionGuidanceAutosave();
  updateCheckpointStatusDom(ATTENTION_GUIDANCE_COMPONENT_ID);
  updateHistoryControlsDom();
}

function scheduleAttentionGuidanceAutosave() {
  if (!state.attentionGuidanceDraft) return;
  if (state.attentionAutosaveTimer) clearTimeout(state.attentionAutosaveTimer);
  setAttentionAutosaveStatus("Saving draft...");
  const requestId = state.attentionAutosaveRequestId + 1;
  state.attentionAutosaveRequestId = requestId;
  state.attentionAutosaveTimer = setTimeout(() => {
    state.attentionAutosaveTimer = null;
    startAttentionGuidanceAutosave(requestId).catch(() => {});
  }, 500);
}

function startAttentionGuidanceAutosave(requestId) {
  const promise = persistAttentionGuidanceDraft(requestId);
  state.attentionAutosavePromise = promise;
  promise.catch((error) => {
    if (requestId === state.attentionAutosaveRequestId) setAttentionAutosaveStatus(`Save failed: ${shortText(error.message, 58)}`);
  }).finally(() => {
    if (state.attentionAutosavePromise === promise) state.attentionAutosavePromise = null;
  });
  return promise;
}

async function persistAttentionGuidanceDraft(requestId) {
  if (!state.attentionGuidanceDraft) return null;
  const decision = await api.post(`/api/decisions/${ATTENTION_GUIDANCE_COMPONENT_ID}/draft`, {
    attentionGuidance: attentionGuidanceForSave(),
    authorEdits: currentEditNotesValue(),
  });
  if (requestId !== state.attentionAutosaveRequestId) return decision;
  if (!state.data.decisions) state.data.decisions = {};
  state.data.decisions[ATTENTION_GUIDANCE_COMPONENT_ID] = decision;
  state.attentionDraftDirty = false;
  if (decision?.current === true && decision?.stale !== true) {
    clearStoryvrCheckpointCompletionPending(ATTENTION_GUIDANCE_COMPONENT_ID);
  } else {
    markStoryvrCheckpointCompletionPending(ATTENTION_GUIDANCE_COMPONENT_ID);
  }
  setAttentionAutosaveStatus("Changes saved");
  updateCheckpointStatusDom(ATTENTION_GUIDANCE_COMPONENT_ID);
  return decision;
}

async function flushAttentionGuidanceAutosave() {
  const hadPendingTimer = Boolean(state.attentionAutosaveTimer);
  const hadPendingPromise = Boolean(state.attentionAutosavePromise);
  if (state.attentionAutosaveTimer) {
    clearTimeout(state.attentionAutosaveTimer);
    state.attentionAutosaveTimer = null;
  }
  if (state.attentionAutosavePromise) await state.attentionAutosavePromise;
  if (hadPendingTimer || state.attentionDraftDirty) {
    const requestId = state.attentionAutosaveRequestId + 1;
    state.attentionAutosaveRequestId = requestId;
    await startAttentionGuidanceAutosave(requestId);
    return true;
  }
  return hadPendingPromise;
}

function syncAttentionManualTargetControls(viewer = textViewer) {
  const scene = attentionSceneRecordForContext(state.attentionGuidanceDraft, activeAttentionSceneContext());
  const button = document.querySelector("[data-attention-add-manual]");
  const placeButton = document.querySelector("[data-attention-place-manual]");
  if (!button) return;
  ensureAttentionTargetObjectSelection(scene);
  const options = attentionManualTargetOptions(scene);
  const optionById = new Map(options.map((candidate) => [candidate.id, candidate]));
  const availableIds = new Set(attentionAvailableManualTargetOptions(scene).map((candidate) => candidate.id));
  const positionById = new Map(options.map((candidate) => [candidate.id, attentionCandidatePosition(viewer, candidate)]));
  for (const item of document.querySelectorAll("[data-attention-select-object]")) {
    const candidate = optionById.get(item.dataset.attentionSelectObject);
    item.disabled = Boolean(viewer?.spatialPlaybackReady && candidate && !positionById.get(candidate.id));
  }
  let selected = selectedAttentionTargetObjectCandidates(scene);
  if (viewer?.spatialPlaybackReady) {
    selected = selected.filter((candidate) => positionById.get(candidate.id));
    state.selectedAttentionTargetCandidateIds = selected.map((candidate) => candidate.id);
    if (!state.selectedAttentionTargetCandidateIds.includes(state.selectedAttentionTargetCandidateId)) {
      state.selectedAttentionTargetCandidateId = state.selectedAttentionTargetCandidateIds.at(-1) || null;
    }
  }
  const selectedIds = new Set(selected.map((candidate) => candidate.id));
  for (const item of document.querySelectorAll("[data-attention-select-object]")) {
    const itemSelected = selectedIds.has(item.dataset.attentionSelectObject);
    item.classList.toggle("selected", itemSelected);
    item.classList.toggle("selection-primary", item.dataset.attentionSelectObject === state.selectedAttentionTargetCandidateId);
    item.setAttribute("aria-pressed", String(itemSelected));
  }
  const addable = selected.filter((candidate) => availableIds.has(candidate.id) && positionById.get(candidate.id));
  button.disabled = !addable.length;
  button.textContent = addable.length > 1
    ? `Add focus markers to ${addable.length} objects`
    : "Add focus marker to object";
  syncAttentionTargetObjectSelectionHelpers(viewer, selected);
  if (placeButton) {
    const manualPosition = attentionAvailableManualPositionTarget(scene);
    placeButton.disabled = !manualPosition || viewer?.locked === true;
    if (!manualPosition && viewer?.manualAttentionPlacementActive) cancelManualAttentionTargetPlacement(viewer);
  }
}

function syncAttentionTargetObjectSelectionHelpers(viewer, candidates) {
  if (!viewer?.scene) return;
  for (const helper of viewer.attentionObjectSelectionHelpers || []) {
    helper.removeFromParent();
    helper.geometry?.dispose?.();
    helper.material?.dispose?.();
  }
  viewer.attentionObjectSelectionHelpers = [];
  for (const candidate of candidates || []) {
    const bounds = attentionCandidateWorldBounds(viewer, candidate);
    if (!bounds) continue;
    const helper = new THREE.Box3Helper(bounds.clone(), 0x007f73);
    helper.name = "StoryVR selected attention target object";
    helper.userData.attentionTargetCandidateId = candidate.id;
    helper.material.transparent = true;
    helper.material.opacity = 0.9;
    helper.material.depthTest = false;
    helper.material.depthWrite = false;
    helper.renderOrder = 1000;
    viewer.scene.add(helper);
    viewer.attentionObjectSelectionHelpers.push(helper);
  }
}

function updateAttentionTargetObjectSelectionHelpers(viewer) {
  const candidateById = new Map(attentionManualTargetOptions(viewer?.attentionScene)
    .map((candidate) => [candidate.id, candidate]));
  for (const helper of viewer?.attentionObjectSelectionHelpers || []) {
    const candidate = candidateById.get(helper.userData.attentionTargetCandidateId);
    const bounds = candidate ? attentionCandidateWorldBounds(viewer, candidate) : null;
    helper.visible = Boolean(bounds);
    if (bounds) helper.box.copy(bounds);
  }
}

function setAttentionTargetObjectSelection(candidateIds, viewer = textViewer, options = {}) {
  const scene = attentionSceneRecordForContext(state.attentionGuidanceDraft, activeAttentionSceneContext());
  const orderedIds = attentionManualTargetOptions(scene).map((candidate) => candidate.id);
  const selected = new Set((candidateIds || []).filter((candidateId) => orderedIds.includes(candidateId)));
  state.selectedAttentionTargetCandidateIds = orderedIds.filter((candidateId) => selected.has(candidateId));
  state.selectedAttentionTargetCandidateId = state.selectedAttentionTargetCandidateIds.includes(options.primaryCandidateId)
    ? options.primaryCandidateId
    : state.selectedAttentionTargetCandidateIds.at(-1) || null;
  cancelManualAttentionTargetPlacement(viewer);
  syncAttentionManualTargetControls(viewer);
  if (options.focusViewer) viewer?.renderer?.domElement?.focus?.();
  return state.selectedAttentionTargetCandidateIds.length > 0;
}

function selectAttentionTargetObjectInViewer(candidateId, viewer = textViewer, options = {}) {
  const scene = attentionSceneRecordForContext(state.attentionGuidanceDraft, activeAttentionSceneContext());
  const orderedIds = attentionManualTargetOptions(scene).map((candidate) => candidate.id);
  if (!orderedIds.includes(candidateId)) return false;
  const candidateIds = spatialSelectionForRectangle(
    orderedIds,
    selectedAttentionTargetObjectCandidateIds(scene),
    [candidateId],
    options,
  );
  const primaryCandidateId = candidateIds.includes(candidateId)
    ? candidateId
    : candidateIds.at(-1) || null;
  return setAttentionTargetObjectSelection(candidateIds, viewer, { ...options, primaryCandidateId });
}

function clearAttentionTargetObjectSelection(viewer = textViewer) {
  const hadSelection = Boolean(state.selectedAttentionTargetCandidateIds.length || state.selectedAttentionTargetCandidateId);
  state.selectedAttentionTargetCandidateIds = [];
  state.selectedAttentionTargetCandidateId = null;
  syncAttentionManualTargetControls(viewer);
  return hadSelection;
}

function setManualAttentionTargetPlacement(viewer, active) {
  if (!viewer || viewer.locked) return false;
  viewer.manualAttentionPlacementActive = active === true;
  const button = document.querySelector("[data-attention-place-manual]");
  if (button) {
    button.classList.toggle("selected", viewer.manualAttentionPlacementActive);
    button.setAttribute("aria-pressed", String(viewer.manualAttentionPlacementActive));
    button.textContent = viewer.manualAttentionPlacementActive ? "Click scene to place focus marker" : "Place focus marker manually";
  }
  viewer.renderer?.domElement?.classList?.toggle("attention-placement-active", viewer.manualAttentionPlacementActive);
  return true;
}

function toggleManualAttentionTargetPlacement(viewer = textViewer) {
  const scene = attentionSceneRecordForContext(state.attentionGuidanceDraft, activeAttentionSceneContext());
  if (!viewer || viewer.locked || (!viewer.manualAttentionPlacementActive && !attentionAvailableManualPositionTarget(scene))) return false;
  return setManualAttentionTargetPlacement(viewer, !viewer.manualAttentionPlacementActive);
}

function cancelManualAttentionTargetPlacement(viewer = textViewer) {
  if (!viewer?.manualAttentionPlacementActive) return false;
  return setManualAttentionTargetPlacement(viewer, false);
}

function addAttentionTargetMarkers({ viewer, scene, entries, historyLabel }) {
  const validEntries = (entries || []).filter((entry) => (
    entry?.candidate && attentionPosition(entry.position)
  ));
  if (!scene || !validEntries.length || viewer?.locked) return false;
  const historyStarted = beginAuthorHistory(historyLabel || "Add focus marker", ATTENTION_GUIDANCE_COMPONENT_ID);
  const addedCandidateIds = new Set(validEntries.map(({ candidate }) => candidate.id));
  scene.dismissedCandidateIds = attentionDismissedCandidateIds(scene)
    .filter((candidateId) => !addedCandidateIds.has(candidateId));
  scene.candidates = dedupeAttentionCandidates([
    ...attentionSceneCandidates(scene),
    ...validEntries.map(({ candidate }) => cloneJson(candidate)),
  ]);
  scene.markers = [
    ...attentionSceneMarkers(scene),
    ...validEntries.map(({ candidate, position, source, evidenceType }) => normalizeAttentionMarker({
        ...candidate,
        inferredPosition: position,
        position,
        manual: true,
        provenance: {
          ...(candidate.provenance || {}),
          source,
          evidenceType,
        },
      })),
  ].filter(Boolean);
  scene.evaluated = true;
  scene.evaluation = {
    status: "evaluated",
    resolvedCandidateCount: scene.markers.length,
    rejectedCandidateCount: Math.max(0, scene.candidates.length - scene.markers.length),
    intentionallyEmpty: false,
  };
  state.selectedAttentionMarkerId = validEntries.at(-1).candidate.id;
  commitAttentionDraftMutation({ immediate: true });
  if (historyStarted) finalizePersistentAuthorHistory(flushAttentionGuidanceAutosave);
  renderPreservingScroll();
  return true;
}

function removeSelectedAttentionMarker(viewer = textViewer) {
  const scene = attentionSceneRecordForContext(state.attentionGuidanceDraft, activeAttentionSceneContext());
  const markers = attentionSceneMarkers(scene);
  const selectedIndex = markers.findIndex((marker) => marker.id === state.selectedAttentionMarkerId);
  if (!scene || selectedIndex < 0 || viewer?.locked === true) return false;
  const historyStarted = beginAuthorHistory("Remove focus marker", ATTENTION_GUIDANCE_COMPONENT_ID);
  const removedMarker = markers[selectedIndex];
  const nextMarkers = markers.filter((marker) => marker.id !== removedMarker.id);
  scene.dismissedCandidateIds = uniqueStrings([
    ...attentionDismissedCandidateIds(scene),
    removedMarker.id,
  ]);
  scene.markers = nextMarkers;
  scene.evaluated = true;
  const activeCandidateCount = attentionSceneCandidates(scene)
    .filter((candidate) => !scene.dismissedCandidateIds.includes(candidate.id)).length;
  scene.evaluation = {
    status: "evaluated",
    resolvedCandidateCount: nextMarkers.length,
    rejectedCandidateCount: Math.max(0, activeCandidateCount - nextMarkers.length),
    intentionallyEmpty: activeCandidateCount === 0,
    reason: activeCandidateCount === 0 ? "author-removed-focus-markers" : null,
  };
  state.selectedAttentionMarkerId = nextMarkers[Math.min(selectedIndex, nextMarkers.length - 1)]?.id || null;
  commitAttentionDraftMutation({ immediate: true });
  if (historyStarted) finalizePersistentAuthorHistory(flushAttentionGuidanceAutosave);
  renderPreservingScroll();
  return true;
}

function addAttentionTargetMarker({ viewer, scene, candidate, position, source, evidenceType, historyLabel }) {
  return addAttentionTargetMarkers({
    viewer,
    scene,
    historyLabel,
    entries: [{ candidate, position, source, evidenceType }],
  });
}

function addManualAttentionTarget() {
  const viewer = textViewer;
  const scene = attentionSceneRecordForContext(state.attentionGuidanceDraft, activeAttentionSceneContext());
  const availableIds = new Set(attentionAvailableManualTargetOptions(scene).map((candidate) => candidate.id));
  const entries = selectedAttentionTargetObjectCandidates(scene)
    .filter((candidate) => availableIds.has(candidate.id))
    .map((candidate) => ({
      candidate,
      position: attentionCandidatePosition(viewer, candidate),
      source: "author-manual-attention-target",
      evidenceType: candidate.targetKind === "standalone-image"
        ? "author-selected-visible-image"
        : "author-selected-visible-glb",
    }))
    .filter((entry) => entry.position);
  if (!entries.length) return false;
  state.selectedAttentionTargetCandidateIds = [];
  state.selectedAttentionTargetCandidateId = null;
  return addAttentionTargetMarkers({
    viewer,
    scene,
    entries,
    historyLabel: entries.length > 1 ? "Add focus markers to objects" : "Add focus marker to object",
  });
}

function addManualAttentionTargetAtPosition(position, viewer = textViewer) {
  const scene = attentionSceneRecordForContext(state.attentionGuidanceDraft, activeAttentionSceneContext());
  const candidate = attentionAvailableManualPositionTarget(scene);
  if (!candidate) return false;
  cancelManualAttentionTargetPlacement(viewer);
  return addAttentionTargetMarker({
    viewer,
    scene,
    candidate,
    position,
    source: "author-manual-attention-position",
    evidenceType: "author-placed-spatial-point",
    historyLabel: "Place focus marker manually",
  });
}

function spatialRelationEntities(contract) {
  const entities = contract?.entities;
  if (Array.isArray(entities)) return entities.filter((entity) => entity && typeof entity === "object" && entity.id);
  if (entities && typeof entities === "object") {
    return Object.entries(entities).map(([id, entity]) => ({ id, ...(entity || {}) }));
  }
  return [];
}

function spatialEntityType(entity) {
  if (entity?.type === "reader" || entity?.kind === "reader" || String(entity?.id || "").startsWith("reader:")) return "reader";
  if (entity?.type === "glb" || entity?.kind === "glb" || String(entity?.id || "").startsWith("glb:")) return "glb";
  if (entity?.type === "image-plane" || entity?.kind === "image-plane" || String(entity?.id || "").startsWith("image:")) return "image-plane";
  return "text-panel";
}

function spatialModelAssets() {
  const seen = new Set();
  return (state.data?.graph?.assetInventory || []).filter((asset) => {
    if (!asset?.id || seen.has(asset.id) || !isModelAsset(asset)) return false;
    seen.add(asset.id);
    return true;
  });
}

function spatialRelationEntityLabel(entity) {
  if (!entity) return "";
  if (spatialEntityType(entity) === "reader") return "Reader";
  if (spatialEntityType(entity) !== "text-panel") {
    const assetId = entity.assetId || String(entity.id).split(":beat:")[0].replace(/^(glb|image):/, "");
    const asset = findAssetById(assetId);
    const label = asset?.filename || asset?.label || assetId || asset?.role;
    return entity.authoredInstance === true
      ? `${label} · Instance ${Math.max(2, Number(entity.instanceIndex) || 2)}`
      : label;
  }
  const beatId = entity.beatId || entity.id.slice("text-panel:".length);
  const beat = textComfortPreviewBeats().find((item) => item.id === beatId);
  return beat?.title || beatId;
}

function spatialEntityScopeLabel(entity) {
  if (spatialEntityType(entity) === "reader") return `Story-part reader pose · ${entity?.beatId || activeSpatialSceneContext()?.beatId || "scene"}`;
  if (spatialEntityType(entity) === "glb") {
    const scope = `Story-part 3D model · ${entity?.beatId || activeSpatialSceneContext()?.beatId || "scene"}`;
    return entity?.authoredInstance === true ? `${scope} · authored instance` : scope;
  }
  if (spatialEntityType(entity) === "image-plane") return `Story-part image · ${entity?.beatId || activeSpatialSceneContext()?.beatId || "scene"}`;
  const beatId = entity?.beatId || String(entity?.id || "").slice("text-panel:".length);
  return `Story-part panel · ${beatId}`;
}

function normalizeSpatialTransform(value, fallback = null) {
  const source = value && typeof value === "object" ? value : {};
  const base = fallback && typeof fallback === "object" ? fallback : {};
  const vector = (candidate, defaults, min, max) => [0, 1, 2].map((index) => {
    const number = Number(Array.isArray(candidate) ? candidate[index] : candidate?.[["x", "y", "z"][index]]);
    const defaultNumber = Number(Array.isArray(defaults) ? defaults[index] : defaults?.[["x", "y", "z"][index]]);
    return Math.max(min, Math.min(max, Number.isFinite(number) ? number : (Number.isFinite(defaultNumber) ? defaultNumber : (min > 0 ? 1 : 0))));
  });
  const position = vector(
    source.position,
    base.position,
    -SPATIAL_TRANSFORM_POSITION_LIMIT,
    SPATIAL_TRANSFORM_POSITION_LIMIT,
  );
  const scale = vector(
    source.scale,
    base.scale || [1, 1, 1],
    0.001,
    SPATIAL_TRANSFORM_SCALE_LIMIT,
  );
  let quaternion = Array.isArray(source.quaternion) ? source.quaternion.map(Number) : null;
  if (!quaternion?.every(Number.isFinite) || quaternion.length !== 4) {
    quaternion = Array.isArray(base.quaternion) ? base.quaternion.map(Number) : null;
  }
  if (!quaternion?.every(Number.isFinite) || quaternion.length !== 4) {
    const rotation = source.rotation || base.rotation;
    if (rotation) {
      const values = vector(rotation, [0, 0, 0], -Math.PI * 4, Math.PI * 4);
      quaternion = new THREE.Quaternion().setFromEuler(new THREE.Euler(...values, "XYZ")).toArray();
    } else quaternion = [0, 0, 0, 1];
  }
  const normalizedQuaternion = new THREE.Quaternion(...quaternion).normalize().toArray();
  return { position, quaternion: normalizedQuaternion, scale };
}

function spatialEntityTransformEditable(entity) {
  return Boolean(entity);
}

function spatialLockedScaleForAxis(startScale, axisIndex, nextAxisValue) {
  const start = [0, 1, 2].map((index) => {
    const value = Number(startScale?.[index]);
    return Math.max(
      0.001,
      Math.min(SPATIAL_TRANSFORM_SCALE_LIMIT, Number.isFinite(value) ? value : 1),
    );
  });
  const index = Number.isInteger(axisIndex) && axisIndex >= 0 && axisIndex <= 2 ? axisIndex : 0;
  const requested = Number(nextAxisValue);
  const desiredRatio = Number.isFinite(requested) ? requested / start[index] : 1;
  const minimumRatio = Math.max(...start.map((value) => 0.001 / value));
  const maximumRatio = Math.min(...start.map((value) => SPATIAL_TRANSFORM_SCALE_LIMIT / value));
  const ratio = Math.max(minimumRatio, Math.min(maximumRatio, desiredRatio));
  return start.map((value) => (
    Math.max(0.001, Math.min(SPATIAL_TRANSFORM_SCALE_LIMIT, value * ratio))
  ));
}

function spatialLockedScaleDriverIndex(startScale, currentScale, axis, previousIndex = null) {
  const axisText = String(axis || "").toUpperCase();
  const axisIndexes = ["X", "Y", "Z"]
    .map((label, index) => axisText.includes(label) ? index : null)
    .filter((index) => index !== null);
  const allowed = axisIndexes.length ? axisIndexes : [0, 1, 2];
  if (allowed.length === 1) return allowed[0];
  if (allowed.includes(previousIndex)) return previousIndex;
  return allowed.reduce((best, index) => {
    const start = Math.max(0.001, Number(startScale?.[index]) || 1);
    const current = Number(currentScale?.[index]);
    const delta = Math.abs((Number.isFinite(current) ? current : start) / start - 1);
    const bestStart = Math.max(0.001, Number(startScale?.[best]) || 1);
    const bestCurrent = Number(currentScale?.[best]);
    const bestDelta = Math.abs((Number.isFinite(bestCurrent) ? bestCurrent : bestStart) / bestStart - 1);
    return delta > bestDelta ? index : best;
  }, allowed[0]);
}

function spatialEulerDegrees(quaternion) {
  const values = Array.isArray(quaternion) ? quaternion : [0, 0, 0, 1];
  const euler = new THREE.Euler().setFromQuaternion(new THREE.Quaternion(...values), "XYZ");
  return [euler.x, euler.y, euler.z].map((value) => THREE.MathUtils.radToDeg(value));
}

function formatSpatialNumber(value) {
  const number = Number(value);
  return Number.isFinite(number) ? String(Number(number.toFixed(4))) : "0";
}

function normalizeSpatialAnchor(anchor, entity = null) {
  const source = anchor && typeof anchor === "object" ? anchor : {};
  const sceneRoot = ["reader", "glb", "image-plane"].includes(spatialEntityType(entity));
  const type = sceneRoot
    ? "scene"
    : ["world", "reader", "asset", "source-focus"].includes(source.type)
      ? source.type
      : "world";
  return {
    ...source,
    type,
    ...(source.assetId ? { assetId: String(source.assetId) } : {}),
    ...(source.cueId ? { cueId: String(source.cueId) } : {}),
  };
}

function spatialAnchorLabel(type) {
  if (type === "reader") return "Reader / headset";
  if (type === "asset") return "3D model";
  if (type === "source-focus") return "Source-camera focus";
  return "World";
}

function spatialOrientationLabel(policy) {
  if (policy === "reader-facing-yaw") return "Upright, face reader";
  if (policy === "reader-facing") return "Full billboard";
  return "Fixed orientation";
}

function spatialFallbackTextEntity(beat, index, proposal, legacyPlacement = null) {
  const kind = inferTextComfortKind(proposal);
  const placement = legacyPlacement
    ? effectiveTextPlacementForBeat(legacyPlacement, beat, kind)
    : defaultTextPlacementForKind(kind, beat);
  const rotation = placement.rotation || { x: 0, y: 0, z: 0 };
  const transform = normalizeSpatialTransform({
    position: [placement.position?.x || 0, placement.position?.y || 0, placement.position?.z || 0],
    rotation: [rotation.x || 0, rotation.y || 0, rotation.z || 0],
    scale: [placement.scale || 1, placement.scale || 1, placement.scale || 1],
  });
  const coordinateSpace = placement.coordinateSpace || "world";
  const anchor = {
    type: coordinateSpace === "source-focus" ? "source-focus" : coordinateSpace === "asset" ? "asset" : coordinateSpace === "reader" ? "reader" : "world",
    ...(placement.anchorAssetId ? { assetId: placement.anchorAssetId } : {}),
    ...(placement.sourceCueId ? { cueId: placement.sourceCueId } : {}),
  };
  const clearanceEnabled = ["source-focus", "asset"].includes(anchor.type) && Boolean(anchor.assetId);
  return {
    id: `text-panel:${beat.id}`,
    type: "text-panel",
    scope: "beat",
    beatId: beat.id,
    inferredTransform: transform,
    transform: cloneJson(transform),
    anchor,
    orientationPolicy: placement.facesReader ? "reader-facing" : "fixed",
    panel: { width: Number(placement.width) || 1.35, height: Number(placement.height) || 0.72 },
    clearance: normalizeSpatialPanelClearance(null, clearanceEnabled),
    manual: false,
    inference: {
      confidence: Number(proposal?.confidence) || 0.5,
      reasons: [beat.linkedAssetIds?.length ? "Placed near the story part's linked visual evidence." : "Placed in a stable world reading zone."],
    },
  };
}

function normalizeSpatialPanelClearance(value, enabledFallback = false) {
  const source = value && typeof value === "object" ? value : {};
  const number = (candidate, fallback, minimum, maximum) => {
    const parsed = Number(candidate);
    return Math.max(minimum, Math.min(maximum, Number.isFinite(parsed) ? parsed : fallback));
  };
  return {
    enabled: source.enabled === undefined ? Boolean(enabledFallback) : source.enabled === true,
    strategy: "visible-bounds-push-v2",
    minSurfaceDistance: number(source.minSurfaceDistance, 0.14, 0.02, 0.75),
    maxPushDistance: number(source.maxPushDistance, 5, 0.1, 5),
    sampleGrid: Math.round(number(source.sampleGrid, 5, 2, 5)),
    recheckIntervalMs: Math.round(number(source.recheckIntervalMs, 250, 50, 1000)),
  };
}

function spatialSceneContextsFromGraph() {
  const contexts = [];
  for (const beat of spatialPreviewBeats()) {
    contexts.push(spatialSceneContext(beat.id));
    const group = variantGroupForBeat(beat);
    for (const option of group?.options || []) contexts.push(spatialSceneContext(beat.id, group.id, option.id));
  }
  return contexts;
}

function spatialSceneEntitySuffix(context) {
  return context?.variantOptionId ? `:variant:${context.variantOptionId}` : "";
}

function inferredSpatialReaderTransform() {
  return normalizeSpatialTransform({
    position: [0, 1.55, 5.2],
    quaternion: [0, 0, 0, 1],
    scale: [1, 1, 1],
  });
}

function fallbackSpatialSceneEntities(context, proposal, legacyPlacement = null) {
  const beat = spatialSceneBeat(context);
  if (!beat) return [];
  const suffix = spatialSceneEntitySuffix(context);
  const readerTransform = inferredSpatialReaderTransform();
  const readerEntity = context.variantOptionId ? null : {
    id: `reader:beat:${context.beatId}${suffix}`,
    type: "reader",
    kind: "reader",
    scope: "beat",
    beatId: context.beatId,
    ...(context.variantGroupId ? { variantGroupId: context.variantGroupId } : {}),
    ...(context.variantOptionId ? { variantOptionId: context.variantOptionId } : {}),
    inferredTransform: readerTransform,
    transform: cloneJson(readerTransform),
    anchor: { type: "scene" },
    orientationPolicy: "fixed",
    manual: false,
    inference: { confidence: 1, reasons: ["Inferred as the scene's default reader pose."] },
  };
  const textEntity = spatialFallbackTextEntity(beat, 0, proposal, legacyPlacement);
  textEntity.id = `text-panel:${context.beatId}${suffix}`;
  textEntity.beatId = context.beatId;
  if (context.variantOptionId) {
    textEntity.variantGroupId = context.variantGroupId;
    textEntity.variantOptionId = context.variantOptionId;
  }
  const assetEntities = (beat.linkedAssetIds || []).map((assetId) => {
    const asset = findAssetById(assetId);
    if (!asset || (!isModelAsset(asset) && !isImageAsset(asset))) return null;
    const type = isModelAsset(asset) ? "glb" : "image-plane";
    const identity = normalizeSpatialTransform(null);
    return {
      id: `${type === "glb" ? "glb" : "image"}:${assetId}:beat:${context.beatId}${suffix}`,
      type,
      kind: type,
      scope: "beat",
      beatId: context.beatId,
      ...(context.variantGroupId ? { variantGroupId: context.variantGroupId } : {}),
      ...(context.variantOptionId ? { variantOptionId: context.variantOptionId } : {}),
      assetId,
      ...(type === "glb" ? { verticalAlignment: "ground" } : {}),
      inferredTransform: identity,
      transform: cloneJson(identity),
      anchor: { type: "scene" },
      orientationPolicy: "fixed",
      ...(type === "image-plane" ? { image: { aspectRatio: null, width: 1.6, height: 0.9 } } : {}),
      manual: false,
      inference: { confidence: 1, reasons: ["Suggested from this scene's Story order asset links."] },
    };
  }).filter(Boolean);
  return [readerEntity, textEntity, ...assetEntities].filter(Boolean);
}

function fallbackSpatialRelationEntities(proposal, legacyPlacement = null) {
  return spatialSceneContextsFromGraph().flatMap((context) => fallbackSpatialSceneEntities(context, proposal, legacyPlacement));
}

function spatialRelationSourceContract(proposal) {
  const decision = spatialRelationsDecision();
  const proposalBundle = spatialRelationsProposalBundle();
  const decisionContract = decision?.spatialRelations;
  if (spatialRelationEntities(decisionContract).length || decisionContract?.resolvedByBeat || decisionContract?.resolvedByVariant) return decisionContract;
  const proposalContract = proposal?.spatialRelations
    || proposal?.inference?.spatialRelations
    || proposalBundle?.spatialRelations
    || proposalBundle?.inference?.spatialRelations;
  if (spatialRelationEntities(proposalContract).length || proposalContract?.resolvedByBeat || proposalContract?.resolvedByVariant) return proposalContract;
  return null;
}

function normalizeSpatialRelationEntity(source, fallback, options = {}) {
  const entity = { ...fallback, ...(source || {}) };
  entity.id = String(entity.id || fallback.id);
  entity.type = spatialEntityType(entity);
  entity.kind = entity.type;
  if (entity.type === "reader") {
    entity.beatId = entity.beatId || fallback.beatId || activeSpatialSceneContext()?.beatId || null;
    entity.scope = "beat";
    delete entity.assetId;
  } else if (entity.type === "glb" || entity.type === "image-plane") {
    entity.assetId = entity.assetId || String(entity.id).split(":beat:")[0].replace(/^(glb|image):/, "");
    entity.beatId = entity.beatId || fallback.beatId || activeSpatialSceneContext()?.beatId || null;
    entity.scope = "beat";
    if (entity.type === "image-plane") {
      entity.image = {
        aspectRatio: Number.isFinite(Number(entity.image?.aspectRatio)) ? Number(entity.image.aspectRatio) : null,
        width: Math.max(0.1, Number(entity.image?.width ?? fallback.image?.width) || 1.6),
        height: Math.max(0.1, Number(entity.image?.height ?? fallback.image?.height) || 0.9),
      };
    }
  } else {
    entity.beatId = entity.beatId || entity.id.slice("text-panel:".length);
    entity.scope = "beat";
  }
  entity.inferredTransform = normalizeSpatialTransform(entity.inferredTransform || entity.transform, fallback.inferredTransform);
  entity.transform = normalizeSpatialTransform(entity.transform, entity.inferredTransform);
  if (entity.type === "reader") {
    entity.inferredTransform.scale = [1, 1, 1];
    entity.transform.scale = [1, 1, 1];
  }
  entity.anchor = normalizeSpatialAnchor(entity.anchor || fallback.anchor, entity);
  const orientationPolicy = entity.orientationPolicy === "yaw-only" ? "reader-facing-yaw"
    : entity.orientationPolicy === "full-billboard" ? "reader-facing"
      : entity.orientationPolicy;
  entity.orientationPolicy = ["fixed", "reader-facing-yaw", "reader-facing"].includes(orientationPolicy)
    ? orientationPolicy
    : fallback.orientationPolicy || "fixed";
  if (entity.type === "text-panel") {
    entity.panel = {
      width: Math.max(0.2, Math.min(8, Number(entity.panel?.width ?? fallback.panel?.width) || 1.35)),
      height: Math.max(0.1, Math.min(5, Number(entity.panel?.height ?? fallback.panel?.height) || 0.72)),
    };
    const clearanceFallback = ["source-focus", "asset"].includes(entity.anchor.type) && Boolean(entity.anchor.assetId);
    entity.clearance = normalizeSpatialPanelClearance(entity.clearance ?? fallback.clearance, clearanceFallback);
  } else delete entity.panel;
  entity.inference = { ...(fallback.inference || {}), ...(entity.inference || {}) };
  entity.manual = Boolean(
    entity.manual
    || !spatialTransformsEqual(entity.transform, entity.inferredTransform),
  );
  if (entity.type === "glb") {
    const suppliedAlignment = !options.migrateLegacyVerticalAlignment
      && source
      && Object.hasOwn(source, "verticalAlignment")
      ? source.verticalAlignment
      : null;
    entity.verticalAlignment = normalizeSpatialVerticalAlignment(
      suppliedAlignment,
      options.migrateLegacyVerticalAlignment ? "ground" : fallback.verticalAlignment || "ground",
    );
  } else delete entity.verticalAlignment;
  entity._inferredAnchor = cloneJson(entity.anchor);
  entity._inferredOrientationPolicy = entity.orientationPolicy;
  entity._inferredClearance = cloneJson(entity.clearance || null);
  return entity;
}

function ensureSpatialRelationsDraft(component = spatialRelationsComponent(), proposal = null) {
  const bundle = spatialRelationsProposalBundle();
  const selectedProposal = proposal || (component ? selectedTopologyProposal(component, bundle, spatialRelationsDecision()) : null);
  const source = spatialRelationSourceContract(selectedProposal);
  const legacyPlacement = !source ? state.data?.decisions?.[LEGACY_TEXT_COMFORT_COMPONENT_ID]?.textPlacement : null;
  const signature = source?.inputSignature || selectedProposal?.inputSignature || bundle?.inputSignature || "frontend-fallback";
  const migrateLegacyVerticalAlignment = source?.inferenceVersion !== CURRENT_SPATIAL_RELATIONS_INFERENCE_VERSION;
  const contexts = spatialSceneContextsFromGraph();
  const draftKey = `${selectedProposal?.optionId || bundle?.defaultOptionId || "inferred-layout"}:${signature}:${contexts.length}:${source?.schemaVersion || "fallback"}`;
  if (!state.spatialRelationsDraft || state.spatialRelationsDraftKey !== draftKey) {
    const sourceFlat = spatialRelationEntities(source);
    const resolvedByBeat = {};
    const resolvedByVariant = {};
    const entities = [];
    for (const context of contexts) {
      const sourceScene = spatialSceneRecordForContext(source, context);
      const fallbackEntities = fallbackSpatialSceneEntities(context, selectedProposal, legacyPlacement);
      const sceneSourceEntities = spatialRelationEntities(sourceScene);
      const normalizedEntities = fallbackEntities.map((fallback) => {
        const exact = sceneSourceEntities.find((entity) => entity.id === fallback.id)
          || sourceFlat.find((entity) => entity.id === fallback.id);
        const compatible = exact || sceneSourceEntities.find((entity) => (
          spatialEntityType(entity) === spatialEntityType(fallback)
          && (fallback.assetId ? entity.assetId === fallback.assetId : entity.beatId === fallback.beatId)
        )) || sourceFlat.find((entity) => (
          spatialEntityType(entity) === spatialEntityType(fallback)
          && (fallback.assetId ? entity.assetId === fallback.assetId : entity.beatId === fallback.beatId)
          && (!entity.variantOptionId || entity.variantOptionId === context.variantOptionId)
        ));
        return normalizeSpatialRelationEntity(compatible, fallback, { migrateLegacyVerticalAlignment });
      });
      for (const sourceEntity of sceneSourceEntities) {
        if (normalizedEntities.some((entity) => entity.id === sourceEntity.id)) continue;
        if (context.variantOptionId && spatialEntityType(sourceEntity) === "reader") continue;
        normalizedEntities.push(normalizeSpatialRelationEntity(sourceEntity, sourceEntity, { migrateLegacyVerticalAlignment }));
      }
      const fallbackBeat = spatialSceneBeat(context);
      const sceneKey = sourceScene?.sceneKey || spatialSceneRequestKey(context);
      const scene = {
        ...(sourceScene ? cloneJson(sourceScene) : {}),
        sceneKey,
        sceneId: sourceScene?.sceneId || sceneKey,
        beatId: context.beatId,
        ...(context.variantGroupId ? { variantGroupId: context.variantGroupId } : {}),
        ...(context.variantOptionId ? { variantOptionId: context.variantOptionId } : {}),
        linkedAssetIds: spatialSceneLinkedAssetIds(sourceScene, fallbackBeat, context.variantOptionId ? sourceGraphVariantOption(context) : null),
        inputSignature: sourceScene?.inputSignature || signature,
        entities: normalizedEntities,
      };
      delete scene.viewpoint;
      delete scene.viewpointLabel;
      if (context.variantOptionId) resolvedByVariant[sceneKey] = scene;
      else resolvedByBeat[context.beatId] = scene;
      entities.push(...normalizedEntities);
    }
    state.spatialRelationsDraft = {
      ...(source ? cloneJson(source) : {}),
      schemaVersion: "storyvr-spatial-relations/v2",
      inferenceVersion: CURRENT_SPATIAL_RELATIONS_INFERENCE_VERSION,
      inputSignature: signature,
      entities,
      resolvedByBeat,
      resolvedByVariant,
    };
    delete state.spatialRelationsDraft.viewpoint;
    delete state.spatialRelationsDraft.viewpointLabel;
    state.spatialRelationsDraftKey = draftKey;
  state.spatialDraftRevision = 0;
  state.spatialDraftDirty = false;
  }
  return state.spatialRelationsDraft;
}

function spatialRelationsForSave(component = spatialRelationsComponent()) {
  const proposal = component ? selectedTopologyProposal(component, spatialRelationsProposalBundle(), spatialRelationsDecision()) : null;
  const draft = ensureSpatialRelationsDraft(component, proposal);
  syncSpatialFlatEntitiesFromScenes(draft);
  const clean = cleanSpatialRelationsValue(draft);
  clean.schemaVersion = "storyvr-spatial-relations/v2";
  const normalizeEntities = (owner) => {
    if (!owner || !Array.isArray(owner.entities)) return;
    owner.entities = owner.entities.map((entity) => {
      return {
        ...entity,
        inferredTransform: normalizeSpatialTransform(entity.inferredTransform),
        transform: normalizeSpatialTransform(entity.transform, entity.inferredTransform),
        manual: Boolean(entity.manual),
      };
    });
  };
  normalizeEntities(clean);
  for (const scene of spatialAllSceneRecords(clean)) normalizeEntities(scene);
  return clean;
}

function cleanSpatialRelationsValue(value) {
  if (Array.isArray(value)) return value.map(cleanSpatialRelationsValue);
  if (!value || typeof value !== "object") return value;
  return Object.fromEntries(Object.entries(value)
    .filter(([key]) => !key.startsWith("_") && !["viewpoint", "viewpointLabel", "viewpointScaleGuidance"].includes(key))
    .map(([key, entry]) => [key, cleanSpatialRelationsValue(entry)]));
}

function sourceGraphVariantOption(context) {
  if (!context?.variantOptionId) return null;
  const beat = (state.data?.graph?.beats || []).find((candidate) => candidate.id === context.beatId);
  const group = beat ? variantGroupForBeat(beat) : null;
  return (group?.options || []).find((option) => option.id === context.variantOptionId) || null;
}

function spatialRelationEntityById(contract, entityId) {
  return spatialSceneEntities(contract).find((entity) => entity.id === entityId)
    || spatialRelationEntities(contract).find((entity) => entity.id === entityId)
    || null;
}

function selectedSpatialRelationEntity(contract = state.spatialRelationsDraft) {
  return spatialRelationEntityById(contract, state.selectedSpatialEntityId);
}

function selectedSpatialRelationEntityIds(
  contract = state.spatialRelationsDraft,
  context = activeSpatialSceneContext(),
) {
  const availableIds = new Set(spatialEditorSceneEntities(contract, context).map((entity) => entity.id));
  const requestedIds = Array.isArray(state.selectedSpatialEntityIds)
    ? state.selectedSpatialEntityIds
    : [];
  const selectedIds = [];
  for (const entityId of [...requestedIds, state.selectedSpatialEntityId]) {
    if (!entityId || !availableIds.has(entityId) || selectedIds.includes(entityId)) continue;
    selectedIds.push(entityId);
  }
  return selectedIds;
}

function selectedSpatialRelationEntities(
  contract = state.spatialRelationsDraft,
  context = activeSpatialSceneContext(),
) {
  const selectedIds = new Set(selectedSpatialRelationEntityIds(contract, context));
  return spatialEditorSceneEntities(contract, context)
    .filter((entity) => selectedIds.has(entity.id));
}

function spatialSelectionCanTransform(
  mode = state.spatialTransformMode,
  contract = state.spatialRelationsDraft,
) {
  const entities = selectedSpatialRelationEntities(contract);
  if (
    !entities.length
    || entities.some((entity) => !spatialEntityTransformEditable(entity))
  ) return false;
  return mode !== "scale" || entities.every((entity) => spatialEntityType(entity) !== "reader");
}

function spatialSelectionLabel(entities = selectedSpatialRelationEntities()) {
  if (entities.length > 1) return `${entities.length} objects selected`;
  return spatialRelationEntityLabel(entities[0]) || "No selection";
}

function setSpatialRelationSelection(entityIds, options = {}) {
  const sceneKey = spatialSceneRequestKey(activeSpatialSceneContext());
  const entities = spatialEditorSceneEntities(
    state.spatialRelationsDraft,
    activeSpatialSceneContext(),
  );
  const requestedIds = new Set((Array.isArray(entityIds) ? entityIds : [entityIds]).filter(Boolean));
  const selectedIds = entities
    .map((entity) => entity.id)
    .filter((entityId) => requestedIds.has(entityId));
  const requestedPrimaryId = String(options.primaryEntityId || "");
  const primaryEntityId = selectedIds.includes(requestedPrimaryId)
    ? requestedPrimaryId
    : selectedIds[selectedIds.length - 1] || null;
  state.selectedSpatialEntityIds = selectedIds;
  state.selectedSpatialEntityId = primaryEntityId;
  if (selectedIds.length) state.spatialSelectionClearedSceneKey = "";
  else if (options.explicitClear === true) state.spatialSelectionClearedSceneKey = sceneKey;
  if (Object.hasOwn(options, "anchorEntityId")) {
    state.spatialSelectionAnchorEntityId = options.anchorEntityId || null;
  } else if (primaryEntityId) state.spatialSelectionAnchorEntityId = primaryEntityId;
  if (options.syncViewer !== false) syncSpatialSelectionInViewer();
  return selectedIds;
}

function spatialHierarchySelectionForClick(
  orderedEntityIds,
  selectedEntityIds,
  clickedEntityId,
  anchorEntityId,
  options = {},
) {
  const orderedIds = [...new Set((orderedEntityIds || []).filter(Boolean))];
  if (!orderedIds.includes(clickedEntityId)) {
    return {
      entityIds: (selectedEntityIds || []).filter((entityId) => orderedIds.includes(entityId)),
      primaryEntityId: null,
      anchorEntityId: anchorEntityId || null,
    };
  }
  const selected = new Set((selectedEntityIds || []).filter((entityId) => orderedIds.includes(entityId)));
  const toggle = options.toggle === true;
  const range = options.range === true;
  let nextAnchorId = anchorEntityId;
  if (range) {
    const anchorIndex = orderedIds.indexOf(anchorEntityId);
    const clickedIndex = orderedIds.indexOf(clickedEntityId);
    const rangeAnchorIndex = anchorIndex >= 0 ? anchorIndex : clickedIndex;
    const rangeIds = orderedIds.slice(
      Math.min(rangeAnchorIndex, clickedIndex),
      Math.max(rangeAnchorIndex, clickedIndex) + 1,
    );
    if (!toggle) selected.clear();
    for (const entityId of rangeIds) selected.add(entityId);
    if (anchorIndex < 0) nextAnchorId = clickedEntityId;
  } else if (toggle) {
    if (selected.has(clickedEntityId) && selected.size > 1) selected.delete(clickedEntityId);
    else selected.add(clickedEntityId);
    nextAnchorId = clickedEntityId;
  } else {
    selected.clear();
    selected.add(clickedEntityId);
    nextAnchorId = clickedEntityId;
  }
  const entityIds = orderedIds.filter((entityId) => selected.has(entityId));
  return {
    entityIds,
    primaryEntityId: selected.has(clickedEntityId)
      ? clickedEntityId
      : entityIds[entityIds.length - 1] || null,
    anchorEntityId: nextAnchorId || clickedEntityId,
  };
}

function ensureSpatialSelection(draft, beat, context = activeSpatialSceneContext()) {
  const entities = spatialEditorSceneEntities(draft, context);
  const entityIds = new Set(entities.map((entity) => entity.id));
  const selectedIds = selectedSpatialRelationEntityIds(draft, context)
    .filter((entityId) => entityIds.has(entityId));
  const sceneKey = spatialSceneRequestKey(context);
  const explicitlyCleared = Boolean(sceneKey)
    && state.spatialSelectionClearedSceneKey === sceneKey;
  if (!selectedIds.length && entities[0]?.id && !explicitlyCleared) selectedIds.push(entities[0].id);
  const primaryEntityId = selectedIds.includes(state.selectedSpatialEntityId)
    ? state.selectedSpatialEntityId
    : selectedIds[selectedIds.length - 1] || null;
  state.selectedSpatialEntityIds = selectedIds;
  state.selectedSpatialEntityId = primaryEntityId;
  if (selectedIds.length || !entities.length) state.spatialSelectionClearedSceneKey = "";
  if (!entityIds.has(state.spatialSelectionAnchorEntityId)) {
    state.spatialSelectionAnchorEntityId = primaryEntityId;
  }
}

function spatialGlbCrossSceneMatchKey(entity, options = {}) {
  if (spatialEntityType(entity) !== "glb" || !entity?.assetId) return "";
  const sourceIdentity = String(entity.sourceInstanceId || "").trim();
  if (sourceIdentity) return `source:${sourceIdentity}`;
  if (entity.authoredInstance !== true) return `${entity.assetId}::base`;
  const idOrdinal = String(entity.id || "").match(/:instance:(\d+)$/)?.[1];
  const instanceIndex = Number(entity.instanceIndex || idOrdinal);
  return Number.isSafeInteger(instanceIndex) && instanceIndex > 0
    ? `${entity.assetId}::instance:${instanceIndex}`
    : "";
}

function spatialMatchingGlbsInOtherScenes(
  sourceEntity,
  contract = state.spatialRelationsDraft,
  sourceContext = activeSpatialSceneContext(),
) {
  const matchKey = spatialGlbCrossSceneMatchKey(sourceEntity);
  if (!matchKey || !contract) return [];
  const sourceScene = spatialSceneRecordForContext(contract, sourceContext);
  return spatialAllSceneRecords(contract).flatMap((scene) => {
    if (scene === sourceScene) return [];
    return spatialRelationEntities(scene)
      .filter((entity) => (
        spatialGlbCrossSceneMatchKey(entity, { includeAttachedSource: true }) === matchKey
      ))
      .map((entity) => ({ scene, entity }));
  });
}

function spatialPropagationTargetBeats(
  sourceEntity = selectedSpatialRelationEntity(),
  contract = state.spatialRelationsDraft,
  sourceContext = activeSpatialSceneContext(),
) {
  const activeBeatId = String(sourceContext?.beatId || sourceEntity?.beatId || "").trim();
  const sceneCountsByBeat = new Map();
  for (const { scene } of spatialMatchingGlbsInOtherScenes(sourceEntity, contract, sourceContext)) {
    const beatId = String(scene?.beatId || "").trim();
    if (!beatId || beatId === activeBeatId) continue;
    sceneCountsByBeat.set(beatId, (sceneCountsByBeat.get(beatId) || 0) + 1);
  }
  return spatialPreviewBeats()
    .map((beat, index) => ({
      ...beat,
      index,
      matchingSceneCount: sceneCountsByBeat.get(beat.id) || 0,
    }))
    .filter((beat) => beat.matchingSceneCount > 0);
}

function spatialClipboardTargetBase(context = activeSpatialSceneContext()) {
  const clipboard = state.spatialClipboard;
  if (!clipboard?.assetId || !context?.beatId) return null;
  return spatialSceneEntities(state.spatialRelationsDraft, context).find((entity) => (
    spatialEntityType(entity) === "glb"
    && entity.authoredInstance !== true
    && entity.assetId === clipboard.assetId
  )) || null;
}

function canPasteSpatialGlbInstance(context = activeSpatialSceneContext()) {
  return Boolean(state.spatialClipboard?.kind === "glb" && spatialClipboardTargetBase(context));
}

function syncSpatialClipboardControls() {
  const selected = selectedSpatialRelationEntity();
  const singleSelected = selectedSpatialRelationEntities().length === 1;
  const copy = document.querySelector("[data-spatial-copy-model]");
  if (copy) copy.disabled = !singleSelected
    || spatialEntityType(selected) !== "glb";
  const paste = document.querySelector("[data-spatial-paste-model]");
  if (paste) paste.disabled = !canPasteSpatialGlbInstance();
  const status = document.querySelector("[data-spatial-clipboard-status]");
  if (status) status.textContent = state.spatialClipboardStatus;
}

function bindSpatialPropagationTargetEvents() {
  document.querySelector("[data-spatial-apply-toggle]")?.addEventListener("click", () => {
    state.spatialPropagationTargetsOpen = !state.spatialPropagationTargetsOpen;
    renderPreservingScroll();
  });
  const selectAll = document.querySelector("[data-spatial-apply-select-all]");
  selectAll?.addEventListener("change", () => {
    state.spatialPropagationTargetBeatIds = selectAll.checked
      ? spatialPropagationTargetBeats().map((beat) => beat.id)
      : [];
    syncSpatialPropagationControls();
  });
  for (const checkbox of document.querySelectorAll("[data-spatial-apply-target]")) {
    checkbox.addEventListener("change", () => {
      const selected = new Set(state.spatialPropagationTargetBeatIds || []);
      if (checkbox.checked) selected.add(checkbox.dataset.spatialApplyTarget);
      else selected.delete(checkbox.dataset.spatialApplyTarget);
      state.spatialPropagationTargetBeatIds = spatialPropagationTargetBeats()
        .map((beat) => beat.id)
        .filter((beatId) => selected.has(beatId));
      syncSpatialPropagationControls();
    });
  }
  document.querySelector("[data-spatial-apply-submit]")?.addEventListener("click", () => {
    applySelectedSpatialGlbTransformToMatchingScenes();
  });
  syncSpatialPropagationControls();
}

function syncSpatialPropagationControls() {
  const selected = selectedSpatialRelationEntities().length === 1
    ? selectedSpatialRelationEntity()
    : null;
  const targetBeats = spatialPropagationTargetBeats(selected);
  const validIds = new Set(targetBeats.map((beat) => beat.id));
  const selectedId = selected?.id || null;
  if (state.spatialPropagationSelectionId !== selectedId) {
    state.spatialPropagationSelectionId = selectedId;
    state.spatialPropagationTargetsOpen = false;
    state.spatialPropagationTargetBeatIds = [];
    state.spatialPropagationStatus = spatialEntityType(selected) === "glb"
      ? (targetBeats.length
          ? `Choose which other story part${targetBeats.length === 1 ? "" : "s"} should receive the ${spatialRelationEntityLabel(selected)} placement.`
          : "No matching instance of this 3D model exists in another story part.")
      : "";
  }
  const selectedIds = new Set(
    (state.spatialPropagationTargetBeatIds || []).filter((beatId) => validIds.has(beatId)),
  );
  const currentBeatSelected = Boolean(activeSpatialSceneContext()?.beatId);
  const selectedBeatCount = selectedIds.size + (currentBeatSelected ? 1 : 0);
  const listedBeatCount = targetBeats.length + (currentBeatSelected ? 1 : 0);
  state.spatialPropagationTargetBeatIds = targetBeats
    .map((beat) => beat.id)
    .filter((beatId) => selectedIds.has(beatId));
  const toggle = document.querySelector("[data-spatial-apply-toggle]");
  if (toggle) {
    toggle.disabled = spatialEntityType(selected) !== "glb" || targetBeats.length === 0;
    toggle.textContent = "Apply placement to other story parts…";
    toggle.title = targetBeats.length
      ? `Choose which of ${targetBeats.length} other matching story part${targetBeats.length === 1 ? "" : "s"} receives this 3D model placement.`
      : "No matching instance of this 3D model exists in another story part.";
    toggle.setAttribute("aria-expanded", String(state.spatialPropagationTargetsOpen));
  }
  const panel = document.querySelector("[data-spatial-apply-target-panel]");
  if (panel) panel.hidden = !state.spatialPropagationTargetsOpen;
  const scope = document.querySelector(".spatial-apply-scope");
  scope?.classList.toggle("open", state.spatialPropagationTargetsOpen);
  const selectAll = document.querySelector("[data-spatial-apply-select-all]");
  if (selectAll) {
    selectAll.checked = Boolean(targetBeats.length) && selectedIds.size === targetBeats.length;
    selectAll.indeterminate = selectedBeatCount > 0 && selectedBeatCount < listedBeatCount;
  }
  for (const checkbox of document.querySelectorAll("[data-spatial-apply-target]")) {
    const checked = selectedIds.has(checkbox.dataset.spatialApplyTarget);
    checkbox.checked = checked;
    checkbox.closest(".spatial-apply-target-row")?.classList.toggle("selected", checked);
  }
  const count = document.querySelector("[data-spatial-apply-count]");
  if (count) count.textContent = `${selectedBeatCount} selected`;
  const submit = document.querySelector("[data-spatial-apply-submit]");
  if (submit) {
    submit.disabled = selectedIds.size === 0;
    submit.textContent = "Apply to selected story parts";
  }
  for (const status of document.querySelectorAll("[data-spatial-propagation-status]")) {
    status.textContent = state.spatialPropagationStatus;
  }
}

function copySelectedSpatialGlb() {
  const entity = selectedSpatialRelationEntity();
  if (
    selectedSpatialRelationEntities().length !== 1
    || spatialEntityType(entity) !== "glb"
  ) {
    state.spatialClipboardStatus = "Select one 3D model before copying.";
    syncSpatialClipboardControls();
    return false;
  }
  state.spatialClipboard = {
    schemaVersion: "storyvr-spatial-clipboard/v1",
    kind: "glb",
    assetId: entity.assetId,
    entity: cloneJson(entity),
  };
  state.spatialClipboardStatus = `${spatialRelationEntityLabel(entity)} copied. Paste to add another instance.`;
  syncSpatialClipboardControls();
  return true;
}

function applySelectedSpatialGlbTransformToMatchingScenes() {
  const sourceEntity = selectedSpatialRelationEntity();
  if (
    selectedSpatialRelationEntities().length !== 1
    || spatialEntityType(sourceEntity) !== "glb"
  ) {
    state.spatialPropagationStatus = "Select a 3D model before applying its placement.";
    syncSpatialPropagationControls();
    return false;
  }
  const sourceBeatId = String(activeSpatialSceneContext()?.beatId || sourceEntity.beatId || "").trim();
  const allMatches = spatialMatchingGlbsInOtherScenes(sourceEntity);
  const availableBeatIds = new Set(allMatches
    .map(({ scene }) => String(scene?.beatId || "").trim())
    .filter((beatId) => beatId && beatId !== sourceBeatId));
  const targetBeatIds = new Set((state.spatialPropagationTargetBeatIds || [])
    .map((beatId) => String(beatId || "").trim())
    .filter((beatId) => availableBeatIds.has(beatId)));
  if (!targetBeatIds.size) {
    state.spatialPropagationStatus = "Select one or more other story parts before applying this placement.";
    syncSpatialPropagationControls();
    return false;
  }
  const matches = allMatches.filter(({ scene }) => targetBeatIds.has(String(scene?.beatId || "").trim()));
  const sourceTransform = normalizeSpatialTransform(sourceEntity.transform, sourceEntity.inferredTransform);
  const sourceVerticalAlignment = spatialEntityVerticalAlignment(sourceEntity);
  const updates = matches.map(({ scene, entity }) => {
    const transform = cloneJson(sourceTransform);
    const manual = entity.authoredInstance === true
      || !spatialTransformsEqual(transform, entity.inferredTransform);
    return {
      scene,
      entity,
      transform,
      verticalAlignment: sourceVerticalAlignment,
      manual,
    };
  }).filter(({ entity, transform, verticalAlignment, manual }) => (
    !spatialTransformsEqual(entity.transform, transform)
    || spatialEntityVerticalAlignment(entity) !== verticalAlignment
    || Boolean(entity.manual) !== manual
  ));
  if (!matches.length) {
    state.spatialPropagationStatus = "No matching instance of this 3D model exists in the selected story parts.";
    syncSpatialPropagationControls();
    return false;
  }
  if (!updates.length) {
    state.spatialPropagationStatus = `This 3D model already has the same placement in ${targetBeatIds.size} selected story part${targetBeatIds.size === 1 ? "" : "s"}.`;
    syncSpatialPropagationControls();
    return false;
  }
  pushSpatialUndoSnapshot();
  for (const {
    entity,
    transform,
    verticalAlignment,
    manual,
  } of updates) {
    entity.transform = transform;
    entity.verticalAlignment = verticalAlignment;
    entity.manual = manual;
  }
  const updatedBeatCount = new Set(updates.map(({ scene }) => String(scene?.beatId || "").trim())).size;
  state.spatialPropagationTargetBeatIds = [];
  state.spatialPropagationStatus = `Applied ${spatialRelationEntityLabel(sourceEntity)} placement to ${updatedBeatCount} selected story part${updatedBeatCount === 1 ? "" : "s"}.`;
  commitSpatialDraftMutation();
  finalizePersistentAuthorHistory(flushSpatialRelationsAutosave);
  syncSpatialPropagationControls();
  return true;
}

function nextSpatialGlbInstanceIdentity(scene, baseEntity) {
  const ids = new Set(spatialRelationEntities(scene).map((entity) => entity.id));
  let instanceIndex = 2;
  while (ids.has(`${baseEntity.id}:instance:${instanceIndex}`)) instanceIndex += 1;
  return {
    id: `${baseEntity.id}:instance:${instanceIndex}`,
    instanceIndex,
  };
}

function spatialPastedTransform(sourceEntity, baseEntity, instanceIndex) {
  const transform = normalizeSpatialTransform(sourceEntity?.transform, baseEntity?.transform || baseEntity?.inferredTransform);
  const offsetIndex = Math.max(1, Number(instanceIndex) - 1);
  const column = ((offsetIndex - 1) % 3) + 1;
  const row = Math.floor((offsetIndex - 1) / 3);
  transform.position[0] = Math.min(100, transform.position[0] + column * 0.35);
  transform.position[2] = Math.max(-100, transform.position[2] - row * 0.28);
  return transform;
}

function pasteSpatialGlbInstance() {
  const context = activeSpatialSceneContext();
  const scene = spatialSceneRecordForContext(state.spatialRelationsDraft, context);
  const baseEntity = spatialClipboardTargetBase(context);
  if (!scene || !baseEntity || state.spatialClipboard?.kind !== "glb") {
    state.spatialClipboardStatus = "This scene does not contain the copied 3D model.";
    syncSpatialClipboardControls();
    return false;
  }
  const identity = nextSpatialGlbInstanceIdentity(scene, baseEntity);
  const instance = {
    ...cloneJson(baseEntity),
    id: identity.id,
    authoredInstance: true,
    instanceOfEntityId: baseEntity.id,
    instanceIndex: identity.instanceIndex,
    copiedFromEntityId: state.spatialClipboard.entity?.id || baseEntity.id,
    inferredTransform: cloneJson(baseEntity.inferredTransform || baseEntity.transform),
    transform: spatialPastedTransform(state.spatialClipboard.entity, baseEntity, identity.instanceIndex),
    manual: true,
  };
  pushSpatialUndoSnapshot();
  if (!Array.isArray(scene.entities)) scene.entities = [];
  scene.entities.push(instance);
  state.selectedSpatialEntityId = instance.id;
  state.selectedSpatialEntityIds = [instance.id];
  state.spatialSelectionAnchorEntityId = instance.id;
  state.spatialClipboardStatus = `${spatialRelationEntityLabel(instance)} pasted as an independent instance.`;
  commitSpatialDraftMutation();
  finalizePersistentAuthorHistory(flushSpatialRelationsAutosave);
  renderPreservingScroll();
  return true;
}

function spatialHierarchyEntities(draft, beat) {
  return spatialEditorSceneEntities(draft, activeSpatialSceneContext());
}

function spatialInferenceConfidence(draft, proposal) {
  const values = spatialRelationEntities(draft)
    .filter((entity) => spatialEntityType(entity) === "text-panel")
    .map((entity) => Number(entity.inference?.confidence))
    .filter(Number.isFinite);
  if (values.length) return values.reduce((sum, value) => sum + value, 0) / values.length;
  const proposalConfidence = Number(proposal?.confidence);
  return Number.isFinite(proposalConfidence) ? proposalConfidence : null;
}

function spatialTransformsEqual(left, right) {
  const a = normalizeSpatialTransform(left);
  const b = normalizeSpatialTransform(right);
  return [...a.position, ...a.quaternion, ...a.scale]
    .every((value, index) => Math.abs(value - [...b.position, ...b.quaternion, ...b.scale][index]) < 0.0001);
}

function spatialSelectionTransformSummary(
  entities = selectedSpatialRelationEntities(),
  viewer = textViewer,
) {
  if (!entities.length) return normalizeSpatialTransform();
  if (entities.length === 1) {
    return normalizeSpatialTransform(entities[0].transform, entities[0].inferredTransform);
  }
  const loadedEntries = spatialSelectionObjects(viewer, entities);
  const allObjectsLoaded = loadedEntries.length === entities.length
    && loadedEntries.every(({ object }) => object);
  const position = allObjectsLoaded
    ? spatialSelectionWorldCenter(loadedEntries).toArray()
    : [0, 0, 0];
  if (allObjectsLoaded) {
    return {
      position,
      quaternion: [0, 0, 0, 1],
      scale: [1, 1, 1],
    };
  }
  for (const entity of entities) {
    const transform = normalizeSpatialTransform(entity.transform, entity.inferredTransform);
    for (let index = 0; index < 3; index += 1) position[index] += transform.position[index];
  }
  return {
    position: position.map((value) => value / entities.length),
    quaternion: [0, 0, 0, 1],
    scale: [1, 1, 1],
  };
}

function updateSpatialEntityManualState(entity, options = {}) {
  entity.manual = entity.authoredInstance === true
    || (options.reset === true
      ? false
      : Boolean(!spatialTransformsEqual(entity.transform, entity.inferredTransform)
      || JSON.stringify(normalizeSpatialAnchor(entity.anchor, entity)) !== JSON.stringify(entity._inferredAnchor)
      || entity.orientationPolicy !== entity._inferredOrientationPolicy));
}

function applySpatialTransformDeltaToEntities(entities, deltaMatrix) {
  if (!deltaMatrix?.isMatrix4) return 0;
  let updatedCount = 0;
  for (const entity of entities || []) {
    if (!spatialEntityTransformEditable(entity)) continue;
    const transform = normalizeSpatialTransform(entity.transform, entity.inferredTransform);
    const matrix = new THREE.Matrix4().compose(
      new THREE.Vector3(...transform.position),
      new THREE.Quaternion(...transform.quaternion),
      new THREE.Vector3(...transform.scale),
    );
    const nextMatrix = deltaMatrix.clone().multiply(matrix);
    const position = new THREE.Vector3();
    const quaternion = new THREE.Quaternion();
    const scale = new THREE.Vector3();
    nextMatrix.decompose(position, quaternion, scale);
    entity.transform = normalizeSpatialTransform({
      position: position.toArray(),
      quaternion: quaternion.normalize().toArray(),
      scale: spatialEntityType(entity) === "reader" ? [1, 1, 1] : scale.toArray(),
    }, entity.inferredTransform);
    updateSpatialEntityManualState(entity);
    updatedCount += 1;
  }
  return updatedCount;
}

function spatialGroupTransformDelta(entities, group, index, value) {
  const summary = spatialSelectionTransformSummary(entities);
  const pivot = new THREE.Vector3(...summary.position);
  if (group === "position") {
    const delta = new THREE.Vector3();
    delta.setComponent(index, value - summary.position[index]);
    return new THREE.Matrix4().makeTranslation(delta.x, delta.y, delta.z);
  }
  const operation = new THREE.Matrix4();
  if (group === "rotation") {
    const axis = [
      new THREE.Vector3(1, 0, 0),
      new THREE.Vector3(0, 1, 0),
      new THREE.Vector3(0, 0, 1),
    ][index];
    operation.makeRotationFromQuaternion(
      new THREE.Quaternion().setFromAxisAngle(axis, THREE.MathUtils.degToRad(value)),
    );
  } else if (group === "scale") {
    const scale = state.spatialScaleRatioLocked
      ? spatialLockedScaleForAxis([1, 1, 1], index, value)
      : [1, 1, 1].map((axisValue, axisIndex) => (
        axisIndex === index
          ? Math.max(0.001, Math.min(SPATIAL_TRANSFORM_SCALE_LIMIT, value))
          : axisValue
      ));
    operation.makeScale(...scale);
  } else return null;
  return new THREE.Matrix4()
    .makeTranslation(pivot.x, pivot.y, pivot.z)
    .multiply(operation)
    .multiply(new THREE.Matrix4().makeTranslation(-pivot.x, -pivot.y, -pivot.z));
}

function pushSpatialUndoSnapshot() {
  if (!state.spatialRelationsDraft) return false;
  return beginAuthorHistory("Edit object placement", "spatial-relations");
}

function commitSpatialDraftMutation() {
  syncSpatialFlatEntitiesFromScenes(state.spatialRelationsDraft);
  state.spatialDraftRevision += 1;
  state.spatialDraftDirty = true;
  markStoryvrCheckpointCompletionPending(spatialRelationsComponentId());
  scheduleSpatialRelationsAutosave();
  const status = document.querySelector("[data-spatial-autosave-status]");
  if (status) status.textContent = `${state.spatialAutosaveStatus} · revision ${state.spatialDraftRevision}`;
  updateCheckpointStatusDom(spatialRelationsComponentId());
  updateHistoryControlsDom();
}

function syncSpatialFlatEntitiesFromScenes(contract) {
  if (!contract) return;
  const sceneEntities = spatialAllSceneRecords(contract).flatMap((scene) => spatialRelationEntities(scene));
  if (sceneEntities.length || contract.resolvedByBeat || contract.resolvedByVariant) contract.entities = sceneEntities;
}

function setSpatialAutosaveStatus(value) {
  state.spatialAutosaveStatus = value;
  const status = document.querySelector("[data-spatial-autosave-status]");
  if (status) status.textContent = `${value} · revision ${state.spatialDraftRevision}`;
}

function scheduleSpatialRelationsAutosave() {
  if (!state.spatialRelationsDraft) return;
  if (state.spatialAutosaveTimer) clearTimeout(state.spatialAutosaveTimer);
  setSpatialAutosaveStatus("Saving changes...");
  const requestId = state.spatialAutosaveRequestId + 1;
  state.spatialAutosaveRequestId = requestId;
  state.spatialAutosaveTimer = setTimeout(() => {
    state.spatialAutosaveTimer = null;
    startSpatialRelationsAutosave(requestId).catch(() => {});
  }, 700);
}

function startSpatialRelationsAutosave(requestId) {
  const promise = persistSpatialRelationsDraft(requestId);
  state.spatialAutosavePromise = promise;
  promise.catch((error) => {
    if (requestId === state.spatialAutosaveRequestId) setSpatialAutosaveStatus(`Save failed: ${shortText(error.message, 58)}`);
  }).finally(() => {
    if (state.spatialAutosavePromise === promise) state.spatialAutosavePromise = null;
  });
  return promise;
}

async function persistSpatialRelationsDraft(requestId) {
  const component = spatialRelationsComponent();
  if (!component) return null;
  const optionId = selectedOptionIdForComponent(component);
  if (!optionId) {
    setSpatialAutosaveStatus("Suggested layout unavailable");
    throw new Error("The suggested object layout is unavailable.");
  }
  const decision = await api.post(`/api/decisions/${SPATIAL_RELATIONS_COMPONENT_ID}/draft`, {
    optionId,
    spatialRelations: spatialRelationsForSave(component),
    authorEdits: currentEditNotesValue(),
  });
  if (requestId !== state.spatialAutosaveRequestId) return decision;
  if (!state.data.decisions) state.data.decisions = {};
  state.data.decisions[SPATIAL_RELATIONS_COMPONENT_ID] = decision;
  state.spatialDraftDirty = false;
  if (decision?.current === true && decision?.stale !== true) {
    clearStoryvrCheckpointCompletionPending(SPATIAL_RELATIONS_COMPONENT_ID);
  } else {
    markStoryvrCheckpointCompletionPending(SPATIAL_RELATIONS_COMPONENT_ID);
  }
  setSpatialAutosaveStatus("Changes saved");
  updateCheckpointStatusDom(SPATIAL_RELATIONS_COMPONENT_ID);
  return decision;
}

async function flushSpatialRelationsAutosave() {
  const hadPendingTimer = Boolean(state.spatialAutosaveTimer);
  if (state.spatialAutosaveTimer) {
    clearTimeout(state.spatialAutosaveTimer);
    state.spatialAutosaveTimer = null;
  }
  if (state.spatialAutosavePromise) await state.spatialAutosavePromise;
  if (hadPendingTimer || state.spatialDraftDirty) {
    const requestId = hadPendingTimer ? state.spatialAutosaveRequestId : state.spatialAutosaveRequestId + 1;
    state.spatialAutosaveRequestId = requestId;
    await startSpatialRelationsAutosave(requestId);
    return true;
  }
  return false;
}

function mutateSelectedSpatialRelation(mutator, options = {}) {
  const entities = selectedSpatialRelationEntities();
  if (
    !entities.length
    || entities.some((entity) => !spatialEntityTransformEditable(entity))
    || typeof mutator !== "function"
  ) return false;
  if (options.recordHistory !== false) pushSpatialUndoSnapshot();
  for (const entity of entities) {
    mutator(entity);
    entity.transform = normalizeSpatialTransform(entity.transform, entity.inferredTransform);
    if (spatialEntityType(entity) === "reader") entity.transform.scale = [1, 1, 1];
    updateSpatialEntityManualState(entity, options);
  }
  commitSpatialDraftMutation();
  finalizePersistentAuthorHistory(flushSpatialRelationsAutosave);
  return true;
}

function updateSelectedSpatialTransformField(field, rawValue) {
  const [group, indexText] = String(field || "").split(".");
  const index = Number(indexText);
  const value = Number(rawValue);
  if (!["position", "rotation", "scale"].includes(group) || !Number.isInteger(index) || index < 0 || index > 2 || !Number.isFinite(value)) return;
  const mode = group === "position" ? "translate" : group === "rotation" ? "rotate" : "scale";
  if (!spatialSelectionCanTransform(mode)) return;
  const entities = selectedSpatialRelationEntities();
  if (entities.length > 1) {
    const deltaMatrix = spatialGroupTransformDelta(entities, group, index, value);
    if (!deltaMatrix) return;
    pushSpatialUndoSnapshot();
    applySpatialTransformDeltaToEntities(entities, deltaMatrix);
    commitSpatialDraftMutation();
    finalizePersistentAuthorHistory(flushSpatialRelationsAutosave);
    applySpatialDraftToViewer(textViewer);
    syncSpatialSelectionInViewer();
    return;
  }
  mutateSelectedSpatialRelation((entity) => {
    const transform = normalizeSpatialTransform(entity.transform, entity.inferredTransform);
    if (group === "rotation") {
      const rotation = spatialEulerDegrees(transform.quaternion);
      rotation[index] = value;
      transform.quaternion = new THREE.Quaternion().setFromEuler(new THREE.Euler(...rotation.map(THREE.MathUtils.degToRad), "XYZ")).toArray();
    } else if (group === "scale" && state.spatialScaleRatioLocked) {
      transform.scale = spatialLockedScaleForAxis(transform.scale, index, value);
    } else {
      transform[group][index] = group === "scale" ? Math.max(0.01, value) : value;
    }
    entity.transform = transform;
  });
  applySpatialDraftToViewer(textViewer);
  syncSpatialInspectorFromSelection();
}

function resetSelectedSpatialEntityToInference() {
  mutateSelectedSpatialRelation((entity) => {
    entity.transform = cloneJson(entity.inferredTransform);
    entity.anchor = cloneJson(entity._inferredAnchor || entity.anchor);
    entity.orientationPolicy = entity._inferredOrientationPolicy || entity.orientationPolicy;
  }, { reset: true });
  applySpatialDraftToViewer(textViewer);
  syncSpatialSelectionInViewer();
}

function resetAllSpatialRelationsToInference() {
  if (!state.spatialRelationsDraft) return;
  pushSpatialUndoSnapshot();
  for (const entity of spatialRelationEntities(state.spatialRelationsDraft)) {
    entity.transform = cloneJson(entity.inferredTransform);
    entity.anchor = cloneJson(entity._inferredAnchor || entity.anchor);
    entity.orientationPolicy = entity._inferredOrientationPolicy || entity.orientationPolicy;
    entity.manual = entity.authoredInstance === true;
  }
  commitSpatialDraftMutation();
  finalizePersistentAuthorHistory(flushSpatialRelationsAutosave);
  applySpatialDraftToViewer(textViewer);
  syncSpatialSelectionInViewer();
  renderPreservingScroll();
}

function undoSpatialRelationsEdit() {
  performHistoryAction("undo");
}

function redoSpatialRelationsEdit() {
  performHistoryAction("redo");
}

function textComfortPreviewBeats() {
  return (state.data.graph.beats || [])
    .filter((beat) => String(beat.text || beat.excerpt || beat.title || "").trim())
    .map((beat, index) => ({
      ...beat,
      id: beat.id || `text-beat-${index + 1}`,
      title: beat.title || beat.section || `Story part ${index + 1}`,
      text: beat.text || beat.excerpt || beat.summary || beat.title || "",
      linkedAssetIds: beatAssetIds(beat),
    }));
}

function clampTextBeatIndex(beats) {
  const max = Math.max((beats || []).length - 1, 0);
  if (!Number.isFinite(state.selectedTextBeatIndex)) state.selectedTextBeatIndex = 0;
  state.selectedTextBeatIndex = Math.max(0, Math.min(max, state.selectedTextBeatIndex));
  return state.selectedTextBeatIndex;
}

function textSceneAssetLinks(proposal, beats) {
  const seen = new Set();
  const links = [];
  for (const beat of beats || []) {
    for (const assetId of beat.linkedAssetIds || []) {
      if (seen.has(assetId)) continue;
      seen.add(assetId);
      links.push({ assetId, role: "Beat anchor" });
    }
  }
  for (const assetLink of proposal?.assetLinks || []) {
    if (!assetLink.assetId || seen.has(assetLink.assetId)) continue;
    seen.add(assetLink.assetId);
    links.push(assetLink);
  }
  return links.slice(0, 18);
}

function ensureTextPlacementDraft(proposal, beat = null) {
  const kind = inferTextComfortKind(proposal);
  const mode = textComfortKindLabel(kind);
  const spatialCueContract = sourceSpatialCueContract();
  const dependencyKey = `${mode}:${spatialCueContract.inferredPath ? "camera-path" : "no-camera-path"}:${spatialCueContract.counts?.cues || 0}`;
  const decision = state.data.decisions["text-comfort"];
  const decisionPlacement = decision?.option?.optionId === proposal?.optionId ? decision.textPlacement : null;
  if (!state.textPlacementDraft || state.textPlacementDraft.mode !== mode || state.textPlacementDraft.dependencyKey !== dependencyKey) {
    state.textPlacementDraft = sanitizeTextPlacement(decisionPlacement, kind, beat);
    state.textPlacementDraft.dependencyKey = dependencyKey;
  }
  if (
    kind === "object-attached"
    && !decisionPlacement
    && beat
    && beatAssetIds(beat).length
    && !["asset", "source-focus"].includes(state.textPlacementDraft.globalDefault?.coordinateSpace)
    && !Object.keys(state.textPlacementDraft.overridesByBeat || {}).length
  ) {
    state.textPlacementDraft.globalDefault = defaultTextPlacementForKind(kind, beat);
  }
  return state.textPlacementDraft;
}

function textPlacementForSave(component) {
  const proposal = selectedTopologyProposal(component, state.data.proposals[component.id], state.data.decisions[component.id]);
  const beats = textComfortPreviewBeats(proposal);
  const beat = beats[clampTextBeatIndex(beats)];
  return sanitizeTextPlacement(ensureTextPlacementDraft(proposal, beat), inferTextComfortKind(proposal), beat);
}

function sanitizeTextPlacement(value, kind, beat) {
  const fallback = defaultTextPlacementForKind(kind, beat);
  const source = value && typeof value === "object" ? value : {};
  const globalDefault = sanitizeTextPlacementEntry(source.globalDefault, fallback);
  const overridesByBeat = {};
  for (const [beatId, placement] of Object.entries(source.overridesByBeat || {})) {
    if (!beatId) continue;
    overridesByBeat[beatId] = sanitizeTextPlacementEntry(placement, globalDefault);
  }
  return {
    schemaVersion: "storyvr-text-placement/v2",
    mode: textComfortKindLabel(kind),
    globalDefault,
    overridesByBeat,
  };
}

function sanitizeTextPlacementEntry(value, fallback) {
  const source = value && typeof value === "object" ? value : {};
  const safeNumber = (number, defaultValue, min = -20, max = 20) => {
    const parsed = Number(number);
    if (!Number.isFinite(parsed)) return defaultValue;
    return Math.max(min, Math.min(max, parsed));
  };
  const position = source.position || {};
  const rotation = source.rotation || {};
  const coordinateSpace = ["world", "reader", "asset", "source-focus"].includes(source.coordinateSpace) ? source.coordinateSpace : fallback.coordinateSpace;
  const anchorSource = ["manual", "reader", "active-object", "source-camera-focus"].includes(source.anchorSource)
    ? source.anchorSource
    : fallback.anchorSource || (coordinateSpace === "reader" ? "reader" : coordinateSpace === "asset" ? "active-object" : coordinateSpace === "source-focus" ? "source-camera-focus" : "manual");
  return {
    coordinateSpace,
    position: {
      x: safeNumber(position.x, fallback.position.x),
      y: safeNumber(position.y, fallback.position.y),
      z: safeNumber(position.z, fallback.position.z),
    },
    rotation: {
      x: safeNumber(rotation.x, fallback.rotation.x, -Math.PI * 2, Math.PI * 2),
      y: safeNumber(rotation.y, fallback.rotation.y, -Math.PI * 2, Math.PI * 2),
      z: safeNumber(rotation.z, fallback.rotation.z, -Math.PI * 2, Math.PI * 2),
    },
    scale: safeNumber(source.scale, fallback.scale, 0.25, 3),
    width: safeNumber(source.width, fallback.width, 0.65, 2.8),
    height: safeNumber(source.height, fallback.height, 0.36, 1.6),
    facesReader: Boolean(source.facesReader ?? fallback.facesReader),
    anchorAssetId: typeof source.anchorAssetId === "string" ? source.anchorAssetId : fallback.anchorAssetId,
    anchorSource,
    sourceCueId: typeof source.sourceCueId === "string" ? source.sourceCueId : fallback.sourceCueId || null,
  };
}

function defaultTextPlacementForKind(kind, beat) {
  const activeAssetId = beat ? beatAssetIds(beat)[0] || null : null;
  if (kind === "reader-facing") {
    return textPlacementEntry("world", { x: 0, y: 1.45, z: -1.24 }, { x: 0, y: 0, z: 0 }, true, null);
  }
  if (kind === "near-body") {
    return textPlacementEntry("reader", { x: 0.42, y: 1.12, z: -0.78 }, { x: -0.08, y: -0.25, z: 0 }, true, null);
  }
  if (kind === "object-attached" && activeAssetId) {
    const sourceCue = sourceSpatialCueForBeat(beat?.id, activeAssetId) || sourceSpatialCueForBeat(beat?.id);
    if (sourceCue) {
      return textPlacementEntry("source-focus", { x: 0.42, y: 0.3, z: 0.06 }, { x: 0, y: 0, z: 0 }, true, sourceCue.assetId || activeAssetId, {
        anchorSource: "source-camera-focus",
        sourceCueId: sourceCue.cueId,
      });
    }
    return textPlacementEntry("asset", { x: 0.72, y: 0.72, z: 0.06 }, { x: 0, y: -0.25, z: 0 }, true, activeAssetId, { anchorSource: "active-object" });
  }
  if (kind === "object-attached" && sourceSpatialCueContract().inferredPath) {
    const firstCue = sourceSpatialCueContract().cues?.[0] || null;
    return textPlacementEntry("source-focus", { x: 0.42, y: 0.3, z: 0.06 }, { x: 0, y: 0, z: 0 }, true, firstCue?.assetId || null, {
      anchorSource: "source-camera-focus",
      sourceCueId: null,
    });
  }
  if (kind === "object-attached") {
    return textPlacementEntry("world", { x: 0.75, y: 1.35, z: -1.05 }, { x: 0, y: -0.35, z: 0 }, true, null);
  }
  return textPlacementEntry("world", { x: -1.05, y: 1.48, z: -1.18 }, { x: 0, y: 0.36, z: 0 }, false, null);
}

function textPlacementEntry(coordinateSpace, position, rotation, facesReader, anchorAssetId, extras = {}) {
  return {
    coordinateSpace,
    position,
    rotation,
    scale: 1,
    width: 1.35,
    height: 0.72,
    facesReader,
    anchorAssetId,
    anchorSource: extras.anchorSource || (coordinateSpace === "reader" ? "reader" : coordinateSpace === "asset" ? "active-object" : coordinateSpace === "source-focus" ? "source-camera-focus" : "manual"),
    sourceCueId: extras.sourceCueId || null,
  };
}

function effectiveTextPlacementForBeat(draft, beat, kind) {
  const sanitized = sanitizeTextPlacement(draft, kind, beat);
  return sanitizeTextPlacementEntry(sanitized.overridesByBeat?.[beat?.id], sanitized.globalDefault);
}

function applyTextPlacementAction(action) {
  const component = componentById("text-comfort");
  const proposal = selectedTopologyProposal(component, state.data.proposals[component.id], state.data.decisions[component.id]);
  const kind = inferTextComfortKind(proposal);
  const beats = textComfortPreviewBeats(proposal);
  const beat = beats[clampTextBeatIndex(beats)];
  if (!beat) return;
  const draft = ensureTextPlacementDraft(proposal, beat);
  const current = effectiveTextPlacementForBeat(draft, beat, kind);
  if (action === "reset") {
    delete draft.overridesByBeat[beat.id];
    return;
  }
  if (action === "apply-all") {
    const globalDefault = { ...current, anchorAssetId: ["asset", "source-focus"].includes(current.coordinateSpace) ? null : current.anchorAssetId };
    state.textPlacementDraft = sanitizeTextPlacement({ ...draft, globalDefault, overridesByBeat: {} }, kind, beat);
    return;
  }
  const snapped = textPlacementForSnapAction(action, kind, beat, current);
  if (snapped) draft.overridesByBeat[beat.id] = sanitizeTextPlacementEntry(snapped, current);
}

function textPlacementForSnapAction(action, kind, beat, current) {
  if (action === "snap-left") {
    return { ...current, coordinateSpace: "world", position: { x: -1.25, y: 1.45, z: -1.18 }, rotation: { x: 0, y: 0.34, z: 0 }, facesReader: kind === "reader-facing", anchorSource: "manual", sourceCueId: null };
  }
  if (action === "snap-right") {
    return { ...current, coordinateSpace: "world", position: { x: 1.25, y: 1.45, z: -1.18 }, rotation: { x: 0, y: -0.34, z: 0 }, facesReader: kind === "reader-facing", anchorSource: "manual", sourceCueId: null };
  }
  if (action === "snap-near-body") {
    return { ...current, coordinateSpace: "reader", position: { x: 0.42, y: 1.12, z: -0.78 }, rotation: { x: -0.08, y: -0.25, z: 0 }, facesReader: true, anchorAssetId: null, anchorSource: "reader", sourceCueId: null };
  }
  if (action === "snap-active-object") {
    const assetId = beatAssetIds(beat)[0] || null;
    if (!assetId) return null;
    return { ...current, coordinateSpace: "asset", position: { x: 0.72, y: 0.72, z: 0.06 }, rotation: { x: 0, y: -0.25, z: 0 }, facesReader: true, anchorAssetId: assetId, anchorSource: "active-object", sourceCueId: null };
  }
  return null;
}

function textComfortWarnings(beat, placement) {
  const warnings = [];
  const textLength = String(beat?.text || "").length;
  const distance = Math.hypot(placement.position.x || 0, placement.position.z || 0);
  if (textLength > 520) warnings.push({ severity: "warning", label: "dense text" });
  if (textLength > 320 && placement.width < 1.1) warnings.push({ severity: "warning", label: "panel may be narrow" });
  if (placement.position.y < 0.85) warnings.push({ severity: "warning", label: "low reading height" });
  if (!["asset", "source-focus"].includes(placement.coordinateSpace) && distance < 0.55) warnings.push({ severity: "warning", label: "very close" });
  if (!["asset", "source-focus"].includes(placement.coordinateSpace) && distance > 3.4) warnings.push({ severity: "warning", label: "far from reader" });
  return warnings;
}

function interactionPreviewBeats(proposal) {
  return textComfortPreviewBeats(proposal);
}

function interactionBoundaryId(fromBeatId, toBeatId) {
  return `${String(fromBeatId || "").trim()}->${String(toBeatId || "").trim()}`;
}

function interactionProgressionEdges() {
  return sourceGraphTransitionEdges(state.data?.graph)
    .filter((edge) => sourceGraphIsStoryProgression(edge));
}

function interactionBoundaryControlForEdge(edge, context = null) {
  const boundaryContext = context || interactionBoundaryContext(selectedInteractionControlBase());
  return boundaryContext?.boundaries?.find((boundary) => (
    boundary.edgeId === edge?.id || boundary.boundaryId === edge?.id
  )) || null;
}

function interactionConfigurationTypeForKind(kind) {
  if (kind === "button-step") return "controller-button-press";
  if (kind === "ui-button-press") return "ui-button-press";
  if (kind === "direct") return "direct-manipulation";
  if (kind === "embodied-control") return "reader-locomotion";
  return "";
}

function interactionKindForConfiguration(value) {
  const type = String(value?.type || "").trim();
  if (type === "controller-button-press") return "button-step";
  if (type === "ui-button-press") return "ui-button-press";
  if (type === "direct-manipulation") return "direct";
  if (type === "reader-locomotion") return "embodied-control";
  return null;
}

function interactionControllerProfile(profileId) {
  return INTERACTION_CONTROLLER_PROFILES[profileId]
    || INTERACTION_CONTROLLER_PROFILES["meta-quest-touch-plus"];
}

function interactionControllerInputIsReserved(value) {
  const input = String(value || "").trim().toLowerCase().replace(/[ _]+/g, "-");
  return input === "trigger" || input === "squeeze" || input === "grip" || input === "menu";
}

function interactionReaderTransformForContext(context) {
  const reader = spatialSceneEntities(lockedSpatialRelationsContract(), context)
    .find((entity) => spatialEntityType(entity) === "reader");
  const transform = reader?.transform || reader?.worldTransform || reader?.pose || reader?.inferredTransform;
  return transform ? normalizeSpatialTransform(transform) : null;
}

function interactionInBeatSceneKey(context) {
  const beatId = String(context?.beatId || "").trim();
  if (!beatId) return "";
  const variantOptionId = String(context?.variantOptionId || "").trim();
  if (!variantOptionId) return `beat:${beatId}`;
  const variantGroupId = String(context?.variantGroupId || "").trim();
  if (!variantGroupId) return "";
  return `beat:${beatId}:group:${variantGroupId}:variant:${variantOptionId}`;
}

function interactionInBeatSceneMatches(record, context) {
  if (!record || !context?.beatId || String(record.beatId || "") !== String(context.beatId)) return false;
  const recordOptionId = String(record.variantOptionId || "");
  const contextOptionId = String(context.variantOptionId || "");
  if (recordOptionId !== contextOptionId) return false;
  if (!recordOptionId) return true;
  const recordGroupId = String(record.variantGroupId || "");
  const contextGroupId = String(context.variantGroupId || "");
  return Boolean(recordGroupId && contextGroupId && recordGroupId === contextGroupId);
}

function interactionInBeatTargetKey(target) {
  if (!target || typeof target !== "object") return "";
  const entityId = String(target.entityId || "");
  if (Number.isSafeInteger(Number(target.nodeIndex)) && Number(target.nodeIndex) >= 0) {
    return `${entityId}|node:${Number(target.nodeIndex)}`;
  }
  const nodePath = String(target.nodePath || "").trim();
  return `${entityId}|${nodePath ? `path:${nodePath}` : "whole"}`;
}

function interactionInBeatFiniteArray(value, fallback, min, max) {
  return [0, 1, 2].map((index) => interactionFiniteNumber(value?.[index], fallback[index], min, max));
}

function interactionInBeatOrderedRange(minValues, maxValues) {
  return {
    min: minValues.map((value, index) => Math.min(value, maxValues[index])),
    max: maxValues.map((value, index) => Math.max(value, minValues[index])),
  };
}

function normalizeInteractionInBeatConstraints(value, initialTransform) {
  const source = value && typeof value === "object" && !Array.isArray(value) ? value : {};
  const constraints = {};
  if (source.position && typeof source.position === "object") {
    constraints.position = interactionInBeatOrderedRange(
      interactionInBeatFiniteArray(source.position.min, initialTransform.position, -1000, 1000),
      interactionInBeatFiniteArray(source.position.max, initialTransform.position, -1000, 1000),
    );
  }
  if (source.rotation && typeof source.rotation === "object") {
    const initialEuler = interactionTransformEulerDegrees(initialTransform);
    const range = interactionInBeatOrderedRange(
      interactionInBeatFiniteArray(source.rotation.minDegrees || source.rotation.min, initialEuler, -360, 360),
      interactionInBeatFiniteArray(source.rotation.maxDegrees || source.rotation.max, initialEuler, -360, 360),
    );
    constraints.rotation = { minDegrees: range.min, maxDegrees: range.max };
  }
  if (source.scale && typeof source.scale === "object") {
    constraints.scale = interactionInBeatOrderedRange(
      interactionInBeatFiniteArray(source.scale.min, initialTransform.scale, 0.001, 100),
      interactionInBeatFiniteArray(source.scale.max, initialTransform.scale, 0.001, 100),
    );
  }
  return constraints;
}

function normalizeInteractionInBeatTarget(value) {
  if (!value || typeof value !== "object") return null;
  const entityId = String(value.entityId || "").trim();
  const assetId = String(value.assetId || "").trim();
  const oneHandGrabbable = value.oneHandGrabbable === true;
  const twoHandScalable = value.twoHandScalable === true;
  if (!entityId || !assetId || (!oneHandGrabbable && !twoHandScalable)) return null;
  const elasticDragging = oneHandGrabbable && value.elasticDragging === true;
  const initialTransform = normalizeSpatialTransform(value.initialTransform);
  const nodeIndex = Number(value.nodeIndex);
  const target = {
    entityId,
    assetId,
    ...(String(value.nodePath || "").trim() ? { nodePath: String(value.nodePath).trim() } : {}),
    ...(Number.isSafeInteger(nodeIndex) && nodeIndex >= 0 ? { nodeIndex } : {}),
    coordinateSpace: "local",
    oneHandGrabbable,
    twoHandScalable,
    ...(elasticDragging ? { elasticDragging: true } : {}),
    initialTransform,
  };
  const constraints = normalizeInteractionInBeatConstraints(value.constraints, initialTransform);
  if (oneHandGrabbable && constraints.position) {
    target.constraints ||= {};
    target.constraints.position = constraints.position;
  }
  if (oneHandGrabbable && constraints.rotation) {
    target.constraints ||= {};
    target.constraints.rotation = constraints.rotation;
  }
  if (twoHandScalable && constraints.scale) {
    target.constraints ||= {};
    target.constraints.scale = constraints.scale;
  }
  return target;
}

function interactionInBeatTargetsWithoutOverlap(values) {
  const byKey = new Map();
  for (const value of values || []) {
    const target = normalizeInteractionInBeatTarget(value);
    if (target) byKey.set(interactionInBeatTargetKey(target), target);
  }
  const targets = [...byKey.values()];
  const entitiesWithParts = new Set(targets.filter((target) => target.nodePath || target.nodeIndex != null).map((target) => target.entityId));
  const withoutWholeOverlaps = targets.filter((target) => target.nodePath || target.nodeIndex != null || !entitiesWithParts.has(target.entityId));
  return withoutWholeOverlaps.filter((target, index, all) => {
    if (!target.nodePath) return true;
    return !all.some((other, otherIndex) => (
      otherIndex !== index
      && other.entityId === target.entityId
      && other.nodePath
      && other.nodePath.startsWith(`${target.nodePath}/`)
    ));
  });
}

function normalizeInteractionInBeatRecord(value) {
  if (!value || typeof value !== "object") return null;
  const beatId = String(value.beatId || "").trim();
  if (!beatId) return null;
  const variantGroupId = String(value.variantGroupId || "").trim();
  const variantOptionId = String(value.variantOptionId || "").trim();
  if (variantOptionId && !variantGroupId) return null;
  const context = { beatId, ...(variantOptionId ? { variantGroupId, variantOptionId } : {}) };
  const targets = interactionInBeatTargetsWithoutOverlap(value.targets).slice(0, 128);
  return {
    sceneKey: interactionInBeatSceneKey(context),
    beatId,
    ...(variantOptionId ? { variantGroupId, variantOptionId } : {}),
    targets,
  };
}

function normalizeInteractionInBeatInteractions(value) {
  const recordsByKey = new Map();
  for (const item of Array.isArray(value) ? value : []) {
    const record = normalizeInteractionInBeatRecord(item);
    if (record) recordsByKey.set(record.sceneKey, record);
  }
  return [...recordsByKey.values()].sort((left, right) => left.sceneKey.localeCompare(right.sceneKey));
}

function savedInteractionInBeatInteractions(decision) {
  return normalizeInteractionInBeatInteractions(decision?.inBeatInteractions);
}

function ensureInteractionInBeatInteractions() {
  if (state.interactionInBeatInteractionsInitialized) return state.interactionInBeatInteractions;
  state.interactionInBeatInteractions = savedInteractionInBeatInteractions(state.data?.decisions?.["interaction-control"]);
  state.interactionInBeatInteractionsInitialized = true;
  return state.interactionInBeatInteractions;
}

function interactionInBeatInteractionsPayload() {
  return normalizeInteractionInBeatInteractions(ensureInteractionInBeatInteractions())
    .filter((record) => record.targets.length > 0);
}

function interactionInBeatInteractionsSignature(value) {
  return JSON.stringify(normalizeInteractionInBeatInteractions(value).map((record) => ({
    ...record,
    targets: [...record.targets].sort((left, right) => interactionInBeatTargetKey(left).localeCompare(interactionInBeatTargetKey(right))),
  })));
}

function resetInteractionControlDraftCaches() {
  state.interactionControllerConfiguration = null;
  state.interactionControllerConfigurationInitialized = false;
  state.interactionBoundaryOverrides = {};
  state.interactionBoundaryOverridesInitialized = false;
  state.interactionBoundaryOverrideResets.clear();
  state.interactionVariantEdgeOverrides = {};
  state.interactionVariantEdgeOverridesInitialized = false;
  state.interactionInBeatInteractions = [];
  state.interactionInBeatInteractionsInitialized = false;
}

function interactionInBeatRecordForContext(context, { create = false } = {}) {
  const records = ensureInteractionInBeatInteractions();
  let record = records.find((candidate) => interactionInBeatSceneMatches(candidate, context)) || null;
  if (!record && create && context?.beatId) {
    record = normalizeInteractionInBeatRecord({
      beatId: context.beatId,
      ...(context.variantOptionId ? {
        variantGroupId: context.variantGroupId,
        variantOptionId: context.variantOptionId,
      } : {}),
      targets: [],
    });
    records.push(record);
  }
  return record;
}

function interactionInBeatTargetsForContext(context) {
  return interactionInBeatRecordForContext(context)?.targets || [];
}

function mutateInteractionInBeatRecord(context, mutate) {
  const record = interactionInBeatRecordForContext(context, { create: true });
  if (!record) return false;
  const before = interactionInBeatInteractionsSignature(ensureInteractionInBeatInteractions());
  mutate(record);
  record.targets = interactionInBeatTargetsWithoutOverlap(record.targets);
  state.interactionInBeatInteractions = normalizeInteractionInBeatInteractions(
    ensureInteractionInBeatInteractions().filter((candidate) => candidate.targets.length > 0 || candidate === record),
  );
  return before !== interactionInBeatInteractionsSignature(state.interactionInBeatInteractions);
}

function interactionSceneHasInteractables(context) {
  return interactionInBeatTargetsForContext(context).some((target) => target.oneHandGrabbable || target.twoHandScalable);
}

function interactionBoundaryDirectManipulationAvailable(boundaryId) {
  const boundary = interactionBoundaryContext().boundaries.find((candidate) => candidate.boundaryId === boundaryId);
  const context = boundary
    ? normalizeMotionSceneContext(boundary.fromContext, boundary.fromBeatId) || interactionSceneContextForBeat(boundary.fromBeatId)
    : null;
  return interactionSceneHasInteractables(context);
}

function interactionVariantDirectManipulationAvailable(edgeId) {
  const edge = interactionVariantSwitchEdges().find((candidate) => candidate.id === edgeId);
  return Boolean(edge && interactionSceneHasInteractables(
    spatialSceneContext(edge.from.beatId, edge.from.variantGroupId, edge.from.variantOptionId),
  ));
}

function interactionDirectSceneTargets(context) {
  const entities = new Map(spatialEditorSceneEntities(lockedSpatialRelationsContract(), context)
    .filter((entity) => spatialEntityType(entity) === "glb")
    .map((entity) => [String(entity.id), entity]));
  return interactionInBeatTargetsForContext(context).map((target) => {
    const entity = entities.get(target.entityId);
    return {
      entityId: target.entityId,
      assetId: target.assetId,
      ...(target.nodePath ? { nodePath: target.nodePath } : {}),
      ...(target.nodeIndex != null ? { nodeIndex: target.nodeIndex } : {}),
      coordinateSpace: "local",
      oneHandGrabbable: target.oneHandGrabbable,
      twoHandScalable: target.twoHandScalable,
      ...(target.elasticDragging ? { elasticDragging: true } : {}),
      constraints: cloneJson(target.constraints || {}),
      label: entity ? spatialRelationEntityLabel(entity) : target.assetId,
      sourceTransform: cloneJson(target.initialTransform),
    };
  });
}

function interactionDirectTargetKey(target) {
  if (!target || typeof target !== "object") return "";
  return interactionInBeatTargetKey(target);
}

function defaultInteractionControllerAction(hand, input) {
  if (hand === "right" && input === "a") return "next-beat";
  if (hand === "left" && input === "x") return "previous-beat";
  if (hand === "left" && input === "thumbstick-up") return "move-forward";
  if (hand === "left" && input === "thumbstick-down") return "move-backward";
  if (hand === "left" && input === "thumbstick-left") return "strafe-left";
  if (hand === "left" && input === "thumbstick-right") return "strafe-right";
  if (hand === "right" && input === "thumbstick-up") return "teleport";
  if (hand === "right" && input === "thumbstick-down") return "turn-back";
  if (hand === "right" && input === "thumbstick-left") return "turn-left";
  if (hand === "right" && input === "thumbstick-right") return "turn-right";
  return "unmapped";
}

function interactionDefaultConfiguration(kind, context = {}) {
  if (kind === "button-step") {
    const profile = interactionControllerProfile(context.profile);
    const bindings = profile.hands.flatMap((hand) => hand.inputs.map((input) => ({
      hand: hand.id,
      input: input.id,
      action: defaultInteractionControllerAction(hand.id, input.id),
    })));
    return {
      schemaVersion: INTERACTION_CONTROLLER_CONFIGURATION_SCHEMA,
      type: "controller-button-press",
      profile: profile.id,
      bindings,
    };
  }
  if (kind === "ui-button-press") {
    const edge = context.edge || null;
    const targetLabel = edge ? storyVariantEndpointLabel(edge.to) : "Continue";
    const defaultPosition = context.variantDirection === "previous"
      ? [0.2, TEXT_PANEL_ACTION_CENTER_Y]
      : context.variantDirection === "next"
        ? [0.8, TEXT_PANEL_ACTION_CENTER_Y]
        : [0.5, TEXT_PANEL_ACTION_CENTER_Y];
    return {
      schemaVersion: INTERACTION_CONFIGURATION_SCHEMA,
      type: "ui-button-press",
      buttons: [{
        id: edge?.id || "continue",
        label: targetLabel,
        action: edge ? "select-variant" : "next-beat",
        position: defaultPosition,
        size: [0.32, TEXT_PANEL_ACTION_MAX_HEIGHT],
      }],
    };
  }
  if (kind === "embodied-control") {
    const targetContext = context.targetSceneContext
      || interactionSceneContextForBeat(context.boundary?.toBeatId || context.edge?.to?.beatId);
    const targetTransform = interactionReaderTransformForContext(targetContext);
    return {
      schemaVersion: INTERACTION_CONFIGURATION_SCHEMA,
      type: "reader-locomotion",
      destination: {
        coordinateSpace: targetTransform ? "world" : "reader-start",
        transform: targetTransform || {
          position: [0, 0, -1.5],
          quaternion: [0, 0, 0, 1],
          scale: [1, 1, 1],
        },
      },
      tolerance: {
        distanceMeters: 0.68,
        dwellSeconds: 1.25,
      },
    };
  }
  return {
    schemaVersion: INTERACTION_CONFIGURATION_SCHEMA,
    type: "direct-manipulation",
    targets: [],
    tolerance: {
      positionMeters: 0.12,
      rotationDegrees: 12,
      scaleRatio: 0.12,
    },
    completion: "all",
  };
}

function interactionFiniteNumber(value, fallback, min, max) {
  const number = Number(value);
  return Math.max(min, Math.min(max, Number.isFinite(number) ? number : fallback));
}

function normalizeInteractionConfiguration(value, kind, context = {}) {
  const defaults = interactionDefaultConfiguration(kind, context);
  const source = value && typeof value === "object" && interactionKindForConfiguration(value) === kind
    ? value
    : {};
  if (kind === "button-step") {
    const profile = interactionControllerProfile(source.profile || defaults.profile);
    const supplied = new Map((Array.isArray(source.bindings) ? source.bindings : [])
      .filter((binding) => !interactionControllerInputIsReserved(binding?.input || binding?.control || binding?.button))
      .map((binding) => [`${binding?.hand}:${binding?.input}`, binding]));
    const migrateV2RightStickDefaults = source.schemaVersion === INTERACTION_CONTROLLER_CONFIGURATION_SCHEMA_V2;
    const migrateLegacyDirectionalDefaults = source.schemaVersion !== INTERACTION_CONTROLLER_CONFIGURATION_SCHEMA
      && !migrateV2RightStickDefaults;
    const bindings = profile.hands.flatMap((hand) => hand.inputs.map((input) => {
      const fallback = defaults.bindings.find((binding) => binding.hand === hand.id && binding.input === input.id);
      const suppliedBinding = supplied.get(`${hand.id}:${input.id}`);
      const replaceLegacyDefault = (
        migrateLegacyDirectionalDefaults
        && INTERACTION_DIRECTIONAL_THUMBSTICK_INPUTS.has(input.id)
        && (!suppliedBinding || suppliedBinding.action === "unmapped")
      ) || (
        migrateV2RightStickDefaults
        && hand.id === "right"
        && (input.id === "thumbstick-up" || input.id === "thumbstick-down")
        && (!suppliedBinding || suppliedBinding.action === "unmapped")
      );
      const binding = replaceLegacyDefault
        ? fallback
        : suppliedBinding || fallback;
      const action = INTERACTION_ACTION_OPTIONS.some((option) => option.id === binding?.action)
        && interactionControllerActionAvailable(input.id, binding?.action)
        ? binding.action
        : "unmapped";
      return {
        hand: hand.id,
        input: input.id,
        action,
      };
    }));
    return { ...defaults, profile: profile.id, bindings };
  }
  if (kind === "ui-button-press") {
    const fallbackButtons = defaults.buttons;
    const buttons = (Array.isArray(source.buttons) && source.buttons.length ? source.buttons : fallbackButtons)
      .slice(0, 8)
      .map((button, index) => {
        const fallback = fallbackButtons[index] || fallbackButtons[0];
        const presentation = normalizeTextPanelActionPresentation(button, {
          fallbackLabel: fallback.label || "Continue",
          fallbackPosition: fallback.position,
          fallbackSize: fallback.size,
        });
        return {
          id: String(button?.id || fallback.id || `button-${index + 1}`).trim(),
          label: presentation.label,
          action: String(button?.action || fallback.action || "next-beat").trim(),
          position: presentation.position,
          size: presentation.size,
        };
      });
    return { ...defaults, buttons };
  }
  if (kind === "embodied-control") {
    return {
      ...defaults,
      destination: {
        coordinateSpace: String(source.destination?.coordinateSpace || defaults.destination.coordinateSpace),
        transform: normalizeSpatialTransform(source.destination?.transform, defaults.destination.transform),
      },
      tolerance: {
        distanceMeters: interactionFiniteNumber(source.tolerance?.distanceMeters, defaults.tolerance.distanceMeters, 0.1, 5),
        dwellSeconds: interactionFiniteNumber(source.tolerance?.dwellSeconds, defaults.tolerance.dwellSeconds, 0, 10),
      },
    };
  }
  const available = new Map(interactionDirectSceneTargets(context.sceneContext).map((target) => [interactionDirectTargetKey(target), target]));
  const normalizedTargets = (Array.isArray(source.targets) ? source.targets : defaults.targets)
    .filter((target) => target?.entityId)
    .slice(0, 32)
    .flatMap((target) => {
      const sceneTarget = available.get(interactionDirectTargetKey(target));
      if (!sceneTarget) return [];
      const sourceTransform = normalizeSpatialTransform(sceneTarget.sourceTransform);
      const destinationTransform = normalizeSpatialTransform(target.destinationTransform, sourceTransform);
      const triggerComponents = interactionDirectTriggerComponents({
        ...sceneTarget,
        triggerComponents: target.triggerComponents,
      });
      if (!triggerComponents.includes("position")) {
        destinationTransform.position = cloneJson(sourceTransform.position);
      }
      if (!triggerComponents.includes("rotation")) {
        destinationTransform.quaternion = cloneJson(sourceTransform.quaternion);
      }
      if (!triggerComponents.includes("scale")) destinationTransform.scale = cloneJson(sourceTransform.scale);
      return {
        entityId: sceneTarget.entityId,
        assetId: sceneTarget.assetId,
        ...(sceneTarget.nodePath ? { nodePath: sceneTarget.nodePath } : {}),
        ...(sceneTarget.nodeIndex != null ? { nodeIndex: sceneTarget.nodeIndex } : {}),
        coordinateSpace: "local",
        oneHandGrabbable: sceneTarget.oneHandGrabbable,
        twoHandScalable: sceneTarget.twoHandScalable,
        ...(sceneTarget.elasticDragging ? { elasticDragging: true } : {}),
        triggerComponents,
        initialTransform: sourceTransform,
        constraints: cloneJson(sceneTarget.constraints || {}),
        destinationTransform,
        destinationAuthored: target.destinationAuthored !== false,
        suggested: target.suggested === true,
        source: String(target.source || (target.suggested ? "transition" : "author")),
      };
    });
  const targetsByKey = new Map(normalizedTargets.map((target) => [interactionDirectTargetKey(target), target]));
  const entitiesWithPartTargets = new Set(normalizedTargets.filter((target) => target.nodePath || target.nodeIndex != null).map((target) => target.entityId));
  const targets = [...targetsByKey.values()].filter((target) => target.nodePath || target.nodeIndex != null || !entitiesWithPartTargets.has(target.entityId));
  return {
    ...defaults,
    targets,
    tolerance: {
      positionMeters: interactionFiniteNumber(source.tolerance?.positionMeters, defaults.tolerance.positionMeters, 0.01, 2),
      rotationDegrees: interactionFiniteNumber(source.tolerance?.rotationDegrees, defaults.tolerance.rotationDegrees, 0.5, 180),
      scaleRatio: interactionFiniteNumber(source.tolerance?.scaleRatio, defaults.tolerance.scaleRatio, 0.01, 1),
    },
    completion: "all",
  };
}

function interactionConfigurationContext({ boundary = null, edge = null, sceneContext = null } = {}) {
  const group = edge
    ? (state.data?.graph?.variantGroups || []).find((candidate) => candidate.id === edge.from?.variantGroupId)
    : null;
  const displayedOptions = group ? sourceGraphDisplayedVariantOptions(group) : [];
  const fromIndex = displayedOptions.findIndex((option) => option.id === edge?.from?.variantOptionId);
  const toIndex = displayedOptions.findIndex((option) => option.id === edge?.to?.variantOptionId);
  const variantDirection = !edge || fromIndex < 0 || toIndex < 0
    ? null
    : toIndex === fromIndex - 1
      ? "previous"
      : toIndex === fromIndex + 1
        ? "next"
        : fromIndex === 0 && toIndex === displayedOptions.length - 1
          ? "previous"
          : fromIndex === displayedOptions.length - 1 && toIndex === 0
            ? "next"
            : toIndex < fromIndex ? "previous" : "next";
  return {
    boundary,
    edge,
    variantDirection,
    sceneContext: sceneContext || (boundary
      ? normalizeMotionSceneContext(boundary.fromContext, boundary.fromBeatId) || interactionSceneContextForBeat(boundary.fromBeatId)
      : edge
        ? spatialSceneContext(edge.from.beatId, edge.from.variantGroupId, edge.from.variantOptionId)
        : null),
    targetSceneContext: boundary
      ? normalizeMotionSceneContext(boundary.toContext, boundary.toBeatId) || interactionSceneContextForBeat(boundary.toBeatId)
      : edge
        ? spatialSceneContext(edge.to.beatId, edge.to.variantGroupId, edge.to.variantOptionId)
        : null,
  };
}

function variantInteractionPolicyKind(value) {
  const label = String(value || "").toLowerCase().trim();
  if (["ui-button-press", "ui button press", "text panel selection"].includes(label)) return "ui-button-press";
  if (["direct", "direct manipulation"].includes(label)) return "direct";
  if (["embodied-control", "reader locomotion", "embodied progression"].includes(label)) return "embodied-control";
  return null;
}

function variantInteractionPolicyLabel(value) {
  const kind = variantInteractionPolicyKind(value);
  if (kind === "direct") return "Direct manipulation";
  if (kind === "embodied-control") return "Reader locomotion";
  return "UI button press";
}

function interactionVariantSwitchEdges() {
  return sourceGraphTransitionEdges(state.data?.graph)
    .filter((edge) => sourceGraphIsManualVariantSwitch(edge));
}

function normalizeInteractionVariantOverride(value, edge = null) {
  if (!value) return null;
  const rawPolicy = typeof value === "string"
    ? value
    : value.policy || value.effectivePolicy;
  const kind = variantInteractionPolicyKind(rawPolicy);
  if (!kind) return null;
  const context = interactionConfigurationContext({ edge });
  return {
    policy: variantInteractionPolicyLabel(kind),
    ...(typeof value === "object" && value.configuration
      ? { configuration: normalizeInteractionConfiguration(value.configuration, kind, context) }
      : {}),
  };
}

function savedInteractionVariantOverrides(decision) {
  const overrides = {};
  const saved = decision?.variantOverrides || decision?.variantEdgeOverrides || {};
  for (const [edgeId, value] of Object.entries(saved)) {
    const edge = interactionVariantSwitchEdges().find((candidate) => candidate.id === edgeId);
    const normalized = normalizeInteractionVariantOverride(value, edge);
    if (normalized) overrides[edgeId] = normalized;
  }
  for (const record of decision?.variantInteractionControlByEdge || []) {
    if (!record?.overridden || !record?.edgeId) continue;
    const edge = interactionVariantSwitchEdges().find((candidate) => candidate.id === record.edgeId);
    const normalized = normalizeInteractionVariantOverride({
      policy: record.effectivePolicy,
      configuration: record.configuration,
    }, edge);
    if (normalized) overrides[record.edgeId] = normalized;
  }
  return overrides;
}

function interactionVariantOverridesSignature(overrides) {
  return JSON.stringify(Object.entries(overrides || {})
    .map(([edgeId, value]) => {
      const edge = interactionVariantSwitchEdges().find((candidate) => candidate.id === edgeId);
      return [edgeId, normalizeInteractionVariantOverride(value, edge)];
    })
    .filter(([, value]) => value?.policy)
    .map(([edgeId, value]) => [edgeId, {
      policy: value.policy,
      ...(value.configuration ? { configuration: value.configuration } : {}),
    }])
    .sort(([left], [right]) => left.localeCompare(right)));
}

function ensureInteractionVariantOverrides() {
  if (state.interactionVariantEdgeOverridesInitialized) return state.interactionVariantEdgeOverrides;
  state.interactionVariantEdgeOverrides = savedInteractionVariantOverrides(
    state.data?.decisions?.["interaction-control"],
  );
  state.interactionVariantEdgeOverridesInitialized = true;
  return state.interactionVariantEdgeOverrides;
}

function interactionVariantOverridesPayload() {
  const validEdgeIds = new Set(interactionVariantSwitchEdges().map((edge) => edge.id));
  return Object.fromEntries(Object.entries(ensureInteractionVariantOverrides())
    .filter(([edgeId, value]) => validEdgeIds.has(edgeId) && value?.policy)
    .map(([edgeId, value]) => {
      const edge = interactionVariantSwitchEdges().find((candidate) => candidate.id === edgeId);
      const kind = variantInteractionPolicyKind(value.policy);
      const normalized = normalizeInteractionVariantOverride(value, edge);
      return [edgeId, {
        policy: variantInteractionPolicyLabel(kind),
        ...(normalized?.configuration ? { configuration: normalized.configuration } : {}),
      }];
    }));
}

function interactionVariantEdgeControlForEdge(edge) {
  const override = ensureInteractionVariantOverrides()[edge?.id] || null;
  const effectivePolicy = override?.policy || "UI button press";
  const kind = variantInteractionPolicyKind(effectivePolicy);
  const configurationContext = interactionConfigurationContext({ edge });
  return {
    edgeId: edge?.id || "",
    beatId: edge?.from?.beatId || edge?.to?.beatId || "",
    variantGroupId: edge?.from?.variantGroupId || edge?.to?.variantGroupId || "",
    fromVariantOptionId: edge?.from?.variantOptionId || "",
    toVariantOptionId: edge?.to?.variantOptionId || "",
    variantDirection: configurationContext.variantDirection,
    defaultPolicy: "UI button press",
    inferredPolicy: "UI button press",
    effectivePolicy,
    overridden: Boolean(override),
    authored: Boolean(override),
    configuration: normalizeInteractionConfiguration(
      override?.configuration,
      kind,
      configurationContext,
    ),
    surface: "text-panel",
    selectionMode: "previous-next",
  };
}

function setInteractionVariantPolicy(edgeId, policyKind, options = {}) {
  const edge = interactionVariantSwitchEdges().find((candidate) => candidate.id === edgeId);
  const kind = variantInteractionPolicyKind(policyKind);
  if (!edge || !kind) return;
  if (kind === "direct" && !interactionVariantDirectManipulationAvailable(edgeId)) return;
  const overrides = ensureInteractionVariantOverrides();
  const policy = variantInteractionPolicyLabel(kind);
  const existing = overrides[edgeId];
  const configuration = normalizeInteractionConfiguration(
    existing?.configuration,
    kind,
    interactionConfigurationContext({ edge }),
  );
  if (policy === "UI button press" && !options.retainConfiguration && !existing?.configuration) {
    delete overrides[edgeId];
  } else {
    overrides[edgeId] = { policy, configuration };
  }
}

function canonicalInteractionPolicy(value) {
  const kind = ["button-step", "direct", "embodied-control", "branching-control"].includes(value)
    ? value
    : inferInteractionControlKind({ label: value });
  return interactionControlKindLabel(kind);
}

function recognizedInteractionPolicyKind(value) {
  const label = String(value || "").toLowerCase().trim();
  if (["button-step", "controller button press", "controller press", "button stepping"].includes(label)) return "button-step";
  if (["direct", "direct manipulation"].includes(label)) return "direct";
  if (["embodied-control", "reader locomotion", "embodied progression"].includes(label)) return "embodied-control";
  if (["branching-control", "branching selection"].includes(label)) return "branching-control";
  return null;
}

function interactionBoundaryRecordIsCurrent(record, edge) {
  const fromBeatId = edge?.from?.beatId;
  const toBeatId = edge?.to?.beatId;
  if (!record || record.fromBeatId !== fromBeatId || record.toBeatId !== toBeatId) return false;
  if (record.edgeId && record.edgeId !== edge.id) return false;
  const fromContext = sourceGraphTransitionSceneContext(edge.from);
  const toContext = sourceGraphTransitionSceneContext(edge.to);
  if (record.fromContext && !sourceGraphTransitionContextMatches(record.fromContext, fromContext)) return false;
  if (record.toContext && !sourceGraphTransitionContextMatches(record.toContext, toContext)) return false;
  const mappedTransition = record.mappedTransition === true || record.assignmentRequired === true;
  const defaultPolicy = record.defaultPolicy ?? record.inferredPolicy;
  if (defaultPolicy && !recognizedInteractionPolicyKind(defaultPolicy)) return false;
  if (!mappedTransition && recognizedInteractionPolicyKind(defaultPolicy) !== "button-step") return false;
  if (record.effectivePolicy && !recognizedInteractionPolicyKind(record.effectivePolicy)) return false;
  if (record.overridden && !recognizedInteractionPolicyKind(record.effectivePolicy)) return false;
  return true;
}

function interactionControlBoundaryRecords() {
  const decision = state.data?.decisions?.["interaction-control"];
  const draft = state.data?.interactionControlDraft;
  const sources = [
    decision?.interactionControlByBoundary,
    decision?.interactionControlByRoute,
    draft?.interactionControlByBoundary,
    draft?.interactionControlByRoute,
  ];
  const records = new Map();
  for (const source of sources) {
    if (!Array.isArray(source)) continue;
    for (const record of source) {
      const fromBeatId = record?.fromBeatId || record?.from?.id;
      const toBeatId = record?.toBeatId || record?.to?.id;
      const boundaryId = record?.boundaryId || record?.edgeId || interactionBoundaryId(fromBeatId, toBeatId);
      if (!boundaryId || !fromBeatId || !toBeatId) continue;
      const previous = records.get(boundaryId) || {};
      records.set(boundaryId, {
        ...previous,
        ...record,
        boundaryId,
        fromBeatId,
        toBeatId,
        defaultReason: record.overridden
          ? previous.defaultReason || ""
          : record.reason || previous.defaultReason || "",
      });
    }
  }
  return records;
}

function interactionVariantControlRecords() {
  const decision = state.data?.decisions?.["interaction-control"];
  const draft = state.data?.interactionControlDraft;
  const sources = [
    decision?.variantInteractionControlByBeat,
    draft?.variantInteractionControlByBeat,
  ];
  const records = new Map();
  for (const source of sources) {
    if (!Array.isArray(source)) continue;
    for (const record of source) {
      const beatId = String(record?.beatId || "").trim();
      const variantGroupId = String(record?.variantGroupId || "").trim();
      if (!beatId || !variantGroupId) continue;
      records.set(variantGroupId, {
        ...(records.get(variantGroupId) || {}),
        ...record,
        beatId,
        variantGroupId,
      });
    }
  }
  return records;
}

function interactionVariantControlForBeat(beat, records) {
  const group = variantGroupForBeat(beat);
  if (!group) return null;
  const record = records.get(group.id)
    || [...records.values()].find((candidate) => candidate.beatId === beat.id)
    || null;
  const supportedPolicy = record?.effectivePolicy === "UI button press"
    || record?.effectivePolicy === "Text panel selection";
  const valid = record
    && record.beatId === beat.id
    && record.variantGroupId === group.id
    && supportedPolicy
    && record.surface === "text-panel";
  if (!valid) {
    return {
      beatId: beat.id,
      variantGroupId: group.id,
      configurationAvailable: true,
      inferredPolicy: "UI button press",
      effectivePolicy: "UI button press",
      surface: "text-panel",
      selectionMode: "previous-next",
      sourceControlKind: group.control?.kind || "variant",
      previousLabel: group.control?.previousLabel || "Previous",
      nextLabel: group.control?.nextLabel || "Next",
      wrap: group.control?.wrap !== false,
      optionIds: group.options.map((option) => option.id),
      reason: `This story part contains ${group.options.length} choices. Previous and Next buttons on the text panel let the reader change the choice without leaving the active story part.`,
    };
  }
  return {
    ...record,
    configurationAvailable: true,
    inferredPolicy: "UI button press",
    effectivePolicy: "UI button press",
    surface: "text-panel",
    selectionMode: "previous-next",
    previousLabel: record.previousLabel || group.control?.previousLabel || "Previous",
    nextLabel: record.nextLabel || group.control?.nextLabel || "Next",
    wrap: record.wrap ?? (group.control?.wrap !== false),
    optionIds: group.options.map((option) => option.id),
    reason: `This story part contains ${group.options.length} choices. Previous and Next buttons on the text panel let the reader change the choice without leaving the active story part.`,
  };
}

function normalizeInteractionBoundaryOverride(value, boundary = null) {
  if (!value) return null;
  const kind = recognizedInteractionPolicyKind(typeof value === "string" ? value : value.policy || value.effectivePolicy);
  if (!kind) return null;
  const policy = interactionControlKindLabel(kind);
  return {
    policy,
    ...(typeof value === "object" && value.locomotionMode
      ? { locomotionMode: normalizeInteractionLocomotionMode(value.locomotionMode) }
      : {}),
    ...(kind !== "button-step" && typeof value === "object" && value.configuration
      ? {
          configuration: normalizeInteractionConfiguration(
            value.configuration,
            kind,
            interactionConfigurationContext({ boundary }),
          ),
        }
      : {}),
  };
}

function interactionDecisionBoundaryRecords(source) {
  if (!source || typeof source !== "object") return [];
  const boundaryRecords = Array.isArray(source.interactionControlByBoundary)
    ? source.interactionControlByBoundary
    : [];
  if (boundaryRecords.length) return boundaryRecords;
  return Array.isArray(source.interactionControlByRoute)
    ? source.interactionControlByRoute
    : boundaryRecords;
}

function interactionControllerConfigurationCandidate(source) {
  if (!source || typeof source !== "object") return null;
  if (source.controllerConfiguration) return source.controllerConfiguration;
  const overrides = Object.values(source.boundaryOverrides || {});
  const authoredOverride = overrides.find((value) => (
    recognizedInteractionPolicyKind(value?.policy || value?.effectivePolicy) === "button-step"
    && value?.configuration
  ));
  if (authoredOverride) return authoredOverride.configuration;
  const records = interactionDecisionBoundaryRecords(source);
  const authoredRecord = records.find((record) => (
    record?.overridden
    && recognizedInteractionPolicyKind(record.effectivePolicy) === "button-step"
    && record.configuration
  ));
  if (authoredRecord) return authoredRecord.configuration;
  return records.find((record) => (
    recognizedInteractionPolicyKind(record?.effectivePolicy || record?.defaultPolicy) === "button-step"
    && record?.configuration
  ))?.configuration || null;
}

function savedInteractionControllerConfiguration(
  decision = state.data?.decisions?.["interaction-control"],
) {
  const draft = state.data?.interactionControlDraft;
  return normalizeInteractionConfiguration(
    interactionControllerConfigurationCandidate(decision)
      || interactionControllerConfigurationCandidate(draft),
    "button-step",
  );
}

function ensureInteractionControllerConfiguration() {
  if (state.interactionControllerConfigurationInitialized) {
    return state.interactionControllerConfiguration;
  }
  state.interactionControllerConfiguration = savedInteractionControllerConfiguration();
  state.interactionControllerConfigurationInitialized = true;
  return state.interactionControllerConfiguration;
}

function interactionControllerConfigurationSignature(value) {
  return JSON.stringify(normalizeInteractionConfiguration(value, "button-step"));
}

function savedInteractionBoundaryOverrides(decision) {
  const overrides = {};
  const records = interactionDecisionBoundaryRecords(decision);
  for (const [boundaryId, value] of Object.entries(decision?.boundaryOverrides || {})) {
    const record = records.find((candidate) => candidate.boundaryId === boundaryId) || null;
    const normalized = normalizeInteractionBoundaryOverride(value, record);
    if (normalized) overrides[boundaryId] = normalized;
  }
  for (const record of records) {
    if (!record?.overridden || !record?.boundaryId) continue;
    const normalized = normalizeInteractionBoundaryOverride({
      policy: record.effectivePolicy,
      locomotionMode: record.locomotionMode,
      configuration: record.configuration,
    }, record);
    if (normalized) overrides[record.boundaryId] = normalized;
  }
  return overrides;
}

function interactionBoundaryOverridesSignature(overrides) {
  const boundariesById = new Map(interactionBoundaryContext(selectedInteractionControlBase()).boundaries
    .map((boundary) => [boundary.boundaryId, boundary]));
  return JSON.stringify(Object.entries(overrides || {})
    .map(([boundaryId, value]) => [boundaryId, normalizeInteractionBoundaryOverride(value, boundariesById.get(boundaryId))])
    .filter(([, value]) => value?.policy)
    .map(([boundaryId, value]) => [boundaryId, {
      policy: canonicalInteractionPolicy(value.policy),
      ...(value.locomotionMode ? { locomotionMode: normalizeInteractionLocomotionMode(value.locomotionMode) } : {}),
      ...(value.configuration && recognizedInteractionPolicyKind(value.policy) !== "button-step"
        ? { configuration: value.configuration }
        : {}),
    }])
    .sort(([left], [right]) => left.localeCompare(right)));
}

function ensureInteractionBoundaryOverrides() {
  if (state.interactionBoundaryOverridesInitialized) return state.interactionBoundaryOverrides;
  const decision = state.data?.decisions?.["interaction-control"];
  const records = interactionDecisionBoundaryRecords(decision);
  const overrides = {};
  if (decision?.boundaryOverrides && typeof decision.boundaryOverrides === "object") {
    for (const [boundaryId, value] of Object.entries(decision.boundaryOverrides)) {
      const record = records.find((candidate) => candidate.boundaryId === boundaryId) || null;
      const normalized = normalizeInteractionBoundaryOverride(value, record);
      if (normalized) overrides[boundaryId] = normalized;
    }
  }
  for (const record of records) {
    if (!record?.overridden || !record?.boundaryId) continue;
    overrides[record.boundaryId] = normalizeInteractionBoundaryOverride({
      policy: record.effectivePolicy,
      locomotionMode: record.locomotionMode,
      configuration: record.configuration,
    }, record);
  }
  state.interactionBoundaryOverrides = overrides;
  state.interactionBoundaryOverridesInitialized = true;
  state.interactionBoundaryOverrideResets = new Set();
  return overrides;
}

function interactionBoundaryContext(proposal = null, sceneContext = null) {
  const variantRecords = interactionVariantControlRecords();
  const variantEdgeControls = interactionVariantSwitchEdges()
    .map((edge) => interactionVariantEdgeControlForEdge(edge));
  let beats = interactionPreviewBeats(proposal).map((beat) => ({
    ...beat,
    variantInteractionControl: interactionVariantControlForBeat(beat, variantRecords),
  }));
  if (sceneContext?.beatId) {
    const sceneBeat = interactionPreviewBeatForSceneContext(proposal, sceneContext);
    if (sceneBeat) {
      beats = beats.map((beat) => beat.id === sceneContext.beatId
        ? { ...beat, ...sceneBeat, variantInteractionControl: beat.variantInteractionControl }
        : beat);
      const sceneBeatIndex = beats.findIndex((beat) => beat.id === sceneContext.beatId);
      if (sceneBeatIndex >= 0) state.selectedInteractionBeatIndex = sceneBeatIndex;
    }
  }
  const records = interactionControlBoundaryRecords();
  const overrides = ensureInteractionBoundaryOverrides();
  const recordsList = [...new Set(records.values())];
  const beatsById = new Map(beats.map((beat) => [beat.id, beat]));
  const boundaries = interactionProgressionEdges().flatMap((edge) => {
    const fromBeatId = edge.from.beatId;
    const toBeatId = edge.to.beatId;
    const fromContext = sourceGraphTransitionSceneContext(edge.from);
    const toContext = sourceGraphTransitionSceneContext(edge.to);
    const from = interactionPreviewBeatForSceneContext(proposal, fromContext) || beatsById.get(fromBeatId);
    const to = interactionPreviewBeatForSceneContext(proposal, toContext) || beatsById.get(toBeatId);
    if (!from || !to) return [];
    const legacyId = interactionBoundaryId(fromBeatId, toBeatId);
    const exactRecord = records.get(edge.id)
      || recordsList.find((item) => item.edgeId === edge.id)
      || null;
    const legacyRecord = records.get(legacyId)
      || recordsList.find((item) => !item.edgeId && item.fromBeatId === fromBeatId && item.toBeatId === toBeatId)
      || null;
    const legacyKind = recognizedInteractionPolicyKind(legacyRecord?.effectivePolicy || legacyRecord?.defaultPolicy || legacyRecord?.inferredPolicy);
    const defaultFromContext = interBeatDefaultSceneContextForBeat(fromBeatId);
    const legacyApplies = Boolean(legacyRecord) && (
      !fromContext.variantOptionId
      || sourceGraphTransitionContextMatches(fromContext, defaultFromContext)
      || legacyKind === "button-step"
      || !legacyKind
    );
    const record = exactRecord || (legacyApplies ? legacyRecord : null);
    const boundaryId = edge.id;
    if (!interactionBoundaryRecordIsCurrent(record, edge)) {
      return {
        boundaryId,
        edgeId: edge.id,
        edge,
        fromBeatId,
        toBeatId,
        fromContext,
        toContext,
        from,
        to,
        configurationAvailable: false,
        mappedTransition: false,
        assignmentRequired: false,
        defaultPolicy: null,
        inferredPolicy: null,
        effectivePolicy: null,
        overridden: false,
        reason: "Finish Scene changes before assigning a reader action to this scene change.",
        evidence: [],
        locomotionMode: null,
      };
    }
    const defaultKind = recognizedInteractionPolicyKind(record.defaultPolicy ?? record.inferredPolicy);
    const defaultPolicy = defaultKind ? interactionControlKindLabel(defaultKind) : null;
    const savedEffectiveKind = recognizedInteractionPolicyKind(record.effectivePolicy);
    const savedEffectivePolicy = savedEffectiveKind ? interactionControlKindLabel(savedEffectiveKind) : null;
    const mappedTransition = record.mappedTransition === true || record.assignmentRequired === true || !defaultPolicy;
    const resetToDefault = state.interactionBoundaryOverrideResets.has(boundaryId);
    const draftOverride = overrides[boundaryId] || (legacyApplies ? overrides[legacyId] : null) || null;
    const preservedAssignment = record.overridden ? savedEffectivePolicy : null;
    const effectivePolicy = resetToDefault ? defaultPolicy : draftOverride?.policy || preservedAssignment || defaultPolicy;
    const overridden = !resetToDefault && Boolean(draftOverride || (record.overridden && preservedAssignment));
    const defaultReason = record.defaultReason || (!record.overridden ? record.reason : "")
      || (mappedTransition
        ? "This scene change has mapped movement. Assign the reader action explicitly."
        : "No mapped scene change is available, so Controller button press is the default.");
    return {
      ...record,
      boundaryId,
      edgeId: edge.id,
      edge,
      fromBeatId,
      toBeatId,
      fromContext,
      toContext,
      from,
      to,
      configurationAvailable: true,
      mappedTransition,
      assignmentRequired: mappedTransition,
      defaultPolicy,
      inferredPolicy: defaultPolicy,
      effectivePolicy,
      overridden,
      authored: overridden,
      reason: resetToDefault
        ? defaultReason
        : draftOverride
          ? `Author assignment selects ${effectivePolicy}. ${defaultReason}`
          : overridden
            ? `The author selected ${effectivePolicy} for this boundary. ${defaultReason}`
            : defaultReason,
      evidence: Array.isArray(record.evidence) ? record.evidence : [],
      locomotionMode: effectivePolicy === "Reader locomotion"
        ? draftOverride?.locomotionMode || record.locomotionMode
        : null,
      configuration: effectivePolicy
        ? normalizeInteractionConfiguration(
            recognizedInteractionPolicyKind(effectivePolicy) === "button-step"
              ? ensureInteractionControllerConfiguration()
              : draftOverride?.configuration || record.configuration,
            recognizedInteractionPolicyKind(effectivePolicy),
            interactionConfigurationContext({
              boundary: { ...record, boundaryId, edgeId: edge.id, fromBeatId, toBeatId, fromContext, toContext },
              sceneContext: fromContext,
            }),
          )
        : null,
    };
  });
  const beatIndex = clampInteractionBeatIndex(beats);
  const requestedBoundary = sceneContext?.interactionTargetType === "boundary"
    ? boundaries.find((candidate) => candidate.boundaryId === sceneContext.interactionTargetId)
    : null;
  const activeSceneBoundary = sceneContext?.beatId
    ? boundaries.find((candidate) => sourceGraphTransitionContextMatches(candidate.toContext, sceneContext))
      || boundaries.find((candidate) => candidate.toBeatId === sceneContext.beatId)
    : null;
  return {
    beats,
    boundaries,
    variantControls: beats.map((beat) => beat.variantInteractionControl).filter(Boolean),
    variantEdgeControls,
    beatIndex,
    beat: beats[beatIndex] || null,
    boundary: requestedBoundary || activeSceneBoundary || null,
    variantControl: beats[beatIndex]?.variantInteractionControl || null,
  };
}

function interactionBoundaryContextIsComplete(context) {
  return Boolean(context)
    && context.boundaries.every((boundary) => {
      const kind = recognizedInteractionPolicyKind(boundary.effectivePolicy);
      return boundary.configurationAvailable
        && kind
        && interactionConfigurationIsComplete(kind, boundary.configuration);
    })
    && context.variantControls.every((record) => record.configurationAvailable && variantInteractionPolicyKind(record.effectivePolicy))
    && context.variantEdgeControls.every((record) => {
      const kind = variantInteractionPolicyKind(record.effectivePolicy);
      return kind && interactionConfigurationIsComplete(kind, record.configuration);
    });
}

function interactionConfigurationIsComplete(kind, configuration) {
  if (!configuration || interactionKindForConfiguration(configuration) !== kind) return false;
  if (kind === "button-step") {
    return configuration.bindings.some((binding) => binding.action === "next-beat");
  }
  if (kind === "ui-button-press") {
    return configuration.buttons.some((button) => button.label && button.action);
  }
  if (kind === "direct") return configuration.targets.length > 0
    && configuration.targets.every((target) => (
      target.destinationAuthored !== false
      && interactionDirectDestinationIsReachable(target)
    ));
  return Boolean(configuration.destination?.transform)
    && configuration.tolerance.distanceMeters > 0
    && configuration.tolerance.dwellSeconds >= 0;
}

function interactionProposalForBoundary(baseProposal, boundary) {
  if (!boundary) return baseProposal;
  const kind = boundary.effectivePolicy ? inferInteractionControlKind({ label: boundary.effectivePolicy }) : null;
  const source = baseProposal || {};
  return {
    ...source,
    optionId: boundary.boundaryId,
    label: boundary.effectivePolicy || "Unassigned",
    description: boundary.reason || (kind ? interactionControlKindHelp(kind) : "Assign a reader action for this mapped scene change."),
    interactionBoundary: boundary,
  };
}

function interactionBoundaryOverridesPayload() {
  const boundaries = interactionBoundaryContext().boundaries
    .filter((boundary) => boundary.configurationAvailable);
  const overrides = ensureInteractionBoundaryOverrides();
  return Object.fromEntries(boundaries.flatMap((boundary) => {
    const boundaryId = boundary.boundaryId;
    const legacyId = interactionBoundaryId(boundary.fromBeatId, boundary.toBeatId);
    const legacyValue = overrides[legacyId] || null;
    const legacyKind = recognizedInteractionPolicyKind(legacyValue?.policy);
    const defaultFromContext = interBeatDefaultSceneContextForBeat(boundary.fromBeatId);
    const legacyApplies = Boolean(legacyValue) && (
      !boundary.fromContext?.variantOptionId
      || sourceGraphTransitionContextMatches(boundary.fromContext, defaultFromContext)
      || legacyKind === "button-step"
      || !legacyKind
    );
    const value = overrides[boundaryId] || (legacyApplies ? legacyValue : null);
    if (!value?.policy) return [];
    return [[boundaryId, {
      policy: canonicalInteractionPolicy(value.policy),
      ...(value.locomotionMode ? { locomotionMode: normalizeInteractionLocomotionMode(value.locomotionMode) } : {}),
      ...(value.configuration && recognizedInteractionPolicyKind(value.policy) !== "button-step" ? { configuration: normalizeInteractionConfiguration(
        value.configuration,
        recognizedInteractionPolicyKind(value.policy),
        interactionConfigurationContext({
          boundary,
        }),
      ) } : {}),
    }]];
  }));
}

function setInteractionBoundaryPolicy(boundaryId, policy, options = {}) {
  const boundary = interactionBoundaryContext().boundaries.find((item) => item.boundaryId === boundaryId);
  if (!boundary?.configurationAvailable) return;
  const canonicalPolicy = canonicalInteractionPolicy(policy);
  const overrides = ensureInteractionBoundaryOverrides();
  state.interactionBoundaryOverrideResets.delete(boundaryId);
  const kind = recognizedInteractionPolicyKind(canonicalPolicy);
  if (kind === "direct" && !interactionBoundaryDirectManipulationAvailable(boundaryId)) return;
  const configuration = normalizeInteractionConfiguration(
    kind === "button-step"
      ? ensureInteractionControllerConfiguration()
      : overrides[boundaryId]?.configuration || boundary.configuration,
    kind,
    interactionConfigurationContext({ boundary }),
  );
  if (boundary.defaultPolicy && canonicalPolicy === boundary.defaultPolicy && !options.retainConfiguration && !overrides[boundaryId]?.configuration) {
    delete overrides[boundaryId];
    if (boundary.overridden) state.interactionBoundaryOverrideResets.add(boundaryId);
  } else {
    overrides[boundaryId] = {
      ...(overrides[boundaryId] || {}),
      policy: canonicalPolicy,
      ...(kind === "button-step" ? {} : { configuration }),
      ...(canonicalPolicy === "Reader locomotion"
        ? { locomotionMode: normalizeInteractionLocomotionMode(overrides[boundaryId]?.locomotionMode || boundary.locomotionMode) }
        : {}),
    };
    if (canonicalPolicy !== "Reader locomotion") delete overrides[boundaryId].locomotionMode;
  }
}

function interactionOptionEditorContext(baseProposal, sceneContext = activeInteractionSceneContext()) {
  if (!sceneContext) return null;
  const context = interactionBoundaryContext(baseProposal, sceneContext);
  if (sceneContext.interactionTargetType === "global-controller") {
    return {
      targetType: "global-controller",
      targetId: "shared-controller-mapping",
      kind: "button-step",
      edge: null,
      boundary: null,
      record: null,
      sceneContext,
      targetSceneContext: sceneContext,
      beat: interactionPreviewBeatForSceneContext(baseProposal, sceneContext),
      fromLabel: "All Controller button press scene changes",
      toLabel: "All Controller button press scene changes",
      configuration: ensureInteractionControllerConfiguration(),
      boundaryContext: context,
    };
  }
  if (sceneContext.interactionTargetType === "variant-edge") {
    const edge = interactionVariantSwitchEdges().find((candidate) => candidate.id === sceneContext.interactionTargetId);
    if (!edge) return null;
    const record = interactionVariantEdgeControlForEdge(edge);
    const kind = variantInteractionPolicyKind(sceneContext.interactionKind || record.effectivePolicy);
    if (!kind) return null;
    return {
      targetType: "variant-edge",
      targetId: edge.id,
      kind,
      edge,
      boundary: null,
      record,
      sceneContext: spatialSceneContext(edge.from.beatId, edge.from.variantGroupId, edge.from.variantOptionId),
      targetSceneContext: spatialSceneContext(edge.to.beatId, edge.to.variantGroupId, edge.to.variantOptionId),
      beat: interactionPreviewBeatForSceneContext(baseProposal, sceneContext),
      fromLabel: storyVariantEndpointLabel(edge.from),
      toLabel: storyVariantEndpointLabel(edge.to),
      configuration: normalizeInteractionConfiguration(
        record.configuration,
        kind,
        interactionConfigurationContext({ edge }),
      ),
      boundaryContext: context,
    };
  }
  if (sceneContext.interactionTargetType !== "boundary") {
    const beat = interactionPreviewBeatForSceneContext(baseProposal, sceneContext);
    return {
      targetType: "in-beat",
      targetId: interactionInBeatSceneKey(sceneContext),
      kind: null,
      edge: null,
      boundary: null,
      record: interactionInBeatRecordForContext(sceneContext),
      sceneContext,
      targetSceneContext: sceneContext,
      beat,
      fromLabel: spatialSceneContextLabel(sceneContext),
      toLabel: spatialSceneContextLabel(sceneContext),
      configuration: null,
      boundaryContext: context,
    };
  }
  const requestedBoundary = sceneContext.interactionTargetType === "boundary"
    ? context.boundaries.find((candidate) => candidate.boundaryId === sceneContext.interactionTargetId)
    : null;
  if (!requestedBoundary) {
    return {
      targetType: "entry",
      targetId: sceneContext.beatId,
      kind: null,
      edge: null,
      boundary: null,
      record: null,
      sceneContext,
      targetSceneContext: sceneContext,
      beat: interactionPreviewBeatForSceneContext(baseProposal, sceneContext),
      fromLabel: "Story entry",
      toLabel: spatialSceneContextLabel(sceneContext),
      configuration: null,
      boundaryContext: context,
    };
  }
  const kind = recognizedInteractionPolicyKind(sceneContext.interactionKind || requestedBoundary.effectivePolicy);
  return {
    targetType: "boundary",
    targetId: requestedBoundary.boundaryId,
    kind,
    edge: null,
    boundary: requestedBoundary,
    record: requestedBoundary,
    sceneContext: normalizeMotionSceneContext(requestedBoundary.fromContext, requestedBoundary.fromBeatId)
      || interactionSceneContextForBeat(requestedBoundary.fromBeatId),
    targetSceneContext: normalizeMotionSceneContext(requestedBoundary.toContext, requestedBoundary.toBeatId)
      || interactionSceneContextForBeat(requestedBoundary.toBeatId),
    beat: requestedBoundary.from,
    fromLabel: interBeatTransitionEndpointTitle(requestedBoundary.from, requestedBoundary.fromContext),
    toLabel: interBeatTransitionEndpointTitle(requestedBoundary.to, requestedBoundary.toContext),
    configuration: kind
      ? normalizeInteractionConfiguration(
          requestedBoundary.configuration,
          kind,
          interactionConfigurationContext({ boundary: requestedBoundary }),
        )
      : null,
    boundaryContext: context,
  };
}

function mutateInteractionOptionConfiguration(editorContext, mutate) {
  if (!editorContext?.kind || typeof mutate !== "function") return false;
  const context = interactionConfigurationContext({
    boundary: editorContext.boundary,
    edge: editorContext.edge,
    sceneContext: editorContext.sceneContext,
  });
  const current = normalizeInteractionConfiguration(editorContext.configuration, editorContext.kind, context);
  const next = cloneJson(current);
  mutate(next);
  const configuration = normalizeInteractionConfiguration(next, editorContext.kind, context);
  if (editorContext.targetType === "global-controller") {
    state.interactionControllerConfiguration = configuration;
    state.interactionControllerConfigurationInitialized = true;
  } else if (editorContext.targetType === "boundary") {
    const overrides = ensureInteractionBoundaryOverrides();
    overrides[editorContext.targetId] = {
      ...(overrides[editorContext.targetId] || {}),
      policy: interactionControlKindLabel(editorContext.kind),
      configuration,
    };
    state.interactionBoundaryOverrideResets.delete(editorContext.targetId);
  } else if (editorContext.targetType === "variant-edge") {
    const overrides = ensureInteractionVariantOverrides();
    overrides[editorContext.targetId] = {
      ...(overrides[editorContext.targetId] || {}),
      policy: variantInteractionPolicyLabel(editorContext.kind),
      configuration,
    };
  } else return false;
  editorContext.configuration = configuration;
  return true;
}

function interactionMappedTransformSuggestions(editorContext) {
  if (editorContext?.kind !== "direct") return [];
  const toBeatId = editorContext.boundary?.toBeatId || editorContext.edge?.to?.beatId;
  if (!toBeatId) return [];
  const routePlayback = editorContext.edge || editorContext.boundary?.edgeId
    ? interBeatBoundaryPlaybackSummary(selectedComponentPreview(componentById("inter-beat-dynamics")), {
        ...editorContext.targetSceneContext,
        transitionEdgeId: editorContext.edge?.id || editorContext.boundary?.edgeId,
      })
    : null;
  if (!editorContext.boundary?.mappedTransition && !routePlayback?.canScrub) return [];
  const toVariantOptionId = editorContext.edge?.to?.variantOptionId
    || editorContext.boundary?.toContext?.variantOptionId
    || null;
  const sourceTargets = interactionDirectSceneTargets(editorContext.sceneContext);
  const sourceTargetsByAsset = new Map();
  for (const target of sourceTargets) {
    if (!sourceTargetsByAsset.has(target.assetId)) sourceTargetsByAsset.set(target.assetId, []);
    sourceTargetsByAsset.get(target.assetId).push(target);
  }
  const states = sourcePartStatesForPreviewBeat(toBeatId);
  const unsafeKinds = /visibility|opacity|material|morph|topology|animation|swap|present/i;
  const suggestions = [];
  for (const partState of states) {
    if (toVariantOptionId && partState.variantOptionId && partState.variantOptionId !== toVariantOptionId) continue;
    if (!partState?.transformChanged || partState.visibilityChanged || partState.opacityChanged || partState.modelSwapped || partState.animationActionChanged) continue;
    if ((partState.changeKinds || []).some((kind) => unsafeKinds.test(String(kind)))) continue;
    const assetTargets = sourceTargetsByAsset.get(String(partState.assetId || "")) || [];
    if (!assetTargets.length) continue;
    const changedParts = (partState.parts || []).filter((part) => (
      part?.transformChanged
      && part.worldTransform
      && !part.visibilityChanged
      && !part.opacityChanged
      && !part.animationActionChanged
      && !(part.changeKinds || []).some((kind) => unsafeKinds.test(String(kind)))
    ));
    for (const part of changedParts) {
      const sourceTarget = assetTargets.find((target) => (
        target.nodePath && String(target.nodePath) === String(part.nodePath || "")
      ));
      if (!sourceTarget) continue;
      const destinationTransform = normalizeSpatialTransform(part.localTransform || part.transform || part.worldTransform, sourceTarget.sourceTransform);
      if (!sourceTarget.oneHandGrabbable) {
        destinationTransform.position = cloneJson(sourceTarget.sourceTransform.position);
        destinationTransform.quaternion = cloneJson(sourceTarget.sourceTransform.quaternion);
      }
      if (!sourceTarget.twoHandScalable) destinationTransform.scale = cloneJson(sourceTarget.sourceTransform.scale);
      suggestions.push({
        entityId: sourceTarget.entityId,
        assetId: sourceTarget.assetId,
        ...(sourceTarget.nodePath ? { nodePath: sourceTarget.nodePath } : {}),
        ...(sourceTarget.nodeIndex != null ? { nodeIndex: sourceTarget.nodeIndex } : {}),
        coordinateSpace: "local",
        oneHandGrabbable: sourceTarget.oneHandGrabbable,
        twoHandScalable: sourceTarget.twoHandScalable,
        ...(sourceTarget.elasticDragging ? { elasticDragging: true } : {}),
        triggerComponents: interactionDirectAvailableTriggerComponents(sourceTarget),
        initialTransform: cloneJson(sourceTarget.sourceTransform),
        constraints: cloneJson(sourceTarget.constraints || {}),
        destinationTransform,
        destinationAuthored: true,
        suggested: true,
        source: "mapped-transition",
      });
    }
  }
  return suggestions;
}

function resetInteractionBoundaryPolicy(boundaryId) {
  delete ensureInteractionBoundaryOverrides()[boundaryId];
  state.interactionBoundaryOverrideResets.add(boundaryId);
}

function interactionSpatialTraversal(proposal = null) {
  const draft = state.data?.interactionControlDraft;
  const decision = state.data?.decisions?.["interaction-control"];
  return draft?.spatialTraversal
    || decision?.spatialTraversal
    || decision?.option?.spatialTraversal
    || null;
}

function interactionTraversalRequiresLocomotion(traversal = interactionSpatialTraversal()) {
  return Boolean(traversal?.requiresLocomotion);
}

function normalizeInteractionLocomotionMode(value) {
  return value === "physical-walking" ? "physical-walking" : "virtual-teleport";
}

function interactionLocomotionMode(proposal = null, boundary = null) {
  const activeBoundary = boundary || proposal?.interactionBoundary || null;
  if (activeBoundary?.locomotionMode) return normalizeInteractionLocomotionMode(activeBoundary.locomotionMode);
  if (state.interactionLocomotionMode) return normalizeInteractionLocomotionMode(state.interactionLocomotionMode);
  const decision = state.data?.decisions?.["interaction-control"];
  const preserved = decision?.locomotionMode || decision?.option?.locomotionMode;
  if (preserved) return normalizeInteractionLocomotionMode(preserved);
  const traversal = interactionSpatialTraversal(proposal);
  if (traversal?.defaultLocomotionMode) return normalizeInteractionLocomotionMode(traversal.defaultLocomotionMode);
  return interactionTraversalRequiresLocomotion(traversal) ? "virtual-teleport" : "physical-walking";
}

function clampInteractionBeatIndex(beats) {
  const max = Math.max((beats || []).length - 1, 0);
  if (!Number.isFinite(state.selectedInteractionBeatIndex)) state.selectedInteractionBeatIndex = 0;
  state.selectedInteractionBeatIndex = Math.max(0, Math.min(max, state.selectedInteractionBeatIndex));
  return state.selectedInteractionBeatIndex;
}

function interactionSceneAssetLinks(proposal, beats) {
  return narrativeSceneAssetLinks(proposal, beats);
}

function applyInteractionAction(action) {
  const proposal = selectedInteractionControlBase();
  const beats = interactionPreviewBeats(proposal);
  const max = Math.max(beats.length - 1, 0);
  if (action === "next") {
    state.selectedInteractionBeatIndex = Math.min(max, state.selectedInteractionBeatIndex + 1);
    return;
  }
  if (action === "embodied-restart" || action === "embodied-step") {
    state.interactionEmbodiedRestartToken += 1;
    return;
  }
  if (action === "previous") {
    state.selectedInteractionBeatIndex = Math.max(0, state.selectedInteractionBeatIndex - 1);
    return;
  }
  if (action === "branch-a" || action === "branch-b") {
    state.interactionBranchChoice = action === "branch-a" ? "A" : "B";
    state.selectedInteractionBeatIndex = Math.min(max, state.selectedInteractionBeatIndex + 1);
    return;
  }
  if (action === "manipulate-left") {
    state.interactionManipulationOffset = {
      x: Math.max(-1.1, (state.interactionManipulationOffset?.x || 0) - 0.22),
      y: 0,
      z: state.interactionManipulationOffset?.z || 0,
    };
    return;
  }
  if (action === "manipulate-right") {
    state.interactionManipulationOffset = {
      x: Math.min(1.1, (state.interactionManipulationOffset?.x || 0) + 0.22),
      y: 0,
      z: state.interactionManipulationOffset?.z || 0,
    };
    return;
  }
  if (action === "reset-manipulation") {
    state.interactionManipulationOffset = { x: 0, y: 0, z: 0 };
  }
}

function formatNumber(value) {
  return Number(value || 0).toFixed(2);
}

function interBeatPreviewTransitions(proposal) {
  const beats = interBeatStoryBeats(proposal);
  const beatsById = new Map(beats.map((beat) => [beat.id, beat]));
  return authoredMotionTransitions({ preserveParallel: true, includeSameBeat: true }).flatMap((transition, index) => {
    const fromBaseBeat = beatsById.get(transition.from.id);
    const toBaseBeat = beatsById.get(transition.to.id);
    if (!fromBaseBeat || !toBaseBeat) return [];
    return [{
      ...transition,
      id: transition.edgeId,
      from: interBeatPreviewBeatForSceneContext(proposal, transition.fromContext) || fromBaseBeat,
      to: interBeatPreviewBeatForSceneContext(proposal, transition.toContext) || toBaseBeat,
      index,
    }];
  });
}

function interBeatStoryBeats(proposal) {
  const graphBeats = state.data?.graph?.beats || [];
  const evidenceByBeat = new Map((proposal?.sourceEvidence || [])
    .filter((item) => item.beatId)
    .map((item) => [item.beatId, item]));
  return graphBeats.map((beat) => {
    const partStates = sourcePartStatesForPreviewBeat(beat.id);
    const linkedAssetIds = uniqueStrings([
      ...beatAssetIds(beat),
      ...partStates.map((item) => item.assetId),
    ]);
    const evidence = evidenceByBeat.get(beat.id);
    return {
      id: beat.id,
      title: beat.title || beat.id,
      text: beat.text || beat.section || evidence?.quote || "",
      linkedAssetIds,
      quote: evidence?.quote || "",
      reason: evidence?.reason || "",
      evidence,
      isTextOnly: isAuthoredTextOnlyTimelineBeat(beat),
      sourcePartStates: partStates,
    };
  });
}

function isAuthoredTextOnlyTimelineBeat(beat) {
  return beat?.isTextOnly === true || beat?.kind === "text-only" || beat?.originalField === "text_only_parts";
}

function beatSourcePartPlaybackMode(beat) {
  return beat?.sourcePartStates?.some((item) => item.playbackMode === "frozen") ? "frozen" : "animated";
}

function selectedInterBeatBeatContext(proposal, sceneContext = activeInterBeatSceneContext()) {
  if (sceneContext?.beatId) {
    const context = interBeatBoundaryForSceneContext(proposal, sceneContext);
    state.selectedInterBeatBeatIndex = context.beatIndex;
    state.selectedInterBeatTransitionIndex = interBeatMotionTransitionIndex(context);
    return context;
  }
  const beats = interBeatStoryBeats(proposal);
  const max = Math.max(beats.length - 1, 0);
  if (!Number.isFinite(state.selectedInterBeatBeatIndex)) state.selectedInterBeatBeatIndex = Math.min(1, max);
  const beatIndex = Math.max(0, Math.min(max, state.selectedInterBeatBeatIndex));
  state.selectedInterBeatBeatIndex = beatIndex;
  const transitions = interBeatPreviewTransitions(proposal);
  const beat = beats[beatIndex] || null;
  const transition = beatIndex > 0 && beatSourcePartPlaybackMode(beat) !== "frozen" ? transitions[beatIndex - 1] || null : null;
  state.selectedInterBeatTransitionIndex = Math.max(0, beatIndex - 1);
  return { beats, beatIndex, beat, transitions, transition };
}

function interBeatBeatDisplayTitle(beat, beats) {
  if (!beat) return "Story part";
  const title = String(beat.title || "").trim();
  if (!title) return beat.id || "Story part";
  const duplicateCount = (beats || []).filter((candidate) => String(candidate?.title || "").trim() === title).length;
  return duplicateCount > 1 ? beat.id || title : title;
}

function sourcePartStatesForPreviewBeat(beatId, assetId = null) {
  if (!beatId) return [];
  const source = state.data?.graph?.sourcePartStates || {};
  const states = Array.isArray(source.resolvedStates) && source.resolvedStates.length ? source.resolvedStates : source.states || [];
  return states.filter((item) => (
    item.beatId === beatId && (!assetId || item.assetId === assetId)
  ));
}

function sourcePartSelectorsForState(partState) {
  return uniqueStrings([
    ...(partState?.partSelectors || []),
    ...(partState?.animationTargetSelectors || []),
  ]);
}

function sourceVisibilitySelectorsForState(partState) {
  return uniqueStrings(partState?.partSelectors || []);
}

function sourcePartStateCanApplyHardMask(partState, assetId) {
  const playback = sourcePlaybackAssetForId(assetId);
  if (playback?.mode !== "shared-timeline") return true;
  return partState?.provenance === "direct-runtime";
}

function expandSourcePartSelectors(selectors) {
  const expand = (value) => {
    const selector = String(value || "").trim();
    if (!selector) return [];
    const plusParts = selector.split(/\s+plus\s+/i);
    if (plusParts.length > 1) return plusParts.flatMap(expand);
    const brace = selector.match(/^(.*?)\{([^{}]+)\}(.*)$/);
    if (brace) return brace[2].split(",").flatMap((choice) => expand(`${brace[1]}${choice.trim()}${brace[3]}`));
    const range = selector.match(/^(.*?)(\d+)\.\.(\d+)(.*)$/);
    if (range) {
      const start = Number(range[2]);
      const end = Number(range[3]);
      const width = Math.max(range[2].length, range[3].length);
      const direction = end >= start ? 1 : -1;
      const values = [];
      for (let number = start; direction > 0 ? number <= end : number >= end; number += direction) {
        values.push(...expand(`${range[1]}${String(number).padStart(width, "0")}${range[4]}`));
      }
      return values;
    }
    return [selector.replace(/^\/+|\/+$/g, "")];
  };
  return uniqueStrings((selectors || []).flatMap(expand));
}

function sourcePartSelectorRegex(selector) {
  const escaped = String(selector || "")
    .replace(/[.+?^${}()|[\]\\]/g, "\\$&")
    .replace(/\*/g, ".*");
  return new RegExp(`^${escaped}$`, "i");
}

function sourcePartNodePath(node, root) {
  const names = [];
  let current = node;
  while (current && current !== root) {
    if (current.name) names.unshift(current.name);
    current = current.parent;
  }
  return names.join("/");
}

function sourcePartSelectorMatchesNode(selector, node, root) {
  const normalizedSelector = String(selector || "").replace(/^\/+|\/+$/g, "");
  if (!normalizedSelector) return false;
  const path = sourcePartNodePath(node, root);
  const pathParts = path.split("/").filter(Boolean);
  const candidates = uniqueStrings([
    path,
    node.name,
    ...pathParts.map((_, index) => pathParts.slice(index).join("/")),
  ]);
  const pattern = sourcePartSelectorRegex(normalizedSelector);
  if (candidates.some((candidate) => pattern.test(candidate))) return true;
  if (!normalizedSelector.includes("*")) {
    const lowerSelector = normalizedSelector.toLowerCase();
    return candidates.some((candidate) => {
      const lowerCandidate = candidate.toLowerCase();
      return lowerCandidate === lowerSelector || lowerCandidate.startsWith(`${lowerSelector}/`) || lowerCandidate.includes(`/${lowerSelector}/`);
    });
  }
  return false;
}

function applySourcePartMask(root, selectors) {
  if (!root?.traverse) return { applied: false, matched: 0, renderables: 0 };
  const expanded = expandSourcePartSelectors(selectors);
  const renderables = [];
  root.traverse((node) => {
    if (!node.isMesh && !node.isPoints && !node.isLine) return;
    if (!("storyvrSourcePartBaseVisible" in node.userData)) node.userData.storyvrSourcePartBaseVisible = node.visible !== false;
    if (!("storyvrSourcePartMaskVisible" in node.userData)) node.userData.storyvrSourcePartMaskVisible = true;
    if (!("storyvrSourceBindingVisible" in node.userData)) node.userData.storyvrSourceBindingVisible = true;
    renderables.push(node);
  });
  if (!expanded.length) {
    for (const node of renderables) {
      node.userData.storyvrSourcePartMaskVisible = true;
      updateSourceRenderableVisibility(node);
    }
    return { applied: false, matched: 0, renderables: renderables.length };
  }
  const matched = renderables.filter((node) => expanded.some((selector) => sourcePartSelectorMatchesNode(selector, node, root)));
  if (!matched.length) {
    for (const node of renderables) {
      node.userData.storyvrSourcePartMaskVisible = true;
      updateSourceRenderableVisibility(node);
    }
    return { applied: false, matched: 0, renderables: renderables.length, fallback: true };
  }
  const matchedSet = new Set(matched);
  for (const node of renderables) {
    node.userData.storyvrSourcePartMaskVisible = matchedSet.has(node);
    updateSourceRenderableVisibility(node);
  }
  return { applied: true, matched: matched.length, renderables: renderables.length };
}

function sourcePartSelectorsForBeatAsset(beatId, assetId) {
  return uniqueStrings(sourcePartStatesForPreviewBeat(beatId, assetId)
    .filter((item) => sourcePartStateCanApplyHardMask(item, assetId))
    .flatMap((item) => sourceVisibilitySelectorsForState(item)));
}

function sourcePlaybackContractOwnsEntryVisibility(entry) {
  if (entry?.sourcePlayback?.asset?.mode === "shared-timeline") return true;
  const assetId = entry?.assetId || entry?.step?.assetId;
  return sourcePlaybackAssetForId(assetId)?.mode === "shared-timeline";
}

function applyInterBeatSourcePartMaskToEntry(viewer, entry, phase = "destination") {
  if (!viewerExecutesInterBeatTransition(viewer) || !entry?.sourceScene) return null;
  if (sourcePlaybackContractOwnsEntryVisibility(entry)) return { applied: false, contractOwned: true };
  const assetId = entry.assetId || entry.step?.assetId;
  const destination = sourcePartSelectorsForBeatAsset(viewer.sourcePartToBeatId, assetId);
  const selectors = phase === "transition"
    ? uniqueStrings([...sourcePartSelectorsForBeatAsset(viewer.sourcePartFromBeatId, assetId), ...destination])
    : destination;
  const result = applySourcePartMask(entry.sourceScene, selectors);
  entry.sourcePartMaskResult = result;
  return result;
}

function applyInterBeatSourcePartMasks(viewer, phase) {
  if (!viewer || viewer.sourcePartMaskPhase === phase) return;
  viewer.sourcePartMaskPhase = phase;
  for (const entry of [...(viewer.dynamicObjects || []), ...(viewer.swapGroups || [])]) {
    applyInterBeatSourcePartMaskToEntry(viewer, entry, phase);
  }
}

function interBeatTransitionBeatLabel(beat, fallback = "story part", maxLength = 64) {
  const id = String(beat?.id || fallback || "story part").trim();
  const cue = String(beat?.text || beat?.title || "").trim();
  if (!cue || cue === id) return shortText(id, maxLength);
  return shortText(`${id} · ${cue}`, maxLength);
}

function clampInterBeatTransitionIndex(transitions) {
  const max = Math.max((transitions || []).length - 1, 0);
  if (!Number.isFinite(state.selectedInterBeatTransitionIndex)) state.selectedInterBeatTransitionIndex = 0;
  state.selectedInterBeatTransitionIndex = Math.max(0, Math.min(max, state.selectedInterBeatTransitionIndex));
  return state.selectedInterBeatTransitionIndex;
}

function interBeatSceneAssetLinks(proposal, transitions) {
  const beatsById = new Map();
  for (const transition of transitions || []) {
    if (transition.from) beatsById.set(transition.from.id, transition.from);
    if (transition.to) beatsById.set(transition.to.id, transition.to);
  }
  return narrativeSceneAssetLinks(proposal, [...beatsById.values()]);
}

function inferDynamicGeometryKind(proposal) {
  const label = String(proposal?.label || "").toLowerCase().trim();
  if (/^dynamics$/.test(label)) return "motion";
  if (/^no\s+dynamics$/.test(label)) return "none";
  if (/^simple\s+geometric\s+motion$/.test(label)) return "motion";
  if (/^flow\s+field\s*\/\s*particles$/.test(label)) return "flow";
  if (/^scale\s+change\s*\/\s*zoom$/.test(label)) return "zoom";
  if (/^part\s+highlighting\s*\/\s*focus\s+states$/.test(label)) return "focus";
  const text = `${label} ${proposal?.description || ""}`.toLowerCase();
  if (/\b(no dynamics|no dynamic|static|inert|without motion|no motion)\b/.test(text)) return "none";
  if (/\b(flow|particle|droplet|field|dust|contamination|sprite)\b/.test(text)) return "flow";
  if (/\b(scale|zoom|magnification|microscope|focus pulse|expand)\b/.test(text)) return "zoom";
  if (/\b(part|highlight|focus|pulse|marker|call attention|outline)\b/.test(text)) return "focus";
  return "motion";
}

function inferInterBeatDynamicsKind(proposal) {
  const label = String(proposal?.label || "").toLowerCase().trim();
  if (/^transition$/.test(label)) return "transition";
  if (/^no\s+transition$/.test(label)) return "none";
  if (/^discrete:\s*hard\s+switch$/.test(label)) return "discrete-hard";
  if (/^discrete:\s*fade\s*\/\s*dissolve$/.test(label)) return "discrete-fade";
  if (/^discrete:\s*spatial\s+wipe$/.test(label)) return "discrete-wipe";
  if (/^discrete:\s*flash\s*\/\s*pop$/.test(label)) return "discrete-pop";
  if (/^continuous\s+active:\s*reader\s+travels\s+to\s+next\s+anchor$/.test(label)) return "continuous-active";
  if (/^continuous\s+passive:\s*next\s+object\s+moves\s+to\s+reader$/.test(label)) return "continuous-passive";
  return null;
}

function interBeatDynamicsLayer(kind) {
  return String(kind || "").startsWith("continuous") ? "continuous" : "discrete";
}

function interBeatDynamicsModeBadge(kind) {
  if (kind === "continuous-active") return { className: "active", label: "active reader" };
  if (kind === "continuous-passive") return { className: "passive", label: "passive object" };
  return null;
}

function interBeatDynamicsKindLabel(kind) {
  if (kind === "transition") return "Scene change";
  if (kind === "none") return "No scene change";
  if (kind === "discrete-hard") return "Hard switch";
  if (kind === "discrete-fade") return "Fade / dissolve";
  if (kind === "discrete-wipe") return "Spatial wipe";
  if (kind === "discrete-pop") return "Flash / pop";
  if (kind === "continuous-active") return "Active travel";
  if (kind === "continuous-passive") return "Passive arrival";
  return "Scene change";
}

function dynamicGeometryKindLabel(kind) {
  if (kind === "none") return "No movement";
  if (kind === "flow") return "Flow / particles";
  if (kind === "zoom") return "Scale / zoom";
  if (kind === "focus") return "Focus states";
  return "Movement";
}

function dynamicGeometryKindHelp(kind) {
  if (kind === "none") return "Keep the saved story objects still with no added movement.";
  if (kind === "flow") return "Preview lightweight particles or trace fields around the object in the active story part.";
  if (kind === "zoom") return "Preview magnification pulses, zoom rings, and scale emphasis.";
  if (kind === "focus") return "Preview focus markers and pulsing focus states without claiming details about unnamed model parts.";
  return "Preview simple whole-object movement such as rotation, bobbing, jitter, or short dashes.";
}

function interBeatDynamicsKindHelp(kind) {
  if (kind === "transition") return "Preview the saved scene-change behavior between consecutive story parts.";
  if (kind === "none") return "No saved scene-change behavior was found between these story parts.";
  if (kind === "discrete-hard") return "Preview a sudden scene change where story part A turns off and story part B snaps on.";
  if (kind === "discrete-fade") return "Preview story part A dissolving out while story part B fades in.";
  if (kind === "discrete-wipe") return "Preview a spatial wipe sweeping attention from story part A to story part B.";
  if (kind === "discrete-pop") return "Preview a short flash during the scene change followed by a pop emphasis on story part B.";
  if (kind === "continuous-active") return "Preview a reader path traveling from story part A's anchor to story part B's anchor.";
  if (kind === "continuous-passive") return "Preview the next object/anchor moving toward a central reader position.";
  return "Preview the scene change between two consecutive story-part anchors.";
}

function inferContextLayerKind(proposal) {
  if (proposal?.environmentEnhancementSkipped === true || proposal?.optionId === "environment-enhancement-no-added-environment") return "none";
  if (proposal?.environmentEnhancement) return "environment";
  const label = String(proposal?.label || "").toLowerCase().trim();
  if (/^object\s+only$/.test(label)) return "object";
  if (/^object\s+in\s+environment$/.test(label)) return "environment";
  if (/^nested\s+or\s+multi-scale\s+scene$/.test(label)) return "nested";
  const text = `${label} ${proposal?.description || ""}`.toLowerCase();
  if (/\b(nested|multi[-\s]?scale|scale|zoom|inset|microscope|detail)\b/.test(text)) return "nested";
  if (/\b(environment|room|home|habitat|surface|context|setting|world)\b/.test(text)) return "environment";
  return "object";
}

function contextLayerKindLabel(kind) {
  if (kind === "none") return "No added setting";
  if (kind === "environment") return "Generated setting";
  if (kind === "nested") return "Nested scale";
  return "Object only";
}

function contextLayerKindHelp(kind) {
  if (kind === "none") return "Keep StoryVR's standard neutral setting without adding a custom setting.";
  if (kind === "environment") return "Preview the saved story objects inside the generated setting.";
  if (kind === "nested") return "Preview object, habitat, and room scale as nested layers with a small detail inset.";
  return "Preview the active story object isolated on the inspection anchor with minimal surrounding context.";
}

function inferTextComfortKind(proposal) {
  const label = String(proposal?.label || "").toLowerCase().trim();
  if (/^fixed\s+panel$/.test(label)) return "fixed";
  if (/^reader-facing\s+panel$/.test(label)) return "reader-facing";
  if (/^hand\s*\/\s*near-body\s+panel$/.test(label)) return "near-body";
  if (/^path\s*\/\s*object-attached\s+text$/.test(label)) return "object-attached";
  const text = `${label} ${proposal?.description || ""}`.toLowerCase();
  if (/\b(reader-facing|reader facing|billboard|facing)\b/.test(text)) return "reader-facing";
  if (/\b(hand|near-body|near body|wrist|held)\b/.test(text)) return "near-body";
  if (/\b(path|object-attached|object attached|anchor|attached)\b/.test(text)) return "object-attached";
  return "fixed";
}

function textComfortKindLabel(kind) {
  if (kind === "reader-facing") return "Reader-facing panel";
  if (kind === "near-body") return "Hand / near-body panel";
  if (kind === "object-attached") return "Path / object-attached text";
  return "Fixed panel";
}

function textComfortKindHelp(kind) {
  if (kind === "reader-facing") return "The panel keeps facing the reader camera while preserving author-chosen position.";
  if (kind === "near-body") return "The panel sits in a near-body reading zone, like a wrist or held card.";
  if (kind === "object-attached") return "The panel uses the source 3D model camera path to suggest each story part's spatial focus, then applies a comfortable reader-facing offset; placement near the active object is the fallback when focus is unverified.";
  return "The panel stays at a stable world-space location for predictable reading.";
}

function inferInteractionControlKind(proposal) {
  const label = String(proposal?.label || "").toLowerCase().trim();
  if (/^(button\s+stepping|controller(?:\s+button)?\s+press)$/.test(label)) return "button-step";
  if (/^direct\s+manipulation$/.test(label)) return "direct";
  if (/^(reader\s+locomotion|embodied\s+progression)$/.test(label)) return "embodied-control";
  if (/^branching\s+selection$/.test(label)) return "branching-control";
  const text = `${label} ${proposal?.description || ""}`.toLowerCase();
  if (/\b(branch|choice|select|fork)\b/.test(text)) return "branching-control";
  if (/\b(locomotion|teleport|embodied|gesture|body|walk|step|lean)\b/.test(text)) return "embodied-control";
  if (/\b(grab|drag|manipulat|touch|direct)\b/.test(text)) return "direct";
  return "button-step";
}

function interactionProposalDisplayLabel(proposal) {
  return interactionControlKindDisplayLabel(inferInteractionControlKind(proposal));
}

function interactionControlKindLabel(kind) {
  if (kind === "ui-button-press") return "UI button press";
  if (kind === "direct") return "Direct manipulation";
  if (kind === "embodied-control") return "Reader locomotion";
  if (kind === "branching-control") return "Branching selection";
  return "Controller button press";
}

function interactionControlKindDisplayLabel(kind) {
  if (kind === "ui-button-press") return "Press a story button";
  if (kind === "direct") return "Move an object";
  if (kind === "embodied-control") return "Walk or teleport";
  if (kind === "branching-control") return "Choose a path";
  return "Press a controller button";
}

function interactionControlOptionSummary(kind) {
  if (kind === "ui-button-press") return "Select a button beside the story text.";
  if (kind === "direct") return "Grab or resize a story object.";
  if (kind === "embodied-control") return "Move to the next reading place.";
  if (kind === "branching-control") return "Choose what to see next.";
  return "Press the assigned button to continue.";
}

function interactionControlKindHelp(kind, locomotionMode = null) {
  if (kind === "ui-button-press") return "Readers select a button beside the story text.";
  if (kind === "direct") return "Readers continue by grabbing, moving, or inspecting an object.";
  if (kind === "embodied-control") return normalizeInteractionLocomotionMode(locomotionMode || interactionLocomotionMode()) === "virtual-teleport"
    ? "Readers teleport to the next reading place."
    : "Readers walk to the next reading place.";
  if (kind === "branching-control") return "Readers choose which story path to follow.";
  return "Readers press an assigned controller button to continue.";
}

function inferTopologyKind(proposal) {
  const label = String(proposal?.label || "").toLowerCase().trim();
  if (/^single\s+anchor$/.test(label)) return "single";
  if (/^collection\s*\/\s*constellation$/.test(label) || /\b(collection|constellation|catalog)\b/.test(label)) return "constellation";
  if (/^map,\s*terrain,\s*or\s*network$/.test(label) || /\b(map|terrain|network)\b/.test(label)) return "map";
  const text = `${label} ${proposal?.description || ""}`.toLowerCase();
  if (/\b(map|terrain|network|habitat|zone|route|room|house)\b/.test(text)) return "map";
  if (/\b(collection|constellation|ring|catalog|node|cluster)\b/.test(text)) return "constellation";
  if (/\b(single|anchor|stage|specimen)\b/.test(text)) return "single";
  return "constellation";
}

function topologyKindLabel(kind) {
  if (kind === "single") return "Single anchor";
  if (kind === "map") return "Map / network";
  return "Constellation";
}

function topologyKindHelp(kind) {
  if (kind === "single") return "One stable focal stage; assets rotate through the anchor.";
  if (kind === "map") return "Assets become zones on a compact spatial map or network.";
  return "Assets become stable nodes arranged around the reader.";
}

function topologyNodePosition(kind, index, total) {
  if (kind === "map") {
    const mapPositions = [
      { x: 20, y: 30 },
      { x: 43, y: 22 },
      { x: 68, y: 35 },
      { x: 78, y: 64 },
      { x: 50, y: 76 },
      { x: 26, y: 66 },
      { x: 56, y: 52 },
    ];
    return mapPositions[index % mapPositions.length];
  }
  const count = Math.max(total, 1);
  const radius = kind === "single" ? 31 : 36;
  const angle = (-Math.PI / 2) + ((Math.PI * 2 * index) / count);
  return {
    x: Number((50 + Math.cos(angle) * radius).toFixed(2)),
    y: Number((50 + Math.sin(angle) * radius).toFixed(2)),
  };
}

function componentById(id) {
  return state.data.components.find((component) => component.id === id) || state.data.components[0];
}

function clearMissingSelectedBeat() {
  const ids = new Set((state.data.graph.beats || []).map((beat) => beat.id));
  const edgeIds = new Set(sourceGraphTransitionEdges(state.data.graph).map((edge) => edge.id));
  if (state.sourceGraphSelectedTransitionId && !edgeIds.has(state.sourceGraphSelectedTransitionId)) {
    state.sourceGraphSelectedTransitionId = null;
  }
  state.selectedBeatIds = (state.selectedBeatIds || []).filter((id) => ids.has(id));
  if (state.beatSelectionAnchorId && !ids.has(state.beatSelectionAnchorId)) state.beatSelectionAnchorId = null;
  if (state.sourceGraphTextDetail && !ids.has(state.sourceGraphTextDetail.beatId)) state.sourceGraphTextDetail = null;
  if (!state.selectedBeatId) return;
  const exists = ids.has(state.selectedBeatId);
  if (!exists) state.selectedBeatId = null;
}

function escapeHtml(value) {
  return String(value ?? "")
    .replaceAll("&", "&amp;")
    .replaceAll("<", "&lt;")
    .replaceAll(">", "&gt;")
    .replaceAll('"', "&quot;")
    .replaceAll("'", "&#039;");
}
